_REGION_MARKER = re.compile(r"^__scheduled_region_(\d+)__$")
# A CALL STATEMENT. Historically the control program had no vocabulary for an
# authored call -- calls were an overlay stitched into the lowered SSA
# afterwards by lexical anchors -- so a loop body whose only content is a call
# was, in the plan's own language, empty. This marker makes a callsite a
# schedulable statement exactly the way a region is one.
_CALLSITE_MARKER = re.compile(r"^__plan_callsite_(\d+)__$")


def _sequence_column_element_dtype(column) -> str:
    """The element dtype a sequence column stores.

    A column an earlier descriptor already made a heap cell is a ``ptr``
    whose element layout is its ``heap_element_dtype``
    (``_heap_sequence_contract``): ``self._c.append(t); len(self._c)``
    reads one field storage twice, and the second view must name the same
    element layout as the first, not the cell.
    """

    element = (column.accounting or {}).get("heap_element_dtype")
    if str(column.dtype) == "ptr" and element:
        return str(element)
    return str(column.dtype or "unknown")

def _region_value_dtype(value_id, value_dtypes, existing, control_name):
    """The dtype the region's value record carries, or a named refusal."""
    declared = (value_dtypes or {}).get(value_id)
    if declared is not None:
        return declared
    if existing is not None and existing.dtype is not None:
        return existing.dtype
    raise ValueError(
        f"region value %{value_id} in {control_name} has a shape record but "
        "no dtype record (value_dtypes and region_value_meta both lack it)")


def _region_table_operations(
    region_index: int,
    table_region_operations: Mapping[int, Any] | None,
    table_region_post_operations: Mapping[int, Any] | None,
) -> tuple[tuple[str, tuple[Any, ...]], ...]:
    """Every table/sequence operation recorded against one region.

    PROGRAM SHAPE: ``buf = [1, 2]; buf += [3, 4]; buf.append(9)``.  The
    instructions realising those effects are removed from the region's planned
    instruction list and live ONLY in ``table_region_operations`` /
    ``table_region_post_operations``.  WRONG RECORD (before): the scheduler
    judged purity from the planned instructions, so a region carrying six
    recorded effects was "pure" while the builder's ``_pure_region_index``
    called the same region a barrier.  RULE NOW HOLDING: one predicate, this
    record; a region with any recorded operation is an effect, not pure.
    """

    return (
        *((table_region_operations or {}).get(int(region_index), ())),
        *((table_region_post_operations or {}).get(int(region_index), ())),
    )


def _table_operation_sequence_accesses(
    kind: str, arguments: tuple[Any, ...],
) -> tuple[set[int], set[int]]:
    """The arenas one recorded table operation reads and writes.

    Positions follow the emitters' own signatures
    (``emit_table_region_operations`` / ``_emit_*``); the sequence id is the
    operation's own, never rediscovered.  Lookups and row loads read; stores,
    deletes, fills, appends, prepends, resets, extends and bit packs write
    their destination, and slice/extend/prepend_packed_bytes/pack_bits also
    read their source arena.
    """

    reads: set[int] = set()
    writes: set[int] = set()
    if kind in ("lookup", "lookup_capture"):
        reads.add(int(arguments[2]))
    elif kind in ("row_load", "row_load_capture"):
        reads.add(int(arguments[1]))
    elif kind == "row_store":
        writes.add(int(arguments[1]))
    elif kind == "store":
        writes.add(int(arguments[3]))
    elif kind == "delete":
        if arguments[2] is not None:
            writes.add(int(arguments[2]))
    elif kind in ("fill", "append_fill", "reset", "prepend"):
        writes.add(int(arguments[0]))
    elif kind in ("append_slice", "prepend_packed_bytes", "pack_bits"):
        writes.add(int(arguments[0]))
        reads.add(int(arguments[1]))
    elif kind == "append_scalar":
        writes.add(int(arguments[0]))
    elif kind == "extend":
        writes.add(int(arguments[1]))
        reads.add(int(arguments[2]))
    elif kind == "structural_consumed":
        pass
    else:
        raise ValueError(f"unknown recorded table operation {kind!r}")
    return reads, writes


def _table_operation_value_reads(
    kind: str, arguments: tuple[Any, ...],
) -> set[int]:
    """The scalar values one recorded table operation reads, by the emitter's
    own signature (a literal beside them is not a value id)."""

    if kind in ("fill", "append_fill"):
        return {int(arguments[2])}
    if kind == "append_slice":
        return {int(value) for value in arguments[2:4] if value is not None}
    if kind == "append_scalar":
        return {int(arguments[1])}
    return set()


def _scoped_value_type_abi(
    lexical_read_scope: Any,
    supplied: Mapping[int, Any] | None = None,
) -> dict[int, Any]:
    """Project one function copy's authoritative native type contracts.

    ``linked_value_abi`` is a physical-ABI view used by the shell, not an
    index of every semantic type fact. A call result used as one arm of a
    conditional can therefore own a complete ``VALUE_TYPE_ABI`` row without
    needing an independent entry in that view. Control lowering consumes the
    page directly so every value with a declared union transports its tag.

    An explicitly supplied projection remains accepted at sectional APIs, but
    it must agree with any row already owned by the concordance page. This
    keeps the page authoritative while still admitting synthetic callers that
    have no lexical scope.
    """

    from .identity_concordance import current_identity_book

    projected: dict[int, Any] = {}
    scope = (
        None if lexical_read_scope is None else tuple(lexical_read_scope)
    )
    if scope is not None:
        page = current_identity_book().page(VALUE_TYPE_ABI.name)
        for row in page.scope_rows(scope):
            if not (
                isinstance(row, tuple)
                and len(row) == 2
                and row[0] == scope
            ):
                continue
            fact = page.latest(row)
            if fact is not None:
                projected[int(row[1])] = fact
    for value_id, fact in (supplied or {}).items():
        value_id = int(value_id)
        incumbent = projected.get(value_id)
        if scope is not None and incumbent is None:
            raise ValueError(
                "native value type ABI handoff has no authoritative "
                "concordance row: "
                f"scope={scope!r}, value={value_id}"
            )
        if incumbent is not None and incumbent != fact:
            raise ValueError(
                "native value type ABI handoff disagrees with concordance: "
                f"scope={scope!r}, value={value_id}"
            )
        projected[value_id] = fact
    return projected


def _case_literal_int(spelling: Any) -> int | None:
    """A tick case label as the integer it denotes (``True``/``False`` are
    the planner's boolean singletons), else None."""

    text = str(spelling).strip()
    if text in {"True", "False"}:
        return int(text == "True")
    try:
        return int(text, 10)
    except ValueError:
        return None


@dataclass(frozen=True, order=True)
class SSALoweringShortfall:
    domain: str
    name: str
    location: str
    reason: str


class SSALoweringIncompleteError(ValueError):
    """A valid source unit reached SSA planning but has unlowered mechanics.

    This is a durable compilation frontier, not a target-emitter failure and
    not an unexpected compiler exception.  The structured mapping lets worker
    and bootstrap manifests retain each exact missing mechanic without parsing
    a backend-named exception string.
    """

    def __init__(
        self,
        failures: Iterable[tuple[str, SSALoweringShortfall]],
    ) -> None:
        self.failures = tuple(
            (str(symbol), shortfall) for symbol, shortfall in failures
        )
        super().__init__(
            "whole-object SSA lowering is incomplete: "
            + "; ".join(
                f"{symbol}::{item.location}::{item.name} ({item.reason})"
                for symbol, item in self.failures
            )
        )

    def to_failure_mapping(self) -> dict[str, Any]:
        kinds: dict[str, int] = {}
        records = []
        for symbol, item in self.failures:
            kinds[str(item.name)] = kinds.get(str(item.name), 0) + 1
            records.append({
                "symbol": symbol,
                "domain": str(item.domain),
                "name": str(item.name),
                "location": str(item.location),
                "reason": str(item.reason),
            })
        return {
            "frontier_kind": "ssa-lowering-incomplete",
            "lowering_stage": "backend-neutral-ssa",
            "lowering_shortfall_count": len(records),
            "lowering_shortfall_kinds": dict(sorted(kinds.items())),
            "lowering_shortfalls": records,
        }


@dataclass(frozen=True, order=True)
class SSACycle:
    function: str
    blocks: tuple[str, ...]
    back_edges: tuple[tuple[str, str], ...]
    phi_blocks: tuple[str, ...]

    @property
    def represented_by_phi(self) -> bool:
        return bool(self.phi_blocks)


def _typed_region_occurrence(
    value: SSAValue,
    canonical: SSAValue,
    authoritative: Meta | None,
) -> SSAValue:
    """Retype one region occurrence without erasing its authored view.

    A repository SSA id identifies storage, not one eternal tensor shape.
    Reshape/view operations intentionally reuse the id with different shapes.
    Dtype reconciliation may use the region-wide contract, but a non-empty
    occurrence shape is more specific and must survive.
    """

    dtype = (
        str(authoritative.dtype)
        if authoritative is not None
        and str(authoritative.dtype or "") not in {"", "unknown"}
        else value.dtype or canonical.dtype
    )
    shape = tuple(value.shape or canonical.shape or ())
    device = value.device or canonical.device
    if (
        value.dtype == dtype
        and tuple(value.shape or ()) == shape
        and value.device == device
    ):
        return value
    return replace(value, dtype=dtype, shape=shape, device=device)


@dataclass(frozen=True)
class PrecompileSSALoweringResult:
    module: IRModule
    validation: PrecompileSSAValidationResult
    shortfalls: tuple[SSALoweringShortfall, ...]
    cycles: tuple[SSACycle, ...]

    @property
    def complete(self) -> bool:
        return (
            self.validation.valid_precompile
            and not self.shortfalls
        )

    def shortfall_report(self) -> str:
        lines = []
        if self.validation.compatibility_shortfalls:
            lines.append(
                self.validation.compatibility_shortfall_report()
            )
        if self.shortfalls:
            lines.append("precompile-to-SSA lowering shortfalls:")
            lines.extend(
                f"- {item.domain}:{item.name} at {item.location}; "
                f"{item.reason}"
                for item in self.shortfalls
            )
        return "\n".join(lines) or "precompile-to-SSA lowering: complete"


def _ssa_value(value_id: int, meta: Meta | None) -> SSAValue:
    dtype = None if meta is None else meta.dtype
    if dtype is not None:
        dtype = str(dtype)
    if dtype is not None and "." in dtype:
        # Capturing through Torch records qualified spellings such as
        # ``torch.bool``. SSA and every compiled ABI use canonical dtype
        # names; allowing the frontend backend's module prefix to escape here
        # makes the Fortran declaration and C sidecar disagree.
        dtype = dtype.rsplit(".", 1)[-1]
    return SSAValue(
        int(value_id),
        dtype=dtype,
        shape=(
            ()
            if meta is None or meta.shape is None
            else tuple(meta.shape)
        ),
        device=None if meta is None else meta.device,
    )


def _post_built_function_rows(function: Function) -> None:
    # Program: a precompile-built function (``numerical_precompile``, the
    # ``numerical_region_N`` and ``planned_region_N`` siblings), whose
    # arguments, results and operands are SSAValues built directly, outside
    # any control builder.
    # Wrong record: those values (an argument, id 0) sat in the function with
    # no ``ssa_value`` row, so ``function_value_structure`` refused it.
    # Rule: the pass that creates a value posts its row at creation, derived
    # from the cells it read.  A precompile-built function carries no lexical
    # read scope, hence no ``canonical_value`` cell for its graph ids; as
    # ``_value_cell`` does for such an id, each value is ADOPTED_GRAPH_ID
    # DERIVED from the function root cell of its scope (a MINTED id: MINTED),
    # stage CONTROL_SSA_ENTRY.  The reader that refuses a value with no row
    # stays.
    from .id_space import MINTED as _FUSED_MINTED, has_flag as _fused_has_flag
    from .identity_concordance import current_identity_book as _fused_row_book
    from .ssa_record_return_state import function_scope_of as _fused_scope_of

    _row_book = _fused_row_book()
    _row_scope = _fused_scope_of(function)
    _row_root = _function_root_cell(_row_book, _row_scope)
    _row_seen: set[int] = set()
    for _row_value in (
        *function.args,
        *(
            value
            for block in function.blocks.values()
            for instruction in block.instrs
            for value in (
                *instruction.args,
                *((instruction.res,) if instruction.res is not None else ()),
            )
        ),
    ):
        if getattr(_row_value, "id", None) is None:
            continue
        _row_id = int(_row_value.id)
        if _row_id in _row_seen:
            continue
        _row_seen.add(_row_id)
        _row_fact = SSAValueFact(
            _row_value.dtype, tuple(_row_value.shape or ()),
            SSAValueOrigin.MINTED if _fused_has_flag(_row_id, _FUSED_MINTED)
            else SSAValueOrigin.ADOPTED_GRAPH_ID,
        )
        _row_ref = _row_book.latest_ref(SSA_VALUE, (_row_scope, _row_id))
        if _row_ref is not None and (
            _row_book.page(SSA_VALUE).cell(_row_ref.row, _row_ref.column)
            == _row_fact
        ):
            continue
        _row_book.post(
            SSA_VALUE, (_row_scope, _row_id), _row_fact,
            stage=CONTROL_SSA_ENTRY, provenance=Derived((_row_root,)),
            mode=Mode.REVISE,
        )


def lower_fused_program_to_ssa(
    program: FusedProgram,
    *,
    function_name: str = "numerical_precompile",
) -> tuple[Function, tuple[SSALoweringShortfall, ...]]:
    """Translate only operations already named by the existing SSA registry.

    .. warning::

       **INTERNAL NUMERIC LOWERER -- DO NOT CALL THIS AS A COMPILER ENTRYPOINT.**

       No person-facing workflow and no orchestration, publishing, inspection,
       or application function may call this lowerer directly.  It accepts an
       already-precompiled :class:`FusedProgram`, not Python or a general AST.
       Only the precompiler and tensor-backend boundary may access it.  All
       other callers must enter through the appropriate precompiler or tensor
       backend and let that layer supply the numeric program.

       Tests may call this function only to verify the lowerer itself; a test
       call is not precedent for production use.
    """

    program = canonicalize_elementwise_steps(program)

    from .evolution_metagraph import (
        EvolutionComponentRef,
        active_evolution_metagraph,
        record_fused_program_evolution,
    )

    evolution = active_evolution_metagraph()
    precompile_evolution = record_fused_program_evolution(program)
    ssa_evolution = (
        None
        if evolution is None
        else evolution.open_graph("ssa", function_name)
    )

    metadata = program.meta or {}
    values = {
        int(value_id): _ssa_value(int(value_id), metadata.get(value_id))
        for value_id in (
            set(program.feeds)
            | {
                int(step.result_id)
                for step in program.steps
                if isinstance(step, OpStep)
            }
        )
    }
    arguments = [values[value_id] for value_id in sorted(program.feeds)]
    available = set(program.feeds)
    instructions: list[Instr] = []
    shortfalls: list[SSALoweringShortfall] = []

    if evolution is not None and ssa_evolution is not None:
        for value_id in sorted(program.feeds):
            sources = (
                (EvolutionComponentRef(precompile_evolution.id, str(value_id)),)
                if precompile_evolution is not None else ()
            )
            target = evolution.component(
                ssa_evolution,
                value_id,
                label=values[value_id].name(),
                kind="argument",
                consumes=sources,
            )
            if sources:
                evolution.handoff(
                    target,
                    sources,
                    transformation="precompile-to-ssa",
                )

    def element_count(value_id: int) -> int:
        meta = metadata.get(value_id)
        count = 1
        for extent in (() if meta is None else (meta.shape or ())):
            count *= int(extent)
        return count

    def tensor_algorithm(step: OpStep) -> str | None:
        if step.op_name == "random_source":
            return XOROSHIRO128SS_FILL
        translations = translations_for_operation(step.op_name)
        if not translations:
            return None
        symbols = {item.llvm_symbol for item in translations}
        if step.op_name == "slice":
            return (
                "index_select_double"
                if step.attrs.get("slice_kind") == "index_select"
                else "slice_copy_double"
            )
        if (
            "binary_scalar_double" in symbols
            and len(step.input_ids) == 1
            and any(name.endswith("_scalar") for name in step.attrs)
        ):
            return "binary_scalar_double"
        if {
            "binary_double",
            "binary_scalar_double",
        } <= symbols and len(step.input_ids) == 2:
            left_count, right_count = (
                element_count(value_id)
                for value_id in step.input_ids
            )
            return (
                "binary_scalar_double"
                if 1 in {left_count, right_count}
                and left_count != right_count
                else "binary_double"
            )
        if step.op_name == "sum":
            return (
                "reduce_dim_double"
                if step.attrs.get("axis") is not None
                else "sum_double"
            )
        # Prefer the public tensor kernel over scalar helpers when more than
        # one exact C/LLVM correspondence names the operation.
        for item in translations:
            if item.llvm_symbol != "binary_value":
                return item.llvm_symbol
        return translations[0].llvm_symbol

    for index, step in enumerate(program.steps):
        argument_count = step.attrs.get("argument_count")
        if (
            step.attrs.get("python_replacement_kind") == "operator"
            and isinstance(argument_count, int)
            and 0 <= argument_count < len(step.input_ids)
        ):
            # Intrinsic-call capture can retain the callable/static-reference
            # node before the authored operands.  The identity receipt states
            # the actual Python arity; only its trailing authored operands
            # belong to the numeric SSA call.  Passing the reference pointer
            # made unary ``float(x)`` a two-argument native cast and likewise
            # shifted _restore_type's cast_like value/reference pair.
            step = replace(
                step,
                input_ids=(
                    list(step.input_ids[-argument_count:])
                    if argument_count else []
                ),
            )
        location = f"{function_name}:step[{index}]"
        reduction = step.attrs.get("reduce", "sum")
        if step.op_name == "scatter" and reduction not in {
            "sum", "mean", "max", "min",
        }:
            shortfalls.append(SSALoweringShortfall(
                "numerical", "scatter", location,
                f"scatter reduce={reduction!r} is not one of "
                "('sum', 'mean', 'max', 'min')",
            ))
            continue
        algorithm = (
            f"scatter_{reduction}_double"
            if step.op_name == "scatter"
            else tensor_algorithm(step)
        )
        handler = (
            Handler.Const
            if step.op_name == "tensor_from_list"
            else Handler.Call
            if algorithm is not None
            else ssa_handler_for_precompile(step.op_name)
        )
        if handler is None:
            shortfalls.append(
                SSALoweringShortfall(
                    "numerical",
                    step.op_name,
                    location,
                    "operation has no name in the existing SSA Handler set",
                )
            )
            continue
        missing = tuple(
            value_id
            for value_id in step.input_ids
            if value_id not in available
        )
        if missing:
            shortfalls.append(
                SSALoweringShortfall(
                    "numerical",
                    step.op_name,
                    location,
                    "operands have no lowered SSA producer: "
                    + ", ".join(map(str, missing)),
                )
            )
            continue
        attributes = dict(step.attrs)
        if handler is Handler.Call:
            attributes.setdefault("tensor_operation", step.op_name)
        if algorithm is not None:
            attributes.update({
                "callee": algorithm,
                "tensor_operation": step.op_name,
                "lowered_from": "c_backend_llvm_ssa.TRANSLATIONS",
            })
        if step.op_name == "tensor_from_list":
            attributes.update({
                "value": attributes.get("data"),
                "tensor_operation": step.op_name,
            })
        instructions.append(
            Instr(
                handler.value,
                [values[value_id] for value_id in step.input_ids],
                values[step.result_id],
                attributes=attributes,
            )
        )
        if evolution is not None and ssa_evolution is not None:
            sources = (
                (EvolutionComponentRef(precompile_evolution.id, str(step.result_id)),)
                if precompile_evolution is not None else ()
            )
            target = evolution.component(
                ssa_evolution,
                step.result_id,
                label=str(handler.value),
                kind="instruction",
                attributes={"tensor_operation": step.op_name},
                consumes=sources,
            )
            if sources:
                evolution.handoff(
                    target,
                    sources,
                    transformation="precompile-to-ssa",
                )
            for position, value_id in enumerate(step.input_ids):
                input_ref = EvolutionComponentRef(
                    ssa_evolution.id,
                    str(value_id),
                )
                if evolution.has_component(input_ref):
                    evolution.relationship(
                        ssa_evolution,
                        input_ref,
                        target,
                        role=f"arg{position}",
                    )
        available.add(step.result_id)

    output_values = [
        values[value_id]
        for value_id in program.outputs.values()
        if value_id in available
    ]
    missing_outputs = tuple(
        (name, value_id)
        for name, value_id in program.outputs.items()
        if value_id not in available
    )
    for name, value_id in missing_outputs:
        shortfalls.append(
            SSALoweringShortfall(
                "numerical",
                "output",
                f"{function_name}:output[{name}]",
                f"value {value_id} has no lowered SSA producer",
            )
        )
    instructions.append(Instr(Handler.Ret.value, output_values, None))
    feed_origins = dict(
        (getattr(program, "extras", None) or {}).get(
            "capture_feed_origins", {}
        )
    )
    identity_tokens = dict(
        (getattr(program, "extras", None) or {}).get(
            "ssa_identity_tokens", {}
        )
    )
    parameter_names = tuple(
        (
            str(
                feed_origins.get(
                    value.id, feed_origins.get(str(value.id), {})
                ).get("binding_name", f"t{value.id}")
            ),
            int(value.id),
        )
        for value in arguments
    )
    function = Function(
        function_name,
        arguments,
        {
            "entry": BasicBlock(
                "entry",
                instructions,
                [],
            )
        },
        metadata={
            "named_outputs": tuple(
                (str(name), int(value_id))
                for name, value_id in program.outputs.items()
                if value_id in available
            ),
            "parameter_names": parameter_names,
            "ssa_identity_tokens": tuple(
                (
                    int(value_id),
                    tuple(map(str, token_chain)),
                )
                for value_id, token_chain in sorted(
                    identity_tokens.items(), key=lambda item: int(item[0])
                )
            ),
        },
    )
    _post_built_function_rows(function)
    if evolution is not None and ssa_evolution is not None:
        evolution.bind_artifact(function, ssa_evolution)
        evolution.close_graph(ssa_evolution)
    return function, tuple(shortfalls)


def _control_placed_table_delete_ids(root: Any) -> set[int]:
    """Effect ids of keyed deletes the control tree carries as table-delete
    mutations, at any depth (an arm, a loop body, a call)."""

    placed: set[int] = set()

    def visit(block: Any) -> None:
        if block is None or isinstance(block, (str, int)):
            return
        if isinstance(block, SequenceMutationBlock):
            if block.mutation.argument_kind in {
                "table_delete_key", "table_delete_keys",
            }:
                placed.add(int(block.mutation.effect_node_id))
            return
        for child in getattr(block, "blocks", ()) or ():
            visit(child)
        for name in ("body", "orelse", "callee", "default", "finalbody"):
            visit(getattr(block, name, None))
        for _label, child in getattr(block, "cases", ()) or ():
            visit(child)
        for child in getattr(block, "lanes", ()) or ():
            visit(child)

    visit(root)
    return placed


def lower_fused_integral_to_repository_ssa(
    program: FusedProgram,
    *,
    function_name: str,
) -> tuple[
    IRModule,
    dict[str, tuple[SSAValue, ...]],
    tuple[str, ...],
    tuple[SSALoweringShortfall, ...],
]:
    """Publish one planner-isolated numeric integral as repository SSA.

    This is the precompiler boundary for deterministic subdivision workers;
    orchestration does not call the numeric lowerer directly. The enclosing
    authored control owner remains source fallback until it can safely link a
    verified child deployment.
    """

    structural_contract = dict(
        (getattr(program, "extras", None) or {}).get(
            "structural_resident_table_contract"
        ) or {}
    )
    if structural_contract:
        sequences = tuple(map(
            dict, structural_contract.get("sequences") or (),
        ))
        stores = tuple(map(
            dict, structural_contract.get("stores") or (),
        ))
        declarations = tuple(
            (
                int(sequence["sequence_id"]),
                str(sequence["policy"]),
                int(sequence["column_count"]),
                bool(sequence["writable"]),
            )
            for sequence in sequences
        )
        column_dtypes = {
            int(sequence["sequence_id"]): tuple(map(
                str, sequence.get("column_dtypes") or (),
            ))
            for sequence in sequences
        }
        table_stores = tuple(
            (
                int(store["effect_value_id"]),
                int(store["key_value_id"]),
                int(store["stored_value_id"]),
                int(store["sequence_value_id"]),
            )
            for store in stores
        )
        value_meta = dict(program.meta or {})
        for sequence in sequences:
            sequence_id = int(sequence["sequence_id"])
            dtypes = column_dtypes[sequence_id]
            if dtypes:
                value_meta[sequence_id] = Meta((), dtypes[0])
        for store in stores:
            sequence = next(
                item for item in sequences
                if int(item["sequence_id"])
                == int(store["sequence_value_id"])
            )
            dtypes = column_dtypes[int(sequence["sequence_id"])]
            value_meta[int(store["key_value_id"])] = Meta((), dtypes[0])
            value_meta[int(store["stored_value_id"])] = Meta((), dtypes[-1])
        authored_ids = {
            *map(int, program.feeds),
            *(int(step.result_id) for step in program.steps),
            *(int(value_id) for value_id in program.outputs.values()),
        }
        # Watermark from the SERIALS, never the raw numbers.  A raw max over
        # ids that carry group/flag bits (see id_space) lands the watermark
        # in whatever group the largest id belonged to, and every value
        # allocated from it then inherits that group's bits without ever
        # passing through ``compose`` -- a value silently claiming a space
        # it was never minted into.  While ids are unflagged this is exactly
        # the previous behaviour, since a legacy id IS its own serial.
        first_value_id = max(
            (_id_serial_of(value_id) for value_id in authored_ids),
            default=-1,
        ) + 1
        control = ControlProgram(SequenceBlock(()))
        function, shortfalls = lower_control_program_to_ssa(
            control,
            function_name=str(function_name),
            first_value_id=first_value_id,
            region_value_meta=value_meta,
            sequence_declarations=declarations,
            sequence_column_dtypes=column_dtypes,
            source_sequence_ids=tuple(
                int(sequence["sequence_id"]) for sequence in sequences
            ),
            retained_sequence_ids=tuple(
                int(sequence["sequence_id"]) for sequence in sequences
            ),
            table_epilogue_operations=tuple(
                ("store", store) for store in table_stores
            ),
            host_reads_table_status=True,
        )
        identity_tokens = dict(
            (getattr(program, "extras", None) or {}).get(
                "ssa_identity_tokens", {}
            )
        )
        function.metadata.update({
            "ssa_identity_tokens": tuple(
                (int(value_id), tuple(map(str, token_chain)))
                for value_id, token_chain in sorted(
                    identity_tokens.items(), key=lambda item: int(item[0])
                )
            ),
            "structural_integral_contract": structural_contract,
            "structural_integral_kind": "resident-table-mutation",
        })
        record_by_value = {
            int(store["stored_value_id"]): str(sequence["value_record"])
            for store in stores
            for sequence in sequences
            if int(sequence["sequence_id"])
            == int(store["sequence_value_id"])
            and sequence.get("value_record") is not None
        }
        for argument in function.args:
            record_identity = record_by_value.get(int(argument.id))
            if record_identity is not None:
                argument.accounting.update({
                    "structural_record_identity": record_identity,
                    "structural_record_handle": True,
                })
        helper_functions, sequence_tables = _sequence_artifacts_from_control(
            function
        )
        module = IRModule({
            str(function_name): function,
            **helper_functions,
        })
        module.sequence_tables.update(sequence_tables)
        return (
            module,
            {str(function_name): ()},
            (str(function_name),),
            tuple(shortfalls),
        )

    function, shortfalls = lower_fused_program_to_ssa(
        program, function_name=str(function_name),
    )
    returns = tuple(
        instruction
        for block in function.blocks.values()
        for instruction in block.instrs
        if instruction.op in {"Ret", "ret", "Return", "return"}
    )
    output_values = tuple(returns[-1].args) if returns else ()
    return (
        IRModule({str(function_name): function}),
        {str(function_name): output_values},
        (str(function_name),),
        tuple(shortfalls),
    )


_LOG = logging.getLogger(__name__)


def _canonical_sequence_dtype(dtype: str | None) -> str | None:
    """Widen inferred Python-integer candidates without a declared row.

    A sequence's storage array is one shared piece of memory that every
    function touching that sequence declares independently (each
    ``_ControlSSABuilder`` instance is per-function and infers column
    dtype from whatever local evidence it has -- a query operand's dtype,
    a fill literal's Python type). Two functions inferring different
    integer widths for the same shared array is a real element-address
    mismatch, not a cosmetic type error. Collapsing every integer
    candidate to one fixed width here, at the sequence descriptor's sole
    construction point, makes every independent inference agree by
    construction instead of requiring them to be reconciled after the
    fact.
    """
    if dtype in {"int", "int8", "int16", "int32"}:
        return "int64"
    return dtype


@dataclass(frozen=True)
class ResolvedSequenceSchema:
    """One sequence's structural shape, resolved once across every function
    that touches it, before any single function's local view can lock in a
    shape another function disagrees with.

    ``_ControlSSABuilder`` instances are built one per function/region, each
    from that one function's own local ``sequence_declarations``/
    ``table_lookups``/``table_stores`` evidence. A sequence's numeric id is a
    genuinely global identity (it traces back to one shared ProcessGraph
    node), so two functions touching the same sequence can each build a
    ``SSASequenceDescriptor`` with a different number of storage cells --
    not just a different dtype, but a structurally different shape (whether
    a status cell or live-flags cell exists at all). That is a real
    memory-layout bug, not a cosmetic one: it shows up as a caller passing
    one SSA value to two formal positions a callee expects to be distinct.

    This schema carries only structural facts, never concrete SSA value
    ids -- each function still mints its own ids from its own disjoint local
    id namespace. ``column_count``/``policy`` are the two fields with no
    sensible "union": every function that touches this sequence must agree
    on them exactly, or the sequence's two conflicting authored shapes ARE
    the bug, and lowering should say so rather than silently pick one.
    ``writable``/``retains_deleted_rows``/``nested_table`` are booleans a
    survey resolves as an OR across every function -- if any one function
    needs the extra storage cell, the one shared array needs it too.
    """

    column_count: int
    policy: str
    writable: bool
    retains_deleted_rows: bool
    nested_table: bool
    nested_tensor: bool = False
    nested_value_dtype: str | None = None
    value_column_count: int = 1


def resolve_sequence_schemas(
    shells: Iterable[Mapping[str, Any]],
    *,
    location: str = "sequence-schema-survey",
) -> tuple[dict[int, ResolvedSequenceSchema], tuple[SSALoweringShortfall, ...]]:
    """Resolve one structural schema per sequence_id from every shell's raw
    evidence, before any shell's ``_ControlSSABuilder`` lowers and locks in
    a shape a different shell might disagree with.

    Each item in ``shells`` is a mapping carrying the same raw tuples
    ``_ControlSSABuilder`` itself consumes for one function/region:
    ``sequence_declarations``, ``sequence_initializations``,
    ``table_deletions``, ``retained_sequence_ids``, ``nested_sequence_ids``.
    Missing keys default to ``()``, so callers may pass only what they have.
    """
    column_counts: dict[int, int] = {}
    value_column_counts: dict[int, int] = {}
    policies: dict[int, str] = {}
    origins: dict[int, str] = {}
    writable_union: dict[int, bool] = {}
    retains_union: dict[int, bool] = {}
    nested_union: dict[int, bool] = {}
    nested_tensor_union: dict[int, bool] = {}
    conflicted: set[int] = set()
    shortfalls: list[SSALoweringShortfall] = []

    def _observe(
        sequence_id: object,
        column_count: object,
        policy: object,
        writable: object,
        origin: object,
        value_column_count: int = 1,
    ) -> None:
        sid = int(sequence_id)
        if sid in column_counts and (
            column_counts[sid] != int(column_count)
            or policies[sid] != str(policy)
            or value_column_counts[sid] != int(value_column_count)
        ):
            if sid not in conflicted:
                shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", "resolved-schema-conflict", location,
                    f"sequence value {sid} was declared with "
                    f"{column_counts[sid]} column(s)/policy {policies[sid]!r} "
                    f"in {origins[sid]} and "
                    f"{int(column_count)} column(s)/policy {str(policy)!r} "
                    f"in {str(origin)} -- every function touching a shared "
                    "sequence must agree on its shape and value-column width",
                ))
                conflicted.add(sid)
            return
        column_counts[sid] = int(column_count)
        value_column_counts[sid] = int(value_column_count)
        policies[sid] = str(policy)
        origins[sid] = str(origin)
        writable_union[sid] = writable_union.get(sid, False) or bool(writable)

    for shell in shells:
        function_name = shell.get("function_name", "<unknown-function>")
        sequence_names = dict(shell.get("sequence_names") or {})
        deletion_ids = {
            int(sequence_id)
            for _effect_id, _key_id, sequence_id, _storage_identity
            in shell.get("table_deletions", ())
            if sequence_id is not None
        }
        deletion_ids.update(int(sid) for sid in shell.get("retained_sequence_ids", ()))
        deletion_ids.update(int(sid) for sid in shell.get("deletion_sequence_ids", ()))
        nested_ids = {int(sid) for sid in shell.get("nested_sequence_ids", ())}
        nested_tensor_ids = {
            int(sid) for sid in shell.get("nested_tensor_sequence_ids", ())
        }
        for sequence_id, policy, column_count, writable in shell.get(
            "sequence_declarations", ()
        ):
            names = tuple(sequence_names.get(int(sequence_id), ()))
            origin = f"{function_name}{names!r}"
            _observe(
                sequence_id, column_count, policy, writable, origin,
                int(dict(shell.get("sequence_value_column_counts") or {}).get(
                    int(sequence_id), 1
                )),
            )
            sid = int(sequence_id)
            retains_union[sid] = retains_union.get(sid, False) or sid in deletion_ids
            nested_union[sid] = nested_union.get(sid, False) or sid in nested_ids
            nested_tensor_union[sid] = (
                nested_tensor_union.get(sid, False)
                or sid in nested_tensor_ids
            )
        for sequence_id, policy, column_count in shell.get(
            "sequence_initializations", ()
        ):
            names = tuple(sequence_names.get(int(sequence_id), ()))
            origin = f"{function_name}{names!r}"
            descriptor_policy = (
                "duplicates"
                if str(policy).startswith((
                    "fill=", "literal_bytes=", "literal_glyphs=",
                    "literal_rows=",
                ))
                else "unique"
                if str(policy).startswith("literal_table=")
                else str(policy)
            )
            _observe(
                sequence_id, column_count, descriptor_policy, True, origin,
            )
            sid = int(sequence_id)
            retains_union[sid] = retains_union.get(sid, False) or sid in deletion_ids
            nested_union[sid] = nested_union.get(sid, False) or sid in nested_ids
            nested_tensor_union[sid] = (
                nested_tensor_union.get(sid, False)
                or sid in nested_tensor_ids
            )

    resolved = {
        sid: ResolvedSequenceSchema(
            column_count=column_counts[sid],
            policy=policies[sid],
            writable=writable_union.get(sid, False),
            retains_deleted_rows=retains_union.get(sid, False),
            nested_table=nested_union.get(sid, False),
            nested_tensor=nested_tensor_union.get(sid, False),
            value_column_count=value_column_counts[sid],
        )
        for sid in column_counts
        if sid not in conflicted
    }
    return resolved, tuple(shortfalls)


def _post_derived_or_raw(
    book: Any, page: Any, row: tuple, fact: Any, sources: Any,
    *, stage: Any, mode: Any,
) -> Any:
    """Post ``fact`` DERIVED from ``sources`` when any exist; otherwise write
    it through the raw primitive, which the book tags ``Unsourced`` itself.

    For module-level writers (the region assembly, the reconciliation pass)
    that have no function root to fall back on: a write that can name no
    cell stays visible on the unsourced worklist rather than inventing one.
    """

    cells = tuple(cell for cell in (sources or ()) if isinstance(cell, Ref))
    # No raw path: the post derives from ``cells`` or is refused at the
    # caller that handed it none.
    return book.post(
        page, row, fact, stage=stage, provenance=Derived(cells), mode=mode,
    )


def _post_region_signature(
    book: Any, scope: Any, lexical_read_scope: Any, region_index: int,
    signature: tuple,
) -> Any:
    """``region_signature`` row ``(function scope, region)``: CONCORD
    DERIVED(the ``deployment_region`` cell when the planner posted one, else
    the canonical cells of the region's feeds and outputs -- plan 80 B7's
    fallback, re-derived when the planner's cell lands)."""

    feeds, outputs = signature
    fact = RegionSignature(tuple(map(int, feeds)), tuple(map(int, outputs)))
    row = (scope, int(region_index))
    existing = book.latest_ref(REGION_SIGNATURE, row)
    if existing is not None and (
        book.pages[REGION_SIGNATURE.name].cells.get((row, existing.column))
        == fact
    ):
        return existing
    sources: list = []
    if lexical_read_scope is not None:
        for value_id in (*feeds, *outputs):
            cell = book.latest_ref(
                CANONICAL_VALUE, (tuple(lexical_read_scope), int(value_id)),
            )
            if cell is not None and cell not in sources:
                sources.append(cell)
    if not sources:
        # A region of a lowering with no lexical read scope (a fused or
        # planned region) or whose values have no canonical cell stands on
        # its control function's root, as ``fresh_value`` does for a mint
        # with no more specific cell.
        sources.append(_function_root_cell(book, scope))
    return _post_derived_or_raw(
        book, REGION_SIGNATURE, row, fact, tuple(sources),
        stage=CONTROL_SSA_REGION, mode=Mode.CONCORD,
    )


def _function_root_cell(book: Any, scope: Any) -> Ref:
    """The function-root ``cell_set`` row ``(scope, 0)`` of a lowering, posted
    NOVEL(CONTROL_FUNCTION_ROOT) on first need (the same row the builder's
    ``_function_root`` posts, so a module-level minter shares it)."""

    existing = book.latest_ref(CELL_SET, (scope, 0))
    if existing is not None:
        return existing
    return book.post(
        CELL_SET, (scope, 0), (),
        stage=CONTROL_SSA_ENTRY,
        provenance=Novel(CONTROL_FUNCTION_ROOT, ()),
        mode=Mode.CONCORD,
    )


def _bind_planning_alias(
    page: Any, scope: Any, alias: int, resident: int, sources: Any = (),
    *, root_scope: Any = None,
) -> None:
    """``IdentityPage.bind_alias`` through the book: REVISE
    ``planning_value_concordance`` row ``(scope, alias)`` DERIVED from
    ``sources`` (the graph cells the caller read), the planning rows the
    resident already resolves through, else the control function's root
    (``root_scope``, the lowering's ``name@control:N``).  A page the book does not own (a standalone planning page) keeps
    the page's own ``bind_alias``."""

    from .concordance_declarations import PLANNING_RESIDENCY, PLANNING_VALUE
    from .identity_concordance import current_identity_book

    book = current_identity_book()
    if book.pages.get(page.name) is not page:
        page.bind_alias(scope, alias, resident)
        return
    cells = [cell for cell in (sources or ()) if isinstance(cell, Ref)]
    cell = book.latest_ref(PLANNING_VALUE, (scope, int(resident)))
    if cell is not None and cell not in cells:
        cells.append(cell)
    if not cells:
        cells.append(_function_root_cell(
            book, scope if root_scope is None else root_scope,
        ))
    book.post(
        PLANNING_VALUE, (scope, int(alias)), int(resident),
        stage=PLANNING_RESIDENCY, provenance=Derived(tuple(cells)),
        mode=Mode.REVISE,
    )


#: Instructions whose result is a view of argument 0's storage (an element,
#: an address into it, a store version of it), not new storage.
_STORAGE_VIEW_OPERATIONS = frozenset({
    "Indexed", "IndexedStore", "GetElementPtr", "Load",
})


def _post_storage_roots(
    book: Any, scope: Any, lexical_read_scope: Any, *,
    formals: Mapping[int, Any], instructions: Iterable[Instr],
    aliases: Mapping[int, int], wanted: Iterable[int],
) -> dict[int, Ref]:
    """Post the ``storage_root`` row of every value in ``wanted`` (and of the
    values its row derives from) and return the cells by value id.

    ``formals``: value id -> the formal's binding cell (or None).  A formal
    is a FORMAL root, an instruction result a PRODUCED root, unless the
    instruction is a view (``_STORAGE_VIEW_OPERATIONS``, or a result that
    declares ``ssa_storage_view``) or the value is a planning alias: those
    are VIEW rows DERIVED from the root cell of the storage they view.
    A value with neither is ``Unresolved(STORAGE_ROOT_UNKNOWN)``.
    """

    producers: dict[int, Instr] = {}
    for instruction in instructions:
        if instruction.res is not None:
            producers.setdefault(int(instruction.res.id), instruction)
    read_scope = (
        None if lexical_read_scope is None else tuple(lexical_read_scope)
    )

    def canonical_cell(value_id: int) -> Ref | None:
        if read_scope is None:
            return None
        return book.latest_ref(CANONICAL_VALUE, (read_scope, int(value_id)))

    cells: dict[int, Ref] = {}
    resolving: set[int] = set()

    def root(value_id: int) -> Ref:
        value_id = int(value_id)
        if value_id in cells:
            return cells[value_id]
        row = (scope, value_id)
        if value_id in resolving:
            # A store version feeding its own base through a carried edge:
            # the cycle names no producer.
            raise ValueError(
                f"{STORAGE_ROOT.name}: no source cell for {row!r} -- a store "
                "version feeds its own base through a carried edge"
            )
        resolving.add(value_id)
        try:
            if value_id in formals:
                source = formals[value_id] or canonical_cell(value_id)
                if source is None:
                    raise ValueError(
                        f"{STORAGE_ROOT.name}: no source cell for {row!r} -- "
                        "the formal has neither a binding nor a canonical_value cell"
                    )
                cell = book.post(
                    STORAGE_ROOT, row,
                    StorageRootFact(StorageRootKind.FORMAL),
                    stage=STORAGE_ROOT_STAGE,
                    provenance=Novel(STORAGE_FORMAL, (source,)),
                    mode=Mode.CONCORD,
                )
            elif value_id in aliases and int(aliases[value_id]) != value_id:
                cell = book.post(
                    STORAGE_ROOT, row, StorageRootFact(StorageRootKind.VIEW),
                    stage=STORAGE_ROOT_STAGE,
                    provenance=Derived((root(int(aliases[value_id])),)),
                    mode=Mode.CONCORD,
                )
            elif value_id in producers:
                instruction = producers[value_id]
                viewed = (
                    instruction.args
                    and (
                        str(instruction.op) in _STORAGE_VIEW_OPERATIONS
                        or isinstance(
                            (instruction.res.accounting or {}).get(
                                "ssa_storage_view"
                            ),
                            Mapping,
                        )
                    )
                )
                if viewed:
                    cell = book.post(
                        STORAGE_ROOT, row,
                        StorageRootFact(StorageRootKind.VIEW),
                        stage=STORAGE_ROOT_STAGE,
                        provenance=Derived((root(int(instruction.args[0].id)),)),
                        mode=Mode.CONCORD,
                    )
                else:
                    source = canonical_cell(value_id)
                    if source is None:
                        raise ValueError(
                            f"{STORAGE_ROOT.name}: no source cell for {row!r}"
                            " -- the produced value has no canonical_value cell"
                        )
                    cell = book.post(
                        STORAGE_ROOT, row,
                        StorageRootFact(StorageRootKind.PRODUCED),
                        stage=STORAGE_ROOT_STAGE,
                        provenance=Novel(STORAGE_PRODUCED, (source,)),
                        mode=Mode.CONCORD,
                    )
            else:
                raise ValueError(
                    f"{STORAGE_ROOT.name}: no source cell for {row!r} -- the "
                    "value is no formal, alias or instruction result"
                )
        finally:
            resolving.discard(value_id)
        cells[value_id] = cell
        return cell

    for value_id in wanted:
        root(int(value_id))
    return cells


def _storage_formal_root(book: Any, cell: Ref) -> Ref | None:
    """Walk ``cell``'s DERIVED edges on ``storage_root`` to its root; the
    root's cell when it is a FORMAL's storage, else ``None``."""

    page = book.page(STORAGE_ROOT)
    seen: set = set()
    frontier = [cell]
    while frontier:
        ref = frontier.pop()
        if ref.key in seen:
            continue
        seen.add(ref.key)
        fact = page.latest(ref.row)
        if isinstance(fact, StorageRootFact):
            if fact.kind is StorageRootKind.FORMAL:
                return ref
            if fact.kind is StorageRootKind.PRODUCED:
                continue
        frontier.extend(
            source for source, _stage in book.edges_into(ref)
            if source.page.name == STORAGE_ROOT.name
        )
    return None


def post_parameter_abi_kinds(
    book: Any, lexical_read_scope: Any, parameters: Iterable[str], *,
    value_abi: Mapping[str, Any], record_abi: Mapping[str, Any],
) -> dict[str, Ref]:
    """Post each parameter's ``parameter_abi_kind`` row at the signature
    and return the cells by name.

    The declaration is the extraction contract's (``value_abi``: a
    ProgramABI value binding; ``record_abi``: a record binding, the
    receiver included).  A declared kind is NOVEL(PARAMETER_ABI_DECLARATION,
    (version-0 ``name_binding`` cell,)); a parameter nothing declares, or a
    storage spelling outside ``ParameterAbiKind``, is
    ``Unresolved(PARAMETER_ABI_UNDECLARED)`` derived from that cell.
    """

    cells: dict[str, Ref] = {}
    if lexical_read_scope is None:
        return cells
    read_scope = tuple(lexical_read_scope)
    for name in dict.fromkeys(map(str, parameters)):
        binding = book.latest_ref(NAME_BINDING, (lexical_read_scope, name, 0))
        if name in record_abi:
            spelling = "record"
        else:
            spelling = str(dict(value_abi.get(name) or {}).get("storage") or "")
        try:
            kind = ParameterAbiKind(spelling)
        except ValueError:
            kind = None
        row = (read_scope, name)
        if kind is not None and binding is not None:
            fact, provenance = kind, Novel(PARAMETER_ABI_DECLARATION, (binding,))
        elif binding is not None:
            fact = Unresolved(PARAMETER_ABI_UNDECLARED, (binding,))
            provenance = Derived((binding,))
        else:
            raise ValueError(
                f"{PARAMETER_ABI_KIND.name}: no source cell for {row!r} -- "
                "the parameter has no version-0 name_binding cell"
            )
        existing = book.latest_ref(PARAMETER_ABI_KIND, row)
        if existing is not None and book.page(PARAMETER_ABI_KIND).latest(row) == fact:
            cells[name] = existing
            continue
        cells[name] = book.post(
            PARAMETER_ABI_KIND, row, fact, stage=STORAGE_ROOT_STAGE,
            provenance=provenance,
            mode=Mode.CONCORD if existing is None else Mode.REVISE,
        )
    return cells


def _mint_ssa_id(
    book: Any, scope: Any, transform: Any, operands: Any, *,
    dtype: Any = None, shape: tuple = (), stage: Any, physical: Any = None,
) -> int:
    """Mint one SSA id through the book from outside a builder: a NOVEL
    ``ssa_value`` row on ``(scope, NEW)`` whose operand is the one cell in
    ``operands`` (several become a ``cell_set`` row; none is refused, since
    a module-level minter has no function root)."""

    cells = tuple(dict.fromkeys(
        cell for cell in (operands or ()) if isinstance(cell, Ref)
    ))
    if len(cells) == 1:
        operand = cells[0]
    elif cells:
        ordinal = book.page(CELL_SET).scope_row_count(scope) + 1
        operand = book.post(
            CELL_SET, (scope, ordinal), tuple(cell.key for cell in cells),
            stage=stage, provenance=Derived(cells), mode=Mode.CONCORD,
        )
    else:
        raise ConcordanceRefusal(
            f"mint under {scope!r} names no operand cell for {transform.name}"
        )
    # Rule: a mint declares its physical fields (``physical``: a mapping of
    # SSAValueFact physical fields, or None for a mint with none).
    ref = book.post(
        SSA_VALUE, (scope, NEW),
        SSAValueFact(
            dtype, tuple(shape), SSAValueOrigin.MINTED, **dict(physical or {}),
        ),
        stage=stage, provenance=Novel(transform, (operand,)), mode=Mode.REVISE,
    )
    return int(ref.row[1])


def _declared_physical_dtype(dtype: Any) -> dict[str, Any]:
    """``{"physical_dtype": dtype}`` for a mint whose element dtype is the
    declared one of the storage it creates; nothing for an unresolved dtype
    (an absent dtype is never posted as a physical one)."""

    if dtype in (None, "", "unknown", "None"):
        return {}
    return {"physical_dtype": str(dtype)}


def _contract_physical(
    book: Any, value: Any, *cells: Any, dtype: str | None = None,
) -> tuple[dict[str, Any], Ref] | None:
    """The physical fields of ``value`` read from its ProgramABI contract row.

    Program: every probe that lowers a typed parameter (repro_opt_tuple.py,
    caller.py, whole.py, gen_sort.py).  Wrong record: the ``ssa_value`` row of
    a root/region formal or a graph-id result carried no ``storage``/``rank``
    while the contract's ``value_type_abi`` row for that very graph id
    declared them (audit ``ssa-physical-unposted``).  Rule: the producer posts
    the fields DERIVED from that contract row -- the ``value_type_abi`` cell
    at the row of the value's ``canonical_value``/``ingestion_value`` cell --
    and only when the row's physical arms are one view (a union whose arms
    share storage, dtype, shape and rank is that view) whose dtype is the
    value's own (and, for a scalar arm, a shapeless value).  A union of
    different views, an optional, a row of another type, or no row posts
    nothing: the fields stay absent rather than guessed.  Returns ``(fields, contract cell)`` so the
    caller adds the contract cell to its DERIVED sources."""

    for cell in cells:
        if not isinstance(cell, Ref) or cell.page not in (
            CANONICAL_VALUE, INGESTION_VALUE,
        ):
            continue
        contract = book.current_ref(VALUE_TYPE_ABI, cell.row)
        if contract is None:
            continue
        fact = book.page(VALUE_TYPE_ABI).cell(contract.row, contract.column)
        arms = tuple(getattr(fact, "physical_alternatives", ()))
        views = {
            (arm.storage, arm.dtype, tuple(arm.shape), arm.rank)
            for arm in arms
        }
        if len(views) != 1 or arms[0].storage == "none":
            return None
        arm = arms[0]
        selected_dtype = value.dtype if dtype is None else dtype
        if str(arm.dtype) != str(selected_dtype):
            return None
        if arm.storage == "scalar" and tuple(value.shape or ()):
            return None
        return {"storage": str(arm.storage), "rank": int(arm.rank)}, contract
    return None


def _runtime_rank_physical(
    book: Any, shape_scope: Any, value: Any,
) -> tuple[dict[str, Any], Ref] | None:
    """A shapeless region result's runtime rank, read from its shape state.

    Program: ``def f(x, y): return x * y`` with x and y declared
    ``storage: span, rank: 1`` and no ``shape``.  Wrong record: the planner's
    descriptor for the product said rank 1, runtime extents
    (``shape_transformation_state``), and the region ``value`` carried that
    rank as accounting, but its ``ssa_value`` row was posted scalar with no
    rank -- so call-result settlement carried a scalar to the caller and
    every backend sized a one-element result.  Rule: a result with no shape
    and no contract row whose graph identity's shape state is a runtime-sized
    span posts ``storage: span`` and that rank, DERIVED from the state cell.
    """

    from .identity_concordance import (
        SHAPE_STATE_PAGE, descriptor_from_shape_transformation_state,
        shape_transformation_state,
    )

    if shape_scope is None:
        return None
    row = (tuple(shape_scope), int(value.id))
    cell = book.latest_ref(SHAPE_STATE_PAGE, row)
    if cell is None:
        return None
    fact = book.page(SHAPE_STATE_PAGE).latest(row)
    if not (isinstance(fact, tuple) and fact and fact[0] == "resolved"):
        return None
    descriptor = descriptor_from_shape_transformation_state(fact[1])
    # Program: ``acc = acc * 2 + i`` in a ``while`` (every int loop).  Wrong
    # record: the computed update posted no storage/rank/physical dtype while
    # the carried slot's literal initial posted them, so the loop-carry
    # transport disagreed.  Rule: a result whose shape state is a resolved
    # static numeric one of the value's own dtype and shape posts that
    # state's physical view, DERIVED from the state cell (this producer
    # owns it; the structural view no longer infers it).
    state = shape_transformation_state(fact[1])
    if state is not None and state[3] == "static":
        from ..transmogrifier.dtype_layout import resolve

        shape, dtype, rank, _metadata, _row_shape = state
        layout = resolve(dtype)
        if (
            layout is not None
            and layout.kind in {"bool", "int", "uint", "float"}
            and str(dtype) == str(value.dtype)
            and str(dtype) != "opaque_ref"
            and rank == len(shape)
            and tuple(shape) == tuple(value.shape or ())
        ):
            return {
                "physical_dtype": str(dtype),
                "storage": "span" if rank else "scalar", "rank": rank,
            }, cell
    if tuple(value.shape or ()):
        return None
    if not (
        descriptor is not None
        and not tuple(descriptor.get("shape") or ())
        and int(descriptor.get("rank", 0) or 0) > 0
        and str(descriptor.get("metadata_state") or "") == "dynamic"
        and str(descriptor.get("dtype")) == str(value.dtype)
    ):
        return None
    return {"storage": "span", "rank": int(descriptor["rank"])}, cell


def _post_planned_region_identities(
    book: Any, scope: str, function: Function, signature_cell: Any,
    graph_cell: Any, shape_scope: Any = None,
) -> None:
    """The identity cells of one planned region function (plan 100, 4.1
    item 2 and 2.6), posted where ``lower_control_sections_to_ssa``
    assembles it.

    ``ssa_value``: every value the region body PRODUCES with no row yet --
    a literal's ``Const`` and every intermediate, whose ids are the graph
    ids they lower -- is adopted as the control builder's ``_value_cell``
    adopts a graph id: ADOPTED_GRAPH_ID DERIVED from the id's
    ``canonical_value`` cell (``graph_cell``, the read-only post-relabel arm
    of ``node_identity_cell``), else
    ``Unsourced(GRAPH_ID_WITHOUT_CANONICAL_CELL)``.  A value that already
    has a row keeps it. Missing declared formals are published from the exact
    region signature, canonical feed and control binding: a logical feed can
    otherwise have only its distinct physical SSA value recorded.

    ``ssa_block``: the region's one block, DERIVED from the region's
    ``region_signature`` cell."""

    from .concordance_declarations import (
        REGION_VALUE_MINT_UNRECORDED, SSA_BLOCK, SSABlockKind,
    )
    from .id_space import MINTED, has_flag

    # A region formal can retain its logical graph id while control lowering
    # bound that feed to a distinct physical Load/Phi value. In that case the
    # feed's presumed SSA row does not exist. Publish the actual declared
    # formal here, where both its signature and binding are available.
    if isinstance(signature_cell, Ref):
        for value in function.args:
            row = (scope, int(value.id))
            if book.latest_ref(SSA_VALUE, row) is not None:
                continue
            # Program: repro_opt_tuple.py / caller.py planned-region formals.
            # Wrong record: the formal's row was born with no storage/rank
            # although its feed's contract row declares them.  Rule: DERIVED
            # from that ``value_type_abi`` row (``_contract_physical``).
            _declared = _contract_physical(
                book, value, graph_cell(int(value.id)),
            )
            sources = tuple(dict.fromkeys(cell for cell in (
                signature_cell, graph_cell(int(value.id)),
                book.latest_ref(CONTROL_VALUE_BINDING, row),
                *((_declared[1],) if _declared else ()),
            ) if cell is not None))
            book.post(
                SSA_VALUE, row,
                SSAValueFact(value.dtype, tuple(value.shape or ()),
                             SSAValueOrigin.ADOPTED_GRAPH_ID,
                             **(_declared[0] if _declared else {})),
                stage=CONTROL_SSA_REGION, provenance=Derived(sources),
                mode=Mode.CONCORD,
            )
    for block in function.blocks.values():
        for instruction in block.instrs:
            value = instruction.res
            if value is None or getattr(value, "id", None) is None:
                continue
            row = (scope, int(value.id))
            if book.latest_ref(SSA_VALUE, row) is not None:
                continue
            source = graph_cell(int(value.id))
            # An id with the MINTED flag is no graph id: its minter (the
            # plan's min/max fold) posted no record, and the row says so
            # rather than calling it adopted.
            minted = has_flag(int(value.id), MINTED)
            if source is None:
                # No canonical cell: the value is the region's own (a planned
                # or fused region, or a plan-minted id) and stands on the
                # region's signature cell, else on the control function's
                # root -- the rule ``_post_region_signature`` applies.
                source = (
                    signature_cell if isinstance(signature_cell, Ref)
                    else _function_root_cell(book, scope)
                )
            # Program: history_projection / loop_call_carry region results.
            # Wrong record: a Call/Load/formal result of a region block was
            # posted with no storage/rank although the graph id's contract
            # row declares them.  Rule: DERIVED from that ``value_type_abi``
            # row (``_contract_physical``); a result with no such row (a
            # minted id, an address Load) posts nothing.
            _declared = (
                None if minted
                else _contract_physical(
                    book, value, graph_cell(int(value.id)),
                )
                or _runtime_rank_physical(book, shape_scope, value)
            )
            book.post(
                SSA_VALUE, row,
                SSAValueFact(
                    value.dtype, tuple(value.shape or ()),
                    SSAValueOrigin.MINTED if minted
                    else SSAValueOrigin.ADOPTED_GRAPH_ID,
                    **(_declared[0] if _declared else {}),
                ),
                stage=CONTROL_SSA_REGION,
                provenance=Derived((
                    source, *((_declared[1],) if _declared else ()),
                )),
                mode=Mode.REVISE,
            )
    if not isinstance(signature_cell, Ref):
        return
    # Source ABI publication precedes consumers of these captures. This is
    # shared by bootstrap regions and the managed validator/tire regions.
    from .ssa_record_return_state import publish_declared_scalar_abi

    for value in function.args:
        publish_declared_scalar_abi(
            function, value, graph_cell(int(value.id)),
            stage=CONTROL_SSA_REGION, book=book,
        )
    for label in function.blocks:
        book.post(
            SSA_BLOCK, (scope, str(function.name), str(label)),
            SSABlockKind(str(label)), stage=CONTROL_SSA_REGION,
            provenance=Derived((signature_cell,)), mode=Mode.CONCORD,
        )


def _control_expression_mapping(
    expression: ControlExpression | None,
) -> dict[str, object] | None:
    if expression is None:
        return None
    return {
        "op": str(expression.op),
        "operands": [
            _control_expression_mapping(operand)
            for operand in expression.operands
        ],
        "value_id": (
            None if expression.value_id is None else int(expression.value_id)
        ),
        "literal": expression.literal,
    }


def register_sequence_lowering(
    lowering: Any, *, book: Any, owner: Ref, caller_scope: Any, stage: Any,
) -> tuple[dict[str, Function], dict[int, SSAValue]]:
    """Install sequence helpers and give every generated value a book-minted ID.

    The sequence algorithm builder's IDs are construction-local labels.
    A helper becomes compiler SSA only here, at its source-linked
    registration boundary; its durable identities are therefore minted
    from the exact operation/control cell that caused the helper (``owner``)
    and from already-published operand cells.  Descriptor storage formals
    keep the caller's (``caller_scope``) physical ids and derive their rows
    from the caller's rows.  Every producer of a sequence helper registers it
    here: the control builder and the shell's structural recovery.

    Returns the registered helpers by name and the generated results that
    still have no row (the control builder adopts those as read views).
    """
    registered: dict[str, Function] = {}
    unposted: dict[int, SSAValue] = {}


    def remap_metadata(value: Any, replacements: Mapping[int, int]) -> Any:
        if isinstance(value, bool):
            return value
        if isinstance(value, int):
            return replacements.get(int(value), value)
        if isinstance(value, tuple):
            return tuple(remap_metadata(item, replacements) for item in value)
        if isinstance(value, list):
            return [remap_metadata(item, replacements) for item in value]
        if isinstance(value, dict):
            return {
                remap_metadata(key, replacements): remap_metadata(
                    item, replacements,
                )
                for key, item in value.items()
            }
        return value

    for function in lowering.functions:
        scope = str(function.name)
        mint_page = book.pages.get("concordance_mint")
        minted_with_edges = {
            int(row[1])
            for row in (() if mint_page is None else mint_page.rows())
            if row[1] is not None
        }
        replacements: dict[int, int] = {}
        # Extra helper formals (for example a keyed lookup's query) are
        # construction-local identities. Descriptor storage formals keep
        # the caller's already-minted physical IDs; only an unaccounted
        # minted label receives a durable helper-local identity here.
        for argument in function.args:
            old_id = int(argument.id)
            if has_flag(old_id, MINTED) and old_id not in minted_with_edges:
                # Program: keyed Tensor lookup (tests/test_sequence_helper
                # _physical_rows.py).  Wrong record: the lookup helper's
                # own formals (its query/default; the builder declares
                # their dtype from the descriptor's key/value column) were
                # minted with dtype only, ``physical_dtype`` reaching the
                # row in accounting alone.  Rule: this registration is the
                # first producer to know the formal and its declared
                # dtype, so the mint posts it (plus ``arena`` when the
                # builder declared a ``sequence_arena``); accounting
                # follows the fact.
                _arena = bool(
                    (argument.accounting or {}).get("sequence_arena")
                )
                replacements[old_id] = _mint_ssa_id(
                    book, scope, CONTROL_EXPRESSION, (owner,),
                    dtype=argument.dtype,
                    shape=tuple(argument.shape or ()),
                    stage=stage,
                    physical={
                        **({"arena": True} if _arena else {}),
                        **_declared_physical_dtype(argument.dtype),
                    } or None,
                )
        if replacements:
            for value in (
                *function.args,
                *(
                    item
                    for block in function.blocks.values()
                    for instruction in block.instrs
                    for item in instruction.args
                ),
            ):
                value.id = replacements.get(int(value.id), int(value.id))
            function.metadata = remap_metadata(
                dict(function.metadata or {}), replacements,
            )
        for label in function.blocks:
            row = (scope, str(function.name), str(label))
            if book.latest_ref(SSA_BLOCK, row) is None:
                book.post(
                    SSA_BLOCK,
                    row,
                    SSABlockKind.SEQUENCE_HELPER,
                    stage=stage,
                    provenance=Derived((owner,)),
                    mode=Mode.CONCORD,
                )
        for argument in function.args:
            row = (scope, int(argument.id))
            if book.latest_ref(SSA_VALUE, row) is None:
                # Program: keyed Tensor lookup.  Wrong record: a helper
                # formal that keeps the caller's descriptor id was
                # adopted with dtype only while the caller's own row
                # (this builder's descriptor mint) posts its physical
                # fields.  Rule: the formal is the same storage, so its
                # row is DERIVED from the caller's row and carries the
                # fields that row records; none recorded posts none.
                _caller_ref = book.latest_ref(
                    SSA_VALUE, (caller_scope, int(argument.id)),
                )
                _caller_fact = (
                    None if _caller_ref is None else
                    book.page(SSA_VALUE).cell(
                        _caller_ref.row, _caller_ref.column,
                    )
                )
                _carried = {
                    name: getattr(_caller_fact, name)
                    for name in (
                        "physical_dtype", "storage", "rank", "arena",
                        "device",
                    )
                    if isinstance(_caller_fact, SSAValueFact)
                    and getattr(_caller_fact, name) not in (None, False)
                }
                # Program: ``[5] * (n % 4 + 1)`` (scratch c_k1).  Wrong
                # record: a sequence helper's heap column formal is the
                # arena's ``ptr`` CELL by construction (``_storage_values``),
                # but the structural view completed its empty shape from
                # the owner graph's (1,) extent and the reserve's heap copy
                # refused the shaped "handle".  Rule: the helper declares
                # that formal a reference, one address no graph extent
                # shapes.  The owner's column keeps its span view: a planned
                # region reduces over its rows through it (corpus c152).
                if (
                    str(argument.dtype) == "ptr"
                    and (argument.accounting or {}).get(
                        "heap_owner_value_id"
                    ) is not None
                ):
                    _carried["storage"] = "reference"
                book.post(
                    SSA_VALUE,
                    row,
                    SSAValueFact(
                        argument.dtype,
                        tuple(argument.shape or ()),
                        SSAValueOrigin.ADOPTED_GRAPH_ID,
                        **_carried,
                    ),
                    stage=stage,
                    provenance=Derived(tuple(
                        (owner,) if not _carried
                        else (owner, _caller_ref)
                    )),
                    mode=Mode.REVISE,
                )
        generated = tuple(
            (instruction, instruction.res)
            for block in function.blocks.values()
            for instruction in block.instrs
            if instruction.res is not None
        )
        for instruction, result in generated:
            old_id = int(result.id)
            operand_cells = tuple(dict.fromkeys(
                cell for value in instruction.args
                if (cell := book.latest_ref(
                    SSA_VALUE,
                    (
                        scope,
                        replacements.get(int(value.id), int(value.id)),
                    ),
                )) is not None
            ))
            replacements[old_id] = _mint_ssa_id(
                book,
                scope,
                (
                    CONTROL_CONST
                    if str(instruction.op).casefold() == "const"
                    else CONTROL_EXPRESSION
                ),
                operand_cells or (owner,),
                dtype=result.dtype,
                shape=tuple(result.shape or ()),
                stage=stage,
            )
        seen_values: set[int] = set()
        for value in (
            *function.args,
            *(
                item
                for block in function.blocks.values()
                for instruction in block.instrs
                for item in (
                    *instruction.args,
                    *((instruction.res,) if instruction.res is not None else ()),
                )
            ),
        ):
            if id(value) in seen_values:
                continue
            seen_values.add(id(value))
            value.id = replacements.get(int(value.id), int(value.id))
        function.metadata = remap_metadata(
            dict(function.metadata or {}), replacements,
        )
        registered[function.name] = function
        for block in function.blocks.values():
            for instruction in block.instrs:
                result = instruction.res
                if result is None:
                    continue
                row = (scope, int(result.id))
                if book.latest_ref(SSA_VALUE, row) is not None:
                    continue
                unposted[int(result.id)] = result
    return registered, unposted


class _ControlSSABuilder(TiledObject):
    __live_storage_root__ = True

    @staticmethod
    def _walk_sequence_queries(block: ControlBlock):
        """Yield lexical sequence queries from the retained control tree."""

        if isinstance(block, SequenceQueryBlock):
            yield block
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                yield from _ControlSSABuilder._walk_sequence_queries(child)
        elif isinstance(block, ConditionalBlock):
            yield from _ControlSSABuilder._walk_sequence_queries(block.body)
            if block.orelse is not None:
                yield from _ControlSSABuilder._walk_sequence_queries(
                    block.orelse
                )
        elif isinstance(block, LoopBlock):
            yield from _ControlSSABuilder._walk_sequence_queries(block.body)
        elif isinstance(block, WhileBlock):
            yield from _ControlSSABuilder._walk_sequence_queries(
                block.condition
            )
            yield from _ControlSSABuilder._walk_sequence_queries(block.body)
        elif isinstance(block, CallBlock):
            yield from _ControlSSABuilder._walk_sequence_queries(block.callee)

    def __init__(
        self,
        program: ControlProgram,
        *,
        function_name: str,
        first_value_id: int,
        region_callees: dict[int, str] | None,
        region_signatures: dict[
            int, tuple[tuple[int, ...], tuple[int, ...]]
        ] | None,
        region_writing_indices: frozenset[int] = frozenset(),
        region_feed_meta: Mapping[int, tuple[Meta, ...]] | None = None,
        region_value_meta: Mapping[int, Meta] | None = None,
        region_value_ranks: Mapping[int, int] | None = None,
        tensor_shape_concordance_scope: str | None = None,
        lexical_read_scope: Any = None,
        planning_scope: Any = None,
        source_value_descriptions: Mapping[int, Mapping[str, Any]] | None = None,
        shape_scope: Any = None,
        plan_callsite_bindings: Mapping[
            int, tuple[tuple[int, ...], tuple[int, ...]]
        ] | None = None,
        value_aliases: Mapping[int, int] | None = None,
        inout_value_ids: tuple[int, ...] = (),
        constant_value_ids: tuple[int, ...] = (),
        none_value_ids: tuple[int, ...] = (),
        output_value_ids: tuple[int, ...] = (),
        named_output_histories: Mapping[str, tuple[int, ...]] | None = None,
        value_name_histories: Mapping[str, tuple[int, ...]] | None = None,
        parameter_names: tuple[str, ...] = (),
        sequence_initializations: tuple[tuple[int, str, int], ...] = (),
        sequence_declarations: tuple[tuple[int, str, int, bool], ...] = (),
        sequence_column_dtypes: Mapping[int, tuple[str, ...]] | None = None,
        sequence_record_identities: Mapping[int, str] | None = None,
        sequence_child_table_layouts: Mapping[
            int, tuple[int, tuple[str, ...], tuple[int, ...], bool]
        ] | None = None,
        sequence_row_record_slots: Mapping[
            int, tuple[tuple[int, str, int], ...]
        ] | None = None,
        source_sequence_ids: tuple[int, ...] = (),
        dynamic_sequence_ids: tuple[int, ...] = (),
        sequence_memberships: tuple[
            tuple[int, int | tuple[int, ...], int, bool], ...
        ] = (),
        table_lookups: tuple[tuple[int, int | tuple[int, ...], int], ...] = (),
        lexical_table_lookup_result_ids: tuple[int, ...] = (),
        table_lookup_defaults: dict[int, int | float] | None = None,
        table_lookup_required_ids: frozenset[int] = frozenset(),
        table_stores: tuple[
            tuple[int, int | tuple[int, ...], int, int], ...
        ] = (),
        table_deletions: tuple[
            tuple[int, int | tuple[int, ...], int | None, str], ...
        ] = (),
        retained_sequence_ids: tuple[int, ...] = (),
        nested_sequence_ids: tuple[int, ...] = (),
        nested_tensor_sequence_ids: tuple[int, ...] = (),
        joined_sequence_ids: tuple[int, ...] = (),
        joined_singleton_values: Mapping[int, int] | None = None,
        nested_row_target_ids: tuple[int, ...] = (),
        selected_nested_sequence_ids: tuple[int, ...] = (),
        variant_projected_target_ids: tuple[int, ...] = (),
        region_array_feed_ids: Mapping[int, tuple[int, ...]] | None = None,
        nested_row_projections: tuple[tuple[int, int, int, str], ...] = (),
        sequence_length_values: Mapping[int, int] | None = None,
        table_region_operations: Mapping[int, tuple[tuple[str, tuple[Any, ...]], ...]] | None = None,
        table_region_post_operations: Mapping[int, tuple[tuple[str, tuple[Any, ...]], ...]] | None = None,
        table_epilogue_operations: tuple[tuple[str, tuple[Any, ...]], ...] = (),
        host_reads_table_status: bool = False,
        consumer_row_loads: Mapping[int, tuple[Any, ...]] | None = None,
        effect_preceding_row_reads: Mapping[int, tuple[int, ...]] | None = None,
        resolved_sequence_schemas: Mapping[int, ResolvedSequenceSchema] | None = None,
        native_object_context: Any = None,
        native_object_module: Any = None,
        native_object_value_ids: Iterable[int] = (),
        native_object_collections: Mapping[int, Mapping[str, Any]] | None = None,
        native_object_type_tests: Mapping[int, Mapping[str, Any]] | None = None,
        native_value_type_abi: Mapping[int, Any] | None = None,
        native_value_type_tests: Mapping[int, Mapping[str, Any]] | None = None,
    ):
        TiledObject.__post_init__(self)
        from .evolution_metagraph import (
            active_evolution_metagraph,
            record_control_program_evolution,
        )

        self.program = program
        #: ssa id -> the SSAValue object the book's ``ssa_value`` row names
        #: (plan 80 B2.1): the one private structure the builder keeps,
        #: because emitted instructions hold the objects and mutate them.
        self.ssa_value_objects: dict[int, SSAValue] = {}
        #: The function-root ``cell_set`` cell, posted on first need.
        self._root_cell: Ref | None = None
        #: The stage posts are made under until a construct's lowering
        #: sets its own (conditional, loop, region, finish).
        self.active_stage: Any = CONTROL_SSA_ENTRY
        self.evolution = active_evolution_metagraph()
        self.control_evolution = record_control_program_evolution(program)
        self.ssa_evolution = (
            None
            if self.evolution is None
            else self.evolution.open_graph("ssa", function_name)
        )
        self._evolution_source = None
        self._evolution_instruction = 0
        self.region_value_meta = dict(region_value_meta or {})
        self.region_value_ranks = {
            int(value_id): int(rank)
            for value_id, rank in (region_value_ranks or {}).items()
        }
        if tensor_shape_concordance_scope is None:
            # A lowering with no control scope handed in (the unit-level
            # entry point, a synthetic function): number one on the book so
            # two lowerings of one name never share their rows.
            _label, serial = self._book().mint_scope(f"control:{function_name}")
            tensor_shape_concordance_scope = f"{function_name}@control:{serial}"
        self.tensor_shape_concordance_scope = str(tensor_shape_concordance_scope)
        # The source graph's reduction scope on the identity book: per-read
        # bindings, per-loop carried bindings and per-region capture reads
        # are read from its pages, never passed in as tables.
        self.lexical_read_scope = (
            None if lexical_read_scope is None else tuple(lexical_read_scope)
        )
        self.planning_scope = planning_scope
        self.source_value_descriptions = {
            int(value_id): dict(description)
            for value_id, description in (source_value_descriptions or {}).items()
        }
        self.source_execution_receipts: dict[int, dict[str, Any]] = {}
        #: The shape scope of the graph COPY this function is lowered from
        #: (``identity_concordance.shape_scope_of``): the key every proven
        #: shape this lowering reads is held under.
        self.shape_scope = (
            ("ir_function", str(function_name)) if shape_scope is None
            else tuple(shape_scope)
        )
        #: The loops enclosing the current emission point, as keys of their
        #: ``loop_entry_state`` rows (None for a loop the book cannot key).
        self.enclosing_loop_states: list[Any] = []
        #: Per entered loop key: its carried entries (the lowering's own
        #: SSA values, by entry position) and whether the latch is being
        #: lowered.  Which entry a binding is lives on the book
        #: (``loop_carried_entry``); this is only where the entry's values are.
        self.loop_frames: dict[Any, dict[str, Any]] = {}
        self.value_aliases = {
            int(alias): int(source)
            for alias, source in (value_aliases or {}).items()
        }
        # The live alias map is temporarily rewritten while a loop body is
        # lowered so exit spellings denote the current carried value.  Keep
        # the resolved planning-concordance snapshot immutable for identity
        # and shape decisions that must survive those lexical rewrites.
        self.concorded_value_aliases = dict(self.value_aliases)
        # PLANNING aliases: one ``control_value_alias`` row per resolved
        # planning alias, DERIVED(the ``control_value_concordance`` cell that
        # resolved it, else the canonical cells of alias and source).
        for alias, source in self.value_aliases.items():
            self._post_alias(
                alias, source, AliasKind.PLANNING,
                self._book().latest_ref(
                    CONTROL_VALUE_CONCORDANCE, (str(function_name), int(alias)),
                ),
                stage=CONTROL_SSA_ENTRY,
            )
        self.inout_value_ids = set(map(int, inout_value_ids))
        # Authored literals the control function owns; a use before any
        # region published them is materialized by
        # ``_materialize_control_constants`` from the provisional argument
        # ``external_value`` mints, never invented as an ABI input.
        self.constant_value_ids = set(map(int, constant_value_ids))
        # Exact authored ``None`` literals, retained separately from the
        # other control-owned constants.  Return-frame normalization must
        # distinguish an absent aggregate/sequence arm from an arbitrary
        # one-slot value without guessing from an SSA dtype.
        self.none_value_ids = set(map(int, none_value_ids))
        self.output_value_ids = tuple(map(int, output_value_ids))
        self.resource_scopes: list[tuple[ResourceScopeBlock, int]] = []
        # (block, per-slot values) for every source ``return`` lowered below
        # the top level; merged per slot in `function_exit_block` by `finish`.
        self.function_return_edges: list[
            tuple[BasicBlock, tuple[SSAValue | None, ...]]
        ] = []
        # Exact optional-glyph presence carried by each authored return edge.
        # The key is the edge block and logical return slot.  It is populated
        # while lowering the conditional arm from that arm's
        # SOURCE_OPTIONAL_GLYPH_CARRY cell; finish must not attach the final
        # merged presence to an earlier return edge where it does not dominate.
        self.optional_glyph_return_presence_by_edge_slot: dict[
            tuple[str, int], SSAValue
        ] = {}
        self._function_exit: BasicBlock | None = None
        self.named_output_histories = {
            str(name): tuple(map(int, history))
            for name, history in (named_output_histories or {}).items()
        }
        self.value_name_histories = {
            str(name): tuple(map(int, history))
            for name, history in (value_name_histories or {}).items()
        }
        self.parameter_names = tuple(map(str, parameter_names))
        self.function_name = function_name
        self.blocks: dict[str, BasicBlock] = {}
        self.block_counts: dict[str, int] = {}
        #: The ``control_block`` cell (None: the block has no row of its
        #: own) of each control block being lowered, innermost last: the
        #: owner every ``ssa_block`` row ``new_block`` posts derives from.
        self._control_cells: list[Ref | None] = []
        self.shortfalls: list[SSALoweringShortfall] = []
        self.region_callees = dict(region_callees or {})
        # A region with a recorded signature is schedulable by definition; its
        # callee name follows the one convention every consumer already uses
        # (autogenesis, backend_sources, the mandelbrot demo all look for
        # ``numerical_region_N``). Defaulting here means a caller supplying
        # signatures alone -- the unit-level entry point does -- gets calls
        # emitted rather than a silently empty program.
        declared_indices = (
            *(region_signatures or {}),
            *(getattr(program, "region_indices", ()) or ()),
        )
        for signature_index in declared_indices:
            self.region_callees.setdefault(
                int(signature_index), f"numerical_region_{int(signature_index)}"
            )
        self.region_signatures = dict(region_signatures or {})
        # Regions whose body stores into memory (a sequence cell): never
        # output-less no-ops.
        self.region_writing_indices = frozenset(map(int, region_writing_indices))
        self.region_feed_meta = {
            int(region): tuple(metadata)
            for region, metadata in (region_feed_meta or {}).items()
        }
        # callsite_id -> (caller argument value ids, caller result value ids).
        self.plan_callsite_bindings = dict(plan_callsite_bindings or {})
        self.plan_callsite_by_result = {
            int(result_id): int(callsite_id)
            for callsite_id, (_argument_ids, result_ids)
            in self.plan_callsite_bindings.items()
            for result_id in result_ids
        }
        self.plan_callsites_by_argument: dict[int, tuple[int, ...]] = {}
        for callsite_id, (argument_ids, _result_ids) in (
            self.plan_callsite_bindings.items()
        ):
            for argument_id in argument_ids:
                value_id = int(argument_id)
                self.plan_callsites_by_argument[value_id] = tuple(dict.fromkeys((
                    *self.plan_callsites_by_argument.get(value_id, ()),
                    int(callsite_id),
                )))
        self.emitted_plan_callsites: set[int] = set()
        # While-latch condition regions may repeat a preheader region whose
        # output list also contains carried seed identities.  The header Phi
        # owns those identities throughout the loop; latch recomputation must
        # project colliding outputs to scratch instead of rebinding the Phi.
        self.preserved_region_output_ids: set[int] = set()
        self.arguments: list[SSAValue] = []
        self.external_values: dict[int, SSAValue] = {}
        #: The SSA value object published under each ``ssa_field_version``
        #: cell this builder posted (keyed by that cell's Ref).  The book row
        #: is the version's identity; this is the object it names, kept the
        #: way ``external_values`` keeps the objects graph ids name.
        self.field_version_values: dict[Any, SSAValue] = {}
        self.scalar_field_effect_destinations: dict[int, tuple[int, str]] = {}

        def index_scalar_field_effects(block: ControlBlock) -> None:
            if isinstance(block, ScalarFieldWriteBlock):
                if block.field_value_id is not None:
                    self.scalar_field_effect_destinations[
                        int(block.effect_node_id)
                    ] = (int(block.field_value_id), str(block.dtype))
                return
            if isinstance(block, SequenceBlock):
                children = block.blocks
            elif isinstance(block, ConditionalBlock):
                children = (block.body, *((block.orelse,) if block.orelse is not None else ()))
            elif isinstance(block, (LoopBlock, WhileBlock)):
                children = (block.body, *block.terminal_controls)
            elif isinstance(block, CallBlock):
                children = (block.callee,)
            elif isinstance(block, ResourceScopeBlock):
                children = (block.body, *block.cleanup)
            elif isinstance(block, ParallelDeployment):
                # ParallelDeployment.lanes are ControlBlocks, not deployment
                # descriptors with a body. The former access crashed even a
                # StatementBlock lane before any lowering could begin.
                children = tuple(block.lanes)
            elif isinstance(block, StateMachineTick):
                children = tuple(body for _case, body in block.cases)
                if block.default is not None:
                    children = (*children, block.default)
            else:
                children = ()
            for child in children:
                index_scalar_field_effects(child)

        index_scalar_field_effects(program.root)
        _alias_debug = os.environ.get("TURING_DEBUG_ALIAS_BINDING")
        if _alias_debug and _alias_debug in str(function_name):
            import traceback as _traceback

            class _TracedExternals(dict):
                def __setitem__(_self, key, value):
                    if value is not None and int(value.id) != int(key):
                        frames = _traceback.extract_stack(limit=6)[:-1]
                        print(
                            f"DEBUG-ALIAS-BINDING {function_name}: "
                            f"external_values[{key}] = value {int(value.id)} "
                            f"accounting={dict(value.accounting or {})} at "
                            + " <- ".join(f"{f.name}:{f.lineno}" for f in reversed(frames)),
                            file=sys.stderr, flush=True,
                        )
                    super().__setitem__(key, value)

            self.external_values = _TracedExternals()
        self.declared_parameter_only_ids: set[int] = set()
        self.validation_contracts: list[dict[str, object]] = []
        self.control_identity_receipts: list[tuple[int, int, str]] = []
        self.table_lookup_ownership_receipts: list[
            tuple[int, str, tuple[int, ...]]
        ] = []
        self.table_lookup_defaults = dict(table_lookup_defaults or {})
        # ``d[k]`` lookups (not ``d.get``): an absent key raises KeyError.
        self.table_lookup_required_ids = frozenset(
            map(int, table_lookup_required_ids)
        )
        self.lexical_table_lookup_result_ids = frozenset(map(
            int, lexical_table_lookup_result_ids,
        ))
        self.sequence_descriptors: dict[int, SSASequenceDescriptor] = {}
        self.source_sequence_column_dtypes = {
            int(sequence_id): tuple(map(str, dtypes))
            for sequence_id, dtypes in (sequence_column_dtypes or {}).items()
        }
        self.sequence_record_identities = {
            int(sequence_id): str(identity)
            for sequence_id, identity in (
                sequence_record_identities or {}
            ).items()
        }
        self.sequence_child_table_layouts = {
            int(sequence_id): (
                int(layout[0]), tuple(map(str, layout[1])),
                tuple(map(int, layout[2])), bool(layout[3]),
            )
            for sequence_id, layout in (
                sequence_child_table_layouts or {}
            ).items()
        }
        # Local sequences whose row count the graph's capacity survey could
        # not bound (``_static_sequence_capacity_survey``).  Their descriptor
        # is born DYNAMIC with a heap owner, never FIXED at an unproven size.
        self.dynamic_sequence_ids = frozenset(map(int, dynamic_sequence_ids))
        self.sequence_heap_owners: dict[int, SSAValue] = {}
        # Record-typed columns of fixed-width rows: (authored column,
        # identity, physical width) per resident sequence.
        self.sequence_row_record_slots = {
            int(sequence_id): tuple(
                (int(position), str(identity), int(width))
                for position, identity, width in slots
            )
            for sequence_id, slots in (
                sequence_row_record_slots or {}
            ).items()
        }
        self.resolved_sequence_schemas: dict[int, ResolvedSequenceSchema] = {
            int(sequence_id): schema
            for sequence_id, schema in (resolved_sequence_schemas or {}).items()
        }
        self.sequence_storage_values: dict[int, tuple[SSAValue, ...]] = {}
        self.sequence_status_values: dict[int, SSAValue] = {}
        self.sequence_helper_functions: dict[str, Function] = {}
        # Presence is the physical value of an optional resident sequence;
        # payload storage remains in the incumbent sequence descriptor.
        # Entries are installed only from SOURCE_OPTIONAL_GLYPH_CARRY cells.
        self.optional_glyph_presence_by_value: dict[int, SSAValue] = {}
        # ProgramABI optional scalar fields are a typed payload plus one
        # Boolean presence cell.  Control IR carries their exact relation so
        # a later union join can construct its semantic tag without treating
        # the inactive numeric filler as a Python object.
        self.optional_scalar_presence_by_payload: dict[int, SSAValue] = {}
        self.native_object_context = native_object_context
        self.native_object_module = native_object_module
        self.native_object_constructor_receipts = []
        self.native_object_context_used = False
        self.native_object_source_ids = set()
        self.native_object_type_tests = dict(native_object_type_tests or {})
        self.native_value_type_abi = _scoped_value_type_abi(
            self.lexical_read_scope, native_value_type_abi,
        )
        self.native_value_type_tests = dict(native_value_type_tests or {})
        self.sequence_column_type_abi: dict[
            tuple[int, int], ValueTypeABIFact
        ] = {}
        self._declare_sequence_column_type_abis()
        self.native_value_type_tags: dict[int, SSAValue] = {}
        self.native_type_tag_phi_by_payload: dict[int, Instr] = {}
        # A loop header is emitted before the body which defines its backedge.
        # Keep the exact companion objects reserved for that future definition,
        # just as ``lower_while`` already reserves the authored payload object.
        # They are definitions-in-waiting, not public ABI formals.
        self.pending_loop_native_type_tags: dict[int, SSAValue] = {}
        self.pending_loop_native_union_payloads: dict[
            int, dict[str, tuple[SSAValue, ...]]
        ] = {}
        self.pending_loop_native_union_injections: dict[int, list[tuple]] = {}
        self.native_value_union_payloads: dict[
            int, dict[str, tuple[SSAValue, ...]]
        ] = {}
        self.native_value_union_sequence_ids: dict[
            int, dict[str, int]
        ] = {}
        self.value_union_table = SSAValueUnionTable(owner=function_name)
        self.native_object_type_test_receipts = []
        self.native_object_requires_member_storage = False
        if native_object_context is not None:
            from .ssa_object_context import context_values
            for cell in context_values(native_object_context):
                self.region_value_meta[cell.id] = Meta(tuple(cell.shape), cell.dtype)
        # A locally authored ``list[bytes]`` has two physical views: the
        # logical outer row count and the flattened byte stream consumed by
        # ``b"".join``. This is the same composite ABI already used for a
        # parameter transformed through ``list(source)`` plus ``join``; the
        # companion is a compile-time storage artifact, not a Python object.
        self.joined_sequence_ids = set(map(int, joined_sequence_ids))
        self.joined_singleton_values = {
            int(sequence_id): int(value_id)
            for sequence_id, value_id in (
                joined_singleton_values or {}
            ).items()
        }
        self.joined_flat_sequence_ids: dict[int, int] = {}
        self.iterable_source_ids = {
            int(iterable_id)
            for iterable_id, _target_id, _induction
            in program.iterable_bindings
        }
        # Heterogeneous destructured rows are columnar at the repository ABI:
        # (resident source, projection) -> independently typed arena.  Column
        # zero retains the source identity; later columns receive fresh SSA
        # identities and share its extent.
        self.projected_row_columns: dict[tuple[int, int], SSAValue] = {}
        self.nested_row_target_ids = set(map(int, nested_row_target_ids))
        self.selected_nested_sequence_ids = set(map(
            int, selected_nested_sequence_ids
        ))
        self.variant_projected_target_ids = set(map(
            int, variant_projected_target_ids
        ))
        self.region_array_feed_ids = {
            int(region): set(map(int, value_ids))
            for region, value_ids in (region_array_feed_ids or {}).items()
        }
        self.nested_row_projections = tuple(
            (int(base), int(column), int(result), str(induction))
            for base, column, result, induction in nested_row_projections
        )
        self.variant_row_values: dict[int, SSAValue] = {}
        self.variant_handle_columns: dict[tuple[int, int], SSAValue] = {}
        # A heterogeneous sequence keeps its semantic payload column and its
        # authoritative VALUE_TYPE_ABI discriminant in parallel arenas.  The
        # key is the same exact (resident sequence, authored projection) used
        # by ``projected_row_columns``/``variant_handle_columns``.
        self.variant_type_tag_columns: dict[
            tuple[int, int], SSAValue
        ] = {}
        self.variant_type_payload_columns: dict[
            tuple[int, int, str], SSAValue
        ] = {}
        # An iterable element (or one projected field of a destructured row)
        # may itself be a sequence/record.  Its outer column stores an integer
        # child handle; caller-owned flattened arenas and strides turn that
        # handle into the row base passed to the consuming region.  The key
        # retains the exact authored source relationship instead of relying on
        # the target's spelling or inferred Python class.
        self.nested_child_rows: dict[
            tuple[str, int, int],
            tuple[SSAValue, SSAValue, SSAValue, SSAValue],
        ] = {}
        self.nested_row_selections: dict[
            int, tuple[SSAValue, SSAValue]
        ] = {}
        self.nested_iterable_targets = {
            int(iterable_id): int(target_id)
            for iterable_id, target_id, _induction in program.iterable_bindings
            if int(target_id) in self.nested_row_target_ids
        }
        self.child_table_selections: dict[
            int, tuple[SSAChildTablePoolDescriptor, SSAValue]
        ] = {}
        self.selected_child_extent_values: dict[int, SSAValue] = {}
        self.empty_default_child_ids: set[int] = set()
        self.child_selection_validity: dict[int, SSAValue] = {}
        self.active_child_selections: set[int] = set()
        # Exact loop-local element loads retained past loop-scope withdrawal.
        # The binding map correctly forgets a ``for`` target at loop exit,
        # but the child arena descriptor still needs the physical dtype proved
        # on that load while lowering the loop body.
        self.selected_child_element_values: list[
            tuple[SSAChildTablePoolDescriptor, int, SSAValue, int]
        ] = []
        self.table_region_operations = {
            int(region): tuple(operations)
            for region, operations in (table_region_operations or {}).items()
        }
        self.table_region_post_operations = {
            int(region): tuple(operations)
            for region, operations in (
                table_region_post_operations or {}
            ).items()
        }
        self.table_epilogue_operations = tuple(table_epilogue_operations)
        # A table store reports a full fixed-capacity table as status 2
        # in its status arena.  Only the structural resident table
        # integral publishes that arena to its host, whose verifier probes
        # the capacity-exhausted outcome; every other caller is compiled
        # code that never reads it, so the store must check it itself.
        self.host_reads_table_status = bool(host_reads_table_status)
        # A structural type predicate can be emitted before the numerical
        # region which owns its subject's sequence-row payload load. Keep the
        # exact scheduled projection addressable by result identity so the
        # predicate can load the parallel type tag at its own control point.
        self.sequence_row_load_operations: dict[int, tuple[Any, ...]] = {}
        for operations in (
            *self.table_region_operations.values(),
            *self.table_region_post_operations.values(),
            self.table_epilogue_operations,
        ):
            for kind, arguments in operations:
                if str(kind) not in {"row_load", "row_load_capture"}:
                    continue
                result_id = int(arguments[0])
                exact = tuple(arguments)
                incumbent = self.sequence_row_load_operations.get(result_id)
                if incumbent is not None and incumbent != exact:
                    raise ValueError(
                        "one sequence projection identity has two scheduled "
                        f"row loads: value={result_id}, "
                        f"first={incumbent!r}, second={exact!r}"
                    )
                self.sequence_row_load_operations[result_id] = exact
        # Program: ``xs[n - 1] if n > 0 else 0`` (a resident list).  Wrong
        # record: a row load is scheduled only by the region that owns its
        # ``Indexed`` instruction or that consumes its value; an IfExp arm
        # whose sole consumer is the merge Phi had neither, so the arm value
        # became an unaccounted formal and read 0.  Rule: a row load no
        # region schedules is emitted where its value is first asked for --
        # the arm, for a result alias -- as the sequence length already is.
        self.consumer_row_loads: dict[int, tuple[Any, ...]] = {
            int(result_id): tuple(operation)
            for result_id, operation in (consumer_row_loads or {}).items()
            if int(result_id) not in self.sequence_row_load_operations
        }
        # Program: ``xs = [3, n]; xs.append(2); a = xs[1]; xs.pop(1)`` then
        # ``a + len(xs)`` (scratch lp/c_v).  A consumer row load is emitted
        # where its value is first asked for; a later effect on the same
        # sequence (``sequence_read_before_effect_edges``) would then be
        # read through.  The read is loaded before that effect instead.
        self.effect_preceding_row_reads: dict[int, tuple[int, ...]] = {
            int(effect_id): tuple(map(int, reads))
            for effect_id, reads in (effect_preceding_row_reads or {}).items()
        }
        self.uniform_values: dict[str, SSAValue] = {}
        # Lexical control names (currently loop induction variables) are SSA
        # values too.  Keeping them here lets a StateMachineTick dispatch on
        # the surrounding loop without degrading that name to a symbolic
        # host-side load.
        self.local_control_values: dict[str, SSAValue] = {}
        self.loop_targets: list[tuple[BasicBlock, BasicBlock]] = []
        # Each active loop records the carried values visible on every direct
        # break edge.  A post-loop value is not always the header Phi: a break
        # can follow a carried update which has not traversed the latch yet.
        # The exit therefore needs its own edge-aware Phi.
        self.loop_exit_contexts: list[dict[str, Any]] = []
        # A source value may seed several logical loop bindings.  Conditional
        # alias publication must not overwrite one binding's update merely
        # because another binding assigned that value as its RHS.
        self.protected_loop_alias_sources: list[frozenset[int]] = []
        self.deployment_records: list[dict[str, Any]] = [
            {
                "region_id": int(region.region_id),
                "kind": str(region.kind),
                "schedule": str(region.schedule),
                "schedule_preference": str(region.schedule_preference),
                "lane_count": len(region.lanes),
                "iteration_space": region.iteration_space,
                "carried_aliases": tuple(region.carried_aliases),
                "recursion_region_id": region.recursion_region_id,
                "origin": str(region.origin),
                "source_loop_node_id": region.source_loop_node_id,
                "scale": int(region.scale),
                "join": region.join,
                "declared_lanes": tuple(region.lanes),
            }
            for region in program.deployment_regions
        ]
        deployment_ids = [
            int(record["region_id"]) for record in self.deployment_records
        ]
        if len(deployment_ids) != len(set(deployment_ids)):
            raise ValueError("control deployment region IDs must be unique")
        self.next_deployment_id = max(deployment_ids, default=-1) + 1
        self.declared_region_memberships: dict[
            int, list[tuple[int, int]]
        ] = {}
        for record in self.deployment_records:
            for lane in record["declared_lanes"]:
                for region_index in lane.region_indices:
                    self.declared_region_memberships.setdefault(
                        int(region_index), []
                    ).append((int(record["region_id"]), int(lane.index)))
        self.active_deployments: list[tuple[int, int]] = []
        self.recursion_regions = {
            int(region.region_id): {
                "kind": str(region.kind),
                "lower_as": str(region.lower_as),
                "control_ir": bool(region.control_ir),
                "members": tuple(map(int, region.members)),
                "control_members": tuple(map(
                    int, region.control_members
                )),
                "incoming": tuple(region.incoming),
                "outgoing": tuple(region.outgoing),
                "feedback": tuple(region.feedback),
            }
            for region in program.recursion_regions
        }
        self.ssa_recursion_table: dict[int, dict[str, Any]] = {}
        declared_sequence_ids = {
            int(declaration[0]) for declaration in sequence_declarations
        }
        for uniform in program.uniforms:
            value = SSAValue(
                int(uniform.value_id),
                dtype=str(uniform.dtype),
            )
            self.uniform_values[str(uniform.name)] = value
            # Program: ``def f(xs: list[int]): k = len(xs); for i in
            # range(k): ...`` (corpus c376, plan C19).  Wrong record: the
            # loop bound ``len(xs)`` was declared a uniform and bound as a
            # function input, so its first use never loaded the length; the
            # input had no caller value and was pruned, leaving the bound
            # undefined.  Rule: a uniform that is the recorded length of a
            # declared sequence is that sequence's length, loaded at its
            # first use (``external_value``), not an input.
            if int((sequence_length_values or {}).get(
                int(uniform.value_id), -1,
            )) in declared_sequence_ids:
                continue
            # UNIFORM: the control program's declared dtype for the uniform
            # (``control_uniform_dtype``, posted at entry) is the cause.
            self._bind(
                int(uniform.value_id), value, BindingKind.UNIFORM,
                self._declared_cell(
                    CONTROL_UNIFORM_DTYPE.name,
                    (str(self.tensor_shape_concordance_scope), int(uniform.value_id)),
                ),
            )
            self.arguments.append(value)
        # A source parameter is part of the authored function ABI even when
        # its only consumer is a PlanCall that will be materialized after all
        # method/control functions have been lowered.  Waiting for an ordinary
        # region/control use drops call-only parameters, leaving the later
        # static linker with an empty callee signature and no caller value to
        # bind.  Preserve the initial identity (the input before any authored
        # reassignment); sequence/table lowering may refine that same identity
        # to its richer storage contract below.
        for name in self.parameter_names:
            history = self.value_name_histories.get(str(name), ())
            if not history:
                continue
            value_id = int(history[0])
            if value_id in self.external_values:
                continue
            value = self._value_from_meta(value_id)
            # PARAMETER_SEED: the parameter's version-0 ``name_binding`` cell
            # is the cause; the seed is declared CALL_ONLY until a use.
            binding_cell = (
                None if self.lexical_read_scope is None
                else self._book().latest_ref(
                    NAME_BINDING, (self.lexical_read_scope, str(name), 0),
                )
            )
            self._bind(value_id, value, BindingKind.PARAMETER_SEED, binding_cell)
            self.declared_parameter_only_ids.add(value_id)
            self._declare_parameter(
                value_id, ParameterDeclaration.CALL_ONLY, binding_cell,
            )
            type_fact = self.native_value_type_abi.get(value_id)
            alternatives = tuple(
                type_fact.get("alternatives", ())
                if isinstance(type_fact, Mapping)
                else getattr(type_fact, "alternatives", ())
            )
            if len(alternatives) > 1:
                physical_alternatives = tuple(
                    type_fact.get("physical_alternatives", ())
                    if isinstance(type_fact, Mapping)
                    else getattr(type_fact, "physical_alternatives", ())
                )
                if tuple(
                    getattr(arm, "identity", None)
                    for arm in physical_alternatives
                ) != alternatives:
                    raise ValueError(
                        "native union parameter has no exact ordered physical "
                        f"arms: {name!r} {physical_alternatives!r}"
                    )
                arm_payloads = {}
                arm_sequences = {}
                deferred_union_publication = False
                material_arms = tuple(
                    arm for arm in physical_alternatives
                    if str(arm.storage) != "none"
                )
                shared_payload = bool(material_arms) and len({
                    (
                        str(arm.storage), str(arm.dtype),
                        tuple(arm.shape or ()), int(arm.rank),
                        tuple(arm.storage_identity or ()),
                    )
                    for arm in material_arms
                }) == 1 and all(
                    str(arm.storage) not in {"sequence", "record"}
                    for arm in material_arms
                )
                # The ``value_type_abi`` row the arms were read from: it is
                # a source of every physical fact posted below.
                type_abi_cell = (
                    None if self.lexical_read_scope is None
                    else self._book().latest_ref(
                        VALUE_TYPE_ABI,
                        (self.lexical_read_scope, value_id),
                    )
                )
                if shared_payload:
                    shared_arm = material_arms[0]
                    value.dtype = str(shared_arm.dtype or "unknown")
                    value.shape = tuple(shared_arm.shape or ())
                    # Program: a native union parameter whose material arms
                    # share one physical view (tests/
                    # test_precompile_contract_rows.py, ``test_union_
                    # parameter_arms_post_their_physical_view``).  Wrong
                    # record: the parameter's ``ssa_value`` row carried no
                    # storage/rank while accounting named the arm's storage.
                    # Rule: DERIVED from the ``value_type_abi`` row and the
                    # arm's source cells; accounting is then set FROM the
                    # posted fact.
                    self._revise_value(
                        value, type_abi_cell, binding_cell,
                        *shared_arm.source_cells,
                        physical={
                            "storage": str(shared_arm.storage),
                            "rank": int(shared_arm.rank),
                        },
                    )
                    value.accounting.update({
                        "native_value_union_shared_parameter": str(name),
                        "native_value_union_source_id": value_id,
                        "native_value_union_alternatives": alternatives,
                        "program_abi_parameter": str(name),
                        **self._posted_physical_accounting(
                            value, ("program_abi_storage",),
                        ),
                    })
                    self.arguments.append(value)
                for arm in physical_alternatives:
                    if str(arm.storage) == "none":
                        arm_payloads[str(arm.identity)] = ()
                        continue
                    if shared_payload:
                        arm_payloads[str(arm.identity)] = (value,)
                        continue
                    if str(arm.storage) == "sequence":
                        # The descriptor is materialized by the ordinary
                        # sequence-declaration pass below.  Retain the exact
                        # arm correlation now and publish the union after that
                        # pass, never as the parameter's shared scalar value.
                        arm_payloads[str(arm.identity)] = ()
                        arm_sequences[str(arm.identity)] = value_id
                        deferred_union_publication = True
                        continue
                    if str(arm.storage) == "record":
                        raise ValueError(
                            "native union parameter record arm lacks its "
                            "descriptor-backed side-by-side frame: "
                            f"{name!r} arm {arm.identity!r}"
                        )
                    # Program: a native union parameter with distinct
                    # physical arms (same test family).  Wrong record: the
                    # per-arm payload formal was minted with no physical
                    # fields although its arm declares storage and rank.
                    # Rule: the arm is read from the ``value_type_abi`` row,
                    # so the mint declares ``physical=`` from it, citing that
                    # row; accounting follows the posted fact.
                    payload = self.fresh_value(
                        dtype=str(arm.dtype or "unknown"),
                        shape=tuple(arm.shape or ()),
                        transform=REGION_FORMAL_SPLIT,
                        operands=(
                            value, binding_cell, type_abi_cell,
                            *arm.source_cells,
                        ),
                        physical={
                            "storage": str(arm.storage),
                            "rank": int(arm.rank),
                        },
                    )
                    payload.accounting.update({
                        "native_value_union_parameter": str(name),
                        "native_value_union_source_id": value_id,
                        "native_value_union_alternative": str(arm.identity),
                        **self._posted_physical_accounting(
                            payload, ("program_abi_storage",),
                        ),
                    })
                    self.arguments.append(payload)
                    arm_payloads[str(arm.identity)] = (payload,)
                self.native_value_union_payloads[value_id] = arm_payloads
                if arm_sequences:
                    self.native_value_union_sequence_ids[value_id] = (
                        arm_sequences
                    )
                tag = self.fresh_value(
                    dtype="int64", transform=REGION_FORMAL_SPLIT,
                    operands=(value, binding_cell),
                )
                tag.accounting.update({
                    "native_type_tag_for_value_id": value_id,
                    "native_type_tag_parameter": str(name),
                    "source_parameter": str(name),
                    "native_type_alternatives": alternatives,
                    "native_type_tags": tuple(
                        type_fact.get("tags", ())
                        if isinstance(type_fact, Mapping)
                        else getattr(type_fact, "tags", ())
                    ),
                })
                self.arguments.append(tag)
                self.native_value_type_tags[value_id] = tag
                value.accounting.update({
                    "native_type_tag_value_id": int(tag.id),
                    "native_type_alternatives": alternatives,
                })
                tag_cell = self._book().latest_ref(
                    SSA_VALUE, (self._scope(), int(tag.id)),
                )
                sources = self._cells(type_abi_cell, tag_cell, binding_cell)
                self._book().post(
                    VALUE_TYPE_TAG,
                    (self._scope(), value_id, int(tag.id)),
                    ValueTypeTagFact(
                        int(tag.id), alternatives,
                        tuple(tag.accounting["native_type_tags"]),
                    ),
                    stage=CONTROL_SSA_ENTRY,
                    provenance=Derived(sources), mode=Mode.CONCORD,
                )
                if not deferred_union_publication:
                    self.publish_native_value_union(value_id, tag, type_fact)
            else:
                self.arguments.append(value)
        signature_ids = {
            value_id
            for feeds, outputs in self.region_signatures.values()
            for value_id in (*feeds, *outputs)
        }
        # Descriptor cells and other compiler-minted storage must live above
        # the complete authored/control identity domain.  Reserving only the
        # numerical region signatures allowed a fresh sequence-length cell to
        # take (for example) ID 212 before the later control-generated
        # sequence carrying authored ID 212 was declared.  Same integer then
        # meant two physical values and made linked ABIs irreconcilable.
        reserved_control_ids = {
            *map(int, control_dependency_value_ids(program)),
            *(
                int(sequence_id)
                for sequence_id, _policy, _columns, _writable
                in sequence_declarations
            ),
        }
        self.sequence_length_values = {
            int(result_id): int(sequence_id)
            for result_id, sequence_id in (
                sequence_length_values or {}
            ).items()
        }
        # A specialized callee may receive a heterogeneous payload directly,
        # after its owning loop has already been split into the caller.  Such
        # a value still has two ABI columns: its authored scalar identity and
        # a separate row arena.  Projected loop bindings populate these later;
        # create only the unbound row columns here.
        projected_variant_targets = {
            int(target_id)
            for _iterable_id, target_id, _induction, _projection
            in program.projected_iterable_bindings
        }
        for value_id in sorted(
            self.variant_projected_target_ids - projected_variant_targets
        ):
            row = self.fresh_value(
                dtype=str(self._value_from_meta(value_id).dtype or "unknown"),
                transform=ROW_COLUMN_PROJECTION, operands=(int(value_id),),
            )
            row.accounting.update({
                "unbound_variant_source_id": int(value_id),
                "variant_column": "row",
            })
            self.arguments.append(row)
            self.variant_row_values[int(value_id)] = row
        # The loop target is the element contract for a resident iterable.
        # Empty Python aggregates carry no observation from which to infer an
        # element dtype and have historically defaulted to logical storage.
        # Bind the iterable's flat arena dtype to its exact target value before
        # lowering emits any indexed loads; shape remains the container shape.
        for iterable_id, target_id, _induction in program.iterable_bindings:
            target = self._value_from_meta(int(target_id))
            if target.dtype in {None, "", "unknown"}:
                continue
            iterable = self.external_value(int(iterable_id))
            iterable.dtype = target.dtype
            iterable.accounting = {
                **dict(iterable.accounting or {}),
                "iterable_element_dtype": str(target.dtype),
                "iterable_target_value_id": int(target_id),
            }
            # Program: ``def f(rows: list[list[float]]) -> float`` summing
            # ``for r in rows: for x in r``.  Wrong record: ``external_value``
            # posted the iterable's ``ssa_value`` row with dtype None (the
            # region meta had none), then this binding set float64 on the
            # object only; the settlement later read the row (None) against
            # the resident float64 and ``publish_ssa_value_type`` refused.
            # Rule: the dtype learned here is revised onto the value's row
            # DERIVED from the target's canonical cell it was read from, and
            # the binding follows the revision (as the REFINED branch of
            # ``external_value`` does).
            previous_binding = self._binding_cell(int(iterable_id))
            revised = self._revise_value(
                iterable, self._canonical_cell(int(target_id)),
            )
            self._bind(
                int(iterable_id), iterable, BindingKind.REFINED,
                previous_binding, revised,
            )
        self.current = self.new_block("entry")
        deletion_sequence_ids = {
            int(sequence_id)
            for _effect_id, _key_id, sequence_id, _storage_identity
            in table_deletions
            if sequence_id is not None
        }
        deletion_sequence_ids.update(map(int, retained_sequence_ids))
        nested_sequence_ids = set(map(int, nested_sequence_ids))
        nested_tensor_sequence_ids = set(map(
            int, nested_tensor_sequence_ids
        ))
        nested_value_dtypes: dict[int, str] = {}
        lookup_sequence_by_result = {
            int(result_id): int(sequence_id)
            for result_id, _query_id, sequence_id in table_lookups
        }
        element_bindings = (
            *program.iterable_bindings,
            *tuple(
                (iterable_id, target_id, induction)
                for iterable_id, target_id, induction, projection
                in program.projected_iterable_bindings
                if projection is None
            ),
        )
        for iterable_id, target_id, _induction in element_bindings:
            sequence_id = lookup_sequence_by_result.get(int(iterable_id))
            target_meta = self.region_value_meta.get(int(target_id))
            if sequence_id is not None and target_meta is not None:
                incoming_dtype = str(target_meta.dtype)
                incumbent_dtype = nested_value_dtypes.get(sequence_id)
                if (
                    incumbent_dtype is not None
                    and incumbent_dtype != incoming_dtype
                ):
                    raise ValueError(
                        "nested sequence element consumers disagree on "
                        "their physical dtype: "
                        f"sequence={sequence_id}, "
                        f"first={incumbent_dtype!r}, "
                        f"incoming={incoming_dtype!r}"
                    )
                nested_value_dtypes[sequence_id] = incoming_dtype
        from .identity_concordance import commit_sequence_contract

        def authored_sequence_mutations(
            block: ControlBlock,
        ) -> tuple[ControlSequenceMutation, ...]:
            """Return the exact resident effects carried by this control tree.

            Loop mutations and lexical mutation blocks are two placements of
            the same authored effect in some plans.  The ProcessGraph effect
            identity is therefore the deduplication key; encounter order is
            otherwise retained so conflicting contracts remain deterministic.
            """

            found: list[ControlSequenceMutation] = []
            seen_effects: set[tuple] = set()

            def visit(candidate: ControlBlock | None) -> None:
                if candidate is None:
                    return
                mutations: tuple[ControlSequenceMutation, ...] = ()
                if isinstance(candidate, SequenceMutationBlock):
                    mutations = (candidate.mutation,)
                elif isinstance(candidate, (LoopBlock, WhileBlock)):
                    mutations = tuple(candidate.sequence_mutations)
                for mutation in mutations:
                    # A display member's effect is (display, ordinal); its
                    # ``effect_node_id`` is the member producer, shared by
                    # every display that holds that value.
                    effect_id = (
                        int(mutation.effect_node_id),
                        mutation.display_member,
                    )
                    if effect_id not in seen_effects:
                        seen_effects.add(effect_id)
                        found.append(mutation)
                if isinstance(candidate, SequenceBlock):
                    for child in candidate.blocks:
                        visit(child)
                if isinstance(candidate, WhileBlock):
                    visit(candidate.condition)
                if isinstance(candidate, (ConditionalBlock, LoopBlock, WhileBlock)):
                    visit(candidate.body)
                if isinstance(candidate, ConditionalBlock):
                    visit(candidate.orelse)
                if isinstance(candidate, CallBlock):
                    visit(candidate.callee)

            visit(block)
            return tuple(found)

        control_mutations = authored_sequence_mutations(program.root)
        self.native_object_source_ids = set(map(int, native_object_value_ids)) | {
            int(mutation.sequence_value_id) for mutation in control_mutations
            if mutation.operator in {'object_construct', 'object_materialize'}}
        self.native_object_collections = dict(native_object_collections or {})
        self.native_object_collection_rows = {}

        static_sequence_capacities: dict[int, int] = {}

        def collect_static_sequence_capacities(
            block: ControlBlock | None,
        ) -> None:
            if block is None:
                return
            if isinstance(block, LoopBlock):
                try:
                    extent = len(range(
                        int(block.start), int(block.stop), int(block.step),
                    ))
                except (TypeError, ValueError, ZeroDivisionError):
                    extent = None
                if extent is not None:
                    for mutation in block.sequence_mutations:
                        sequence_id = int(mutation.sequence_value_id)
                        incumbent = static_sequence_capacities.get(sequence_id)
                        if incumbent is not None and incumbent != extent:
                            raise ValueError(
                                "one resident sequence has conflicting static "
                                f"producer extents: sequence={sequence_id} "
                                f"{incumbent} versus {extent}"
                            )
                        static_sequence_capacities[sequence_id] = extent
            if isinstance(block, SequenceBlock):
                for child in block.blocks:
                    collect_static_sequence_capacities(child)
            if isinstance(block, WhileBlock):
                collect_static_sequence_capacities(block.condition)
            if isinstance(block, (ConditionalBlock, LoopBlock, WhileBlock)):
                collect_static_sequence_capacities(block.body)
            if isinstance(block, ConditionalBlock):
                collect_static_sequence_capacities(block.orelse)
            if isinstance(block, CallBlock):
                collect_static_sequence_capacities(block.callee)

        collect_static_sequence_capacities(program.root)
        self.static_sequence_capacities = static_sequence_capacities

        # A list merged from branches is declared (it has a contract and
        # readers) but owns no storage: its descriptor members are Phis of
        # the arms' members, minted where the branches join
        # (``_lower_sequence_handle_merge``), not formals born here.
        handle_merge_ids: set[int] = set()

        def collect_handle_merges(block: ControlBlock | None) -> None:
            if block is None:
                return
            if isinstance(block, ConditionalBlock):
                handle_merge_ids.update(
                    int(merged) for merged in block.sequence_handle_results
                )
                collect_handle_merges(block.orelse)
            if isinstance(block, SequenceBlock):
                for child in block.blocks:
                    collect_handle_merges(child)
            if isinstance(block, WhileBlock):
                collect_handle_merges(block.condition)
            if isinstance(block, (ConditionalBlock, LoopBlock, WhileBlock)):
                collect_handle_merges(block.body)
            if isinstance(block, CallBlock):
                collect_handle_merges(block.callee)

        collect_handle_merges(program.root)

        for sequence_id, policy, column_count, writable in sequence_declarations:
            committed = commit_sequence_contract(
                function_name,
                int(sequence_id),
                str(policy),
                int(column_count),
                bool(writable),
                source="SSA sequence declaration",
                sources=(
                    self._canonical_cell(int(sequence_id))
                    or self._function_root(),
                ),
                stage=self._stage(),
            )
            if int(sequence_id) in handle_merge_ids:
                continue
            authored_column_dtypes = tuple(
                (sequence_column_dtypes or {}).get(int(sequence_id), ())
            )
            column_dtypes: list[str | None] = [
                authored_column_dtypes[column]
                if column < len(authored_column_dtypes) else None
                for column in range(int(column_count))
            ]
            column_shapes: list[tuple[int, ...]] = [
                () for _column in range(int(column_count))
            ]
            row_layout = committed_sequence_row_layout(
                self.shape_scope, int(sequence_id),
            )
            if row_layout is not None:
                if len(row_layout.column_shapes) != int(column_count):
                    raise ValueError(
                        "sequence row layout width disagrees with its "
                        f"physical contract in {function_name}: sequence "
                        f"{int(sequence_id)} has "
                        f"{len(row_layout.column_shapes)} layout column(s) "
                        f"and {int(column_count)} physical column(s)"
                    )
                column_shapes[:] = row_layout.column_shapes
                for column, dtype in enumerate(row_layout.column_dtypes):
                    if column_dtypes[column] in {None, "unknown"}:
                        column_dtypes[column] = dtype
            # A retained comprehension appends the numerical value produced
            # by its body.  That exact mutation edge owns the shape of one
            # resident row; the sequence handle is not the row and must not
            # inherit the row shape as its complete extent.  The shape proof
            # is an identity-book fact produced by the source transformation
            # graph.  Do not reconstruct it from ``region_value_meta``: that
            # id-keyed summary is a stage-local second key and was precisely
            # how a proven ``(3,)`` reduction result became a scalar row here.
            for mutation in control_mutations:
                if (
                    int(mutation.sequence_value_id) != int(sequence_id)
                    or str(mutation.operator) not in {"append", "add"}
                    or len(tuple(mutation.argument_value_ids))
                    != int(column_count)
                ):
                    continue
                for column, argument_id in enumerate(
                    mutation.argument_value_ids
                ):
                    row_contract = proven_shape_contract_of(
                        self.shape_scope, int(argument_id),
                    )
                    if row_contract is None:
                        continue
                    proposed_shape, proposed_dtype = row_contract
                    incumbent_shape = column_shapes[column]
                    if incumbent_shape and incumbent_shape != proposed_shape:
                        self.shortfalls.append(SSALoweringShortfall(
                            "ssa-sequence", "conflicting-row-shape",
                            f"{function_name}.sequence_declaration",
                            f"sequence value {int(sequence_id)} column "
                            f"{column} receives both {incumbent_shape!r} "
                            f"and {proposed_shape!r}",
                        ))
                        continue
                    column_shapes[column] = proposed_shape
                    if column_dtypes[column] in {None, "unknown"}:
                        column_dtypes[column] = str(proposed_dtype)
            for _result_id, query_id, lookup_sequence_id in table_lookups:
                if int(lookup_sequence_id) != int(sequence_id):
                    continue
                query_ids = query_id if isinstance(query_id, tuple) else (query_id,)
                for column, query_value_id in enumerate(query_ids):
                    meta = self.region_value_meta.get(int(query_value_id))
                    if meta is not None and column < len(column_dtypes) and column_dtypes[column] in {None, "unknown"}:
                        column_dtypes[column] = str(meta.dtype)
            for _effect_id, key_id, value_id, store_sequence_id in table_stores:
                if int(store_sequence_id) != int(sequence_id):
                    continue
                key_ids = key_id if isinstance(key_id, tuple) else (key_id,)
                for column, key_value_id in enumerate(key_ids):
                    meta = self.region_value_meta.get(int(key_value_id))
                    if meta is not None and column < len(column_dtypes) and column_dtypes[column] in {None, "unknown"}:
                        column_dtypes[column] = str(meta.dtype)
                value_meta = self.region_value_meta.get(int(value_id))
                if value_meta is not None and column_dtypes and column_dtypes[-1] in {None, "unknown"}:
                    column_dtypes[-1] = str(value_meta.dtype)
            self._sequence_descriptor(
                int(sequence_id),
                policy=committed.policy,
                writable=committed.writable,
                location=f"{function_name}.sequence_declaration",
                column_count=committed.column_count,
                retains_deleted_rows=int(sequence_id) in deletion_sequence_ids,
                nested_table=int(sequence_id) in nested_sequence_ids,
                nested_tensor=(
                    int(sequence_id) in nested_tensor_sequence_ids
                ),
                nested_value_dtype=nested_value_dtypes.get(int(sequence_id)),
                element_dtype=(
                    "int" if int(sequence_id) in self.joined_sequence_ids
                    else None
                ),
                column_dtypes=tuple(column_dtypes),
                column_shapes=tuple(column_shapes),
            )
        # Sequence arms were correlated when their semantic parameter was
        # declared, but their authoritative descriptor rows only exist after
        # the ordinary sequence-declaration pass above.  Publish those unions
        # now from that descriptor-backed storage.
        for value_id, arm_sequences in tuple(
            self.native_value_union_sequence_ids.items()
        ):
            if self.value_union_table.by_id(int(value_id)) is not None:
                continue
            if any(
                int(sequence_id) not in self.sequence_descriptors
                for sequence_id in arm_sequences.values()
            ):
                raise ValueError(
                    "native union sequence parameter has no exact resident "
                    f"descriptor: value={int(value_id)}, arms={arm_sequences!r}"
                )
            tag = self.native_value_type_tags.get(int(value_id))
            fact = self.native_value_type_abi.get(int(value_id))
            if tag is None or fact is None:
                raise ValueError(
                    "native union sequence parameter lost its ABI/tag "
                    f"correlation: value={int(value_id)}"
                )
            for identity, sequence_id in arm_sequences.items():
                descriptor = self.sequence_descriptors[int(sequence_id)]
                signature = self._native_union_sequence_signature(descriptor)
                for member_position, member in enumerate(
                    self._native_union_sequence_values(int(sequence_id))
                ):
                    if all(
                        int(argument.id) != int(member.id)
                        for argument in self.arguments
                    ):
                        self.arguments.append(member)
                    member.accounting = {
                        **dict(member.accounting or {}),
                        "native_value_union_alternative": str(identity),
                        "native_value_union_source_id": int(value_id),
                        "native_value_union_sequence_id": int(sequence_id),
                        "native_value_union_sequence_member": int(
                            member_position
                        ),
                        "native_value_union_sequence_signature": signature,
                    }
            self.publish_native_value_union(int(value_id), tag, fact)

        # Caller-provided arrays are the physical frame for both authored
        # inputs and compiler locals.  Their logical lifetimes are different:
        # retained source sequences arrive populated, while a writable local
        # (for example ``out = bytearray()``) is newly empty on every function
        # invocation even when its storage frame is reused by a linked caller.
        retained_residents = {
            *map(int, retained_sequence_ids),
            *map(int, source_sequence_ids),
        }
        for sequence_id, descriptor in sorted(self.sequence_descriptors.items()):
            if not descriptor.writable or int(sequence_id) in retained_residents:
                continue
            length_cell = self.sequence_storage_values[int(sequence_id)][
                len(descriptor.column_value_ids)
            ]
            zero_index = self.constant_value(0, length_cell)
            zero_length = self.constant_value(0, length_cell)
            length_address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(length_cell,),
            )
            self.emit(
                Handler.GetElementPtr,
                [length_cell, zero_index],
                length_address,
                attributes={"binding": "ssa_local_sequence_length"},
            )
            self.emit(
                Handler.Store, [zero_length, length_address],
                attributes={
                    "binding": "ssa_local_sequence_initialize",
                    "sequence_id": int(sequence_id),
                },
            )
        for sequence_id in sorted(self.joined_sequence_ids):
            if int(sequence_id) not in self.sequence_descriptors:
                continue
            # The flat view's sequence id is a compiler-minted identity: mint
            # it through the book from the joined sequence's own cell.
            flat_sequence_id = int(self.fresh_value(
                dtype="int", transform=DESCRIPTOR_CELL,
                operands=(int(sequence_id), self._sequence_contract_cell(int(sequence_id))),
            ).id)
            flat = self._sequence_descriptor(
                flat_sequence_id,
                policy="duplicates",
                writable=True,
                location=f"{function_name}.joined_sequence_flat_view",
                element_dtype="int",
            )
            if flat is None:
                continue
            self.joined_flat_sequence_ids[int(sequence_id)] = flat_sequence_id
            flat_length = self.sequence_storage_values[flat_sequence_id][
                len(flat.column_value_ids)
            ]
            flat_length_address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(flat_length,),
            )
            self.emit(
                Handler.GetElementPtr,
                [flat_length, self.constant_value(0, flat_length)],
                flat_length_address,
                attributes={"binding": "ssa_joined_sequence_length"},
            )
            self.emit(
                Handler.Store,
                [self.constant_value(0), flat_length_address],
                attributes={"binding": "ssa_joined_sequence_initialize"},
            )
        for sequence_id, policy, column_count in sequence_initializations:
            literal_table_rows = None
            descriptor_policy = (
                "duplicates"
                if str(policy).startswith((
                    "fill=", "literal_bytes=", "literal_glyphs=",
                    "literal_rows=",
                ))
                else "unique"
                if str(policy).startswith("literal_table=")
                else str(policy)
            )
            element_dtype = None
            if str(policy).startswith("fill=") and ";count=" in str(policy):
                fill_literal = ast.literal_eval(
                    str(policy).split(";", 1)[0].split("=", 1)[1]
                )
                if isinstance(fill_literal, bool):
                    element_dtype = "bool"
                elif type(fill_literal) is int:
                    from ..transmogrifier.dtype_layout import (
                        python_int_literal_dtype,
                    )

                    element_dtype = python_int_literal_dtype(fill_literal)
                elif isinstance(fill_literal, float):
                    element_dtype = "float64"
                else:
                    element_dtype = "int64" if fill_literal is None else None
                if isinstance(fill_literal, tuple):
                    # Program: ``xs = [n] * 3; xs[1] = 3``.  Wrong record:
                    # a runtime member left the rows unclassed, so the
                    # control function stored them float64 while every
                    # region read them int64.  Rule: the rows hold the class
                    # the regions prove for the sequence, else the member's.
                    proven = (
                        self.region_value_meta.get(int(sequence_id))
                        or self.region_value_meta.get(int(fill_literal[1]))
                    )
                    if proven is not None:
                        element_dtype = str(proven.dtype)
            elif str(policy).startswith("literal_bytes="):
                element_dtype = "int"
            elif str(policy).startswith("literal_glyphs="):
                element_dtype = "int64"
            column_dtypes = None
            if str(policy).startswith(("literal_table=", "literal_rows=")):
                literal_table_rows = tuple(ast.literal_eval(
                    str(policy).split("=", 1)[1]
                ))
                columns = tuple(zip(*literal_table_rows)) if literal_table_rows else ()
                def literal_column_dtype(column):
                    if all(isinstance(value, bool) for value in column):
                        return "bool"
                    if all(type(value) is int for value in column):
                        from ..transmogrifier.dtype_layout import (
                            common_integer_dtype, python_int_literal_dtype,
                        )

                        return common_integer_dtype(tuple(
                            python_int_literal_dtype(value)
                            for value in column
                        )) or "unknown"
                    if all(
                        isinstance(value, (int, float))
                        and not isinstance(value, bool)
                        for value in column
                    ):
                        return "float64"
                    return "unknown"

                column_dtypes = tuple(
                    literal_column_dtype(column) for column in columns
                ) or None
            descriptor = self._sequence_descriptor(
                int(sequence_id),
                policy=descriptor_policy,
                writable=True,
                location=f"{function_name}.sequence_initialization",
                column_count=int(column_count),
                retains_deleted_rows=int(sequence_id) in deletion_sequence_ids,
                nested_table=int(sequence_id) in nested_sequence_ids,
                nested_tensor=(
                    int(sequence_id) in nested_tensor_sequence_ids
                ),
                nested_value_dtype=nested_value_dtypes.get(int(sequence_id)),
                element_dtype=element_dtype,
                column_dtypes=column_dtypes,
            )
            if descriptor is None:
                continue
            length_cell = self.sequence_storage_values[int(sequence_id)][
                len(descriptor.column_value_ids)
            ]
            zero = self.constant_value(0, length_cell)
            zero_index = self.constant_value(0, length_cell)
            length_address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(length_cell,),
            )
            self.emit(
                Handler.GetElementPtr,
                [length_cell, zero_index],
                length_address,
                attributes={"binding": "ssa_sequence_length"},
            )
            self.emit(
                Handler.Store,
                [zero, length_address],
                attributes={"binding": "ssa_sequence_initialize_length"},
            )
            if str(policy).startswith("literal_glyphs="):
                glyphs = tuple(ast.literal_eval(
                    str(policy).split("=", 1)[1]
                ))
                glyph_column = self.sequence_storage_values[
                    int(sequence_id)
                ][0]
                for offset, glyph in enumerate(glyphs):
                    index = self.constant_value(int(offset), glyph_column)
                    address = self.fresh_value(
                        dtype="ptr", transform=ADDRESS,
                        operands=(glyph_column, index),
                    )
                    self.emit(
                        Handler.GetElementPtr,
                        [glyph_column, index],
                        address,
                        attributes={"binding": "ssa_sequence_literal_glyph"},
                    )
                    value = self.fresh_value(
                        dtype="int64", transform=CONTROL_CONST,
                        operands=(address,),
                    )
                    self.emit(
                        Handler.Const, [], value,
                        attributes={"value": int(glyph)},
                    )
                    self.emit(
                        Handler.Store, [value, address],
                        attributes={"binding": "ssa_sequence_literal_glyph"},
                    )
                self.emit(
                    Handler.Store,
                    [self.constant_value(len(glyphs), length_cell), length_address],
                    attributes={"binding": "ssa_sequence_literal_glyph_length"},
                )
            elif str(policy).startswith(("literal_table=", "literal_rows=")):
                # ``literal_rows=`` is the duplicates-policy twin of a
                # compile-time table: a list whose rows are proven literals
                # with no other writer (a folded slice, see fortran_c_shell).
                rows = literal_table_rows or ()
                if any(len(tuple(row)) != len(descriptor.column_value_ids)
                       for row in rows):
                    self.shortfalls.append(SSALoweringShortfall(
                        "ssa-sequence", "literal-table", self.function_name,
                        f"table {sequence_id} rows do not match its columns",
                    ))
                    continue
                for offset, row in enumerate(rows):
                    index = self.constant_value(int(offset), length_cell)
                    for column, literal in enumerate(tuple(row)):
                        column_cell = self.sequence_storage_values[
                            int(sequence_id)
                        ][column]
                        address = self.fresh_value(
                            dtype="ptr", transform=ADDRESS,
                            operands=(column_cell, index),
                        )
                        self.emit(
                            Handler.GetElementPtr,
                            [column_cell, index],
                            address,
                            attributes={
                                "binding": "ssa_sequence_literal_table"
                            },
                        )
                        value = self.fresh_value(
                            dtype=descriptor.column_dtypes[column],
                            transform=CONTROL_CONST, operands=(address,),
                        )
                        self.emit(
                            Handler.Const, [], value,
                            attributes={"value": literal},
                        )
                        self.emit(
                            Handler.Store, [value, address],
                            attributes={
                                "binding": "ssa_sequence_literal_table"
                            },
                        )
                self.emit(
                    Handler.Store,
                    [self.constant_value(len(rows), length_cell), length_address],
                    attributes={
                        "binding": "ssa_sequence_literal_table_length"
                    },
                )
            elif str(policy).startswith("literal_bytes="):
                payload = bytes.fromhex(str(policy).split("=", 1)[1])
                byte_column = self.sequence_storage_values[int(sequence_id)][0]
                for offset, byte in enumerate(payload):
                    index = self.constant_value(int(offset), byte_column)
                    address = self.fresh_value(
                        dtype="ptr", transform=ADDRESS,
                        operands=(byte_column, index),
                    )
                    self.emit(
                        Handler.GetElementPtr,
                        [byte_column, index],
                        address,
                        attributes={"binding": "ssa_sequence_literal_bytes"},
                    )
                    value = self.fresh_value(
                        dtype="int", transform=CONTROL_CONST, operands=(address,),
                    )
                    self.emit(
                        Handler.Const,
                        [],
                        value,
                        attributes={"value": int(byte)},
                    )
                    self.emit(
                        Handler.Store,
                        [value, address],
                        attributes={"binding": "ssa_sequence_literal_bytes"},
                    )
                count = self.constant_value(len(payload))
                self.emit(
                    Handler.Store,
                    [count, length_address],
                    attributes={"binding": "ssa_sequence_literal_length"},
                )
        # The tables a keyed ``del`` clears rows of (their live flags then
        # mark deleted rows, not only the rows a filtered loop kept).
        self.keyed_deletion_sequence_ids = {
            int(deletion[2]) for deletion in table_deletions
            if deletion[2] is not None
        }
        self.lexical_membership_arguments: dict[int, tuple[Any, ...]] = {}
        self._captured_instruction_sink: list[Instr] | None = None
        lexical_membership_ids = {
            int(query.result_value_id)
            for query in self._walk_sequence_queries(program.root)
            if query.operation == "membership"
        }
        for result_id, query_id, sequence_id, negate in sequence_memberships:
            # Program: ``for k in range(4): if k in d: ...`` (scratch c202).
            # Wrong record: a lexical membership's instructions were built
            # here, at function entry, and replayed at the query; its key
            # ``k`` was read at entry, outside its loop, and became a root
            # input.  Rule: a lexical membership is built where its query is
            # lowered; only an entry-resident one is built here.
            if int(result_id) in lexical_membership_ids:
                self.lexical_membership_arguments[int(result_id)] = (
                    result_id, query_id, sequence_id, negate,
                )
                continue
            self._emit_sequence_membership(
                result_id, query_id, sequence_id, negate,
            )
        scheduled_table_operations = {
            (
                "lookup" if str(kind) == "lookup_capture" else str(kind),
                tuple(operation),
            )
            # Program: ``d[3] = n; d[1] += 5`` then reads (scratch c201).
            # Wrong record: operations a region schedules AFTER its call
            # (``table_region_post_operations``) were not counted as
            # scheduled, so this prologue emitted them a second time before
            # the table existed (a store read its value before definition).
            # Rule: an operation any region schedules is scheduled.
            for operations in (
                *self.table_region_operations.values(),
                *self.table_region_post_operations.values(),
                self.table_epilogue_operations,
            )
            for kind, operation in operations
        }
        # A keyed delete placed as its own control effect (a table-delete
        # mutation anywhere in the control tree) is scheduled there, not here.
        placed_delete_ids = _control_placed_table_delete_ids(program.root)
        scheduled_table_operations.update(
            ("delete", tuple(deletion)) for deletion in table_deletions
            if int(deletion[0]) in placed_delete_ids
        )
        for result_id, query_id, sequence_id in table_lookups:
            if int(result_id) in self.lexical_table_lookup_result_ids:
                continue
            if ("lookup", (result_id, query_id, sequence_id)) in scheduled_table_operations:
                continue
            # A whole-program shell graph shows every linked frame's nodes,
            # so a lookup can be recorded here whose result this function
            # never consumes -- it is a callee's operation.  Emitting it
            # anyway materialized its operands as id()-carrying arguments
            # (dead code by definition: real value ids are monotonic), which
            # displaced the frame's positional public-span correlation.  The
            # The owner is the function whose regions or explicitly bound
            # source calls consume the result.  A lookup used only as a call
            # argument has no numerical-region metadata, but the plan binding
            # is equally exact local provenance.
            callsite_owners = self.plan_callsites_by_argument.get(
                int(result_id), ()
            )
            if (
                int(result_id) not in self.region_value_meta
                and not callsite_owners
            ):
                continue
            ownership = "region"
            owner_ids: tuple[int, ...] = ()
            if callsite_owners:
                ownership = "source_call"
                owner_ids = tuple(map(int, callsite_owners))
            self.table_lookup_ownership_receipts.append((
                int(result_id), ownership, owner_ids,
            ))
            self._emit_table_lookup(
                result_id, query_id, sequence_id,
                ownership=ownership,
                owner_ids=owner_ids,
            )
        for effect_id, key_id, value_id, sequence_id in table_stores:
            if ("store", (effect_id, key_id, value_id, sequence_id)) in scheduled_table_operations:
                continue
            self._emit_table_store(effect_id, key_id, value_id, sequence_id)
        for effect_id, key_id, sequence_id, storage_identity in table_deletions:
            if ("delete", (effect_id, key_id, sequence_id, storage_identity)) in scheduled_table_operations:
                continue
            self._emit_table_delete(effect_id, key_id, sequence_id, storage_identity)
        self.active_stage = CONTROL_SSA

    def _emit_sequence_membership(
        self, result_id: int, query_id: Any, sequence_id: int, negate: bool,
    ) -> None:
        """Emit one resident membership test at the current position."""

        descriptor = self.sequence_descriptors.get(int(sequence_id))
        query_ids = (
            tuple(map(int, query_id))
            if isinstance(query_id, tuple)
            else (int(query_id),)
        )
        logical_query_values = tuple(
            self._table_query_values(query_id, descriptor)
        )
        query_values = list(logical_query_values)
        tag_columns = self.sequence_native_type_tag_columns(
            int(sequence_id)
        ) if descriptor is not None else {}
        physical_descriptor = descriptor
        physical_columns = []
        if descriptor is not None and tag_columns:
            union_columns = self.sequence_native_value_union_columns(
                int(sequence_id)
            )
            physical_dtypes = []
            physical_shapes = []
            physical_keys = []
            physical_queries = []
            key_ordinal = {
                int(column): ordinal for ordinal, column in enumerate(
                    descriptor.key_columns or (
                        (0,)
                        if len(descriptor.column_value_ids) == 1 else ()
                    )
                )
            }
            logical_shapes = tuple(descriptor.column_shapes or (
                () for _value in descriptor.column_value_ids
            ))
            for column, (column_id, dtype, shape) in enumerate(zip(
                descriptor.column_value_ids,
                descriptor.column_dtypes,
                logical_shapes,
                strict=True,
            )):
                tagged = tag_columns.get(int(column))
                if tagged is None:
                    physical_index = len(physical_columns)
                    physical_columns.append(
                        self.sequence_storage_values[int(sequence_id)][
                            int(column)
                        ]
                    )
                    physical_dtypes.append(str(dtype))
                    physical_shapes.append(tuple(shape))
                    if int(column) in key_ordinal:
                        ordinal = key_ordinal[int(column)]
                        physical_keys.append(physical_index)
                        physical_queries.append(
                            logical_query_values[ordinal]
                        )
                    continue
                tag_column, _target_id, fact = tagged
                query_arm_values = ()
                query_tag = None
                if int(column) in key_ordinal:
                    ordinal = key_ordinal[int(column)]
                    if ordinal >= len(query_ids):
                        raise ValueError(
                            "native sequence membership tag has no "
                            "matching authored query component: "
                            f"sequence={int(sequence_id)}, "
                            f"column={column}, query={query_ids!r}"
                        )
                    authored_query_id = int(query_ids[ordinal])
                    query_arm_values = (
                        self._native_value_union_row_payloads(
                            authored_query_id,
                            logical_query_values[ordinal], fact,
                        )
                    )
                    query_tag = self.native_type_tag_for(
                        authored_query_id, fact,
                    )
                    if query_tag is None:
                        raise ValueError(
                            "native sequence membership query has no "
                            "exact type evidence: "
                            f"sequence={int(sequence_id)}, "
                            f"column={column}, value={authored_query_id}"
                        )
                for arm_index, (arm, arm_column) in enumerate(
                    union_columns[int(column)]
                ):
                    physical_index = len(physical_columns)
                    physical_columns.append(arm_column)
                    physical_dtypes.append(str(
                        arm_column.dtype or "unknown"
                    ))
                    physical_shapes.append(tuple(
                        arm_column.shape or ()
                    ))
                    if int(column) in key_ordinal:
                        physical_keys.append(physical_index)
                        physical_queries.append(
                            query_arm_values[arm_index]
                        )
                physical_index = len(physical_columns)
                physical_columns.append(tag_column)
                physical_dtypes.append("int64")
                physical_shapes.append(())
                if int(column) in key_ordinal:
                    physical_keys.append(physical_index)
                    physical_queries.append(query_tag)
            physical_descriptor = replace(
                descriptor,
                column_value_ids=tuple(
                    int(value.id) for value in physical_columns
                ),
                column_dtypes=tuple(physical_dtypes),
                column_shapes=tuple(physical_shapes),
                key_columns=tuple(physical_keys),
            )
            query_values = physical_queries
        membership_columns = (
            () if physical_descriptor is None else
            tuple(physical_descriptor.key_columns) or (
                (0,)
                if len(physical_descriptor.column_value_ids) == 1 else ()
            )
        )
        if (
            physical_descriptor is None
            or not membership_columns
            or len(query_values) != len(membership_columns)
        ):
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence",
                "contains",
                f"{self.function_name}.sequence_membership[{result_id}]",
                "membership requires one exact query component per "
                "key/value membership column",
            ))
            return
        from .ir_sequence_tables import lower_sequence_contains

        helper_name = self._sequence_helper_name(
            int(sequence_id), "contains",
        )
        lowering = lower_sequence_contains(
            physical_descriptor,
            function_name=helper_name,
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        self._register_sequence_lowering(lowering)
        contract_cell = self._sequence_contract_cell(int(sequence_id))
        call_result = (
            self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(*query_values, contract_cell),
            )
            if negate else SSAValue(int(result_id), dtype="bool")
        )
        if not negate:
            self._bind(
                int(result_id), call_result, BindingKind.SEQUENCE_RESULT,
                *query_values, contract_cell,
            )
        self.emit(
            Handler.Call,
            [
                *(physical_columns if tag_columns else
                  self.sequence_storage_values[int(sequence_id)][
                      :len(descriptor.column_value_ids)
                  ]),
                *self.sequence_storage_values[int(sequence_id)][
                    len(descriptor.column_value_ids):
                ],
                *query_values,
            ],
            call_result,
            attributes={
                "callee": helper_name,
                "source_linked": True,
                "ssa_sequence_operation": "contains",
                "sequence_id": int(sequence_id),
            },
        )
        if negate:
            result = SSAValue(int(result_id), dtype="bool")
            self._bind(
                int(result_id), result, BindingKind.SEQUENCE_RESULT,
                call_result,
            )
            self.emit(Handler.LNot, [call_result], result)

    def _sequence_helper_name(
        self, sequence_id: int, operation: str, *related_ids: int,
    ) -> str:
        """Name function-local sequence storage in the repository namespace.

        Sequence identities are deliberately local to one lowered function.
        Their helper symbols therefore have to retain that owner identity too;
        spelling only the numeric id lets an unrelated function's helper
        overwrite this one when the per-function modules are assembled.
        """

        suffix = "".join(f"_{int(value_id)}" for value_id in related_ids)
        return (
            f"{self.function_name}__ssa_sequence_{int(sequence_id)}_"
            f"{operation}{suffix}"
        )

    def _table_query_values(
        self, query_ids: int | tuple[int, ...], descriptor: Any = None,
    ) -> tuple[SSAValue, ...]:
        values = tuple(
            self.external_value(int(value_id))
            for value_id in (
                query_ids if isinstance(query_ids, tuple) else (query_ids,)
            )
        )
        if descriptor is None:
            return values
        key_columns = tuple(map(int, descriptor.key_columns))
        if len(values) != len(key_columns):
            return values
        converted = []
        for value, column in zip(values, key_columns, strict=True):
            expected = str(descriptor.column_dtypes[column])
            accounting = dict(value.accounting or {})
            if (
                str(value.dtype) == "opaque_ref"
                and expected in {"int", "int32", "int64"}
            ):
                # The value's ``opaque_ref`` dtype is already the settled
                # fixed-width native reference ABI.  Program-ABI accounting
                # is attached later while linked frames are reconciled, so it
                # cannot be required here (units 027/030 reached this point
                # with only their exact source class).  The table descriptor
                # owns the integer key representation.  Convert that native
                # word explicitly; no Python object or runtime inspection is
                # involved.
                # Program: a table lookup/store keyed by an ``opaque_ref``
                # (tests/test_ir_sequence_tables::test_static_program_
                # reference_is_typed_ssa_and_native_handle_storage).  Wrong
                # record: the cast result carried scalar/rank 0 only in
                # accounting.  Rule: the cast's result IS a fixed-width
                # native word, scalar by construction, so that literal is the
                # DECLARATION of the construct and is posted Novel at the
                # mint (``physical=``); accounting is set from the fact.
                handle = self.fresh_value(
                    dtype=expected,
                    transform=CONTROL_EXPRESSION,
                    operands=(value,),
                    physical={"storage": "scalar", "rank": 0},
                )
                handle.accounting.update({
                    "native_reference_handle_for_value_id": int(value.id),
                    **self._posted_physical_accounting(handle),
                })
                self.emit(
                    Handler.Cast, [value], handle,
                    attributes={
                        "reference_cast": True,
                        "binding": "opaque_reference_identity",
                        "sequence_key_column": int(column),
                    },
                )
                converted.append(handle)
            else:
                converted.append(value)
        return tuple(converted)

    def _emit_table_lookup(
        self, result_id: int, query_id: int | tuple[int, ...], sequence_id: int,
        *, ownership: str = "scheduled", owner_ids: tuple[int, ...] = (),
    ) -> None:
        if int(sequence_id) in self.native_object_source_ids:
            keys = query_id if isinstance(query_id, tuple) else (query_id,)
            if len(keys) != 1:
                raise ValueError('native object member lookup requires one reference key')
            self._emit_native_object_operation('get', int(sequence_id), tuple(keys), int(result_id))
            return
        descriptor = self.sequence_descriptors.get(int(sequence_id))
        if descriptor is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-table", "lookup", self.function_name,
                f"table {sequence_id} has no sequence descriptor",
            ))
            return
        from .ir_sequence_tables import lower_table_lookup

        default_literal = self.table_lookup_defaults.get(int(result_id))
        empty_default = isinstance(default_literal, tuple) and not default_literal
        if empty_default:
            default_literal = None
            if int(result_id) in self.region_value_meta:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-table", "optional-child-index", self.function_name,
                    "an empty-default child lookup needs exact presence and bounds proof before indexed region use",
                ))
                return
        # Program: ``d = {1: n, 2: 5}; return d[n]`` with ``n = 7`` (silent
        # lane, scratch s43/k).  Wrong record: the lookup's absent branch
        # returned 0 where Python raises KeyError (clean audit).  Rule: an
        # authored subscript read requires its key; its helper raises
        # validation error 84 (``required_key_absent``) on the absent path.
        # ``d.get`` keeps its default (or zero) branch.
        required = (
            default_literal is None
            and int(result_id) in self.table_lookup_required_ids
        )
        helper_name = self._sequence_helper_name(
            int(sequence_id),
            "lookup_or_default" if default_literal is not None
            else "lookup_required" if required else "lookup",
        )
        lowering = lower_table_lookup(
            descriptor,
            function_name=helper_name,
            default_parameter=default_literal is not None,
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
            required=required,
        )
        self._register_sequence_lowering(lowering)
        pool = descriptor.child_table_pool
        tensor_child = bool(
            pool is not None
            and pool.shape_value_id is not None
            and pool.rank_value_id is not None
            and pool.shape_stride_value_id is not None
        )
        contract_cell = self._sequence_contract_cell(int(sequence_id))
        query_values = self._table_query_values(query_id, descriptor)
        value_columns = tuple(
            column
            for column in range(len(descriptor.column_value_ids))
            if column not in descriptor.key_columns
        )
        aggregate_member_ids = self._structural_return_members(int(result_id)) or ()
        if len(value_columns) > 1 and (
            len(aggregate_member_ids) != len(value_columns)
        ):
            raise ValueError(
                "multi-column mapping lookup has no exact aggregate member "
                f"layout: result={int(result_id)}, "
                f"value_columns={value_columns!r}, "
                f"members={aggregate_member_ids!r}"
            )
        result = (
            self.fresh_value(
                dtype="int", transform=TABLE_LOOKUP,
                operands=(contract_cell, *query_values),
            )
            if tensor_child
            else self.fresh_value(
                dtype="ssa.aggregate", transform=TABLE_LOOKUP,
                operands=(contract_cell, *query_values),
            )
            if len(value_columns) > 1
            else SSAValue(
                int(result_id),
                dtype=("int" if pool is not None
                       else descriptor.column_dtypes[
                           next(
                               column
                               for column in range(
                                   len(descriptor.column_value_ids)
                               )
                               if column not in descriptor.key_columns
                           )
                       ]),
            )
        )
        if not tensor_child and len(value_columns) == 1:
            self._bind(
                int(result_id), result, BindingKind.SEQUENCE_RESULT,
                contract_cell, *query_values,
            )
        default_operands: tuple[SSAValue, ...] = ()
        if default_literal is not None:
            value_columns = tuple(
                column
                for column in range(len(descriptor.column_value_ids))
                if column not in descriptor.key_columns
            )
            default_dtype = (
                descriptor.column_dtypes[value_columns[0]]
                if len(value_columns) == 1 else "unknown"
            )
            default_value = self.fresh_value(
                dtype=str(default_dtype), transform=CONTROL_CONST,
                operands=(contract_cell, *query_values),
            )
            self.emit(
                Handler.Const, [], default_value,
                attributes={"value": default_literal},
            )
            default_operands = (default_value,)
        call_attributes = {
            "callee": helper_name,
            "source_linked": True,
            "ssa_sequence_operation": "lookup",
            "sequence_id": int(sequence_id),
            "ssa_lookup_ownership": str(ownership),
            "ssa_lookup_owner_ids": tuple(map(int, owner_ids)),
        }
        if len(value_columns) > 1:
            call_attributes.update({
                "output_ids": aggregate_member_ids,
                "result_convention": "ssa.aggregate",
            })
        self.emit(
            Handler.Call,
            [
                *self.sequence_storage_values[int(sequence_id)],
                self.sequence_status_values[int(sequence_id)],
                *query_values,
                *default_operands,
            ],
            result,
            attributes=call_attributes,
        )
        if len(value_columns) > 1:
            self._bind(
                int(result_id), result, BindingKind.SEQUENCE_RESULT,
                contract_cell, *query_values,
            )
            for output_index, member_id in enumerate(aggregate_member_ids):
                self.indexed_load(
                    result,
                    self.constant_value(output_index, result),
                    int(member_id),
                    attributes={
                        "aggregate_index": int(output_index),
                        "source_output_id": int(member_id),
                        "mapping_lookup_projection": True,
                    },
                    claim_provisional_definition=True,
                )
        if pool is not None:
            self.child_table_selections[int(result_id)] = (
                pool, result
            )
            if empty_default:
                self.empty_default_child_ids.add(int(result_id))
                # ``for x in d.get(k, ())``: lookup status owns presence.
                # A missing key yields the authored empty tuple; it must
                # never read child row zero's length (zero is a valid handle).
                status_address = self._sequence_status_address(self.sequence_status_values[int(sequence_id)])
                status = self.fresh_value(dtype="int", transform=LOAD, operands=(status_address, result))
                self.emit(Handler.Load, [status_address], status,
                          attributes={"binding": "selected_child_lookup_status", "source_value_id": int(result_id)})
                present = self.fresh_value(dtype="bool", transform=CONTROL_PREDICATE, operands=(status,))
                self.emit(Handler.Eq, [status, self.constant_value(1, status)], present,
                          attributes={"binding": "selected_child_lookup_presence"})
                found = self.new_block("if_true")
                absent = self.new_block("if_false")
                complete = self.new_block("if_merge")
                self.conditional_branch(present, found, absent)
                self.current = found
                lengths = self.external_value(pool.length_value_id)
                address = self.fresh_value(dtype="ptr", transform=ADDRESS, operands=(lengths, result))
                self.emit(Handler.GetElementPtr, [lengths, result], address,
                          attributes={"binding": "selected_child_length"})
                length = self.fresh_value(dtype="int64", transform=LOAD, operands=(address,))
                self.emit(Handler.Load, [address], length,
                          attributes={"binding": "selected_child_length"})
                self.branch(complete)
                self.current = absent
                empty = self.fresh_value(dtype="int64", transform=CONTROL_CONST, operands=(status,))
                self.emit(Handler.Const, [], empty, attributes={"value": 0, "binding": "authored_empty_child_length"})
                self.branch(complete)
                self.current = complete
                extent = self.fresh_value(dtype="int64", transform=CONTROL_EXPRESSION, operands=(length, empty, present))
                self.emit(Handler.Phi, [length, empty], extent,
                          attributes={"binding": "selected_child_optional_extent", "incoming_blocks": (found.name, absent.name),
                                      "source_value_id": int(result_id), "authored_default": ()})
                self.selected_child_extent_values[int(result_id)] = extent
        if tensor_child:
            # A keyed Tensor value is a child-row handle at the outer lookup
            # boundary and a span at every numerical consumer. Materialize
            # that existing child-pool address contract here, while the exact
            # handle and pool identities are both present. No backend should
            # reconstruct a Python mapping or guess which arena the handle
            # selects.
            row_stride = self.external_value(pool.row_stride_value_id)
            offset = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(result, row_stride),
            )
            row_base = self.produced_value(
                int(result_id),
                dtype=str(pool.column_dtypes[0] or "unknown"),
                claim_provisional_definition=True,
                cause=(result, offset),
            )
            self.emit(
                Handler.Mul,
                [result, row_stride],
                offset,
                attributes={"binding": "keyed_tensor_row_offset"},
            )
            self.emit(
                Handler.GetElementPtr,
                [self.external_value(pool.column_value_ids[0]), offset],
                row_base,
                attributes={"binding": "keyed_tensor_row_base"},
            )
            if (
                pool.shape_value_id is None
                or pool.rank_value_id is None
                or pool.shape_stride_value_id is None
            ):
                raise ValueError(
                    f"keyed Tensor sequence {sequence_id} has no concorded "
                    "shape/rank child-pool contract"
                )
            shape_stride = self.external_value(pool.shape_stride_value_id)
            shape_offset = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(result, shape_stride),
            )
            shape_address = self.fresh_value(
                dtype="int32", transform=ADDRESS, operands=(shape_offset,),
            )
            rank_address = self.fresh_value(
                dtype="int32", transform=ADDRESS, operands=(result,),
            )
            rank = self.fresh_value(
                dtype="int32", transform=LOAD, operands=(rank_address,),
            )
            element_count = self.fresh_value(
                dtype="int32", transform=LOAD, operands=(result,),
            )
            self.emit(
                Handler.Mul,
                [result, shape_stride],
                shape_offset,
                attributes={"binding": "keyed_tensor_shape_offset"},
            )
            self.emit(
                Handler.GetElementPtr,
                [self.external_value(pool.shape_value_id), shape_offset],
                shape_address,
                attributes={"binding": "keyed_tensor_row_shape"},
            )
            self.emit(
                Handler.GetElementPtr,
                [self.external_value(pool.rank_value_id), result],
                rank_address,
                attributes={"binding": "keyed_tensor_row_rank_address"},
            )
            self.emit(
                Handler.Load,
                [rank_address],
                rank,
                attributes={"binding": "keyed_tensor_row_rank"},
            )
            length_address = self.fresh_value(
                dtype="int32", transform=ADDRESS, operands=(result,),
            )
            self.emit(
                Handler.GetElementPtr,
                [self.external_value(pool.length_value_id), result],
                length_address,
                attributes={"binding": "keyed_tensor_row_length_address"},
            )
            self.emit(
                Handler.Load,
                [length_address],
                element_count,
                attributes={"binding": "keyed_tensor_row_length"},
            )
            # Program: a keyed Tensor lookup (test_precompile_contract_rows.py,
            # ``test_keyed_tensor_lookup_posts_span_rank``).  Wrong record:
            # the selected child span's rank (the region's rank claim, read
            # from the ``tensor_shape_concordance`` row the planner posted
            # under this identity) reached the row base only in accounting,
            # with just the shape-concordance row posted.  Rule: this lookup
            # owns the physical child-span identities, so it commits the
            # complete contract under the authored result identity FIRST
            # (DERIVED from the incumbent row, the lookup's ``ssa_value``
            # cell and the cells it names), then posts the row base's
            # storage/rank DERIVED from that contract cell, then sets the
            # accounting FROM the posted fact.
            _keyed_rank = max(
                1, int(self.region_value_ranks.get(int(result_id), 1))
            )
            _contract_cell = self._post_tensor_shape_contract(
                int(result_id),
                {
                    "program_abi_storage": "span",
                    "program_abi_rank": _keyed_rank,
                    "tensor_metadata_state": "dynamic",
                    "tensor_shape_value_id": int(shape_address.id),
                    "tensor_rank_value_id": int(rank.id),
                    "tensor_element_count_value_id": int(element_count.id),
                    "source": "control-keyed-tensor-lookup",
                },
                result, shape_address, rank, element_count,
            )
            self._revise_value(
                row_base, _contract_cell,
                physical={"storage": "span", "rank": _keyed_rank},
            )
            row_base.accounting = {
                **dict(row_base.accounting or {}),
                **self._posted_physical_accounting(row_base),
                "tensor_metadata_state": "dynamic",
                "tensor_shape_value_id": int(shape_address.id),
                "tensor_rank_value_id": int(rank.id),
                "tensor_element_count_value_id": int(element_count.id),
                "keyed_tensor_handle_value_id": int(result.id),
            }
            self._bind(
                int(result_id), row_base, BindingKind.SEQUENCE_RESULT,
                result, offset,
            )

    def _post_tensor_shape_contract(
        self, value_id: int, contract: dict, *cells: Any,
    ) -> Ref:
        """``tensor_shape_concordance`` row ``(control scope, value)``: a
        REVISE DERIVED from ``cells`` (and the incumbent, when the new
        contract is merged over one), replacing the silent page-wide
        column write."""

        book = self._book()
        row = (str(self.tensor_shape_concordance_scope), int(value_id))
        incumbent = book.latest_ref(TENSOR_SHAPE_CONCORDANCE, row)
        sources = self._cells(incumbent, *cells, self._canonical_cell(value_id))
        if not sources:
            sources = (self._function_root(),)
        return book.post(
            TENSOR_SHAPE_CONCORDANCE, row, dict(contract),
            stage=self.active_stage,
            provenance=Derived(sources),
            mode=Mode.REVISE,
        )
    def _emit_table_store(
        self, _effect_id: int, key_id: int | tuple[int, ...],
        value_id: int, sequence_id: int, *, child_guard: SSAValue | None = None,
    ) -> None:
        if int(sequence_id) in self.native_object_source_ids:
            keys = key_id if isinstance(key_id, tuple) else (key_id,)
            if len(keys) != 1:
                raise ValueError('native object member store requires one reference key')
            self._emit_native_object_operation('set', int(sequence_id), (*keys, value_id), None)
            return
        descriptor = self.sequence_descriptors.get(int(sequence_id))
        if descriptor is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-table", "store", self.function_name,
                f"table {sequence_id} has no sequence descriptor",
            ))
            return
        query_values = self._table_query_values(key_id, descriptor)
        stored_value = self.external_value(int(value_id))
        tag_columns = self.sequence_native_type_tag_columns(int(sequence_id))
        value_columns = tuple(
            column
            for column in range(len(descriptor.column_value_ids))
            if column not in descriptor.key_columns
        )
        stored_values = (stored_value,)
        if len(value_columns) > 1:
            member_ids = tuple(map(
                int,
                self.source_value_descriptions.get(
                    int(value_id), {}
                ).get("aggregate_leaf_value_ids", ()),
            ))
            if len(member_ids) != len(value_columns):
                raise ValueError(
                    "multi-column mapping store has no exact aggregate member "
                    f"layout: value={int(value_id)}, "
                    f"value_columns={value_columns!r}, members={member_ids!r}"
                )
            stored_values = tuple(
                self.external_value(member_id) for member_id in member_ids
            )
        if tag_columns:
            if len(value_columns) != 1 or set(tag_columns) != {
                int(value_columns[0])
            }:
                raise ValueError(
                    "heterogeneous native table requires exactly one "
                    "declared union value column: "
                    f"sequence={int(sequence_id)}, "
                    f"key_columns={descriptor.key_columns!r}, "
                    f"tag_columns={tuple(sorted(tag_columns))!r}"
                )
            value_column = int(value_columns[0])
            tag_column, target_id, fact = tag_columns[value_column]
            tag_value = self.native_type_tag_for(int(value_id), fact)
            if tag_value is None:
                raise ValueError(
                    "authored heterogeneous table value has no exact "
                    f"native type evidence: sequence={int(sequence_id)}, "
                    f"value={int(value_id)}"
                )
            arm_values = self._native_value_union_row_payloads(
                int(value_id), stored_value, fact,
            )
            arms = self.sequence_native_value_union_columns(
                int(sequence_id)
            )[value_column]
            if len(arms) != len(arm_values):
                raise ValueError(
                    "heterogeneous table writer arm count differs from its "
                    "authoritative column ABI"
                )
            storage = self.sequence_storage_values[int(sequence_id)]
            physical_columns: list[SSAValue] = []
            physical_row: list[SSAValue] = []
            physical_dtypes: list[str] = []
            physical_shapes: list[tuple[int, ...]] = []
            physical_keys: list[int] = []
            query_by_column = dict(zip(descriptor.key_columns, query_values))
            logical_shapes = tuple(descriptor.column_shapes or (
                () for _ in descriptor.column_value_ids
            ))
            for column in range(len(descriptor.column_value_ids)):
                if column in descriptor.key_columns:
                    physical_keys.append(len(physical_columns))
                    physical_columns.append(storage[column])
                    physical_row.append(query_by_column[column])
                    physical_dtypes.append(str(descriptor.column_dtypes[column]))
                    physical_shapes.append(tuple(logical_shapes[column]))
                    continue
                for (arm, arm_column), arm_value in zip(
                    arms, arm_values, strict=True,
                ):
                    physical_columns.append(arm_column)
                    physical_row.append(arm_value)
                    physical_dtypes.append(str(
                        arm_column.dtype or "unknown"
                    ))
                    physical_shapes.append(tuple(
                        arm_column.shape or ()
                    ))
                physical_columns.append(tag_column)
                physical_row.append(tag_value)
                physical_dtypes.append("int64")
                physical_shapes.append(())
            physical = replace(
                descriptor,
                column_value_ids=tuple(value.id for value in physical_columns),
                column_dtypes=tuple(physical_dtypes),
                column_shapes=tuple(physical_shapes),
                key_columns=tuple(physical_keys),
            )
            from .ir_sequence_tables import lower_table_store

            helper_name = self._sequence_helper_name(
                int(sequence_id), "store",
            )
            lowering = lower_table_store(
                physical,
                function_name=helper_name,
                first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
            )
            self._register_sequence_lowering(lowering)
            logical_width = len(descriptor.column_value_ids)
            self.emit(
                Handler.Call,
                [
                    *physical_columns,
                    *storage[logical_width:],
                    self.sequence_status_values[int(sequence_id)],
                    *physical_row,
                ],
                None,
                attributes={
                    "callee": helper_name,
                    "source_linked": True,
                    "ssa_sequence_operation": "table_store",
                    "sequence_id": int(sequence_id),
                    "native_type_tag_sequence": (
                        value_column, int(tag_column.id), int(tag_value.id),
                        int(target_id),
                    ),
                },
            )
            self._require_table_store_room(int(sequence_id), int(_effect_id))
            return
        actual_dtypes = tuple(
            str(_canonical_sequence_dtype(value.dtype) or "unknown")
            for value in (*query_values, *stored_values)
        )
        if len(actual_dtypes) == len(descriptor.column_dtypes):
            concorded_dtypes = concord_sequence_row_dtypes(
                self.function_name,
                {int(sequence_id): actual_dtypes},
                source=f"{self.function_name}: table store operands",
                sources=self._cells(
                    self._sequence_contract_cell(int(sequence_id)),
                    *query_values,
                    *stored_values,
                    *self.sequence_storage_values.get(
                        int(sequence_id), ()
                    ),
                ) or (self._function_root(),),
                stage=self._stage(),
            )
            if tuple(descriptor.column_dtypes) != concorded_dtypes:
                descriptor = replace(
                    descriptor, column_dtypes=concorded_dtypes,
                )
                self.sequence_descriptors[int(sequence_id)] = descriptor
            row_dtype_cell = self._book().latest_ref(
                SEQUENCE_ROW_DTYPE, (self.function_name, int(sequence_id)),
            )
            for value, dtype in zip(
                self.sequence_storage_values[int(sequence_id)],
                concorded_dtypes,
            ):
                if str(value.dtype or "unknown") in {
                    "", "None", "unknown",
                }:
                    # Program: ``ssa_heap_allocation.
                    # validate_heap_context_projection``'s keyed store.
                    # Wrong record: the column storage (value 111) took the
                    # concorded int64 here while its ``ssa_value`` row kept
                    # 'unknown' ("unresolved evidence cannot erase resident
                    # type").  Rule: as at the other concorded-column
                    # writers, the resident change is a REVISE of its row
                    # DERIVED from the row-dtype concordance it was read
                    # from; a descriptor column is an arena.
                    value.dtype = str(dtype)
                    self._revise_value(
                        value, row_dtype_cell,
                        self._sequence_contract_cell(int(sequence_id)),
                        stage=self._stage(),
                        physical=(
                            {"arena": True}
                            if int(value.id) in descriptor.column_value_ids
                            else KEEP_PHYSICAL
                        ),
                    )
        from .ir_sequence_tables import lower_table_store

        helper_name = self._sequence_helper_name(int(sequence_id), "store")
        lowering = lower_table_store(
            descriptor,
            function_name=helper_name,
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        self._register_sequence_lowering(lowering)
        self.emit(
            Handler.Call,
            [
                *self.sequence_storage_values[int(sequence_id)],
                self.sequence_status_values[int(sequence_id)],
                *query_values,
                *stored_values,
            ],
            None,
            attributes={
                "callee": helper_name,
                "source_linked": True,
                "ssa_sequence_operation": "table_store",
                "sequence_id": int(sequence_id),
                **({"child_selection_guard_value_id": int(child_guard.id)} if child_guard is not None else {}),
            },
        )
        self._require_table_store_room(int(sequence_id), int(_effect_id))

    def _require_table_store_room(self, sequence_id: int, effect_id: int) -> None:
        """Raise when the keyed store just emitted found no free row.

        Program: a store past a FIXED table's proven capacity (scratch
        s42/t2 before its capacity bound counted deleted rows).  Wrong
        record: the store helper reports "full" as status 2 into the
        table's status cell (the ABI the structural resident-table verifier
        probes), and no caller read it, so the row was dropped and
        ``len(d)`` was 1 for 2 (clean audit).  Rule (takeover rule 10, as a
        fixed append raises): the caller reads the status and a full store
        raises validation error 75.
        """

        if self.host_reads_table_status:
            return
        self._raise_on_table_status(
            sequence_id, effect_id, 2,
            binding="ssa_table_store_status",
            error_code=75, failure="fixed_capacity_exhausted",
        )

    def _require_table_delete_found(
        self, sequence_id: int, effect_id: int,
    ) -> None:
        """Raise KeyError's validation error when a keyed delete found no
        live row.

        Program: ``d = {1: n, 2: 5}; del d[n]`` with ``n = 7`` (silent lane,
        scratch s43/j).  Wrong record: the delete helper reports "absent" as
        status 0 and no caller read it, so the program went on where Python
        raises KeyError (clean audit).  Rule: the caller reads the status;
        absent raises validation error 84 (``required_key_absent``), the
        code a required lookup raises.
        """

        if self.host_reads_table_status:
            return
        self._raise_on_table_status(
            sequence_id, effect_id, 0,
            binding="ssa_table_delete_status",
            error_code=84, failure="required_key_absent",
        )

    def _raise_on_table_status(
        self, sequence_id: int, effect_id: int, failing_status: int, *,
        binding: str, error_code: int, failure: str,
    ) -> None:
        """Read a table's status cell after a helper call; raise
        ``error_code`` when it holds ``failing_status``."""

        attributes = {
            "binding": str(binding),
            "sequence_id": int(sequence_id),
            "source_effect_node_id": int(effect_id),
        }
        status_arena = self.sequence_status_values[int(sequence_id)]
        zero = self.constant_value(0, status_arena)
        address = self.fresh_value(
            dtype="ptr", transform=ADDRESS, operands=(status_arena, zero),
        )
        self.emit(
            Handler.GetElementPtr, [status_arena, zero], address,
            attributes=attributes,
        )
        status = self.fresh_value(
            dtype="int", transform=LOAD, operands=(address,),
        )
        self.emit(Handler.Load, [address], status, attributes=attributes)
        failed = self.fresh_value(
            dtype="bool", transform=CONTROL_PREDICATE, operands=(status,),
        )
        self.emit(
            Handler.Eq,
            [status, self.constant_value(int(failing_status), status)],
            failed,
            attributes=attributes,
        )
        failing = self.new_block("validation_fail")
        passing = self.new_block("validation_pass")
        self.conditional_branch(failed, failing, passing)
        self.current = failing
        self.emit(
            Handler.Call,
            [],
            attributes={
                "callee": "turing_validation_error",
                "error_code": int(error_code),
                "failure": str(failure),
                **attributes,
            },
        )
        self.branch(passing)
        self.current = passing

    def _sequence_row_index(
        self, sequence_id: int, index_id: int, literal: int | None,
    ) -> SSAValue:
        if literal is None:
            return self.external_value(int(index_id), dtype="int64")
        if int(literal) >= 0:
            return self.constant_value(int(literal))
        descriptor = self.sequence_descriptors[int(sequence_id)]
        length_cell = self.sequence_storage_values[int(sequence_id)][
            len(descriptor.column_value_ids)
        ]
        length = self.fresh_value(
            dtype="int64", transform=LOAD, operands=(length_cell,),
        )
        self.emit(
            Handler.Load, [length_cell], length,
            attributes={
                "binding": "ssa_sequence_row_length",
                "sequence_id": int(sequence_id),
            },
        )
        normalized = self.fresh_value(
            dtype="int64", transform=CONTROL_EXPRESSION, operands=(length,),
        )
        self.emit(
            Handler.Add, [length, self.constant_value(int(literal), length)], normalized,
            attributes={
                "binding": "ssa_sequence_negative_index",
                "sequence_id": int(sequence_id),
            },
        )
        return normalized

    def _emit_sequence_row_load(
        self, result_id: int, sequence_id: int, index_id: int,
        index_literal: int | None, column: int, _row_value_id: int,
    ) -> None:
        descriptor = self.sequence_descriptors.get(int(sequence_id))
        if descriptor is None or not 0 <= int(column) < len(
            descriptor.column_value_ids
        ):
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "row-load", self.function_name,
                f"sequence {sequence_id} has no column {column}",
            ))
            return
        index = self._sequence_row_index(
            int(sequence_id), int(index_id), index_literal
        )
        # Program: ``xs = [5] * (n % 4 + 1); xs[0]`` (scratch c_k1).  Wrong
        # record: the row load demanded the heap column at its element
        # dtype, so ``external_value`` revised the ``ptr`` cell's row back
        # to int64; the structural view then completed its shape from the
        # planner's (1,) extent and the reserve's heap copy refused the
        # shaped "handle".  Rule: a heap column is its ``ptr`` cell (the
        # element type is ``heap_element_dtype``, which ``indexed_load``
        # reads); a row load demands the element dtype only of a column
        # that holds its rows.
        # A selected pool row's columns are the slice addresses built where
        # the row was selected; they are the descriptor's storage values and
        # have no other binding.
        source = (
            self.sequence_storage_values[int(sequence_id)][int(column)]
            if int(sequence_id) in self.child_table_selections
            and int(sequence_id) in self.sequence_storage_values
            else self.external_value(
                int(descriptor.column_value_ids[int(column)]),
                dtype=(
                    None if descriptor.heap_owner_value_id is not None
                    else str(descriptor.column_dtypes[int(column)])
                ),
            )
        )
        pool = descriptor.child_table_pool
        if pool is not None and int(column) == int(pool.handle_column):
            # Program: ``g = [[1, 2], [3, n]]; g[i][1]`` (corpus c732).  The
            # outer list's column holds row handles; ``g[i]`` is the pool
            # slice that handle selects, as a keyed lookup's row is, and a
            # region that reads it takes the slice's first column address.
            handle = self.indexed_load(
                source, index,
                int(self.fresh_value(
                    dtype="int64", transform=LOAD, operands=(source, index),
                ).id),
                attributes={
                    "binding": "ssa_sequence_row_handle_load",
                    "sequence_id": int(sequence_id),
                    "column": int(column),
                },
            )
            self.child_table_selections[int(result_id)] = (pool, handle)
            if self._sequence_descriptor(
                int(result_id), policy="duplicates", writable=True,
                location=f"{self.function_name}.sequence_row_load",
            ) is None:
                return
            self._bind(
                int(result_id),
                self.sequence_storage_values[int(result_id)][0],
                BindingKind.SEQUENCE_RESULT, handle,
            )
            return
        projected_value = self.indexed_load(
            source, index, int(result_id),
            attributes={
                "binding": "ssa_sequence_row_load",
                "sequence_id": int(sequence_id),
                "column": int(column),
            },
            # Control construction is not lexical execution order.  A while
            # predicate can ask for this graph id before its exact resident
            # row-load block is emitted.  The load is the producer already
            # named by the sequence contract, so it must resolve that
            # provisional argument rather than mint a second SSA identity.
            claim_provisional_definition=True,
        )
        # Program: ``xs = []; ...; ys = sorted(xs)`` then ``ys[0] * 100``
        # (scratch c135).  Wrong record: the planner posted ``ys[0]``'s
        # ``ssa_value`` row float64 (its capture guess) before control
        # lowering; this load produced int64 and left that row standing, so
        # the region-feed occurrence and scalar settlement re-read float64
        # and typed the heap arena's loads float64 ("storage types are
        # immutable").  Rule: the row load is the producer; it revises its
        # row to the column's element type, derived from the column cell.
        if str(projected_value.dtype or "unknown") not in {
            "", "None", "unknown", "ptr",
        }:
            self._revise_value(projected_value, *self._cells(source))
        # A direct sequence-row load is the same physical projection as a
        # loop-bound row value.  When the concordance declares this logical
        # column heterogeneous, load its parallel tag column at the identical
        # row index.  Leaving the tag to the later predicate path creates a
        # provisional public formal even though the sequence projection is
        # already the authoritative producer (IdentityPage._reaches_origin,
        # value 23).
        type_tag = self.projected_native_type_tag(
            int(sequence_id), int(column), index, int(result_id),
        )
        if type_tag is not None:
            projected_value.accounting = {
                **dict(projected_value.accounting or {}),
                "native_type_tag_value_id": int(type_tag.id),
                "native_type_alternatives": tuple(
                    type_tag.accounting.get("native_type_alternatives", ())
                ),
            }

    def _emit_sequence_row_store(
        self, result_id: int, sequence_id: int, index_id: int,
        index_literal: int | None, row_value_ids: tuple[int | None, ...],
        _row_aggregate_id: int,
    ) -> None:
        descriptor = self.sequence_descriptors.get(int(sequence_id))
        if descriptor is None or len(row_value_ids) != len(
            descriptor.column_value_ids
        ):
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "row-store", self.function_name,
                f"sequence {sequence_id} row width is unresolved",
            ))
            return
        if not descriptor.writable:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "row-store", self.function_name,
                f"sequence {sequence_id} is declared read-only",
            ))
            return
        index = self._sequence_row_index(
            int(sequence_id), int(index_id), index_literal
        )
        for column, (column_id, value_id) in enumerate(zip(
            descriptor.column_value_ids, row_value_ids
        )):
            # A sparse row update carries None for untouched columns. It
            # updates the selected reference slot without loading/copying
            # the other payloads or inventing a temporary row allocation.
            if value_id is None:
                continue
            column_value = self.external_value(int(column_id))
            address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(column_value, index),
            )
            self.emit(
                Handler.GetElementPtr,
                [column_value, index],
                address,
                attributes={
                    "binding": "ssa_sequence_row_store",
                    "sequence_id": int(sequence_id),
                    "column": int(column),
                },
            )
            self.emit(
                Handler.Store,
                [self.external_value(int(value_id)), address],
                attributes={
                    "binding": "ssa_sequence_row_store",
                    "sequence_id": int(sequence_id),
                    "column": int(column),
                },
            )
        if all(value_id is not None for value_id in row_value_ids):
            self._bind(
                int(result_id), self.external_value(int(sequence_id)),
                BindingKind.SEQUENCE_RESULT,
                self._sequence_contract_cell(int(sequence_id)), index,
            )

    def _emit_table_delete(
        self, effect_id: int, key_id: int | tuple[int, ...],
        sequence_id: int | None, storage_identity: str,
        *, required: bool = True,
    ) -> None:
        if sequence_id is None:
            match = re.fullmatch(r"nested-table-value:(\d+)", storage_identity)
            selection = (
                self.child_table_selections.get(int(match.group(1)))
                if match is not None else None
            )
            if selection is not None:
                pool, handle = selection
                from .ir_sequence_tables import lower_child_table_delete

                helper_name = (
                    f"{self.function_name}__ssa_child_table_"
                    f"{int(match.group(1))}_delete"
                )
                lowering = lower_child_table_delete(
                    pool,
                    function_name=helper_name,
                    first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                )
                self._register_sequence_lowering(lowering)
                pool_arguments = [
                    self.external_value(value_id)
                    for value_id in (
                        *pool.column_value_ids,
                        pool.length_value_id,
                        pool.capacity_value_id,
                        pool.row_stride_value_id,
                        pool.status_value_id,
                        pool.live_flags_value_id,
                    )
                ]
                self.emit(
                    Handler.Call,
                    [
                        *pool_arguments,
                        handle,
                        *self._table_query_values(key_id, pool),
                    ],
                    None,
                    attributes={
                        "callee": helper_name,
                        "source_linked": True,
                        "ssa_sequence_operation": "child_table_delete",
                        "child_handle_value_id": int(match.group(1)),
                    },
                )
                return
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-table", "delitem",
                f"{self.function_name}.table_delete[{effect_id}]",
                "nested table deletion requires a resident nested-table "
                f"descriptor: storage={storage_identity}, key_value_id={key_id}",
            ))
            return
        descriptor = self.sequence_descriptors.get(int(sequence_id))
        if descriptor is None or descriptor.live_flags_value_id is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-table", "delitem",
                f"{self.function_name}.table_delete[{effect_id}]",
                f"table {sequence_id} has no tombstone-enabled descriptor",
            ))
            return
        from .ir_sequence_tables import lower_table_delete

        first_live = isinstance(key_id, tuple) and not key_id
        if first_live:
            from .ir_sequence_tables import lower_table_delete_first
            helper_name = self._sequence_helper_name(
                int(sequence_id), "delete_first",
            )
            lowering = lower_table_delete_first(
                descriptor,
                function_name=helper_name,
                first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
            )
        else:
            helper_name = self._sequence_helper_name(
                int(sequence_id), "delete",
            )
            lowering = lower_table_delete(
                descriptor,
                function_name=helper_name,
                first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
            )
        self._register_sequence_lowering(lowering)
        self.emit(
            Handler.Call,
            [
                *self.sequence_storage_values[int(sequence_id)],
                self.sequence_status_values[int(sequence_id)],
                *(
                    self._table_query_values(key_id, descriptor)
                    if not first_live else ()
                ),
            ],
            None,
            attributes={
                "callee": helper_name,
                "source_linked": True,
                "ssa_sequence_operation": (
                    "table_delete_first" if first_live else "table_delete"
                ),
                "sequence_id": int(sequence_id),
            },
        )
        # ``del d[k]`` and ``d.pop(k)`` require the key; the first-live
        # delete has no authored key to require.
        if required and not first_live:
            self._require_table_delete_found(int(sequence_id), int(effect_id))

    def _emit_sequence_fill(
        self, sequence_id: int, literal: bool | int | float | None, count_id: int
    ) -> None:
        descriptor = self.sequence_descriptors.get(int(sequence_id))
        if descriptor is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "fill", self.function_name,
                f"sequence {sequence_id} has no descriptor",
            ))
            return
        from .ir_sequence_tables import lower_sequence_fill

        helper_name = self._sequence_helper_name(int(sequence_id), "fill")
        lowering = lower_sequence_fill(
            descriptor,
            function_name=helper_name,
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        self._register_sequence_lowering(lowering)
        contract_cell = self._sequence_contract_cell(int(sequence_id))
        if isinstance(literal, tuple):
            # ``[n] * k``: the member is a runtime value (its value id).
            value = self.external_value(
                int(literal[1]), dtype=str(descriptor.column_dtypes[0]),
            )
        else:
            value = self.fresh_value(
                dtype=str(descriptor.column_dtypes[0]), transform=CONTROL_CONST,
                operands=(contract_cell,),
            )
            self.emit(Handler.Const, [], value, attributes={"value": literal})
        status = self.fresh_value(
            dtype="int", transform=REGION_CALL_RESULT,
            operands=(contract_cell, value),
        )
        self.emit(
            Handler.Call,
            [
                *self.sequence_storage_values[int(sequence_id)],
                value,
                self.external_value(int(count_id), dtype="int"),
            ],
            status,
            attributes={
                "callee": helper_name,
                "source_linked": True,
                "ssa_sequence_operation": "fill",
                "sequence_id": int(sequence_id),
            },
        )
        self.emit(
            Handler.Store,
            [status, self._sequence_status_address(
                self.sequence_status_values[int(sequence_id)]
            )],
            attributes={"binding": "ssa_sequence_status"},
        )

    def _emit_sequence_append_fill(
        self, sequence_id: int, literal: bool | int | float | None,
        count_id: int,
    ) -> None:
        descriptor = self.sequence_descriptors.get(int(sequence_id))
        if descriptor is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "append_fill", self.function_name,
                f"sequence {sequence_id} has no descriptor",
            ))
            return
        from .ir_sequence_tables import lower_sequence_append_fill

        helper_name = self._sequence_helper_name(
            int(sequence_id), "append_fill",
        )
        lowering = lower_sequence_append_fill(
            descriptor,
            function_name=helper_name,
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        self._register_sequence_lowering(lowering)
        contract_cell = self._sequence_contract_cell(int(sequence_id))
        value = self.fresh_value(
            dtype=str(descriptor.column_dtypes[0]), transform=CONTROL_CONST,
            operands=(contract_cell,),
        )
        self.emit(Handler.Const, [], value, attributes={"value": literal})
        status = self.fresh_value(
            dtype="int", transform=REGION_CALL_RESULT,
            operands=(contract_cell, value),
        )
        self.emit(
            Handler.Call,
            [
                *self.sequence_storage_values[int(sequence_id)],
                value,
                self.external_value(int(count_id), dtype="int"),
            ],
            status,
            attributes={
                "callee": helper_name,
                "source_linked": True,
                "ssa_sequence_operation": "append_fill",
                "sequence_id": int(sequence_id),
            },
        )
        self.emit(
            Handler.Store,
            [status, self._sequence_status_address(
                self.sequence_status_values[int(sequence_id)]
            )],
            attributes={"binding": "ssa_sequence_status"},
        )

    def _emit_sequence_append_slice(
        self, destination_id: int, source_id: int,
        lower_id: int | None, upper_id: int | None,
        *, lower_literal: int | None = None, upper_literal: int | None = None,
    ) -> None:
        self.ensure_plan_callsite_result(
            int(source_id), location=f"{self.function_name}.append_slice"
        )
        destination = self.sequence_descriptors.get(int(destination_id))
        source = self.sequence_descriptors.get(int(source_id))
        if destination is None or source is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "append_slice", self.function_name,
                "slice append requires resident source and destination "
                f"descriptors: destination={destination_id}, source={source_id}",
            ))
            return
        # Program: ``xs = [1, 2] + [n, 8]; return xs[2]`` (c264).  Wrong
        # record: the concatenation's arena had no row writer but these
        # slice appends, so its row stayed ``unknown`` and scalar settlement
        # typed it float64 (3.0 for 3).  Rule: a slice append is a row
        # writer; the source's row type refines the destination's, as an
        # append's stored value does.
        if any(
            str(column) in {"", "unknown", "None"}
            and str(source_column) not in {"", "unknown", "None"}
            for column, source_column in zip(
                destination.column_dtypes, source.column_dtypes,
            )
        ):
            refined = self._sequence_descriptor(
                int(destination_id),
                policy="unique" if destination.key_columns else "duplicates",
                writable=True,
                location=f"{self.function_name}.append_slice",
                column_count=len(destination.column_dtypes),
                column_dtypes=tuple(
                    None if str(column) in {"", "unknown", "None"}
                    else str(column)
                    for column in source.column_dtypes
                ),
                dtype_sources=tuple(
                    self.sequence_storage_values[int(source_id)][
                        :len(source.column_dtypes)
                    ]
                ),
            )
            if refined is None:
                return
            destination = refined
        from .ir_sequence_tables import lower_sequence_append_slice

        helper_name = self._sequence_helper_name(
            int(destination_id), "append_slice", int(source_id),
        )
        lowering = lower_sequence_append_slice(
            destination,
            source,
            function_name=helper_name,
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        if not lowering.complete:
            self.shortfalls.extend(
                SSALoweringShortfall(
                    "ssa-sequence", item.code.value, self.function_name,
                    item.reason,
                )
                for item in lowering.shortfalls
            )
            return
        self._register_sequence_lowering(lowering)
        storage = tuple({
            value.id: value
            for value in (
                *self.sequence_storage_values[int(destination_id)],
                *self.sequence_storage_values[int(source_id)],
            )
        }.values())
        # A whole-sequence extend (``resident += other``) has no authored
        # bounds: 0 and a beyond-any-length constant span the source, and
        # the helper's Python-slice clipping does the rest.
        source_cell = self._sequence_contract_cell(int(source_id))
        if lower_id is None:
            lower_value = self.fresh_value(
                dtype="int64", transform=CONTROL_CONST, operands=(source_cell,),
            )
            self.emit(
                Handler.Const, [], lower_value, attributes={
                    "value": 0 if lower_literal is None else int(lower_literal)
                },
            )
        else:
            lower_value = self.external_value(int(lower_id), dtype="int64")
        if upper_id is None:
            upper_value = self.fresh_value(
                dtype="int64", transform=CONTROL_CONST, operands=(source_cell,),
            )
            self.emit(
                Handler.Const, [], upper_value,
                attributes={"value": 2 ** 31 - 1 if upper_literal is None
                            else int(upper_literal)},
            )
        else:
            upper_value = self.external_value(int(upper_id), dtype="int64")
        status = self.fresh_value(
            dtype="int", transform=REGION_CALL_RESULT,
            operands=(*storage, lower_value, upper_value),
        )
        self.emit(
            Handler.Call,
            [
                *storage,
                lower_value,
                upper_value,
            ],
            status,
            attributes={
                "callee": helper_name,
                "source_linked": True,
                "ssa_sequence_operation": "append_slice",
                "sequence_id": int(destination_id),
                "source_sequence_id": int(source_id),
            },
        )
        self.emit(
            Handler.Store,
            [status, self._sequence_status_address(
                self.sequence_status_values[int(destination_id)]
            )],
            attributes={"binding": "ssa_sequence_status"},
        )

    def _emit_sequence_reset(self, sequence_id: int) -> None:
        """Start one ordinary sequence-expression result at logical length 0."""

        descriptor = self.sequence_descriptors.get(int(sequence_id))
        storage = self.sequence_storage_values.get(int(sequence_id))
        if descriptor is None or storage is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "reset", self.function_name,
                f"sequence {sequence_id} has no resident descriptor",
            ))
            return
        length_address = storage[len(descriptor.column_value_ids)]
        zero = self.fresh_value(
            dtype="int64", transform=CONTROL_CONST, operands=(length_address,),
        )
        self.emit(Handler.Const, [], zero, attributes={"value": 0})
        self.emit(
            Handler.Store, [zero, length_address],
            attributes={
                "binding": "ssa_sequence_expression_reset",
                "sequence_id": int(sequence_id),
            },
        )

    def _emit_sequence_pack_bits(
        self, destination_id: int, source_id: int, width_id: int,
        width_literal: bool = False,
        callee_reference: int | None = None,
        plan_callsite_id: int | None = None,
    ) -> None:
        destination = self.sequence_descriptors.get(int(destination_id))
        source = self.sequence_descriptors.get(int(source_id))
        if destination is None or source is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "pack_bits", self.function_name,
                "bit packing requires resident source and destination "
                f"descriptors: destination={destination_id}, source={source_id}",
            ))
            return
        from .ir_sequence_tables import lower_sequence_pack_bits

        helper_name = self._sequence_helper_name(
            int(destination_id), "pack_bits", int(source_id),
        )
        lowering = lower_sequence_pack_bits(
            destination,
            source,
            function_name=helper_name,
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        if not lowering.complete:
            self.shortfalls.extend(
                SSALoweringShortfall(
                    "ssa-sequence", item.code.value, self.function_name,
                    item.reason,
                ) for item in lowering.shortfalls
            )
            return
        self._register_sequence_lowering(lowering)
        storage = tuple({
            value.id: value
            for value in (
                *self.sequence_storage_values[int(destination_id)],
                *self.sequence_storage_values[int(source_id)],
            )
        }.values())
        status = self.fresh_value(
            dtype="int", transform=REGION_CALL_RESULT, operands=tuple(storage),
        )
        if width_literal:
            width = self.fresh_value(
                dtype="int", transform=CONTROL_CONST, operands=tuple(storage),
            )
            self.emit(
                Handler.Const, [], width,
                attributes={"value": int(width_id)},
            )
        else:
            width = self.external_value(int(width_id), dtype="int")
        self.emit(
            Handler.Call,
            [*storage, width],
            status,
            attributes={
                "callee": helper_name,
                "source_linked": True,
                "ssa_sequence_operation": "pack_bits",
                "sequence_id": int(destination_id),
                "source_sequence_id": int(source_id),
                "decomposed_plan_call": callee_reference is not None,
                "callee_reference": callee_reference,
                "plan_callsite_id": plan_callsite_id,
            },
        )
        self.emit(
            Handler.Store,
            [status, self._sequence_status_address(
                self.sequence_status_values[int(destination_id)]
            )],
            attributes={"binding": "ssa_sequence_status"},
        )

    def _emit_sequence_prepend(
        self, sequence_id: int, value_id: int,
    ) -> None:
        descriptor = self.sequence_descriptors.get(int(sequence_id))
        if descriptor is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "prepend", self.function_name,
                f"sequence {sequence_id} has no descriptor",
            ))
            return
        from .ir_sequence_tables import lower_sequence_prepend

        helper_name = self._sequence_helper_name(int(sequence_id), "prepend")
        lowering = lower_sequence_prepend(
            descriptor,
            function_name=helper_name,
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        self._register_sequence_lowering(lowering)
        status = self.fresh_value(
            dtype="int", transform=REGION_CALL_RESULT,
            operands=(self._sequence_contract_cell(int(sequence_id)),),
        )
        self.emit(
            Handler.Call,
            [
                *self.sequence_storage_values[int(sequence_id)],
                self.external_value(int(value_id), dtype=str(
                    descriptor.column_dtypes[0]
                )),
            ],
            status,
            attributes={
                "callee": helper_name,
                "source_linked": True,
                "ssa_sequence_operation": "prepend",
                "sequence_id": int(sequence_id),
            },
        )
        self.emit(
            Handler.Store,
            [status, self._sequence_status_address(
                self.sequence_status_values[int(sequence_id)]
            )],
            attributes={"binding": "ssa_sequence_status"},
        )

    def _emit_sequence_prepend_packed_bytes(
        self, destination_id: int, source_id: int,
        prefix_id: int, byte_width: int,
        plan_callsite_id: int | None = None,
    ) -> None:
        destination = self.sequence_descriptors.get(int(destination_id))
        source = self.sequence_descriptors.get(int(source_id))
        if destination is None or source is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "prepend_packed_bytes", self.function_name,
                "packed prepend requires resident source and destination "
                f"descriptors: destination={destination_id}, source={source_id}",
            ))
            return
        from .ir_sequence_tables import lower_sequence_prepend_packed_bytes

        helper_name = self._sequence_helper_name(
            int(destination_id), "prepend_packed", int(source_id),
        )
        lowering = lower_sequence_prepend_packed_bytes(
            destination,
            source,
            function_name=helper_name,
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        self._register_sequence_lowering(lowering)
        storage = tuple({
            value.id: value
            for value in (
                *self.sequence_storage_values[int(destination_id)],
                *self.sequence_storage_values[int(source_id)],
            )
        }.values())
        width_value = self.fresh_value(
            dtype="int", transform=CONTROL_CONST, operands=tuple(storage),
        )
        self.emit(
            Handler.Const, [], width_value,
            attributes={"value": int(byte_width)},
        )
        status = self.fresh_value(
            dtype="int", transform=REGION_CALL_RESULT,
            operands=(*storage, width_value),
        )
        self.emit(
            Handler.Call,
            [
                *storage,
                self.external_value(int(prefix_id), dtype=str(
                    destination.column_dtypes[0]
                )),
                width_value,
            ],
            status,
            attributes={
                "callee": helper_name,
                "source_linked": True,
                "ssa_sequence_operation": "prepend_packed_bytes",
                "sequence_id": int(destination_id),
                "source_sequence_id": int(source_id),
                "decomposed_plan_call": True,
                "plan_callsite_id": plan_callsite_id,
            },
        )
        self.emit(
            Handler.Store,
            [status, self._sequence_status_address(
                self.sequence_status_values[int(destination_id)]
            )],
            attributes={"binding": "ssa_sequence_status"},
        )

    def emit_table_region_operations(self, region_index: int) -> bool:
        operations = self.table_region_operations.get(int(region_index), ())
        if not operations:
            return False
        replaces_region = True
        for kind, arguments in operations:
            if kind == "lookup":
                self._emit_table_lookup(*arguments)
            elif kind == "lookup_capture":
                # The lookup replaces only the keyed source instruction.  Its
                # resident scalar result is an ordinary capture of the mixed
                # arithmetic region that follows.
                self._emit_table_lookup(*arguments)
                replaces_region = False
            elif kind == "row_load":
                self._emit_sequence_row_load(*arguments)
            elif kind == "row_load_capture":
                self._emit_sequence_row_load(*arguments)
                replaces_region = False
            elif kind == "row_store":
                self._emit_sequence_row_store(*arguments)
            elif kind == "store":
                self._emit_table_store(*arguments)
            elif kind == "delete":
                self._emit_table_delete(*arguments)
            elif kind == "fill":
                self._emit_sequence_fill(*arguments)
            elif kind == "append_fill":
                self._emit_sequence_append_fill(*arguments)
            elif kind == "append_slice":
                self._emit_sequence_append_slice(*arguments)
            elif kind == "reset":
                self._emit_sequence_reset(*arguments)
            elif kind == "append_scalar":
                destination_id, value_id = arguments
                self.lower_sequence_mutation(
                    ControlSequenceMutation(
                        sequence_value_id=int(destination_id),
                        operator="append",
                        argument_value_ids=(int(value_id),),
                        effect_node_id=int(value_id),
                        policy="duplicates",
                        argument_kind="scalar",
                    ),
                    path=f"{self.function_name}.structural_concat",
                )
            elif kind == "prepend":
                self._emit_sequence_prepend(*arguments)
            elif kind == "prepend_packed_bytes":
                self._emit_sequence_prepend_packed_bytes(*arguments)
            elif kind == "pack_bits":
                self._emit_sequence_pack_bits(*arguments)
            elif kind == "structural_consumed":
                # Its only result is consumed by a later structural helper.
                # The source region has no independent runtime effect.
                pass
            else:
                raise ValueError(f"unknown scheduled table operation {kind!r}")
        # Program: ``xs0 = [5, 7] + [n, 7]; xs1 = [2] * (n % 4 + 1)`` (fuzzer
        # p3_54).  Wrong record: the concat's reset/append_slice claimed to
        # replace region 0, which still had a lowered body (the count
        # ``n % 4 + 1``) and a post-operation (the fill); both were skipped
        # and ``xs1`` stayed empty.  Rule: an operation replaces its region
        # only when the region has nothing left to publish (its signature's
        # outputs: a planned region is pure, so a body with no outputs is
        # no work).  Program: ``d = {1: 5, 2: n}; del d[1]; d[3] = 4``
        # (scratch s42/t3).  Wrong record: the delete was the region's
        # pre-operation and the store its post-operation; the delete claimed
        # to replace the output-less region, so the call -- and the store
        # emitted after it -- never ran (``len(d)`` 1 for 2; clean audit).
        # Rule: a region with post-operations is not replaced either.
        # Program: ``d = {1: 2, 2: n, 3: 2}; del d[2]; xs = [4, n, 7];
        # xs[1] = 0`` (coverage march, fuzz p0_132).  Wrong record: the
        # delete rode region 0 -- the ``xs[1] = 0`` store -- as its
        # pre-operation, and replaced that output-less region, so the store
        # never ran (``xs[1]`` stayed ``n``; clean audit).  Rule: a region
        # whose body stores into memory has work without outputs and is
        # never replaced.
        return replaces_region and not tuple(
            self.region_signatures.get(int(region_index), ((), ()))[1]
        ) and not self.table_region_post_operations.get(
            int(region_index)
        ) and int(region_index) not in self.region_writing_indices

    def _register_sequence_lowering(self, lowering) -> None:
        """Install helpers through ``register_sequence_lowering``, caused by
        the innermost control cell (else this lowering's root)."""

        registered, unposted = register_sequence_lowering(
            lowering,
            book=self._book(),
            owner=next((
                cell for cell in reversed(self._control_cells)
                if cell is not None
            ), None) or self._function_root(),
            caller_scope=self._scope(),
            stage=self._stage(),
        )
        self.sequence_helper_functions.update(registered)
        self.ssa_value_objects.update(unposted)

    def external_value(
        self,
        value_id: int,
        *,
        dtype: str | None = None,
        follow_aliases: bool = True,
    ) -> SSAValue:
        value_id = int(value_id)
        if value_id in self.native_value_type_tests and (
            value_id not in self.external_values or self._is_stand_in(value_id)
        ):
            self._emit_native_value_type_test(value_id)
        if value_id in self.native_object_type_tests and (
            value_id not in self.external_values or self._is_stand_in(value_id)
        ):
            self._emit_native_object_type_test(value_id)
        field_effect = self.scalar_field_effect_destinations.get(value_id)
        if field_effect is not None and value_id not in self.external_values:
            field_value_id, field_dtype = field_effect
            if field_value_id != value_id:
                # Before its lexical Store, a SetAttr version denotes the
                # incumbent value in the same resident field.  This matters
                # when an in-place update uses one graph identity for both the
                # pre-branch and written versions.
                incumbent = self.external_value(field_value_id, dtype=field_dtype)
                # FIELD_INCUMBENT: the incumbent's own binding cell is the
                # cause (its ``ssa_field_version`` cell when lane C posted
                # one is reached through that binding).
                self._bind(
                    value_id, incumbent, BindingKind.FIELD_INCUMBENT,
                    self._binding_cell(field_value_id),
                )
        consumer_row_load = self.consumer_row_loads.get(value_id)
        if consumer_row_load is not None and value_id not in self.external_values:
            del self.consumer_row_loads[value_id]
            self._emit_sequence_row_load(*consumer_row_load)
        sequence_id = self.sequence_length_values.get(value_id)
        if sequence_id is not None and value_id not in self.external_values:
            if int(sequence_id) in self.native_object_source_ids:
                self._emit_native_object_operation('length', int(sequence_id), (), value_id)
            descriptor = self.sequence_descriptors.get(int(sequence_id))
            if descriptor is not None:
                length_cell = self.sequence_storage_values[int(sequence_id)][
                    len(descriptor.column_value_ids)
                ]
                value = SSAValue(value_id, dtype="int64")
                if descriptor.live_flags_value_id is not None:
                    # Program: ``d = {1: n, 2: 3}; del d[1]; len(d)``.
                    # Wrong record: ``len`` loaded the length cell, which
                    # still counts the tombstoned row, and returned 2.
                    # Rule: a table that retains deleted rows has the
                    # length of its live rows.
                    from .ir_sequence_tables import lower_sequence_live_length

                    helper_name = self._sequence_helper_name(
                        int(sequence_id), "live_length",
                    )
                    self._register_sequence_lowering(lower_sequence_live_length(
                        descriptor,
                        function_name=helper_name,
                        first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                    ))
                    self.emit(
                        Handler.Call,
                        list(self.sequence_storage_values[int(sequence_id)]),
                        value,
                        attributes={
                            "callee": helper_name,
                            "source_linked": True,
                            "ssa_sequence_operation": "live_length",
                            "sequence_id": int(sequence_id),
                        },
                    )
                else:
                    # c632's record materialization retains the length as
                    # one sequence cell, not a plain span formal. Address
                    # that exact cell through the ordinary memory SSA before
                    # loading it, as sequence initialization already does.
                    address = self.fresh_value(
                        dtype="ptr", transform=ADDRESS, operands=(length_cell,),
                    )
                    self.emit(
                        Handler.GetElementPtr,
                        [length_cell, self.constant_value(0, length_cell)],
                        address,
                        attributes={"binding": "ssa_sequence_length_address"},
                    )
                    self.emit(
                        Handler.Load, [address], value,
                        attributes={
                            "binding": "ssa_sequence_length_value",
                            "sequence_id": int(sequence_id),
                        },
                    )
                # SEQUENCE_LENGTH: the sequence's contract cell is the cause.
                self._bind(
                    value_id, value, BindingKind.SEQUENCE_LENGTH,
                    self._sequence_contract_cell(int(sequence_id)), length_cell,
                )
        if follow_aliases:
            seen: set[int] = set()
            while value_id in self.value_aliases and value_id not in seen:
                seen.add(value_id)
                value_id = int(self.value_aliases[value_id])
        if value_id in self.declared_parameter_only_ids:
            self.declared_parameter_only_ids.discard(value_id)
            self._declare_parameter(value_id, ParameterDeclaration.USED)
        value = self.external_values.get(value_id)
        if value is None:
            value = self._value_from_meta(value_id, dtype=dtype)
            description = self.source_value_descriptions.get(value_id)
            if description is not None:
                receipt = dict(description)
                node_id = int(receipt.get("node_id", value_id))
                fact = None
                if self.planning_scope is not None:
                    page = self._book().pages.get(EXECUTABLE_NODE.name)
                    if page is not None:
                        fact = page.cell(
                            (self.planning_scope, node_id), 0, None,
                        )
                receipt["planner_verdict"] = (
                    "absent" if fact is None else str(fact.kind.value)
                )
                if fact is not None:
                    receipt["planner_rule"] = str(fact.rule.value)
                self.source_execution_receipts[value_id] = dict(receipt)
                value.accounting = {
                    **dict(value.accounting or {}),
                    "source_execution_receipt": receipt,
                }
            # PROVISIONAL_ARGUMENT: a value minted from absence -- no region
            # has published the id yet -- is recorded as unresolved; the
            # producer's later claim is the revision that resolves it.
            self._bind_unresolved(value_id, NO_PRODUCER_AT_USE, value=value)
            self.arguments.append(value)
        elif (
            str(dtype or "unknown") not in {"", "unknown"}
            and str(value.dtype or "unknown") != str(dtype)
        ):
            # A structural control use can carry a stronger contract than an
            # earlier generic region capture.  Refine the one SSA identity
            # before the Function signature is assembled.
            #
            # Program: ``argument_binding_history``'s nested row loop.  The
            # sequence row load demanded its column's descriptor dtype,
            # still ``unknown``, of the row base minted ``int64`` by
            # ``bind_nested_row``; the "refinement" replaced the int64
            # identity with an unknown one and revised its row back to
            # unknown ("unresolved evidence cannot erase resident type").
            # Rule: only a resolved dtype is a contract that refines.
            refined = SSAValue(
                value.id,
                dtype=str(dtype),
                shape=tuple(value.shape),
                device=value.device,
                accounting=dict(value.accounting),
            )
            # REFINED: the value's row is revised to the demanded dtype and
            # the binding derives from that revision.
            previous_binding = self._binding_cell(value_id)
            self.ssa_value_objects[int(refined.id)] = refined
            revised = self._revise_value(refined, previous_binding)
            self._bind(
                value_id, refined, BindingKind.REFINED, previous_binding, revised,
            )
            self.arguments[:] = [
                refined if item is value else item for item in self.arguments
            ]
            value = refined
        return value

    def _sequence_contract_cell(self, sequence_id: int) -> Ref | None:
        """The ``sequence_contract_concordance`` cell of a resident sequence
        under this function's scopes, if committed."""

        book = self._book()
        page = book.pages.get("sequence_contract_concordance")
        if page is None:
            return None
        for scope in (
            self.function_name, str(self.tensor_shape_concordance_scope),
            self.lexical_read_scope,
        ):
            if scope is None:
                continue
            cell = self._declared_cell(
                "sequence_contract_concordance", (scope, int(sequence_id)),
            )
            if cell is not None:
                return cell
        return None

    def _value_from_meta(
        self, value_id: int, *, dtype: str | None = None
    ) -> SSAValue:
        """An SSA value carrying whatever the owning region already knows.

        The control program names values that regions define; only the region
        records their dtype and shape.  Building the value without that turns
        an array into a shapeless scalar, which every pointer-based backend
        tolerates and Fortran cannot express.
        """

        meta = self.region_value_meta.get(int(value_id))
        if meta is None:
            return SSAValue(int(value_id), dtype=dtype)
        value = _ssa_value(int(value_id), meta)
        if dtype is None:
            return value
        return SSAValue(
            value.id,
            dtype=str(dtype),
            shape=tuple(value.shape),
            device=value.device,
            accounting=dict(value.accounting),
        )

    def _defines(self, value: SSAValue) -> bool:
        """Whether an emitted instruction already defines ``value``."""

        return self.__dict__.get("_defined_results", {}).get(id(value)) is value

    def produced_value(
        self,
        value_id: int,
        *,
        dtype: str | None = None,
        claim_provisional_definition: bool = False,
        cause: tuple = (),
    ) -> SSAValue:
        """The SSA value a definition of graph id ``value_id`` writes.

        ``cause`` names the cells of the definition being emitted (its
        operands): a claim that resolves a provisional binding derives from
        them, so the resolution has the cause the api asks for.
        """

        value_id = int(value_id)
        value = self.external_values.get(value_id)
        # The region that publishes this id, when one does: its
        # ``region_signature`` cell is the cause of a produced binding.
        producer = self._cells(self._producing_region_cell(value_id), *cause)
        if value is not None:
            if value in self.arguments:
                if (
                    claim_provisional_definition
                    and value_id not in self.inout_value_ids
                ):
                    # Region/control construction is not lexical emission
                    # order.  A later-emitted coordinator load can therefore
                    # be the real definition of a value that an earlier-built
                    # region call provisionally exposed as a root argument.
                    # Keep the same SSAValue object so all already-built uses
                    # now refer to this definition, and retire only its
                    # provisional public-ABI role.  This is exact for loop
                    # projections: the coordinator owns the definition and
                    # the value is explicitly not in/out storage.
                    self.arguments.remove(value)
                    if dtype is not None:
                        value.dtype = str(dtype)
                    # REGION_RESULT: the claim resolves the PROVISIONAL row.
                    revised = self._revise_value(value, *producer)
                    self._bind(
                        value_id, value, BindingKind.REGION_RESULT,
                        *producer, revised,
                    )
                    return value
                # A preallocated arena is commonly both the initial value
                # entering control and the destination published by a later
                # region.  SSA versions the write; it is not an identity
                # conflict.  The source value ID stays in accounting so the
                # public arena-address policy can rotate the two versions.
                previous = value
                value = self.fresh_value(
                    dtype=dtype or value.dtype,
                    shape=tuple(value.shape),
                    transform=VERSIONED_WRITE,
                    operands=(self._binding_cell(value_id), previous),
                )
                value.accounting.update({
                    **dict(self.external_values[value_id].accounting or {}),
                    "source_value_id": value_id,
                    **(
                        {"ssa_inout_write_version": True}
                        if value_id in self.inout_value_ids else {}
                    ),
                })
                self._bind(
                    value_id, value, BindingKind.VERSIONED_WRITE, *producer,
                )
                return value
            if self._defines(value) and self.__dict__.get("_latch_test_generation"):
                # Program: ``while index < count and everything[index] ==
                # position:`` (c37_while_in_for).  Wrong record: the latch
                # re-evaluates the test, re-emitting the row load of 11 with
                # the SAME SSAValue object as the entry evaluation; region
                # calls bind arguments by id, so the later repair clone
                # (``freshen_redefined_ssa_objects``) never reached them and
                # the latch compared the entry's row.  Rule: a value the
                # latch's re-evaluation of the test defines again is the
                # test's next generation -- a VERSIONED_WRITE bound to the
                # id, exactly as for a preallocated argument.  The
                # generation keeps the identity's recorded type (the reuse
                # it replaces kept the incumbent object's dtype): a
                # redefining producer's own claim (a region view's float64,
                # tuple_loop_row_handle_contract value 18) does not retype it.
                # The recorded type is the identity's ``ssa_value`` row:
                # ``_merge_partitions.resident``'s row load 14 was posted
                # float64 by region planning while its entry object still
                # read 'unknown', and a generation copying the object was
                # minted with no dtype ("unresolved physical transport").
                recorded = self._book().latest_ref(
                    SSA_VALUE, (self._scope(), int(value_id)),
                )
                recorded_fact = (
                    None if recorded is None
                    else self._book().page(SSA_VALUE).cell(
                        recorded.row, recorded.column,
                    )
                )
                recorded_dtype = (
                    recorded_fact.dtype
                    if isinstance(recorded_fact, SSAValueFact)
                    and recorded_fact.dtype not in {None, "", "unknown"}
                    else None
                )
                previous = value
                value = self.fresh_value(
                    dtype=recorded_dtype or value.dtype or dtype,
                    shape=tuple(value.shape),
                    transform=VERSIONED_WRITE,
                    operands=(self._binding_cell(value_id), previous),
                )
                value.accounting.update({
                    **dict(previous.accounting or {}),
                    "source_value_id": value_id,
                })
                self._bind(
                    value_id, value, BindingKind.VERSIONED_WRITE, *producer,
                )
            elif (
                str(value.dtype or "unknown") in {"", "unknown"}
                and str(dtype or "unknown") not in {"", "unknown"}
                and not self._defines(value)
                and getattr(self._binding_fact(value_id), "kind", None) is BindingKind.LOOP_SEED
            ):
                # A control-only ``previous = value`` loop reserves its
                # backedge before the static iterable Load proves int64.
                # The reservation has no definition/type yet; the exact
                # producer must resolve its one object AND posted row.
                value.dtype = str(dtype)
                revised = self._revise_value(value, *producer)
                self._bind(value_id, value, BindingKind.REGION_RESULT, *producer, revised)
            return value
        value = self._value_from_meta(value_id, dtype=dtype)
        self._bind(value_id, value, BindingKind.REGION_RESULT, *producer)
        return value

    def _declaring_region_cell(self, value_id: int) -> Ref | None:
        """The ``region_signature`` cell of the first region whose feeds or
        outputs name ``value_id``, when one is on the book: the control
        program's own declaration of the id."""

        for region_index, (feeds, outputs) in self.region_signatures.items():
            if int(value_id) in outputs or int(value_id) in feeds:
                cell = self._declared_cell(
                    REGION_SIGNATURE.name, (self._scope(), int(region_index)),
                )
                if cell is not None:
                    return cell
        return None

    def _producing_region_cell(self, value_id: int) -> Ref | None:
        """The ``region_signature`` cell of the region whose outputs name
        ``value_id``, when one is on the book."""

        for region_index, (_feeds, outputs) in self.region_signatures.items():
            if int(value_id) in outputs:
                return self._declared_cell(
                    REGION_SIGNATURE.name, (self._scope(), int(region_index)),
                )
        return None

    def constant_value(
        self, literal: int, *operands: Any, dtype: str = "int",
    ) -> SSAValue:
        """An int literal the builder needs: CONTROL_CONST from ``operands``
        (the cells of what the literal indexes or bounds; a bare literal has
        no identity cell of its own and names the function root).

        A literal that enters a loop Phi takes the Phi's dtype: an ``int``
        zero entering an ``int64`` index Phi (or an ``int`` False entering a
        ``bool`` accumulator) is a representation change no Phi can make,
        and the LLVM lane refused every resident ``sum``/``any``/``count``
        loop on it (lane E)."""

        value = self.fresh_value(
            dtype=dtype, transform=CONTROL_CONST, operands=operands,
        )
        self.emit(
            Handler.Const,
            [],
            value,
            attributes={"value": int(literal)},
        )
        return value

    def indexed_load(
        self,
        source: SSAValue,
        index: SSAValue | tuple[SSAValue, ...] | list[SSAValue],
        result_id: int,
        *,
        attributes: dict[str, Any],
        claim_provisional_definition: bool = False,
        element_dtype: str | None = None,
        element_dtype_cell: Ref | None = None,
    ) -> SSAValue:
        indices = (
            tuple(index)
            if isinstance(index, (tuple, list))
            else (index,)
        )
        row_shape = tuple(map(
            int,
            (source.accounting or {}).get("sequence_row_shape") or (),
        ))
        if row_shape and len(indices) == 1:
            # A shaped sequence column is one flat arena. Selecting row i is
            # an address view at i * elements_per_row; it neither loads one
            # scalar nor materializes a second tensor object.
            linear_index = indices[0]
            row_width = math.prod(row_shape)
            if row_width != 1:
                offset = self.fresh_value(
                    dtype="int64", transform=CONTROL_EXPRESSION,
                    operands=(linear_index, source),
                )
                self.emit(
                    Handler.Mul,
                    [linear_index, self.constant_value(int(row_width), source)],
                    offset,
                    attributes={
                        **attributes,
                        "binding": "shaped_sequence_row_offset",
                        "row_shape": row_shape,
                    },
                )
                linear_index = offset
            result = self.produced_value(
                result_id,
                dtype=str(
                    (source.accounting or {}).get("heap_element_dtype")
                    or source.dtype or "unknown"
                ),
                claim_provisional_definition=claim_provisional_definition,
                cause=(source, linear_index),
            )
            result.shape = row_shape
            self._revise_value(result, source)
            self.emit(
                Handler.GetElementPtr,
                [source, linear_index],
                result,
                attributes={
                    **attributes,
                    "binding": "shaped_sequence_row_view",
                    "row_shape": row_shape,
                },
            )
            return result
        address = self.fresh_value(
            dtype="ptr", transform=ADDRESS, operands=(source, *indices),
        )
        self.emit(
            Handler.GetElementPtr,
            [source, *indices],
            address,
            attributes=attributes,
        )
        # A projection out of an ``ssa.aggregate`` handle is the region's
        # declared value, not the handle: the aggregate's dtype on a region
        # output typed a function's return merge as an aggregate, and the
        # caller's native result contract then returned a handle with no
        # scalar buffer (the managed window's ``dt_next`` read 0).
        # A heap column is its ``ptr`` CELL; the rows it addresses are its
        # ``heap_element_dtype`` (``heap_allocate``), the one element record
        # the C and LLVM lanes read too.
        dtype = str(
            (source.accounting or {}).get("heap_element_dtype")
            or source.dtype or "unknown"
        )
        if dtype == "ssa.aggregate":
            declared = self._value_from_meta(int(result_id))
            # Program: three calls validate([0, 1]), validate([False, True]),
            # validate([0, 2]) against ``offsets: list[int]``.  Wrong record:
            # the bool call's Load inherited int64 from generic target meta
            # while its exact resident descriptor column and target ABI were
            # bool.  Rule: when the exact descriptor cell is present, its
            # element dtype owns this Load; generic metadata cannot override
            # the column, and the target ABI must confirm the same view.
            dtype = str(
                element_dtype
                if element_dtype_cell is not None and element_dtype
                else declared.dtype or element_dtype or "unknown"
            )
        result = self.produced_value(
            result_id,
            dtype=dtype,
            claim_provisional_definition=claim_provisional_definition,
            cause=(address,),
        )
        if element_dtype_cell is not None:
            canonical = self._canonical_cell(int(result_id))
            if canonical is None:
                raise ValueError(
                    "descriptor-typed static iterable Load has no exact "
                    f"canonical target identity: {int(result_id)}"
                )
            physical = _contract_physical(
                self._book(), result, canonical, dtype=dtype,
            )
            if (
                physical is None
                and self._book().current_ref(
                    VALUE_TYPE_ABI, canonical.row,
                ) is None
                and not tuple(result.shape or ())
            ):
                # Program: ``for x in [1, 5, 9]: ...`` in a root (c156).  A
                # target of a LOCAL literal list has no ProgramABI contract
                # row to disagree with; the exact descriptor column is the
                # whole proof, so the element is a scalar of its dtype.  A
                # contract row that exists and does not match still refuses.
                physical = (
                    {"storage": "scalar", "rank": 0}, element_dtype_cell,
                )
            if physical is None:
                raise ValueError(
                    "descriptor-typed static iterable Load has no matching "
                    f"target ABI physical view: {int(result_id)} as {dtype}"
                )
            # Keep the resident object and its authoritative SSA_VALUE row in
            # step.  The exact descriptor and target ABI cells are the causes
            # of this physical Load; without a matching target contract the
            # Load has no proven native element view and lowering must refuse.
            result.dtype = dtype
            physical_fields, target_abi = physical
            self._revise_value(
                result, address, element_dtype_cell, canonical, target_abi,
                physical={
                    **_declared_physical_dtype(dtype),
                    **physical_fields,
                },
            )
        self.emit(Handler.Load, [address], result, attributes=attributes)
        return result

    def _declare_sequence_column_type_abis(self) -> None:
        """Concord heterogeneous mapping writers into column-wide ABIs.

        Each authored value already owns a ``VALUE_TYPE_ABI`` row.  A native
        table column is one storage location across every update, so its ABI
        is the exact union of those writer rows, derived before the first
        store is lowered.  This prevents visitation order from choosing the
        column dtype and gives readers/writers one stable tag vocabulary.
        """

        writers: dict[tuple[int, int], list[int]] = {}

        def walk(block: Any) -> None:
            for child in _flatten_control_sequence(block):
                if isinstance(child, SequenceMutationBlock):
                    mutation = child.mutation
                    if (
                        mutation.operator == "update"
                        and mutation.argument_kind == "mapping_items"
                    ):
                        values = tuple(map(int, mutation.argument_value_ids))
                        for value_id in values[1::2]:
                            writers.setdefault(
                                (int(mutation.sequence_value_id), 1), []
                            ).append(value_id)
                for _arm, _index, children in _control_block_arms(child):
                    for grandchild in children:
                        walk(grandchild)

        walk(self.program.root)
        for key, value_ids in writers.items():
            arms_by_identity: dict[str, ValueTypeABIAlternative] = {}
            source_cells: list[Ref] = []
            for value_id in dict.fromkeys(value_ids):
                fact = self.native_value_type_abi.get(int(value_id))
                if fact is None:
                    continue
                fact_arms = tuple(
                    fact.get("physical_alternatives", ())
                    if isinstance(fact, Mapping)
                    else getattr(fact, "physical_alternatives", ())
                )
                type_cell = (
                    None if self.lexical_read_scope is None else
                    self._book().latest_ref(
                        VALUE_TYPE_ABI,
                        (self.lexical_read_scope, int(value_id)),
                    )
                )
                if type_cell is not None and type_cell not in source_cells:
                    source_cells.append(type_cell)
                for arm in fact_arms:
                    identity = str(arm.identity)
                    incumbent = arms_by_identity.get(identity)
                    if incumbent is not None:
                        physical = (
                            arm.storage, arm.dtype, arm.shape, arm.rank,
                            arm.storage_identity, arm.metadata_state,
                            arm.row_shape,
                        )
                        incumbent_physical = (
                            incumbent.storage, incumbent.dtype,
                            incumbent.shape, incumbent.rank,
                            incumbent.storage_identity,
                            incumbent.metadata_state, incumbent.row_shape,
                        )
                        if physical != incumbent_physical:
                            raise ValueError(
                                "sequence column type alternative has "
                                "conflicting physical ABI: "
                                f"sequence={key[0]}, column={key[1]}, "
                                f"identity={identity!r}, "
                                f"first={incumbent_physical!r}, "
                                f"incoming={physical!r}"
                            )
                        arm = ValueTypeABIAlternative(
                            identity, arm.storage, arm.dtype, arm.shape,
                            arm.rank, arm.storage_identity,
                            tuple(dict.fromkeys((
                                *incumbent.source_cells,
                                *arm.source_cells,
                            ))),
                            arm.metadata_state, arm.row_shape,
                        )
                    arms_by_identity[identity] = arm
            alternatives = tuple(sorted(arms_by_identity))
            if len(alternatives) <= 1:
                continue
            physical = tuple(
                arms_by_identity[identity] for identity in alternatives
            )
            fact = ValueTypeABIFact(
                alternatives,
                tuple(
                    (identity, ordinal)
                    for ordinal, identity in enumerate(alternatives)
                ),
                physical,
            )
            row = (self._scope(), int(key[0]), int(key[1]))
            self._book().post(
                SEQUENCE_COLUMN_TYPE_ABI, row, fact,
                stage=CONTROL_SSA_ENTRY,
                provenance=Derived(tuple(source_cells) or (
                    self._function_root(),
                )),
                mode=Mode.CONCORD,
            )
            self.sequence_column_type_abi[key] = fact

    def _native_type_tag_sequence_column(
        self, iterable_id: int, column_projection: int, target_id: int,
        fact: object | None = None,
    ) -> tuple[SSAValue, object] | None:
        """Return the resident tag arena for an exact projected value.

        The projected value's VALUE_TYPE_ABI cell owns the alternative table.
        This parallel int64 column is only its physical sequence view; a later
        predicate is never allowed to define or widen that table.
        """
        if fact is None:
            fact = self.native_value_type_abi.get(int(target_id))
        alternatives = tuple(
            fact.get("alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "alternatives", ())
        )
        if len(alternatives) <= 1:
            return None
        physical = tuple(
            fact.get("physical_alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "physical_alternatives", ())
        )
        if tuple(getattr(arm, "identity", None) for arm in physical) != alternatives:
            raise ValueError(
                "native union merge has no exact ordered physical arms: "
                f"{physical!r}"
            )
        tags = tuple(
            fact.get("tags", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "tags", ())
        )
        material_arms = tuple(
            arm for arm in physical if str(arm.storage) != "none"
        )
        shared_payload = bool(material_arms) and len({
            (
                str(arm.storage), str(arm.dtype),
                tuple(arm.shape or ()), int(arm.rank),
                tuple(arm.storage_identity or ()),
            )
            for arm in material_arms
        }) == 1 and all(
            str(arm.storage) not in {"sequence", "record"}
            for arm in material_arms
        )
        storage = self.sequence_storage_values.get(int(iterable_id))
        if shared_payload and (
            storage is None
            or not 0 <= int(column_projection) < len(storage)
        ):
            # The union record describes the semantic alternatives, but it
            # does not create the iterable's physical payload arena.  A
            # mapping/iterator consumer must read that producer-owned arena;
            # manufacturing a column here would sever its storage identity.
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", "missing-union-payload-column",
                self.function_name,
                f"projected union value {int(target_id)} reads column "
                f"{int(column_projection)} of iterable {int(iterable_id)}, "
                "which has no published resident sequence payload",
            ))
            return None
        key = (int(iterable_id), int(column_projection))
        source = self.variant_type_tag_columns.get(key)
        if source is None:
            # Program: a heterogeneous resident sequence read through its
            # union tag column (test_precompile_contract_rows.py).  Wrong
            # record: every column projection below carried span/rank 1 only
            # in accounting.  Rule: a table column IS a one-axis span by
            # construction -- that literal is the DECLARATION of the
            # construct, posted Novel at the mint (``physical=``), and the
            # accounting is set from the posted fact.
            _column_physical = {"storage": "span", "rank": 1}
            source = self.fresh_value(
                dtype="int64", transform=ROW_COLUMN_PROJECTION,
                operands=(int(iterable_id), int(target_id)),
                physical=_column_physical,
            )
            parameter_name = next((
                str(name) for name, history in self.value_name_histories.items()
                if int(iterable_id) in tuple(map(int, history))
            ), None)
            source.accounting.update({
                "native_type_tag_sequence_for_value_id": int(iterable_id),
                "native_type_tag_projection": int(column_projection),
                "native_type_alternatives": alternatives,
                "native_type_tags": tags,
                **({
                    "native_type_tag_sequence_parameter": parameter_name,
                    "program_abi_parameter": parameter_name,
                } if parameter_name is not None else {}),
                **self._posted_physical_accounting(source),
            })
            self.arguments.append(source)
            self.variant_type_tag_columns[key] = source
            payload_columns = {}
            shared_column = None
            if shared_payload:
                shared_column = storage[int(column_projection)]
            for arm in physical:
                identity = str(arm.identity)
                storage = str(arm.storage)
                if storage == "none":
                    continue
                if shared_column is not None:
                    # Equal physical arms share the logical payload arena;
                    # the parallel tag alone distinguishes their semantic
                    # identities.  IdentityPage fact values are the canonical
                    # example: every admitted class is one opaque native
                    # reference handle, not one Python-shaped payload column
                    # per class.
                    self.variant_type_payload_columns[
                        (int(iterable_id), int(column_projection), identity)
                    ] = shared_column
                    payload_columns[identity] = int(shared_column.id)
                    continue
                if storage == "sequence":
                    # A heterogeneous table stores a descriptor identity for
                    # an aggregate arm, never the aggregate's Python object
                    # or its inline elements.  The module sequence table owns
                    # the descriptor addressed by this fixed-width handle.
                    payload = self.fresh_value(
                        dtype="int64",
                        transform=ROW_COLUMN_PROJECTION,
                        operands=(int(iterable_id), int(target_id), identity),
                        physical=_column_physical,
                    )
                    payload.accounting.update({
                        "native_value_union_sequence_for_value_id": int(
                            iterable_id
                        ),
                        "native_value_union_projection": int(
                            column_projection
                        ),
                        "native_value_union_alternative": identity,
                        "native_value_union_storage_identity": tuple(
                            arm.storage_identity
                        ),
                        "descriptor_handle_column": True,
                        "compiler_frame_storage": str(self.function_name),
                        "compiler_frame_sequence_id": int(iterable_id),
                        "compiler_frame_member": (
                            "value_union", int(column_projection), identity,
                        ),
                        **self._posted_physical_accounting(payload),
                    })
                    self.arguments.append(payload)
                    self.variant_type_payload_columns[
                        (int(iterable_id), int(column_projection), identity)
                    ] = payload
                    payload_columns[identity] = int(payload.id)
                    continue
                if storage in {"record", "reference"}:
                    raise ValueError(
                        "heterogeneous resident sequence arm requires an "
                        "exact nested descriptor-backed payload column: "
                        f"sequence={int(iterable_id)}, projection="
                        f"{int(column_projection)}, arm={identity!r}, "
                        f"storage={storage!r}"
                    )
                payload = self.fresh_value(
                    dtype=str(arm.dtype or "unknown"),
                    shape=tuple(arm.shape or ()),
                    transform=ROW_COLUMN_PROJECTION,
                    operands=(int(iterable_id), int(target_id), identity),
                    physical=_column_physical,
                )
                payload.accounting.update({
                    "native_value_union_sequence_for_value_id": int(
                        iterable_id
                    ),
                    "native_value_union_projection": int(column_projection),
                    "native_value_union_alternative": identity,
                    "native_value_union_storage_identity": tuple(
                        arm.storage_identity
                    ),
                    "compiler_frame_storage": str(self.function_name),
                    "compiler_frame_sequence_id": int(iterable_id),
                    "compiler_frame_member": (
                        "value_union", int(column_projection), identity,
                    ),
                    **self._posted_physical_accounting(payload),
                    "sequence_row_shape": tuple(arm.shape or ()),
                })
                self.arguments.append(payload)
                self.variant_type_payload_columns[
                    (int(iterable_id), int(column_projection), identity)
                ] = payload
                payload_columns[identity] = int(payload.id)
            subject = self.external_values.get(int(iterable_id))
            if subject is not None and payload_columns:
                subject.accounting = {
                    **dict(subject.accounting or {}),
                    "native_value_union_sequence_columns": tuple(sorted(
                        (
                            int(column_projection), str(identity),
                            int(value_id),
                        )
                        for identity, value_id in payload_columns.items()
                    )),
                }
            owner = self.external_value(int(iterable_id))
            columns = dict((owner.accounting or {}).get(
                "native_type_tag_sequence_columns", ()
            ))
            columns[int(column_projection)] = int(source.id)
            owner.accounting = {
                **dict(owner.accounting or {}),
                "native_type_tag_sequence_columns": tuple(sorted(
                    (int(column), int(value_id))
                    for column, value_id in columns.items()
                )),
            }
        return source, fact

    def projected_native_type_tag(
        self, iterable_id: int, column_projection: int,
        projection_index: SSAValue, target_id: int,
    ) -> SSAValue | None:
        """Load a projected element's parallel native type discriminant."""

        existing = self.native_value_type_tags.get(int(target_id))
        if (
            existing is not None
            and int((existing.accounting or {}).get(
                "native_type_tag_pending_for_value_id", -1
            )) != int(target_id)
        ):
            return existing

        resident = self._native_type_tag_sequence_column(
            int(iterable_id), int(column_projection), int(target_id),
        )
        if resident is None:
            return None
        source, fact = resident
        alternatives = tuple(
            fact.get("alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "alternatives", ())
        )
        tags = tuple(
            fact.get("tags", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "tags", ())
        )
        physical = tuple(
            fact.get("physical_alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "physical_alternatives", ())
        )
        address = self.fresh_value(
            dtype="ptr", transform=ADDRESS,
            operands=(source, projection_index),
        )
        self.emit(
            Handler.GetElementPtr, [source, projection_index], address,
            attributes={
                "binding": "projected_native_type_tag_address",
                "iterable_id": int(iterable_id),
                "projection": int(column_projection),
                "target_value_id": int(target_id),
            },
        )
        tag = self.native_value_type_tags.get(int(target_id))
        if not (
            tag is not None
            and tag in self.arguments
            and int((tag.accounting or {}).get(
                "native_type_tag_pending_for_value_id", -1
            )) == int(target_id)
        ):
            tag = self.fresh_value(
                dtype="int64", transform=LOAD, operands=(address,),
            )
        else:
            # A predicate may be constructed before the coordinator emits
            # this row load.  Claim its exact provisional tag object so every
            # already-built comparison now reads the resident parallel tag,
            # just as ``indexed_load(... claim_provisional_definition=True)``
            # claims the payload object.
            self.arguments.remove(tag)
            tag.dtype = "int64"
            tag.accounting.pop("native_type_tag_pending_for_value_id", None)
            self._revise_value(tag, address)
        tag.accounting.update({
            "native_type_tag_for_value_id": int(target_id),
            "native_type_alternatives": alternatives,
            "native_type_tags": tags,
        })
        self.emit(
            Handler.Load, [address], tag,
            attributes={
                "binding": "projected_native_type_tag",
                "iterable_id": int(iterable_id),
                "projection": int(column_projection),
                "target_value_id": int(target_id),
            },
        )
        self.native_value_type_tags[int(target_id)] = tag
        type_abi_cell = (
            None if self.lexical_read_scope is None else
            self._book().latest_ref(
                VALUE_TYPE_ABI,
                (self.lexical_read_scope, int(target_id)),
            )
        )
        tag_cell = self._book().latest_ref(
            SSA_VALUE, (self._scope(), int(tag.id)),
        )
        if type_abi_cell is None or tag_cell is None:
            raise ValueError(
                "projected native type tag has no ABI/value provenance: "
                f"{self.function_name} value {int(target_id)}"
            )
        self._book().post(
            VALUE_TYPE_TAG,
            (self._scope(), int(target_id), int(tag.id)),
            ValueTypeTagFact(int(tag.id), alternatives, tags),
            stage=self._stage(),
            provenance=Derived(self._cells(type_abi_cell, tag_cell, source)),
            mode=Mode.CONCORD,
        )
        payloads = {}
        material_arms = tuple(
            arm for arm in physical if str(arm.storage) != "none"
        )
        shared_payload = bool(material_arms) and len({
            (
                str(arm.storage), str(arm.dtype), tuple(arm.shape or ()),
                int(arm.rank), tuple(arm.storage_identity or ()),
            )
            for arm in material_arms
        }) == 1 and all(
            str(arm.storage) not in {"sequence", "record"}
            for arm in material_arms
        )
        if shared_payload:
            projected = self.external_values.get(int(target_id))
            if projected is None:
                raise ValueError(
                    "shared native union projection has no resident payload: "
                    f"sequence={int(iterable_id)}, target={int(target_id)}"
                )
            shared_arm = material_arms[0]
            projected.dtype = str(shared_arm.dtype or "unknown")
            projected.shape = tuple(shared_arm.shape or ())
            payloads.update({
                str(arm.identity): (projected,) for arm in material_arms
            })
        for arm in physical:
            identity = str(arm.identity)
            if str(arm.storage) == "none":
                payloads[identity] = ()
                continue
            if shared_payload:
                continue
            column = self.variant_type_payload_columns.get((
                int(iterable_id), int(column_projection), identity,
            ))
            if column is None:
                raise ValueError(
                    "projected native union has no exact alternative payload "
                    f"column: sequence={int(iterable_id)}, arm={identity!r}"
                )
            row_shape = tuple(arm.shape or ())
            row_index = projection_index
            if row_shape and math.prod(row_shape) != 1:
                row_index = self.fresh_value(
                    dtype="int64", transform=CONTROL_EXPRESSION,
                    operands=(projection_index, column),
                )
                self.emit(
                    Handler.Mul,
                    [projection_index, self.constant_value(
                        int(math.prod(row_shape)), column,
                    )],
                    row_index,
                    attributes={
                        "binding": "projected_native_value_union_arm_offset",
                        "alternative": identity,
                    },
                )
            payload_address = self.fresh_value(
                dtype="ptr", transform=ADDRESS,
                operands=(column, row_index),
            )
            self.emit(
                Handler.GetElementPtr, [column, row_index], payload_address,
                attributes={
                    "binding": "projected_native_value_union_arm_address",
                    "iterable_id": int(iterable_id),
                    "projection": int(column_projection),
                    "alternative": identity,
                },
            )
            payload_dtype = (
                "int64" if str(arm.storage) == "sequence"
                else str(arm.dtype or "unknown")
            )
            payload_shape = (
                () if str(arm.storage) == "sequence" else row_shape
            )
            payload = (
                payload_address if payload_shape else self.fresh_value(
                    dtype=payload_dtype, transform=LOAD,
                    operands=(payload_address,),
                )
            )
            if payload_shape:
                payload.dtype = payload_dtype
                payload.shape = payload_shape
            payload.accounting.update({
                "native_value_union_alternative": identity,
                "native_value_union_source_id": int(target_id),
            })
            if not payload_shape:
                self.emit(
                    Handler.Load, [payload_address], payload,
                    attributes={
                        "binding": "projected_native_value_union_arm",
                        "iterable_id": int(iterable_id),
                        "projection": int(column_projection),
                        "alternative": identity,
                    },
                )
            payloads[identity] = (payload,)
        self.native_value_union_payloads[int(target_id)] = payloads
        self.publish_native_value_union(int(target_id), tag, fact)
        return tag

    def scheduled_projected_native_type_tag(
        self, target_id: int,
    ) -> SSAValue | None:
        """Materialize a scheduled row projection's tag at its first use.

        Payload scheduling follows numerical regions, while a short-circuit
        ``isinstance(row[i], T)`` belongs to structural control. The row-load
        operation is the authoritative correlation between ``target_id`` and
        its resident sequence/index/column, so its parallel tag can be loaded
        independently without prematurely loading the payload.
        """

        operation = self.sequence_row_load_operations.get(int(target_id))
        if operation is None:
            return None
        (
            result_id, sequence_id, index_id, index_literal, column,
            _row_value_id,
        ) = operation
        if int(result_id) != int(target_id):
            raise ValueError(
                "scheduled row-load result identity changed during type-tag "
                f"projection: expected={int(target_id)}, actual={result_id!r}"
            )
        index = self._sequence_row_index(
            int(sequence_id), int(index_id), index_literal,
        )
        # Shared-layout union arms point at the one logical payload object.
        # Preserve that identity provisionally; the scheduled payload load
        # later claims this same object through ``produced_value``.
        self.external_value(int(target_id))
        return self.projected_native_type_tag(
            int(sequence_id), int(column), index, int(target_id),
        )

    def sequence_native_type_tag_columns(
        self, sequence_id: int,
    ) -> dict[int, tuple[SSAValue, int, object]]:
        """Materialize every declared union companion for ``sequence_id``.

        Projected-iterable bindings are the reducer's exact edges from the
        sequence row to the loop value.  They are therefore the declaration
        authority for a heterogeneous row.  Equal repeated consumers share
        one arena; disagreeing consumers are concordance failure, not an
        opportunity to choose a table locally.
        """

        declared: dict[int, tuple[tuple, int, object]] = {}
        for (declared_sequence, column), fact in (
            self.sequence_column_type_abi.items()
        ):
            if int(declared_sequence) != int(sequence_id):
                continue
            alternatives = tuple(fact.alternatives)
            tags = tuple(fact.tags)
            writer_id = next(
                (
                    int(value_id)
                    for child in _flatten_control_sequence(self.program.root)
                    if isinstance(child, SequenceMutationBlock)
                    and int(child.mutation.sequence_value_id)
                    == int(sequence_id)
                    and child.mutation.argument_kind == "mapping_items"
                    for value_id in child.mutation.argument_value_ids[1::2]
                ),
                int(sequence_id),
            )
            declared[int(column)] = (
                (alternatives, tags), writer_id, fact,
            )
        for iterable_id, target_id, _induction, projection in (
            self.program.projected_iterable_bindings
        ):
            if int(iterable_id) != int(sequence_id) or projection is None:
                continue
            if (
                isinstance(projection, tuple)
                and len(projection) == 3
                and projection[0] == "column_at_value"
            ):
                column = int(projection[1])
            elif isinstance(projection, int):
                column = int(projection)
            else:
                continue
            fact = self.native_value_type_abi.get(int(target_id))
            alternatives = tuple(
                fact.get("alternatives", ())
                if isinstance(fact, Mapping)
                else getattr(fact, "alternatives", ())
            )
            if len(alternatives) <= 1:
                continue
            tags = tuple(
                fact.get("tags", ())
                if isinstance(fact, Mapping)
                else getattr(fact, "tags", ())
            )
            signature = (alternatives, tags)
            incumbent = declared.get(column)
            if incumbent is not None and incumbent[0] != signature:
                raise ValueError(
                    "sequence projection consumers disagree on the linked "
                    f"native type ABI: function={self.function_name!r}, "
                    f"sequence={int(sequence_id)}, column={column}, "
                    f"first={incumbent[0]!r}, incoming={signature!r}"
                )
            declared[column] = (signature, int(target_id), fact)
        result = {}
        for column, (_signature, target_id, fact) in declared.items():
            resident = self._native_type_tag_sequence_column(
                int(sequence_id), int(column), int(target_id), fact,
            )
            if resident is not None:
                result[int(column)] = (resident[0], int(target_id), fact)
        return result

    def sequence_native_value_union_columns(
        self, sequence_id: int,
    ) -> dict[int, tuple[tuple[object, SSAValue], ...]]:
        """Return each heterogeneous logical column's physical arm arenas.

        Calling :meth:`sequence_native_type_tag_columns` first is
        intentional: it materializes the tag and all arm arenas from the
        same authoritative VALUE_TYPE_ABI row.  Writers and copies consume
        this view instead of treating the logical column as a shared union
        payload.
        """

        tags = self.sequence_native_type_tag_columns(int(sequence_id))
        result: dict[int, tuple[tuple[object, SSAValue], ...]] = {}
        for column, (_tag, _target_id, fact) in tags.items():
            physical = tuple(
                fact.get("physical_alternatives", ())
                if isinstance(fact, Mapping)
                else getattr(fact, "physical_alternatives", ())
            )
            arms = []
            seen_payloads = set()
            for arm in physical:
                if str(arm.storage) == "none":
                    continue
                payload = self.variant_type_payload_columns.get((
                    int(sequence_id), int(column), str(arm.identity),
                ))
                if payload is None:
                    raise ValueError(
                        "heterogeneous sequence has no exact physical arm "
                        f"column: sequence={int(sequence_id)}, "
                        f"column={int(column)}, arm={str(arm.identity)!r}"
                    )
                if int(payload.id) in seen_payloads:
                    continue
                seen_payloads.add(int(payload.id))
                arms.append((arm, payload))
            result[int(column)] = tuple(arms)
        return result

    def _native_value_union_row_payloads(
        self,
        value_id: int,
        value: SSAValue,
        fact: object,
    ) -> tuple[SSAValue, ...]:
        """Inject one authored value into an authoritative physical row."""

        physical = tuple(
            fact.get("physical_alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "physical_alternatives", ())
        )
        resident_value_id = self._concorded_resident(int(value_id))
        source_fact = (
            self.native_value_type_abi.get(int(value_id))
            or self.native_value_type_abi.get(resident_value_id)
        )
        source_alternatives = tuple(
            source_fact.get("alternatives", ())
            if isinstance(source_fact, Mapping)
            else getattr(source_fact, "alternatives", ())
        )
        if not source_alternatives:
            exact = dict(value.accounting or {}).get("native_exact_type")
            if exact is not None:
                source_alternatives = (str(exact),)
        retained = (
            self.native_value_union_payloads.get(int(value_id))
            or self.native_value_union_payloads.get(resident_value_id, {})
        )
        material_arms = tuple(
            arm for arm in physical if str(arm.storage) != "none"
        )
        shared_payload = bool(material_arms) and len({
            (
                str(arm.storage), str(arm.dtype), tuple(arm.shape or ()),
                int(arm.rank), tuple(arm.storage_identity or ()),
            )
            for arm in material_arms
        }) == 1 and all(
            str(arm.storage) not in {"sequence", "record"}
            for arm in material_arms
        )
        if shared_payload:
            arm = material_arms[0]
            material_identities = {
                str(candidate.identity) for candidate in material_arms
            }
            if source_alternatives and not (
                material_identities & set(map(str, source_alternatives))
            ):
                # A shared union frame still owns one fixed-width payload
                # slot when the selected semantic arm is storage-free (most
                # commonly ``None``).  The companion tag makes that slot
                # inactive, but the slot itself must retain the declared ABI
                # so callers and callees agree on one physical frame.
                inactive = self.fresh_value(
                    dtype=str(arm.dtype or "unknown"),
                    shape=tuple(arm.shape or ()),
                    transform=CONTROL_CONST,
                    operands=(self._canonical_cell(int(value_id)),),
                )
                self.emit(
                    Handler.Const, [], inactive,
                    attributes={
                        "value": 0,
                        "native_value_union_inactive_shared_payload": True,
                        "native_value_union_source_id": int(value_id),
                    },
                )
                return (inactive,)
            if (
                str(value.dtype or "unknown") == "unknown"
                and tuple(value.shape or ()) == tuple(arm.shape or ())
                and self.native_value_type_abi.get(int(value_id)) is fact
            ):
                # Program: ``def wrap(r, f): return maybe(r, f)`` where
                # ``maybe`` returns ``r + 1 if f > 0 else None``.  Wrong
                # record: the forwarded call result is not linked yet, so its
                # SSA object has no dtype, and an untyped value was read as a
                # disagreement with its own union frame.  Rule: the value's
                # own VALUE_TYPE_ABI row types its shared payload slot.
                value.dtype = str(arm.dtype)
                self._revise_value(value, self._book().current_ref(
                    VALUE_TYPE_ABI, (self.lexical_read_scope, int(value_id)),
                ))
            if (
                str(value.dtype or "unknown")
                != str(arm.dtype or "unknown")
                or tuple(value.shape or ()) != tuple(arm.shape or ())
            ):
                raise ValueError(
                    "shared heterogeneous sequence payload changes its "
                    f"physical ABI: value={int(value_id)}, "
                    f"payload={(value.dtype, value.shape)!r}, "
                    f"declared={(arm.dtype, arm.shape)!r}"
                )
            return (value,)
        result = []
        for arm in physical:
            identity = str(arm.identity)
            storage = str(arm.storage)
            if storage == "none":
                continue
            if storage == "sequence":
                # A row stores the fixed-width handle of an already resident
                # sequence descriptor.  This is not the same relation as
                # ``native_value_union_sequence_ids``: that table describes
                # side-by-side sequence arms owned by a *union parameter*.
                # An exact locally materialized list has no union tag of its
                # own, but its sequence descriptor is still the authoritative
                # payload named by this heterogeneous row arm.
                sequence_id = (
                    resident_value_id
                    if resident_value_id in self.sequence_descriptors
                    else None
                )
                if sequence_id is not None and source_alternatives == (
                    identity,
                ):
                    handle = self.fresh_value(
                        dtype="int64", transform=CONTROL_CONST,
                        operands=(self._canonical_cell(int(value_id)),),
                    )
                    self.emit(
                        Handler.Const, [], handle,
                        attributes={
                            "value": int(sequence_id),
                            "native_sequence_descriptor_handle_for": int(
                                value_id
                            ),
                            "native_value_union_alternative": identity,
                        },
                    )
                else:
                    handle = self.fresh_value(
                        dtype="int64", transform=CONTROL_CONST,
                        operands=(self._canonical_cell(int(value_id)),),
                    )
                    self.emit(
                        Handler.Const, [], handle,
                        attributes={
                            "value": 0,
                            "native_value_union_inactive_arm": identity,
                            "native_value_union_source_id": int(value_id),
                        },
                    )
                result.append(handle)
                continue
            if storage in {"record", "reference"}:
                # Aggregate arms are expanded by their authoritative
                # descriptor, never coerced into one logical payload cell.
                continue
            payloads = retained.get(identity)
            if payloads is None and source_alternatives == (identity,):
                payloads = (value,)
            if payloads is None:
                inactive = self.fresh_value(
                    dtype=str(arm.dtype or "unknown"),
                    shape=tuple(arm.shape or ()),
                    transform=CONTROL_CONST,
                    operands=(self._canonical_cell(int(value_id)),),
                )
                self.emit(
                    Handler.Const, [], inactive,
                    attributes={
                        "value": 0,
                        "native_value_union_inactive_arm": identity,
                        "native_value_union_source_id": int(value_id),
                    },
                )
                payloads = (inactive,)
            if len(payloads) != 1:
                raise ValueError(
                    "heterogeneous sequence row arm is not one exact "
                    f"scalar/span payload: value={int(value_id)}, "
                    f"arm={identity!r}, payloads={payloads!r}"
                )
            payload = payloads[0]
            if (
                storage == "scalar"
                and int(resident_value_id) != int(value_id)
                and int(payload.id) == int(resident_value_id)
                and str(payload.dtype or "unknown") == "unknown"
                and str(arm.dtype or "unknown") != "unknown"
                and not tuple(arm.shape or ())
            ):
                # A semantic projection may share its resident carrier with
                # a differently named source value (Enum.value is the common
                # case).  The alias establishes identity; the exact physical
                # arm establishes the ctypes scalar layout.  Refine the
                # unresolved external placeholder from those two concorded
                # facts instead of asking the source runtime for a value.
                payload = self.external_value(
                    int(resident_value_id), dtype=str(arm.dtype),
                )
            if (
                str(payload.dtype or "unknown") != str(arm.dtype or "unknown")
                or tuple(payload.shape or ()) != tuple(arm.shape or ())
            ):
                raise ValueError(
                    "heterogeneous sequence row arm changes its physical "
                    f"ABI: value={int(value_id)}, arm={identity!r}, "
                    f"payload={(payload.dtype, payload.shape)!r}, "
                    f"declared={(arm.dtype, arm.shape)!r}"
                )
            result.append(payload)
        return tuple(result)

    def bind_nested_row(
        self,
        source: SSAValue,
        induction: SSAValue,
        target_id: int,
        *,
        child_key: tuple[str, int, int],
        attributes: dict[str, Any],
    ) -> SSAValue:
        """Bind one caller-owned child row selected by an integer handle.

        Nested collections cross the repository ABI as two ordinary tables:
        the outer column contains integer row handles and a flattened child
        arena contains the rows.  This emits the complete address calculation
        into SSA; neither the backend nor a runtime language reconstructs an
        object for the selected row.
        """

        selected_sequence = int(child_key[1]) in (
            self.selected_nested_sequence_ids
        )
        if selected_sequence:
            handle = source
        else:
            handle_address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(source, induction),
            )
            handle = self.fresh_value(
                dtype="int", transform=LOAD, operands=(handle_address,),
            )
            handle_attributes = {
                **attributes, "binding": "nested_row_handle"
            }
            self.emit(
                Handler.GetElementPtr,
                [source, induction],
                handle_address,
                attributes=handle_attributes,
            )
            self.emit(
                Handler.Load,
                [handle_address],
                handle,
                attributes=handle_attributes,
            )
        child = self._nested_child_storage(child_key, target_id)
        child_data, child_lengths, sequence_stride, row_stride = child
        self.nested_row_selections[int(target_id)] = (
            child_lengths, handle,
        )
        row_index = induction
        if selected_sequence:
            sequence_offset = self.fresh_value(
                dtype="int", transform=CONTROL_EXPRESSION,
                operands=(handle, sequence_stride),
            )
            row_index = self.fresh_value(
                dtype="int", transform=CONTROL_EXPRESSION,
                operands=(sequence_offset, induction),
            )
            self.emit(
                Handler.Mul,
                [handle, sequence_stride],
                sequence_offset,
                attributes={
                    **attributes, "binding": "nested_sequence_offset"
                },
            )
            self.emit(
                Handler.Add,
                [sequence_offset, induction],
                row_index,
                attributes={
                    **attributes, "binding": "nested_sequence_row"
                },
            )
        offset = self.fresh_value(
            dtype="int", transform=CONTROL_EXPRESSION,
            operands=(row_index if selected_sequence else handle, row_stride),
        )
        row_base = self.fresh_value(
            dtype=str(child_data.dtype or "unknown"),
            transform=ROW_COLUMN_PROJECTION, operands=(child_data, offset),
        )
        row_base.accounting.update({
            "source_value_id": int(target_id),
            # The selected child row is an addressable one-dimensional span,
            # even when its extent is dynamic and therefore absent from
            # ``shape``.  Region-call construction reads this exact physical
            # rank; without it the callee formal was published as a scalar
            # while its first operation was GetElementPtr.
            "ssa_call_rank": 1,
        })
        self.emit(
            Handler.Mul,
            [row_index if selected_sequence else handle, row_stride],
            offset,
            attributes={**attributes, "binding": "nested_row_offset"},
        )
        self.emit(
            Handler.GetElementPtr,
            [child_data, offset],
            row_base,
            attributes={**attributes, "binding": "nested_row_base"},
        )
        self._bind(
            int(target_id), row_base, BindingKind.SEQUENCE_RESULT,
            child_data, offset,
        )
        return row_base

    def bind_selected_child_element(
        self,
        pool: SSAChildTablePoolDescriptor,
        handle: SSAValue,
        induction: SSAValue,
        target_id: int,
        *,
        column: int,
        latch: BasicBlock,
        attributes: Mapping[str, Any],
        claim_provisional_definition: bool = False,
    ) -> SSAValue:
        """Load one element from an already selected child-table row.

        A keyed outer lookup returns the integer handle of its resident child
        row.  The child pool, not that handle, owns element storage: address
        ``handle * row_stride + induction`` in the exact declared column.
        This is the same caller-owned ctypes layout used by child-table
        mutation and extent queries; no host collection is reconstructed.
        """

        column = int(column)
        if column < 0 or column >= len(pool.column_value_ids):
            raise ValueError(
                "selected child-table element names a column outside its "
                f"declared layout: column={column}, "
                f"columns={len(pool.column_value_ids)}"
            )
        row_stride = self.external_value(pool.row_stride_value_id)
        base_offset = self.fresh_value(
            dtype="int", transform=CONTROL_EXPRESSION,
            operands=(handle, row_stride),
        )
        offset = self.fresh_value(
            dtype="int", transform=CONTROL_EXPRESSION,
            operands=(base_offset, induction),
        )
        address = self.fresh_value(
            dtype="ptr", transform=ADDRESS, operands=(offset,),
        )
        target = self.produced_value(
            int(target_id),
            dtype=(
                str(pool.column_dtypes[column])
                if pool.column_dtypes else "unknown"
            ),
            cause=(address,),
            claim_provisional_definition=claim_provisional_definition,
        )
        self.emit(
            Handler.Mul,
            [handle, row_stride],
            base_offset,
            attributes={**dict(attributes), "binding": "child_table_offset"},
        )
        self.emit(
            Handler.Add,
            [base_offset, induction],
            offset,
            attributes={**dict(attributes), "binding": "child_table_offset"},
        )
        if pool.live_flags_value_id is not None:
            live_address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(offset,),
            )
            live = self.fresh_value(
                dtype="bool", transform=LOAD, operands=(live_address,),
            )
            active = self.new_block("child_table_live")
            self.emit(
                Handler.GetElementPtr,
                [self.external_value(pool.live_flags_value_id), offset],
                live_address,
                attributes={**dict(attributes), "binding": "child_table_live"},
            )
            self.emit(
                Handler.Load,
                [live_address],
                live,
                attributes={**dict(attributes), "binding": "child_table_live"},
            )
            self.conditional_branch(live, active, latch)
            self.current = active
        self.emit(
            Handler.GetElementPtr,
            [self.external_value(pool.column_value_ids[column]), offset],
            address,
            attributes={
                **dict(attributes),
                "binding": "child_table_element",
                "child_table_column": column,
            },
        )
        self.emit(
            Handler.Load,
            [address],
            target,
            attributes={
                **dict(attributes),
                "binding": "child_table_element",
                "child_table_column": column,
            },
        )
        self.selected_child_element_values.append((
            pool, column, target, int(attributes.get("iterable_id", -1)),
        ))
        return target

    def settle_selected_child_element_dtypes(self) -> None:
        """Apply settled loop-element dtypes to selected child arenas.

        The loop target can acquire its exact scalar type only after its body
        is lowered (for example, when it becomes a key of another declared
        table).  Child descriptors are created before that body.  Reconcile
        the descriptor at the function boundary from the exact binding edge;
        unknown is absence of a fact, while two concrete dtypes are a real
        ABI disagreement.
        """

        grouped: dict[
            tuple[int, int],
            tuple[SSAChildTablePoolDescriptor, set[str], set[int]],
        ] = {}
        for pool, column, target, iterable_id in (
            self.selected_child_element_values
        ):
            key = (id(pool), int(column))
            _pool, dtypes, iterable_ids = grouped.setdefault(
                key, (pool, set(), set()),
            )
            dtype = str(target.dtype or "unknown")
            if dtype not in {"", "None", "unknown"}:
                dtypes.add(dtype)
            if int(iterable_id) >= 0:
                iterable_ids.add(int(iterable_id))
        for (_pool_identity, column), (
            pool, dtypes, iterable_ids,
        ) in grouped.items():
            if len(dtypes) > 1:
                raise ValueError(
                    "selected child sequence element has conflicting "
                    "physical dtypes: "
                    f"values={tuple(sorted(iterable_ids))!r}, "
                    f"dtypes={tuple(sorted(dtypes))!r}"
                )
            if not dtypes:
                continue
            dtype = next(iter(dtypes))
            incumbent = str(
                pool.column_dtypes[column]
                if pool.column_dtypes else "unknown"
            )
            if incumbent not in {"", "None", "unknown", dtype}:
                raise ValueError(
                    "selected child sequence element changes its physical "
                    f"dtype: values={tuple(sorted(iterable_ids))!r}, "
                    f"declared={incumbent!r}, settled={dtype!r}"
                )
            column_value = self.external_value(
                int(pool.column_value_ids[column])
            )
            column_value_dtype = str(column_value.dtype or "unknown")
            owned_cell = column_value_dtype == "ptr" and (column_value.accounting or {}).get("heap_owner_value_id") is not None
            if owned_cell:
                # The context-owned pool column is a pointer CELL.  Its
                # element layout, not ptr, is the scalar row's type.
                column_value_dtype = str((column_value.accounting or {}).get("heap_element_dtype") or "unknown")
            if column_value_dtype not in {"", "None", "unknown", dtype}:
                raise ValueError(
                    "selected child sequence arena changes its physical "
                    f"dtype: values={tuple(sorted(iterable_ids))!r}, "
                    f"arena={column_value_dtype!r}, settled={dtype!r}"
                )
            if not owned_cell:
                column_value.dtype = dtype
            if incumbent == dtype:
                continue
            column_dtypes = list(pool.column_dtypes or (
                "unknown" for _column in pool.column_value_ids
            ))
            column_dtypes[column] = dtype
            settled_pool = replace(
                pool, column_dtypes=tuple(column_dtypes),
            )
            for selected_id, (candidate, handle) in tuple(
                self.child_table_selections.items()
            ):
                if candidate == pool:
                    self.child_table_selections[selected_id] = (
                        settled_pool, handle,
                    )
            for sequence_id, descriptor in tuple(
                self.sequence_descriptors.items()
            ):
                if descriptor.child_table_pool == pool:
                    self.sequence_descriptors[sequence_id] = replace(
                        descriptor, child_table_pool=settled_pool,
                    )

    def _nested_child_storage(
        self,
        child_key: tuple[str, int, int],
        target_id: int,
    ) -> tuple[SSAValue, SSAValue, SSAValue, SSAValue]:
        child = self.nested_child_rows.get(child_key)
        if child is None:
            target_meta = self.region_value_meta.get(int(target_id))
            # The child arena's four formals descend from the nested source
            # (``child_key[1]``, a graph id) and the target they serve.
            child_operands = (int(child_key[1]), int(target_id))
            child_data = self.fresh_value(dtype=(
                None if target_meta is None else str(target_meta.dtype)
            ), transform=DESCRIPTOR_CELL, operands=child_operands)
            child_lengths = self.fresh_value(
                dtype="int", transform=DESCRIPTOR_CELL, operands=(child_data,),
            )
            sequence_stride = self.fresh_value(
                dtype="int", transform=DESCRIPTOR_CELL, operands=(child_data,),
            )
            row_stride = self.fresh_value(
                dtype="int", transform=DESCRIPTOR_CELL, operands=(child_data,),
            )
            child_data.accounting.update({
                "nested_row_source_kind": str(child_key[0]),
                "nested_row_source_id": int(child_key[1]),
                "nested_row_projection": int(child_key[2]),
            })
            for member, value in enumerate((
                child_data, child_lengths, sequence_stride, row_stride,
            )):
                value.accounting.update({
                    "compiler_frame_storage": str(self.function_name),
                    "compiler_frame_nested_row_source_id": int(
                        child_key[1]
                    ),
                    "compiler_frame_nested_row_member": int(member),
                })
            self.arguments.extend((
                child_data, child_lengths, sequence_stride, row_stride
            ))
            child = (
                child_data, child_lengths, sequence_stride, row_stride
            )
            self.nested_child_rows[child_key] = child
        return child

    def _note_callsite_arguments(
        self, callsite_id: int, argument_ids, arguments,
    ) -> None:
        """Record what one scheduled callsite resolved its arguments to.

        A graph id that resolves to itself inside a loop body means the
        carried machinery did not map it to the current iteration.
        """

        book = self._book()
        for position, (graph_id, value) in enumerate(
            zip(argument_ids, arguments)
        ):
            row = (str(self.function_name), int(callsite_id), position)
            fact = (int(graph_id), int(value.id), bool(self.loop_targets))
            # DERIVED(the ``call_argument_operand`` cell of this position,
            # the resolved binding cell of the argument).
            sources = self._cells(
                self._declared_cell(
                    "call_argument_operand",
                    (self.lexical_read_scope, int(callsite_id), int(position)),
                ) if self.lexical_read_scope is not None else None,
                self._binding_cell(int(graph_id)), value,
            )
            latest = book.latest_ref(CALLSITE_ARGUMENT, row)
            if latest is not None and (
                book.pages[CALLSITE_ARGUMENT.name].cells.get(
                    (row, latest.column)
                ) == fact
            ):
                continue
            book.post(
                CALLSITE_ARGUMENT, row, fact,
                stage=self.active_stage,
                provenance=Derived(sources),
                mode=Mode.REVISE,
            )

    def emit_plan_callsite(self, callsite_id: int, *, location: str) -> None:
        """Lower a scheduled call statement to a placeholder Call.

        Arguments resolve through ``external_value`` at THIS position, which
        is the point of scheduling the call as a statement: inside a loop
        body the carried machinery maps them to the current iteration's
        values, instead of the post-hoc anchor insertion binding whatever id
        the graph happened to record. The placeholder carries the callsite id
        so frame linking can complete callee symbol and bindings in place --
        position from the plan, bindings from the linker.
        """

        bindings = self.plan_callsite_bindings.get(int(callsite_id))
        if bindings is None:
            self.shortfalls.append(SSALoweringShortfall(
                "control", "plan_callsite", location,
                f"scheduled callsite {callsite_id} has no recorded bindings",
            ))
            return
        argument_ids, result_ids = bindings
        arguments = [
            self._callsite_argument(int(callsite_id), position, int(value_id))
            for position, value_id in enumerate(argument_ids)
        ]
        self._note_callsite_arguments(callsite_id, argument_ids, arguments)
        for index, value in enumerate(arguments):
            if self._value_dominates_current_edge(value):
                continue
            # A source-call record can retain an arm's assigned value ID
            # after the conditional has published its merge. Only a unique
            # dominating Phi that explicitly consumes that value can repair
            # the binding; unrelated live values or names are not evidence.
            merges = {
                int(instruction.res.id): instruction.res
                for emitted in self.blocks.values()
                for instruction in emitted.instrs
                if instruction.op == "Phi"
                and instruction.res is not None
                and instruction.attributes.get("binding") == "conditional_carried"
                and any(argument is value for argument in instruction.args)
                and self._value_dominates_current_edge(instruction.res)
            }
            if len(merges) == 1:
                arguments[index] = next(iter(merges.values()))
            elif len(merges) > 1:
                self.shortfalls.append(SSALoweringShortfall(
                    "control", "ambiguous-call-conditional-merge", location,
                    f"callsite {callsite_id} argument {value.id} has multiple "
                    f"dominating conditional merges {sorted(merges)}",
                ))
        marker_attributes = {
            "callee": f"__plan_callsite_{int(callsite_id)}__",
            "plan_callsite_marker": True,
            "plan_callsite_id": int(callsite_id),
            "output_ids": tuple(int(v) for v in result_ids),
        }
        if len(result_ids) > 1:
            # A multi-result call publishes EVERY bound caller result here,
            # at its scheduled position, through the same aggregate
            # convention a region call uses.  Publishing only the first
            # result left the others without a producer at this position;
            # inside a loop body that is exactly the carried update whose
            # latch operand the loop machinery must see produced.  The
            # placeholder projections own the result objects by identity;
            # frame linking rebinds the linked call's projections onto them.
            aggregate = self.fresh_value(
                dtype="ssa.aggregate", transform=REGION_CALL_RESULT,
                operands=tuple(arguments),
            )
            self.emit(
                Handler.Call,
                arguments,
                aggregate,
                attributes={
                    **marker_attributes,
                    "result_convention": "ssa.aggregate",
                },
            )
            for output_index, output_id in enumerate(result_ids):
                projection_attributes = {
                    "plan_callsite_marker_projection": True,
                    "plan_callsite_id": int(callsite_id),
                    "aggregate_index": int(output_index),
                    "source_output_id": int(output_id),
                }
                address = self.fresh_value(
                    dtype="ptr", transform=ADDRESS, operands=(aggregate,),
                )
                self.emit(
                    Handler.GetElementPtr,
                    [aggregate, self.constant_value(output_index, aggregate)],
                    address,
                    attributes=projection_attributes,
                )
                # The projection's dtype/shape are the region-declared facts
                # of the caller result, not the aggregate handle's dtype.
                result = self.produced_value(int(output_id), cause=(address,))
                self.emit(
                    Handler.Load, [address], result,
                    attributes=projection_attributes,
                )
                self.reserve_pending_call_native_union(
                    int(output_id), result,
                )
            self.emitted_plan_callsites.add(int(callsite_id))
            return
        result = None
        if result_ids:
            primary = int(result_ids[0])
            result = self.external_values.get(primary)
            if result is None:
                result = self._value_from_meta(primary)
                # CALL_RESULT: the callsite's argument cells are the cause.
                self._bind(
                    primary, result, BindingKind.CALL_RESULT, *arguments,
                )
            self.reserve_pending_call_native_union(primary, result)
        self.emit(
            Handler.Call,
            arguments,
            result,
            attributes=marker_attributes,
        )
        self.emitted_plan_callsites.add(int(callsite_id))

    def reserve_pending_call_native_union(
        self, value_id: int, value: SSAValue,
    ) -> None:
        """Reserve the concorded tag of a not-yet-linked call result.

        Scheduled calls are placed while control SSA is built, before frame
        linking expands a union return into its physical payload/tag frame.
        A control join may nevertheless consume that tag immediately.  Keep
        one typed, provisional frame value under the result's authoritative
        ``VALUE_TYPE_ABI`` row; ``_propagate_native_type_tag_results`` claims
        it with the linked call's physical tag and removes this temporary
        formal from the completed caller ABI.
        """

        value_id = int(value_id)
        fact = self.native_value_type_abi.get(value_id)
        alternatives = tuple(
            fact.get("alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "alternatives", ())
        )
        if len(alternatives) <= 1 or value_id in self.native_value_type_tags:
            return
        tags = tuple(
            fact.get("tags", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "tags", ())
        )
        tag = self.fresh_value(
            dtype="int64", transform=REGION_FORMAL_SPLIT,
            operands=(self._canonical_cell(value_id), value),
        )
        tag.accounting.update({
            "native_type_tag_pending_for_value_id": value_id,
            "native_type_tag_pending_call_result": True,
            "native_type_alternatives": alternatives,
            "native_type_tags": tags,
        })
        self.arguments.append(tag)
        self.native_value_type_tags[value_id] = tag
        value.accounting = {
            **dict(value.accounting or {}),
            "native_type_tag_value_id": int(tag.id),
            "native_type_alternatives": alternatives,
        }
        self.post_native_type_tag(value_id, tag, fact, value)

    # -- reads resolved through the identity book --------------------------
    #
    # One base fact decides every read: ``lexical_read_binding`` row
    # ``(read scope, consumer, role, ordinal)`` names the authored binding an
    # operand read.  Planner pages record only WHICH operand a lowering
    # operand is (``consumer_operand``, ``call_argument_operand``,
    # ``region_feed_consumer``); a loop's entry state records which bindings
    # it carries under each initial id and their pre-loop value
    # (``loop_entry_state``).  The builder keeps only its position: the
    # loops enclosing the current emission point.

    def _book(self) -> Any:
        from .identity_concordance import current_identity_book

        return current_identity_book()

    # ------------------------------------------- the book's api, step 5
    # Every SSA value this builder mints is a NOVEL ``ssa_value`` row; every
    # graph id it binds is a ``control_value_binding`` revision DERIVED from
    # the cells that caused it (plan 80, part B).  ``external_values`` and
    # ``ssa_value_objects`` are the read views: the dict readers keep, and
    # the object table the emitted instructions hold (objects are mutated
    # in place after creation, so the book holds facts and the table holds
    # the objects, keyed by the book's id).

    def _scope(self) -> Any:
        """The function scope the builder's pages are keyed by: the control
        scope of THIS lowering (book-numbered by ``mint_scope``).

        Not the graph's ``lexical_read_scope``: one ControlProgram is lowered
        more than once while specializations settle (see
        ``_enter_loop_state``), and rows whose facts are this lowering's
        physical cells (``carried_snapshot``, ``function_output``, ...) must
        not be concorded against another lowering's.  Graph-side cells
        (``canonical_value``, ``name_binding``) are read under
        ``lexical_read_scope`` as before.
        """

        return str(self.tensor_shape_concordance_scope)

    def _stage(self, stage: Any = None) -> Any:
        return stage if stage is not None else self.active_stage

    def _function_root(self) -> Ref:
        """The one root row of this lowering: ``cell_set`` row ``(scope, 0)``
        posted NOVEL(CONTROL_FUNCTION_ROOT) with no NEW, so it mints nothing
        and carries only its origin edge.  A mint that has no more specific
        cell to name (a literal, a function the reducer never saw) names it.
        """

        if self._root_cell is None:
            self._root_cell = self._book().post(
                CELL_SET, (self._scope(), 0), (),
                stage=CONTROL_SSA_ENTRY,
                provenance=Novel(CONTROL_FUNCTION_ROOT, ()),
                mode=Mode.CONCORD,
            )
        return self._root_cell

    def _cell_set(self, cells: tuple, stage: Any = None) -> Ref:
        """One ``cell_set`` row DERIVED from every cell in ``cells``; its
        fact repeats them as keys.  The operand of a mint made from several
        cells (the api's transforms take one operand)."""

        book = self._book()
        scope = self._scope()
        ordinal = book.page(CELL_SET).scope_row_count(scope) + 1
        return book.post(
            CELL_SET, (scope, ordinal), tuple(cell.key for cell in cells),
            stage=self._stage(stage),
            provenance=Derived(tuple(cells)),
            mode=Mode.CONCORD,
        )

    def _canonical_cell(self, graph_id: Any) -> Ref | None:
        """The ``canonical_value`` cell of graph id ``graph_id``, if the
        reducer saw this function."""

        if self.lexical_read_scope is None or graph_id is None:
            return None
        row = (self.lexical_read_scope, int(graph_id))
        return self._book().latest_ref(CANONICAL_VALUE, row) or (
            self._book().latest_ref(INGESTION_VALUE, row)
        )

    def _structural_return_members(self, value_id: int) -> tuple[int, ...] | None:
        """Read recursive tuple positions from their live concordance view."""
        from .concordance_declarations import SOURCE_AGGREGATE_LAYOUT
        from .structural_concordance import source_structure

        if self.lexical_read_scope is None:
            return None
        book = self._book()
        row = (self.lexical_read_scope, int(value_id))
        if book.latest_ref(SOURCE_AGGREGATE_LAYOUT, row) is None:
            return None
        structure, _cell = source_structure(*row, book=book)
        if structure.kind != "product" or structure.storage != "tuple":
            return None
        return tuple(leaf.value_id for _path, leaf in structure.leaves())

    def _declared_cell(self, page_name: str, row: tuple) -> Ref | None:
        """Read-side lookup of a cell on a page another lane declares
        (``item_operand``, ``consumer_operand``, ...): None until the page
        is declared and the cell exists."""

        book = self._book()
        page = book.registry.pages.get(page_name)
        if page is None:
            return None
        return book.latest_ref(page, row)

    def _cells(self, *items: Any) -> tuple[Ref, ...]:
        """Cells named loosely -- a Ref, an SSAValue (its ``ssa_value``
        cell), a graph id (its ``canonical_value`` cell) or None -- as the
        distinct Refs that exist."""

        found: list[Ref] = []
        for item in items:
            if item is None:
                continue
            if isinstance(item, Ref):
                cell = item
            elif isinstance(item, SSAValue):
                cell = self._value_cell(item)
            elif isinstance(item, int) and not isinstance(item, bool):
                cell = self._canonical_cell(item)
            else:
                continue
            if cell is not None and cell not in found:
                found.append(cell)
        return tuple(found)

    def _value_cell(
        self, value: SSAValue, *cells: Any, stage: Any = None,
    ) -> Ref:
        """The ``ssa_value`` cell of ``value``.

        A value the builder minted has its row already.  A value whose id
        IS a graph id (``_value_from_meta``, a region's declared value) is
        adopted on first sight: its row is DERIVED from the id's
        ``canonical_value`` cell (and ``cells``), or posted
        ``Unsourced(GRAPH_ID_WITHOUT_CANONICAL_CELL)`` when the reducer
        never saw this function (plan 80 B6 R8).
        """

        book = self._book()
        row = (self._scope(), int(value.id))
        ref = book.latest_ref(SSA_VALUE, row)
        if ref is not None:
            # The object most recently seen under the id is the one the
            # emitted instructions hold (a produced value replaces the
            # object its mint handed out).
            self.ssa_value_objects[int(value.id)] = value
            return ref
        fact = SSAValueFact(
            value.dtype, tuple(value.shape or ()),
            SSAValueOrigin.ADOPTED_GRAPH_ID,
        )
        sources = self._cells(self._canonical_cell(value.id), *cells)
        if not sources and has_flag(int(value.id), MINTED):
            # A minted id is no graph id and never has a canonical cell (a
            # sequence handle, a record part): it stands on the sequence's
            # contract cell when it is one, else on the function root, as
            # ``fresh_value`` does for a mint.
            fact = SSAValueFact(
                value.dtype, tuple(value.shape or ()), SSAValueOrigin.MINTED,
            )
            sources = self._cells(
                self._sequence_contract_cell(int(value.id)),
            ) or (self._function_root(),)
        if not sources:
            # A graph id the reducer never saw in this lowering (no lexical
            # read scope: a fused or planned control program) is declared by
            # the control program itself: it stands on the ``region_signature``
            # cell of the region that names it as a feed or output, else on
            # the function root -- the rule ``_post_region_signature`` applies
            # to the region.
            sources = self._cells(
                self._declaring_region_cell(int(value.id)),
            ) or (self._function_root(),)
        # Program: gen_sort.py / caller.py root formals, singleton_snapshot
        # call results.  Wrong record: an adopted graph id's row carried no
        # storage/rank although its contract row (``value_type_abi`` at the
        # id's canonical cell) declares them.  Rule: DERIVED from that row
        # (``_contract_physical``); an id with no contract row posts none.
        _declared = _contract_physical(book, value, *sources)
        if _declared:
            fact = replace(fact, **_declared[0])
            sources = (*sources, _declared[1])
        ref = book.post(
            SSA_VALUE, row, fact,
            stage=self._stage(stage),
            provenance=Derived(sources),
            mode=Mode.REVISE,
        )
        self.ssa_value_objects[int(value.id)] = value
        return ref

    def _phi_physical(self, *operands: SSAValue) -> dict[str, Any] | None:
        """The ``storage``/``rank`` of a Phi, read from its operands' rows.

        Program: loop_call_carry (``lower_loop`` carried Phis).  Wrong
        record: the header Phi row posted no storage/rank beside its seed's.
        Rule: a Phi is one storage with its operands; every operand row that
        carries the fields must carry the SAME fields, which the Phi posts;
        operand rows that carry none are no evidence.  Operands that disagree
        are refused by name -- a Phi of two storages is not one value."""

        book = self._book()
        seen: dict[tuple, SSAValue] = {}
        for operand in operands:
            cell = book.latest_ref(
                SSA_VALUE, (self._scope(), int(operand.id)),
            )
            fact = (
                None if cell is None
                else book.page(SSA_VALUE).cell(cell.row, cell.column)
            )
            if not isinstance(fact, SSAValueFact) or fact.storage is None:
                continue
            seen.setdefault((fact.storage, fact.rank), operand)
        if not seen:
            return None
        if len(seen) > 1:
            raise ConcordanceRefusal(
                "Phi operands name different physical storage: "
                + ", ".join(
                    f"value {int(v.id)} is storage={k[0]!r} rank={k[1]!r}"
                    for k, v in seen.items()
                )
            )
        (storage, rank), = seen
        return {"storage": storage, "rank": rank}

    def _posted_carried_type(
        self, initial: SSAValue, *operands: SSAValue,
    ) -> tuple[Any, dict[str, Any] | None]:
        """The dtype and physical fields a carried Phi is minted with, read
        from the POSTED ``ssa_value`` row of its initial value.

        Program: ``for i in range(8): j = 0; while j < 4: ...; j = j + 1``.
        Wrong record: the header Phi was minted with the initial's authored
        spelling (``int``, the object's dtype) while the literal's posted row
        is the declared ``int64`` (constant materialization revises it), so
        one shape edge keyed on the Phi id received ``int64 -> int`` beside
        ``int64 -> int64`` from the region-call occurrences.  Rule: the book
        is the authority and the object a view; a carried Phi is DERIVED from
        its initial's cell (the operand of the mint) and declares that row's
        dtype and physical fields.  A value with no posted row keeps its
        object's dtype."""

        book = self._book()
        cell = book.latest_ref(SSA_VALUE, (self._scope(), int(initial.id)))
        fact = (
            None if cell is None
            else book.page(SSA_VALUE).cell(cell.row, cell.column)
        )
        physical = dict(self._phi_physical(initial, *operands) or {})
        if not isinstance(fact, SSAValueFact):
            return initial.dtype, (physical or None)
        if fact.physical_dtype is not None:
            physical.setdefault("physical_dtype", fact.physical_dtype)
        return fact.dtype, (physical or None)

    def fresh_value(
        self,
        *,
        dtype: str | None = None,
        shape: tuple[int, ...] = (),
        transform: Any,
        operands: tuple = (),
        stage: Any = None,
        physical: Any = None,
    ) -> SSAValue:
        """Mint one SSA value through the book: NOVEL(``transform``,
        operand) on ``ssa_value`` row ``(scope, NEW)``.

        ``operands`` name what the value was made from (Refs, SSAValues or
        graph ids, see ``_cells``); several cells become one ``cell_set``
        row, none becomes the function root.  The id is the book's.
        """

        stage = self._stage(stage)
        cells = self._cells(*operands)
        if len(cells) == 1:
            operand = cells[0]
        elif cells:
            operand = self._cell_set(cells, stage)
        else:
            operand = self._function_root()
        # Rule: a mint declares its physical fields (``physical``: a mapping
        # of SSAValueFact physical fields, or None for a mint with none),
        # as ``_mint_ssa_id`` does.
        ref = self._book().post(
            SSA_VALUE, (self._scope(), NEW),
            SSAValueFact(
                dtype, tuple(shape), SSAValueOrigin.MINTED,
                **dict(physical or {}),
            ),
            stage=stage,
            provenance=Novel(transform, (operand,)),
            mode=Mode.REVISE,
        )
        value = SSAValue(int(ref.row[1]), dtype=dtype, shape=shape)
        self.ssa_value_objects[int(value.id)] = value
        return value

    def _posted_physical_accounting(
        self, value: SSAValue,
        keys: tuple[str, ...] = ("program_abi_storage", "program_abi_rank"),
    ) -> dict[str, Any]:
        """The ProgramABI accounting labels (``program_abi_storage``,
        ``program_abi_rank``) of ``value`` read FROM its posted ``ssa_value``
        row, for the fields the row records.  Rule: the book is the
        authority and accounting a derived view -- a producer posts the
        physical fact first (``physical=`` on the mint or the revise) and
        sets its accounting from this, never the other way round."""

        book = self._book()
        cell = book.latest_ref(SSA_VALUE, (self._scope(), int(value.id)))
        fact = (
            None if cell is None
            else book.page(SSA_VALUE).cell(cell.row, cell.column)
        )
        view: dict[str, Any] = {}
        if isinstance(fact, SSAValueFact):
            if fact.storage is not None and "program_abi_storage" in keys:
                view["program_abi_storage"] = fact.storage
            if fact.rank is not None and "program_abi_rank" in keys:
                view["program_abi_rank"] = fact.rank
            if fact.arena and "sequence_arena" in keys:
                view["sequence_arena"] = True
            if fact.physical_dtype is not None and "physical_dtype" in keys:
                view["physical_dtype"] = fact.physical_dtype
        return view

    def _revise_value(
        self, value: SSAValue, *cells: Any, stage: Any = None,
        physical: Any = KEEP_PHYSICAL,
    ) -> Ref | None:
        """Record an in-place dtype/shape change of ``value`` as a REVISE
        of its ``ssa_value`` row DERIVED(previous cell, ``cells``)."""

        book = self._book()
        row = (self._scope(), int(value.id))
        previous = book.latest_ref(SSA_VALUE, row)
        if previous is None:
            return self._value_cell(value, *cells, stage=stage)
        recorded = book.pages[SSA_VALUE.name].cells.get((row, previous.column))
        origin = getattr(recorded, "origin", SSAValueOrigin.ADOPTED_GRAPH_ID)
        # Rule: a rebuilt fact carries its physical fields (KEEP by default).
        fact = rebuilt_ssa_value_fact(
            recorded, value.dtype, value.shape, origin, physical,
        )
        if fact == recorded:
            return previous
        return book.post(
            SSA_VALUE, row, fact,
            stage=self._stage(stage),
            provenance=Derived(self._cells(previous, *cells)),
            mode=Mode.REVISE,
        )

    def _binding_cell(self, graph_id: Any) -> Ref | None:
        return self._book().latest_ref(
            CONTROL_VALUE_BINDING, (self._scope(), int(graph_id)),
        )

    def _binding_fact(self, graph_id: Any) -> Any:
        cell = self._binding_cell(graph_id)
        if cell is None:
            return None
        page = self._book().pages.get(CONTROL_VALUE_BINDING.name)
        return None if page is None else page.cell(cell.row, cell.column)

    def _binding(self, graph_id: Any) -> SSAValue | None:
        """The SSA value bound to ``graph_id`` (the read view)."""

        return self.external_values.get(int(graph_id))

    def _bind(
        self,
        graph_id: Any,
        value: SSAValue,
        kind: BindingKind,
        *cells: Any,
        stage: Any = None,
    ) -> Ref | None:
        """Bind graph id ``graph_id`` to ``value``: one REVISE row on
        ``control_value_binding`` DERIVED(the id's ``canonical_value`` cell,
        the value's ``ssa_value`` cell, ``cells``), then the read view.

        Rebinding the same value is a no-op (no post); a function the
        reducer never saw binds with kind UNSCOPED (R8).
        """

        graph_id = int(graph_id)
        self.external_values[graph_id] = value
        if value is None:
            return None
        type_fact = self.native_value_type_abi.get(graph_id)
        alternatives = tuple(
            type_fact.get("alternatives", ())
            if isinstance(type_fact, Mapping)
            else getattr(type_fact, "alternatives", ())
        )
        if len(alternatives) == 1:
            value.accounting = {
                **dict(value.accounting or {}),
                "native_exact_type": str(alternatives[0]),
            }
        tag_id = (value.accounting or {}).get("native_type_tag_value_id")
        if tag_id is not None:
            tag = self.ssa_value_objects.get(int(tag_id))
            if tag is not None:
                self.native_value_type_tags[graph_id] = tag
        book = self._book()
        value_cell = self._value_cell(value, stage=stage)
        row = (self._scope(), graph_id)
        latest = book.latest_ref(CONTROL_VALUE_BINDING, row)
        if latest is not None:
            recorded = book.pages[CONTROL_VALUE_BINDING.name].cells.get(
                (row, latest.column)
            )
            if (
                isinstance(recorded, ControlBinding)
                and recorded.ssa_value == value_cell
            ):
                return latest
        if self.lexical_read_scope is None:
            kind = BindingKind.UNSCOPED
        sources = self._cells(self._canonical_cell(graph_id), value_cell, *cells)
        return book.post(
            CONTROL_VALUE_BINDING, row, ControlBinding(value_cell, kind),
            stage=self._stage(stage),
            provenance=Derived(sources),
            mode=Mode.REVISE,
        )

    def _bind_unresolved(
        self,
        graph_id: Any,
        reason: Any,
        *cells: Any,
        value: SSAValue | None = None,
        stage: Any = None,
    ) -> Ref | None:
        """Record that ``graph_id`` has no resolvable binding here:
        ``Unresolved(reason, read=cells)`` on its binding row, DERIVED from
        what was read.  ``value`` (a stand-in) goes to the read view only."""

        graph_id = int(graph_id)
        if value is not None:
            self.external_values[graph_id] = value
        read = self._cells(self._canonical_cell(graph_id), *cells)
        if value is not None:
            read = self._cells(*read, self._value_cell(value, stage=stage))
        if not read:
            return None
        return self._book().post(
            CONTROL_VALUE_BINDING, (self._scope(), graph_id),
            Unresolved(reason, read=read),
            stage=self._stage(stage),
            provenance=Derived(read),
            mode=Mode.REVISE,
        )

    def _declare_parameter(
        self, graph_id: Any, declaration: ParameterDeclaration, *cells: Any,
    ) -> Ref | None:
        """``declared_parameter`` row ``(scope, graph id)``: CALL_ONLY
        DERIVED(the parameter's version-0 ``name_binding`` cell, its binding
        cell); USED DERIVED(the previous declaration, the use's cell)."""

        graph_id = int(graph_id)
        book = self._book()
        row = (self._scope(), graph_id)
        previous = book.latest_ref(DECLARED_PARAMETER, row)
        if previous is not None:
            recorded = book.pages[DECLARED_PARAMETER.name].cells.get(
                (row, previous.column)
            )
            if recorded is declaration:
                return previous
        sources = self._cells(
            previous, *cells, self._binding_cell(graph_id),
            self._canonical_cell(graph_id),
        )
        if not sources:
            return None
        return book.post(
            DECLARED_PARAMETER, row, declaration,
            stage=self.active_stage,
            provenance=Derived(sources),
            mode=Mode.REVISE,
        )

    def _rebind_view(
        self, values: Mapping[int, SSAValue], kind: BindingKind, *cells: Any,
    ) -> None:
        """Rebind every id in ``values`` whose current view differs (the
        ``update(...)`` writers: restores and merges)."""

        for graph_id, value in values.items():
            if self.external_values.get(int(graph_id)) is value:
                continue
            self._bind(int(graph_id), value, kind, *cells)

    def _withdraw(self, graph_id: Any, previous: SSAValue | None, *cells: Any) -> None:
        """``pop`` then ``[...] = previous``: the saved value is rebound
        RESTORED; with no previous the binding is withdrawn with an
        ``Unresolved(BINDING_WITHDRAWN)`` revision, never an erasure."""

        graph_id = int(graph_id)
        current = self.external_values.pop(graph_id, None)
        if previous is None:
            if current is not None:
                self._bind_unresolved(
                    graph_id, BINDING_WITHDRAWN, *cells, self._value_cell(current),
                )
            return
        self._bind(graph_id, previous, BindingKind.RESTORED, *cells)

    def _construct_cell(self, node_id: Any) -> Ref | None:
        """The identity cell of a control construct's source graph node."""

        return self._canonical_cell(node_id)

    def _restore_view(self, saved: Mapping[int, SSAValue], *cells: Any) -> None:
        """Make the read view equal ``saved`` again (an arm that leaves
        through its own edge): every id the arm added is withdrawn, every
        id it rebound is RESTORED.  Each change is a revision, never an
        erasure."""

        for graph_id in tuple(self.external_values):
            if int(graph_id) not in saved:
                self._withdraw(int(graph_id), None, *cells)
        for graph_id, value in saved.items():
            if self.external_values.get(int(graph_id)) is not value:
                self._bind(int(graph_id), value, BindingKind.RESTORED, *cells)

    def _post_carried_snapshots(
        self, conditional_cell: Ref | None, snapshots: Mapping[int, SSAValue],
    ) -> dict[int, Ref]:
        """One ``carried_snapshot`` row per snapshotted initial id: the
        binding cell current at branch entry, DERIVED from that cell and
        the conditional construct's cell.  Returns initial id -> the cell
        that stands for the snapshot (the row's cell; the binding cell when
        the conditional has no identity cell to key the row by)."""

        book = self._book()
        cells: dict[int, Ref] = {}
        for initial_id, value in snapshots.items():
            initial_id = int(initial_id)
            binding_cell = self._binding_cell(initial_id)
            if binding_cell is None:
                binding_cell = self._value_cell(value)
            if conditional_cell is None:
                cells[initial_id] = binding_cell
                continue
            row = (self._scope(), conditional_cell, initial_id)
            existing = book.latest_ref(CARRIED_SNAPSHOT, row)
            if existing is not None:
                cells[initial_id] = existing
                continue
            cells[initial_id] = book.post(
                CARRIED_SNAPSHOT, row, binding_cell,
                stage=CONTROL_SSA_CONDITIONAL,
                provenance=Derived(self._cells(binding_cell, conditional_cell)),
                mode=Mode.CONCORD,
            )
        return cells

    def _concorded_resident(self, value_id: int) -> int:
        """The resident ``value_id`` denotes under the CONCORDED planning
        aliases (the ``control_value_alias`` PLANNING rows as resolved at
        builder entry), never the live ``value_aliases`` view that loops
        rewrite while their bodies lower."""

        current = int(value_id)
        seen: set[int] = set()
        while current in self.concorded_value_aliases:
            if current in seen:
                raise ValueError(
                    "cyclic durable planning concordance for "
                    f"{self.function_name!r}: {current}"
                )
            seen.add(current)
            target = int(self.concorded_value_aliases[current])
            if target == current:
                break
            current = target
        return current

    def _recorded_name_write(self, value_id: int) -> bool:
        """Whether the book records an authored write producing ``value_id``:
        a ``name_binding`` row under the read scope whose fact names it.

        This is the record decision 7.2 asks for: an arm id with no such
        row is not a write the arm made (a merge node, a planner alias), so
        the arm takes the entered version; an arm id with one and no
        binding in this lowering is a version the builder cannot find.

        An in-place store (``m[2] = ...``, ``m[:2] -= ...``) is the one
        version that has BOTH: an authored ``name_binding`` row and a
        PLANNING alias to the storage it writes (store versions are versions
        of one storage).  The builder never binds such a version, so
        ``_carried_name_arm`` resolves the arm through the concorded alias
        chain before asking this question; this answer alone never decides
        an in-place store arm.
        """

        if self.lexical_read_scope is None:
            return False
        recorded = getattr(self, "_authored_write_ids", None)
        if recorded is None:
            recorded = set()
            page = self._book().pages.get(NAME_BINDING.name)
            if page is not None:
                for row in page.scope_rows(self.lexical_read_scope):
                    fact = page.latest(row)
                    value = getattr(fact, "value_id", None)
                    if value is not None and getattr(fact, "authored", True):
                        recorded.add(int(value))
            self._authored_write_ids = recorded
        return int(value_id) in recorded

    def _conditional_shared_sources(self, merged_id: int, source_ids: Any) -> frozenset[int]:
        """Source identities also owned by bindings this merge does not version."""
        binding_names = self.__dict__.get('_conditional_binding_names')
        if binding_names is None:
            binding_names = {}
            page = self._book().pages.get(NAME_BINDING.name)
            if page is not None and self.lexical_read_scope is not None:
                for row in page.scope_rows(self.lexical_read_scope):
                    fact = page.latest(row)
                    value_id = getattr(fact, 'value_id', None)
                    if value_id is not None:
                        binding_names.setdefault(int(value_id), set()).add(row[1])
            self._conditional_binding_names = binding_names
        merged_names = binding_names.get(int(merged_id), set())
        return frozenset(
            int(source_id) for source_id in source_ids
            if merged_names and binding_names.get(int(source_id), set()) - merged_names
        )

    def _carried_name_arm(
        self,
        arm_id: Any,
        initial_id: Any,
        snapshot: SSAValue,
        snapshot_cell: Ref | None,
        *,
        path: str,
    ) -> tuple[SSAValue, Any]:
        """The SSA value a name-carried merge takes from one arm, and the
        cell it derives from (decision 7.2 of the design).

        The arm id equal to the initial id: the arm did not rebind the name,
        the entered version (the snapshot) is the arm and the snapshot cell
        is its source.  A different arm id with a binding: that binding (the
        version the book records for the arm).  A different arm id with no
        binding: the graph records a version the builder cannot find --
        ``Unresolved(NAME_ARM_VERSION_MISSING)`` is posted at the arm id, a
        ``carried-name-arm-missing`` shortfall is appended, and the snapshot
        stands in for the emitted Phi without being posted as the arm.
        """

        arm_id = int(arm_id)
        if arm_id == int(initial_id):
            return snapshot, snapshot_cell
        if arm_id in self.consumer_row_loads:
            # ``if n > 0: last = xs[n - 1]``: the merge is the row load's
            # only consumer, and this is the arm's exit -- the place its
            # value is first asked for (see ``consumer_row_loads``).
            self.external_value(arm_id)
        value = self.external_values.get(arm_id)
        # The fused pointer-type program first binds store-version 462 in
        # the nested true arm (Phi319), then republishes it as Phi321. It
        # did not exist at parent entry, so restoring entry snapshots cannot
        # remove this true-only binding. Reading it on if_false.12 emitted
        # Phi322(Phi321, Phi321), which LLVM correctly rejects. Residency in
        # the global read view is not edge availability: use the existing
        # exact SSA/CFG dominance operator before accepting an arm binding.
        # If it is unavailable here, the existing concorded-storage alias
        # and authored-write rules below still decide the arm, not a guess.
        if value is not None and self._value_dominates_current_edge(value):
            source = self._binding_cell(arm_id)
            return value, source if source is not None else self._value_cell(value)
        if arm_id in self.constant_value_ids:
            # An authored literal (``rejected = False`` in the arm): no
            # region publishes it; the control function owns it.  Resolve it
            # as the provisional formal ``_materialize_control_constants``
            # turns into this function's own ``Const`` -- as a folded
            # ``flag = True; break`` is resolved on its break edge and an
            # owned literal output is resolved at the exit.
            value = self.external_value(arm_id)
            source = self._binding_cell(arm_id)
            return value, source if source is not None else self._value_cell(value)
        # An in-place store version is aliased (``control_value_alias``,
        # PLANNING) to the storage it writes and is never bound.
        # ``m = call(); if c: m[2] = ...; if t > 0: m[:2] -= ...`` merges the
        # inner ``if`` with arm = the ``m[:2]`` store and initial = the
        # ``m[2]`` store: both resolve to the call result, so the arm
        # carries the entered storage.  Resolve through the CONCORDED alias
        # chain (not the live view loops rewrite) before the authored-write
        # check; refuse only a distinct resolved version with no binding.
        resident = self._concorded_resident(arm_id)
        if resident == self._concorded_resident(initial_id):
            return snapshot, snapshot_cell
        if resident != arm_id:
            value = self.external_values.get(resident)
            if value is not None and self._value_dominates_current_edge(value):
                source = self._binding_cell(resident)
                return value, (
                    source if source is not None else self._value_cell(value)
                )
        if not self._recorded_name_write(arm_id):
            # The book records no authored write of this value in the arm
            # (no ``name_binding`` row names it): the arm did not assign, the
            # value falls up the scope ladder to the entered version.  Never
            # refused (design decision 7.2).
            return snapshot, snapshot_cell
        missing = self._bind_unresolved(
            arm_id, NAME_ARM_VERSION_MISSING, snapshot_cell,
        )
        self.shortfalls.append(SSALoweringShortfall(
            "control", "carried-name-arm-missing", path,
            "a name-carried conditional arm names a version with no "
            f"binding in this lowering: arm={arm_id} initial={int(initial_id)}"
            + ("" if missing is None else f" (recorded {NAME_ARM_VERSION_MISSING.name})"),
        ))
        return snapshot, None

    # ------------------------------------------------- field-state versions
    # A scalar field write and a conditional field merge each ARE one
    # ``reducer_field_state`` cell (plan 70, sections 4-5).  The SSA value
    # this builder emits for such a cell is published on ``ssa_field_version``
    # at ``(function scope, cell)``; the conditional merge reads each arm's
    # version at the arm's own cell.  ``external_values[<graph id>]`` stays
    # as a read view, never as the source of an arm.

    def _field_version_row(self, cell: Any) -> tuple | None:
        if self.lexical_read_scope is None or not isinstance(cell, Ref):
            return None
        return (self.lexical_read_scope, cell)

    def _publish_field_version(
        self, cell: Any, value: SSAValue, sources: tuple[Any, ...],
        *, mode: Mode = Mode.CONCORD,
    ) -> Any:
        """Post ``value`` as the SSA version of field-state ``cell``.

        ``sources`` are the cells the version derives from (the field-state
        cell itself for a write; the arm versions and the merged cell for a
        merge).  Returns the version cell's Ref, or None when the function
        has no reduction scope to key the row by.
        """
        row = self._field_version_row(cell)
        if row is None:
            return None
        ref = self._book().post(
            SSA_FIELD_VERSION, row, int(value.id),
            stage=CONTROL_SSA,
            provenance=Derived(tuple(
                source for source in sources if isinstance(source, Ref)
            )),
            mode=mode,
        )
        self.field_version_values[ref] = value
        return ref

    def _field_state_kind(self, cell: Ref) -> Any:
        """The ``FieldStateKind`` recorded at a ``reducer_field_state`` cell."""
        page = self._book().pages.get(cell.page.name)
        fact = None if page is None else page.cell(cell.row, cell.column)
        return getattr(fact, "kind", None)

    def _carried_field_arm(
        self,
        arm_cell: Any,
        other_arm_cell: Any,
        snapshot: SSAValue,
        *,
        path: str,
        arm_value_id: Any = None,
    ) -> tuple[SSAValue, Any]:
        """The SSA value a field-carried merge takes from one arm.

        Returns ``(value, source)`` where ``source`` is the cell the merged
        version derives from for this arm: the arm's ``ssa_field_version``
        cell when the arm wrote, or the arm cell itself when the arm did not
        write (the arm cell IS the pre-branch cell -- an OBSERVED state, or
        the same cell as the other arm -- so the snapshot is its value).  An
        arm cell that names a write or a merge with no version posted is
        recorded as ``Unresolved(ARM_VERSION_MISSING)`` at its row and a
        shortfall is raised; the snapshot then stands in for the emitted Phi
        but is never posted as the arm.

        ``arm_value_id`` is the arm's graph value the planner paired with
        ``arm_cell`` (the reducer Phi's arm parent; ``carried_aliases`` and
        ``carried_field_cells`` are index-aligned).  An ELEMENT_WRITTEN cell
        (``obj.field[i] = v``, plan 70 section 1.3) holds the IndexedStore
        as both value and effect; that store is emitted inside a planned
        region, so no block of this builder publishes a version for it.
        Its version IS the storage the store writes in place: the store id
        is aliased to that storage by its ``control_value_alias`` PLANNING
        row (the same chain ``_carried_name_arm`` resolves an in-place
        store through), and the storage's current binding is the value.
        Program: ``dt_controller.step_with_dt_control_used``, ``if
        rejected: metrics.control_values[0] = ...; metrics.control_present[0]
        = 1.0`` on the retry loop -- the only statements of the arm are
        element writes, and the merge named their ELEMENT_WRITTEN cells
        with no version (``carried-field-arm-missing``, N=2 orbital dt
        system; tools/compiler_probes/probe_element_written_field_arm.py).
        """
        book = self._book()
        row = self._field_version_row(arm_cell)
        if row is None:
            return snapshot, None
        version_ref = book.latest_ref(SSA_FIELD_VERSION, row)
        recorded_missing = None
        recorded_reason = ARM_VERSION_MISSING
        if version_ref is not None:
            fact = book.pages[SSA_FIELD_VERSION.name].latest(row)
            value = self.field_version_values.get(version_ref)
            if value is None and isinstance(fact, int):
                # The version was posted by another builder over this scope;
                # the row's fact IS the SSA identity, so name it directly.
                value = SSAValue(
                    int(fact), dtype=snapshot.dtype, shape=snapshot.shape,
                )
            if value is not None:
                return value, version_ref
            if (
                isinstance(fact, Unresolved)
                and arm_cell in fact.read
            ):
                # A prior control section may already have read this exact
                # authored arm and recorded the more precise reason it has no
                # SSA version (for example, an unproven write dtype).  Keep
                # that fact: replacing its reason without a changed source
                # would be a false revision.
                recorded_missing = version_ref
                recorded_reason = fact.reason
        kind = self._field_state_kind(arm_cell)
        if arm_cell == other_arm_cell or kind in {
            FieldStateKind.OBSERVED, FieldStateKind.ARM_SELECTED,
            FieldStateKind.LOOP_EXIT,
        }:
            # The arm did not write: its cell is the state the branch was
            # entered with, whose SSA value is the snapshot.
            return snapshot, arm_cell
        if kind is FieldStateKind.WRITTEN and arm_value_id is not None:
            # A scheduled region may already have lowered the exact value of
            # a whole-field write even when the preparatory scalar pass could
            # not prove a static dtype (for example ``row.dtype = str(x)``).
            # The durable planning concordance identifies that resident and
            # the control binding supplies its actual SSA type. Publish that
            # existing value at the reducer's WRITTEN cell; no type inference
            # or fallback-policy decision is needed here.
            resident_id = self._concorded_resident(int(arm_value_id))
            value = self.external_values.get(resident_id)
            if (
                value is not None
                and value is not snapshot
                and self._value_dominates_current_edge(value)
            ):
                binding_cell = self._binding_cell(resident_id)
                version_ref = self._publish_field_version(
                    arm_cell, value, (arm_cell, binding_cell),
                    mode=(
                        Mode.REVISE
                        if recorded_missing is not None else Mode.CONCORD
                    ),
                )
                return value, (
                    version_ref if version_ref is not None else arm_cell
                )
        if kind is FieldStateKind.ELEMENT_WRITTEN and arm_value_id is not None:
            storage_id = self._concorded_resident(int(arm_value_id))
            storage = self.external_values.get(storage_id)
            if storage is not None:
                # ELEMENT_WRITTEN version: the in-place storage, DERIVED(the
                # ELEMENT_WRITTEN cell, the store's PLANNING alias cell, the
                # storage's binding cell).
                version_ref = self._publish_field_version(
                    arm_cell, storage, (
                        arm_cell,
                        book.latest_ref(
                            CONTROL_VALUE_ALIAS,
                            (self._scope(), int(arm_value_id)),
                        ),
                        self._binding_cell(storage_id),
                    ),
                )
                return storage, (
                    version_ref if version_ref is not None else arm_cell
                )
        missing = recorded_missing or book.post(
            SSA_FIELD_VERSION,
            row,
            Unresolved(ARM_VERSION_MISSING, read=(arm_cell,)),
            stage=CONTROL_SSA,
            provenance=Derived((arm_cell,)),
            mode=Mode.REVISE,
        )
        self.shortfalls.append(SSALoweringShortfall(
            "control", "carried-field-arm-missing", path,
            "a field-carried conditional arm names a field-state cell with "
            f"no ssa_field_version: row={missing.row!r} "
            f"(recorded {recorded_reason.name})",
        ))
        return snapshot, None

    def _operand_bindings(self, operands: Any) -> set:
        """The bindings read by ``(consumer, role, ordinal)`` operands.

        An ``Unresolved`` revision (a withdrawn position) reads as absence.
        """

        page = self._book().page(LEXICAL_READ_BINDING)
        found = set()
        for consumer, role, ordinal in operands:
            fact = page.latest((self.lexical_read_scope, consumer, role, ordinal))
            found.add(None if isinstance(fact, Unresolved) else fact)
        return found

    def _read_binding_cells(self, operands: Any) -> tuple[Ref, ...]:
        """The ``lexical_read_binding`` cells at ``(consumer, role,
        ordinal)`` operand positions that have one."""

        if self.lexical_read_scope is None:
            return ()
        book = self._book()
        return self._cells(*(
            book.latest_ref(
                LEXICAL_READ_BINDING,
                (self.lexical_read_scope, consumer, role, ordinal),
            )
            for consumer, role, ordinal in operands
        ))

    def _enter_loop_state(self, loop: Any, carried: Any) -> Any:
        """Commit this loop's entry state; return its key for the stack.

        Row ``(control scope, loop node, initial id)`` holds the bindings the
        loop carries under that initial id (``loop_carried_binding``) and
        the value that initial id had before the loop.  A pair the book does
        not attribute is not committed; its reads keep the header rebinding.
        """

        loop_node = getattr(loop, "source_loop_node_id", None)
        if self.lexical_read_scope is None or loop_node is None:
            return None
        book = self._book()
        loop_cell = self._construct_cell(loop_node)
        key = (str(self.tensor_shape_concordance_scope), int(loop_node))
        states: dict[int, set] = {}
        state_sources: dict[int, list] = {}
        for entry, (updated_id, initial_id, initial_value, *_rest) in (
            enumerate(carried)
        ):
            binding_row = (
                self.lexical_read_scope, int(loop_node),
                int(updated_id), int(initial_id),
            )
            binding_cell = book.latest_ref(LOOP_CARRIED_BINDING, binding_row)
            bindings = book.page(LOOP_CARRIED_BINDING).latest(binding_row)
            if bindings is None or isinstance(bindings, Unresolved):
                # A carried pair the book does not attribute: recorded, not
                # silently kept as the header rebinding (plan 80 B2.4).
                self._bind_unresolved(
                    int(initial_id), CARRIED_ENTRY_NOT_ATTRIBUTED,
                    self._binding_cell(int(updated_id)), loop_cell,
                )
                continue
            owned = states.setdefault(int(initial_id), set())
            owned.update(bindings)
            state_sources.setdefault(int(initial_id), []).append(binding_cell)
            # Row ``(control scope, loop, binding)`` -> the carried entry
            # that binding is.  Two bindings seeded from one value
            # (``second = value; third = value``) share an initial id but
            # are distinct entries with distinct header Phis.  DERIVED(the
            # ``loop_carried_binding`` cell it read).
            for binding in bindings:
                self._post_concord(
                    LOOP_CARRIED_ENTRY, (*key, str(binding)), int(entry),
                    binding_cell, loop_cell, stage=CONTROL_SSA_LOOP,
                )
        for initial_id, owned in states.items():
            # The book records the authored state identity, never a physical
            # SSAValue from one lowering.  One ControlProgram may be lowered
            # more than once while specializations settle; retaining the
            # first lowering's SSA object made the next lowering disagree on
            # incidental dtype/shape metadata for the same semantic row.
            # Its concrete pre-loop value is already owned by this builder's
            # loop frame and is recovered there by _resolve_read.  DERIVED(
            # the same cells, the pre-loop binding cell of the initial).
            self._post_concord(
                LOOP_ENTRY_STATE, (*key, initial_id),
                (tuple(sorted(owned)), int(initial_id)),
                *state_sources.get(initial_id, ()),
                self._binding_cell(initial_id), loop_cell,
                stage=CONTROL_SSA_LOOP,
            )
        self.loop_frames[key] = {"carried": carried, "latch": False}
        return key

    def _post_concord(
        self, page: Any, row: tuple, fact: Any, *cells: Any, stage: Any = None,
    ) -> Ref:
        """One CONCORD post DERIVED from ``cells`` (the function root when
        none exists), replacing a raw ``concord`` on a declared page."""

        sources = self._cells(*cells)
        if not sources:
            sources = (self._function_root(),)
        return self._book().post(
            page, row, fact,
            stage=self._stage(stage),
            provenance=Derived(sources),
            mode=Mode.CONCORD,
        )

    def _loop_scope_value_cells(self, *value_ids: Any) -> tuple:
        """The ``ssa_value`` cells of the SSA values a loop-scope generation
        names, in this lowering's scope."""

        book = self._book()
        return tuple(
            book.latest_ref(SSA_VALUE, (self._scope(), int(value_id)))
            for value_id in value_ids
        )

    def _loop_scope_rebinds(self, loop: Any, carried: Any) -> tuple:
        """Describe every carried entry without collapsing shared seeds.

        The value triple alone is insufficient source identity: two authored
        bindings may share an outer value while selecting different updates.
        Carry the lexical binding receipt into the loop-scope declaration so
        the concordance can represent those simultaneous possibilities as
        separate rows.
        """

        loop_node = getattr(loop, "source_loop_node_id", None)
        page = self._book().page("loop_carried_binding")
        binding_scope = (
            None
            if self.lexical_read_scope is None or loop_node is None
            else (self.lexical_read_scope, int(loop_node))
        )
        return tuple(
            (
                int(initial.id), int(current.id), int(updated.id),
                int(initial_id), int(updated_id),
                tuple(
                    () if binding_scope is None else (
                        page.latest((
                            *binding_scope,
                            int(updated_id), int(initial_id),
                        )) or ()
                    )
                ),
            )
            for updated_id, initial_id, initial, updated, current in carried
        )

    def _resolve_read(
        self, value_id: int, bindings: set, reader: str,
    ) -> Any | None:
        """The value ``bindings`` see for ``value_id`` at this point.

        Walks the enclosing loops innermost first.  A loop that carries
        every read binding under this initial id is where the value is (its
        header, or its latch update -- the ordinary resolution); a loop
        carrying none of them is passed through to its pre-loop value; a
        loop carrying some, or a read no row attributes, raises.  Returns
        None when the ordinary resolution is the answer.
        """

        if not bindings:
            return None
        state_page = self._book().page("loop_entry_state")
        candidate = None
        for key in reversed(self.enclosing_loop_states):
            if key is None:
                continue
            state = state_page.latest((*key, int(value_id)))
            if state is None:
                continue
            carried = set(state[0])
            frame = self.loop_frames.get(key)
            before = None
            if frame is not None:
                before = next((
                    initial
                    for _updated_id, initial_id, initial, *_rest
                    in frame["carried"]
                    if int(initial_id) == int(value_id)
                ), None)
            if bindings <= carried:
                entry_value = self._carried_entry_value(
                    key, int(value_id), bindings, reader,
                )
                return candidate if entry_value is None else entry_value
            if None in bindings:
                raise ValueError(
                    f"{self.function_name}: {reader} reads carried initial "
                    f"{value_id} through an operand no lexical_read_binding "
                    "row attributes"
                )
            if bindings & carried:
                raise ValueError(
                    f"{self.function_name}: {reader} reads value {value_id} "
                    f"as bindings {sorted(bindings, key=repr)!r}, of which "
                    f"the enclosing loop carries only {sorted(carried)!r}"
                )
            # A name newly captured IN this loop is not an older alias held
            # before the loop. The compiler's heap ``position = size`` had
            # the same value id, but the old pass froze its guard at size 0.
            # Follow the reducer's assignment receipt to the source binding
            # for this exact loop generation. Bindings captured outside the
            # loop retain the pre-loop value in the branch below.
            capture_index = self.__dict__.get("_name_binding_capture_index")
            if capture_index is None:
                captures = self._book().page("name_binding_capture")
                names = self._book().page("name_binding")
                capture_index = {}
                # Reduction/canonicalization sealed this read scope before
                # this builder started. Index its exact edges once, never
                # rescan every binding for every region feed in every loop.
                for row in captures.scope_rows(self.lexical_read_scope):
                    capture = captures.latest(row)
                    target = names.latest(row)
                    source = names.latest((self.lexical_read_scope, capture[0], capture[1]))
                    if target is not None and source is not None and target.value_id == source.value_id:
                        capture_index.setdefault((int(target.value_id), row[1], capture[2]), set()).add(capture[0])
                self._name_binding_capture_index = capture_index
            source_bindings = set().union(*(
                capture_index.get((int(value_id), binding, key[1]), ())
                for binding in bindings
            ))
            if source_bindings and source_bindings <= carried:
                return self._carried_entry_value(key, int(value_id), source_bindings, reader)
            if before is not None:
                candidate = before
                # The loop carries this initial under other bindings, and
                # this read is not one of them: the preheader value is read
                # inside the loop.  Recorded so the completed-module loop
                # scope pass does not rebind it to the carried Phi.
                self.__dict__.setdefault("_retained_outer_reads", set()).add(
                    (int(key[1]), int(value_id))
                )
        return candidate

    def _carried_entry_value(
        self, key: Any, value_id: int, bindings: set, reader: str,
    ) -> Any | None:
        """The carried entry's value for ``bindings`` read in loop ``key``.

        The entry is the book's (``loop_carried_entry``); its header Phi in
        the body, its published update while the latch re-evaluates the
        predicate. Bindings naming two entries cannot be one read. Even a
        unique entry is selected from its frame: an inner loop may have
        rebound its seed under a different binding in the shared live view.
        """

        frame = self.loop_frames.get(key)
        if frame is None:
            return None
        carried = frame["carried"]
        entry_page = self._book().page("loop_carried_entry")
        entries = {
            entry_page.latest((*key, str(binding))) for binding in bindings
        }
        if None in entries or len(entries) != 1:
            raise ValueError(
                f"{self.function_name}: {reader} reads carried initial "
                f"{value_id} as bindings {sorted(bindings, key=repr)!r}, "
                f"which name carried entries {sorted(entries, key=repr)!r}; "
                "one read is one entry"
            )
        entry = int(entries.pop())
        updated_id, _initial_id, _initial, updated, current = carried[entry]
        if frame["latch"]:
            # In the heap push, parent's initial is position's update. The
            # value-id view gets rebound while completing parent's latch;
            # that does not change position's independently completed edge.
            return frame.get("updates", {}).get(
                entry, self.external_values.get(int(updated_id), updated),
            )
        return current

    def _read(self, value_id: int, bindings: set, reader: str) -> Any:
        resolved = (
            self._resolve_read(value_id, bindings, reader)
            if self.enclosing_loop_states else None
        )
        if resolved is None and self.enclosing_loop_states:
            # topological_order's indegree store spelling75 is a planning
            # alias of resident2, not a new scalar formal. Neither enclosing
            # loop carries75; the temporary body aliases2->75 and75->2 must
            # not mint75 as a second ABI argument. Consult the durable
            # planning resident AFTER the exact authored generation: doing
            # this first would lose total=tensor(0)'s carried constructor in
            # favour of its literal-zero resident. Both reads use the same
            # lexical binding edges; no name/dtype/storage guess is involved.
            resident = self._concorded_resident(int(value_id))
            if resident != int(value_id):
                resolved = self._resolve_read(resident, bindings, reader)
                if resolved is None:
                    return self.external_value(resident)
        return self.external_value(int(value_id)) if resolved is None else resolved

    def _callsite_argument(
        self, callsite_id: int, position: int, value_id: int,
    ) -> Any:
        """A call argument, read by the binding its operand read."""

        if int(value_id) in self.child_selection_validity:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-table", "bounded-child-call", self.function_name,
                "a possibly exhausted child selection cannot cross an unguarded source call",
            ))
            return self.external_value(int(value_id))
        if self.lexical_read_scope is None or not self.enclosing_loop_states:
            return self.external_value(int(value_id))
        operand = self._book().page("call_argument_operand").latest(
            (self.lexical_read_scope, int(callsite_id), int(position))
        )
        bindings = (
            set() if operand is None
            else self._operand_bindings(((int(callsite_id), *operand),))
        )
        return self._read(
            value_id, bindings, f"callsite {callsite_id} argument {position}",
        )

    def _break_bound_initial(self, port_id: int, initial_id: int) -> Any:
        """A break-bound port's no-break value: its binding's pre-loop value.

        The port's own identity is the binding it continues
        (``loop_result_port_binding``).
        """

        if self.lexical_read_scope is None or not self.enclosing_loop_states:
            return self.external_value(int(initial_id))
        binding = self._book().page("loop_result_port_binding").latest(
            (self.lexical_read_scope, int(port_id))
        )
        if binding is None:
            raise ValueError(
                f"{self.function_name}: break-bound result port {port_id} "
                "has no loop_result_port_binding row"
            )
        return self._read(
            initial_id, {str(binding)}, f"result port {port_id}",
        )

    def _aliases_resolving_to(self, value_id: int) -> tuple[int, ...]:
        """The graph spellings of a region feed's planning resident.

        ``blocked[j] = 1.0`` followed by ``rhs[k] = blocked[k]`` in
        successive inner loops of one retained outer loop reads a LoopResult
        port in the graph and its resident span in region SSA.  Entering the
        loops redirects the live aliases to their updates; those temporal
        aliases cannot identify the graph operand whose lexical row we need.
        Use the same durable planning concordance that canonicalized the
        region operand, preserving its exact authored read position.
        """

        return tuple(
            int(alias)
            for alias in self.concorded_value_aliases
            if int(alias) != int(value_id)
            and self._concorded_resident(int(alias)) == int(value_id)
        )

    def _region_feed(self, region_index: int, value_id: int) -> Any:
        """A region feed, read by the bindings of the operands it serves."""

        book = self._book() if self.lexical_read_scope is not None else None
        split = None if book is None else book.page(
            "region_capture_binding"
        ).latest((
            str(self.tensor_shape_concordance_scope), int(region_index),
            int(value_id),
        ))
        if split is not None:
            # A formal the region split off one captured value: it is fed
            # that value as read by exactly one binding.
            source_id, binding = split
            if not self.enclosing_loop_states:
                return self.external_value(int(source_id))
            return self._read(
                int(source_id), {str(binding)},
                f"region {region_index} formal {value_id}",
            )
        item = None if book is None else book.page("item_operand").latest(
            (self.lexical_read_scope, int(value_id))
        )
        if item is not None:
            # A captured ``item()`` (planner page ``item_operand``): read its
            # operand by the binding at the item's operand position, in this
            # site's loop generation.  A rank-0 operand IS the item's value;
            # that merge is decided here, on the value read, and recorded.
            operand_id, role, ordinal = item
            source = (
                self._read(
                    int(operand_id),
                    self._operand_bindings(
                        ((int(value_id), role, int(ordinal)),)
                    ),
                    f"region {region_index} item {value_id}",
                )
                if self.enclosing_loop_states
                else self.external_value(int(operand_id))
            )
            if not tuple(source.shape or ()):
                # The rank-0 merge is one ``scalar_item_merge`` row (plan 80
                # B1.3), no longer a raw ``identity_transition`` revise.
                self._post_scalar_item_merge(int(value_id), source)
                return source
        if self.lexical_read_scope is None or not self.enclosing_loop_states:
            return self.external_value(int(value_id))
        feed_row = (
            str(self.tensor_shape_concordance_scope), int(region_index),
            int(value_id),
        )
        consumers = book.page(REGION_FEED_CONSUMER).latest(feed_row) or ()
        operand_page = book.page("consumer_operand")
        operands = []
        source_operands = {}
        for consumer in consumers:
            positions = operand_page.latest(
                (self.lexical_read_scope, int(consumer), int(value_id))
            )
            if not positions:
                # The consumer's operand is a version that resolves to this
                # feed (an in-place store chain resolving to its arena): its
                # row is keyed by that version.
                alias_positions_for_consumer = []
                for alias in self._aliases_resolving_to(int(value_id)):
                    alias_positions = operand_page.latest(
                        (self.lexical_read_scope, int(consumer), alias)
                    ) or ()
                    if alias_positions:
                        alias_positions_for_consumer.extend(alias_positions)
                        source_operands.setdefault(alias, []).extend(
                            (int(consumer), role, ordinal)
                            for role, ordinal in alias_positions
                        )
                positions = tuple(alias_positions_for_consumer)
            else:
                source_operands.setdefault(int(value_id), []).extend(
                    (int(consumer), role, ordinal) for role, ordinal in positions
                )
            if not positions:
                # No ``consumer_operand`` row: recorded before the fallback
                # (plan 80 B2.5), DERIVED(the feed's consumer cell).
                self._bind_unresolved(
                    int(value_id), REGION_FEED_NO_OPERAND_ROW,
                    book.latest_ref(REGION_FEED_CONSUMER, feed_row),
                    self._canonical_cell(consumer),
                )
                operands.append((int(consumer), None, 0))
                source_operands.setdefault(int(value_id), []).append(
                    (int(consumer), None, 0),
                )
                continue
            operands.extend(
                (int(consumer), role, ordinal) for role, ordinal in positions
            )
        if source_operands:
            # total = tensor(0); total += amount: planning aliases the tensor
            # constructor to its literal, but the loop carries the constructor
            # identity. Resolve each exact consumer operand in its lexical
            # generation, not the physical planning resident (constant zero).
            # Different carried generations cannot share one regional formal.
            reads = [
                self._read(source_id, self._operand_bindings(rows),
                           f"region {region_index}")
                for source_id, rows in source_operands.items()
            ]
            if len({read.id for read in reads}) != 1:
                raise ValueError(
                    f"{self.function_name}: region {region_index} feed "
                    f"{value_id} aliases distinct lexical generations: "
                    f"{tuple((source, read.id) for source, read in zip(source_operands, reads))!r}"
                )
            return reads[0]
        return self._read(
            value_id, self._operand_bindings(operands),
            f"region {region_index}",
        )

    def emit_region_call(self, region_index: int, *, location: str) -> None:
        if self.emit_table_region_operations(region_index):
            return
        if region_index not in self.region_callees:
            # A scheduled region the lowering cannot call is a hole in the
            # program, not a no-op. Silently returning here produced exactly
            # the failure shape this tree keeps paying for -- a plan that
            # says N regions and an emitted function containing none of
            # them, with nothing raised.
            self.shortfalls.append(SSALoweringShortfall(
                "control", "region_callee", location,
                f"scheduled region {region_index} has no callee and no "
                "signature to default one from; the region's work is absent "
                "from the emitted function",
            ))
            return
        callee = self.region_callees[region_index]
        # Program: ``ys1 = sorted(xs1); xs2 = [6] * (n % 4 + 1)`` (E22b;
        # lane E).  Wrong record: the replication's region kept only its
        # post-operation (the fill); its count came from another region, so
        # no body was lowered and no signature recorded, yet the call to the
        # defaulted ``numerical_region_N`` was still emitted and C refused an
        # undefined function.  Rule: when this lowering records its regions'
        # signatures, a scheduled region with none, no pre-operations and no
        # stores has no body: its post-operations are its whole work.
        if (
            self.region_signatures
            and int(region_index) not in self.region_signatures
            and callee == f"numerical_region_{int(region_index)}"
            and not self.table_region_operations.get(int(region_index))
            and self.table_region_post_operations.get(int(region_index))
            and int(region_index) not in self.region_writing_indices
        ):
            self._emit_region_post_operations(region_index, location=location)
            return
        feeds, outputs = self.region_signatures.get(
            region_index, ((), ())
        )
        array_feeds = self.region_array_feed_ids.get(int(region_index), set())
        storage_arguments = [
            self.variant_row_values.get(int(value_id), self.external_value(value_id))
            if int(value_id) in array_feeds
            else self._region_feed(region_index, value_id)
            for value_id in feeds
        ]
        feed_meta = self.region_feed_meta.get(int(region_index), ())
        arguments = [
            SSAValue(
                storage.id,
                dtype=(
                    str(feed_meta[position].dtype)
                    if position < len(feed_meta) else storage.dtype
                ),
                shape=(
                    tuple(feed_meta[position].shape)
                    if position < len(feed_meta) else tuple(storage.shape)
                ),
                device=(
                    feed_meta[position].device
                    if position < len(feed_meta) else storage.device
                ),
                accounting={
                    **dict(storage.accounting or {}),
                    "ssa_storage_alias": int(storage.id),
                    "ssa_region_feed": (int(region_index), int(position)),
                    **(
                        {"ssa_loop_carried_feed": int(value_id)}
                        if int(value_id) in self.preserved_region_output_ids
                        else {}
                    ),
                },
            )
            for position, (value_id, storage) in enumerate(zip(
                feeds, storage_arguments,
            ))
        ]
        # Rule: an argument occurrence states its id's POSTED dtype -- the
        # row is the authority, the occurrence its view.  The feed's dtype
        # is the region formal's spelling (``region_feed_meta``, built from
        # the planned region's ``arguments``) and may be the authored
        # ``int`` where the storage's row declares ``int64``; spelling the
        # occurrence from the feed posted two target states to one shape
        # edge.  A storage with no posted row keeps the feed's dtype.
        for _position, _argument in enumerate(arguments):
            _cell = self._book().latest_ref(
                SSA_VALUE, (self._scope(), int(_argument.id)),
            )
            _recorded = (
                None if _cell is None
                else self._book().page(SSA_VALUE).cell(_cell.row, _cell.column)
            )
            if (
                isinstance(_recorded, SSAValueFact)
                and _recorded.dtype not in {None, "unknown"}
                and _argument.dtype != _recorded.dtype
            ):
                _argument.dtype = _recorded.dtype
        # REGION_CALL_RESULT: the region's signature cell (posted where the
        # signature was built) and the storage arguments it is fed.
        signature_cell = self._declared_cell(
            REGION_SIGNATURE.name, (self._scope(), int(region_index)),
        )
        aggregate = (
            self.fresh_value(
                dtype="ssa.aggregate", transform=REGION_CALL_RESULT,
                operands=(signature_cell, *storage_arguments),
            )
            if outputs
            else None
        )
        self.emit(
            Handler.Call,
            arguments,
            aggregate,
            attributes={
                "callee": callee,
                "region_index": region_index,
                "feed_ids": feeds,
                "feed_shapes": tuple(tuple(value.shape) for value in arguments),
                "feed_dtypes": tuple(str(value.dtype or "") for value in arguments),
                "output_ids": outputs,
                "result_convention": "ssa.aggregate",
            },
        )
        if aggregate is not None:
            for output_index, output_id in enumerate(outputs):
                index = self.constant_value(output_index, aggregate)
                attributes = {
                    "region_index": region_index,
                    "aggregate_index": output_index,
                    "source_output_id": output_id,
                }
                if int(output_id) in self.preserved_region_output_ids:
                    address = self.fresh_value(
                        dtype="ptr", transform=ADDRESS,
                        operands=(aggregate, index),
                    )
                    self.emit(
                        Handler.GetElementPtr,
                        [aggregate, index],
                        address,
                        attributes=attributes,
                    )
                    contract = self._value_from_meta(int(output_id))
                    scratch = self.fresh_value(
                        dtype=contract.dtype,
                        shape=contract.shape,
                        transform=LOAD, operands=(address,),
                    )
                    self.emit(
                        Handler.Load, [address], scratch,
                        attributes={
                            **attributes,
                            "discarded_carried_seed_projection": True,
                        },
                    )
                else:
                    self.indexed_load(
                        aggregate,
                        index,
                        output_id,
                        attributes=attributes,
                        # Control construction can encounter a consumer before
                        # lexical scheduling emits the region which defines it.
                        # ``external_value`` provisionally exposes that identity as
                        # a formal.  This load is its exact planned definition, so
                        # claim the same SSAValue object and retire the provisional
                        # formal.  ``produced_value`` still refuses this transition
                        # for declared in/out storage and versions those writes.
                        claim_provisional_definition=True,
                    )
        self._emit_region_post_operations(region_index, location=location)

    def _emit_region_post_operations(
        self, region_index: int, *, location: str,
    ) -> None:
        """Run the table operations scheduled after region ``region_index``."""

        for kind, table_arguments in self.table_region_post_operations.get(
            int(region_index), ()
        ):
            if kind == "lookup":
                self._emit_table_lookup(*table_arguments)
            elif kind == "store":
                self._emit_table_store(*table_arguments)
            elif kind == "delete":
                self._emit_table_delete(*table_arguments)
            elif kind == "fill":
                self._emit_sequence_fill(*table_arguments)
            elif kind == "append_fill":
                self._emit_sequence_append_fill(*table_arguments)
            elif kind == "append_slice":
                self._emit_sequence_append_slice(*table_arguments)
            elif kind == "prepend":
                self._emit_sequence_prepend(*table_arguments)
            elif kind == "prepend_packed_bytes":
                self._emit_sequence_prepend_packed_bytes(*table_arguments)
            elif kind == "pack_bits":
                self._emit_sequence_pack_bits(*table_arguments)
            elif kind == "extend":
                effect_id, destination_id, source_id = table_arguments
                self.lower_sequence_mutation(
                    ControlSequenceMutation(
                        sequence_value_id=int(destination_id),
                        operator="extend",
                        argument_value_ids=(int(source_id),),
                        effect_node_id=int(effect_id),
                        policy="duplicates",
                        argument_kind="sequence",
                    ),
                    path=f"{location}.structural",
                )
            else:
                raise ValueError(
                    f"unknown post-region table operation {kind!r}"
                )

    def new_block(self, stem: str, *, also: tuple = ()) -> BasicBlock:
        """A new block.  ``also`` names cells beyond the owning control
        block's that the block is made from (a tick's case literal)."""

        count = self.block_counts.get(stem, 0)
        self.block_counts[stem] = count + 1
        name = stem if count == 0 else f"{stem}.{count}"
        block = BasicBlock(name)
        self.blocks[name] = block
        self._post_ssa_block(name, stem, also=also)
        return block

    def _post_ssa_block(
        self, label: str, stem: str, *, also: tuple = (),
    ) -> Ref:
        """``ssa_block`` row ``(scope, function, label)`` (plan 100, 2.6),
        CONCORD.  ENTRY / FUNCTION_EXIT belong to the function: DERIVED
        from the shell ``control_program`` cell (when posted) and the
        function root.  Any other block is DERIVED from the ``control_block``
        cell of the control block being lowered; when that block has no row
        of its own the fact is ``Unresolved(SSA_BLOCK_OWNER_UNROUTED)``
        reading the nearest enclosing control cell (else the function's)."""

        from .concordance_declarations import (
            CONTROL_PROGRAM, SHELL, SSA_BLOCK, SSA_BLOCK_OWNER_UNROUTED,
            SSABlockKind as _Kind,
        )

        # The stem is the declared kind's value: an undeclared stem raises.
        kind = _Kind(stem)
        book = self._book()
        program = (
            None if self.lexical_read_scope is None
            else book.latest_ref(
                CONTROL_PROGRAM, (tuple(self.lexical_read_scope), SHELL),
            )
        )
        function_cells = tuple(
            cell for cell in (program, self._function_root()) if cell is not None
        )
        fact: Any = kind
        if kind in {_Kind.ENTRY, _Kind.FUNCTION_EXIT}:
            sources = function_cells
        elif self._control_cells and self._control_cells[-1] is not None:
            sources = (self._control_cells[-1],)
        else:
            enclosing = next(
                (cell for cell in reversed(self._control_cells) if cell is not None),
                None,
            )
            sources = (enclosing,) if enclosing is not None else function_cells
            fact = Unresolved(SSA_BLOCK_OWNER_UNROUTED, sources)
        sources = tuple(dict.fromkeys((
            *sources, *(cell for cell in also if isinstance(cell, Ref)),
        )))
        return book.post(
            SSA_BLOCK, (self._scope(), str(self.function_name), str(label)),
            fact, stage=self._stage(), provenance=Derived(sources),
            mode=Mode.CONCORD,
        )

    def function_exit_block(self) -> BasicBlock:
        """The one block every source ``return`` branches to (created lazily).

        It is registered when first needed but only ever filled by `finish`,
        which merges the return edges per output slot and emits the Ret.
        """

        if self._function_exit is None:
            self._function_exit = self.new_block("function_exit")
        return self._function_exit

    def _cast_on_edge(
        self, block: BasicBlock, value: SSAValue, dtype: str,
    ) -> SSAValue:
        """``value`` converted to ``dtype`` at the end of ``block``.

        The conversion is emitted before ``block``'s terminator, so it is
        the merge's incoming value on that edge.  A value already of
        ``dtype``, or one with no class (an absent arm), is returned as is.
        """

        if (
            value.dtype in {None, "unknown", "none", "None"}
            or str(value.dtype) == str(dtype)
        ):
            return value
        widened = self.fresh_value(
            dtype=str(dtype), transform=CONTROL_CAST, operands=(value,),
        )
        self.current = block
        terminator = block.instrs.pop()
        self.emit(
            Handler.Cast, [value], widened,
            attributes={"target_dtype": str(dtype)},
        )
        block.instrs.append(terminator)
        return widened

    _NUMERIC_CLASS = {
        "bool": "bool", "int": "int", "int32": "int", "int64": "int",
        "float": "float", "float16": "float", "float32": "float",
        "float64": "float", "double": "float",
    }

    def _numeric_join(self, values: Iterable[SSAValue]) -> str | None:
        """The class a scalar numeric join of ``values`` has, or ``None``.

        The planner's branch-join rule (``_value_shape_dtype``, ``phi``):
        the widest float when any arm is float, int64 when the arms are
        ints and bools.  Absent arms (``None``) state nothing.  Shaped or
        non-numeric arms, or arms that already agree, answer ``None``.
        """

        present = tuple(
            value for value in values
            if value.dtype not in {None, "unknown", "none", "None"}
        )
        dtypes = {str(value.dtype) for value in present}
        if (
            len(dtypes) < 2
            or any(tuple(value.shape or ()) for value in present)
            or not dtypes <= set(self._NUMERIC_CLASS)
        ):
            return None
        floats = tuple(
            {"float": "float64", "double": "float64"}.get(dtype, dtype)
            for dtype in dtypes if self._NUMERIC_CLASS[dtype] == "float"
        )
        if floats:
            from ..common.tensors.topological_reducer import _widest_element

            return _widest_element(*floats) or "float64"
        return "int64"

    def _numeric_join_arms(
        self,
        dtype: str | None,
        arms: tuple[tuple[BasicBlock, SSAValue], ...],
    ) -> tuple[SSAValue, ...]:
        """A scalar numeric join's arms, each in the join's class ``dtype``.

        Program: ``if c == 2: s = n else: s = n * 0.5; return s + 0.25``
        (corpus c770).  The join's class is the planner's (the widest float
        when an arm is float), and an int arm entered the Phi as an int:
        C converted it implicitly, LLVM refused the Phi.  Rule: an arm of
        a narrower numeric class converts on its own edge; an arm of a
        wider class than the join is refused, never narrowed.  Anything
        but scalar int/bool/float arms is left as it is.
        """

        numeric_class = self._NUMERIC_CLASS
        absent = {"None", "unknown", "none"}
        values = tuple(value for _block, value in arms)
        merged_class = numeric_class.get(str(dtype))
        if (
            merged_class is None
            or any(tuple(value.shape or ()) for value in values)
            or not all(
                str(value.dtype) in numeric_class or str(value.dtype) in absent
                for value in values
            )
        ):
            return values
        rank = {"bool": 0, "int": 1, "float": 2}
        narrowed = tuple(
            str(value.dtype) for value in values
            if str(value.dtype) in numeric_class
            and rank[numeric_class[str(value.dtype)]] > rank[merged_class]
        )
        if narrowed:
            # A conversion here would drop what Python keeps (3.5 -> 3).
            raise ValueError(
                f"{self.function_name}: a scalar join of class {dtype!r} "
                f"has arms of a wider class {narrowed!r}; no record "
                "settles the join's class to hold them"
            )
        current = self.current
        converted = tuple(
            self._cast_on_edge(block, value, str(dtype))
            if numeric_class.get(str(value.dtype), merged_class)
            != merged_class else value
            for block, value in arms
        )
        self.current = current
        return converted

    def _value_dominates_block(
        self, value: SSAValue, current_name: str,
    ) -> bool:
        """Whether this exact SSA object is resident on a block's entry."""

        if any(argument is value for argument in self.arguments):
            return True
        producer_blocks = {
            name
            for name, block in self.blocks.items()
            if any(instruction.res is value for instruction in block.instrs)
        }
        if not producer_blocks:
            return False
        if current_name in producer_blocks:
            return True
        block_names = tuple(self.blocks)
        entry_name = block_names[0]
        predecessors = {name: set() for name in block_names}
        for name, block in self.blocks.items():
            for successor in block.successors:
                if successor in predecessors:
                    predecessors[successor].add(name)
        # Only blocks reachable from the entry take part.  An unreachable
        # block (the continuation minted after an unconditional break/return
        # inside an arm) has no predecessors; letting it into the fixpoint
        # collapsed every dominator set downstream of the merge it feeds to
        # the block itself, so a value defined before an inner loop was
        # judged non-dominating at that loop's exit.
        reachable = {entry_name}
        frontier = [entry_name]
        while frontier:
            name = frontier.pop()
            for successor in self.blocks[name].successors:
                if successor in predecessors and successor not in reachable:
                    reachable.add(successor)
                    frontier.append(successor)
        dominators = {
            name: ({name} if name == entry_name else set(block_names))
            for name in block_names
        }
        changed = True
        while changed:
            changed = False
            for name in block_names:
                if name == entry_name or name not in reachable:
                    continue
                incoming = {
                    parent for parent in predecessors[name]
                    if parent in reachable
                }
                common = (
                    set.intersection(*(
                        dominators[parent] for parent in incoming
                    ))
                    if incoming else set()
                )
                updated = {name} | common
                if updated != dominators[name]:
                    dominators[name] = updated
                    changed = True
        # A carried "updated" slot is one SSAValue object written twice by
        # design: seeded in the preheader, rewritten in the body (see
        # ``lower_loop``).  Whichever of those writes dominates the current
        # block is the write the edge observes, so the slot is resident here
        # when ANY producer block dominates.  Requiring exactly one producer
        # rejected every carried slot at a break site, and the exit edge
        # silently carried the header Phi (the value from BEFORE this
        # iteration's update) instead.
        return any(
            producer in dominators[current_name]
            for producer in producer_blocks
        )

    def _value_dominates_current_edge(self, value: SSAValue) -> bool:
        """Whether this exact SSA object is resident on the current edge."""

        return self._value_dominates_block(value, self.current.name)

    def _is_stand_in(self, graph_id: int) -> bool:
        """Whether ``graph_id`` is bound only to the stand-in ``external_value``
        minted from absence (``Unresolved(NO_PRODUCER_AT_USE)`` on its binding
        row): no region has produced the id here."""

        fact = self._book().page(CONTROL_VALUE_BINDING).latest(
            (self._scope(), int(graph_id))
        )
        return (
            isinstance(fact, Unresolved)
            and fact.reason is NO_PRODUCER_AT_USE
        )

    def _phi_initial_binding(
        self, spelled_id: int, resident: SSAValue, phi_result: SSAValue,
        *, stage: Any,
    ) -> int:
        """Post ``phi_initial_binding`` for one Phi and return the resident id
        THE ROW states, which is what the Phi's ``initial_value_id`` carries.

        The graph speaks of the version that stood before a merge or a loop
        by its planning spelling (``spelled_id``: a graph id, a planning
        alias, a literal's graph node); the lowering holds that version as
        the SSA value ``resident``, whose id is not always the spelling (a
        planning alias of a region output, a minted literal, a restored
        carried slot).  An ``initial_value_id`` that kept the spelling named
        an id its function does not define.  DERIVED(the resident's and the
        Phi result's ``ssa_value`` cells).
        """

        from .concordance_declarations import PHI_INITIAL_BINDING

        book = self._book()
        row = (self._scope(), int(phi_result.id))
        book.post(
            PHI_INITIAL_BINDING, row, (int(spelled_id), int(resident.id)),
            stage=stage, provenance=Derived(self._cells(resident, phi_result)),
            mode=Mode.REVISE,
        )
        return int(book.page(PHI_INITIAL_BINDING).latest(row)[1])

    def _complete_current_join_value(
        self,
        candidate: SSAValue,
        incumbent: SSAValue,
        *,
        initial_value_id: int,
        initial_value: SSAValue,
        updated_value_id: int,
        site_node_id: int | None,
    ) -> SSAValue:
        """Make a partially defined carried value resident at this join.

        A predicated ``continue`` is represented after its enclosing arms have
        merged.  The value recorded at the source site can therefore dominate
        only the arm on which the continue predicate is true.  Complete that
        value with the loop-header incumbent on every other incoming edge.
        This is the ordinary SSA fixed point for the binding: an authored
        update wins where it is available; an equal-priority missing update
        retains the incumbent.
        """

        if self._value_dominates_current_edge(candidate):
            return candidate

        block_names = tuple(self.blocks)
        entry_name = block_names[0]
        predecessors = {name: [] for name in block_names}
        for name, block in self.blocks.items():
            for successor in block.successors:
                if successor in predecessors:
                    predecessors[successor].append(name)
        reachable = {entry_name}
        frontier = [entry_name]
        while frontier:
            name = frontier.pop()
            for successor in self.blocks[name].successors:
                if successor in predecessors and successor not in reachable:
                    reachable.add(successor)
                    frontier.append(successor)
        incoming_blocks = tuple(
            name for name in predecessors[self.current.name]
            if name in reachable
        )
        if not incoming_blocks:
            return incumbent
        incoming_values = tuple(
            candidate
            if self._value_dominates_block(candidate, predecessor)
            else incumbent
            for predecessor in incoming_blocks
        )
        if all(value is incoming_values[0] for value in incoming_values[1:]):
            return incoming_values[0]

        completed = self.fresh_value(
            dtype=str(candidate.dtype or incumbent.dtype or "unknown"),
            shape=tuple(candidate.shape or incumbent.shape),
            transform=PHI_LOOP_HEADER, operands=tuple(incoming_values),
            physical=self._phi_physical(*incoming_values),
        )
        self.emit(
            Handler.Phi,
            list(incoming_values),
            completed,
            attributes={
                "incoming_blocks": incoming_blocks,
                "binding": "loop_continue_carried",
                "initial_value_id": self._phi_initial_binding(
                    initial_value_id, initial_value, completed,
                    stage=CONTROL_SSA_LOOP,
                ),
                "initial_spelled_value_id": int(initial_value_id),
                "updated_value_id": int(updated_value_id),
                "site_node_id": site_node_id,
                "tie_policy": "incumbent",
            },
        )
        # Phis describe block entry and must precede any ordinary operation
        # already emitted into the merge block.
        emitted = self.current.instrs.pop()
        phi_end = next(
            (
                index for index, instruction in enumerate(self.current.instrs)
                if str(instruction.op).casefold() != "phi"
            ),
            len(self.current.instrs),
        )
        self.current.instrs.insert(phi_end, emitted)
        type_source_id = next((
            value_id for value_id in (
                int(updated_value_id), int(initial_value_id)
            )
            if value_id in self.native_value_type_abi
        ), None)
        if type_source_id is not None:
            completed_tag = self.merge_native_type_tags(
                int(type_source_id), completed,
                tuple(int(value.id) for value in incoming_values),
                incoming_blocks,
                binding="loop_continue_carried_native_type_tag",
            )
            if completed_tag is not None:
                # Companion Phis are block-entry definitions beside their
                # payload Phi.  A continue-site join must not leave its tag
                # after ordinary merge-block instructions.
                emitted_tag = self.current.instrs.pop()
                tag_phi_end = next(
                    (
                        index for index, instruction
                        in enumerate(self.current.instrs)
                        if str(instruction.op).casefold() != "phi"
                    ),
                    len(self.current.instrs),
                )
                self.current.instrs.insert(tag_phi_end, emitted_tag)
        return completed

    def _complete_loop_latch_carried(
        self,
        carried: list[tuple[int, int, SSAValue, SSAValue, SSAValue]],
        carried_phis: dict[int, Instr],
        carried_updates: dict[int, SSAValue],
        continue_edges: list[tuple[BasicBlock, tuple[SSAValue, ...]]],
    ) -> None:
        """Resolve every reachable latch edge to one carried value per name."""

        block_names = tuple(self.blocks)
        entry_name = block_names[0]
        predecessors = {name: [] for name in block_names}
        for name, block in self.blocks.items():
            for successor in block.successors:
                if successor in predecessors:
                    predecessors[successor].append(name)
        reachable = {entry_name}
        frontier = [entry_name]
        while frontier:
            name = frontier.pop()
            for successor in self.blocks[name].successors:
                if successor in predecessors and successor not in reachable:
                    reachable.add(successor)
                    frontier.append(successor)
        incoming_blocks = tuple(
            name for name in predecessors[self.current.name]
            if name in reachable
        )
        continue_by_block = {
            edge.name: values for edge, values in continue_edges
            if edge.name in incoming_blocks
        }
        for index, (
            updated_id, initial_id, initial_value, reserved, incumbent
        ) in enumerate(carried):
            candidate = carried_updates[index]
            incoming_values = tuple(
                continue_by_block[predecessor][index]
                if predecessor in continue_by_block
                else (
                    candidate
                    if self._value_dominates_block(candidate, predecessor)
                    else incumbent
                )
                for predecessor in incoming_blocks
            )
            if not incoming_values:
                completed = incumbent
            elif all(
                value is incoming_values[0] for value in incoming_values[1:]
            ):
                completed = incoming_values[0]
            else:
                completed = self.fresh_value(
                    dtype=str(candidate.dtype or incumbent.dtype or "unknown"),
                    shape=tuple(candidate.shape or incumbent.shape),
                    transform=PHI_LOOP_HEADER, operands=tuple(incoming_values),
                    physical=self._phi_physical(*incoming_values),
                )
                self.emit(
                    Handler.Phi,
                    list(incoming_values),
                    completed,
                    attributes={
                        "incoming_blocks": incoming_blocks,
                        "binding": "loop_latch_carried",
                        "initial_value_id": self._phi_initial_binding(
                            initial_id, initial_value, completed,
                            stage=CONTROL_SSA_LOOP,
                        ),
                        "initial_spelled_value_id": int(initial_id),
                        "updated_value_id": int(updated_id),
                        "tie_policy": "incumbent",
                    },
                )
            if os.environ.get("TURING_DEBUG_LOOP_ALIAS_PUBLICATION"):
                print(
                    "DEBUG-LOOP-LATCH-CHOICE "
                    f"fn={self.function_name} "
                    f"updated={int(updated_id)} initial={int(initial_id)} "
                    f"candidate={int(candidate.id)} "
                    f"incumbent={int(incumbent.id)} "
                    f"incoming_blocks={incoming_blocks!r} "
                    f"incoming={tuple(int(value.id) for value in incoming_values)!r} "
                    f"completed={int(completed.id)}",
                    file=sys.stderr,
                    flush=True,
                )
            carried_phis[index].args[1] = completed
            carried_updates[index] = completed
            type_source_id = next((
                value_id for value_id in (int(updated_id), int(initial_id))
                if value_id in self.native_value_type_abi
            ), None)
            if type_source_id is not None:
                fact = self.native_value_type_abi[int(type_source_id)]
                alternatives = tuple(
                    fact.get("alternatives", ())
                    if isinstance(fact, Mapping)
                    else getattr(fact, "alternatives", ())
                )
                if len(alternatives) > 1:
                    if len(incoming_values) > 1 and not all(
                        value is incoming_values[0]
                        for value in incoming_values[1:]
                    ):
                        completed_tag = self.merge_native_type_tags(
                            int(type_source_id), completed,
                            tuple(int(value.id) for value in incoming_values),
                            incoming_blocks,
                            binding="loop_latch_carried_native_type_tag",
                        )
                    else:
                        completed_tag = self.native_type_tag_for(
                            int(completed.id), fact,
                        )
                        if completed_tag is not None:
                            self.post_native_type_tag(
                                int(type_source_id), completed_tag, fact,
                                completed, candidate, incumbent,
                            )
                    header_tag_phi = self.native_type_tag_phi_by_payload.get(
                        int(carried_phis[index].res.id)
                    )
                    if completed_tag is None or header_tag_phi is None:
                        raise ValueError(
                            "loop-carried native union lost its companion "
                            "Phi: "
                            f"function={self.function_name!r}, "
                            f"initial={int(initial_id)}, "
                            f"updated={int(updated_id)}"
                        )
                    header_tag_phi.args[1] = completed_tag
                    header_tag = header_tag_phi.res
                    self.native_value_type_tags[int(initial_id)] = header_tag
                    self.native_value_type_tags[int(updated_id)] = header_tag
                    self.native_value_type_tags[int(completed.id)] = (
                        completed_tag
                    )
            source_loop_node_id = carried_phis[index].attributes.get(
                "source_loop_node_id"
            )
            key = (str(self.tensor_shape_concordance_scope), source_loop_node_id)
            if key in self.loop_frames:
                self.loop_frames[key].setdefault("updates", {})[index] = completed
            # LOOP_LATCH: the body's binding of the update is the cause.
            self._bind(
                int(updated_id), completed, BindingKind.LOOP_LATCH,
                candidate, incumbent,
            )
            if (
                source_loop_node_id is not None
                and int(completed.id) != int(reserved.id)
            ):
                from .identity_concordance import rebind_loop_scope_inner

                rebind_loop_scope_inner(
                    self.function_name,
                    source_loop_node_id,
                    int(reserved.id),
                    int(completed.id),
                    "complete_loop_latch_carried",
                    cells=self._loop_scope_value_cells(
                        int(reserved.id), int(completed.id),
                    ),
                )
                completed.accounting = {
                    **dict(completed.accounting or {}),
                    "loop_scope_inner_transition": (
                        int(reserved.id), int(completed.id),
                        "complete_loop_latch_carried",
                    ),
                }

    def _load_reads_before_effect(self, effect_id: int | None) -> None:
        """Load the pending row reads that source-precede ``effect_id``."""

        preceding = self.__dict__.get("effect_preceding_row_reads") or {}
        if effect_id is None or not preceding.get(int(effect_id)):
            return
        for read_id in preceding.pop(int(effect_id)):
            pending = self.consumer_row_loads.get(int(read_id))
            if pending is not None and int(read_id) not in self.external_values:
                del self.consumer_row_loads[int(read_id)]
                self._emit_sequence_row_load(*pending)
            elif int(read_id) in self.sequence_length_values:
                # c632's row=len(field) precedes append but its scalar is
                # consumed at return.  Freeze that exact temporal read at
                # the same pre-effect boundary as an indexed row load.
                self.external_value(int(read_id))

    def emit(
        self,
        op: Handler,
        args: list[SSAValue],
        result: SSAValue | None = None,
        *,
        attributes: dict[str, Any] | None = None,
    ) -> None:
        resolved_attributes = dict(attributes or {})
        self._load_reads_before_effect(resolved_attributes.get(
            "source_effect_node_id", resolved_attributes.get("plan_callsite_id"),
        ))
        if self.active_deployments:
            resolved_attributes.setdefault(
                "deployment_memberships",
                tuple(self.active_deployments),
            )
        instruction = Instr(
            op.value,
            args,
            result,
            attributes=resolved_attributes,
        )
        if result is not None:
            # Every emitted definition, by object: ``produced_value`` versions
            # a second definition of a defined object (``_defines``).
            self.__dict__.setdefault("_defined_results", {})[id(result)] = result
        captured_sink = getattr(self, "_captured_instruction_sink", None)
        if captured_sink is not None:
            captured_sink.append(instruction)
            return
        self.current.instrs.append(instruction)
        if self.evolution is not None and self.ssa_evolution is not None:
            from .evolution_metagraph import EvolutionComponentRef

            local_id = (
                str(result.id)
                if result is not None
                else f"{self.current.name}:{self._evolution_instruction}:{op.value}"
            )
            self._evolution_instruction += 1
            sources = (
                (self._evolution_source,)
                if self._evolution_source is not None else ()
            )
            target = self.evolution.component(
                self.ssa_evolution,
                local_id,
                label=str(op.value),
                kind="control-instruction",
                attributes={
                    "block": self.current.name,
                    "control_op": str(op.value),
                    **{
                        key: resolved_attributes[key]
                        for key in (
                            "deployment_memberships",
                            "deployment_frame",
                            "region_id",
                            "region_index",
                            "scale",
                            "join_mode",
                            "reduction_operator",
                            "allow_reassociation",
                            "schedule_preference",
                            "predicate_value_id",
                            "recursion_region_id",
                        )
                        if key in resolved_attributes
                    },
                },
                consumes=sources,
            )
            if sources:
                self.evolution.handoff(
                    target,
                    sources,
                    transformation="control-ir-to-ssa",
                )
            for position, argument in enumerate(args):
                argument_ref = EvolutionComponentRef(
                    self.ssa_evolution.id,
                    str(argument.id),
                )
                if self.evolution.has_component(argument_ref):
                    self.evolution.relationship(
                        self.ssa_evolution,
                        argument_ref,
                        target,
                        role=f"arg{position}",
                    )

    def emit_deployment_boundary(
        self, op: Handler, record: dict[str, Any]
    ) -> tuple[str, int]:
        """Emit a structural frame marker; it performs no numeric work."""
        site = (self.current.name, len(self.current.instrs))
        join = record["join"]
        self.emit(op, [], attributes={
            "deployment_frame": True,
            "region_id": int(record["region_id"]),
            "scale": int(record.get("scale", 1)),
            "join_mode": join.mode.value,
            "reduction_operator": join.reduction_operator,
            "allow_reassociation": bool(join.allow_reassociation),
            "schedule_preference": str(record["schedule_preference"]),
        })
        record["deploy_site" if op is Handler.Deploy else "join_site"] = site
        return site

    def branch(self, target: BasicBlock) -> None:
        self.emit(
            Handler.Br,
            [],
            attributes={"target": target.name},
        )
        self.current.successors.append(target.name)

    def conditional_branch(
        self,
        condition: SSAValue,
        if_true: BasicBlock,
        if_false: BasicBlock,
    ) -> None:
        self.emit(
            Handler.CondBr,
            [condition],
            attributes={
                "true_target": if_true.name,
                "false_target": if_false.name,
            },
        )
        self.current.successors.extend((if_true.name, if_false.name))

    def expression_value(
        self,
        expression: str,
        *,
        location: str,
    ) -> SSAValue:
        spelling = str(expression).strip()
        iterable_extent = re.fullmatch(
            r"__iterable_extent_(\d+)__", spelling
        )
        if iterable_extent is not None:
            iterable_id = int(iterable_extent.group(1))
            selected_extent = self.selected_child_extent_values.get(iterable_id)
            if selected_extent is not None:
                return selected_extent
            resident_id = iterable_id
            seen_aliases: set[int] = set()
            while (
                resident_id in self.value_aliases
                and resident_id not in seen_aliases
            ):
                seen_aliases.add(resident_id)
                resident_id = int(self.value_aliases[resident_id])
            child_selection = self.child_table_selections.get(iterable_id)
            if child_selection is not None:
                if iterable_id in self.child_selection_validity:
                    self.shortfalls.append(SSALoweringShortfall(
                        "ssa-table", "bounded-child-query", self.function_name,
                        "a possibly exhausted child selection needs an exact guarded iterable extent",
                    ))
                    return self.constant_value(0)
                pool, handle = child_selection
                pool_length = self.external_value(pool.length_value_id)
                length_address = self.fresh_value(
                    dtype="ptr", transform=ADDRESS,
                    operands=(pool_length, handle),
                )
                extent = self.fresh_value(
                    dtype="int", transform=LOAD, operands=(length_address,),
                )
                self.emit(
                    Handler.GetElementPtr,
                    [pool_length, handle],
                    length_address,
                    attributes={"binding": "child_table_length"},
                )
                self.emit(
                    Handler.Load, [length_address], extent,
                    attributes={"binding": "child_table_length"},
                )
                return extent
            resident = self.sequence_descriptors.get(resident_id)
            if resident is not None:
                length_cell = self.sequence_storage_values[resident_id][
                    len(resident.column_value_ids)
                ]
                extent = self.fresh_value(
                    dtype="int64", transform=LOAD,
                    operands=(length_cell, iterable_id),
                )
                self.emit(
                    Handler.Load, [length_cell], extent,
                    attributes={
                        "binding": "resident_iterable_length",
                        "sequence_id": int(resident_id),
                        "source_value_id": iterable_id,
                    },
                )
                return extent
            nested_target_id = self.nested_iterable_targets.get(iterable_id)
            if nested_target_id is not None:
                child_key = ("iterable", iterable_id, -1)
                _child_data, child_lengths, _sequence_stride, _row_stride = (
                    self._nested_child_storage(child_key, nested_target_id)
                )
                handle = self.external_value(iterable_id, dtype="int")
                length_address = self.fresh_value(
                    dtype="ptr", transform=ADDRESS,
                    operands=(child_lengths, handle),
                )
                extent = self.fresh_value(
                    dtype="int", transform=LOAD, operands=(length_address,),
                )
                self.emit(
                    Handler.GetElementPtr,
                    [child_lengths, handle],
                    length_address,
                    attributes={"binding": "nested_row_length"},
                )
                self.emit(
                    Handler.Load, [length_address], extent,
                    attributes={"binding": "nested_row_length"},
                )
                return extent
            source = self.external_value(iterable_id)
            extent = self.fresh_value(
                dtype="int", transform=CONTROL_EXPRESSION, operands=(source,),
            )
            self.emit(
                Handler.Call,
                [source],
                extent,
                attributes={
                    "tensor_operation": "extent",
                    "extent_kind": "dim",
                    "axis": 0,
                    "binding": "iterable_extent",
                    "source_value_id": iterable_id,
                },
            )
            return extent
        value_match = re.fullmatch(r"value_(\d+)", spelling)
        if value_match is not None:
            return self.external_value(int(value_match.group(1)))
        uniform = self.uniform_values.get(spelling)
        if uniform is not None:
            # In ``for i in range(n): for j in range(i, n): ...``, the
            # declared u_control_i initially names a formal, then the outer
            # loop binds its graph id to its induction Phi. Returning the
            # cached declaration froze the inner start and leaked that local
            # as an unnamed function input. The declaration names the id;
            # the current binding owns its value, as for arithmetic bounds.
            return self.external_value(int(uniform.id))
        local = self.local_control_values.get(spelling)
        if local is not None:
            return local
        try:
            literal = int(spelling, 10)
        except ValueError:
            lowered = self._control_arithmetic_value(spelling)
            if lowered is not None:
                return lowered
            value = self.fresh_value(dtype="int", transform=LOAD)
            self.emit(
                Handler.Load,
                [],
                value,
                attributes={"control_expression": spelling},
            )
            self.shortfalls.append(
                SSALoweringShortfall(
                    "control",
                    "expression",
                    location,
                    f"control expression {spelling!r} is retained as a "
                    "symbolic load",
                )
            )
            return value
        value = self.fresh_value(dtype="int", transform=CONTROL_CONST)
        self.emit(
            Handler.Const,
            [],
            value,
            attributes={"value": literal},
        )
        return value

    def _control_arithmetic_value(self, spelling: str) -> SSAValue | None:
        """Lower planner-authored scalar arithmetic to ordinary SSA.

        Dynamic loop bounds are retained as small expressions over resident
        ``u_control_<id>`` values (for example ``((u_control_6 -
        u_control_8) / u_control_4) + 1``).  They are compiler IR, not host
        Python to evaluate.  Parse only the closed arithmetic vocabulary the
        planner emits and return ``None`` for every other shape so the caller
        preserves its explicit symbolic-load shortfall.
        """

        try:
            expression = ast.parse(spelling, mode="eval").body
        except (SyntaxError, ValueError):
            return None

        binary_handlers = {
            ast.Add: Handler.Add,
            ast.Sub: Handler.Sub,
            ast.Mult: Handler.Mul,
            ast.Div: Handler.Div,
            ast.FloorDiv: Handler.FloorDiv,
            ast.Mod: Handler.Mod,
        }

        def lower(node: ast.AST) -> SSAValue | None:
            if isinstance(node, ast.Constant) and isinstance(
                node.value, (bool, int, float)
            ):
                value = self.fresh_value(
                    dtype="bool" if isinstance(node.value, bool)
                    else "int" if isinstance(node.value, int)
                    else "float64",
                    transform=CONTROL_CONST,
                )
                self.emit(
                    Handler.Const, [], value,
                    attributes={"value": node.value},
                )
                return value
            if isinstance(node, ast.Name):
                if re.fullmatch(r"__iterable_extent_\d+__", node.id):
                    return self.expression_value(node.id, location='iterable_cardinality')
                control = re.fullmatch(r"u_control_(\d+)", node.id)
                if control is not None:
                    return self.external_value(int(control.group(1)))
                value = re.fullmatch(r"value_(\d+)", node.id)
                if value is not None:
                    return self.external_value(int(value.group(1)))
                uniform = self.uniform_values.get(node.id)
                return (
                    self.external_value(int(uniform.id))
                    if uniform is not None else
                    self.local_control_values.get(node.id)
                )
            if isinstance(node, ast.UnaryOp) and isinstance(
                node.op, (ast.UAdd, ast.USub)
            ):
                operand = lower(node.operand)
                if operand is None:
                    return None
                if isinstance(node.op, ast.UAdd):
                    return operand
                result = self.fresh_value(
                    dtype=operand.dtype,
                    shape=operand.shape,
                    transform=CONTROL_EXPRESSION, operands=(operand,),
                )
                self.emit(Handler.Neg, [operand], result)
                return result
            if isinstance(node, ast.BinOp):
                handler = binary_handlers.get(type(node.op))
                if handler is None:
                    return None
                left = lower(node.left)
                right = lower(node.right)
                if left is None or right is None:
                    return None
                result = self.fresh_value(
                    dtype=left.dtype or right.dtype,
                    shape=left.shape or right.shape,
                    transform=CONTROL_EXPRESSION, operands=(left, right),
                )
                self.emit(
                    handler,
                    [left, right],
                    result,
                    attributes={"binding": "control_expression"},
                )
                return result
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == "min"
                and len(node.args) >= 2
                and not node.keywords
            ):
                values = tuple(lower(argument) for argument in node.args)
                if any(value is None for value in values):
                    return None
                incumbent = values[0]
                for candidate in values[1:]:
                    predicate = self.fresh_value(
                        dtype="bool", transform=CONTROL_PREDICATE,
                        operands=(candidate, incumbent),
                    )
                    self.emit(
                        Handler.Lt, [candidate, incumbent], predicate,
                        attributes={"binding": "control_minimum"},
                    )
                    selected = self.fresh_value(
                        dtype=incumbent.dtype or candidate.dtype,
                        shape=incumbent.shape or candidate.shape,
                        transform=CONTROL_EXPRESSION,
                        operands=(predicate, candidate, incumbent),
                    )
                    self.emit(
                        Handler.Select,
                        [predicate, candidate, incumbent], selected,
                        attributes={"binding": "control_minimum"},
                    )
                    incumbent = selected
                return incumbent
            return None

        return lower(expression)

    def _control_leaf(self, expression: ControlExpression) -> SSAValue:
        """A ``value`` leaf, read by the binding its operand read.

        The leaf carries its operand position (``read``); the binding is
        the book's ``lexical_read_binding`` fact.  Outside loops, or for a
        leaf with no recorded position, the value id is the answer.
        """

        value_id = int(expression.value_id)
        if (
            expression.read is None
            or self.lexical_read_scope is None
            or not self.enclosing_loop_states
        ):
            return self.external_value(value_id)
        return self._read(
            value_id,
            self._operand_bindings((tuple(expression.read),)),
            f"control expression leaf {value_id}",
        )

    def lower_control_expression(
        self,
        expression: ControlExpression,
        *,
        result_override: SSAValue | None = None,
    ) -> SSAValue:
        if expression.op == "value":
            return self._control_leaf(expression)
        if expression.op == "optional_presence":
            if expression.value_id is None:
                raise ValueError("optional presence requires a value id")
            value = self.external_value(
                int(expression.value_id), dtype="bool"
            )
            # Rule: post first; accounting is a view.  The presence value's
            # physical record (bool, scalar, rank 0) is revised onto its
            # ``ssa_value`` row DERIVED from the presence expression's
            # canonical cell and the payload's canonical cell, then the
            # accounting below is set FROM that posted fact.
            _presence_sources = (
                int(expression.value_id),
                *((int(expression.optional_payload_value_id),)
                  if expression.optional_payload_value_id is not None else ()),
            )
            self._value_cell(value, *_presence_sources)
            _presence_cell = self._revise_value(
                value, *_presence_sources,
                physical={
                    "physical_dtype": "bool", "storage": "scalar", "rank": 0,
                    "arena": False, "device": value.device,
                },
            )
            _presence_fact = self._book().page(SSA_VALUE).cell(
                _presence_cell.row, _presence_cell.column,
            )
            value.accounting = {
                **dict(value.accounting or {}),
                **({
                    "program_abi_record": expression.program_abi_record,
                } if expression.program_abi_record is not None else {}),
                **({
                    "program_abi_parameter": expression.program_abi_parameter,
                } if expression.program_abi_parameter is not None else {}),
                **({
                    "program_abi_field": expression.program_abi_field,
                } if expression.program_abi_field is not None else {}),
                "program_abi_storage": _presence_fact.storage,
                "program_abi_optional_presence": True,
                "program_abi_optional_present_when": True,
                "physical_dtype": _presence_fact.physical_dtype,
                "physical_dtype_provenance": (
                    "control_ir_optional_presence"
                ),
                "physical_dtype_tie_policy": "incumbent",
            }
            if expression.optional_payload_value_id is not None:
                self.optional_scalar_presence_by_payload[
                    int(expression.optional_payload_value_id)
                ] = value
            return value
        if expression.op == "native_type_identity":
            if expression.value_id is None:
                raise ValueError("native type identity requires a value id")
            identities = tuple(map(str, expression.literal or ()))
            if not identities:
                raise ValueError(
                    "native type identity requires canonical alternatives"
                )
            return self._native_value_type_predicate(
                int(expression.value_id), identities,
                result_override=result_override,
                subtype=False,
                receipt={
                    "control_expression": "native_type_identity",
                    "subject_value_id": int(expression.value_id),
                    "accepted_types": identities,
                },
            )
        if expression.op == "const":
            if isinstance(expression.literal, (tuple, list)):
                # Data-context aggregate constants use ordinary typed SSA
                # Const storage. Never reduce a row payload to truthiness.
                import numpy as np
                literal = np.asarray(expression.literal)
                if literal.dtype.kind not in "bifu":
                    raise ValueError("control row constant needs a rectangular numeric layout")
                result = result_override or self.fresh_value(
                    dtype=str(literal.dtype), shape=tuple(literal.shape),
                    transform=CONTROL_CONST, operands=(expression.value_id,),
                )
                self.emit(Handler.Const, [], result,
                    attributes={"values": literal.tolist()})
                return result
            result = result_override or self.fresh_value(
                dtype="bool" if isinstance(expression.literal, bool) else None,
                transform=CONTROL_CONST, operands=(expression.value_id,),
            )
            self.emit(
                Handler.Const, [], result,
                attributes={"value": expression.literal},
            )
            return result
        if expression.op == "sequence_nonempty":
            if expression.value_id is None:
                raise ValueError("sequence truth predicate requires a value id")
            sequence_id = int(expression.value_id)
            descriptor = self._sequence_descriptor(
                sequence_id,
                policy=("unique" if bool(expression.literal) else "duplicates"),
                writable=True,
                location=f"control.sequence_nonempty[{sequence_id}]",
            )
            if descriptor is None:
                raise ValueError(
                    "cannot lower sequence truth predicate with conflicting "
                    f"storage policy for value {sequence_id}"
                )
            length_address = self.sequence_storage_values[sequence_id][
                len(descriptor.column_value_ids)
            ]
            length = self.fresh_value(
                dtype="int", transform=LOAD,
                operands=(length_address, self._sequence_contract_cell(sequence_id)),
            )
            self.emit(
                Handler.Load,
                [length_address],
                length,
                attributes={
                    "binding": "ssa_sequence_length",
                    "sequence_value_id": sequence_id,
                },
            )
            zero = self.constant_value(0, length)
            result = result_override or self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE, operands=(length, zero),
            )
            self.emit(
                Handler.Gt,
                [length, zero],
                result,
                attributes={
                    "binding": "sequence_nonempty",
                    "sequence_value_id": sequence_id,
                },
            )
            return result
        none_test = self._union_none_identity_subject(expression)
        if none_test is not None:
            # Program: ``v = maybe(row, flag); if v is None: ...`` where
            # ``maybe`` returns ``row + 1 if flag > 0 else None``.  Wrong
            # record: the identity test lowered to ``Eq(payload, None)``,
            # which reads only the int arm's storage and is never true.  Rule:
            # ``is None`` on a value whose type ABI is a union with NoneType
            # is an exact type-identity test of that union's tag.
            is_none = self._native_value_type_predicate(
                none_test, ("builtins.NoneType",),
                result_override=(
                    result_override if expression.op == "eq" else None
                ),
                subtype=False,
                receipt={
                    "control_expression": f"none_identity_{expression.op}",
                    "subject_value_id": int(none_test),
                    "accepted_types": ("builtins.NoneType",),
                },
            )
            if expression.op == "eq":
                result = is_none
            else:
                result = result_override or self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE,
                    operands=(is_none,),
                )
                self.emit(Handler.LNot, [is_none], result, attributes={
                    "binding": "control_expression",
                    "source_value_id": expression.value_id,
                })
            if expression.value_id is not None:
                self._bind(
                    int(expression.value_id), result,
                    BindingKind.CONTROL_EXPRESSION, is_none,
                )
            return result
        operand_values = [
            self.lower_control_expression(operand)
            for operand in expression.operands
        ]
        if expression.op in {"float", "int", "bool"}:
            return operand_values[0]
        if expression.op == "item":
            source = operand_values[0]
            if not source.shape:
                if expression.value_id is not None:
                    source_id = int(expression.value_id)
                    # A rank-0 operand IS the item's value: the merge is one
                    # ``scalar_item_merge`` row and the item id's binding.
                    self._post_scalar_item_merge(source_id, source)
                    self._bind(
                        source_id, source, BindingKind.CONTROL_EXPRESSION,
                        self._book().latest_ref(
                            SCALAR_ITEM_MERGE, (self._scope(), source_id),
                        ),
                    )
                    self.control_identity_receipts.append((
                        source_id, int(source.id), "scalar_item_identity",
                    ))
                return source
            index = self.constant_value(0, source)
            address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(source, index),
            )
            self.emit(
                Handler.GetElementPtr, [source, index], address,
                attributes={"binding": "control_scalar_item"},
            )
            result = result_override or self.fresh_value(
                dtype=source.dtype, transform=LOAD, operands=(address,),
            )
            self.emit(
                Handler.Load, [address], result,
                attributes={"binding": "control_scalar_item"},
            )
            return result
        handlers = {
            "add": Handler.Add, "sub": Handler.Sub,
            "mul": Handler.Mul, "div": Handler.Div,
            "neg": Handler.Neg,
            "lt": Handler.Lt, "le": Handler.Le,
            "gt": Handler.Gt, "ge": Handler.Ge,
            "eq": Handler.Eq, "ne": Handler.Ne,
            "and": Handler.LAnd, "or": Handler.LOr,
            "not": Handler.LNot,
            "bitand": Handler.And, "bitor": Handler.Or,
            "bitxor": Handler.Xor, "shl": Handler.Shl,
            "shr": Handler.Shr,
            # Both native scalar emitters implement the registry's intrinsic
            # spelling. A Python math call must not survive this boundary.
            "isfinite": Handler.IsFinite,
        }
        handler = handlers.get(expression.op)
        if handler is None:
            raise ValueError(
                f"unsupported control expression {expression.op!r}"
            )
        result = result_override or self.fresh_value(
            dtype=(
                "bool" if expression.op in {
                    "lt", "le", "gt", "ge", "eq", "ne",
                    "and", "or", "not",
                } else operand_values[0].dtype
            ),
            transform=CONTROL_EXPRESSION,
            operands=(*operand_values, expression.value_id),
        )
        self.emit(handler, operand_values, result, attributes={
            "binding": "control_expression",
            "source_value_id": expression.value_id,
        })
        if expression.value_id is not None:
            # CONTROL_EXPRESSION: the operand bindings are the cause.
            self._bind(
                int(expression.value_id), result,
                BindingKind.CONTROL_EXPRESSION, *operand_values,
            )
        return result

    def _union_none_identity_subject(self, expression) -> int | None:
        """The subject id of ``subject is None`` when its type ABI is a union
        that admits NoneType; otherwise None (an ordinary comparison)."""

        if expression.op not in {"eq", "ne"} or len(expression.operands) != 2:
            return None
        values = tuple(
            operand for operand in expression.operands
            if operand.op == "value" and operand.value_id is not None
        )
        nones = tuple(
            operand for operand in expression.operands
            if operand.op == "const" and operand.literal is None
            and not operand.operands
        )
        if len(values) != 1 or len(nones) != 1:
            return None
        subject_id = int(values[0].value_id)
        fact = self.native_value_type_abi.get(subject_id)
        alternatives = tuple(map(str,
            fact.get("alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "alternatives", ())
        ))
        if len(alternatives) <= 1 or "builtins.NoneType" not in alternatives:
            return None
        # Only a fixed-width value union carries its tag beside the payload.
        # Program: bootstrap unit 35 (``found = self._resolved(...)``, an
        # Optional[tuple]).  Wrong record: its ``is None`` minted a pending
        # tag that nothing publishes; an optional aggregate's presence is a
        # member of its own layout.  Rule: aggregate or reference arms keep
        # the ordinary comparison and its optional-aggregate lowering.
        physical = tuple(
            fact.get("physical_alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "physical_alternatives", ())
        )
        if not physical or any(
            str(arm.storage) not in {"none", "scalar"} for arm in physical
        ):
            return None
        return subject_id

    def _post_scalar_item_merge(self, item_id: int, source: SSAValue) -> Ref:
        """``scalar_item_merge`` row ``(function scope, item)`` -> the
        merged source's ``ssa_value`` cell, DERIVED(the ``item_operand``
        cell when the planner declared it, the operand's binding cell)."""

        book = self._book()
        row = (self._scope(), int(item_id))
        source_cell = self._value_cell(source)
        latest = book.latest_ref(SCALAR_ITEM_MERGE, row)
        if latest is not None and (
            book.pages[SCALAR_ITEM_MERGE.name].cells.get((row, latest.column))
            == source_cell
        ):
            return latest
        sources = self._cells(
            self._declared_cell(
                "item_operand", (self.lexical_read_scope, int(item_id)),
            ) if self.lexical_read_scope is not None else None,
            self._binding_cell(int(source.id)), source_cell,
            self._canonical_cell(item_id),
        )
        if latest is not None and self.__dict__.get("_latch_test_generation"):
            # Program: ``while (lim - total).item() > eps: total = total +
            # dt`` (the tire's ``run_superstep``, lanes plan A4).  Wrong
            # record: the latch re-evaluates the test with ``total`` at its
            # carried value, so the item's operand is a new SSA value, and
            # the entry test's row (one per function) refused it as a
            # disagreement.  Rule: as for every value the latch's test
            # defines again, this is the item's next generation -- a
            # revision of its row derived from the entry row and the
            # latch's operand.  Outside the latch a second source is still
            # a disagreement.
            return book.post(
                SCALAR_ITEM_MERGE, row, source_cell,
                stage=self.active_stage,
                provenance=Derived(self._cells(latest, *sources)),
                mode=Mode.REVISE,
            )
        return book.post(
            SCALAR_ITEM_MERGE, row, source_cell,
            stage=self.active_stage,
            provenance=Derived(sources),
            mode=Mode.CONCORD,
        )

    def lower(self, block: ControlBlock, *, path: str = "root") -> None:
        if os.environ.get("TURING_DEBUG_CONTROL_OVERLAY"):
            print(
                f"DEBUG-LOWER fn={self.function_name} path={path} "
                f"block={type(block).__name__}"
                + (
                    f" action={block.action} source_action={block.source_action}"
                    f" return_value_ids={block.return_value_ids!r}"
                    if isinstance(block, LoopControlBlock) else ""
                )
                + (
                    f" lines={block.lines!r}"
                    if isinstance(block, StatementBlock) else ""
                ),
                file=sys.stderr,
            )
        previous = self._evolution_source
        if self.evolution is not None:
            self._evolution_source = self.evolution.component_for_artifact(block)
        # A SequenceBlock is a container with no row (flattened for
        # placement); its children are owned by their own rows.
        owned = not isinstance(block, SequenceBlock)
        if owned:
            from .control_source import control_block_cell

            self._control_cells.append(control_block_cell(
                self._book(), self.lexical_read_scope, block,
            ))
        try:
            self._lower(block, path=path)
        finally:
            self._evolution_source = previous
            if owned:
                self._control_cells.pop()

    def _emit_resource_cleanup(self, action: str, path: str) -> None:
        for scope, loop_depth in reversed(self.resource_scopes):
            if action != "return" and loop_depth < len(self.loop_targets):
                continue  # This exit stays inside a scope surrounding the loop.
            for index, operation in enumerate(scope.cleanup):
                self.lower(operation, path=f"{path}.cleanup[{scope.source_scope_id}:{index}]")

    def _pure_region_index(self, child: "ControlBlock") -> int | None:
        """The region a child emits, when reordering it is provably safe.

        Safe means: the child is a single scheduled-region statement, the
        region has a recorded signature to order by, and it carries no table
        or sequence operations -- those are EFFECTS, whose relative order the
        plan may be preserving for reasons dataflow over value ids cannot
        see. An effectful or unrecognised child is a reordering barrier.
        """

        if not isinstance(child, StatementBlock) or len(child.lines) != 1:
            return None
        match = _REGION_MARKER.fullmatch(str(child.lines[0]))
        if match is None:
            return None
        region_index = int(match.group(1))
        if region_index not in self.region_signatures:
            return None
        if _region_table_operations(
            region_index,
            self.table_region_operations,
            self.table_region_post_operations,
        ):
            return None
        return region_index

    def _dependency_ordered(
        self, children: "tuple[ControlBlock, ...]"
    ) -> "list[ControlBlock]":
        """Reorder contiguous runs of pure region statements by dataflow.

        The planner's flat schedule can list a consumer region before its
        producer.  The lowering then reaches the consumer's feed before any
        instruction produces it, ``external_value`` mints the feed as a
        FORMAL, and the emitted function silently grows a parameter that is
        also a region output -- a one-parameter source becoming a
        two-parameter program with an unnamed formal no caller could fill
        (scorecard levels: nested calls, division-and-power).

        The signatures needed to order correctly are already here, so order
        by them: within each contiguous run of pure region statements, a
        stable topological sort placing producers before the regions that
        feed on them.  Stability preserves the plan's order wherever dataflow
        does not force a change, and anything effectful or unrecognised is a
        barrier that no region crosses.
        """

        ordered: list[ControlBlock] = []
        run: list[tuple[int, ControlBlock]] = []

        def flush() -> None:
            if len(run) < 2:
                ordered.extend(child for _index, child in run)
                run.clear()
                return
            produced_by = {
                int(output): position
                for position, (region_index, _child) in enumerate(run)
                for output in self.region_signatures[region_index][1]
            }
            remaining = list(range(len(run)))
            placed: set[int] = set()
            emitted_outputs: set[int] = set()
            while remaining:
                progressed = False
                for position in tuple(remaining):
                    region_index, _child = run[position]
                    feeds = self.region_signatures[region_index][0]
                    if all(
                        int(feed) not in produced_by
                        or produced_by[int(feed)] == position
                        or produced_by[int(feed)] in placed
                        for feed in feeds
                    ):
                        ordered.append(run[position][1])
                        placed.add(position)
                        remaining.remove(position)
                        progressed = True
                if not progressed:
                    # A dependency cycle among regions is not resolvable by
                    # ordering; emit the plan's own order for the remainder
                    # rather than looping forever or guessing.
                    ordered.extend(run[position][1] for position in remaining)
                    remaining.clear()
            run.clear()

        for child in children:
            region_index = self._pure_region_index(child)
            if region_index is None:
                flush()
                ordered.append(child)
            else:
                run.append((region_index, child))
        flush()
        return ordered

    def _lower(self, block: ControlBlock, *, path: str = "root") -> None:
        if isinstance(block, SequenceBlock):
            # Reordering is confined to straight-line context. Inside a loop
            # body the carried-value machinery is itself an ordering
            # constraint -- the LAST publish of a carried id becomes the
            # phi's latch operand via ``external_values`` rebinding -- and
            # that dependency is invisible to feed/output signatures, so the
            # sort must not run there.
            children = (
                tuple(block.blocks)
                if self.loop_targets
                else tuple(self._dependency_ordered(tuple(block.blocks)))
            )
            for index, child in enumerate(children):
                self.lower(child, path=f"{path}.sequence[{index}]")
            return
        if isinstance(block, StatementBlock):
            for index, line in enumerate(block.lines):
                match = _REGION_MARKER.fullmatch(str(line))
                location = f"{path}.statement[{index}]"
                callsite = _CALLSITE_MARKER.fullmatch(str(line))
                if callsite is not None:
                    self.emit_plan_callsite(
                        int(callsite.group(1)), location=location
                    )
                    continue
                if match is not None:
                    region_index = int(match.group(1))
                    memberships = self.declared_region_memberships.get(
                        region_index, ()
                    )
                    self.active_deployments.extend(memberships)
                    try:
                        self.emit_region_call(
                            region_index,
                            location=location,
                        )
                    finally:
                        if memberships:
                            del self.active_deployments[-len(memberships):]
                else:
                    self.emit(
                        Handler.Call,
                        [],
                        attributes={
                            "callee": "unlowered_control_statement",
                            "source": str(line),
                        },
                    )
                    self.shortfalls.append(
                        SSALoweringShortfall(
                            "control",
                            "statement",
                            location,
                            f"statement remains untranslated: {line!r}",
                        )
                    )
            return
        if isinstance(block, LoopBlock):
            self.lower_loop(block, path=path)
            return
        if isinstance(block, ConditionalBlock):
            self.lower_conditional(block, path=path)
            return
        if isinstance(block, WhileBlock):
            self.lower_while(block, path=path)
            return
        if isinstance(block, ResourceScopeBlock):
            self.resource_scopes.append((block, len(self.loop_targets)))
            try:
                self.lower(block.body, path=f"{path}.resource_body")
            finally:
                self.resource_scopes.pop()
            for index, operation in enumerate(block.cleanup):
                self.lower(operation, path=f"{path}.resource_cleanup[{index}]")
            return
        if isinstance(block, LoopControlBlock) and block.action == "return":
            # A source ``return`` below the function's top level: capture
            # this return's own slot values on the edge and branch to the
            # function exit, where every return edge is merged per slot
            # (`finish`). Loop-carried Phis at any enclosing loop exit do
            # not receive this edge -- the post-loop code does not run on
            # a return path -- which is exactly the semantics of ``return``.
            if os.environ.get("TURING_DEBUG_CONTROL_OVERLAY"):
                for slot in block.return_value_ids:
                    if slot is None:
                        continue
                    chain = []
                    current = int(slot)
                    while current in self.value_aliases and len(chain) < 8:
                        current = int(self.value_aliases[current])
                        chain.append(current)
                    resident = self.external_values.get(int(slot))
                    print(
                        f"DEBUG-RETURN-SLOT fn={self.function_name} slot={slot} "
                        f"alias_chain={chain!r} "
                        f"external_values[slot]={None if resident is None else int(resident.id)} "
                        f"external_values[chain_end]={None if self.external_values.get(current) is None else int(self.external_values[current].id)}",
                        file=sys.stderr,
                    )
            # Fixed tuples are already authored as ordered scalar identities
            # by SOURCE_AGGREGATE_LAYOUT.  Carry those identities across the
            # return edge instead of collapsing them back into the tuple's
            # conceptual handle.  This is especially important for an
            # optional tuple: the existing return merge can then pair each
            # authored member with its presence bit, rather than publishing
            # ``(aggregate_handle, presence)`` as though the handle were a
            # physical scalar result.
            edge_values_list: list[SSAValue | None] = []
            edge_source_value_ids: list[int | None] = []
            for slot in block.return_value_ids:
                members = None if slot is None else self._structural_return_members(int(slot))
                if members is not None:
                    edge_values_list.extend(
                        self.external_value(member) for member in members
                    )
                    edge_source_value_ids.extend(members)
                else:
                    edge_values_list.append(
                        None if slot is None
                        else self.external_value(int(slot))
                    )
                    edge_source_value_ids.append(
                        None if slot is None else int(slot)
                    )
            edge_values = tuple(edge_values_list)
            exit_block = self.function_exit_block()
            if block.predicate_value_id is None and (
                block.predicate_expression is None
            ):
                self._emit_resource_cleanup("return", path)
                self.function_return_edges.append((self.current, edge_values))
                self.branch(exit_block)
                self.current.instrs[-1].attributes["source_control"] = "return"
                self.current.instrs[-1].attributes["return_source_value_ids"] = tuple(edge_source_value_ids)
                if block.return_site_cell is not None:
                    # The edge names its own return SITE (the construct's
                    # cell), not only the values it carries.
                    self.current.instrs[-1].attributes["return_site_cell"] = block.return_site_cell
                self.current = self.new_block("unreachable_return_control")
            else:
                fallthrough = self.new_block("return_control_next")
                predicate = (
                    self.lower_control_expression(block.predicate_expression)
                    if block.predicate_expression is not None
                    else self.external_value(
                        block.predicate_value_id, dtype="bool"
                    )
                )
                # The predicated edge leaves from a block of its own so the
                # exit Phi's incoming block names exactly one return site.
                returning = self.new_block("return_edge")
                self.conditional_branch(
                    predicate,
                    returning if block.expect_true else fallthrough,
                    fallthrough if block.expect_true else returning,
                )
                self.current.instrs[-1].attributes["source_control"] = "return"
                self.current = returning
                self._emit_resource_cleanup("return", path)
                self.function_return_edges.append((self.current, edge_values))
                self.branch(exit_block)
                self.current.instrs[-1].attributes["return_source_value_ids"] = tuple(edge_source_value_ids)
                if block.return_site_cell is not None:
                    self.current.instrs[-1].attributes["return_site_cell"] = block.return_site_cell
                self.current = fallthrough
            return
        if isinstance(block, LoopControlBlock):
            if self.resource_scopes and (
                block.predicate_value_id is not None or block.predicate_expression is not None
            ):
                predicate = (
                    self.lower_control_expression(block.predicate_expression)
                    if block.predicate_expression is not None else
                    self.external_value(block.predicate_value_id, dtype="bool")
                )
                leaving = self.new_block("resource_exit")
                fallthrough = self.new_block("resource_exit_next")
                self.conditional_branch(predicate,
                                        leaving if block.expect_true else fallthrough,
                                        fallthrough if block.expect_true else leaving)
                self.current = leaving
                self.lower(replace(block, predicate_value_id=None, predicate_expression=None), path=path)
                self.current = fallthrough
                return
            if not self.loop_targets:
                raise ValueError(
                    f"{block.action} appears outside a loop "
                    f"(site {block.site_node_id}, {self.function_name}, {path})"
                )
            latch, exit_block = self.loop_targets[-1]
            target = exit_block if block.action == "break" else latch
            self._emit_resource_cleanup(block.action, path)
            if self.loop_exit_contexts and block.site_node_id is not None:
                self.loop_exit_contexts[-1]["sites_seen"].add(
                    int(block.site_node_id)
                )
            if block.action in {"break", "continue"} and self.loop_exit_contexts:
                context = self.loop_exit_contexts[-1]
                # The reducer recorded, per site, the value every rebound
                # name holds THERE (keyed by its pre-loop identity).  That is
                # the value the exit edge carries; the older
                # "updated-if-it-dominates-else-current" rule remains only
                # for names the site table does not mention.
                site_values = {
                    (int(initial_id), int(updated_id)): int(value_id)
                    for (initial_id, updated_id), value_id in block.site_values
                }

                def site_value(
                    initial_id: int,
                    updated_id: int,
                    incumbent: SSAValue,
                    initial_value: SSAValue,
                ) -> SSAValue | None:
                    value_id = site_values.get((int(initial_id), int(updated_id)))
                    if value_id is None:
                        return None
                    if int(value_id) == int(initial_id):
                        # The reducer's explicit unchanged-site receipt is
                        # this binding's header generation, not the live
                        # value-id view another binding may have rebound.
                        return incumbent
                    value = self.external_values.get(int(value_id))
                    if value is None and int(value_id) in self.constant_value_ids:
                        # A folded literal (``flag = True; break``): the
                        # control function materializes it in its entry.
                        value = self.external_value(int(value_id))
                    if value is not None and self._value_dominates_current_edge(value):
                        return value
                    if value is not None and block.action == "continue":
                        return self._complete_current_join_value(
                            value,
                            incumbent,
                            initial_value_id=int(initial_id),
                            initial_value=initial_value,
                            updated_value_id=int(updated_id),
                            site_node_id=block.site_node_id,
                        )
                    if value is None or block.action == "break":
                        if os.environ.get("TURING_DEBUG_BREAK_EDGE"):
                            print(
                                f"DEBUG-BREAK-EDGE {self.function_name} site="
                                f"{block.site_node_id} initial={initial_id} "
                                f"value_id={value_id} object={value!r} "
                                f"current={self.current.name}",
                                file=sys.stderr, flush=True,
                            )
                            for name, emitted in self.blocks.items():
                                for instruction in emitted.instrs:
                                    print(
                                        f"    {name}: {instruction.op} "
                                        f"{[int(a.id) for a in instruction.args]} -> "
                                        f"{None if instruction.res is None else int(instruction.res.id)}"
                                        f"{' <== SITE VALUE OBJECT' if value is not None and instruction.res is value else ''}",
                                        file=sys.stderr, flush=True,
                                    )
                        self.shortfalls.append(SSALoweringShortfall(
                            "control", "break-edge-value", path,
                            f"break site {block.site_node_id} carries value "
                            f"{value_id} for pre-loop identity {initial_id} "
                            "but that value does not dominate the exit edge",
                        ))
                        return None
                    return value

                carried_values = []
                for updated_id, initial_id, current, initial_value in (
                    context["carried"]
                ):
                    at_site = site_value(
                        int(initial_id), int(updated_id), current,
                        initial_value,
                    )
                    if at_site is not None:
                        carried_values.append(at_site)
                        continue
                    candidate = self.external_values.get(
                        int(updated_id),
                        self.external_values.get(int(initial_id), current),
                    )
                    if self._value_dominates_current_edge(candidate):
                        carried_values.append(candidate)
                    elif block.action == "continue":
                        carried_values.append(self._complete_current_join_value(
                            candidate,
                            current,
                            initial_value_id=int(initial_id),
                            initial_value=initial_value,
                            updated_value_id=int(updated_id),
                            site_node_id=block.site_node_id,
                        ))
                    else:
                        carried_values.append(current)
                if block.action == "break":
                    bound_values = []
                    for _port_id, initial_id in context["break_bound"]:
                        incumbent = self.external_value(int(initial_id))
                        at_site = site_value(
                            int(initial_id), int(initial_id), incumbent,
                            incumbent,
                        )
                        bound_values.append(
                            at_site if at_site is not None else incumbent
                        )
                    context["break_edges"].append((
                        self.current, tuple(carried_values), tuple(bound_values)
                    ))
                else:
                    context["continue_edges"].append((
                        self.current, tuple(carried_values)
                    ))
            if block.predicate_value_id is None:
                self.branch(target)
                self.current.instrs[-1].attributes["source_control"] = (
                    block.source_action or block.action
                )
                self.current = self.new_block("unreachable_loop_control")
            else:
                fallthrough = self.new_block("loop_control_next")
                predicate = (
                    self.lower_control_expression(block.predicate_expression)
                    if block.predicate_expression is not None
                    else self.external_value(
                        block.predicate_value_id, dtype="bool"
                    )
                )
                self.conditional_branch(
                    predicate,
                    target if block.expect_true else fallthrough,
                    fallthrough if block.expect_true else target,
                )
                self.current.instrs[-1].attributes["source_control"] = (
                    block.source_action or block.action
                )
                self.current = fallthrough
            return
        if isinstance(block, CallBlock):
            # Hierarchy planning has already unified the bound value IDs.
            # CallBlock is lexical organization around the nested compiled
            # control, not an additional runtime invocation.
            self.lower(block.callee, path=f"{path}.callee")
            return
        if isinstance(block, DispatchBlock):
            arguments = [self.external_value(value_id)
                         for value_id in block.argument_value_ids]
            arguments.extend(self.external_value(value_id)
                             for _name, value_id in block.keyword_argument_value_ids)
            result = None if block.result_value_id is None else SSAValue(
                int(block.result_value_id), dtype=str(block.result_dtype)
            )
            self.emit(Handler.Dispatch, arguments, result, attributes={
                "dispatch_operation": str(block.operation),
                "source_callsite_id": int(block.callsite_id),
                "keyword_names": tuple(name for name, _ in block.keyword_argument_value_ids),
                "deployment_owner": "dispatcher",
                "required_capability": "communicating_tasks",
                "effectful": True,
                "ordered_effect": True,
                "extraction_identity": "turing.dispatch." + str(block.operation),
            })
            if result is not None:
                # CALL_RESULT: the dispatch's argument cells are the cause.
                self._bind(
                    int(result.id), result, BindingKind.CALL_RESULT, *arguments,
                )
            return
        if isinstance(block, ExternalReferenceCallBlock):
            arguments = [
                self.external_value(value_id)
                for value_id in block.argument_value_ids
            ]
            arguments.extend(
                self.external_value(value_id)
                for _name, value_id in block.keyword_argument_value_ids
            )
            result = SSAValue(
                int(block.result_value_id), dtype=str(block.result_dtype)
            )
            self.emit(
                Handler.Call,
                arguments,
                result,
                attributes={
                    "callee": "turing_external_reference_call",
                    "external_reference": True,
                    "external_identity": str(block.identity),
                    "external_callsite_id": int(block.callsite_id),
                    "external_domain": str(block.external_domain),
                    "shell_abi": str(block.shell_abi),
                    "native_abi": str(block.native_abi),
                    "runtime_owner": str(block.runtime_owner),
                    "shell_profiles": tuple(block.shell_profiles),
                    "keyword_names": tuple(
                        name for name, _value_id
                        in block.keyword_argument_value_ids
                    ),
                    "external_argument_sequences": tuple(
                        {
                            "position": int(position),
                            "sequence_id": int(sequence_id),
                            "encoding": str(encoding),
                        }
                        for position, sequence_id, encoding
                        in block.argument_sequence_ids
                    ),
                    "argument_frame": "turing.external-reference-arguments.v1",
                    "result_frame": "turing.external-reference-value.v1",
                    "object_policy": "shell-owned-opaque-handles",
                    "extraction_identity": str(block.identity),
                    **({
                        "external_result_sequence": "utf8",
                    } if str(block.result_dtype) == "utf8_sequence" else {}),
                },
            )
            # CALL_RESULT: the external call's argument cells are the cause.
            self._bind(
                int(block.result_value_id), result, BindingKind.CALL_RESULT,
                *arguments,
            )
            if str(block.result_dtype) == "utf8_sequence":
                status = self.sequence_status_values.get(
                    int(block.result_value_id)
                )
                if status is None:
                    raise ValueError(
                        "UTF-8 external result has no exact resident sequence "
                        f"status cell: value={block.result_value_id}"
                    )
                succeeded = self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE,
                    operands=(status,),
                )
                self.emit(
                    Handler.Eq,
                    [status, self.constant_value(1, status)],
                    succeeded,
                    attributes={
                        "external_result_status": "utf8_sequence",
                        "source_callsite_id": int(block.callsite_id),
                    },
                )
                passed = self.new_block("validation_pass")
                failed = self.new_block("validation_fail")
                self.conditional_branch(succeeded, passed, failed)
                self.current = failed
                self.emit(
                    Handler.Call,
                    [],
                    attributes={
                        "callee": "turing_validation_error",
                        "error_code": 73,
                        "extraction_identity": str(block.identity),
                        "external_result_status": "utf8_sequence",
                    },
                )
                self.branch(passed)
                self.current = passed
            return
        if isinstance(block, ValidationBlock):
            self.validation_contracts.append({
                "predicate_value_id": int(block.predicate_value_id),
                "error_code": int(block.error_code),
                "expect_true": bool(block.expect_true),
                "predicate_expression": _control_expression_mapping(
                    block.predicate_expression
                ),
                "extraction_identity": block.extraction_identity,
            })
            predicate = (
                self.lower_control_expression(block.predicate_expression)
                if block.predicate_expression is not None
                else self.external_value(
                    block.predicate_value_id,
                    dtype="bool",
                )
            )
            passed = self.new_block("validation_pass")
            failed = self.new_block("validation_fail")
            if block.expect_true:
                self.conditional_branch(predicate, passed, failed)
            else:
                self.conditional_branch(predicate, failed, passed)
            self.current = failed
            self.emit(
                Handler.Call,
                [],
                attributes={
                    "callee": "turing_validation_error",
                    "error_code": int(block.error_code),
                    "extraction_identity": block.extraction_identity,
                },
            )
            self.branch(passed)
            self.current = passed
            return
        if isinstance(block, SequenceMutationBlock):
            self.lower_sequence_mutation(block.mutation, path=path)
            return
        if isinstance(block, ScalarFieldWriteBlock):
            value = self.lower_control_expression(block.value_expression)
            if block.field_value_id is not None:
                destination = self.external_value(
                    block.field_value_id, dtype=block.dtype,
                )
                self.emit(Handler.Store, [value, destination], attributes={
                    "source_effect_node_id": block.effect_node_id,
                    # The write's own field-state cell: the version published
                    # below begins at THIS effect (record-return selection
                    # starts its intervening-write scan after it).
                    "field_state_cell": block.field_state_cell,
                    "binding": "scalar_record_field_assignment",
                })
            # The write IS one ``reducer_field_state`` cell (its WRITTEN
            # revision).  The emitted value is that cell's SSA version: post
            # it on ``ssa_field_version`` at (function scope, cell) so the
            # conditional merge and the record-return selection read the
            # version at the cell the reducer's merge named, not under a
            # graph id.  Local returned records have no destination cell
            # here; their record-return materialization consumes this same
            # version.
            version_cell = None
            if block.field_state_cell is not None:
                version_cell = self._publish_field_version(
                    block.field_state_cell, value, (block.field_state_cell,),
                )
            # FIELD_WRITE: the SetAttr id resolves to the written value; the
            # version cell lane C posts is its cause.
            self._bind(
                int(block.effect_node_id), value, BindingKind.FIELD_WRITE,
                version_cell, block.field_state_cell,
            )
            return
        if isinstance(block, SequenceQueryBlock):
            self.lower_sequence_query(block, path=path)
            return
        if isinstance(block, StreamPublishBlock):
            payload_ids = (
                tuple(map(int, block.payload_value_ids))
                if block.payload_value_ids
                else (int(block.value_id),)
            )
            args = [self.external_value(value_id) for value_id in payload_ids]
            if block.count_value_id is not None:
                args.append(self.external_value(block.count_value_id))
            if block.predicate_value_id is not None:
                args.append(
                    self.external_value(
                        block.predicate_value_id,
                        dtype="bool",
                    )
                )
            self.emit(
                Handler.Call,
                args,
                attributes={
                    "callee": "turing_stream_publish",
                    "stream_id": int(block.stream_id),
                    "final": bool(block.final),
                    "source_payload_value_id": int(block.value_id),
                    "aggregate_payload_value_ids": tuple(payload_ids),
                },
            )
            return
        if isinstance(block, StateMachineTick):
            self.lower_state_machine(block, path=path)
            return
        if isinstance(block, ParallelDeployment):
            deployment_id = self.next_deployment_id
            self.next_deployment_id += 1
            record = {
                "region_id": deployment_id,
                "kind": "parallel_candidate",
                "schedule": "independent_lanes",
                "schedule_preference": block.schedule_preference,
                "lane_count": len(block.lanes),
                "iteration_space": None,
                "carried_aliases": (),
                "recursion_region_id": None,
                "origin": "parallel_block",
                "source_loop_node_id": None,
                "scale": 1,
                "join": DeploymentJoin(),
                "declared_lanes": (),
            }
            self.deployment_records.append(record)
            self.emit_deployment_boundary(Handler.Deploy, record)
            for index, lane in enumerate(block.lanes):
                self.active_deployments.append((deployment_id, index))
                try:
                    self.lower(lane, path=f"{path}.lane[{index}]")
                finally:
                    self.active_deployments.pop()
            self.emit_deployment_boundary(Handler.Join, record)
            return
        raise TypeError(f"unknown control block {type(block).__name__}")

    def _mint_arena_column(
        self, dtype: str | None, operands: tuple,
    ) -> SSAValue:
        """A descriptor column beyond column 0: an arena whose element dtype
        the descriptor declares at the mint."""

        return self.fresh_value(
            dtype=dtype, transform=DESCRIPTOR_CELL, operands=operands,
            physical={"arena": True, **_declared_physical_dtype(dtype)},
        )

    def _sequence_descriptor(
        self,
        value_id: int,
        *,
        policy: str,
        writable: bool,
        location: str,
        column_count: int | None = None,
        retains_deleted_rows: bool = False,
        nested_table: bool = False,
        nested_tensor: bool = False,
        nested_value_dtype: str | None = None,
        element_dtype: str | None = None,
        column_dtypes: tuple[str | None, ...] | None = (),
        column_shapes: tuple[tuple[int, ...], ...] | None = (),
        dtype_sources: tuple = (),
    ) -> SSASequenceDescriptor | None:
        """``dtype_sources``: the values whose dtypes ``column_dtypes``
        proposes (a row a writer stores); their cells derive the row
        dtype the proposal refines."""
        value_id = int(value_id)
        selected = self.child_table_selections.get(value_id)
        if selected is not None and value_id in self.empty_default_child_ids:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-table", "optional-child-view", location,
                "an empty-default child lookup is not an unconditional mutable row view",
            ))
            return None
        if selected is not None and value_id in self.child_selection_validity:
            if value_id not in self.active_child_selections:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-table", "unguarded-child-view", location,
                    "a bounded child selection requires its exact control-owned validity guard",
                ))
                return None
            existing_view = self.sequence_descriptors.get(value_id)
            if existing_view is not None and any(
                not self._value_dominates_current_edge(self.ssa_value_objects[column])
                for column in existing_view.column_value_ids
                if column in self.ssa_value_objects
            ):
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-table", "conditional-child-view-reuse", location,
                    "a selected row view from another conditional needs an explicit merged physical view",
                ))
                return None
        if selected is not None and selected[0].shape_value_id is None and value_id not in self.sequence_descriptors:
            # ``d.setdefault(k, []).append(v)``: the returned collection is
            # exactly the selected pool row. Allocating an arena for this
            # source identity detached the append from the dictionary.
            pool, handle = selected
            stride = self.external_value(pool.row_stride_value_id)
            offset = self.fresh_value(dtype="int64", transform=CONTROL_EXPRESSION, operands=(handle, stride))
            self.emit(Handler.Mul, [handle, stride], offset,
                      attributes={"binding": "selected_child_row_offset"})
            columns = []
            for column_id, dtype in zip(pool.column_value_ids, pool.column_dtypes):
                base = self.external_value(column_id)
                address = self.fresh_value(dtype=str(dtype), transform=ADDRESS, operands=(base, offset),
                                           physical={"arena": True, "storage": "span", "rank": 1})
                self.emit(Handler.GetElementPtr, [base, offset], address,
                          attributes={"binding": "selected_child_row_view", "source_value_id": value_id,
                                      **({"child_selection_guard_value_id": int(self.child_selection_validity[value_id].id)} if value_id in self.child_selection_validity else {})})
                columns.append(address)
            lengths = self.external_value(pool.length_value_id)
            length = self.fresh_value(dtype="ptr", transform=ADDRESS, operands=(lengths, handle), physical={"physical_dtype": "int64"})
            self.emit(Handler.GetElementPtr, [lengths, handle], length,
                      attributes={"binding": "selected_child_length_view"})
            status = None
            if pool.status_value_id is not None:
                statuses = self.external_value(pool.status_value_id)
                status = self.fresh_value(dtype="ptr", transform=ADDRESS, operands=(statuses, handle), physical={"physical_dtype": "int"})
                self.emit(Handler.GetElementPtr, [statuses, handle], status,
                          attributes={"binding": "selected_child_status_view"})
            live = None
            if pool.live_flags_value_id is not None:
                flags = self.external_value(pool.live_flags_value_id)
                live = self.fresh_value(dtype="bool", transform=ADDRESS, operands=(flags, offset),
                                        physical={"arena": True, "storage": "span", "rank": 1})
                self.emit(Handler.GetElementPtr, [flags, offset], live,
                          attributes={"binding": "selected_child_live_view"})
            # Program: ``g = [[1, 2], [3, n]]; g[i][1] + g[1][i]`` (corpus
            # c732).  Wrong record: every selected row of one pool named the
            # pool's one stride cell as its capacity, so the descriptor audit
            # saw one cell filling the capacity role of four sequences.  Rule:
            # a selected row owns its capacity, which is the stride.
            capacity = self.fresh_value(dtype="int64", transform=CONTROL_CAST, operands=(stride,))
            self.emit(Handler.Cast, [stride], capacity,
                      attributes={"target_dtype": "int64", "binding": "selected_child_capacity"})
            descriptor = SSASequenceDescriptor(
                sequence_id=value_id, column_value_ids=tuple(int(v.id) for v in columns),
                length_address_id=int(length.id), capacity_value_id=int(capacity.id),
                status_address_id=None if status is None else int(status.id),
                column_dtypes=tuple(pool.column_dtypes), column_shapes=((),) * len(columns),
                key_columns=tuple(pool.key_columns), writable=bool(pool.writable),
                live_flags_value_id=None if live is None else int(live.id),
                capacity_policy=SSASequenceCapacityPolicy.FIXED,
            )
            self.sequence_descriptors[value_id] = descriptor
            self.sequence_storage_values[value_id] = (*columns, length, capacity, *((live,) if live is not None else ()))
            if status is not None:
                self.sequence_status_values[value_id] = status
            return descriptor
        # Literal-table survey uses ``None`` to mean that an empty table has
        # no authored rows from which a column dtype/shape can be inferred.
        # Normalize that absence before the column loop; it is not itself a
        # different sequence representation.
        column_dtypes = tuple(column_dtypes or ())
        column_shapes = tuple(column_shapes or ())
        if not column_dtypes and value_id not in self.sequence_descriptors:
            # c626: an array("I") receiver is first materialized by append,
            # after the local declaration walk.  Use the source field's
            # uint32 row contract before minting its physical SSA column.
            column_dtypes = self.source_sequence_column_dtypes.get(value_id, ())
        resolved = self.resolved_sequence_schemas.get(value_id)
        declared_child_layout = self.sequence_child_table_layouts.get(value_id)
        if declared_child_layout is not None:
            nested_table = True
        existing = self.sequence_descriptors.get(value_id)
        if column_count is None:
            column_count = (
                int(resolved.column_count) if resolved is not None
                else len(existing.column_value_ids) if existing is not None
                else 1
            )
        if resolved is not None:
            if (
                int(resolved.column_count) != int(column_count)
                or str(resolved.policy) != str(policy)
            ):
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", "resolved-schema-mismatch", location,
                    f"sequence value {value_id} disagrees with its "
                    "whole-program resolved schema: this function sees "
                    f"{int(column_count)} column(s)/policy {policy!r}, "
                    f"but the survey resolved {int(resolved.column_count)} "
                    f"column(s)/policy {resolved.policy!r} from every "
                    "function that touches this sequence",
                ))
                return None
            # writable/retains_deleted_rows/nested_table are resolved as an
            # OR across every function during the survey -- this function's
            # own local view is always a subset of that, never a conflict,
            # so the resolved value simply wins rather than being checked.
            writable = bool(writable or resolved.writable)
            retains_deleted_rows = bool(
                retains_deleted_rows or resolved.retains_deleted_rows
            )
            nested_table = bool(nested_table or resolved.nested_table)
            nested_tensor = bool(nested_tensor or resolved.nested_tensor)
            nested_value_dtype = nested_value_dtype or resolved.nested_value_dtype
        value_column_count = (
            int(resolved.value_column_count) if resolved is not None else 1
        )
        key_columns = (
            tuple(range(max(1, int(column_count) - value_column_count)))
            if policy == "unique" else ()
        )
        def _canonicalize_column(raw_dtype: str | None, column: int) -> str | None:
            # c633: the constructor and every record read already agree on
            # array("b")'s int8 row. Generic Python-integer inference must
            # not widen that authored physical row to int64 in this callee.
            # Only an inferred column without a source contract is widened.
            declared_columns = self.source_sequence_column_dtypes.get(value_id, ())
            declared_dtype = (declared_columns[column]
                              if column < len(declared_columns) else None)
            if declared_dtype not in {None, "", "unknown", "None"}:
                return str(declared_dtype)
            canonical = _canonical_sequence_dtype(raw_dtype)
            if canonical != raw_dtype and _LOG.isEnabledFor(logging.DEBUG):
                _LOG.debug(
                    "sequence %d column %d at %s: widened dtype %r -> %r "
                    "(this array is shared across every function that "
                    "touches the sequence, so its element width must be "
                    "one fact, not whatever the first function to see it "
                    "happened to infer)",
                    value_id, column, location, raw_dtype, canonical,
                )
            return canonical

        first_dtype = _canonicalize_column(element_dtype or (
            column_dtypes[0] if column_dtypes else None
        ), 0)
        proposed_column_dtypes = tuple(
            _canonicalize_column(
                first_dtype if column == 0 else (
                    column_dtypes[column]
                    if column < len(column_dtypes) else None
                ),
                column,
            ) or "unknown"
            for column in range(int(column_count))
        )
        proposed_column_shapes = tuple(
            tuple(map(int, column_shapes[column]))
            if column < len(column_shapes) else ()
            for column in range(int(column_count))
        )
        if existing is not None:
            if existing.key_columns != key_columns:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence",
                    "conflicting-policy",
                    location,
                    f"sequence value {value_id} is used with both unique and duplicate policies",
                ))
                return None
            if len(existing.column_value_ids) != int(column_count):
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence",
                    "conflicting-width",
                    location,
                    f"sequence value {value_id} is used with both "
                    f"{len(existing.column_value_ids)} and {int(column_count)} columns",
                ))
                return None
            if retains_deleted_rows and existing.live_flags_value_id is None:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", "conflicting-retention", location,
                    f"sequence value {value_id} requires deletion retention "
                    "after storage was declared without live flags",
                ))
                return None
            concorded_column_dtypes = concord_sequence_row_dtypes(
                self.function_name,
                {value_id: proposed_column_dtypes},
                source=f"{location}: descriptor reuse",
                sources=self._cells(
                    self._sequence_contract_cell(value_id),
                    *self.sequence_storage_values.get(value_id, ()),
                    *dtype_sources,
                ) or (self._function_root(),),
                stage=self._stage(),
            )
            if tuple(existing.column_dtypes) != concorded_column_dtypes:
                existing = self._heap_sequence_contract(replace(
                    existing, column_dtypes=concorded_column_dtypes,
                ))
                self.sequence_descriptors[value_id] = existing
                for value, dtype in zip(
                    self.sequence_storage_values[value_id],
                    concorded_column_dtypes,
                ):
                    if str(value.dtype or "unknown") in {
                        "", "None", "unknown",
                    }:
                        # Program: a mapping whose string keys are Constants
                        # (test_mapping_value_column_uses_writer_union_abi).
                        # Wrong record: resident dtype from the concorded
                        # column vs the ssa_value row ('unknown'). Rule: the
                        # pass that retypes a resident value REVISEs its row,
                        # derived from the sequence contract it read.
                        value.dtype = str(dtype)
                        self._revise_value(
                            value, self._sequence_contract_cell(value_id),
                            stage=self._stage(),
                        )
            incumbent_shapes = tuple(existing.column_shapes) or tuple(
                () for _column in existing.column_value_ids
            )
            merged_shapes = []
            for column, (incumbent, proposed) in enumerate(zip(
                incumbent_shapes, proposed_column_shapes, strict=True,
            )):
                if incumbent and proposed and incumbent != proposed:
                    self.shortfalls.append(SSALoweringShortfall(
                        "ssa-sequence", "conflicting-row-shape", location,
                        f"sequence value {value_id} column {column} receives "
                        f"both {incumbent!r} and {proposed!r}",
                    ))
                    return None
                merged_shapes.append(incumbent or proposed)
            if tuple(merged_shapes) != incumbent_shapes:
                existing = replace(
                    existing, column_shapes=tuple(merged_shapes),
                )
                self.sequence_descriptors[value_id] = existing
            return existing
        concorded_column_dtypes = concord_sequence_row_dtypes(
            self.function_name,
            {value_id: proposed_column_dtypes},
            source=f"{location}: descriptor construction",
            sources=self._cells(
                self._sequence_contract_cell(value_id),
                self.ssa_value_objects.get(value_id),
                self._canonical_cell(value_id),
            ) or (self._function_root(),),
            stage=self._stage(),
        )
        if concorded_column_dtypes:
            first_dtype = concorded_column_dtypes[0]
        # Program: ``xs = [5, n, 2]; xs[0] = 7`` (scratch c140).  Wrong
        # record: with no row type concorded yet, the arena was minted from
        # the planner's region meta -- its float64 capture guess -- and that
        # row outlived the int64 the appends concorded ("storage types are
        # immutable").  Rule: an arena's element type is its row contract;
        # before any writer states one it is ``unknown``, never the guess.
        data = self.external_value(
            value_id,
            dtype=(
                first_dtype
                if first_dtype not in {None, "", "None"}
                else "unknown"
            ),
        )
        # Claim the physical arena at its creation boundary.  Waiting for the
        # final storage-declaration sweep is too late: call/result identity
        # reconciliation may otherwise treat this provisional formal as a
        # replaceable source value and substitute a loop-local scalar.  The
        # storage claim is incumbent provenance; later equal-priority source
        # aliases must retain it.
        data.accounting = {
            **dict(data.accounting or {}),
            "compiler_frame_storage": str(self.function_name),
            "compiler_frame_sequence_id": value_id,
            "compiler_frame_member": 0,
            "transformation_priority": "compiler_storage_identity",
            "transformation_tie_policy": "incumbent",
            "sequence_row_shape": proposed_column_shapes[0],
        }
        if (
            first_dtype not in {None, "", "unknown"}
            and str(data.dtype or "unknown") in {
                "", "None", "unknown", "opaque", "opaque_ref",
            }
        ):
            # The concorded sequence-row dtype is the physical arena type.
            # Apply it to a provisional external occurrence regardless of
            # whether this particular consumer repeated ``element_dtype``;
            # optional glyph clear/replace operations arrive through their
            # exact source contract and must not leave the resident payload
            # opaque at the function boundary.
            data.dtype = str(first_dtype)
        # Program: gen_sort.py (sorted-generator result) -- the sort scratch
        # arena, minted 'unknown' by ``fresh_value`` and then taken through
        # ``external_value(dtype=first_dtype)`` (whose ``_value_cell`` keeps
        # the existing row), plus the write just above.  Wrong record: the
        # resident arena carries the concorded dtype while its ``ssa_value``
        # row kept 'unknown'; and ``sequence_arena`` was set above with no
        # ``arena`` posted.  Rule: the producer posts the change at the
        # moment it makes it, derived from the cells the dtype was concorded
        # from (the same cells ``concord_sequence_row_dtypes`` read); the
        # data column is column 0 of the sequence's descriptor, hence an
        # arena; an unchanged fact posts nothing.
        self._revise_value(
            data,
            self._sequence_contract_cell(value_id),
            self.ssa_value_objects.get(value_id),
            self._canonical_cell(value_id),
            stage=self._stage(),
            physical={"arena": True},
        )
        data.accounting = {
            **dict(data.accounting or {}),
            **self._posted_physical_accounting(data, ("sequence_arena",)),
        }
        # Every storage cell of the descriptor descends from the data arena
        # (the authored sequence's value) and its contract cell.
        descriptor_operands = (data, self._sequence_contract_cell(int(value_id)))
        handle_column = (
            int(declared_child_layout[0])
            if declared_child_layout is not None else
            1
        )
        # Program: gen_sort.py -- the sort order/scratch descriptors' extra
        # columns.  Wrong record: each was minted with no ``arena`` while the
        # accounting set below says ``sequence_arena``.  Rule: a column
        # beyond column 0 of the descriptor schema is an arena; the mint
        # declares it (``physical``), derived from the descriptor operands.
        # Program: a keyed Tensor lookup (tests/test_sequence_helper_physical_
        # rows.py).  Wrong record: the descriptor's arenas and typed storage
        # cells were minted with their element dtype only in ``dtype``; the
        # helper formals built from them later carried ``physical_dtype`` in
        # accounting alone (audit ``ssa-physical-unposted``).  Rule: the
        # descriptor is the first producer to know the element type of its
        # arena / typed one-element cell, so the mint declares it
        # (``_declared_physical_dtype``); accounting is set from the fact.
        extra_columns = tuple(
            self._mint_arena_column(
                _canonicalize_column(
                    (
                        "int64"
                        if nested_table and index + 1 == handle_column
                        else concorded_column_dtypes[index + 1]
                    ),
                    index + 1,
                ), descriptor_operands,
            )
            for index in range(max(0, int(column_count) - 1))
        )
        for index, column in enumerate(extra_columns, start=1):
            column.accounting = {
                **dict(column.accounting or {}),
                "compiler_frame_storage": str(self.function_name),
                "compiler_frame_sequence_id": value_id,
                "compiler_frame_member": int(index),
                **self._posted_physical_accounting(column, ("sequence_arena",)),
                "sequence_row_shape": proposed_column_shapes[index],
                "transformation_priority": "compiler_storage_identity",
                "transformation_tie_policy": "incumbent",
            }
        self.arguments.extend(extra_columns)
        # Mutable scalar cells are one-element typed arenas at the C ABI, not
        # opaque pointer-typed scalars (which the Fortran emitter would have
        # no element type for and could accidentally pass by value).
        # int64, not the generic "int" default: these two cells are shared
        # ABI storage a sequence-helper caller may bind to an externally
        # int64-typed value (e.g. a keyed instance field's own length, see
        # _storage_values in ir_sequence_tables.py) -- both sides of that
        # shared value must declare the same width or the Fortran call
        # fails with a real ABI type mismatch, not a cosmetic one.
        def storage_cell(dtype: str, shape: tuple = ()) -> SSAValue:
            return self.fresh_value(
                dtype=dtype, shape=shape, transform=DESCRIPTOR_CELL,
                operands=descriptor_operands,
                physical=_declared_physical_dtype(dtype),
            )

        length_address = storage_cell("int64", (1,))
        capacity = storage_cell("int64")
        requires_status = bool(writable) or policy == "unique"
        status_address = (
            storage_cell("int", (1,))
            if requires_status else None
        )
        self.arguments.extend((length_address, capacity))
        if status_address is not None:
            self.arguments.append(status_address)
        live_flags = (
            storage_cell("bool") if retains_deleted_rows else None
        )
        if live_flags is not None:
            self.arguments.append(live_flags)
        child_table_pool = None
        child_pool_values: tuple[SSAValue, ...] = ()
        if nested_table:
            if declared_child_layout is None:
                child_column_dtypes = (
                    (nested_value_dtype or "unknown",)
                    if nested_tensor else
                    ("unknown", nested_value_dtype or "unknown")
                )
                child_key_columns = (() if nested_tensor else (0,))
                child_writable = bool(writable)
            else:
                (
                    handle_column, child_column_dtypes,
                    child_key_columns, child_writable,
                ) = declared_child_layout
            child_columns = tuple(
                storage_cell(dtype) for dtype in child_column_dtypes
            )
            child_lengths = storage_cell("int64")
            child_capacity = storage_cell("int64")
            child_stride = storage_cell("int64")
            child_shapes = (
                storage_cell("int32") if nested_tensor else None
            )
            child_ranks = (
                storage_cell("int32") if nested_tensor else None
            )
            child_shape_stride = (
                storage_cell("int64") if nested_tensor else None
            )
            child_status = (
                storage_cell("int") if child_writable else None
            )
            child_live = (
                storage_cell("bool") if child_writable and child_key_columns else None
            )
            child_pool_values = (
                *child_columns, child_lengths, child_capacity,
                child_stride,
                *((child_shapes, child_ranks, child_shape_stride)
                  if nested_tensor else ()),
                *((child_status,) if child_status is not None else ()),
                *((child_live,) if child_live is not None else ()),
            )
            for member, pool_value in enumerate(child_pool_values):
                pool_value.accounting = {
                    **dict(pool_value.accounting or {}),
                    "compiler_frame_storage": str(self.function_name),
                    "compiler_frame_sequence_id": value_id,
                    "compiler_frame_child_table_member": int(member),
                    "transformation_priority": "compiler_storage_identity",
                    "transformation_tie_policy": "incumbent",
                }
            self.arguments.extend(child_pool_values)
            # The pool cells are bound under their own (minted) ids: the
            # sequence contract is their cause.
            for pool_value in child_pool_values:
                self._bind(
                    int(pool_value.id), pool_value,
                    BindingKind.SEQUENCE_RESULT, *descriptor_operands,
                )
            child_table_pool = SSAChildTablePoolDescriptor(
                handle_column=int(handle_column),
                column_value_ids=tuple(
                    int(column.id) for column in child_columns
                ),
                length_value_id=int(child_lengths.id),
                capacity_value_id=int(child_capacity.id),
                row_stride_value_id=int(child_stride.id),
                shape_value_id=(
                    None if child_shapes is None else int(child_shapes.id)
                ),
                rank_value_id=(
                    None if child_ranks is None else int(child_ranks.id)
                ),
                shape_stride_value_id=(
                    None
                    if child_shape_stride is None
                    else int(child_shape_stride.id)
                ),
                status_value_id=(
                    None if child_status is None else int(child_status.id)
                ),
                live_flags_value_id=(
                    None if child_live is None else int(child_live.id)
                ),
                column_dtypes=tuple(child_column_dtypes),
                key_columns=tuple(child_key_columns),
                writable=bool(child_writable),
            )
        # Program: ``xs = []; for i in range(n): xs.append(i * i)``.  Wrong
        # record: the descriptor was FIXED while nothing proves its rows, so
        # the frame allocated one element; LLVM's append reported "full" into
        # a status nobody reads (n=5 returned 1, not 35) and C refused the
        # program.  Rule: a private local list the capacity survey leaves
        # unbounded is born DYNAMIC with its own heap owner cell; growth is
        # the existing checked reserve and the owner is released with the
        # frame.  Borrowed (parameter) storage, child pools, live flags and
        # shaped rows keep their fixed contracts.
        # Program: ``xs = []; for i in range(n): xs.append(i * i)``.  Wrong
        # record: the descriptor took column 0 from the data arena's row
        # (int64) while ``sequence_row_dtype`` still said 'unknown', so the
        # next reuse concorded 'unknown' back over the descriptor's int64.
        # Rule: the descriptor's column dtypes are posted to the row
        # concordance at birth, derived from the arena cells they came from;
        # the two records state one row layout.
        born_column_dtypes = tuple(
            _sequence_column_element_dtype(column)
            for column in (data, *extra_columns)
        )
        if born_column_dtypes != tuple(concorded_column_dtypes):
            concord_sequence_row_dtypes(
                self.function_name,
                {value_id: born_column_dtypes},
                source=f"{location}: descriptor arena dtypes",
                sources=self._cells(
                    self._sequence_contract_cell(value_id),
                    data, *extra_columns,
                ) or (self._function_root(),),
                stage=self._stage(),
            )
        # A parameter's view joins its caller's DYNAMIC storage through the
        # settled call bindings (``linked_dynamic_sequence_ids``); its owner
        # cell is then a parameter member like length and capacity, bound
        # to the caller's owner by ``_bind_sequence_storage_members``.
        # Program: ``detail = None; if c: detail = f'scope={t!r}'``.  The
        # optional payload (seq 19) resolves by alias to the f-string's own
        # data cell (seq 11): two descriptors, one arena.  Wrong record: each
        # minted its own owner and the later stamp overwrote the cell's
        # ``heap_owner_value_id``, so seq 11's helpers met a cell naming an
        # owner their call did not bind.  Rule: an arena has one owner; a
        # descriptor born on a cell that is already a heap cell adopts that
        # cell's owner.
        incumbent_owner_id = (data.accounting or {}).get("heap_owner_value_id")
        incumbent_owner = None if incumbent_owner_id is None else next((
            cell for cell in self.sequence_heap_owners.values()
            if int(cell.id) == int(incumbent_owner_id)
        ), None)
        if incumbent_owner_id is not None and incumbent_owner is None:
            raise ValueError(
                f"{location}: sequence {value_id} data cell names heap owner "
                f"{int(incumbent_owner_id)}, which this function never declared"
            )
        if incumbent_owner is not None:
            self.sequence_heap_owners[value_id] = incumbent_owner
        elif (
            value_id in self.dynamic_sequence_ids
            and (child_table_pool is None or (
                not child_table_pool.key_columns
                and child_table_pool.live_flags_value_id is None
                and child_table_pool.shape_value_id is None
            ))
            and live_flags is None
            and not any(proposed_column_shapes)
        ):
            heap_owner = storage_cell("ptr", (1,))
            heap_owner.accounting = {
                **dict(heap_owner.accounting or {}),
                "heap_owner": True,
                "compiler_frame_storage": str(self.function_name),
                "compiler_frame_sequence_id": value_id,
                "transformation_priority": "compiler_storage_identity",
                "transformation_tie_policy": "incumbent",
            }
            self.arguments.append(heap_owner)
            self.sequence_heap_owners[value_id] = heap_owner
        descriptor = SSASequenceDescriptor(
            sequence_id=value_id,
            column_value_ids=(int(data.id), *(
                int(column.id) for column in extra_columns
            )),
            length_address_id=int(length_address.id),
            capacity_value_id=int(capacity.id),
            status_address_id=(
                None if status_address is None else int(status_address.id)
            ),
            column_dtypes=born_column_dtypes,
            column_shapes=proposed_column_shapes,
            key_columns=key_columns,
            live_flags_value_id=(
                None if live_flags is None else int(live_flags.id)
            ),
            capacity_policy=SSASequenceCapacityPolicy.FIXED,
            writable=bool(writable),
            child_table_pool=child_table_pool,
        )
        descriptor = self._heap_sequence_contract(descriptor)
        # NOTE: a key column here is routinely left with the provisional
        # dtype a structural constant carries (float64, or "unknown"), and
        # no column contract reaches this point to correct it -- see
        # ``identity_concordance``'s ``key-column-not-integral`` finding,
        # which reports it for the whole module.  It is NOT raised as an
        # ``SSALoweringShortfall`` here on purpose: a shortfall is fatal at
        # emission, the defect is present for every keyed store in the
        # tree, and making it fatal halts every build before the root cause
        # (the missing contract) can be threaded down to this point.  The
        # audit carries it until then.
        self.sequence_descriptors[value_id] = descriptor
        self.sequence_storage_values[value_id] = (
            data, *extra_columns, length_address, capacity,
            *((live_flags,) if live_flags is not None else ()),
            *(tuple(self.ssa_value_objects[member] for member in (
                *child_table_pool.column_value_ids,
                child_table_pool.length_value_id,
                *(() if child_table_pool.status_value_id is None else (child_table_pool.status_value_id,)),
                child_table_pool.capacity_value_id,
                child_table_pool.row_stride_value_id,
            )) if descriptor.heap_owner_value_id is not None and child_table_pool is not None else ()),
            *(
                (self.sequence_heap_owners[value_id],)
                if descriptor.heap_owner_value_id is not None else ()
            ),
        )
        if status_address is not None:
            self.sequence_status_values[value_id] = status_address
        # A sequence rooted at an authored parameter is BORROWED storage.
        # Its generated columns/counters belong to that same parameter, not
        # the compiler's private frame. Otherwise native_memo(memo,key,value)
        # emitted six uninitialized singleton root.frame slots and ignored
        # the caller's table entirely. Derive ownership at descriptor creation
        # from the exact initial parameter identity, before ABI publication.
        parameter_owner = next((
            name for name in self.parameter_names
            if self.value_name_histories.get(name, ())
            and int(self.value_name_histories[name][0]) == int(value_id)
        ), None)
        # The parameter identity alone is NOT a native arena declaration.
        # A text-key formal also gets a provisional unknown sequence view;
        # promoting that view redirected keyed tensor payloads to its scalar
        # key storage. Require the explicit row-layout contract supplied to
        # this descriptor constructor, not its provisional inferred dtype.
        if parameter_owner is not None and column_dtypes and all(
            dtype not in {None, "", "unknown"} for dtype in column_dtypes
        ):
            members = (
                *self.sequence_storage_values[value_id],
                *((status_address,) if status_address is not None else ()),
                *child_pool_values,
            )
            arena_ids = {*descriptor.column_value_ids,
                         *((descriptor.live_flags_value_id,) if descriptor.live_flags_value_id is not None else ())}
            # A fixed caller-owned mapping's selected child row borrows the
            # same parameter's pool. Omitting these exact descriptor members
            # classified its row arena as private and refused valid capacity.
            if child_table_pool is not None:
                arena_ids.update(child_table_pool.column_value_ids)
                arena_ids.add(child_table_pool.length_value_id)
                if child_table_pool.status_value_id is not None:
                    arena_ids.add(child_table_pool.status_value_id)
            # Program: gen_sort.py (``xs: list[int]`` parameter).  Wrong record:
            # the descriptor members (data arena, length address, capacity,
            # status address, live flags) were given ProgramABI storage/rank
            # in accounting only, their rows carrying none.  Rule: post
            # first, accounting is a view.  A member is a span when the
            # descriptor schema names it a column/live-flag arena or its
            # shape is non-empty, else a scalar; the row is revised DERIVED
            # from the sequence contract cell, the owner's
            # ``parameter_abi_kind`` cell and the member's own row, and the
            # accounting is set FROM the posted fact.
            _owner_kind = (
                None if self.lexical_read_scope is None
                else self._book().latest_ref(
                    PARAMETER_ABI_KIND,
                    (tuple(self.lexical_read_scope), str(parameter_owner)),
                )
            )
            for member in members:
                span = int(member.id) in arena_ids or bool(member.shape)
                _member_cell = self._revise_value(
                    member,
                    self._sequence_contract_cell(value_id), _owner_kind,
                    stage=self._stage(),
                    physical={
                        "storage": "span" if span else "scalar",
                        "rank": 1 if span else 0,
                    },
                )
                _member_fact = self._book().page(SSA_VALUE).cell(
                    _member_cell.row, _member_cell.column,
                )
                member.accounting = {
                    **dict(member.accounting or {}),
                    "program_abi_parameter": str(parameter_owner),
                    "program_abi_storage": _member_fact.storage,
                    "program_abi_rank": _member_fact.rank,
                }
        return descriptor

    def _heap_sequence_contract(
        self, descriptor: SSASequenceDescriptor,
    ) -> SSASequenceDescriptor:
        """State the DYNAMIC contract once every column layout is known.

        An unbounded local list is usually born empty (``xs = []``), so its
        element type arrives with its first writer.  Its heap owner cell is
        claimed at birth; the descriptor becomes DYNAMIC, and its columns
        heap pointer cells, at the first moment the layouts exist -- the
        heap contract never guesses an element layout.
        """

        from ..transmogrifier.dtype_layout import layout_for

        owner = self.sequence_heap_owners.get(int(descriptor.sequence_id))
        if (
            owner is None
            or descriptor.capacity_policy is SSASequenceCapacityPolicy.DYNAMIC
        ):
            return descriptor
        try:
            layouts = tuple(
                layout_for(str(dtype)) for dtype in descriptor.column_dtypes
            )
        except KeyError:
            return descriptor
        if len(layouts) != len(descriptor.column_value_ids):
            return descriptor
        columns = self.sequence_storage_values.get(
            int(descriptor.sequence_id), ()
        )[:len(descriptor.column_value_ids)] or tuple(
            self.ssa_value_objects[int(value_id)]
            for value_id in descriptor.column_value_ids
        )
        if descriptor.child_table_pool is not None:
            pool = descriptor.child_table_pool
            if pool.key_columns or pool.live_flags_value_id is not None or pool.shape_value_id is not None:
                return descriptor
            pool_ids = (*pool.column_value_ids, pool.length_value_id,
                        *(() if pool.status_value_id is None else (pool.status_value_id,)))
            pool_dtypes = (*pool.column_dtypes, "int64",
                          *(() if pool.status_value_id is None else ("int",)))
            try:
                pool_layouts = tuple(layout_for(dtype) for dtype in pool_dtypes)
            except KeyError:
                return descriptor
            columns = (*columns, *(self.ssa_value_objects[value_id] for value_id in pool_ids))
            layouts = (*layouts, *pool_layouts)
        for column, layout in zip(columns, layouts, strict=True):
            # Program: ``xs = []; for i in range(n): xs.append(i * 3)``
            # lowered with the repository SSA reference.  Wrong record: the
            # owner kept the column at its element dtype (int64) while every
            # helper spells the same identity as its pointer CELL (``ptr``,
            # ``_storage_values``); the metadata transport posted int64->ptr
            # and ptr->int64 onto one shape edge until the book refused it.
            # Rule: a heap column is a ``ptr`` cell everywhere -- the element
            # layout lives in ``heap_element_dtype`` (``heap_allocate``) --
            # and a cell is one scalar address: ``[2] * k`` kept the
            # literal's planner extent (1,) and its reserve's heap copy
            # refused the shaped "handle".
            column.dtype = "ptr"
            column.accounting = {
                **dict(column.accounting or {}),
                "heap_element_dtype": layout.name,
                "heap_owner_value_id": int(owner.id),
            }
            self._revise_value(
                column, self._sequence_contract_cell(
                    int(descriptor.sequence_id)
                ),
                stage=self._stage(),
                physical={
                    "physical_dtype": layout.name,
                    "storage": "span",
                    "rank": max(1, len(tuple(column.shape or ()))),
                    "arena": True,
                },
            )
        # The owner is a storage member, last (``_storage_values``): every
        # helper call that passes the sequence's storage passes its owner.
        sequence_id = int(descriptor.sequence_id)
        if sequence_id in self.sequence_storage_values:
            ordinary_count = len(descriptor.column_value_ids) + 2 + (descriptor.live_flags_value_id is not None)
            self.sequence_storage_values[sequence_id] = (
                *self.sequence_storage_values[sequence_id][:ordinary_count],
                *(tuple(self.ssa_value_objects[member] for member in (
                    *descriptor.child_table_pool.column_value_ids,
                    descriptor.child_table_pool.length_value_id,
                    *(() if descriptor.child_table_pool.status_value_id is None else (descriptor.child_table_pool.status_value_id,)),
                    descriptor.child_table_pool.capacity_value_id,
                    descriptor.child_table_pool.row_stride_value_id,
                )) if descriptor.child_table_pool is not None else ()),
                owner,
            )
        return replace(
            descriptor,
            capacity_policy=SSASequenceCapacityPolicy.DYNAMIC,
            heap_owner_value_id=int(owner.id),
        )

    def _lower_positional_sequence_operation(
        self, mutation: ControlSequenceMutation, destination: Any, *,
        location: str,
    ) -> None:
        """``list.pop(i)``, ``list.insert(i, x)`` and ``list.reverse()``.

        Program: ``xs = [5, n, 2]; xs.pop(0)`` / ``xs.insert(0, 8)`` /
        ``xs.reverse()`` (scratch c141-c143).  Wrong record: these methods had
        no lowering and were either dropped (results read the unmutated
        display) or refused.  Rule: each is the repository helper of the same
        name over the sequence's own storage (``ir_sequence_tables``); an
        out-of-range ``pop(i)`` raises through the validation runtime as the
        zero-argument ``pop`` does (Python's IndexError).
        """

        from .ir_sequence_tables import (
            lower_sequence_delete_at, lower_sequence_insert_at,
            lower_sequence_reverse,
        )

        operation = str(mutation.operator)
        attributes = {
            "binding": f"ssa_sequence_{operation}",
            "sequence_id": int(destination.sequence_id),
            "source_effect_node_id": int(mutation.effect_node_id),
        }
        arguments = tuple(
            (
                self.lower_control_expression(expression)
                if expression is not None
                else self.external_value(value_id)
            )
            for value_id, expression in zip(
                mutation.argument_value_ids,
                (
                    *mutation.argument_expressions,
                    *(None for _ in range(
                        len(mutation.argument_value_ids)
                        - len(mutation.argument_expressions)
                    )),
                ),
            )
        )
        columns = len(destination.column_value_ids)
        if operation == "insert" and len(arguments) == 1 + columns:
            # The writer of a row proposes the dtypes it stores (the append
            # rule): ``xs = []`` then ``xs.insert(0, i * 3)`` in a loop
            # (scratch c161) otherwise left the row unknown, so the private
            # list never stated its heap contract.
            stored = tuple(arguments[1:])
            for value, expression in zip(
                stored,
                (*mutation.argument_expressions[1:], *(None,) * columns),
            ):
                if (
                    expression is not None and expression.op == "const"
                    and str(value.dtype or "unknown") in {"", "unknown", "None"}
                ):
                    literal = expression.literal
                    if type(literal) is int:
                        from ..transmogrifier.dtype_layout import (
                            python_int_literal_dtype,
                        )

                        proposed = python_int_literal_dtype(literal)
                    else:
                        proposed = (
                            "bool" if isinstance(literal, bool)
                            else "float64" if isinstance(literal, float)
                            else None
                        )
                    if proposed is not None:
                        value.dtype = proposed
                        self._revise_value(value)
            if any(
                str(column_dtype) in {"", "unknown", "None"}
                and str(value.dtype or "unknown") not in {"", "unknown", "None"}
                for column_dtype, value in zip(destination.column_dtypes, stored)
            ):
                refined = self._sequence_descriptor(
                    mutation.sequence_value_id,
                    policy=mutation.policy,
                    writable=True,
                    location=location,
                    column_count=columns,
                    column_dtypes=tuple(
                        None if str(value.dtype or "unknown")
                        in {"", "unknown", "None"} else str(value.dtype)
                        for value in stored
                    ),
                    dtype_sources=stored,
                )
                if refined is None:
                    return
                destination = refined
        expected = {"reverse": 0, "pop": 1, "insert": 1 + columns}[operation]
        if len(arguments) != expected:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", operation, location,
                f"{operation} expects {expected} argument(s) for a "
                f"{columns}-column row, received {len(arguments)}",
            ))
            return
        storage = self.sequence_storage_values[int(destination.sequence_id)]
        length_address = storage[columns]
        helper_operation = {
            "reverse": "reverse", "pop": "delete_at", "insert": "insert_at",
        }[operation]
        lower = {
            "reverse": lower_sequence_reverse,
            "delete_at": lower_sequence_delete_at,
            "insert_at": lower_sequence_insert_at,
        }[helper_operation]
        lowering = lower(
            destination,
            function_name=self._sequence_helper_name(
                int(destination.sequence_id), helper_operation,
            ),
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        if not lowering.complete:
            self.shortfalls.extend(
                SSALoweringShortfall(
                    "ssa-sequence", item.code.value, location, item.reason,
                )
                for item in lowering.shortfalls
            )
            return
        self._register_sequence_lowering(lowering)
        extra: tuple[SSAValue, ...] = ()
        if operation == "pop":
            # Python's index rule, then the row read, then the removal.
            index = arguments[0]
            length = self.fresh_value(
                dtype="int64", transform=LOAD, operands=(length_address,),
            )
            self.emit(Handler.Load, [length_address], length, attributes=attributes)
            zero = self.constant_value(0, length)
            negative = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE, operands=(index,),
            )
            self.emit(Handler.Lt, [index, zero], negative, attributes=attributes)
            wrapped = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(index, length),
            )
            self.emit(Handler.Add, [index, length], wrapped, attributes=attributes)
            normalized = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(negative, wrapped, index),
            )
            self.emit(
                Handler.Select, [negative, wrapped, index], normalized,
                attributes=attributes,
            )
            at_least_zero = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE, operands=(normalized,),
            )
            self.emit(Handler.Ge, [normalized, zero], at_least_zero, attributes=attributes)
            below_length = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(normalized, length),
            )
            self.emit(Handler.Lt, [normalized, length], below_length, attributes=attributes)
            inside = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(at_least_zero, below_length),
            )
            self.emit(Handler.LAnd, [at_least_zero, below_length], inside, attributes=attributes)
            selected = self.new_block("sequence_pop_selected")
            outside = self.new_block("sequence_pop_empty")
            self.conditional_branch(inside, selected, outside)
            self.current = outside
            self.emit(
                Handler.Call, [],
                attributes={
                    "callee": "turing_validation_error", "error_code": 71,
                    **attributes,
                },
            )
            self.branch(selected)
            self.current = selected
            if columns == 1:
                address = self.fresh_value(
                    dtype="ptr", transform=ADDRESS,
                    operands=(storage[0], normalized),
                )
                self.emit(
                    Handler.GetElementPtr, [storage[0], normalized], address,
                    attributes=attributes,
                )
                result = self.produced_value(
                    int(mutation.effect_node_id),
                    dtype=str(destination.column_dtypes[0] or "unknown"),
                    claim_provisional_definition=True,
                    cause=(address,),
                )
                self.emit(Handler.Load, [address], result, attributes=attributes)
                self._bind(
                    int(mutation.effect_node_id), result,
                    BindingKind.SEQUENCE_RESULT, address,
                )
            extra = (normalized,)
        elif operation == "insert":
            extra = tuple(arguments)
        storage_by_id = {int(value.id): value for value in storage}
        remaining = iter(extra)
        call_arguments = []
        for formal in lowering.entry.args:
            if int(formal.id) in storage_by_id:
                call_arguments.append(storage_by_id[int(formal.id)])
            else:
                call_arguments.append(next(remaining))
        status = self.fresh_value(
            dtype="int", transform=REGION_CALL_RESULT, operands=tuple(call_arguments),
        )
        self.emit(
            Handler.Call, call_arguments, status,
            attributes={
                "callee": lowering.entry.name, "source_linked": True,
                "ssa_sequence_operation": helper_operation, **attributes,
            },
        )
        status_arena = self.sequence_status_values.get(int(destination.sequence_id))
        if status_arena is not None:
            self.emit(
                Handler.Store, [status, self._sequence_status_address(status_arena)],
                attributes={"binding": "ssa_sequence_status"},
            )

    def _sequence_status_address(self, status_arena: SSAValue) -> SSAValue:
        if str(status_arena.dtype) == "ptr":
            # A selected row already supplies its exact per-child address.
            # Indexing that address again invents a second arena designator.
            return status_arena
        zero = self.constant_value(0, status_arena)
        address = self.fresh_value(
            dtype="ptr", transform=ADDRESS, operands=(status_arena, zero),
        )
        self.emit(
            Handler.GetElementPtr,
            [status_arena, zero],
            address,
            attributes={"binding": "ssa_sequence_status"},
        )
        return address

    def _reserve_owned_child_pool(self, descriptor, required, required_stride, *, location):
        """Use the incumbent context's typed reserve before deriving views."""
        from .ir_sequence_tables import lower_sequence_reserve
        helper_name = self._sequence_helper_name(int(descriptor.sequence_id), "reserve_child_pool")
        helper = self.sequence_helper_functions.get(helper_name)
        if helper is None:
            lowering = lower_sequence_reserve(descriptor, function_name=helper_name)
            if not lowering.complete:
                self.shortfalls.extend(SSALoweringShortfall("ssa-sequence", item.code.value, location, item.reason)
                                       for item in lowering.shortfalls)
                return self.constant_value(False, required, dtype="bool")
            self._register_sequence_lowering(lowering)
            helper = self.sequence_helper_functions[helper_name]
        status = self.fresh_value(dtype="int", transform=REGION_CALL_RESULT, operands=(required, required_stride))
        self.emit(Handler.Call, [*self.sequence_storage_values[int(descriptor.sequence_id)], required, required_stride], status,
                  attributes={"callee": helper.name, "source_linked": True, "ssa_sequence_operation": "reserve", "sequence_id": int(descriptor.sequence_id)})
        valid = self.fresh_value(dtype="bool", transform=CONTROL_PREDICATE, operands=(status,))
        self.emit(Handler.Lt, [status, self.constant_value(2, status)], valid)
        passed, failed, complete = (self.new_block(kind) for kind in ("validation_pass", "validation_fail", "if_merge"))
        self.conditional_branch(valid, passed, failed)
        self.current = failed
        self.emit(Handler.Call, [], attributes={"callee": "turing_validation_error", "error_code": 75,
                  "failure": "invalid_extent", "binding": "owned_child_pool_reserve"})
        self.branch(complete)
        self.current = passed
        self.branch(complete)
        self.current = complete
        return valid

    def lower_sequence_mutation(
        self,
        mutation: ControlSequenceMutation,
        *,
        path: str,
    ) -> None:
        if mutation.argument_kind in {"table_delete_key", "table_delete_keys"}:
            # A keyed ``del`` placed as its own control effect (see the
            # delete-carrier rule where table deletions are settled).
            keys = tuple(map(int, mutation.argument_value_ids))
            self._emit_table_delete(
                int(mutation.effect_node_id),
                keys if mutation.argument_kind == "table_delete_keys" else keys[0],
                int(mutation.sequence_value_id),
                f"sequence:{int(mutation.sequence_value_id)}",
            )
            return
        selection_validity = self.child_selection_validity.get(int(mutation.sequence_value_id))
        if mutation.predicate_expression is None and selection_validity is None:
            self._lower_sequence_mutation_body(mutation, path=path)
            return
        predicate = selection_validity
        if mutation.predicate_expression is not None:
            authored_predicate = self.lower_control_expression(mutation.predicate_expression)
            if predicate is None:
                predicate = authored_predicate
            else:
                combined = self.fresh_value(dtype="bool", transform=CONTROL_PREDICATE, operands=(predicate, authored_predicate))
                self.emit(Handler.LAnd, [predicate, authored_predicate], combined,
                          attributes={"binding": "selected_child_mutation_guard"})
                predicate = combined
        selected = self.new_block("sequence_mutation_selected")
        skipped = self.new_block("sequence_mutation_skipped")
        complete = self.new_block("sequence_mutation_merge")
        self.conditional_branch(predicate, selected, skipped)
        self.current = skipped
        self.branch(complete)
        self.current = selected
        if selection_validity is not None:
            self.active_child_selections.add(int(mutation.sequence_value_id))
        child_selection = self.child_table_selections.get(int(mutation.sequence_value_id))
        if child_selection is not None:
            pool, handle = child_selection
            parents = {(
                descriptor.column_value_ids, descriptor.length_address_id,
                descriptor.capacity_value_id, descriptor.heap_owner_value_id,
            ): descriptor for descriptor in self.sequence_descriptors.values()
                if descriptor.child_table_pool == pool and descriptor.heap_owner_value_id is not None}
            if len(parents) == 1:
                parent = next(iter(parents.values()))
                if str(mutation.operator) != "append":
                    self.shortfalls.append(SSALoweringShortfall("ssa-sequence", "owned-child-mutation", path,
                        "owned child growth requires an exact append extent"))
                    self.branch(complete)
                    self.current = complete
                    return
                lengths = self.external_value(pool.length_value_id)
                address = self.fresh_value(dtype="ptr", transform=ADDRESS, operands=(lengths, handle), physical={"physical_dtype": "int64"})
                self.emit(Handler.GetElementPtr, [lengths, handle], address)
                length = self.fresh_value(dtype="int64", transform=LOAD, operands=(address,))
                self.emit(Handler.Load, [address], length)
                required = self.fresh_value(dtype="int64", transform=CONTROL_EXPRESSION, operands=(length,))
                self.emit(Handler.Add, [length, self.constant_value(1, length, dtype="int64")], required)
                # Capacity is already this descriptor's scalar storage
                # member.  Re-reading its minted id as an external source
                # value appended a second, untyped formal (c639 borrowed
                # Index: 18 argument slots for17 identities).
                capacity = self.sequence_storage_values[int(parent.sequence_id)][len(parent.column_value_ids) + 1]
                valid = self._reserve_owned_child_pool(parent, capacity, required, location=path)
                append_block = self.new_block("sequence_mutation_selected")
                self.conditional_branch(valid, append_block, skipped)
                self.current = append_block
        self._lower_sequence_mutation_body(mutation, path=path)
        if selection_validity is not None:
            self.active_child_selections.discard(int(mutation.sequence_value_id))
        if not self.current.successors:
            self.branch(complete)
        self.current = complete

    def lower_sequence_query(
        self,
        query: SequenceQueryBlock,
        *,
        path: str,
    ) -> None:
        """Lower a lexical query against the sequence's length-cell ABI."""

        location = f"{path}.sequence_query[{query.source_call_node_id}]"
        if int(query.sequence_value_id) in self.native_object_source_ids and query.operation == 'length':
            self._emit_native_object_operation('length', int(query.sequence_value_id), (), int(query.result_value_id))
            return
        if query.operation == "lookup":
            self._emit_table_lookup(
                int(query.result_value_id),
                (
                    int(query.key_value_ids[0])
                    if len(query.key_value_ids) == 1
                    else tuple(map(int, query.key_value_ids))
                ),
                int(query.sequence_value_id),
            )
            return
        if query.operation == "membership":
            arguments = self.lexical_membership_arguments.pop(
                int(query.result_value_id), None
            )
            if arguments is None:
                raise ValueError(
                    "lexical sequence membership has no declared emission: "
                    f"{self.function_name} value {int(query.result_value_id)}"
                )
            self._emit_sequence_membership(*arguments)
            return
        sequence_id = int(query.sequence_value_id)
        selected_extent = self.selected_child_extent_values.get(sequence_id)
        if selected_extent is not None and query.operation in {"length", "truth"}:
            result = self.produced_value(int(query.result_value_id),
                dtype="bool" if query.operation == "truth" else "int64",
                cause=(selected_extent,), claim_provisional_definition=True)
            if query.operation == "truth":
                self.emit(Handler.Ne, [selected_extent, self.constant_value(0, selected_extent)], result,
                          attributes={"binding": "selected_child_optional_truth"})
            else:
                self.emit(Handler.Cast, [selected_extent], result,
                          attributes={"binding": "selected_child_optional_length"})
            self._bind(int(query.result_value_id), result, BindingKind.SEQUENCE_RESULT, selected_extent)
            return
        nested_selection = self.nested_row_selections.get(sequence_id)
        if (
            nested_selection is not None
            and query.operation in {"length", "truth"}
        ):
            child_lengths, handle = nested_selection
            attributes = {
                "binding": f"ssa_sequence_{query.operation}",
                "sequence_value_id": sequence_id,
                "source_call_node_id": query.source_call_node_id,
                "extraction_identity": query.extraction_identity,
            }
            length_address = self.fresh_value(
                dtype="ptr", transform=ADDRESS,
                operands=(child_lengths, handle),
            )
            length = self.fresh_value(
                dtype="int64", transform=LOAD,
                operands=(length_address,),
            )
            self.emit(
                Handler.GetElementPtr,
                [child_lengths, handle],
                length_address,
                attributes={**attributes, "binding": "nested_row_length"},
            )
            self.emit(
                Handler.Load, [length_address], length,
                attributes={**attributes, "binding": "nested_row_length"},
            )
            result = self.produced_value(
                int(query.result_value_id),
                dtype="bool" if query.operation == "truth" else "int64",
                claim_provisional_definition=True,
                cause=(length,),
            )
            self.emit(
                Handler.Gt if query.operation == "truth" else Handler.Cast,
                (
                    [length, self.constant_value(0, length)]
                    if query.operation == "truth" else [length]
                ),
                result,
                attributes={**attributes, "target_dtype": result.dtype},
            )
            self._bind_sequence_query_result(query, result, length)
            return
        from .identity_concordance import committed_sequence_contract

        contract = committed_sequence_contract(
            self.function_name, sequence_id,
        )
        resolved = self.resolved_sequence_schemas.get(sequence_id)
        # Length/maximum/first queries do not declare a collection policy.
        # Consume the exact resident contract committed before control
        # lowering.  The former unconditional ``duplicates`` claim rewrote a
        # set comprehension's already-concorded ``unique`` identity merely
        # because len(layouts) happened to be the first consumer lowered.
        query_policy = (
            str(contract.policy)
            if contract is not None
            else str(resolved.policy)
            if resolved is not None
            else "duplicates"
        )
        descriptor = self._sequence_descriptor(
            sequence_id,
            policy=query_policy,
            writable=True,
            location=location,
        )
        if descriptor is None:
            return
        storage = self.sequence_storage_values[sequence_id]
        length_address = storage[len(descriptor.column_value_ids)]
        attributes = {
            "binding": f"ssa_sequence_{query.operation}",
            "sequence_value_id": int(query.sequence_value_id),
            "source_call_node_id": query.source_call_node_id,
            "extraction_identity": query.extraction_identity,
        }
        length = self.fresh_value(
            dtype="int64", transform=LOAD, operands=(length_address,),
        )
        self.emit(Handler.Load, [length_address], length, attributes=attributes)
        if query.operation == "any":
            preheader = self.current
            header = self.new_block("sequence_any_header")
            body = self.new_block("sequence_any_body")
            latch = self.new_block("sequence_any_latch")
            exit_block = self.new_block("sequence_any_exit")
            zero = self.constant_value(0, length, dtype="int64")
            one = self.constant_value(1, length, dtype="int64")
            false = self.constant_value(False, length, dtype="bool")
            next_index = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(length,),
            )
            next_accumulator = self.fresh_value(
                dtype="bool", transform=CONTROL_EXPRESSION,
                operands=(storage[0],),
            )
            self.branch(header)

            self.current = header
            index = self.fresh_value(
                dtype="int64", transform=PHI_LOOP_HEADER,
                operands=(zero, next_index),
            )
            self.emit(
                Handler.Phi, [zero, next_index], index,
                attributes={
                    **attributes,
                    "incoming_blocks": (preheader.name, latch.name),
                    "binding": "ssa_sequence_any_index",
                },
            )
            accumulator = self.fresh_value(
                dtype="bool", transform=PHI_LOOP_HEADER,
                operands=(false, next_accumulator),
            )
            self.emit(
                Handler.Phi, [false, next_accumulator], accumulator,
                attributes={
                    **attributes,
                    "incoming_blocks": (preheader.name, latch.name),
                    "binding": "ssa_sequence_any_accumulator",
                },
            )
            has_item = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(index, length),
            )
            self.emit(
                Handler.Lt, [index, length], has_item,
                attributes=attributes,
            )
            self.conditional_branch(has_item, body, exit_block)

            self.current = body
            address = self.fresh_value(
                dtype="ptr", transform=ADDRESS,
                operands=(storage[0], index),
            )
            self.emit(
                Handler.GetElementPtr, [storage[0], index], address,
                attributes=attributes,
            )
            candidate = self.fresh_value(
                dtype="bool", transform=LOAD, operands=(address,),
            )
            self.emit(
                Handler.Load, [address], candidate,
                attributes=attributes,
            )
            self.emit(
                Handler.Or, [accumulator, candidate], next_accumulator,
                attributes={**attributes, "binding": "ssa_sequence_any"},
            )
            self.branch(latch)

            self.current = latch
            self.emit(
                Handler.Add, [index, one], next_index,
                attributes=attributes,
            )
            self.branch(header)

            self.current = exit_block
            result = self.produced_value(
                int(query.result_value_id), dtype="bool",
                claim_provisional_definition=True,
                cause=(accumulator,),
            )
            self.emit(
                Handler.Cast, [accumulator], result,
                attributes={**attributes, "target_dtype": "bool"},
            )
            self._bind_sequence_query_result(query, result, accumulator)
            return
        if query.operation == "maximum":
            value_dtype = str((descriptor.column_dtypes or ("unknown",))[0])

            def ordered_maximum(
                incumbent: SSAValue,
                candidate: SSAValue,
            ) -> SSAValue:
                """Select candidate only for strict greater-than.

                This is Python's ordered ``max`` rule: equality and unordered
                floating-point comparisons retain the incumbent.
                """

                selected = self.new_block("sequence_maximum_selected")
                retained = self.new_block("sequence_maximum_retained")
                complete = self.new_block("sequence_maximum_merge")
                greater = self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE,
                    operands=(candidate, incumbent),
                )
                self.emit(
                    Handler.Gt,
                    [candidate, incumbent],
                    greater,
                    attributes=attributes,
                )
                self.conditional_branch(greater, selected, retained)
                self.current = selected
                self.branch(complete)
                self.current = retained
                self.branch(complete)
                self.current = complete
                merged = self.fresh_value(
                    dtype=value_dtype, transform=PHI_CONDITIONAL,
                    operands=(candidate, incumbent, greater),
                )
                self.emit(
                    Handler.Phi,
                    [candidate, incumbent],
                    merged,
                    attributes={
                        **attributes,
                        "incoming_blocks": (selected.name, retained.name),
                        "binding": "ssa_sequence_ordered_maximum",
                    },
                )
                return merged

            prefix = tuple(
                self.external_value(int(value_id), dtype=value_dtype)
                for value_id in query.reduction_prefix_value_ids
            )
            accumulator = prefix[0]
            for candidate in prefix[1:]:
                accumulator = ordered_maximum(accumulator, candidate)

            preheader = self.current
            header = self.new_block("sequence_maximum_header")
            body = self.new_block("sequence_maximum_body")
            selected = self.new_block("sequence_maximum_loop_selected")
            retained = self.new_block("sequence_maximum_loop_retained")
            latch = self.new_block("sequence_maximum_latch")
            exit_block = self.new_block("sequence_maximum_exit")
            zero = self.constant_value(0, length, dtype="int64")
            one = self.constant_value(1, length, dtype="int64")
            next_index = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION, operands=(length,),
            )
            next_accumulator = self.fresh_value(
                dtype=value_dtype, transform=PHI_CONDITIONAL,
                operands=(accumulator, storage[0]),
            )
            self.branch(header)

            self.current = header
            index = self.fresh_value(
                dtype="int64", transform=PHI_LOOP_HEADER,
                operands=(zero, next_index),
            )
            self.emit(
                Handler.Phi,
                [zero, next_index],
                index,
                attributes={
                    **attributes,
                    "incoming_blocks": (preheader.name, latch.name),
                    "binding": "ssa_sequence_maximum_index",
                },
            )
            current_accumulator = self.fresh_value(
                dtype=value_dtype, transform=PHI_LOOP_HEADER,
                operands=(accumulator, next_accumulator),
            )
            self.emit(
                Handler.Phi,
                [accumulator, next_accumulator],
                current_accumulator,
                attributes={
                    **attributes,
                    "incoming_blocks": (preheader.name, latch.name),
                    "binding": "ssa_sequence_maximum_accumulator",
                },
            )
            has_item = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(index, length),
            )
            self.emit(Handler.Lt, [index, length], has_item, attributes=attributes)
            self.conditional_branch(has_item, body, exit_block)

            self.current = body
            address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(storage[0], index),
            )
            self.emit(
                Handler.GetElementPtr,
                [storage[0], index],
                address,
                attributes=attributes,
            )
            candidate = self.fresh_value(
                dtype=value_dtype, transform=LOAD, operands=(address,),
            )
            self.emit(Handler.Load, [address], candidate, attributes=attributes)
            greater = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(candidate, current_accumulator),
            )
            self.emit(
                Handler.Gt,
                [candidate, current_accumulator],
                greater,
                attributes=attributes,
            )
            self.conditional_branch(greater, selected, retained)
            self.current = selected
            self.branch(latch)
            self.current = retained
            self.branch(latch)

            self.current = latch
            self.emit(
                Handler.Phi,
                [candidate, current_accumulator],
                next_accumulator,
                attributes={
                    **attributes,
                    "incoming_blocks": (selected.name, retained.name),
                    "binding": "ssa_sequence_ordered_maximum",
                },
            )
            self.emit(
                Handler.Add,
                [index, one],
                next_index,
                attributes=attributes,
            )
            self.branch(header)

            self.current = exit_block
            accumulator = current_accumulator
            for value_id in query.reduction_suffix_value_ids:
                accumulator = ordered_maximum(
                    accumulator,
                    self.external_value(int(value_id), dtype=value_dtype),
                )
            result = self.produced_value(
                int(query.result_value_id),
                dtype=value_dtype,
                claim_provisional_definition=True,
                cause=(accumulator,),
            )
            self.emit(
                Handler.Cast,
                [accumulator],
                result,
                attributes={**attributes, "target_dtype": value_dtype},
            )
            self._bind_sequence_query_result(query, result, accumulator)
            return
        if query.operation == "sum":
            # ``sum(collection[, start])`` over the materialized row column.
            # Python's ``sum`` of an empty float collection is the int 0,
            # so a float row has no single result type: only integer and
            # bool rows (whose sum is always an int) with an integer start
            # are lowered; anything else is a named shortfall.
            row_dtype = str((descriptor.column_dtypes or ("unknown",))[0])
            start = (
                None if query.default_value_id is None
                else self.external_value(int(query.default_value_id))
            )
            if row_dtype not in {"int64", "int32", "int", "bool"} or (
                start is not None
                and str(start.dtype or "unknown") not in {
                    "int64", "int32", "int", "bool",
                }
            ):
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", "sum", self.function_name,
                    f"resident sum over {row_dtype!r} rows with start "
                    f"{None if start is None else start.dtype!r}: Python's "
                    "sum has one result type only for integer rows and an "
                    "integer start",
                ))
                return
            if start is None:
                start = self.constant_value(0, length, dtype="int64")
            elif str(start.dtype) != "int64":
                widened = self.fresh_value(
                    dtype="int64", transform=CONTROL_CAST, operands=(start,),
                )
                self.emit(
                    Handler.Cast, [start], widened,
                    attributes={**attributes, "target_dtype": "int64"},
                )
                start = widened
            preheader = self.current
            header = self.new_block("sequence_sum_header")
            body = self.new_block("sequence_sum_body")
            exit_block = self.new_block("sequence_sum_exit")
            zero = self.constant_value(0, length, dtype="int64")
            one = self.constant_value(1, length, dtype="int64")
            next_index = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION, operands=(length,),
            )
            next_accumulator = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(start, storage[0]),
            )
            self.branch(header)

            self.current = header
            index = self.fresh_value(
                dtype="int64", transform=PHI_LOOP_HEADER,
                operands=(zero, next_index),
            )
            self.emit(
                Handler.Phi, [zero, next_index], index,
                attributes={
                    **attributes,
                    "incoming_blocks": (preheader.name, body.name),
                    "binding": "ssa_sequence_sum_index",
                },
            )
            accumulator = self.fresh_value(
                dtype="int64", transform=PHI_LOOP_HEADER,
                operands=(start, next_accumulator),
            )
            self.emit(
                Handler.Phi, [start, next_accumulator], accumulator,
                attributes={
                    **attributes,
                    "incoming_blocks": (preheader.name, body.name),
                    "binding": "ssa_sequence_sum_accumulator",
                },
            )
            has_item = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(index, length),
            )
            self.emit(Handler.Lt, [index, length], has_item, attributes=attributes)
            self.conditional_branch(has_item, body, exit_block)

            self.current = body
            address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(storage[0], index),
            )
            self.emit(
                Handler.GetElementPtr, [storage[0], index], address,
                attributes=attributes,
            )
            item = self.fresh_value(
                dtype=row_dtype, transform=LOAD, operands=(address,),
            )
            self.emit(Handler.Load, [address], item, attributes=attributes)
            if row_dtype != "int64":
                widened_item = self.fresh_value(
                    dtype="int64", transform=CONTROL_CAST, operands=(item,),
                )
                self.emit(
                    Handler.Cast, [item], widened_item,
                    attributes={**attributes, "target_dtype": "int64"},
                )
                item = widened_item
            self.emit(
                Handler.Add, [accumulator, item], next_accumulator,
                attributes=attributes,
            )
            self.emit(Handler.Add, [index, one], next_index, attributes=attributes)
            self.branch(header)

            self.current = exit_block
            result = self.produced_value(
                int(query.result_value_id),
                dtype="int64",
                claim_provisional_definition=True,
                cause=(accumulator,),
            )
            self.emit(
                Handler.Cast, [accumulator], result,
                attributes={**attributes, "target_dtype": "int64"},
            )
            self._bind_sequence_query_result(query, result, accumulator)
            return
        if query.operation in {"count", "index"}:
            # ``xs.count(v)``: rows equal to ``v``.  ``xs.index(v)``: the
            # first such row; Python raises ValueError when there is none
            # (validation error 76).  The comparison is one dtype: a key of
            # another dtype is a named shortfall, not a conversion.
            row_dtype = str((descriptor.column_dtypes or ("unknown",))[0])
            key = self.external_value(int(query.key_value_ids[0]))
            if len(descriptor.column_value_ids) != 1 or str(
                key.dtype or "unknown"
            ) != row_dtype or row_dtype not in {
                "int64", "float64", "bool",
            }:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", query.operation, self.function_name,
                    f"resident {query.operation} over {row_dtype!r} rows "
                    f"with a {key.dtype!r} key",
                ))
                return
            counting = query.operation == "count"
            preheader = self.current
            header = self.new_block(f"sequence_{query.operation}_header")
            body = self.new_block(f"sequence_{query.operation}_body")
            latch = self.new_block(f"sequence_{query.operation}_latch")
            exit_block = self.new_block(f"sequence_{query.operation}_exit")
            found = None if counting else self.new_block("sequence_index_found")
            missing = None if counting else self.new_block("sequence_index_missing")
            zero = self.constant_value(0, length, dtype="int64")
            one = self.constant_value(1, length, dtype="int64")
            next_index = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION, operands=(length,),
            )
            next_count = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(storage[0], key),
            ) if counting else None
            self.branch(header)

            self.current = header
            index = self.fresh_value(
                dtype="int64", transform=PHI_LOOP_HEADER,
                operands=(zero, next_index),
            )
            self.emit(
                Handler.Phi, [zero, next_index], index,
                attributes={
                    **attributes,
                    "incoming_blocks": (preheader.name, latch.name),
                    "binding": f"ssa_sequence_{query.operation}_index",
                },
            )
            tally = None
            if counting:
                tally = self.fresh_value(
                    dtype="int64", transform=PHI_LOOP_HEADER,
                    operands=(zero, next_count),
                )
                self.emit(
                    Handler.Phi, [zero, next_count], tally,
                    attributes={
                        **attributes,
                        "incoming_blocks": (preheader.name, latch.name),
                        "binding": "ssa_sequence_count_tally",
                    },
                )
            has_item = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(index, length),
            )
            self.emit(Handler.Lt, [index, length], has_item, attributes=attributes)
            self.conditional_branch(
                has_item, body, exit_block if counting else missing,
            )

            self.current = body
            address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(storage[0], index),
            )
            self.emit(
                Handler.GetElementPtr, [storage[0], index], address,
                attributes=attributes,
            )
            item = self.fresh_value(
                dtype=row_dtype, transform=LOAD, operands=(address,),
            )
            self.emit(Handler.Load, [address], item, attributes=attributes)
            equal = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE, operands=(item, key),
            )
            self.emit(Handler.Eq, [item, key], equal, attributes=attributes)
            if counting:
                hit = self.fresh_value(
                    dtype="int64", transform=CONTROL_CAST, operands=(equal,),
                )
                self.emit(
                    Handler.Cast, [equal], hit,
                    attributes={**attributes, "target_dtype": "int64"},
                )
                self.emit(Handler.Add, [tally, hit], next_count, attributes=attributes)
                self.branch(latch)
            else:
                self.conditional_branch(equal, found, latch)

            self.current = latch
            self.emit(Handler.Add, [index, one], next_index, attributes=attributes)
            self.branch(header)

            if counting:
                self.current = exit_block
                answer = tally
            else:
                self.current = missing
                self.emit(
                    Handler.Call, [],
                    attributes={
                        "callee": "turing_validation_error", "error_code": 76,
                        **attributes,
                    },
                )
                absent = self.constant_value(-1, length, dtype="int64")
                self.branch(exit_block)
                self.current = found
                self.branch(exit_block)
                self.current = exit_block
                answer = self.fresh_value(
                    dtype="int64", transform=PHI_LOOP_HEADER,
                    operands=(index, absent),
                )
                self.emit(
                    Handler.Phi, [index, absent], answer,
                    attributes={
                        **attributes,
                        "incoming_blocks": (found.name, missing.name),
                        "binding": "ssa_sequence_index_result",
                    },
                )
            result = self.produced_value(
                int(query.result_value_id),
                dtype="int64",
                claim_provisional_definition=True,
                cause=(answer,),
            )
            self.emit(
                Handler.Cast, [answer], result,
                attributes={**attributes, "target_dtype": "int64"},
            )
            self._bind_sequence_query_result(query, result, answer)
            return
        if query.operation in {"length", "truth"}:
            result = self.produced_value(
                int(query.result_value_id),
                dtype="bool" if query.operation == "truth" else "int64",
                claim_provisional_definition=True,
                cause=(length,),
            )
            self.emit(
                Handler.Gt if query.operation == "truth" else Handler.Cast,
                [length, self.constant_value(0, length)] if query.operation == "truth" else [length],
                result,
                attributes={**attributes, "target_dtype": result.dtype},
            )
            self._bind_sequence_query_result(query, result, length)
            return

        zero = self.constant_value(0, length)
        if query.operation == "first":
            row_storage = storage[:len(descriptor.column_value_ids)]
            if len(row_storage) > 1 and len(query.result_member_ids) != len(row_storage):
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", "first-aggregate-row",
                    self.function_name,
                    "resident sequence first requires an exact aggregate "
                    "member identity for every row column",
                ))
                return
            if len(row_storage) > 1:
                contract_cell = self._sequence_contract_cell(
                    int(query.sequence_value_id)
                )
                for column, (column_storage, member_id) in enumerate(zip(
                    row_storage, query.result_member_ids,
                )):
                    address = self.fresh_value(
                        dtype="ptr", transform=ADDRESS,
                        operands=(column_storage, zero),
                    )
                    member_attributes = {
                        **attributes,
                        "aggregate_index": int(column),
                        "binding": "sequence_first_aggregate_member",
                    }
                    self.emit(
                        Handler.GetElementPtr,
                        [column_storage, zero],
                        address,
                        attributes=member_attributes,
                    )
                    selected_value = self.fresh_value(
                        dtype=column_storage.dtype,
                        transform=LOAD,
                        operands=(address,),
                    )
                    self.emit(
                        Handler.Load, [address], selected_value,
                        attributes=member_attributes,
                    )
                    result = self.produced_value(
                        int(member_id),
                        dtype=str(selected_value.dtype or "unknown"),
                        claim_provisional_definition=True,
                        cause=(selected_value,),
                    )
                    self.emit(
                        Handler.Cast, [selected_value], result,
                        attributes={
                            **member_attributes,
                            "target_dtype": result.dtype,
                        },
                    )
                    self._bind(
                        int(member_id), result,
                        BindingKind.SEQUENCE_RESULT,
                        contract_cell, selected_value,
                    )
                return
            address = self.fresh_value(
                dtype="ptr", transform=ADDRESS,
                operands=(storage[0], zero),
            )
            self.emit(
                Handler.GetElementPtr, [storage[0], zero], address,
                attributes=attributes,
            )
            selected_value = self.fresh_value(
                dtype=str((descriptor.column_dtypes or ("unknown",))[0]), transform=LOAD,
                operands=(address,),
            )
            self.emit(
                Handler.Load, [address], selected_value,
                attributes=attributes,
            )
            result = self.produced_value(
                int(query.result_value_id),
                dtype=str(selected_value.dtype or "unknown"),
                claim_provisional_definition=True,
                cause=(selected_value,),
            )
            self.emit(
                Handler.Cast, [selected_value], result,
                attributes={**attributes, "target_dtype": result.dtype},
            )
            self._bind_sequence_query_result(query, result, selected_value)
            return
        nonempty = self.fresh_value(
            dtype="bool", transform=CONTROL_PREDICATE, operands=(length, zero),
        )
        self.emit(Handler.Gt, [length, zero], nonempty, attributes=attributes)
        selected = self.new_block("sequence_query_selected")
        defaulted = self.new_block("sequence_query_defaulted")
        complete = self.new_block("sequence_query_merge")
        self.conditional_branch(nonempty, selected, defaulted)

        self.current = selected
        address = self.fresh_value(
            dtype="ptr", transform=ADDRESS, operands=(storage[0], zero),
        )
        self.emit(
            Handler.GetElementPtr,
            [storage[0], zero],
            address,
            attributes=attributes,
        )
        selected_value = self.fresh_value(
            dtype=("int" if query.row_handle else str((descriptor.column_dtypes or ("unknown",))[0])),
            transform=LOAD, operands=(address,),
        )
        self.emit(Handler.Load, [address], selected_value, attributes=attributes)
        self.branch(complete)

        self.current = defaulted
        default_value = (
            self.constant_value(-1, storage[0])
            if query.row_handle
            else self.external_value(int(query.default_value_id))
        )
        self.branch(complete)

        self.current = complete
        result = self.produced_value(
            int(query.result_value_id),
            dtype=str(selected_value.dtype or default_value.dtype or "unknown"),
            claim_provisional_definition=True,
            cause=(selected_value, default_value, nonempty),
        )
        self.emit(
            Handler.Phi,
            [selected_value, default_value],
            result,
            attributes={
                **attributes,
                "incoming_blocks": (selected.name, defaulted.name),
            },
        )
        self._bind_sequence_query_result(
            query, result, selected_value, default_value,
        )

    def _bind_sequence_query_result(
        self, query: Any, result: SSAValue, *cells: Any,
    ) -> None:
        """Bind a sequence query's result id and its alias ids to ``result``
        (SEQUENCE_RESULT, from the sequence's contract cell and ``cells``)."""

        contract_cell = self._sequence_contract_cell(int(query.sequence_value_id))
        self._bind(
            int(query.result_value_id), result, BindingKind.SEQUENCE_RESULT,
            contract_cell, *cells,
        )
        for alias_id in query.result_alias_ids:
            self._bind(
                int(alias_id), result, BindingKind.SEQUENCE_RESULT,
                contract_cell, *cells,
            )

    def ensure_plan_callsite_result(
        self, value_id: int, *, location: str,
    ) -> None:
        """Materialize a planned call at its first lexical structural use."""

        callsite_id = self.plan_callsite_by_result.get(int(value_id))
        if (
            callsite_id is None
            or int(callsite_id) in self.emitted_plan_callsites
        ):
            return
        self.emit_plan_callsite(int(callsite_id), location=location)

    def _native_object_bindings(self):
        from .ssa_object_context import context_values
        context = self.native_object_context
        if context is None or self.native_object_module is None:
            raise ValueError('source object operation has no admitted context')
        bindings = {}
        for cell in context_values(context):
            actual = self.external_value(cell.id, dtype=cell.dtype)
            actual.accounting = {**dict(actual.accounting or {}), **dict(cell.accounting or {}),
                'native_object_context_storage_identity': context.storage_identity,
                'native_object_context_value_id': cell.id}
            bindings[cell.id] = actual
        self.native_object_context_used = True
        return bindings

    def _emit_native_object_operation(self, operation, reference_id, operands, result_id):
        from .ssa_object_operations import object_call
        from ..transmogrifier.ssa import SSAOpaqueObject
        bindings = self._native_object_bindings()
        helper = next(function for function in self.native_object_module.functions.values()
            if function.metadata.get('opaque_object_helper', {}).get('operation') == operation)
        receipt = helper.metadata['opaque_object_helper']
        # A compiler-minted Const already is the exact SSA occurrence. Sending
        # its id through source alias resolution made the materialize kind
        # token a producerless formal, despite its preceding real Const.
        operand_values = tuple(value_id if isinstance(value_id, SSAValue)
            else self.external_value(int(value_id)) for value_id in operands)
        result_dtype = receipt['result_layout'][0]
        result = (self.fresh_value(dtype=result_dtype, transform=CONTROL_EXPRESSION,
                                  operands=(int(reference_id), *operand_values)) if result_id is None
                  else self.produced_value(int(result_id), dtype=result_dtype,
                    claim_provisional_definition=True, cause=(int(reference_id), *operand_values)))
        reference = SSAOpaqueObject(self.external_value(reference_id), self.native_object_context.storage_identity)
        instruction = object_call(self.native_object_module, helper.name, reference,
            context=bindings, operands=dict(zip(receipt['operand_formal_ids'], operand_values, strict=True)), result=result)
        instruction.attributes['source_object_operation'] = (operation, reference_id,
            tuple(value.id for value in operand_values), result_id)
        self.emit(Handler.Call, instruction.args, instruction.res, attributes=instruction.attributes)
        if operation in {'length', 'get', 'set', 'materialize', 'collect', 'update'}:
            self.native_object_requires_member_storage = True
        return result

    def _emit_native_object_type_test(self, value_id):
        # isinstance(item,tuple) retained an intrinsic/static type object but
        # had no Boolean SSA producer. Read the optional introspection facet
        # of the SAME identity table; storage-kind equality is not MRO evidence.
        source = self.native_object_type_tests[value_id]
        context = self.native_object_context
        vocabulary = context.type_vocabulary
        bits = sum(1 << vocabulary.index(token) for token in set(source['accepted_types']))
        evidence = self._emit_native_object_operation('type_mask', source['reference_value_id'], (), None)
        token = self.fresh_value(dtype='int64', transform=CONTROL_CONST, operands=(evidence,))
        self.emit(Handler.Const, [], token, attributes={'value': bits})
        selected = self.fresh_value(dtype='int64', transform=CONTROL_EXPRESSION, operands=(evidence, token))
        self.emit(Handler.And, [evidence, token], selected)
        zero = self.fresh_value(dtype='int64', transform=CONTROL_CONST, operands=(selected,))
        self.emit(Handler.Const, [], zero, attributes={'value': 0})
        result = self.produced_value(value_id, dtype='bool', claim_provisional_definition=True,
                                     cause=(evidence, token, selected, zero))
        receipt = {**source, 'context': context.to_mapping(), 'mask_value_id': evidence.id,
                   'token_value_id': token.id, 'selected_value_id': selected.id, 'mask': bits}
        self.emit(Handler.Ne, [selected, zero], result, attributes={'source_object_type_test': receipt})
        self.native_object_type_test_receipts.append(receipt)

    def _native_value_type_predicate(
        self, subject_id, accepted, *, result_override=None,
        subtype=False, receipt=None,
    ):
        """Return the native predicate for one authoritative type ABI row.

        ``native_type_identity`` control expressions use exact identity.
        Authored ``isinstance`` tests opt into the separately stated subtype
        relation.  Both consume the same linked tag table and therefore can
        own branch-local work without executing a Python predicate or
        minting an independent discriminant.
        """

        subject_id = int(subject_id)
        fact = self.native_value_type_abi.get(subject_id)
        if fact is None:
            raise ValueError(
                "native type predicate has no authoritative value_type_abi "
                f"for {self.function_name} value {subject_id}"
            )
        alternatives = tuple(
            fact.get("alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "alternatives", ())
        )
        element_class_fact = tuple(
            (receipt or {}).get(
                "subject_callsite_iterable_element_class_fact", ()
            )
        )
        if (
            len(element_class_fact) >= 4
            and str(element_class_fact[0]) == "unknown"
        ):
            exact_classes = tuple(sorted(set(map(
                str, element_class_fact[3],
            ))))
            tag = self.native_value_type_tags.get(subject_id)
            if tag is None:
                tag = self.scheduled_projected_native_type_tag(subject_id)
            if tuple(map(str, alternatives)) != exact_classes or tag is None:
                raise ValueError(
                    "unsupported mixed-element native type ABI: "
                    f"{self.function_name} value {subject_id} has exact "
                    f"callsite element classes {exact_classes!r}, while "
                    f"VALUE_TYPE_ABI declares {tuple(map(str, alternatives))!r}; "
                    "the sequence ABI has no per-element class tag"
                )
        tags = dict(
            fact.get("tags", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "tags", ())
        )
        accepted = set(map(str, accepted))
        admitted_identities = set(accepted)
        if subtype:
            admitted_identities = {
                identity
                for base in accepted
                for identity in canonical_python_subtype_identities(
                    base, book=self._book(),
                )
            }

        def admitted(identity: str) -> bool:
            return identity in admitted_identities

        matching = tuple(
            identity for identity in alternatives if admitted(str(identity))
        )
        if len(alternatives) == 1:
            result = result_override or self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(
                    self._book().latest_ref(
                        VALUE_TYPE_ABI,
                        (self.lexical_read_scope, subject_id),
                    ),
                ),
            )
            self.emit(
                Handler.Const, [], result,
                attributes={
                    "value": bool(matching),
                    "source_native_type_test": dict(receipt or {}),
                },
            )
            return result
        evidence = self.native_value_type_tags.get(subject_id)
        if evidence is None:
            evidence = self.scheduled_projected_native_type_tag(subject_id)
        if evidence is None:
            # PlanCall results are linked after control SSA construction.  As
            # with their payload placeholder, retain a typed formal now; the
            # exact call-result binding replaces this SAME companion during
            # frame linking.  It is not a Python/runtime fallback.
            evidence = self.fresh_value(
                dtype="int64", transform=REGION_FORMAL_SPLIT,
                operands=(self._canonical_cell(subject_id),),
            )
            evidence.accounting.update({
                "native_type_tag_pending_for_value_id": subject_id,
                "native_type_alternatives": alternatives,
                "native_type_tags": tuple(tags.items()),
            })
            self.arguments.append(evidence)
            self.native_value_type_tags[subject_id] = evidence
            payload = self.external_value(subject_id)
            payload.accounting = {
                **dict(payload.accounting or {}),
                "native_type_tag_value_id": int(evidence.id),
                "native_type_alternatives": alternatives,
            }
            self.post_native_type_tag(
                subject_id, evidence, fact, payload,
            )
        comparisons = []
        for identity in matching:
            token = self.fresh_value(
                dtype="int64", transform=CONTROL_CONST,
                operands=(evidence,),
            )
            self.emit(
                Handler.Const, [], token,
                attributes={"value": int(tags[str(identity)])},
            )
            comparison = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(evidence, token),
            )
            self.emit(Handler.Eq, [evidence, token], comparison)
            comparisons.append(comparison)
        if not comparisons:
            result = result_override or self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(evidence,),
            )
            self.emit(
                Handler.Const, [], result,
                attributes={
                    "value": False,
                    "source_native_type_test": dict(receipt or {}),
                },
            )
            return result
        selected = comparisons[0]
        for comparison in comparisons[1:]:
            combined = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(selected, comparison),
            )
            self.emit(Handler.Or, [selected, comparison], combined)
            selected = combined
        result = result_override or self.fresh_value(
            dtype="bool", transform=CONTROL_PREDICATE,
            operands=(evidence, *comparisons),
        )
        # A final identity copy is ordinary boolean SSA; no callable or
        # interpreter escape remains in the repository module.
        self.emit(
            Handler.Or, [selected, selected], result,
            attributes={
                "source_native_type_test": {
                    **dict(receipt or {}),
                    "type_abi": fact,
                    "tag_value_id": int(evidence.id),
                },
            },
        )
        return result

    def _native_dynamic_type_predicate(
        self, subject_id, target_id, target_types, *, result_override,
        receipt=None,
    ):
        """Compare a value tag with an API-declared runtime type target.

        The target is an ordinary one-based int64 token in the declared
        vocabulary.  The subject keeps its own VALUE_TYPE_ABI tag table; this
        routine joins the two canonical identity tables explicitly, including
        subtype admission, so unrelated dense tag ordinals are never compared
        as though they shared a namespace.
        """

        subject_id = int(subject_id)
        target_id = int(target_id)
        fact = self.native_value_type_abi.get(subject_id)
        if fact is None:
            raise ValueError(
                "dynamic native type predicate has no authoritative "
                f"value_type_abi for {self.function_name} value {subject_id}"
            )
        alternatives = tuple(map(str, (
            fact.get("alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "alternatives", ())
        )))
        tags = dict(
            fact.get("tags", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "tags", ())
        )
        target_types = tuple(map(str, target_types))
        target = self.external_value(target_id, dtype="int64")
        target.dtype = "int64"

        subject_tag = self.native_value_type_tags.get(subject_id)
        if subject_tag is None:
            subject_tag = self.scheduled_projected_native_type_tag(subject_id)
        if len(alternatives) > 1 and subject_tag is None:
            subject_tag = self.fresh_value(
                dtype="int64", transform=REGION_FORMAL_SPLIT,
                operands=(self._canonical_cell(subject_id),),
            )
            subject_tag.accounting.update({
                "native_type_tag_pending_for_value_id": subject_id,
                "native_type_alternatives": alternatives,
                "native_type_tags": tuple(tags.items()),
            })
            self.arguments.append(subject_tag)
            self.native_value_type_tags[subject_id] = subject_tag
            payload = self.external_value(subject_id)
            payload.accounting = {
                **dict(payload.accounting or {}),
                "native_type_tag_value_id": int(subject_tag.id),
                "native_type_alternatives": alternatives,
            }
            self.post_native_type_tag(
                subject_id, subject_tag, fact, payload,
            )

        matches = []
        for identity in alternatives:
            admitted_targets = tuple(
                index + 1
                for index, target_identity in enumerate(target_types)
                if identity in canonical_python_subtype_identities(
                    target_identity, book=self._book(),
                )
            )
            for target_token_value in admitted_targets:
                target_token = self.fresh_value(
                    dtype="int64", transform=CONTROL_CONST,
                    operands=(target,),
                )
                self.emit(
                    Handler.Const, [], target_token,
                    attributes={
                        "value": int(target_token_value),
                        "program_abi_vocabulary_token": target_types[
                            target_token_value - 1
                        ],
                    },
                )
                target_match = self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE,
                    operands=(target, target_token),
                )
                self.emit(Handler.Eq, [target, target_token], target_match)
                if subject_tag is None:
                    matches.append(target_match)
                    continue
                subject_token = self.fresh_value(
                    dtype="int64", transform=CONTROL_CONST,
                    operands=(subject_tag,),
                )
                self.emit(
                    Handler.Const, [], subject_token,
                    attributes={"value": int(tags[identity])},
                )
                subject_match = self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE,
                    operands=(subject_tag, subject_token),
                )
                self.emit(
                    Handler.Eq, [subject_tag, subject_token], subject_match,
                )
                pair_match = self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE,
                    operands=(subject_match, target_match),
                )
                self.emit(
                    Handler.And, [subject_match, target_match], pair_match,
                )
                matches.append(pair_match)

        if not matches:
            self.emit(
                Handler.Const, [], result_override,
                attributes={
                    "value": False,
                    "source_native_type_test": dict(receipt or {}),
                },
            )
            return result_override
        selected = matches[0]
        for match in matches[1:]:
            combined = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(selected, match),
            )
            self.emit(Handler.Or, [selected, match], combined)
            selected = combined
        self.emit(
            Handler.Or, [selected, selected], result_override,
            attributes={
                "source_native_type_test": {
                    **dict(receipt or {}),
                    "type_abi": fact,
                    "target_value_id": target_id,
                    "target_vocabulary": target_types,
                    **({
                        "tag_value_id": int(subject_tag.id),
                    } if subject_tag is not None else {}),
                },
            },
        )
        return result_override

    def native_type_tag_for(
        self, value_id: int, authoritative_fact: Any,
    ) -> SSAValue | None:
        """Return ``value_id``'s tag in ``authoritative_fact``'s table.

        Exact values become constants.  A union already using the table is
        forwarded.  A different accepted union is explicitly remapped with
        integer comparisons and Selects; independently minted dense integers
        are never compared as though they shared an identity space.
        """

        target_alternatives = tuple(
            authoritative_fact.get("alternatives", ())
            if isinstance(authoritative_fact, Mapping)
            else getattr(authoritative_fact, "alternatives", ())
        )
        if len(target_alternatives) <= 1:
            return None
        target_tags = dict(
            authoritative_fact.get("tags", ())
            if isinstance(authoritative_fact, Mapping)
            else getattr(authoritative_fact, "tags", ())
        )
        resident_value_id = self._concorded_resident(int(value_id))
        source_fact = (
            self.native_value_type_abi.get(int(value_id))
            or self.native_value_type_abi.get(resident_value_id)
        )
        source_value = (
            self.external_values.get(int(value_id))
            or self.ssa_value_objects.get(int(value_id))
        )
        source_accounting = dict(
            () if source_value is None else source_value.accounting or {}
        )
        source_alternatives = tuple(
            source_fact.get("alternatives", ())
            if isinstance(source_fact, Mapping)
            else getattr(source_fact, "alternatives", ())
        ) or tuple(source_accounting.get("native_type_alternatives", ()))
        if not source_alternatives and source_accounting.get(
            "native_exact_type"
        ) is not None:
            source_alternatives = (
                str(source_accounting["native_exact_type"]),
            )
        if not source_alternatives:
            return None
        if any(identity not in target_tags for identity in source_alternatives):
            raise ValueError(
                "native type tag remap loses an exact alternative: "
                f"source={source_alternatives!r}, "
                f"target={target_alternatives!r}"
            )
        if len(source_alternatives) == 1:
            tag = self.fresh_value(
                dtype="int64", transform=CONTROL_CONST,
                operands=(self._canonical_cell(int(value_id)),),
            )
            self.emit(
                Handler.Const, [], tag,
                attributes={
                    "value": int(target_tags[source_alternatives[0]]),
                    "native_type_tag_constant_for": int(value_id),
                },
            )
            return tag
        source_tag = self.native_value_type_tags.get(int(value_id))
        if source_tag is None and source_accounting.get(
            "native_type_tag_value_id"
        ) is not None:
            source_tag = (
                self.external_values.get(int(source_accounting[
                    "native_type_tag_value_id"
                ]))
                or self.ssa_value_objects.get(int(source_accounting[
                    "native_type_tag_value_id"
                ]))
            )
        if source_tag is None:
            presence = self.optional_scalar_presence_by_payload.get(
                int(value_id)
            )
            presence_id = self.source_value_descriptions.get(
                int(value_id), {}
            ).get("optional_presence_value_id")
            if presence is None and presence_id is not None:
                presence = self.external_value(int(presence_id), dtype="bool")
                self.optional_scalar_presence_by_payload[int(value_id)] = (
                    presence
                )
            material_source = tuple(
                identity for identity in source_alternatives
                if identity != "builtins.NoneType"
            )
            if (
                presence is not None
                and "builtins.NoneType" in source_alternatives
                and len(material_source) == 1
            ):
                present_token = self.constant_value(
                    int(target_tags[material_source[0]]), presence,
                )
                absent_token = self.constant_value(
                    int(target_tags["builtins.NoneType"]), presence,
                )
                source_tag = self.fresh_value(
                    dtype="int64", transform=CONTROL_EXPRESSION,
                    operands=(presence, present_token, absent_token),
                )
                self.emit(
                    Handler.Select,
                    [presence, present_token, absent_token], source_tag,
                    attributes={
                        "binding": "program_abi_optional_scalar_type_tag",
                        "payload_value_id": int(value_id),
                    },
                )
                self.native_value_type_tags[int(value_id)] = source_tag
        if source_tag is None:
            return None
        source_tags = dict(
            source_fact.get("tags", ())
            if isinstance(source_fact, Mapping)
            else getattr(source_fact, "tags", ())
        ) or dict(source_accounting.get("native_type_tags", ()))
        if (
            source_alternatives == target_alternatives
            and source_tags == target_tags
        ):
            return source_tag
        remapped = None
        for identity in source_alternatives:
            source_token = self.constant_value(
                int(source_tags[identity]), source_tag,
            )
            target_token = self.constant_value(
                int(target_tags[identity]), source_tag,
            )
            matches = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(source_tag, source_token),
            )
            self.emit(Handler.Eq, [source_tag, source_token], matches)
            if remapped is None:
                remapped = target_token
                continue
            selected = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(matches, target_token, remapped),
            )
            self.emit(
                Handler.Select, [matches, target_token, remapped], selected,
                attributes={"binding": "native_type_tag_remap"},
            )
            remapped = selected
        return remapped

    def post_native_type_tag(
        self, value_id: int, tag: SSAValue, type_fact: Any, *sources: Any,
    ) -> Ref:
        """Publish one companion writer with its exact ABI/value causes."""

        alternatives = tuple(
            type_fact.get("alternatives", ())
            if isinstance(type_fact, Mapping)
            else getattr(type_fact, "alternatives", ())
        )
        tags = tuple(
            type_fact.get("tags", ())
            if isinstance(type_fact, Mapping)
            else getattr(type_fact, "tags", ())
        )
        abi_cell = (
            None if self.lexical_read_scope is None else
            self._book().latest_ref(
                VALUE_TYPE_ABI,
                (self.lexical_read_scope, int(value_id)),
            )
        )
        tag_cell = self._book().latest_ref(
            SSA_VALUE, (self._scope(), int(tag.id)),
        )
        if abi_cell is None or tag_cell is None:
            raise ValueError(
                "native type tag has no ABI/value provenance: "
                f"{self.function_name} value {int(value_id)}"
            )
        return self._book().post(
            VALUE_TYPE_TAG,
            (self._scope(), int(value_id), int(tag.id)),
            ValueTypeTagFact(int(tag.id), alternatives, tags),
            stage=self._stage(),
            provenance=Derived(self._cells(
                abi_cell, tag_cell, *sources,
            )),
            mode=Mode.CONCORD,
        )

    def _native_union_sequence_values(
        self, sequence_id: int,
    ) -> tuple[SSAValue, ...]:
        descriptor = self.sequence_descriptors.get(int(sequence_id))
        if descriptor is None:
            return ()
        child = descriptor.child_table_pool
        member_ids = tuple(dict.fromkeys((
            *descriptor.column_value_ids,
            int(descriptor.length_address_id),
            int(descriptor.capacity_value_id),
            *(() if descriptor.status_address_id is None else (
                int(descriptor.status_address_id),
            )),
            *(() if descriptor.live_flags_value_id is None else (
                int(descriptor.live_flags_value_id),
            )),
            *(() if descriptor.heap_owner_value_id is None else (
                int(descriptor.heap_owner_value_id),
            )),
            *(() if child is None else (
                *map(int, child.column_value_ids),
                int(child.length_value_id), int(child.capacity_value_id),
                int(child.row_stride_value_id),
                *(() if child.shape_value_id is None else (
                    int(child.shape_value_id),
                )),
                *(() if child.rank_value_id is None else (
                    int(child.rank_value_id),
                )),
                *(() if child.shape_stride_value_id is None else (
                    int(child.shape_stride_value_id),
                )),
                *(() if child.status_value_id is None else (
                    int(child.status_value_id),
                )),
                *(() if child.live_flags_value_id is None else (
                    int(child.live_flags_value_id),
                )),
            )),
        )))
        values = tuple(
            self.ssa_value_objects.get(value_id)
            or self.external_values.get(value_id)
            for value_id in member_ids
        )
        if any(value is None for value in values):
            raise ValueError(
                "native union sequence descriptor names an absent physical "
                f"cell: sequence={int(sequence_id)}, members={member_ids!r}"
            )
        return values

    @staticmethod
    def _native_union_sequence_signature(
        descriptor: SSASequenceDescriptor,
    ) -> tuple:
        child = descriptor.child_table_pool
        return (
            tuple(descriptor.column_dtypes),
            tuple(tuple(shape) for shape in descriptor.column_shapes),
            tuple(descriptor.key_columns), bool(descriptor.writable),
            descriptor.status_address_id is not None,
            descriptor.live_flags_value_id is not None,
            descriptor.heap_owner_value_id is not None,
            None if child is None else (
                tuple(child.column_dtypes), tuple(child.key_columns),
                bool(child.writable), child.shape_value_id is not None,
                child.rank_value_id is not None,
                child.shape_stride_value_id is not None,
                child.status_value_id is not None,
                child.live_flags_value_id is not None,
            ),
        )

    def publish_native_value_union(
        self, value_id: int, tag: SSAValue, type_fact: Any,
    ) -> SSAValueUnionDescriptor:
        """Publish the physical row for one semantic union."""

        physical = tuple(
            type_fact.get("physical_alternatives", ())
            if isinstance(type_fact, Mapping)
            else getattr(type_fact, "physical_alternatives", ())
        )
        payloads = self.native_value_union_payloads.get(int(value_id), {})
        sequence_arms = self.native_value_union_sequence_ids.get(
            int(value_id), {}
        )
        material_payloads = tuple(
            tuple(int(value.id) for value in payloads.get(str(arm.identity), ()))
            for arm in physical
            if str(arm.storage) != "none"
        )
        layout = (
            "shared"
            if material_payloads
            and len(set(material_payloads)) == 1
            and not sequence_arms
            else "side-by-side"
        )
        alternatives = []
        for arm in physical:
            identity = str(arm.identity)
            storage = SSAValueUnionStorage(str(arm.storage))
            values = tuple(payloads.get(identity, ()))
            sequence_id = sequence_arms.get(identity)
            if storage is SSAValueUnionStorage.SEQUENCE:
                descriptor = (
                    None if sequence_id is None else
                    self.sequence_descriptors.get(int(sequence_id))
                )
                if descriptor is None and not (
                    sequence_id is None
                    and len(values) == 1
                    and str(values[0].dtype) == "int64"
                    and not tuple(values[0].shape or ())
                ):
                    raise ValueError(
                        "native value union sequence arm has not retained its "
                        "descriptor or native handle: "
                        f"value={int(value_id)}, arm={identity!r}"
                    )
                if descriptor is not None:
                    values = ()
            elif storage is not SSAValueUnionStorage.NONE and not values:
                raise ValueError(
                    "native value union arm has no materialized payload "
                    f"cells: value={int(value_id)}, arm={identity!r}"
                )
            if storage is SSAValueUnionStorage.RECORD:
                raise ValueError(
                    "native value union aggregate arm has not retained its "
                    f"descriptor: value={int(value_id)}, arm={identity!r}"
                )
            if (
                storage is SSAValueUnionStorage.REFERENCE
                and layout != "shared"
                and any(
                not any(
                    instruction.res is not None
                    and int(instruction.res.id) == int(value.id)
                    and instruction.op in {"StaticRef", "static_ref"}
                    and not bool(instruction.attributes.get(
                        "host_resident", True
                    ))
                    for block in self.blocks.values()
                    for instruction in block.instrs
                )
                for value in values
                )
            ):
                raise ValueError(
                    "native value union reference arm lacks an exact native, "
                    "non-host-resident reference descriptor: "
                    f"{identity!r}"
                )
            alternatives.append(SSAValueUnionAlternative(
                name=identity,
                storage=storage,
                dtype=str(arm.dtype or ""),
                shape=tuple(arm.shape or ()),
                value_ids=tuple(value.id for value in values),
                sequence_id=(
                    int(sequence_id)
                    if storage is SSAValueUnionStorage.SEQUENCE
                    and sequence_id is not None else None
                ),
                storage_identity=(
                    None if not arm.storage_identity
                    else repr(tuple(arm.storage_identity))
                ),
            ))
        descriptor = SSAValueUnionDescriptor(
            union_id=int(value_id),
            identity=" | ".join(arm.name for arm in alternatives),
            tag_value_id=int(tag.id),
            alternatives=tuple(alternatives),
            metadata_state="dynamic",
            layout=layout,
        )
        abi_cell = (
            None if self.lexical_read_scope is None else
            self._book().latest_ref(
                VALUE_TYPE_ABI,
                (self.lexical_read_scope, int(value_id)),
            )
        )
        type_tag_cell = self._book().latest_ref(
            VALUE_TYPE_TAG, (self._scope(), int(value_id), int(tag.id)),
        )
        if abi_cell is None or type_tag_cell is None:
            raise ValueError(
                "native value union has no exact ABI/tag concordance cells: "
                f"{self.function_name} value {int(value_id)}"
            )
        self.value_union_table.register(
            descriptor,
            sources=self._cells(
                abi_cell, tag,
                *(value for values in payloads.values() for value in values),
                *(
                    value
                    for sequence_id in sequence_arms.values()
                    for value in self._native_union_sequence_values(
                        int(sequence_id)
                    )
                ),
            ),
            stage=self._stage(),
        )
        states = tuple((
            tuple(arm.shape), str(arm.dtype), int(arm.rank),
            str(arm.metadata_state),
            None if arm.row_shape is None else tuple(arm.row_shape),
        ) for arm in physical)
        union_sources = self._cells(
            abi_cell, type_tag_cell, tag,
            *(cell for arm in physical for cell in arm.source_cells),
            *(value for values in payloads.values() for value in values),
            *(
                value
                for sequence_id in sequence_arms.values()
                for value in self._native_union_sequence_values(
                    int(sequence_id)
                )
            ),
        )
        if not union_sources:
            raise ValueError(
                "native value union state has no exact ABI/tag provenance: "
                f"{self.function_name} value {int(value_id)}"
            )
        self._book().post(
            UNION_ALTERNATIVE_STATE,
            (self._scope(), int(value_id)),
            UnionAlternativeStateFact(
                tuple(arm.name for arm in alternatives), int(tag.id), states,
            ),
            stage=self._stage(), provenance=Derived(union_sources),
            mode=Mode.REVISE,
        )
        for position, (physical_arm, descriptor_arm) in enumerate(zip(
            physical, alternatives, strict=True,
        )):
            arm_state = (
                tuple(physical_arm.shape), str(physical_arm.dtype),
                int(physical_arm.rank), str(physical_arm.metadata_state),
                None if physical_arm.row_shape is None
                else tuple(physical_arm.row_shape),
            )
            arm_scope = (
                *tuple(self.shape_scope), "value_union",
                int(value_id), str(descriptor_arm.name),
            )
            for payload_id in descriptor_arm.value_ids:
                payload = self.ssa_value_objects.get(int(payload_id))
                record_shape_transformation(
                    arm_scope, int(value_id), self.shape_scope,
                    int(payload_id), stage=UNION_PROJECTION,
                    operation="value_union_projection",
                    source_state=arm_state, target_state=arm_state,
                    role=f"alternative:{position}",
                    source_cells=self._cells(
                        abi_cell, tag, payload,
                        *physical_arm.source_cells,
                    ),
                )
            if descriptor_arm.sequence_id is not None:
                sequence_id = int(descriptor_arm.sequence_id)
                record_shape_transformation(
                    arm_scope, int(value_id), self.shape_scope, sequence_id,
                    stage=UNION_PROJECTION,
                    operation="value_union_sequence_projection",
                    source_state=arm_state, target_state=arm_state,
                    role=f"alternative:{position}",
                    source_cells=self._cells(
                        abi_cell, tag,
                        *self._native_union_sequence_values(sequence_id),
                        *physical_arm.source_cells,
                    ),
                )
        return descriptor

    def merge_native_type_tags(
        self,
        result_source_id: int,
        result: SSAValue,
        incoming_source_ids: tuple[int, ...],
        incoming_blocks: tuple[str, ...],
        *,
        binding: str,
    ) -> SSAValue | None:
        """Emit the companion Phi for one authored payload Phi.

        The result's VALUE_TYPE_ABI row supplies the only accepted table.
        Each incoming tag is forwarded, folded, or explicitly remapped by
        :meth:`native_type_tag_for`; thus loops and N-way state joins preserve
        the same identity evidence as ordinary two-arm conditionals.
        """

        fact = self.native_value_type_abi.get(int(result_source_id))
        alternatives = tuple(
            fact.get("alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "alternatives", ())
        )
        if len(alternatives) <= 1:
            return None
        publication_id = int(result.id)
        incoming_tags_list = []
        merge_block = self.current
        for value_id, block_name in zip(
            incoming_source_ids, incoming_blocks, strict=True,
        ):
            # Exact arms and tag-table remaps emit constants/comparisons.
            # A Phi consumes each of those on its predecessor edge, so the
            # companion computation belongs in that predecessor, not in the
            # merge block beside the Phi which reads it.
            self.current = self.blocks[str(block_name)]
            incoming_tags_list.append(
                self.native_type_tag_for(int(value_id), fact)
            )
        self.current = merge_block
        incoming_tags = tuple(incoming_tags_list)
        if any(value is None for value in incoming_tags):
            raise ValueError(
                "native union Phi has an incoming value without exact type "
                f"evidence: result={int(result_source_id)}, "
                f"incoming={incoming_source_ids!r}, binding={binding!r}"
            )
        tags = tuple(
            fact.get("tags", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "tags", ())
        )
        physical = tuple(
            fact.get("physical_alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "physical_alternatives", ())
        )
        if tuple(str(arm.identity) for arm in physical) != alternatives:
            raise ValueError(
                "native union Phi has no exact per-alternative physical ABI: "
                f"result={int(result_source_id)}, alternatives={alternatives!r}, "
                f"physical={tuple(str(arm.identity) for arm in physical)!r}"
            )
        merged = self.pending_loop_native_type_tags.pop(
            int(result_source_id), None,
        )
        if merged is None:
            merged = self.fresh_value(
                dtype="int64", transform=PHI_CONDITIONAL,
                operands=tuple(incoming_tags),
            )
        else:
            merged.dtype = "int64"
            merged.accounting.pop(
                "native_type_tag_pending_loop_update", None,
            )
        merged.accounting.update({
            "native_type_tag_for_value_id": publication_id,
            "native_type_alternatives": alternatives,
            "native_type_tags": tags,
        })
        self.emit(
            Handler.Phi, list(incoming_tags), merged,
            attributes={
                "incoming_blocks": tuple(incoming_blocks),
                "binding": str(binding),
                "native_type_tag_phi": True,
                "payload_value_id": int(result.id),
                "source_value_id": publication_id,
            },
        )
        self.native_type_tag_phi_by_payload[int(result.id)] = (
            self.current.instrs[-1]
        )
        material = tuple(
            arm for arm in physical if str(arm.storage) != "none"
        )
        shared_payload = bool(material) and len({
            (
                str(arm.storage), str(arm.dtype), tuple(arm.shape or ()),
                int(arm.rank), tuple(arm.storage_identity or ()),
                str(arm.metadata_state),
                None if arm.row_shape is None else tuple(arm.row_shape),
            )
            for arm in material
        }) == 1 and all(
            str(arm.storage) not in {"sequence", "record"}
            for arm in material
        )
        pending_payloads = self.pending_loop_native_union_payloads.get(
            int(result_source_id), {},
        )
        merged_payloads: dict[str, tuple[SSAValue, ...]] = {}
        for arm in physical:
            identity = str(arm.identity)
            if str(arm.storage) == "none":
                merged_payloads[identity] = ()
                continue
            if shared_payload:
                # The authored payload Phi already transports the one common
                # physical slot.  Only its companion tag selects the arm.
                merged_payloads[identity] = (result,)
                continue
            if str(arm.storage) == "sequence":
                # Aggregate arms cross a conditional as fixed-width native
                # descriptor handles.  A locally resident sequence contributes
                # its descriptor id; a call-boundary result already is the
                # declared handle word.  Inactive arms contribute zero and the
                # companion tag prevents that sentinel from being observed.
                incoming_handles = []
                for source_id, block_name in zip(
                    incoming_source_ids, incoming_blocks,
                ):
                    retained_payload = self.native_value_union_payloads.get(
                        int(source_id), {},
                    ).get(identity)
                    if retained_payload is not None:
                        if len(retained_payload) != 1:
                            raise ValueError(
                                "native sequence union arm has non-scalar "
                                f"handle cells: {identity!r} -> "
                                f"{retained_payload!r}"
                            )
                        incoming_handles.append(retained_payload[0])
                        continue
                    source_fact = self.native_value_type_abi.get(int(source_id))
                    source_alternatives = tuple(
                        source_fact.get("alternatives", ())
                        if isinstance(source_fact, Mapping)
                        else getattr(source_fact, "alternatives", ())
                    )
                    prior = self.current
                    self.current = self.blocks[str(block_name)]
                    if identity not in source_alternatives:
                        handle = self.fresh_value(
                            dtype="int64", transform=CONTROL_CONST,
                            operands=(self._canonical_cell(int(source_id)),),
                        )
                        self.emit(
                            Handler.Const, [], handle,
                            attributes={
                                "value": 0,
                                "native_value_union_inactive_arm": identity,
                            },
                        )
                    else:
                        retained_sequence = (
                            self.native_value_union_sequence_ids.get(
                                int(source_id), {}
                            ).get(identity)
                        )
                        resident_id = self._concorded_resident(int(source_id))
                        if (
                            retained_sequence is None
                            and resident_id in self.sequence_descriptors
                        ):
                            retained_sequence = resident_id
                        if retained_sequence is not None:
                            handle = self.fresh_value(
                                dtype="int64", transform=CONTROL_CONST,
                                operands=(self._canonical_cell(int(source_id)),),
                            )
                            self.emit(
                                Handler.Const, [], handle,
                                attributes={
                                    "value": int(retained_sequence),
                                    "native_sequence_descriptor_handle_for": int(
                                        source_id
                                    ),
                                    "native_value_union_alternative": identity,
                                },
                            )
                        else:
                            source_handle = (
                                self.external_values.get(int(source_id))
                                or self.ssa_value_objects.get(int(source_id))
                                or self.external_value(int(source_id))
                            )
                            if str(source_handle.dtype) == "int64" and not tuple(
                                source_handle.shape or ()
                            ):
                                handle = source_handle
                            else:
                                handle = self.fresh_value(
                                    dtype="int64", transform=CONTROL_CAST,
                                    operands=(source_handle,),
                                )
                                self.emit(
                                    Handler.Cast, [source_handle], handle,
                                    attributes={
                                        "binding": (
                                            "native_sequence_descriptor_handle"
                                        ),
                                        "source_value_id": int(source_id),
                                        "native_value_union_alternative": identity,
                                    },
                                )
                    self.current = prior
                    incoming_handles.append(handle)
                retained_result = pending_payloads.get(identity)
                merged_handle = (
                    retained_result[0]
                    if retained_result is not None
                    and len(retained_result) == 1
                    else self.fresh_value(
                        dtype="int64", transform=PHI_CONDITIONAL,
                        operands=tuple(incoming_handles),
                    )
                )
                merged_handle.dtype = "int64"
                merged_handle.accounting.pop(
                    "native_union_payload_pending_loop_update", None,
                )
                self.emit(
                    Handler.Phi, incoming_handles, merged_handle,
                    attributes={
                        "incoming_blocks": tuple(incoming_blocks),
                        "binding": f"{binding}_native_value_union_{identity}",
                        "native_value_union_alternative": identity,
                        "descriptor_handle_transport": True,
                        "source_value_id": publication_id,
                    },
                )
                merged_payloads[identity] = (merged_handle,)
                continue
            if str(arm.storage) == "record":
                raise ValueError(
                    "native union aggregate Phi requires descriptor-backed "
                    f"arm transport: value={int(result_source_id)}, "
                    f"arm={identity!r}"
                )
            incoming_payloads = []
            for source_id, block_name in zip(
                incoming_source_ids, incoming_blocks,
            ):
                source_payloads = self.native_value_union_payloads.get(
                    int(source_id), {}
                ).get(identity)
                if source_payloads is None:
                    source_fact = self.native_value_type_abi.get(int(source_id))
                    source_alternatives = tuple(
                        source_fact.get("alternatives", ())
                        if isinstance(source_fact, Mapping)
                        else getattr(source_fact, "alternatives", ())
                    )
                    if source_alternatives == (identity,):
                        source_value = (
                            self.external_values.get(int(source_id))
                            or self.ssa_value_objects.get(int(source_id))
                        )
                        if source_value is None:
                            source_value = self.external_value(int(source_id))
                        source_payloads = (source_value,)
                    else:
                        prior = self.current
                        self.current = self.blocks[str(block_name)]
                        inactive = self.fresh_value(
                            dtype=str(arm.dtype or "unknown"),
                            shape=tuple(arm.shape or ()),
                            transform=CONTROL_CONST,
                            operands=(self._canonical_cell(int(source_id)),),
                        )
                        self.emit(
                            Handler.Const, [], inactive,
                            attributes={
                                "value": 0,
                                "native_value_union_inactive_arm": identity,
                            },
                        )
                        self.current = prior
                        source_payloads = (inactive,)
                if len(source_payloads) != 1:
                    raise ValueError(
                        "native scalar/span union arm has non-scalar payload "
                        f"cells: {identity!r} -> {source_payloads!r}"
                    )
                incoming_payloads.append(source_payloads[0])
            retained_result = pending_payloads.get(identity)
            merged_arm = (
                retained_result[0]
                if retained_result is not None and len(retained_result) == 1
                else self.fresh_value(
                    dtype=str(
                        arm.dtype or incoming_payloads[0].dtype or "unknown"
                    ),
                    shape=tuple(arm.shape or incoming_payloads[0].shape or ()),
                    transform=PHI_CONDITIONAL,
                    operands=tuple(incoming_payloads),
                )
            )
            merged_arm.dtype = str(
                arm.dtype or incoming_payloads[0].dtype or "unknown"
            )
            merged_arm.shape = tuple(
                arm.shape or incoming_payloads[0].shape or ()
            )
            merged_arm.accounting.pop(
                "native_union_payload_pending_loop_update", None,
            )
            self.emit(
                Handler.Phi, incoming_payloads, merged_arm,
                attributes={
                    "incoming_blocks": tuple(incoming_blocks),
                    "binding": f"{binding}_native_value_union_{identity}",
                    "native_value_union_alternative": identity,
                    "source_value_id": publication_id,
                },
            )
            merged_payloads[identity] = (merged_arm,)
        for source_id, source_tag in zip(
            incoming_source_ids, incoming_tags, strict=True,
        ):
            source_fact = self.native_value_type_abi.get(int(source_id))
            source_physical = tuple(
                source_fact.get("physical_alternatives", ())
                if isinstance(source_fact, Mapping)
                else getattr(source_fact, "physical_alternatives", ())
            )
            target_by_identity = {
                str(arm.identity): arm for arm in physical
            }
            target_position = {
                str(arm.identity): position
                for position, arm in enumerate(physical)
            }
            for source_arm in source_physical:
                identity = str(source_arm.identity)
                target_arm = target_by_identity.get(identity)
                if target_arm is None:
                    raise ValueError(
                        "native union injection loses an exact source arm: "
                        f"result={int(result_source_id)}, source={int(source_id)}, "
                        f"arm={identity!r}"
                    )
                source_state = (
                    tuple(source_arm.shape), str(source_arm.dtype),
                    int(source_arm.rank), str(source_arm.metadata_state),
                    None if source_arm.row_shape is None
                    else tuple(source_arm.row_shape),
                )
                target_state = (
                    tuple(target_arm.shape), str(target_arm.dtype),
                    int(target_arm.rank), str(target_arm.metadata_state),
                    None if target_arm.row_shape is None
                    else tuple(target_arm.row_shape),
                )
                if source_state != target_state:
                    raise ValueError(
                        "native union injection changes an alternative's "
                        f"physical shape state: {identity!r}: "
                        f"{source_state!r} != {target_state!r}"
                    )
                arm_scope = (
                    *tuple(self.shape_scope), "value_union",
                    publication_id, identity,
                )
                if int(source_id) in self.pending_loop_native_type_tags:
                    # The loop header may use the backedge's exact ABI before
                    # the body defines its value.  Its physical state is
                    # knowable, but its shape-transformation source is not yet
                    # resident.  Publish that edge when the reserved body tag
                    # is claimed, rather than immediately invalidating it when
                    # the definition arrives.
                    self.pending_loop_native_union_injections.setdefault(
                        int(source_id), [],
                    ).append((
                        arm_scope, publication_id, identity,
                        source_state, target_state,
                        f"alternative:{target_position[identity]}",
                    ))
                    continue
                record_shape_transformation(
                    self.shape_scope, int(source_id), arm_scope,
                    publication_id, stage=UNION_INJECTION,
                    operation="value_union_injection",
                    source_state=source_state, target_state=target_state,
                    role=f"alternative:{target_position[identity]}",
                    source_cells=self._cells(
                        source_tag, *source_arm.source_cells,
                    ),
                )
        if publication_id != int(result_source_id):
            source_abi_cell = (
                None if self.lexical_read_scope is None else
                self._book().latest_ref(
                    VALUE_TYPE_ABI,
                    (self.lexical_read_scope, int(result_source_id)),
                )
            )
            if source_abi_cell is None:
                raise ValueError(
                    "native union Phi result has no source ABI cell: "
                    f"result={publication_id}, "
                    f"source={int(result_source_id)}"
                )
            self._book().post(
                VALUE_TYPE_ABI,
                (self.lexical_read_scope, publication_id),
                fact,
                stage=self._stage(),
                provenance=Derived(self._cells(
                    source_abi_cell,
                    result,
                    *(
                        cell
                        for arm in fact.physical_alternatives
                        for cell in arm.source_cells
                    ),
                )),
                mode=Mode.CONCORD,
            )
            self.native_value_type_abi[publication_id] = fact
        self.native_value_union_payloads[int(result_source_id)] = merged_payloads
        self.native_value_union_payloads[publication_id] = merged_payloads
        self.pending_loop_native_union_payloads.pop(
            int(result_source_id), None,
        )
        result.accounting = {
            **dict(result.accounting or {}),
            "native_type_tag_value_id": int(merged.id),
            "native_type_alternatives": alternatives,
        }
        self.native_value_type_tags[int(result_source_id)] = merged
        self.native_value_type_tags[int(result.id)] = merged
        self.post_native_type_tag(
            publication_id, merged, fact, result, *incoming_tags,
        )
        self.publish_native_value_union(publication_id, merged, fact)
        pending_injections = self.pending_loop_native_union_injections.pop(
            int(result_source_id), (),
        )
        if pending_injections:
            source_by_identity = {
                str(arm.identity): arm for arm in physical
            }
            for (
                arm_scope, target_id, identity,
                source_state, target_state, role,
            ) in pending_injections:
                source_arm = source_by_identity[identity]
                record_shape_transformation(
                    self.shape_scope, int(result_source_id),
                    arm_scope, int(target_id), stage=UNION_INJECTION,
                    operation="value_union_injection",
                    source_state=source_state, target_state=target_state,
                    role=role,
                    source_cells=self._cells(
                        merged, *source_arm.source_cells,
                    ),
                )
        return merged

    def reserve_loop_native_union_update(
        self, value_id: int, value: SSAValue,
    ) -> None:
        """Reserve exact local union companions for a future loop backedge.

        Loop payload Phis are installed before their body is lowered.  Their
        authored update therefore has an ABI row but no SSA definition yet.
        Reserve the tag and any side-by-side arm payloads under that authored
        identity; the body's ordinary union merge claims these same objects.
        """

        value_id = int(value_id)
        fact = self.native_value_type_abi.get(value_id)
        alternatives = tuple(
            fact.get("alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "alternatives", ())
        )
        if len(alternatives) <= 1 or value_id in self.native_value_type_tags:
            return
        physical = tuple(
            fact.get("physical_alternatives", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "physical_alternatives", ())
        )
        if tuple(str(arm.identity) for arm in physical) != alternatives:
            raise ValueError(
                "loop-carried native union has no exact ordered physical "
                f"arms: value={value_id}, alternatives={alternatives!r}"
            )
        tags = tuple(
            fact.get("tags", ())
            if isinstance(fact, Mapping)
            else getattr(fact, "tags", ())
        )
        tag = self.fresh_value(
            dtype="int64", transform=PHI_LOOP_HEADER,
            operands=(self._canonical_cell(value_id), value),
        )
        tag.accounting.update({
            "native_type_tag_pending_loop_update": value_id,
            "native_type_alternatives": alternatives,
            "native_type_tags": tags,
        })
        self.pending_loop_native_type_tags[value_id] = tag
        self.native_value_type_tags[value_id] = tag
        value.accounting.update({
            "native_type_tag_value_id": int(tag.id),
            "native_type_alternatives": alternatives,
        })

        material = tuple(
            arm for arm in physical if str(arm.storage) != "none"
        )
        shared_payload = bool(material) and len({
            (
                str(arm.storage), str(arm.dtype), tuple(arm.shape or ()),
                int(arm.rank), tuple(arm.storage_identity or ()),
                str(arm.metadata_state),
                None if arm.row_shape is None else tuple(arm.row_shape),
            )
            for arm in material
        }) == 1 and all(
            str(arm.storage) not in {"sequence", "record"}
            for arm in material
        )
        payloads: dict[str, tuple[SSAValue, ...]] = {}
        for arm in physical:
            identity = str(arm.identity)
            storage = str(arm.storage)
            if storage == "none":
                payloads[identity] = ()
            elif shared_payload:
                payloads[identity] = (value,)
            elif storage == "record":
                raise ValueError(
                    "loop-carried native union record arm requires its "
                    f"descriptor-backed frame: value={value_id}, "
                    f"arm={identity!r}"
                )
            else:
                payload = self.fresh_value(
                    dtype=("int64" if storage == "sequence" else str(
                        arm.dtype or "unknown"
                    )),
                    shape=(() if storage == "sequence" else tuple(
                        arm.shape or ()
                    )),
                    transform=PHI_LOOP_HEADER,
                    operands=(self._canonical_cell(value_id), value),
                )
                payload.accounting.update({
                    "native_union_payload_pending_loop_update": value_id,
                    "native_value_union_alternative": identity,
                })
                payloads[identity] = (payload,)
        self.pending_loop_native_union_payloads[value_id] = payloads
        self.native_value_union_payloads[value_id] = payloads

    def _emit_native_value_type_test(self, value_id):
        """Lower a concorded authored ``isinstance`` to integer SSA only."""

        source = self.native_value_type_tests[int(value_id)]
        result = self.produced_value(
            int(value_id), dtype="bool",
            claim_provisional_definition=True,
            cause=tuple(filter(None, (
                source.get("intrinsic_cell"),
                source.get("target_definition_cell"),
                *tuple(source.get("target_expectation_cells") or ()),
            ))),
        )
        if str(source.get("predicate_kind")) == "dynamic_subtype":
            self._native_dynamic_type_predicate(
                int(source["subject_value_id"]),
                int(source["target_value_id"]),
                source["target_types"],
                result_override=result,
                receipt=dict(source),
            )
            return
        self._native_value_type_predicate(
            int(source["subject_value_id"]), source["accepted_types"],
            result_override=result,
            subtype=str(source.get("predicate_kind")) == "subtype",
            receipt=dict(source),
        )

    def _emit_native_object_constructor(self, mutation, *, location):
        from .ssa_object_operations import object_call
        context = self.native_object_context
        module = self.native_object_module
        bindings = self._native_object_bindings()
        kind = str(mutation.argument_kind)
        from .ssa_object_context import object_source_contract
        accepted = object_source_contract(mutation.object_contract_cell, book=self._book())
        members = tuple(accepted['member_value_ids'])
        if (kind not in context.kind_vocabulary or accepted['kind'] != kind
                or members != mutation.argument_value_ids
                or accepted['source_value_id'] != mutation.sequence_value_id):
            raise ValueError(f'{location}: source object constructor contract disagrees')
        helper = next(function for function in module.functions.values()
            if function.metadata.get('opaque_object_helper', {}).get('operation') == 'construct')
        token = self.fresh_value(dtype='int64', transform=CONTROL_CONST,
                                 operands=(int(mutation.sequence_value_id),))
        self.emit(Handler.Const, [], token,
                  attributes={'value': context.kind_vocabulary.index(kind) + 1})
        result = self.produced_value(int(mutation.sequence_value_id), dtype='opaque_ref',
            claim_provisional_definition=True, cause=(token, mutation.object_contract_cell))
        result.accounting.update(native_object_storage_identity=context.storage_identity,
                                 native_object_source_kind=kind)
        operand_id, = helper.metadata['opaque_object_helper']['operand_formal_ids']
        instruction = object_call(module, helper.name, None, context=bindings,
            operands={operand_id: token}, result=result)
        instruction.attributes.update(source_object_constructor={**accepted,
            'source_value_id': int(mutation.sequence_value_id),
            'source_node_id': int(mutation.effect_node_id),
            'kind': kind, 'initial_extent': 0,
            'context': context.to_mapping(), 'contract_cell': mutation.object_contract_cell,
            'member_value_ids': members})
        self.emit(Handler.Call, instruction.args, instruction.res, attributes=instruction.attributes)
        self.native_object_constructor_receipts.append(instruction.attributes['source_object_constructor'])
        for position, member_id in enumerate(members, 1):
            member = self.external_value(member_id)
            if member.dtype != 'opaque_ref' or member.shape:
                raise ValueError(f'{location}: tuple member has no accepted reference layout')
            ordinal = self.fresh_value(dtype='int64', transform=CONTROL_CONST,
                                   operands=(mutation.object_contract_cell,))
            self.emit(Handler.Const, [], ordinal, attributes={'value': position})
            key = self.fresh_value(dtype='opaque_ref', transform=CONTROL_EXPRESSION, operands=(ordinal,))
            self.emit(Handler.Cast, [ordinal], key, attributes={'binding': 'object_context_position'})
            self._emit_native_object_operation('set', result.id, (key, member), None)

    def _emit_native_object_materialization(self, mutation, *, location):
        context = self.native_object_context
        kind = str(mutation.argument_kind)
        if context is None or kind not in context.kind_vocabulary or len(mutation.argument_value_ids) != 1:
            raise ValueError(f'{location}: source materialization has no admitted kind/source')
        token = self.fresh_value(dtype='int64', transform=CONTROL_CONST,
            operands=(int(mutation.sequence_value_id),))
        self.emit(Handler.Const, [], token,
            attributes={'value': context.kind_vocabulary.index(kind) + 1})
        source, = mutation.argument_value_ids
        operation = 'materialize_frozen' if kind == 'builtins.frozenset' else 'materialize'
        result = self._emit_native_object_operation(operation, int(source),
            (token,), int(mutation.sequence_value_id))
        result.accounting.update(native_object_storage_identity=context.storage_identity,
                                 native_object_source_kind=kind)
        self.current.instrs[-1].attributes['source_object_materialization'] = {
            'source_value_id': int(mutation.sequence_value_id),
            'source_node_id': int(mutation.effect_node_id),
            'input_value_id': int(source), 'kind': kind, 'context': context.to_mapping()}

    def _lower_sequence_mutation_body(
        self,
        mutation: ControlSequenceMutation,
        *,
        path: str,
    ) -> None:
        operation = str(mutation.operator)
        location = f"{path}.sequence_mutation[{mutation.effect_node_id}]"
        if operation == "slice":
            # ``dst = src[lower:upper]`` (resident_sequence_materialization.
            # _source_sequence_slices): reset, then the clipped append.
            source_id, *bound_ids = map(int, mutation.argument_value_ids)
            _kind, *spellings = str(mutation.argument_kind).split(":")
            if (
                _kind != "slice" or len(spellings) != 2
                or sum(item.startswith("v") for item in spellings)
                != len(bound_ids)
                or any(item[:1] not in {"", "v", "c"} for item in spellings)
            ):
                raise ValueError(
                    f"{location}: slice bounds {bound_ids!r} do not match "
                    f"{mutation.argument_kind!r}"
                )
            values = iter(bound_ids)
            bounds = [
                None if not item
                else ("value", next(values)) if item.startswith("v")
                else ("literal", int(item[1:]))
                for item in spellings
            ]
            self._emit_sequence_reset(int(mutation.sequence_value_id))
            self._emit_sequence_append_slice(
                int(mutation.sequence_value_id), source_id,
                *(bound[1] if bound and bound[0] == "value" else None
                  for bound in bounds),
                lower_literal=(bounds[0][1] if bounds[0] and bounds[0][0] == "literal" else None),
                upper_literal=(bounds[1][1] if bounds[1] and bounds[1][0] == "literal" else None),
            )
            return
        if operation in {"sort", "sorted"} and mutation.source_contract_cell is None:
            raise ValueError(
                f"{location}: native sort has no exact source contract"
            )
        if mutation.source_contract_cell is not None:
            from .concordance_declarations import (
                SOURCE_GLYPH_SEQUENCE,
                SOURCE_OPTIONAL_GLYPH_CARRY,
                SOURCE_SORT_CONTRACT,
                SourceGlyphSequence,
                SourceOptionalGlyphCarry,
                SourceSortContract,
            )

            cell = mutation.source_contract_cell
            glyph_page = self._book().registry.pages.get(
                SOURCE_GLYPH_SEQUENCE.name
            )
            optional_page = self._book().registry.pages.get(
                SOURCE_OPTIONAL_GLYPH_CARRY.name
            )
            sort_page = self._book().registry.pages.get(
                SOURCE_SORT_CONTRACT.name
            )
            if getattr(cell, "page", None) not in {
                glyph_page, optional_page, sort_page,
            }:
                raise ValueError(
                    f"{location}: sequence source cell is not a resident "
                    "sequence contract"
                )
            fact = self._book().page(cell.page).cell(cell.row, cell.column)
            if isinstance(fact, SourceSortContract):
                expected_arguments = tuple(map(int, fact.argument_value_ids))
                expected_kind = str(fact.argument_kind)
                authored_operation = str(fact.operation)
                if authored_operation == "sorted":
                    if fact.source_value_id is None:
                        raise ValueError(
                            f"{location}: sorted contract has no source value"
                        )
                common = (
                    int(cell.row[1]) == int(mutation.effect_node_id)
                    and fact.destination_value_id is not None
                    and int(fact.destination_value_id)
                    == int(mutation.sequence_value_id)
                    and str(fact.policy) == str(mutation.policy)
                )
                if authored_operation == "sorted" and operation == "replace":
                    admitted = (
                        common
                        and tuple(map(int, mutation.argument_value_ids))
                        == (int(fact.source_value_id),)
                    )
                elif authored_operation == "sorted" and operation == "sort":
                    admitted = (
                        common
                        and tuple(map(int, mutation.argument_value_ids))
                        == expected_arguments
                        and str(mutation.argument_kind) == expected_kind
                        and fact.key_column == mutation.sort_key_column
                        and bool(fact.reverse) == bool(mutation.sort_reverse)
                    )
                else:
                    if authored_operation == "sorted":
                        expected_arguments = (
                            int(fact.source_value_id), *expected_arguments,
                        )
                        expected_kind = f"sorted_{expected_kind}"
                    admitted = (
                        common
                        and authored_operation == operation
                        and expected_arguments
                        == tuple(map(int, mutation.argument_value_ids))
                        and expected_kind == str(mutation.argument_kind)
                        and fact.key_column == mutation.sort_key_column
                        and bool(fact.reverse) == bool(mutation.sort_reverse)
                    )
            elif isinstance(fact, SourceGlyphSequence):
                destination_id = int(cell.row[1])
                def glyph_tree(component):
                    yield component
                    for child in component.projection_components:
                        yield from glyph_tree(child)
                all_components = tuple(
                    component
                    for root in fact.components
                    for component in glyph_tree(root)
                )
                component_ids = {
                    int(
                        component.formatted_sequence_value_id
                        if component.formatted_sequence_value_id is not None
                        else component.component_value_id
                    )
                    for component in all_components
                }
                token_components = {
                    (
                        int(component.component_value_id),
                        int(
                            component.projection_source_value_id
                            if component.projection_source_value_id is not None
                            else component.operand_value_id
                        ),
                    )
                    for component in all_components
                    if str(component.kind) == "formatted"
                    and str(component.projection_kind) in {
                        "string_token", "enum_name",
                    }
                    and component.operand_value_id is not None
                    and component.formatted_sequence_value_id is None
                }
                projection_destinations = {
                    int(component.component_value_id): {
                        int(
                            child.formatted_sequence_value_id
                            if child.formatted_sequence_value_id is not None
                            else child.component_value_id
                        )
                        for child in component.projection_components
                    }
                    for component in all_components
                    if component.projection_components
                }
                union_destinations = {
                    int(component.component_value_id): (
                        int(component.operand_value_id),
                        tuple(
                            (
                                str(arm.identity),
                                int(arm.sequence_value_id),
                                tuple(arm.source_cells),
                            )
                            for arm in component.union_alternatives
                        ),
                    )
                    for component in all_components
                    if component.union_alternatives
                    and component.operand_value_id is not None
                }
                union_contract = union_destinations.get(
                    int(mutation.sequence_value_id)
                )
                admitted = (
                    operation == "clear"
                    and int(mutation.sequence_value_id) == destination_id
                    and not mutation.argument_value_ids
                    or operation == "extend"
                    and int(mutation.sequence_value_id) == destination_id
                    and len(mutation.argument_value_ids) == 1
                    and int(mutation.argument_value_ids[0]) in component_ids
                    or operation == "clear"
                    and int(mutation.sequence_value_id)
                    in projection_destinations
                    and not mutation.argument_value_ids
                    or operation == "extend"
                    and int(mutation.sequence_value_id)
                    in projection_destinations
                    and len(mutation.argument_value_ids) == 1
                    and int(mutation.argument_value_ids[0])
                    in projection_destinations[
                        int(mutation.sequence_value_id)
                    ]
                    or operation == "glyph_token_lookup_copy"
                    and len(mutation.argument_value_ids) == 2
                    and (
                        int(mutation.sequence_value_id),
                        int(mutation.argument_value_ids[0]),
                    ) in token_components
                    or operation == "glyph_union_select"
                    and str(mutation.argument_kind)
                    == "value_union_glyph_projection"
                    and union_contract is not None
                    and tuple(map(int, mutation.argument_value_ids)) == (
                        int(union_contract[0]),
                        *(
                            int(sequence_id)
                            for _identity, sequence_id, _sources
                            in union_contract[1]
                        ),
                    )
                    or operation == "replace"
                    and str(mutation.argument_kind)
                    == "value_union_glyph_arm"
                    and union_contract is not None
                    and len(mutation.argument_value_ids) == 1
                    and int(mutation.argument_value_ids[0]) in {
                        int(sequence_id)
                        for _identity, sequence_id, _sources
                        in union_contract[1]
                    }
                )
            elif isinstance(fact, SourceOptionalGlyphCarry):
                destination_id = int(fact.payload_sequence_value_id)
                arms = tuple(arm for arm in (
                    fact.true_arm, fact.false_arm, fact.initial_arm,
                ) if arm is not None)
                present_sources = {
                    int(arm.sequence_value_id)
                    for arm in arms if arm.sequence_value_id is not None
                }
                admitted = (
                    int(mutation.sequence_value_id) == destination_id
                    and (
                        operation == "clear"
                        and not mutation.argument_value_ids
                        and any(arm.presence is False for arm in arms)
                        or operation == "replace"
                        and len(mutation.argument_value_ids) == 1
                        and int(mutation.argument_value_ids[0])
                        in present_sources
                    )
                )
            else:
                admitted = False
            if not admitted:
                raise ValueError(
                    f"{location}: mutation differs from its source contract"
                )
        if operation == "glyph_token_lookup_copy":
            from .concordance_declarations import STRING_GLYPH_VOCABULARY

            vocabulary_cell = mutation.vocabulary_contract_cell
            vocabulary_row = (
                None if vocabulary_cell is None
                else tuple(vocabulary_cell.row)
            )
            # Control blocks can cross the live-tile/pickle boundary after
            # this Ref is minted.  Page objects are schema values there, so
            # object identity is not the cell identity.  Resolve the retained
            # row through the active book and require the complete canonical
            # key (page name, row, column) to agree.  Unit 038 carried the
            # exact vocabulary fact but the old ``is`` test rejected its
            # rehydrated Page instance before consulting that fact.
            canonical_vocabulary_cell = (
                None if vocabulary_row is None
                else self._book().latest_ref(
                    STRING_GLYPH_VOCABULARY, vocabulary_row,
                )
            )
            if (
                vocabulary_cell is None
                or canonical_vocabulary_cell is None
                or vocabulary_cell.key != canonical_vocabulary_cell.key
                or len(mutation.argument_value_ids) != 2
                or int(vocabulary_cell.row[1])
                != int(mutation.argument_value_ids[1])
            ):
                raise ValueError(
                    f"{location}: token projection has no exact vocabulary"
                )
        if operation == 'object_identity_reduce':
            from .ssa_object_context import object_source_contract
            accepted = object_source_contract(mutation.object_contract_cell, book=self._book())
            if (mutation.sequence_value_id != accepted['result_value_id']
                    or mutation.argument_value_ids != accepted['source_value_ids']):
                raise ValueError(f'{location}: identity reduction differs from its concordance edges')
            left, right = accepted['source_value_ids']
            self._emit_native_object_operation('identity_all', left, (right,), accepted['result_value_id'])
            self.current.instrs[-1].attributes['source_object_identity_reduction'] = {'contract_cell': mutation.object_contract_cell}
            return
        if operation == 'object_construct':
            self._emit_native_object_constructor(mutation, location=location)
            return
        if operation == 'object_materialize':
            self._emit_native_object_materialization(mutation, location=location)
            return
        if operation == 'object_update':
            from .ssa_object_context import object_source_contract
            accepted = object_source_contract(mutation.object_contract_cell, book=self._book())
            if (mutation.sequence_value_id != accepted['destination_value_id']
                    or mutation.argument_value_ids != (accepted['source_value_id'],)):
                raise ValueError(f'{location}: update differs from its authoritative concordance cell')
            self._emit_native_object_operation(accepted['operation'], mutation.sequence_value_id, mutation.argument_value_ids, None)
            self.current.instrs[-1].attributes['source_object_update'] = {'contract_cell': mutation.object_contract_cell}
            return
        if operation == "glyph_union_select":
            from .concordance_declarations import (
                SOURCE_GLYPH_SEQUENCE,
                SourceGlyphSequence,
            )

            cell = mutation.source_contract_cell
            fact = self._book().page(SOURCE_GLYPH_SEQUENCE).cell(
                cell.row, cell.column,
            )

            def glyph_tree(component):
                yield component
                for child in component.projection_components:
                    yield from glyph_tree(child)

            selected = tuple(
                component
                for root in fact.components
                for component in glyph_tree(root)
                if int(component.component_value_id)
                == int(mutation.sequence_value_id)
                and component.union_alternatives
            )
            if len(selected) != 1:
                raise ValueError(
                    f"{location}: value-union glyph destination does not "
                    "name exactly one source component"
                )
            component = selected[0]
            subject_id = int(component.operand_value_id)
            descriptor = self.value_union_table.by_id(subject_id)
            type_fact = self.native_value_type_abi.get(subject_id)
            if descriptor is None or type_fact is None:
                raise ValueError(
                    f"{location}: value-union glyph projection has no exact "
                    f"native descriptor for value {subject_id}"
                )
            tags = dict(getattr(type_fact, "tags", ()))
            physical = {
                str(arm.identity): arm
                for arm in getattr(type_fact, "physical_alternatives", ())
            }
            recipes = tuple(component.union_alternatives)
            identities = tuple(str(arm.identity) for arm in recipes)
            if (
                identities != tuple(arm.name for arm in descriptor.alternatives)
                or set(tags) != set(identities)
                or set(physical) != set(identities)
            ):
                raise ValueError(
                    f"{location}: glyph alternatives disagree with the "
                    "concorded value-union descriptor"
                )
            for arm in recipes:
                exact_sources = set(physical[str(arm.identity)].source_cells)
                if not arm.source_cells or not set(arm.source_cells) <= exact_sources:
                    raise ValueError(
                        f"{location}: glyph arm {arm.identity!r} lacks its "
                        "exact VALUE_TYPE_ABI source cells"
                    )
            tag = self.external_value(
                int(descriptor.tag_value_id), dtype="int64"
            )
            merge = self.new_block("glyph_union_merge")
            for ordinal, arm in enumerate(recipes):
                arm_block = self.new_block("glyph_union_arm")
                if ordinal + 1 == len(recipes):
                    self.branch(arm_block)
                else:
                    next_test = self.new_block("glyph_union_test")
                    tag_token = self.constant_value(int(tags[arm.identity]), tag)
                    matches = self.fresh_value(
                        dtype="bool", transform=CONTROL_PREDICATE,
                        operands=(tag, tag_token, *tuple(arm.source_cells)),
                    )
                    self.emit(
                        Handler.Eq, [tag, tag_token], matches,
                        attributes={
                            "binding": "value_union_glyph_arm",
                            "source_value_id": subject_id,
                            "alternative": str(arm.identity),
                        },
                    )
                    self.conditional_branch(matches, arm_block, next_test)
                self.current = arm_block
                self._lower_sequence_mutation_body(
                    ControlSequenceMutation(
                        int(mutation.sequence_value_id), "replace",
                        (int(arm.sequence_value_id),),
                        int(mutation.effect_node_id), policy=mutation.policy,
                        argument_kind="value_union_glyph_arm",
                        source_contract_cell=cell,
                    ),
                    path=f"{path}.value_union[{arm.identity}]",
                )
                if not self.current.successors:
                    self.branch(merge)
                if ordinal + 1 != len(recipes):
                    self.current = next_test
            self.current = merge
            return
        if int(mutation.sequence_value_id) in self.native_object_source_ids:
            workspace = self.native_object_collection_rows.get(int(mutation.sequence_value_id))
            if workspace is not None and operation == 'append':
                receipt, base, induction = workspace
                from .ssa_object_context import object_source_contract
                arguments = mutation.argument_value_ids
                if mutation.object_contract_cell is not None:
                    publication = object_source_contract(mutation.object_contract_cell, book=self._book())
                    if arguments != publication['projected_argument_value_ids']:
                        raise ValueError(f'{location}: publication differs from its concordance projection')
                    arguments = publication['source_argument_value_ids']
                if (arguments != (receipt['source_value_id'],)
                        or mutation.predicate_expression is not None
                        or int(mutation.effect_node_id) != receipt['loop_node_id']):
                    raise ValueError(f'{location}: native collection publication differs from its loop edge')
                item = self.external_value(receipt['member_value_id'])
                if item.dtype not in {None, 'unknown', 'opaque_ref'} or item.shape:
                    raise ValueError(f'{location}: collection member has unresolved/non-reference layout {item.dtype}/{item.shape}')
                address = self._native_collection_address(receipt, base, induction)
                self.emit(Handler.Store, [item, address], attributes={'native_collection_row': {
                    **receipt, 'action': 'publish', 'base_value_id': base.id,
                    'index_value_id': induction.id}})
                return
            if operation == 'update' and mutation.argument_kind == 'mapping_items' and len(mutation.argument_value_ids) == 2:
                self._emit_table_store(mutation.effect_node_id, mutation.argument_value_ids[0],
                                      mutation.argument_value_ids[1], mutation.sequence_value_id)
                return
            raise ValueError(f'{location}: native object operation {operation!r}/{mutation.argument_kind!r} is not bound')
        if mutation.policy is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence",
                operation,
                location,
                "destination uniqueness policy is unresolved",
            ))
            return
        if not mutation.argument_value_ids and operation not in {"clear", "pop", "sort", "reverse"} and str(mutation.argument_kind) != "child_row":
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence",
                operation,
                location,
                "sequence mutation has no explicit source value",
            ))
            return
        destination = self._sequence_descriptor(
            mutation.sequence_value_id,
            policy=mutation.policy,
            writable=True,
            location=location,
            **({
                "column_count": 1,
                "column_dtypes": ("int64",),
            } if operation == "glyph_token_lookup_copy" else {}),
        )
        if destination is None:
            return

        if operation == "sorted":
            if not mutation.argument_value_ids:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", operation, location,
                    "sorted requires one resident source sequence",
                ))
                return
            # ``sorted`` owns a distinct result arena.  Its extent follows
            # the resident source at run time.  A private result is born
            # DYNAMIC with its own heap owner (the shell's dynamic set): the
            # copy reserves to the source's length.  Only a result with no
            # heap owner -- a public output's fixed extent -- is exposed on
            # the root ABI as caller-provided workspace.
            heap_owned = (
                int(destination.sequence_id) in self.sequence_heap_owners
            )
            for value in () if heap_owned else self.sequence_storage_values[
                int(destination.sequence_id)
            ]:
                value.accounting = {
                    **dict(value.accounting or {}),
                    "caller_provided_workspace": True,
                    "workspace_operation": "sorted_result",
                }
            destination_status = self.sequence_status_values.get(
                int(destination.sequence_id)
            )
            if destination_status is not None and not heap_owned:
                destination_status.accounting = {
                    **dict(destination_status.accounting or {}),
                    "caller_provided_workspace": True,
                    "workspace_operation": "sorted_result",
                }
            source_id, *sort_arguments = tuple(map(
                int, mutation.argument_value_ids,
            ))
            self._lower_sequence_mutation_body(
                ControlSequenceMutation(
                    sequence_value_id=int(mutation.sequence_value_id),
                    operator="replace",
                    argument_value_ids=(int(source_id),),
                    effect_node_id=int(mutation.effect_node_id),
                    policy=mutation.policy,
                    source_contract_cell=mutation.source_contract_cell,
                ),
                path=f"{path}.sorted_copy",
            )
            self._lower_sequence_mutation_body(
                ControlSequenceMutation(
                    sequence_value_id=int(mutation.sequence_value_id),
                    operator="sort",
                    argument_value_ids=tuple(sort_arguments),
                    effect_node_id=int(mutation.effect_node_id),
                    policy=mutation.policy,
                    argument_kind=str(mutation.argument_kind).removeprefix(
                        "sorted_"
                    ),
                    sort_key_column=mutation.sort_key_column,
                    sort_reverse=mutation.sort_reverse,
                    source_contract_cell=mutation.source_contract_cell,
                ),
                path=f"{path}.sorted_order",
            )
            return

        if operation == "sort":
            key_mapping = None
            if mutation.argument_kind == "sort_key_mapping_getitem":
                if len(mutation.argument_value_ids) != 1:
                    self.shortfalls.append(SSALoweringShortfall(
                        "ssa-sequence", operation, location,
                        "mapping-key sort requires one resident mapping",
                    ))
                    return
                key_mapping = self._sequence_descriptor(
                    int(mutation.argument_value_ids[0]),
                    policy="unique",
                    writable=True,
                    location=f"{location}.key_mapping",
                )
                if key_mapping is None:
                    return
            elif mutation.argument_kind == "sort_key_unsupported":
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", operation, location,
                    "sort key must be a direct row projection or a resident "
                    "mapping __getitem__; reverse must be a bool literal",
                ))
                return
            elif mutation.argument_value_ids:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", operation, location,
                    "resident sequence sort received unsupported arguments",
                ))
                return
            from .ir_sequence_tables import lower_sequence_sort

            scratch_id = int(self.fresh_value(
                dtype="unknown",
                transform=DESCRIPTOR_CELL,
                operands=(
                    self._sequence_contract_cell(
                        int(destination.sequence_id)
                    ),
                    *self.sequence_storage_values[
                        int(destination.sequence_id)
                    ],
                ),
            ).id)
            # A heap-owned destination's workspaces are the function's own
            # storage, sized to its rows by the sort's reserve; a fixed
            # destination's remain caller-provided workspace.
            heap_workspaces = (
                int(destination.sequence_id) in self.sequence_heap_owners
            )
            if heap_workspaces:
                self.dynamic_sequence_ids = self.dynamic_sequence_ids | {
                    scratch_id,
                }
            scratch = self._sequence_descriptor(
                scratch_id,
                policy="duplicates",
                writable=True,
                location=f"{location}.scratch",
                column_count=len(destination.column_value_ids),
                column_dtypes=tuple(destination.column_dtypes),
                column_shapes=tuple(destination.column_shapes),
            )
            if scratch is None:
                return
            for value in () if heap_workspaces else self.sequence_storage_values[int(scratch.sequence_id)]:
                value.accounting = {
                    **dict(value.accounting or {}),
                    "caller_provided_workspace": True,
                    "workspace_operation": "sort",
                }
            scratch_status = self.sequence_status_values.get(
                int(scratch.sequence_id)
            )
            if scratch_status is not None and not heap_workspaces:
                scratch_status.accounting = {
                    **dict(scratch_status.accounting or {}),
                    "caller_provided_workspace": True,
                    "workspace_operation": "sort",
                }
            # The sort orders a permutation: two int64 buffers, plus the
            # mapped key per source row when keys come from a resident
            # mapping (looked up once per row, not once per comparison).
            order_dtypes = ("int64", "int64")
            if key_mapping is not None:
                mapping_value_column = next(
                    column for column in range(len(key_mapping.column_value_ids))
                    if column not in key_mapping.key_columns
                )
                order_dtypes = (
                    *order_dtypes,
                    key_mapping.column_dtypes[mapping_value_column],
                )
            order_id = int(self.fresh_value(
                dtype="unknown",
                transform=DESCRIPTOR_CELL,
                operands=(
                    self._sequence_contract_cell(
                        int(destination.sequence_id)
                    ),
                    *self.sequence_storage_values[
                        int(destination.sequence_id)
                    ],
                ),
            ).id)
            if heap_workspaces:
                self.dynamic_sequence_ids = self.dynamic_sequence_ids | {
                    order_id,
                }
            order = self._sequence_descriptor(
                order_id,
                policy="duplicates",
                writable=True,
                location=f"{location}.order",
                column_count=len(order_dtypes),
                column_dtypes=order_dtypes,
                column_shapes=((),) * len(order_dtypes),
            )
            if order is None:
                return
            for value in () if heap_workspaces else self.sequence_storage_values[int(order.sequence_id)]:
                value.accounting = {
                    **dict(value.accounting or {}),
                    "caller_provided_workspace": True,
                    "workspace_operation": "sort_order",
                }
            order_status = self.sequence_status_values.get(
                int(order.sequence_id)
            )
            if order_status is not None and not heap_workspaces:
                order_status.accounting = {
                    **dict(order_status.accounting or {}),
                    "caller_provided_workspace": True,
                    "workspace_operation": "sort_order",
                }
            function_name = self._sequence_helper_name(
                int(destination.sequence_id), "sort",
            )
            lowering = lower_sequence_sort(
                destination,
                scratch,
                order,
                key_column=int(mutation.sort_key_column or 0),
                key_mapping=key_mapping,
                reverse=bool(mutation.sort_reverse),
                function_name=function_name,
                first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
            )
            if not lowering.complete:
                self.shortfalls.extend(
                    SSALoweringShortfall(
                        "ssa-sequence", item.code.value, location, item.reason,
                    )
                    for item in lowering.shortfalls
                )
                return
            self._register_sequence_lowering(lowering)
            available_arguments = {
                int(value.id): value
                for value in (
                    *self.sequence_storage_values[int(destination.sequence_id)],
                    *self.sequence_storage_values[int(scratch.sequence_id)],
                    *self.sequence_storage_values[int(order.sequence_id)],
                    *(
                        self.sequence_storage_values[int(key_mapping.sequence_id)]
                        if key_mapping is not None else ()
                    ),
                    *(
                        (self.sequence_status_values[int(key_mapping.sequence_id)],)
                        if key_mapping is not None else ()
                    ),
                )
            }
            call_arguments = tuple(
                available_arguments[int(formal.id)]
                for formal in lowering.entry.args
            )
            status = self.fresh_value(
                dtype="int", transform=REGION_CALL_RESULT,
                operands=call_arguments,
            )
            self.emit(
                Handler.Call,
                list(call_arguments),
                status,
                attributes={
                    "callee": lowering.entry.name,
                    "source_linked": True,
                    "ssa_sequence_operation": "sort",
                    "sequence_id": int(destination.sequence_id),
                    "scratch_sequence_id": int(scratch.sequence_id),
                    "order_sequence_id": int(order.sequence_id),
                    "sort_key_column": int(mutation.sort_key_column or 0),
                    "sort_key_mapping_sequence_id": (
                        None if key_mapping is None
                        else int(key_mapping.sequence_id)
                    ),
                    "sort_reverse": bool(mutation.sort_reverse),
                    "source_effect_node_id": int(mutation.effect_node_id),
                },
            )
            self.emit(
                Handler.Store,
                [
                    status,
                    self._sequence_status_address(
                        self.sequence_status_values[destination.sequence_id]
                    ),
                ],
                attributes={"binding": "ssa_sequence_status"},
            )
            return

        if operation == "glyph_token_lookup_copy":
            if len(mutation.argument_value_ids) != 2:
                raise ValueError(
                    f"{location}: glyph token projection requires token and vocabulary"
                )
            token_id, vocabulary_id = tuple(map(
                int, mutation.argument_value_ids,
            ))
            vocabulary = self._sequence_descriptor(
                vocabulary_id,
                policy="unique",
                writable=False,
                location=f"{location}.vocabulary",
                column_count=3,
                column_dtypes=("int64", "int64", "int64"),
            )
            if vocabulary is None:
                return
            from .ir_sequence_tables import lower_glyph_token_copy

            lowering = lower_glyph_token_copy(
                destination,
                vocabulary,
                function_name=self._sequence_helper_name(
                    int(destination.sequence_id), "glyph_token_copy",
                    int(vocabulary.sequence_id),
                ),
            )
            self._register_sequence_lowering(lowering)
            token = self.external_value(token_id, dtype="int64")
            call_arguments = tuple({
                int(value.id): value
                for value in (
                    *self.sequence_storage_values[
                        int(destination.sequence_id)
                    ],
                    *self.sequence_storage_values[
                        int(vocabulary.sequence_id)
                    ],
                    self.sequence_status_values[int(vocabulary.sequence_id)],
                )
            }.values()) + (token,)
            status = self.fresh_value(
                dtype="int", transform=REGION_CALL_RESULT,
                operands=call_arguments,
            )
            self.emit(
                Handler.Call, list(call_arguments), status,
                attributes={
                    "callee": lowering.entry.name,
                    "source_linked": True,
                    "ssa_sequence_operation": operation,
                    "sequence_id": int(destination.sequence_id),
                    "vocabulary_sequence_id": int(vocabulary.sequence_id),
                    "source_effect_node_id": int(mutation.effect_node_id),
                },
            )
            self.emit(
                Handler.Store,
                [
                    status,
                    self._sequence_status_address(
                        self.sequence_status_values[
                            int(destination.sequence_id)
                        ]
                    ),
                ],
                attributes={"binding": "ssa_sequence_status"},
            )
            return

        if operation == "clear" and not mutation.argument_kind.startswith(
            "mapping_"
        ):
            if mutation.argument_value_ids:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", operation, location,
                    "resident sequence clear takes no arguments",
                ))
                return
            storage = self.sequence_storage_values[
                int(destination.sequence_id)
            ]
            length_address = storage[len(destination.column_value_ids)]
            self.emit(
                Handler.Store,
                [self.constant_value(0), length_address],
                attributes={
                    "binding": "ssa_sequence_clear",
                    "sequence_id": int(destination.sequence_id),
                    "source_effect_node_id": int(mutation.effect_node_id),
                    **({
                        "extraction_identity": str(
                            mutation.extraction_identity
                        ),
                    } if mutation.extraction_identity is not None else {}),
                },
            )
            return

        if operation in {"insert", "reverse"} or (
            operation == "pop" and mutation.argument_value_ids
            and not mutation.argument_kind.startswith("mapping_")
        ):
            self._lower_positional_sequence_operation(
                mutation, destination, location=location,
            )
            return
        if operation == "pop" and not mutation.argument_kind.startswith(
            "mapping_"
        ):
            if len(destination.column_value_ids) != 1:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", operation, location,
                    "resident sequence pop requires one resolved value "
                    "column before aggregate-row results are admitted",
                ))
                return
            storage = self.sequence_storage_values[
                int(destination.sequence_id)
            ]
            length_address = storage[len(destination.column_value_ids)]
            attributes = {
                "binding": "ssa_sequence_pop",
                "sequence_id": int(destination.sequence_id),
                "source_effect_node_id": int(mutation.effect_node_id),
                **({
                    "extraction_identity": str(
                        mutation.extraction_identity
                    ),
                } if mutation.extraction_identity is not None else {}),
            }
            length = self.fresh_value(
                dtype="int64", transform=LOAD, operands=(length_address,),
            )
            self.emit(
                Handler.Load, [length_address], length,
                attributes=attributes,
            )
            nonempty = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE, operands=(length,),
            )
            self.emit(
                Handler.Gt,
                [length, self.constant_value(0, length)],
                nonempty,
                attributes=attributes,
            )
            selected = self.new_block("sequence_pop_selected")
            empty = self.new_block("sequence_pop_empty")
            self.conditional_branch(nonempty, selected, empty)

            self.current = empty
            self.emit(
                Handler.Call,
                [],
                attributes={
                    "callee": "turing_validation_error",
                    "error_code": 71,
                    **attributes,
                },
            )
            self.branch(selected)

            self.current = selected
            new_length = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION, operands=(length,),
            )
            self.emit(
                Handler.Sub,
                [length, self.constant_value(1, length)],
                new_length,
                attributes=attributes,
            )
            address = self.fresh_value(
                dtype="ptr", transform=ADDRESS, operands=(storage[0], new_length),
            )
            self.emit(
                Handler.GetElementPtr,
                [storage[0], new_length],
                address,
                attributes=attributes,
            )
            result = self.produced_value(
                int(mutation.effect_node_id),
                dtype=str((destination.column_dtypes or ("unknown",))[0]),
                claim_provisional_definition=True,
                cause=(address,),
            )
            self.emit(
                Handler.Load, [address], result,
                attributes=attributes,
            )
            self.emit(
                Handler.Store,
                [new_length, length_address],
                attributes=attributes,
            )
            self._bind(
                int(mutation.effect_node_id), result,
                BindingKind.SEQUENCE_RESULT, address,
            )
            return

        if operation == "remove" and not mutation.argument_kind.startswith(
            "mapping_"
        ):
            expected_columns = len(destination.column_value_ids)
            if len(mutation.argument_value_ids) != expected_columns:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", operation, location,
                    "resident sequence remove requires one explicit value "
                    f"per row column; expected {expected_columns}, received "
                    f"{len(mutation.argument_value_ids)}",
                ))
                return
            queries = tuple(
                (
                    self.lower_control_expression(expression)
                    if expression is not None
                    else self.external_value(value_id)
                )
                for value_id, expression in zip(
                    mutation.argument_value_ids,
                    (
                        *mutation.argument_expressions,
                        *(None for _ in range(
                            len(mutation.argument_value_ids)
                            - len(mutation.argument_expressions)
                        )),
                    ),
                )
            )
            storage = self.sequence_storage_values[
                int(destination.sequence_id)
            ]
            length_address = storage[len(destination.column_value_ids)]
            attributes = {
                "binding": "ssa_sequence_remove",
                "sequence_id": int(destination.sequence_id),
                "source_effect_node_id": int(mutation.effect_node_id),
            }
            length = self.fresh_value(
                dtype="int64", transform=LOAD, operands=(length_address,),
            )
            self.emit(Handler.Load, [length_address], length, attributes=attributes)
            zero = self.constant_value(0, length, dtype="int64")
            one = self.constant_value(1, length, dtype="int64")
            scan_header = self.new_block("sequence_remove_scan")
            scan_body = self.new_block("sequence_remove_compare")
            scan_latch = self.new_block("sequence_remove_next")
            shift_header = self.new_block("sequence_remove_shift")
            shift_body = self.new_block("sequence_remove_shift_row")
            shift_latch = self.new_block("sequence_remove_shift_next")
            store_length = self.new_block("sequence_remove_store_length")
            absent = self.new_block("sequence_remove_absent")
            complete = self.new_block("sequence_remove_complete")
            scan_entry = self.current
            self.branch(scan_header)

            self.current = scan_header
            next_scan = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION, operands=(length,),
            )
            scan_index = self.fresh_value(
                dtype="int64", transform=PHI_LOOP_HEADER,
                operands=(zero, next_scan),
            )
            self.emit(
                Handler.Phi, [zero, next_scan], scan_index,
                attributes={
                    **attributes,
                    "incoming_blocks": (scan_entry.name, scan_latch.name),
                },
            )
            scanning = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(scan_index, length),
            )
            self.emit(Handler.Lt, [scan_index, length], scanning,
                      attributes=attributes)
            self.conditional_branch(scanning, scan_body, absent)

            self.current = scan_body
            matches = None
            for column, query in enumerate(queries):
                address = self.fresh_value(
                    dtype="ptr", transform=ADDRESS,
                    operands=(storage[column], scan_index),
                )
                existing = self.fresh_value(
                    dtype=str(destination.column_dtypes[column]),
                    transform=LOAD, operands=(address,),
                )
                equal = self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE,
                    operands=(existing, query),
                )
                self.emit(
                    Handler.GetElementPtr,
                    [storage[column], scan_index], address,
                    attributes=attributes,
                )
                self.emit(Handler.Load, [address], existing,
                          attributes=attributes)
                self.emit(Handler.Eq, [existing, query], equal,
                          attributes=attributes)
                if matches is None:
                    matches = equal
                else:
                    combined = self.fresh_value(
                        dtype="bool", transform=CONTROL_PREDICATE,
                        operands=(matches, equal),
                    )
                    self.emit(Handler.LAnd, [matches, equal], combined,
                              attributes=attributes)
                    matches = combined
            self.conditional_branch(matches, shift_header, scan_latch)

            self.current = scan_latch
            self.emit(Handler.Add, [scan_index, one], next_scan,
                      attributes=attributes)
            self.branch(scan_header)

            new_length = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(length, one),
            )
            self.current = shift_header
            next_shift = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(scan_index, one),
            )
            shift_index = self.fresh_value(
                dtype="int64", transform=PHI_LOOP_HEADER,
                operands=(scan_index, next_shift),
            )
            # The header's Phi leads its block: LLVM rejects a Phi after the
            # ``length - 1`` it once followed (c137, lane E).
            self.emit(
                Handler.Phi, [scan_index, next_shift], shift_index,
                attributes={
                    **attributes,
                    "incoming_blocks": (scan_body.name, shift_latch.name),
                },
            )
            self.emit(Handler.Sub, [length, one], new_length,
                      attributes=attributes)
            shifting = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(shift_index, new_length),
            )
            self.emit(Handler.Lt, [shift_index, new_length], shifting,
                      attributes=attributes)
            self.conditional_branch(shifting, shift_body, store_length)

            self.current = shift_body
            source_index = self.fresh_value(
                dtype="int64", transform=CONTROL_EXPRESSION,
                operands=(shift_index, one),
            )
            self.emit(Handler.Add, [shift_index, one], source_index,
                      attributes=attributes)
            for column, dtype in enumerate(destination.column_dtypes):
                source_address = self.fresh_value(
                    dtype="ptr", transform=ADDRESS,
                    operands=(storage[column], source_index),
                )
                destination_address = self.fresh_value(
                    dtype="ptr", transform=ADDRESS,
                    operands=(storage[column], shift_index),
                )
                value = self.fresh_value(
                    dtype=str(dtype), transform=LOAD, operands=(source_address,),
                )
                self.emit(
                    Handler.GetElementPtr,
                    [storage[column], source_index], source_address,
                    attributes=attributes,
                )
                self.emit(Handler.Load, [source_address], value,
                          attributes=attributes)
                self.emit(
                    Handler.GetElementPtr,
                    [storage[column], shift_index], destination_address,
                    attributes=attributes,
                )
                self.emit(Handler.Store, [value, destination_address],
                          attributes=attributes)
            self.branch(shift_latch)

            self.current = shift_latch
            self.emit(Handler.Add, [shift_index, one], next_shift,
                      attributes=attributes)
            self.branch(shift_header)

            self.current = store_length
            self.emit(Handler.Store, [new_length, length_address],
                      attributes=attributes)
            self.branch(complete)

            self.current = absent
            self.emit(
                Handler.Call, [],
                attributes={
                    "callee": "turing_validation_error",
                    "error_code": 72,
                    **attributes,
                },
            )
            self.branch(complete)
            self.current = complete
            return

        if mutation.argument_kind.startswith("mapping_"):
            if operation == "update":
                if (
                    mutation.argument_kind != "mapping_items"
                    or len(mutation.argument_value_ids) % 2
                ):
                    self.shortfalls.append(SSALoweringShortfall(
                        "ssa-table", operation, location,
                        "mapping update requires deterministic key/value "
                        "pairs from a fixed mapping aggregate",
                    ))
                    return
                value_columns = tuple(
                    column
                    for column in range(len(destination.column_value_ids))
                    if column not in destination.key_columns
                )
                if not destination.key_columns or len(value_columns) != 1:
                    self.shortfalls.append(SSALoweringShortfall(
                        "ssa-table", operation, location,
                        "mapping update requires a resolved table schema "
                        "with key columns and one value column",
                    ))
                    return
                for key_id, value_id in zip(
                    mutation.argument_value_ids[0::2],
                    mutation.argument_value_ids[1::2],
                ):
                    self._emit_table_store(
                        int(mutation.effect_node_id), int(key_id),
                        int(value_id), int(destination.sequence_id),
                    )
                return
            if operation == "pop":
                optional_none = (
                    mutation.argument_kind == "mapping_pop_default_none"
                )
                if len(mutation.argument_value_ids) != (2 if optional_none else 1):
                    self.shortfalls.append(SSALoweringShortfall(
                        "ssa-table", operation, location,
                        "mapping pop with a default requires an explicit "
                        "optional-result ABI before lookup-and-delete; "
                        f"child_pool={destination.child_table_pool is not None}, "
                        f"key_columns={destination.key_columns}, "
                        f"column_dtypes={destination.column_dtypes}, "
                        f"arguments={mutation.argument_value_ids}, "
                        f"resolved_schema={self.resolved_sequence_schemas.get(int(destination.sequence_id))!r}",
                    ))
                    return
                key_id = int(mutation.argument_value_ids[0])
                if optional_none:
                    self.table_lookup_defaults[int(mutation.effect_node_id)] = -1
                self._emit_table_lookup(
                    int(mutation.effect_node_id), key_id,
                    int(destination.sequence_id),
                )
                self._emit_table_delete(
                    int(mutation.effect_node_id), key_id,
                    int(destination.sequence_id),
                    f"sequence:{int(destination.sequence_id)}",
                    required=not optional_none,
                )
                return
            if operation == "setdefault":
                pool = destination.child_table_pool
                key_count = len(destination.key_columns)
                value_columns = tuple(
                    column
                    for column in range(len(destination.column_value_ids))
                    if column not in destination.key_columns
                )
                if (
                    pool is None
                    and key_count
                    and len(value_columns) == 1
                    and len(mutation.argument_value_ids) == key_count + 1
                ):
                    from .ir_sequence_tables import lower_table_lookup

                    key_ids = tuple(map(
                        int, mutation.argument_value_ids[:key_count]
                    ))
                    default_id = int(mutation.argument_value_ids[-1])
                    lookup_name = self._sequence_helper_name(
                        int(destination.sequence_id), "setdefault_lookup",
                    )
                    lookup = lower_table_lookup(
                        destination,
                        function_name=lookup_name,
                        first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                    )
                    self._register_sequence_lowering(lookup)
                    query_values = self._table_query_values(
                        key_ids, destination,
                    )
                    existing = self.fresh_value(
                        dtype=str(destination.column_dtypes[value_columns[0]]),
                        transform=TABLE_LOOKUP,
                        operands=(
                            self._sequence_contract_cell(
                                int(destination.sequence_id)
                            ),
                            *query_values,
                        ),
                    )
                    self.emit(
                        Handler.Call,
                        [
                            *self.sequence_storage_values[
                                int(destination.sequence_id)
                            ],
                            self.sequence_status_values[
                                int(destination.sequence_id)
                            ],
                            *query_values,
                        ],
                        existing,
                        attributes={
                            "callee": lookup_name,
                            "source_linked": True,
                            "ssa_sequence_operation": "setdefault_lookup",
                            "sequence_id": int(destination.sequence_id),
                        },
                    )
                    status_cell = self._sequence_status_address(
                        self.sequence_status_values[
                            int(destination.sequence_id)
                        ]
                    )
                    status = self.fresh_value(
                        dtype="int", transform=LOAD, operands=(status_cell,),
                    )
                    self.emit(
                        Handler.Load, [status_cell], status,
                        attributes={"binding": "ssa_mapping_setdefault_status"},
                    )
                    found = self.fresh_value(
                        dtype="bool", transform=CONTROL_PREDICATE,
                        operands=(status,),
                    )
                    self.emit(
                        Handler.Gt,
                        [status, self.constant_value(0, status)],
                        found,
                        attributes={"binding": "ssa_mapping_setdefault_found"},
                    )
                    found_block = self.new_block("mapping_setdefault_found")
                    missing_block = self.new_block("mapping_setdefault_missing")
                    complete = self.new_block("mapping_setdefault_merge")
                    self.conditional_branch(found, found_block, missing_block)

                    self.current = found_block
                    self.branch(complete)

                    self.current = missing_block
                    default = self.external_value(default_id)
                    self._emit_table_store(
                        int(mutation.effect_node_id), key_ids, default_id,
                        int(destination.sequence_id),
                    )
                    missing_exit_name = self.current.name
                    self.branch(complete)

                    self.current = complete
                    result = self.produced_value(
                        int(mutation.effect_node_id),
                        dtype=str(existing.dtype or default.dtype or "unknown"),
                        claim_provisional_definition=True,
                        cause=(existing, default, found),
                    )
                    self.emit(
                        Handler.Phi,
                        [existing, default],
                        result,
                        attributes={
                            "incoming_blocks": (
                                found_block.name, missing_exit_name,
                            ),
                            "binding": "ssa_mapping_setdefault_result",
                        },
                    )
                    self._bind(
                        int(mutation.effect_node_id), result,
                        BindingKind.SEQUENCE_RESULT, existing, default,
                    )
                    return
                if (
                    pool is None
                    or len(mutation.argument_value_ids) != key_count + 1
                ):
                    self.shortfalls.append(SSALoweringShortfall(
                        "ssa-table", operation, location,
                        "mapping setdefault requires a resolved child-table "
                        "pool, exact key columns, and one aggregate default; "
                        f"child_pool={pool is not None}, "
                        f"key_columns={destination.key_columns}, "
                        f"arguments={mutation.argument_value_ids}, "
                        f"resolved_schema={self.resolved_sequence_schemas.get(int(destination.sequence_id))!r}",
                    ))
                    return
                from .ir_sequence_tables import lower_table_lookup

                lookup_name = self._sequence_helper_name(
                    int(destination.sequence_id), "setdefault_lookup",
                )
                lookup = lower_table_lookup(
                    destination,
                    function_name=lookup_name,
                    first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                )
                self._register_sequence_lowering(lookup)
                # A selected child handle is the parent table's declared
                # value column. Narrowing it to generic int made the fixed
                # int64 table-store call ill-typed (and truncated large rows).
                handle_dtype = destination.column_dtypes[pool.handle_column]
                lookup_handle = self.fresh_value(
                    dtype=handle_dtype, transform=TABLE_LOOKUP,
                    operands=(
                        self._sequence_contract_cell(int(destination.sequence_id)),
                        *mutation.argument_value_ids[:key_count],
                    ),
                )
                key_ids = tuple(map(
                    int, mutation.argument_value_ids[:key_count]
                ))
                self.emit(
                    Handler.Call,
                    [
                        *self.sequence_storage_values[
                            int(destination.sequence_id)
                        ],
                        self.sequence_status_values[
                            int(destination.sequence_id)
                        ],
                        *self._table_query_values(key_ids),
                    ],
                    lookup_handle,
                    attributes={
                        "callee": lookup_name,
                        "source_linked": True,
                        "ssa_sequence_operation": "setdefault_lookup",
                        "sequence_id": int(destination.sequence_id),
                    },
                )
                status_cell = self._sequence_status_address(
                    self.sequence_status_values[int(destination.sequence_id)]
                )
                status = self.fresh_value(
                    dtype="int", transform=LOAD, operands=(status_cell,),
                )
                self.emit(
                    Handler.Load,
                    [status_cell],
                    status,
                    attributes={"binding": "ssa_mapping_setdefault_status"},
                )
                found = self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE, operands=(status,),
                )
                self.emit(
                    Handler.Gt, [status, self.constant_value(0, status)], found,
                    attributes={"binding": "ssa_mapping_setdefault_found"},
                )
                found_block = self.new_block("mapping_setdefault_found")
                missing_block = self.new_block("mapping_setdefault_missing")
                complete = self.new_block("mapping_setdefault_merge")
                self.conditional_branch(found, found_block, missing_block)

                self.current = found_block
                self.branch(complete)

                self.current = missing_block
                outer_length_address = self.sequence_storage_values[
                    int(destination.sequence_id)
                ][len(destination.column_value_ids)]
                outer_length_cell = outer_length_address
                outer_length_address = self.fresh_value(dtype="ptr", transform=ADDRESS, operands=(outer_length_cell,))
                self.emit(Handler.GetElementPtr, [outer_length_cell, self.constant_value(0, outer_length_cell)], outer_length_address,
                          attributes={"binding": "ssa_mapping_setdefault_length_address"})
                outer_length = self.fresh_value(
                    dtype="int64", transform=LOAD, operands=(outer_length_address,),
                )
                self.emit(
                    Handler.Load, [outer_length_address], outer_length,
                    attributes={"binding": "ssa_mapping_setdefault_handle"},
                )
                new_handle = self.fresh_value(
                    dtype=handle_dtype, transform=CONTROL_CAST, operands=(outer_length,),
                )
                self.emit(
                    Handler.Cast, [outer_length], new_handle,
                    attributes={"target_dtype": handle_dtype},
                )
                self._bind(
                    int(new_handle.id), new_handle, BindingKind.SEQUENCE_RESULT,
                    outer_length,
                )
                # Same flattened-pool rule as append_child_copy: each new
                # handle owns one whole stride, and the outer row must fit.
                # Error runtime calls return, so the failure edge MUST skip
                # initialization/store and the dependent append's row view.
                next_length = self.fresh_value(dtype="int64", transform=CONTROL_EXPRESSION, operands=(outer_length,))
                self.emit(Handler.Add, [outer_length, self.constant_value(1, outer_length, dtype="int64")], next_length)
                reserve_valid = None
                if destination.heap_owner_value_id is not None:
                    reserve_valid = self._reserve_owned_child_pool(destination, next_length,
                        self.constant_value(1, outer_length, dtype="int64"), location=location)
                outer_capacity = self.sequence_storage_values[int(destination.sequence_id)][len(destination.column_value_ids) + 1]
                stride = self.external_value(pool.row_stride_value_id)
                pool_capacity = self.external_value(pool.capacity_value_id)
                outer_room = self.fresh_value(dtype="bool", transform=CONTROL_PREDICATE, operands=(outer_length, outer_capacity))
                self.emit(Handler.Lt, [outer_length, outer_capacity], outer_room)
                row_end = self.fresh_value(dtype="int64", transform=CONTROL_EXPRESSION, operands=(next_length, stride))
                self.emit(Handler.Mul, [next_length, stride], row_end)
                pool_room = self.fresh_value(dtype="bool", transform=CONTROL_PREDICATE, operands=(row_end, pool_capacity))
                self.emit(Handler.Le, [row_end, pool_capacity], pool_room)
                room = self.fresh_value(dtype="bool", transform=CONTROL_PREDICATE, operands=(outer_room, pool_room))
                self.emit(Handler.LAnd, [outer_room, pool_room], room,
                          attributes={"binding": "selected_child_allocation_bounds"})
                if reserve_valid is not None:
                    checked_room = self.fresh_value(dtype="bool", transform=CONTROL_PREDICATE, operands=(room, reserve_valid))
                    self.emit(Handler.LAnd, [room, reserve_valid], checked_room,
                              attributes={"binding": "selected_child_allocation_bounds"})
                    room = checked_room
                room_pass = self.new_block("validation_pass")
                room_fail = self.new_block("validation_fail")
                missing_join = self.new_block("if_merge")
                self.conditional_branch(room, room_pass, room_fail)
                self.current = room_fail
                self.emit(Handler.Call, [], attributes={
                    "callee": "turing_validation_error", "error_code": 75,
                    "failure": "fixed_capacity_exhausted", "binding": "selected_child_allocation_bounds",
                    "source_effect_node_id": int(mutation.effect_node_id),
                })
                self.branch(missing_join)
                self.current = room_pass
                pool_length = self.external_value(int(pool.length_value_id))
                child_length_address = self.fresh_value(
                    dtype="ptr", transform=ADDRESS,
                    operands=(pool_length, new_handle),
                )
                self.emit(
                    Handler.GetElementPtr,
                    [pool_length, new_handle],
                    child_length_address,
                    attributes={"binding": "ssa_child_table_length", "child_selection_guard_value_id": int(room.id)},
                )
                self.emit(
                    Handler.Store,
                    [self.constant_value(0, child_length_address), child_length_address],
                    attributes={"binding": "ssa_child_table_initialize", "child_selection_guard_value_id": int(room.id)},
                )
                if pool.status_value_id is not None:
                    pool_status = self.external_value(int(pool.status_value_id))
                    child_status_address = self.fresh_value(
                        dtype="ptr", transform=ADDRESS,
                        operands=(pool_status, new_handle),
                    )
                    self.emit(
                        Handler.GetElementPtr,
                        [pool_status, new_handle],
                        child_status_address,
                        attributes={"binding": "ssa_child_table_status", "child_selection_guard_value_id": int(room.id)},
                    )
                    self.emit(
                        Handler.Store,
                        [self.constant_value(0, child_status_address), child_status_address],
                        attributes={"binding": "ssa_child_table_initialize", "child_selection_guard_value_id": int(room.id)},
                    )
                self._emit_table_store(
                    int(mutation.effect_node_id), key_ids,
                    int(new_handle.id), int(destination.sequence_id),
                    child_guard=room,
                )
                self.branch(missing_join)
                self.current = missing_join
                missing_exit_name = self.current.name
                self.branch(complete)

                self.current = complete
                result = self.produced_value(
                    int(mutation.effect_node_id),
                    dtype=handle_dtype,
                    claim_provisional_definition=True,
                    cause=(lookup_handle, new_handle, found),
                )
                self.emit(
                    Handler.Phi,
                    [lookup_handle, new_handle],
                    result,
                    attributes={
                        "incoming_blocks": (
                            found_block.name, missing_exit_name
                        ),
                        "binding": "ssa_mapping_setdefault_result",
                    },
                )
                validity = self.fresh_value(dtype="bool", transform=CONTROL_PREDICATE, operands=(found, room))
                self.emit(Handler.Phi, [self.constant_value(True, found, dtype="bool"), room], validity,
                          attributes={"incoming_blocks": (found_block.name, missing_exit_name),
                                      "binding": "selected_child_validity", "source_value_id": int(mutation.effect_node_id)})
                self.child_selection_validity[int(mutation.effect_node_id)] = validity
                self._bind(
                    int(mutation.effect_node_id), result,
                    BindingKind.SEQUENCE_RESULT, lookup_handle, new_handle,
                )
                self.child_table_selections[int(mutation.effect_node_id)] = (
                    pool, result
                )
                return
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-table", operation, location,
                "unknown mapping mutation operator",
            ))
            return

        from .ir_sequence_tables import (
            lower_sequence_add,
            lower_sequence_append,
            lower_sequence_extend,
            lower_sequence_replace,
        )

        call_arguments: tuple[SSAValue, ...]
        deferred_record_row: tuple[int, str, int] | None = None
        deferred_record_slots: tuple[tuple[int, int, str, int], ...] = ()
        indexed_record_row_source: tuple[int, int, str] | None = None
        native_type_tag_sequence_receipt: tuple = ()
        if operation == "append" and str(mutation.argument_kind) == "child_row":
            self._emit_child_row_birth(mutation, destination, location=location)
            return
        if operation in {"append", "add"}:
            expected_columns = len(destination.column_value_ids)
            record_slots = self.sequence_row_record_slots.get(
                int(destination.sequence_id), ()
            )
            if record_slots and len(
                mutation.argument_value_ids
            ) != expected_columns:
                # A record named at one column of the authored row stands
                # for its member fields.  Its physical layout is proven by
                # native-call linking, which expands the single semantic
                # operand in place; here the row is checked to be exactly
                # the authored width once every record column is expanded.
                argument_count = len(mutation.argument_value_ids)
                applicable = tuple(
                    (position, identity, width)
                    for position, identity, width in record_slots
                    if position < argument_count
                )
                expanded_width = argument_count + sum(
                    width - 1 for _position, _identity, width in applicable
                )
                if applicable and expanded_width == expected_columns:
                    deferred_record_slots = tuple(
                        (
                            int(position),
                            int(mutation.argument_value_ids[position]),
                            str(identity),
                            int(width),
                        )
                        for position, identity, width in applicable
                    )
            if (
                not deferred_record_slots
                and len(mutation.argument_value_ids) != expected_columns
            ):
                record_identity = self.sequence_record_identities.get(
                    int(destination.sequence_id)
                )
                if (
                    record_identity is not None
                    and len(mutation.argument_value_ids) == 1
                    and expected_columns > 1
                ):
                    row_value_id = int(mutation.argument_value_ids[0])
                    row_sources = tuple(
                        (
                            int(iterable_id), int(target_id),
                            str(induction_name),
                        )
                        for iterable_id, target_id, induction_name, projection
                        in self.program.projected_iterable_bindings
                        if int(target_id) == row_value_id
                        and projection == "induction"
                    )
                    row_source = (
                        None if len(row_sources) != 1
                        else self.sequence_descriptors.get(
                            int(row_sources[0][0])
                        )
                    )
                    source_row_identity = (
                        None if row_source is None
                        else self.sequence_record_identities.get(
                            int(row_source.sequence_id)
                        )
                    )
                    if (
                        row_source is not None
                        and len(row_source.column_value_ids)
                        == int(expected_columns)
                        and (
                            source_row_identity is None
                            or str(source_row_identity) == str(record_identity)
                            or str(source_row_identity).rsplit(".", 1)[-1]
                            == str(record_identity).rsplit(".", 1)[-1]
                        )
                    ):
                        indexed_record_row_source = row_sources[0]
                    else:
                        deferred_record_row = (
                            row_value_id,
                            str(record_identity),
                            int(expected_columns),
                        )
                else:
                    self.shortfalls.append(SSALoweringShortfall(
                        "ssa-sequence", operation, location,
                        "row insertion requires one explicit value per resident "
                        f"column; expected {expected_columns}, received "
                        f"{len(mutation.argument_value_ids)}",
                    ))
                    return
            joined_flat_id = self.joined_flat_sequence_ids.get(
                int(destination.sequence_id)
            )
            if joined_flat_id is not None:
                source_id = int(mutation.argument_value_ids[0])
                self.ensure_plan_callsite_result(
                    source_id, location=f"{location}.joined_source"
                )
                flat = self.sequence_descriptors[int(joined_flat_id)]
                singleton_value_id = self.joined_singleton_values.get(
                    source_id
                )
                source = (
                    None
                    if singleton_value_id is not None
                    else self._sequence_descriptor(
                        source_id,
                        policy="duplicates",
                        writable=False,
                        location=f"{location}.joined_source",
                    )
                )
                if singleton_value_id is None and source is None:
                    return
                count_name = self._sequence_helper_name(
                    int(destination.sequence_id), "append",
                )
                count_lowering = lower_sequence_append(
                    destination,
                    function_name=count_name,
                    first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                )
                if not count_lowering.complete:
                    self.shortfalls.extend(
                        SSALoweringShortfall(
                            "ssa-sequence", item.code.value, location,
                            item.reason,
                        )
                        for item in count_lowering.shortfalls
                    )
                    return
                self._register_sequence_lowering(count_lowering)
                flat_name = self._sequence_helper_name(
                    int(joined_flat_id),
                    (
                        "append_singleton"
                        if singleton_value_id is not None else "extend"
                    ),
                    (
                        int(source_id)
                        if singleton_value_id is not None
                        else int(source.sequence_id)
                    ),
                )
                flat_lowering = (
                    lower_sequence_append(
                        flat,
                        function_name=flat_name,
                        first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                    )
                    if singleton_value_id is not None
                    else lower_sequence_extend(
                        flat,
                        source,
                        function_name=flat_name,
                        first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                    )
                )
                if not flat_lowering.complete:
                    self.shortfalls.extend(
                        SSALoweringShortfall(
                            "ssa-sequence", item.code.value, location,
                            item.reason,
                        )
                        for item in flat_lowering.shortfalls
                    )
                    return
                self._register_sequence_lowering(flat_lowering)
                destination_storage = self.sequence_storage_values[
                    destination.sequence_id
                ]
                count_status = self.fresh_value(
                    dtype="int", transform=REGION_CALL_RESULT,
                    operands=tuple(destination_storage),
                )
                self.emit(
                    Handler.Call,
                    [
                        *destination_storage,
                        self.constant_value(0, *destination_storage),
                    ],
                    count_status,
                    attributes={
                        "callee": count_lowering.entry.name,
                        "source_linked": True,
                        "ssa_sequence_operation": "append_joined_count",
                        "sequence_id": int(destination.sequence_id),
                        "source_effect_node_id": int(mutation.effect_node_id),
                    },
                )
                joined_call_values = {
                    int(value.id): value
                    for value in (
                        *self.sequence_storage_values[int(joined_flat_id)],
                        *(
                            (self.external_value(singleton_value_id),)
                            if singleton_value_id is not None
                            else self.sequence_storage_values[
                                source.sequence_id
                            ]
                        ),
                    )
                }
                flat_status = self.fresh_value(
                    dtype="int", transform=REGION_CALL_RESULT,
                    operands=tuple(joined_call_values.values()),
                )
                self.emit(
                    Handler.Call,
                    list(joined_call_values.values()),
                    flat_status,
                    attributes={
                        "callee": flat_lowering.entry.name,
                        "source_linked": True,
                        "ssa_sequence_operation": (
                            "append_joined_singleton"
                            if singleton_value_id is not None
                            else "extend_joined_bytes"
                        ),
                        "sequence_id": int(joined_flat_id),
                        "joined_outer_sequence_id": int(
                            destination.sequence_id
                        ),
                        "joined_source_sequence_id": int(source_id),
                        "joined_source_value_id": (
                            None if singleton_value_id is None
                            else int(singleton_value_id)
                        ),
                        "source_effect_node_id": int(mutation.effect_node_id),
                    },
                )
                for sequence_id, status in (
                    (int(destination.sequence_id), count_status),
                    (int(joined_flat_id), flat_status),
                ):
                    self.emit(
                        Handler.Store,
                        [
                            status,
                            self._sequence_status_address(
                                self.sequence_status_values[sequence_id]
                            ),
                        ],
                        attributes={"binding": "ssa_sequence_status"},
                    )
                return
            mutation_values = tuple(
                (
                    self.lower_control_expression(expression)
                    if expression is not None
                    else self.external_value(value_id)
                )
                for value_id, expression in zip(
                    mutation.argument_value_ids,
                    (
                        *mutation.argument_expressions,
                        *(None for _ in range(
                            len(mutation.argument_value_ids)
                            - len(mutation.argument_expressions)
                        )),
                    ),
                )
            )
            if indexed_record_row_source is not None:
                source_id, _row_target_id, induction_name = (
                    indexed_record_row_source
                )
                source_descriptor = self.sequence_descriptors[int(source_id)]
                source_columns = self.sequence_storage_values[int(source_id)][
                    :len(source_descriptor.column_value_ids)
                ]
                row_index = mutation_values[0]
                indexed_values = []
                for column_index, (source_column, column_dtype) in enumerate(
                    zip(
                        source_columns,
                        source_descriptor.column_dtypes,
                        strict=True,
                    )
                ):
                    existing_targets = tuple(
                        int(target_id)
                        for (
                            iterable_id, target_id, projected_induction,
                            projection,
                        ) in self.program.projected_iterable_bindings
                        if int(iterable_id) == int(source_id)
                        and str(projected_induction) == str(induction_name)
                        and projection == int(column_index)
                        and int(target_id) in self.external_values
                    )
                    if len(existing_targets) == 1:
                        projected = self.external_values[existing_targets[0]]
                    else:
                        projected = self.indexed_load(
                            source_column,
                            row_index,
                            int(self.fresh_value(
                                dtype=str(source_column.dtype or "unknown"),
                                transform=ROW_COLUMN_PROJECTION,
                                operands=(source_column, row_index),
                            ).id),
                            attributes={
                                "binding": "record_sequence_row_column",
                                "record_identity": str(
                                    self.sequence_record_identities.get(
                                        int(destination.sequence_id), ""
                                    )
                                ),
                                "source_sequence_id": int(source_id),
                                "column_index": int(column_index),
                            },
                        )
                    if str(column_dtype) not in {"", "unknown", "None"}:
                        projected.dtype = str(column_dtype)
                    indexed_values.append(projected)
                mutation_values = tuple(indexed_values)
            # Program: ``xs = [5, n, 2, 9]; xs.sort()`` (scratch c133).
            # Wrong record: the literal member 5 is lowered as an untyped
            # Const, so its append proposed no row dtype; ``xs`` called its
            # FIXED append helper there and the DYNAMIC one from ``n`` on,
            # under one helper name (refused: the call binds 4 of 5
            # formals).  Rule: a literal a writer stores proposes its
            # Python class's dtype, as an SSA value proposes its own.
            def static_literal_dtype(expression):
                if expression is None or expression.op != "const":
                    return None
                literal = expression.literal
                if type(literal) is int:
                    from ..transmogrifier.dtype_layout import (
                        python_int_literal_dtype,
                    )

                    return python_int_literal_dtype(literal)
                return (
                    "bool" if isinstance(literal, bool)
                    else "float64" if isinstance(literal, float)
                    else None
                )

            literal_dtypes = tuple(
                static_literal_dtype(expression)
                for expression in (
                    *mutation.argument_expressions,
                    *(None for _ in range(
                        len(mutation_values)
                        - len(mutation.argument_expressions)
                    )),
                )
            )
            for value, literal_dtype in zip(mutation_values, literal_dtypes):
                if literal_dtype is not None and str(
                    value.dtype or "unknown"
                ) in {"", "unknown", "None"}:
                    value.dtype = literal_dtype
                    self._revise_value(value)
            converted_values = []
            from ..transmogrifier.dtype_layout import resolve as dtype_layout
            for value, row_dtype in zip(
                mutation_values, destination.column_dtypes, strict=True,
            ):
                layout = dtype_layout(row_dtype)
                if (layout is not None and layout.kind == "float"
                        and str(value.dtype) == "int64"):
                    converted = self.fresh_value(
                        dtype=layout.name, transform=CONTROL_CAST, operands=(value,),
                    )
                    self.emit(Handler.Cast, [value], converted, attributes={
                        "target_dtype": layout.name,
                        "binding": f"ssa_sequence_{layout.name}_conversion",
                    })
                    converted_values.append(converted)
                    continue
                if (layout is None or layout.kind not in {"int", "uint"}
                        or layout.name == "int64"
                        or str(value.dtype) != "int64"):
                    converted_values.append(value)
                    continue
                # c626/c632/c633: a typed array owns its declared integer
                # row; the Python int source is int64. Validate that row's
                # bounds before converting, including signed narrow rows.
                # A nonnegative int64 already fits uint64's upper bound.
                lower_bound = (0 if layout.kind == "uint" else
                               -(1 << (8 * layout.byte_size - 1)))
                zero = self.constant_value(lower_bound, value, dtype="int64")
                nonnegative = self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE,
                    operands=(value, zero),
                )
                self.emit(Handler.Ge, [value, zero], nonnegative)
                valid = nonnegative
                if layout.byte_size < 8:
                    maximum = self.constant_value(
                        (1 << (8 * layout.byte_size - (layout.kind == "int"))) - 1,
                        value, dtype="int64",
                    )
                    bounded = self.fresh_value(
                        dtype="bool", transform=CONTROL_PREDICATE,
                        operands=(value, maximum),
                    )
                    self.emit(Handler.Le, [value, maximum], bounded)
                    valid = self.fresh_value(
                        dtype="bool", transform=CONTROL_PREDICATE,
                        operands=(nonnegative, bounded),
                    )
                    self.emit(Handler.LAnd, [nonnegative, bounded], valid)
                range_binding = f"ssa_sequence_{layout.name}_range"
                accepted = self.new_block("validation_pass")
                invalid = self.new_block("validation_fail")
                self.conditional_branch(valid, accepted, invalid)
                self.current = invalid
                self.emit(Handler.Call, [], attributes={
                    "callee": "turing_validation_error",
                    "error_code": 74,
                    "binding": range_binding,
                })
                self.branch(accepted)
                self.current = accepted
                narrowed = self.fresh_value(
                    dtype=layout.name, transform=CONTROL_CAST,
                    operands=(value,),
                )
                self.emit(
                    Handler.Cast, [value], narrowed,
                    attributes={"target_dtype": layout.name,
                                "binding": range_binding},
                )
                converted_values.append(narrowed)
            mutation_values = tuple(converted_values)
            if (
                deferred_record_row is None and not deferred_record_slots
                and indexed_record_row_source is None
                and len(mutation_values) == len(destination.column_value_ids)
                and any(
                    str(column_dtype) in {"", "unknown", "None"}
                    and str(value.dtype or "unknown")
                    not in {"", "unknown", "None"}
                    for column_dtype, value in zip(
                        destination.column_dtypes, mutation_values,
                    )
                )
            ):
                # Program: ``xs = []`` then ``xs.append(i * 2 + n)``.  Wrong
                # record: the row dtype was concorded only at the empty
                # literal ('unknown') and the appended int64 never proposed
                # its dtype, so the arena became a double buffer read back as
                # float64 into an int64 accumulator (physical transport
                # disagreement).  Rule: the writer of a row proposes the
                # dtypes of the values it stores; ``unknown`` is absence and
                # a known dtype refines it through the row-dtype concordance,
                # DERIVED from the stored values' cells.  A disagreement with
                # a known column still raises there.
                refined = self._sequence_descriptor(
                    mutation.sequence_value_id,
                    policy=mutation.policy,
                    writable=True,
                    location=location,
                    column_count=len(destination.column_value_ids),
                    column_dtypes=tuple(
                        None if str(value.dtype or "unknown")
                        in {"", "unknown", "None"} else str(value.dtype)
                        for value in mutation_values
                    ),
                    dtype_sources=tuple(mutation_values),
                )
                if refined is None:
                    return
                destination = refined
            if deferred_record_row is None and not deferred_record_slots:
                for mutation_value, element_dtype in zip(
                    mutation_values, destination.column_dtypes
                ):
                    if str(element_dtype) not in {"", "unknown", "None"}:
                        mutation_value.dtype = str(element_dtype)
            elif deferred_record_slots:
                # Scalar columns keep their contract; a record column's
                # dtypes are applied by the link-time expansion.
                slot_positions = {
                    position for position, *_rest in deferred_record_slots
                }
                column_index = 0
                for position, mutation_value in enumerate(mutation_values):
                    slot = next((
                        item for item in deferred_record_slots
                        if item[0] == position
                    ), None)
                    if slot is not None:
                        column_index += int(slot[3])
                        continue
                    if column_index < len(destination.column_dtypes):
                        element_dtype = destination.column_dtypes[column_index]
                        if str(element_dtype) not in {"", "unknown", "None"}:
                            mutation_value.dtype = str(element_dtype)
                    column_index += 1
                del slot_positions
            physical_destination = destination
            tag_columns = (
                {}
                if deferred_record_row is not None or deferred_record_slots
                else self.sequence_native_type_tag_columns(
                    int(destination.sequence_id)
                )
            )
            union_columns = (
                {}
                if not tag_columns else
                self.sequence_native_value_union_columns(
                    int(destination.sequence_id)
                )
            )
            physical_column_ids = []
            physical_column_dtypes = []
            physical_column_shapes = []
            physical_column_values = []
            physical_row_values = []
            sequence_receipt = []
            logical_shapes = tuple(destination.column_shapes or (
                () for _value in destination.column_value_ids
            ))
            # The per-column walk exists for heterogeneous (tagged) columns
            # only; a row written as one deferred record value (expanded
            # at link time into its field columns) has no value per column
            # and the call below passes ``mutation_values`` as they are.
            for column, (logical_column_id, logical_dtype, logical_shape,
                         mutation_value) in enumerate(zip(
                destination.column_value_ids,
                destination.column_dtypes,
                logical_shapes,
                mutation_values,
                strict=True,
            ) if tag_columns else ()):
                tagged = tag_columns.get(int(column))
                if tagged is None:
                    physical_column_ids.append(int(logical_column_id))
                    physical_column_dtypes.append(str(logical_dtype))
                    physical_column_shapes.append(tuple(logical_shape))
                    physical_column_values.append(
                        self.sequence_storage_values[
                            int(destination.sequence_id)
                        ][int(column)]
                    )
                    physical_row_values.append(mutation_value)
                    continue
                tag_column, target_id, fact = tagged
                authored_value_id = int(
                    mutation.argument_value_ids[int(column)]
                )
                tag_value = self.native_type_tag_for(
                    authored_value_id, fact,
                )
                if tag_value is None:
                    raise ValueError(
                        "authored heterogeneous sequence row has no exact "
                        "native type evidence: "
                        f"sequence={int(destination.sequence_id)}, "
                        f"column={int(column)}, value={authored_value_id}"
                    )
                arm_values = self._native_value_union_row_payloads(
                    authored_value_id, mutation_value, fact,
                )
                arms = union_columns[int(column)]
                if len(arms) != len(arm_values):
                    raise ValueError(
                        "heterogeneous sequence writer arm count differs "
                        "from its authoritative ABI"
                    )
                for (arm, arm_column), arm_value in zip(
                    arms, arm_values, strict=True,
                ):
                    physical_column_ids.append(int(arm_column.id))
                    physical_column_dtypes.append(str(
                        arm_column.dtype or "unknown"
                    ))
                    physical_column_shapes.append(tuple(
                        arm_column.shape or ()
                    ))
                    physical_column_values.append(arm_column)
                    physical_row_values.append(arm_value)
                physical_column_ids.append(int(tag_column.id))
                physical_column_dtypes.append("int64")
                physical_column_shapes.append(())
                physical_column_values.append(tag_column)
                physical_row_values.append(tag_value)
                sequence_receipt.append((
                    int(column),
                    tuple((str(arm.identity), int(arm_column.id),
                           int(arm_value.id)) for (arm, arm_column), arm_value
                          in zip(arms, arm_values, strict=True)),
                    int(tag_column.id), int(tag_value.id), int(target_id),
                ))
            if tag_columns:
                physical_destination = replace(
                    destination,
                    column_value_ids=tuple(physical_column_ids),
                    column_dtypes=tuple(physical_column_dtypes),
                    column_shapes=tuple(physical_column_shapes),
                )
                native_type_tag_sequence_receipt = tuple(sequence_receipt)
            function_name = self._sequence_helper_name(
                int(destination.sequence_id), str(operation),
            )
            lowering = (
                lower_sequence_append(
                    physical_destination,
                    function_name=function_name,
                    first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                )
                if operation == "append"
                else lower_sequence_add(
                    physical_destination,
                    function_name=function_name,
                    first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                )
            )
            destination_storage = self.sequence_storage_values[
                destination.sequence_id
            ]
            payload_width = len(destination.column_value_ids)
            call_arguments = (
                *(physical_column_values if tag_columns else
                  destination_storage[:payload_width]),
                *destination_storage[payload_width:],
                *(physical_row_values if tag_columns else mutation_values),
            )
        elif operation in {"extend", "replace"}:
            if mutation.argument_kind == "generator":
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence",
                    operation,
                    location,
                    "generator-backed extend requires the SSA iterator contract",
                ))
                return
            if mutation.argument_kind == "filtered_sequence":
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence",
                    operation,
                    location,
                    "filtered list-comprehension extend requires predicated compact materialization before eager insertion",
                ))
                return
            if len(mutation.argument_value_ids) != 1:
                self.shortfalls.append(SSALoweringShortfall(
                    "ssa-sequence", operation, location,
                    "extend currently requires one resident source sequence",
                ))
                return
            source_id = int(mutation.argument_value_ids[0])
            self.ensure_plan_callsite_result(
                source_id, location=f"{location}.source"
            )
            source = self._sequence_descriptor(
                source_id,
                policy=mutation.policy if operation == "replace" else "duplicates",
                writable=False,
                location=location,
            )
            if source is None:
                return
            _dtype_cells = self._cells(
                self._sequence_contract_cell(
                    int(destination.sequence_id)
                ),
                self._sequence_contract_cell(int(source.sequence_id)),
                *self.sequence_storage_values.get(
                    int(destination.sequence_id), ()
                ),
                *self.sequence_storage_values.get(
                    int(source.sequence_id), ()
                ),
            ) or (self._function_root(),)
            # c634: extend copies known rows of different numeric types;
            # its helper checks/converts each value. Those arenas do not
            # become physically equivalent merely because one is copied.
            typed_row_conversion = (
                operation == "extend"
                and tuple(destination.column_dtypes) != tuple(source.column_dtypes)
                and all(dtype not in {None, "", "unknown", "None"}
                        for dtype in (*destination.column_dtypes, *source.column_dtypes))
            )
            if not typed_row_conversion:
                concorded_dtypes = concord_sequence_row_dtypes(
                    self.function_name,
                    {
                        int(destination.sequence_id): destination.column_dtypes,
                        int(source.sequence_id): source.column_dtypes,
                    },
                    source=f"{location}: {operation} equivalence",
                    sources=_dtype_cells,
                    stage=self._stage(),
                )
                if tuple(destination.column_dtypes) != concorded_dtypes:
                    destination = replace(
                        destination, column_dtypes=concorded_dtypes
                    )
                    self.sequence_descriptors[
                        int(destination.sequence_id)
                    ] = destination
                if tuple(source.column_dtypes) != concorded_dtypes:
                    source = replace(source, column_dtypes=concorded_dtypes)
                    self.sequence_descriptors[int(source.sequence_id)] = source
            for descriptor in (destination, source):
                for value, dtype in zip(
                    self.sequence_storage_values[
                        int(descriptor.sequence_id)
                    ],
                    descriptor.column_dtypes if typed_row_conversion else concorded_dtypes,
                ):
                    if str(value.dtype or "unknown") in {
                        "", "None", "unknown",
                    }:
                        # Program: gen_sort.py (sorted-generator result) --
                        # value 7, the ``sorted_result`` arena argument.
                        # Wrong record: its ``ssa_value`` row was adopted
                        # 'unknown' at descriptor construction (no row dtype
                        # concorded yet); this write set only the resident,
                        # so settlement found resident float64 vs row
                        # 'unknown'.  Rule: the producer posts the change at
                        # the moment it makes it, derived from the cells the
                        # concorded dtype was read from; the resident is a
                        # view of its row.
                        value.dtype = str(dtype)
                        # ... and a descriptor column is an arena: the same
                        # revise posts ``arena`` when the schema names this
                        # value one of the descriptor's columns.
                        self._revise_value(
                            value, *_dtype_cells, stage=self._stage(),
                            physical=(
                                {"arena": True}
                                if int(value.id) in descriptor.column_value_ids
                                else KEEP_PHYSICAL
                            ),
                        )
            # Program: ``xs = []; for ...: xs.append(..)`` then
            # ``ys = sorted(xs)`` (scratch c135).  Wrong record: ys was born
            # heap-owned with an unknown row, its layout arrived with this
            # copy's concord, and the descriptor stayed FIXED, so the copy
            # ran a fixed capacity check (refused by C as unproven).  Rule:
            # the heap contract is stated the moment the layout exists, as
            # ``_heap_sequence_contract`` says -- here, for the destination.
            stated = self._heap_sequence_contract(destination)
            if stated is not destination:
                destination = stated
                self.sequence_descriptors[
                    int(destination.sequence_id)
                ] = destination
            # The source's layout may arrive with this concord too: a
            # private ``[]`` copied into a function's result at its return
            # site (A6 probe c996) is never written itself.
            stated = self._heap_sequence_contract(source)
            if stated is not source:
                source = stated
                self.sequence_descriptors[int(source.sequence_id)] = source
            destination_tags = self.sequence_native_type_tag_columns(
                int(destination.sequence_id)
            )
            source_tags = self.sequence_native_type_tag_columns(
                int(source.sequence_id)
            )
            if set(destination_tags) != set(source_tags):
                raise ValueError(
                    "sequence copy changes its declared heterogeneous "
                    "columns: "
                    f"destination={tuple(sorted(destination_tags))!r}, "
                    f"source={tuple(sorted(source_tags))!r}"
                )
            destination_union_columns = (
                self.sequence_native_value_union_columns(
                    int(destination.sequence_id)
                ) if destination_tags else {}
            )
            source_union_columns = (
                self.sequence_native_value_union_columns(
                    int(source.sequence_id)
                ) if source_tags else {}
            )
            column_value_maps = {}
            for column in sorted(destination_tags):
                destination_fact = destination_tags[column][2]
                source_fact = source_tags[column][2]
                destination_alternatives = tuple(
                    destination_fact.get("alternatives", ())
                    if isinstance(destination_fact, Mapping)
                    else getattr(destination_fact, "alternatives", ())
                )
                destination_table = dict(
                    destination_fact.get("tags", ())
                    if isinstance(destination_fact, Mapping)
                    else getattr(destination_fact, "tags", ())
                )
                source_alternatives = tuple(
                    source_fact.get("alternatives", ())
                    if isinstance(source_fact, Mapping)
                    else getattr(source_fact, "alternatives", ())
                )
                source_table = dict(
                    source_fact.get("tags", ())
                    if isinstance(source_fact, Mapping)
                    else getattr(source_fact, "tags", ())
                )
                if (
                    source_alternatives != destination_alternatives
                    or source_table != destination_table
                ):
                    raise ValueError(
                        "sequence copy requires the authoritative linked "
                        "native union table on both sides; no independently "
                        "minted dense tag or implicit subset remap is "
                        f"admissible in column {int(column)}: "
                        f"source={source_alternatives!r}, "
                        f"destination={destination_alternatives!r}"
                    )
            physical_destination = destination
            physical_source = source
            destination_physical_columns = []
            source_physical_columns = []
            physical_dtypes = []
            physical_shapes = []
            receipt = []
            destination_shapes = tuple(destination.column_shapes or (
                () for _value in destination.column_value_ids
            ))
            source_shapes = tuple(source.column_shapes or (
                () for _value in source.column_value_ids
            ))
            for column, (
                destination_column_id, source_column_id,
                destination_dtype, source_dtype,
                destination_shape, source_shape,
            ) in enumerate(zip(
                destination.column_value_ids, source.column_value_ids,
                destination.column_dtypes, source.column_dtypes,
                destination_shapes, source_shapes,
                strict=True,
            )):
                if column not in destination_tags:
                    if (
                        (str(destination_dtype) != str(source_dtype)
                         and not typed_row_conversion)
                        or tuple(destination_shape) != tuple(source_shape)
                    ):
                        raise ValueError(
                            "sequence copy changes a physical column ABI: "
                            f"column={column}"
                        )
                    destination_physical_columns.append(
                        self.sequence_storage_values[
                            int(destination.sequence_id)
                        ][column]
                    )
                    source_physical_columns.append(
                        self.sequence_storage_values[
                            int(source.sequence_id)
                        ][column]
                    )
                    physical_dtypes.append(str(destination_dtype))
                    physical_shapes.append(tuple(destination_shape))
                    continue
                destination_arms = destination_union_columns[column]
                source_arms = source_union_columns[column]
                if len(destination_arms) != len(source_arms):
                    raise ValueError(
                        "sequence copy changes its physical union arm count"
                    )
                arm_receipt = []
                for (destination_arm, destination_column), (
                    source_arm, source_column,
                ) in zip(destination_arms, source_arms, strict=True):
                    destination_state = (
                        str(destination_arm.identity),
                        str(destination_arm.storage),
                        str(destination_arm.dtype or "unknown"),
                        tuple(destination_arm.shape or ()),
                        tuple(destination_arm.storage_identity),
                    )
                    source_state = (
                        str(source_arm.identity),
                        str(source_arm.storage),
                        str(source_arm.dtype or "unknown"),
                        tuple(source_arm.shape or ()),
                        tuple(source_arm.storage_identity),
                    )
                    if destination_state != source_state:
                        raise ValueError(
                            "sequence copy changes an exact value-union arm "
                            f"ABI: column={column}, "
                            f"destination={destination_state!r}, "
                            f"source={source_state!r}"
                        )
                    destination_physical_columns.append(destination_column)
                    source_physical_columns.append(source_column)
                    physical_dtypes.append(destination_state[2])
                    physical_shapes.append(destination_state[3])
                    arm_receipt.append((
                        destination_state[0], int(destination_column.id),
                        int(source_column.id),
                    ))
                destination_tag = destination_tags[column][0]
                source_tag = source_tags[column][0]
                destination_physical_columns.append(destination_tag)
                source_physical_columns.append(source_tag)
                physical_dtypes.append("int64")
                physical_shapes.append(())
                receipt.append((
                    int(column), tuple(arm_receipt),
                    int(destination_tag.id), int(source_tag.id), (),
                ))
            if destination_tags:
                physical_destination = replace(
                    destination,
                    column_value_ids=tuple(
                        int(value.id) for value in destination_physical_columns
                    ),
                    column_dtypes=tuple(physical_dtypes),
                    column_shapes=tuple(physical_shapes),
                )
                physical_source = replace(
                    source,
                    column_value_ids=tuple(
                        int(value.id) for value in source_physical_columns
                    ),
                    column_dtypes=tuple(physical_dtypes),
                    column_shapes=tuple(physical_shapes),
                )
                native_type_tag_sequence_receipt = tuple(receipt)
            function_name = self._sequence_helper_name(
                int(destination.sequence_id), str(operation),
                int(source.sequence_id),
            )
            lowering = (lower_sequence_replace if operation == "replace" else lower_sequence_extend)(
                physical_destination,
                physical_source,
                function_name=function_name,
                first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
                column_value_maps=column_value_maps,
            )
            destination_storage = self.sequence_storage_values[
                destination.sequence_id
            ]
            source_storage = self.sequence_storage_values[source.sequence_id]
            destination_width = len(destination.column_value_ids)
            source_width = len(source.column_value_ids)
            call_arguments = tuple({
                value.id: value
                for value in (
                    *(destination_physical_columns if destination_tags else
                      destination_storage[:destination_width]),
                    *destination_storage[destination_width:],
                    *(source_physical_columns if source_tags else
                      source_storage[:source_width]),
                    *source_storage[source_width:],
                )
            }.values())
        else:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-sequence", operation, location,
                "unknown sequence mutation operator",
            ))
            return

        if not lowering.complete:
            self.shortfalls.extend(
                SSALoweringShortfall(
                    "ssa-sequence",
                    item.code.value,
                    location,
                    item.reason,
                )
                for item in lowering.shortfalls
            )
            return
        self._register_sequence_lowering(lowering)
        callee = lowering.entry.name
        # A DYNAMIC destination's entry takes its heap owner cell last
        # (``_lower_dynamic_sequence_mutation``); the owner is the exact
        # cell the descriptor names, never a positional stand-in.
        status = self.fresh_value(
            dtype="int", transform=REGION_CALL_RESULT,
            operands=tuple(call_arguments),
        )
        self.emit(
            Handler.Call,
            list(call_arguments),
            status,
            attributes={
                "callee": callee,
                "source_linked": True,
                "ssa_sequence_operation": operation,
                "sequence_id": int(destination.sequence_id),
                "source_effect_node_id": int(mutation.effect_node_id),
                "native_type_tag_sequence": native_type_tag_sequence_receipt,
                **({
                    "ssa_deferred_record_row": deferred_record_row,
                } if deferred_record_row is not None else {}),
                **({
                    "ssa_indexed_record_row": indexed_record_row_source,
                } if indexed_record_row_source is not None else {}),
                **({
                    "ssa_deferred_record_slots": (
                        len(call_arguments) - len(mutation.argument_value_ids),
                        deferred_record_slots,
                    ),
                } if deferred_record_slots else {}),
                **({
                    "extraction_identity": str(mutation.extraction_identity),
                } if mutation.extraction_identity is not None else {}),
            },
        )
        self.emit(
            Handler.Store,
            [
                status,
                self._sequence_status_address(
                    self.sequence_status_values[destination.sequence_id]
                ),
            ],
            attributes={"binding": "ssa_sequence_status"},
        )

    def _emit_child_row_birth(
        self,
        mutation: ControlSequenceMutation,
        destination: SSASequenceDescriptor,
        *,
        location: str,
    ) -> None:
        """Birth one row of a list of lists: a pool slice and its handle.

        Program: ``g = [[1, 2], [3, n]]; g[i][1]`` (corpus c732).  The outer
        list's one column holds row handles and each row is a fixed-stride
        slice of its child-table pool, as the keyed ``setdefault(k, [])`` row
        is.  The first row resets the outer list.  The new handle is the
        outer length; it must fit the outer capacity and its whole stride
        the pool (error runtime calls return, so the failure edge skips the
        initialization and the append).  The row is then selected exactly as
        a keyed lookup's row is, guarded by the allocation's room, so the
        row's own member appends and every later read address the slice.
        """

        pool = destination.child_table_pool
        # The row is the display the mutation's effect node names (its
        # value id, as a keyed lookup's row is); it is not an argument: the
        # row's own appends are produced after this allocation.
        row_id = int(mutation.effect_node_id)
        if pool is None:
            self.shortfalls.append(SSALoweringShortfall(
                "ssa-table", "child_row", location,
                f"list {int(destination.sequence_id)} has list rows but no "
                "child-table pool",
            ))
            return
        if int(mutation.display_member[1]) >> 16 == 0:
            self._emit_sequence_reset(int(destination.sequence_id))
        handle_dtype = "int64"
        storage = self.sequence_storage_values[int(destination.sequence_id)]
        width = len(destination.column_value_ids)
        outer_length_address = self.fresh_value(
            dtype="ptr", transform=ADDRESS, operands=(storage[width],),
        )
        self.emit(
            Handler.GetElementPtr,
            [storage[width], self.constant_value(0, storage[width])],
            outer_length_address,
            attributes={"binding": "ssa_child_row_length_address"},
        )
        outer_length = self.fresh_value(
            dtype="int64", transform=LOAD, operands=(outer_length_address,),
        )
        self.emit(
            Handler.Load, [outer_length_address], outer_length,
            attributes={"binding": "ssa_child_row_handle"},
        )
        new_handle = self.fresh_value(
            dtype=handle_dtype, transform=CONTROL_CAST, operands=(outer_length,),
        )
        self.emit(
            Handler.Cast, [outer_length], new_handle,
            attributes={"target_dtype": handle_dtype},
        )
        self._bind(
            int(new_handle.id), new_handle, BindingKind.SEQUENCE_RESULT,
            outer_length,
        )
        one = self.constant_value(1, outer_length, dtype="int64")
        next_length = self.fresh_value(
            dtype="int64", transform=CONTROL_EXPRESSION, operands=(outer_length,),
        )
        self.emit(Handler.Add, [outer_length, one], next_length)
        outer_capacity = storage[width + 1]
        stride = self.external_value(pool.row_stride_value_id)
        pool_capacity = self.external_value(pool.capacity_value_id)
        outer_room = self.fresh_value(
            dtype="bool", transform=CONTROL_PREDICATE,
            operands=(outer_length, outer_capacity),
        )
        self.emit(Handler.Lt, [outer_length, outer_capacity], outer_room)
        row_end = self.fresh_value(
            dtype="int64", transform=CONTROL_EXPRESSION,
            operands=(next_length, stride),
        )
        self.emit(Handler.Mul, [next_length, stride], row_end)
        pool_room = self.fresh_value(
            dtype="bool", transform=CONTROL_PREDICATE,
            operands=(row_end, pool_capacity),
        )
        self.emit(Handler.Le, [row_end, pool_capacity], pool_room)
        room = self.fresh_value(
            dtype="bool", transform=CONTROL_PREDICATE,
            operands=(outer_room, pool_room),
        )
        self.emit(
            Handler.LAnd, [outer_room, pool_room], room,
            attributes={"binding": "selected_child_allocation_bounds"},
        )
        # The row's view is pure address arithmetic over the new handle, so
        # it is built here where every later use of the row is dominated by
        # it; only the stores through it are guarded by ``room``.
        self.child_table_selections[row_id] = (pool, new_handle)
        if self._sequence_descriptor(
            row_id, policy="duplicates", writable=True, location=location,
        ) is None:
            return
        # A region that reads the row takes its first column's address.
        self._bind(
            row_id, self.sequence_storage_values[row_id][0],
            BindingKind.SEQUENCE_RESULT, new_handle,
        )
        room_pass = self.new_block("validation_pass")
        room_fail = self.new_block("validation_fail")
        joined = self.new_block("if_merge")
        self.conditional_branch(room, room_pass, room_fail)
        self.current = room_fail
        self.emit(Handler.Call, [], attributes={
            "callee": "turing_validation_error", "error_code": 75,
            "failure": "fixed_capacity_exhausted",
            "binding": "selected_child_allocation_bounds",
            "source_effect_node_id": int(mutation.effect_node_id),
        })
        self.branch(joined)
        self.current = room_pass
        guard = {"child_selection_guard_value_id": int(room.id)}
        pool_length = self.external_value(int(pool.length_value_id))
        child_length_address = self.fresh_value(
            dtype="ptr", transform=ADDRESS, operands=(pool_length, new_handle),
        )
        self.emit(
            Handler.GetElementPtr, [pool_length, new_handle],
            child_length_address,
            attributes={"binding": "ssa_child_table_length", **guard},
        )
        self.emit(
            Handler.Store,
            [self.constant_value(0, child_length_address), child_length_address],
            attributes={"binding": "ssa_child_table_initialize", **guard},
        )
        if pool.status_value_id is not None:
            pool_status = self.external_value(int(pool.status_value_id))
            child_status_address = self.fresh_value(
                dtype="ptr", transform=ADDRESS,
                operands=(pool_status, new_handle),
            )
            self.emit(
                Handler.GetElementPtr, [pool_status, new_handle],
                child_status_address,
                attributes={"binding": "ssa_child_table_status", **guard},
            )
            self.emit(
                Handler.Store,
                [self.constant_value(0, child_status_address),
                 child_status_address],
                attributes={"binding": "ssa_child_table_initialize", **guard},
            )
        from .ir_sequence_tables import lower_sequence_append

        lowering = lower_sequence_append(
            destination,
            function_name=self._sequence_helper_name(
                int(destination.sequence_id), "append",
            ),
            first_value_id=GLOBAL_MONOTONIC_IDS.peek(),
        )
        if not lowering.complete:
            self.shortfalls.extend(
                SSALoweringShortfall(
                    "ssa-sequence", item.code.value, location, item.reason,
                )
                for item in lowering.shortfalls
            )
            return
        self._register_sequence_lowering(lowering)
        call_arguments = (*storage, new_handle)
        status = self.fresh_value(
            dtype="int", transform=REGION_CALL_RESULT,
            operands=tuple(call_arguments),
        )
        self.emit(
            Handler.Call, list(call_arguments), status,
            attributes={
                "callee": lowering.entry.name,
                "source_linked": True,
                "ssa_sequence_operation": "append",
                "sequence_id": int(destination.sequence_id),
                "source_effect_node_id": int(mutation.effect_node_id),
            },
        )
        self.emit(
            Handler.Store,
            [status, self._sequence_status_address(
                self.sequence_status_values[int(destination.sequence_id)]
            )],
            attributes={"binding": "ssa_sequence_status"},
        )
        self.branch(joined)
        self.current = joined
        self.child_selection_validity[row_id] = room

    def lower_conditional(
        self, conditional: ConditionalBlock, *, path: str,
    ) -> None:
        """Lower one authored branch and publish its lexical merge values."""

        # A row read before an effect in either arm is loaded here, where
        # both arms are still ahead (``effect_preceding_row_reads``).
        self._load_reads_before_effect(conditional.source_node_id)
        predicate_sequence_id = None
        if conditional.entry_record_projections:
            handle_id = int(conditional.entry_record_projections[0][1])
            handle_value = self.external_value(handle_id, dtype="int")
            predicate = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(handle_value,),
            )
            self.emit(
                Handler.Ge,
                [handle_value, self.constant_value(0, handle_value)],
                predicate,
                attributes={
                    "binding": "optional_record_present",
                    "row_handle_value_id": handle_id,
                },
            )
        elif (
            conditional.predicate_expression is not None
            and conditional.predicate_expression.op == "value"
            and conditional.predicate_expression.value_id is not None
            and int(conditional.predicate_expression.value_id)
            in self.sequence_descriptors
        ):
            predicate_sequence_id = int(
                conditional.predicate_expression.value_id
            )
        elif int(conditional.predicate_value_id) in self.sequence_descriptors:
            predicate_sequence_id = int(conditional.predicate_value_id)
        if conditional.entry_record_projections:
            pass
        elif predicate_sequence_id is not None:
            descriptor = self.sequence_descriptors[predicate_sequence_id]
            length_cell = self.sequence_storage_values[
                predicate_sequence_id
            ][len(descriptor.column_value_ids)]
            length = self.fresh_value(
                dtype="int64", transform=LOAD,
                operands=(length_cell, predicate_sequence_id),
            )
            predicate = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE, operands=(length,),
            )
            self.emit(
                Handler.Load,
                [length_cell],
                length,
                attributes={
                    "binding": "resident_sequence_truthiness",
                    "sequence_id": predicate_sequence_id,
                },
            )
            self.emit(
                Handler.Gt,
                [length, self.constant_value(0, length)],
                predicate,
                attributes={
                    "binding": "resident_sequence_truthiness",
                    "sequence_id": predicate_sequence_id,
                },
            )
        elif int(conditional.predicate_value_id) in self.iterable_source_ids:
            predicate_source_id = int(conditional.predicate_value_id)
            length = self.expression_value(
                f"__iterable_extent_{predicate_source_id}__",
                location=f"{path}.truthiness",
            )
            predicate = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(length, predicate_source_id),
            )
            self.emit(
                Handler.Gt,
                [length, self.constant_value(0, length)],
                predicate,
                attributes={
                    "binding": "resident_iterable_truthiness",
                    "source_value_id": predicate_source_id,
                },
            )
        else:
            predicate = (
                self.lower_control_expression(
                    conditional.predicate_expression
                )
                if conditional.predicate_expression is not None
                else self.external_value(
                    conditional.predicate_value_id, dtype="bool"
                )
            )
        true_block = self.new_block("if_true")
        false_block = self.new_block("if_false")
        merge_block = self.new_block("if_merge")
        self.conditional_branch(
            predicate,
            true_block if conditional.expect_true else false_block,
            false_block if conditional.expect_true else true_block,
        )

        # Snapshot incoming scalar versions before lowering either arm.
        # Nested conditionals publish their merge by updating
        # ``external_values[initial_id]`` for the continuation.  Without this
        # boundary the child in the false arm can overwrite the parent's
        # incoming binding before the parent Phi is assembled, making both
        # parent inputs name the child result.  The deterministic SSA identity
        # history remains unchanged; this only preserves its path-specific
        # value object at the branch entry.
        carried_snapshots = {
            int(initial_value_id): self.external_value(int(initial_value_id))
            for _true_value_id, _false_value_id, initial_value_id,
            _merged_value_id in conditional.carried_aliases
        }
        # The whole-module storage-effect program has three nested guards
        # around edge_sources/edge_targets stores. A loop's entered version
        # is carried as arm 215/216, while the source initial is 37/38. The
        # child publishes Phi145/Phi169 under those arm identities; restoring
        # only source initials let both parent arms read the CHILD Phi, which
        # does not dominate the parent's false edge. Snapshot every ALREADY
        # bound arm identity at this boundary, through the existing snapshot
        # rows/writer. Never materialize a future branch-local definition.
        for true_id, false_id, _initial_id, _merged_id in conditional.carried_aliases:
            for arm_id in (int(true_id), int(false_id)):
                incumbent = self.external_values.get(arm_id)
                if incumbent is not None and arm_id not in carried_snapshots:
                    carried_snapshots[arm_id] = incumbent

        def nested_conditional_aliases(block: ControlBlock):
            if isinstance(block, ConditionalBlock):
                yield from block.carried_aliases
                yield from nested_conditional_aliases(block.body)
                if block.orelse is not None:
                    yield from nested_conditional_aliases(block.orelse)
            elif isinstance(block, SequenceBlock):
                for child in block.blocks:
                    yield from nested_conditional_aliases(child)
            elif isinstance(block, (LoopBlock, WhileBlock)):
                yield from nested_conditional_aliases(block.body)
                for child in block.terminal_controls:
                    yield from nested_conditional_aliases(child)
            elif isinstance(block, CallBlock):
                yield from nested_conditional_aliases(block.callee)
            elif isinstance(block, ParallelDeployment):
                for lane in block.lanes:
                    yield from nested_conditional_aliases(lane)
            elif isinstance(block, StateMachineTick):
                for _value, child in block.cases:
                    yield from nested_conditional_aliases(child)
                if block.default is not None:
                    yield from nested_conditional_aliases(block.default)

        nested_aliases = tuple(nested_conditional_aliases(conditional.body))
        if conditional.orelse is not None:
            nested_aliases += tuple(nested_conditional_aliases(
                conditional.orelse
            ))
        nested_initial_ids = {
            int(initial_id)
            for _true_id, _false_id, initial_id, _merged_id
            in nested_aliases
        }
        nested_merge_ids = {
            int(merged_id)
            for _true_id, _false_id, _initial_id, merged_id
            in nested_aliases
        }
        for true_id, false_id, _initial_id, _merged_id in (
            conditional.carried_aliases
        ):
            for value_id in (int(true_id), int(false_id)):
                if (
                    value_id in nested_initial_ids
                    and value_id not in nested_merge_ids
                    and value_id not in carried_snapshots
                ):
                    carried_snapshots[value_id] = self.external_value(value_id)
        # One ``carried_snapshot`` row per snapshotted id: the binding cell
        # current at branch entry, DERIVED from that cell and the
        # conditional construct's identity cell (plan 80 B2.3).
        conditional_cell = self._construct_cell(conditional.source_node_id)
        snapshot_cells = self._post_carried_snapshots(
            conditional_cell, carried_snapshots,
        )
        stage_before = self.active_stage
        self.active_stage = CONTROL_SSA_CONDITIONAL

        from .concordance_declarations import (
            SOURCE_OPTIONAL_GLYPH_CARRY,
            SourceOptionalGlyphCarry,
        )

        optional_facts = []
        for cell in conditional.optional_glyph_carry_cells:
            fact = self._book().page(SOURCE_OPTIONAL_GLYPH_CARRY).cell(
                cell.row, cell.column,
            )
            if not isinstance(fact, SourceOptionalGlyphCarry):
                raise ValueError(
                    f"{path}: optional glyph carry cell has no carry fact"
                )
            optional_facts.append((cell, fact))

        def lower_optional_arm(cell, fact, arm, *, arm_path: str):
            destination_id = int(fact.payload_sequence_value_id)
            if arm.presence is False:
                self.lower_sequence_mutation(
                    ControlSequenceMutation(
                        destination_id, "clear", (), destination_id,
                        policy="duplicates",
                        argument_kind="optional_glyph_absent",
                        source_contract_cell=cell,
                    ),
                    path=arm_path,
                )
            else:
                if arm.sequence_value_id is None:
                    raise ValueError(
                        f"{arm_path}: present optional glyph arm has no payload"
                    )
                source_id = int(arm.sequence_value_id)
                if source_id != destination_id:
                    self.lower_sequence_mutation(
                        ControlSequenceMutation(
                            destination_id, "replace", (source_id,),
                            destination_id, policy="duplicates",
                            argument_kind="optional_glyph_payload",
                            source_contract_cell=cell,
                        ),
                        path=arm_path,
                    )
            if arm.presence is None:
                inherited = self.optional_glyph_presence_by_value.get(
                    int(arm.value_id)
                )
                if inherited is None:
                    raise ValueError(
                        f"{arm_path}: inherited optional glyph presence "
                        f"{int(arm.value_id)} has no prior carry"
                    )
                return inherited
            presence = self.fresh_value(
                dtype="bool", transform=CONTROL_CONST,
                operands=(cell, arm.presence_source),
            )
            self.emit(
                Handler.Const, [], presence,
                attributes={
                    "value": bool(arm.presence),
                    "binding": "optional_glyph_presence_edge",
                    "payload_value_id": destination_id,
                },
            )
            return presence

        self.current = true_block
        true_return_edge_start = len(self.function_return_edges)
        for (
            origin_sequence_id, handle_id, result_id, column, dtype,
        ) in conditional.entry_record_projections:
            descriptor = self.sequence_descriptors.get(int(origin_sequence_id))
            if (
                descriptor is None
                or not 0 <= int(column) < len(descriptor.column_value_ids)
            ):
                self.shortfalls.append(SSALoweringShortfall(
                    "control",
                    "optional-record-projection",
                    path,
                    "optional record field has no resident origin column: "
                    f"sequence={origin_sequence_id} column={column}",
                ))
                continue
            source = self.external_value(
                int(descriptor.column_value_ids[int(column)]),
                dtype=str(dtype),
            )
            self.indexed_load(
                source,
                self.external_value(int(handle_id), dtype="int"),
                int(result_id),
                attributes={
                    "binding": "optional_record_field",
                    "origin_sequence_id": int(origin_sequence_id),
                    "column": int(column),
                },
                claim_provisional_definition=True,
            )
        # An arm that leaves through its own edge (``continue``/``break``
        # placed in the arm) never reaches the merge: nothing it binds may
        # reach the continuation.  The snapshot above covers only merged
        # identities; a non-falling-through arm restores every binding.
        # (``if retries < 2: dt = dt * 0.5; continue`` -- the arm published
        # ``dt`` = ``dt * 0.5`` and the fall-through call read it.)
        values_before_body = dict(self.external_values)
        self.lower(conditional.body, path=f"{path}.body")
        for value_id, expression in conditional.body_value_expressions:
            # Bind the reducer's exact arm identity. ``result_override``
            # prevents the expression lowerer from minting a parallel value;
            # ``lower_control_expression`` posts the operand-derived binding.
            result = self.produced_value(
                int(value_id), claim_provisional_definition=True,
                cause=(conditional_cell,),
            )
            self.lower_control_expression(expression, result_override=result)
        body_falls_through = (
            not self.current.successors
            or merge_block.name in self.current.successors
        )
        # Name-carried arms (decision 7.2): an arm that did not rebind the
        # name takes the entered version; an arm whose version the builder
        # cannot find is refused with ``Unresolved(NAME_ARM_VERSION_MISSING)``.
        # Program: ``a = k * 2; b = a; if k > 1: b = b - 1 else: a = a + 10;
        # return b, a``.  Wrong record: both names enter the branch as value
        # 2, and the arms were keyed by that shared initial id, so ``b``'s
        # true arm (7) overwrote ``a``'s and ``a`` merged as Phi(7, 2): (5, 5)
        # for (5, 6).  Rule: a carried arm belongs to its alias (its merge),
        # never to the entered value two names may share.
        true_carried = {}
        carried_name_sources: dict[int, list[Any]] = {}
        for position, (true_id, _false_id, initial_id, _merged_id) in enumerate(
            conditional.carried_aliases
        ):
            arm_value, arm_source = self._carried_name_arm(
                true_id, initial_id, carried_snapshots[int(initial_id)],
                snapshot_cells.get(int(initial_id)), path=f"{path}.body",
            )
            true_carried[position] = arm_value
            carried_name_sources[position] = [arm_source]
        # Field-carried merges name their arms as ``reducer_field_state``
        # cells; the arm's value is the version posted AT that cell, never a
        # graph-id lookup that may miss and default to the snapshot.
        carried_field_cells = tuple(conditional.carried_field_cells)
        carried_field_cells += (None,) * (
            len(conditional.carried_aliases) - len(carried_field_cells)
        )
        carried_field_sources: dict[int, list[Any]] = {}
        for position, (alias, cells) in enumerate(
            zip(conditional.carried_aliases, carried_field_cells)
        ):
            if cells is None:
                continue
            initial_id = int(alias[2])
            true_value, true_source = self._carried_field_arm(
                cells[0], cells[1], carried_snapshots[initial_id],
                path=f"{path}.body", arm_value_id=int(alias[0]),
            )
            true_carried[position] = true_value
            carried_field_sources[position] = [true_source]
        true_results = {
            int(result_id): self.external_value(int(true_id))
            for true_id, _false_id, result_id in conditional.result_aliases
        }
        true_optional_presence = {
            int(fact.merged_value_id): lower_optional_arm(
                cell, fact, fact.true_arm,
                arm_path=f"{path}.body.optional_glyph",
            )
            for cell, fact in optional_facts
        }
        for _cell, fact in optional_facts:
            presence = true_optional_presence[int(fact.merged_value_id)]
            arm_ids = {
                int(fact.true_arm.value_id),
                *(
                    (int(fact.true_arm.sequence_value_id),)
                    if fact.true_arm.sequence_value_id is not None else ()
                ),
            }
            for edge_block, _edge_values in self.function_return_edges[
                true_return_edge_start:
            ]:
                terminator = edge_block.instrs[-1]
                for slot, source_id in enumerate(
                    terminator.attributes.get("return_source_value_ids", ())
                ):
                    if source_id is not None and int(source_id) in arm_ids:
                        self.optional_glyph_return_presence_by_edge_slot.setdefault(
                            (str(edge_block.name), int(slot)), presence,
                        )
        for true_id, _false_id, initial_id, merged_id in (
            conditional.carried_sequence_aliases
        ):
            if int(true_id) != int(initial_id):
                self.lower_sequence_mutation(
                    ControlSequenceMutation(
                        int(initial_id), "replace", (int(true_id),),
                        int(merged_id), policy="duplicates",
                    ),
                    path=f"{path}.body",
                )
        true_exit = self.current
        if not true_exit.successors:
            self.branch(merge_block)
        if not body_falls_through:
            self._restore_view(values_before_body, conditional_cell)

        # Each arm starts with the same incumbent versions.  Retain the true
        # arm's exact values above, then restore these identities before
        # lowering the false arm so in-place SetAttr effects cannot leak across
        # the branch boundary.  RESTORED, from the snapshot cells.
        for snapshot_id, snapshot_value in carried_snapshots.items():
            if self.external_values.get(int(snapshot_id)) is not snapshot_value:
                self._bind(
                    int(snapshot_id), snapshot_value, BindingKind.RESTORED,
                    snapshot_cells.get(int(snapshot_id)), conditional_cell,
                )
        self.current = false_block
        false_return_edge_start = len(self.function_return_edges)
        values_before_orelse = dict(self.external_values)
        if conditional.orelse is not None:
            self.lower(conditional.orelse, path=f"{path}.orelse")
        for value_id, expression in conditional.orelse_value_expressions:
            result = self.produced_value(
                int(value_id), claim_provisional_definition=True,
                cause=(conditional_cell,),
            )
            self.lower_control_expression(expression, result_override=result)
        if self.current.successors and (
            merge_block.name not in self.current.successors
        ):
            self._restore_view(values_before_orelse, conditional_cell)
        false_results = {
            int(result_id): self.external_value(int(false_id))
            for _true_id, false_id, result_id in conditional.result_aliases
        }
        false_optional_presence = {
            int(fact.merged_value_id): lower_optional_arm(
                cell, fact, fact.false_arm,
                arm_path=f"{path}.orelse.optional_glyph",
            )
            for cell, fact in optional_facts
        }
        for _cell, fact in optional_facts:
            presence = false_optional_presence[int(fact.merged_value_id)]
            arm_ids = {
                int(fact.false_arm.value_id),
                *(
                    (int(fact.false_arm.sequence_value_id),)
                    if fact.false_arm.sequence_value_id is not None else ()
                ),
            }
            for edge_block, _edge_values in self.function_return_edges[
                false_return_edge_start:
            ]:
                terminator = edge_block.instrs[-1]
                for slot, source_id in enumerate(
                    terminator.attributes.get("return_source_value_ids", ())
                ):
                    if source_id is not None and int(source_id) in arm_ids:
                        self.optional_glyph_return_presence_by_edge_slot.setdefault(
                            (str(edge_block.name), int(slot)), presence,
                        )
        false_carried = {}
        for position, (_true_id, false_id, initial_id, _merged_id) in enumerate(
            conditional.carried_aliases
        ):
            arm_value, arm_source = self._carried_name_arm(
                false_id, initial_id, carried_snapshots[int(initial_id)],
                snapshot_cells.get(int(initial_id)), path=f"{path}.orelse",
            )
            false_carried[position] = arm_value
            carried_name_sources.setdefault(position, []).append(arm_source)
        for position, (alias, cells) in enumerate(
            zip(conditional.carried_aliases, carried_field_cells)
        ):
            if cells is None:
                continue
            initial_id = int(alias[2])
            false_value, false_source = self._carried_field_arm(
                cells[1], cells[0], carried_snapshots[initial_id],
                path=f"{path}.orelse", arm_value_id=int(alias[1]),
            )
            false_carried[position] = false_value
            carried_field_sources.setdefault(position, []).append(false_source)
        for _true_id, false_id, initial_id, merged_id in (
            conditional.carried_sequence_aliases
        ):
            if int(false_id) != int(initial_id):
                self.lower_sequence_mutation(
                    ControlSequenceMutation(
                        int(initial_id), "replace", (int(false_id),),
                        int(merged_id), policy="duplicates",
                    ),
                    path=f"{path}.orelse",
                )
        false_exit = self.current
        if not false_exit.successors:
            self.branch(merge_block)

        self.current = merge_block
        for cell, fact in optional_facts:
            merged_id = int(fact.merged_value_id)
            true_presence = true_optional_presence[merged_id]
            false_presence = false_optional_presence[merged_id]
            presence = self.fresh_value(
                dtype="bool", transform=PHI_CONDITIONAL,
                operands=(cell, true_presence, false_presence, predicate),
            )
            presence.accounting.update({
                "ssa_optional_presence": True,
                "ssa_optional_payload_id": merged_id,
                "optional_glyph_sequence": True,
            })
            self.emit(
                Handler.Phi, [true_presence, false_presence], presence,
                attributes={
                    "incoming_blocks": (
                        true_exit.name, false_exit.name,
                    ),
                    "binding": "optional_glyph_presence",
                    "payload_value_id": merged_id,
                },
            )
            self.optional_glyph_presence_by_value[merged_id] = presence
        for _true_id, _false_id, result_id in conditional.result_aliases:
            true_value = true_results[int(result_id)]
            false_value = false_results[int(result_id)]
            merged = self.produced_value(
                int(result_id), claim_provisional_definition=True,
                cause=(true_value, false_value, predicate),
            )
            if merged.dtype in {None, "unknown"}:
                # Program: ``if c == 2: s = n else: s = n * 0.5`` (corpus
                # c770).  Wrong record: the merge took its TRUE arm's class,
                # so a float arm could be narrowed to int64.
                # Rule: a scalar numeric join promotes (``_numeric_join``).
                merged.dtype = self._numeric_join(
                    (true_value, false_value),
                ) or true_value.dtype or false_value.dtype
            true_value, false_value = self._numeric_join_arms(
                merged.dtype if not tuple(merged.shape or ()) else None,
                ((true_exit, true_value), (false_exit, false_value)),
            )
            if (
                int(result_id) not in self.region_value_meta
                and tuple(true_value.shape) == tuple(false_value.shape)
                and true_value.dtype == false_value.dtype
            ):
                merged.shape = tuple(true_value.shape)
                merged.device = true_value.device
            self._revise_value(merged, true_value, false_value)
            self.emit(
                Handler.Phi, [true_value, false_value], merged,
                attributes={
                    "incoming_blocks": (true_exit.name, false_exit.name),
                    "binding": "conditional_result",
                    # The merge of a short-circuit operator IS the operator.
                    **({
                        "structural_operation": "boolop",
                        "semantic_family": conditional.short_circuit_operator,
                    } if conditional.short_circuit_operator else {}),
                },
            )
            self.merge_native_type_tags(
                int(result_id), merged,
                (int(_true_id), int(_false_id)),
                (true_exit.name, false_exit.name),
                binding="conditional_native_type_tag",
            )
            if (
                int(_true_id) in self.sequence_descriptors
                and int(_false_id) in self.sequence_descriptors
                and int(result_id) in conditional.sequence_handle_results
            ):
                self._lower_sequence_handle_merge(
                    int(_true_id), int(_false_id), merged,
                    incoming_blocks=(true_exit.name, false_exit.name),
                )
            # An optional keyed lookup changes whether its child handle is
            # present; it does not create another child arena.  Preserve the
            # exact pool on the merged handle so guarded iteration obtains
            # its extent and elements from the resident table.
            selections = tuple(
                self.child_table_selections[int(arm_id)]
                for arm_id in (int(_true_id), int(_false_id))
                if int(arm_id) in self.child_table_selections
            )
            if selections and len({id(pool) for pool, _ in selections}) == 1:
                pool, _handle = selections[0]
                self.child_table_selections[int(result_id)] = (pool, merged)
        for position, ((
            true_value_id, false_value_id, initial_value_id, merged_value_id,
        ), field_cells) in enumerate(
            zip(conditional.carried_aliases, carried_field_cells)
        ):
            initial = carried_snapshots[int(initial_value_id)]
            true_value = true_carried[position]
            false_value = false_carried[position]
            # The Phi's operands on the book: each arm's source cell (its
            # binding, or the snapshot cell when it did not write) and the
            # snapshot cell -- PHI_CONDITIONAL (plan 80 B2.3).
            phi_operands = (
                *carried_name_sources.get(position, ()),
                snapshot_cells.get(int(initial_value_id)),
                true_value, false_value, predicate,
            )
            if int(merged_value_id) in {
                int(true_value.id), int(false_value.id),
            }:
                # Graph identities may reuse the selected arm's SetAttr id as
                # the enclosing join id.  They are the same source version,
                # but the join is a distinct SSA definition.  Allocate that
                # definition separately and retain the graph id as provenance
                # instead of emitting a self-referential Phi.
                merged = self.fresh_value(
                    dtype=initial.dtype, shape=initial.shape,
                    transform=PHI_CONDITIONAL, operands=phi_operands,
                )
                merged.accounting.update({
                    "source_value_id": int(merged_value_id),
                    "ssa_conditional_write_version": True,
                })
            else:
                merged = SSAValue(
                    int(merged_value_id),
                    dtype=initial.dtype,
                    shape=initial.shape,
                )
                # The join adopts the graph's merge id; its row derives from
                # the same operands the Phi is made from.
                self._value_cell(merged, *phi_operands)
            # The version that stood before the branch.  The planner spells it
            # ``initial_value_id``; when no region ever produced that spelling
            # (``NO_PRODUCER_AT_USE``: ``external_value`` handed back a stand-in
            # formal) the entered version is the arm value that was already
            # bound when the branch was entered -- the arm that did not
            # rebind the name (``_carried_name_arm``).  N=2 orbital dt system,
            # ``_apply_energy_sidechain``: alias (65, 55, 64, 66), 64 never
            # produced, 55 the first conditional's merge.
            entered = initial
            if self._is_stand_in(initial_value_id):
                candidates = [
                    arm_value for arm_id, arm_value in (
                        (true_value_id, true_value),
                        (false_value_id, false_value),
                    )
                    if values_before_body.get(int(arm_id)) is arm_value
                ]
                if len(candidates) == 1:
                    entered = candidates[0]
            preserved_binding_sources = self._conditional_shared_sources(
                int(merged_value_id), (initial_value_id, true_value_id, false_value_id),
            )
            self.emit(
                Handler.Phi,
                [true_value, false_value],
                merged,
                attributes={
                    "incoming_blocks": (true_exit.name, false_exit.name),
                    "binding": "conditional_carried",
                    "initial_value_id": self._phi_initial_binding(
                        initial_value_id, entered, merged,
                        stage=CONTROL_SSA_CONDITIONAL,
                    ),
                    "initial_spelled_value_id": int(initial_value_id),
                    # Each arm's SSA identity as lowered here.  A later
                    # settlement that replaces an arm with a resident value
                    # (a folded field read becoming the constructor argument)
                    # leaves a different id at that position; the
                    # continuation pass preserves such an arm when another
                    # name binding in this scope owns the resident.
                    "arm_lowered_value_ids": (
                        int(true_value.id), int(false_value.id),
                    ),
                    "arm_lowered_binding_scope": self.lexical_read_scope,
                    "arm_lowered_merge_id": int(merged_value_id),
                    "preserved_name_binding_value_ids": tuple(sorted(preserved_binding_sources)),
                    # The same receipt by Phi operand position: an arm's SSA
                    # value need not carry its graph id (a loop induction is
                    # a header Phi with a fresh id), so readers of the
                    # operands match positions, never ids across the spaces.
                    "preserved_name_binding_arm_positions": tuple(
                        position
                        for position, arm_id in enumerate(
                            (true_value_id, false_value_id)
                        )
                        if int(arm_id) in preserved_binding_sources
                    ),
                    **({"preserved_name_binding_scope": self.lexical_read_scope,
                        "preserved_name_binding_merge_id": int(merged_value_id)}
                    if preserved_binding_sources else {}),
                },
            )
            merged_type_tag = self.merge_native_type_tags(
                int(merged_value_id), merged,
                (int(true_value_id), int(false_value_id)),
                (true_exit.name, false_exit.name),
                binding="conditional_carried_native_type_tag",
            )
            # The merge IS the reducer's MERGED cell: publish the Phi as that
            # cell's SSA version, derived from the two arm sources (each arm's
            # version cell, or the arm cell itself when it did not write) and
            # the merged cell.  An arm recorded ARM_VERSION_MISSING has no
            # source; the merge then posts nothing rather than post a
            # snapshot as an arm.
            if field_cells is not None and field_cells[2] is not None:
                sources = carried_field_sources.get(position, [])
                if len(sources) == 2 and all(
                    isinstance(source, Ref) for source in sources
                ):
                    self._publish_field_version(
                        field_cells[2], merged,
                        (sources[0], sources[1], field_cells[2]),
                    )
            # Every source identity participating in this join denotes the
            # merged version in the lexical continuation.  A later region may
            # legitimately define one of the arm ids again; lowering that
            # region overwrites the entry as usual.  Until then, retaining a
            # branch-local arm value here makes a following conditional read
            # a value that does not dominate it (and silently skips the first
            # conditional on the opposite arm).
            protected_sources = frozenset().union(
                *self.protected_loop_alias_sources
            ) if self.protected_loop_alias_sources else frozenset()
            # A merge versions a BINDING, not every name sharing its input.
            # Trapped in the fused storage kernel: name_binding attributes
            # 366 to both incumbent and proposed, but merge 374 to proposed
            # alone. Publishing 374 under 366 made proposed != incumbent
            # read Phi374 twice and silently suppress every worklist update.
            # Use those existing lexical facts to retain other bindings'
            # exact source value; the merge's own identity is still published.
            protected_sources |= preserved_binding_sources
            published = {int(merged_value_id): merged}
            if int(initial_value_id) not in protected_sources:
                published[int(initial_value_id)] = merged
            for arm_value_id in (true_value_id, false_value_id):
                if int(arm_value_id) not in protected_sources:
                    published[int(arm_value_id)] = merged
            if (
                os.environ.get("TURING_DEBUG_LOOP_ALIAS_PUBLICATION")
                and protected_sources
                and protected_sources.intersection({
                    int(true_value_id), int(false_value_id),
                    int(initial_value_id), int(merged_value_id),
                })
            ):
                print(
                    "DEBUG-LOOP-ALIAS-PUBLICATION "
                    f"fn={self.function_name} path={path} "
                    f"alias={(int(true_value_id), int(false_value_id), int(initial_value_id), int(merged_value_id))!r} "
                    f"protected={tuple(sorted(protected_sources))!r} "
                    f"published={tuple(sorted(published))!r} "
                    f"merged_ssa={int(merged.id)}",
                    file=sys.stderr,
                    flush=True,
                )
            # CONDITIONAL_MERGE: every published id derives from the Phi.
            self._rebind_view(
                published, BindingKind.CONDITIONAL_MERGE, merged, conditional_cell,
            )
            if merged_type_tag is not None:
                for published_id in published:
                    self.native_value_type_tags[int(published_id)] = (
                        merged_type_tag
                    )
        for _true_id, _false_id, initial_id, merged_id in (
            conditional.carried_sequence_aliases
        ):
            resident = self.external_value(int(initial_id))
            self._bind(
                int(merged_id), resident, BindingKind.CONDITIONAL_MERGE,
                self._binding_cell(int(initial_id)), conditional_cell,
            )
        self.active_stage = stage_before

    def _lower_sequence_handle_merge(
        self, true_id: int, false_id: int, merged: SSAValue, *,
        incoming_blocks: tuple[str, str],
    ) -> None:
        """A list merged from two arms is a handle onto the taken arm's storage.

        Program: ``a = [n, 1]; if n > 2: t = a else: t = [7, n, 2]`` then
        ``t.append(9); return len(a) * 100 + len(t)`` (c736).  Python's ``t``
        is the same list object as the taken arm, so a change through ``t``
        shows through ``a`` and the reverse.  Wrong record: the merge owned
        storage of its own and each arm was copied into it, or only its data
        arena was selected and its length/capacity were fresh formals nothing
        wrote.  Rule: the merge owns no cell.  Every storage member of the
        descriptor (data columns, length cell, capacity cell, status cell and
        the heap owner of a DYNAMIC list) is one Phi of the two arms' members,
        so a read, store, append or reserve through the merge lands in the
        taken arm's own cells, exactly as a selected child row view addresses
        pool cells.  The data arena Phi is already emitted (``merged``).
        Arms that disagree about the storage contract (width, policy, row
        shape, FIXED/DYNAMIC) are refused by name: the settled component is
        one contract (``_settle_linked_dynamic_sequences``).
        """

        arm_ids = (int(true_id), int(false_id))
        true_arm, false_arm = (self.sequence_descriptors[i] for i in arm_ids)
        # The merge is one list, so its arms have ONE row type.  An arm with
        # no rows to state it (``t = []``, c732) has not concorded one yet;
        # the other arm's is its contract.  Two stated types that differ are
        # refused below with the rest of the storage contract.
        unstated = {"", "None", "unknown"}
        pair = (tuple(true_arm.column_dtypes), tuple(false_arm.column_dtypes))
        if pair[0] != pair[1] and len(pair[0]) == len(pair[1]):
            settled = tuple(
                right if str(left) in unstated else left
                for left, right in zip(*pair)
                if str(left) in unstated or str(right) in unstated
                or left == right
            )
            if len(settled) == len(pair[0]):
                for arm_id, arm in zip(arm_ids, (true_arm, false_arm)):
                    if tuple(arm.column_dtypes) == settled:
                        continue
                    self._sequence_descriptor(
                        arm_id,
                        policy="unique" if arm.key_columns else "duplicates",
                        writable=bool(arm.writable),
                        location=f"{self.function_name}.sequence_handle_merge",
                        column_count=len(arm.column_value_ids),
                        column_dtypes=settled,
                    )
                true_arm, false_arm = (
                    self.sequence_descriptors[i] for i in arm_ids
                )
        true_cells, false_cells = (
            self.sequence_storage_values[i] for i in arm_ids
        )
        merged_id = int(merged.id)
        if merged_id in self.sequence_descriptors:
            raise ValueError(
                f"list {merged_id} is a branch merge that already owns a "
                "sequence descriptor; a merge is a handle and owns no storage"
            )

        def contract(descriptor):
            return (
                len(descriptor.column_value_ids), tuple(descriptor.key_columns),
                tuple(descriptor.column_dtypes),
                tuple(descriptor.column_shapes),
                descriptor.capacity_policy,
                descriptor.heap_owner_value_id is not None,
                descriptor.status_address_id is not None,
                descriptor.live_flags_value_id is not None,
                descriptor.child_table_pool is not None,
                descriptor.writable,
            )

        if (
            contract(true_arm) != contract(false_arm)
            or len(true_cells) != len(false_cells)
            or true_arm.live_flags_value_id is not None
            or true_arm.child_table_pool is not None
            or true_arm.key_columns
        ):
            raise ValueError(
                f"list {merged_id} is merged from branches whose lists "
                f"{arm_ids!r} disagree about their storage contract "
                f"({contract(true_arm)!r} vs {contract(false_arm)!r}); a list "
                "merged from branches is a handle onto the taken arm's "
                "storage, which needs one contract (width, row layout, "
                "FIXED or DYNAMIC) for both"
            )
        book = self._book()
        selected: dict[int, SSAValue] = {int(true_cells[0].id): merged}
        # The data arena Phi is the first member of the handle: it is the
        # same kind of cell as the arm's, so it declares the arm's physical
        # fields (arena/span, element dtype) and heap contract.
        true_data_cell = book.latest_ref(
            SSA_VALUE, (self._scope(), int(true_cells[0].id)),
        )
        true_data_fact = (
            None if true_data_cell is None
            else book.page(SSA_VALUE).cell(
                true_data_cell.row, true_data_cell.column,
            )
        )
        if true_data_fact is not None:
            merged.dtype = true_cells[0].dtype
            merged.shape = tuple(true_cells[0].shape or ()) or (1,)
            merged.accounting = {
                **dict(merged.accounting or {}),
                **{
                    key: value
                    for key, value in dict(true_cells[0].accounting or {}).items()
                    if key in {"heap_element_dtype", "sequence_row_shape"}
                },
            }
            self._revise_value(
                merged, true_cells[0], false_cells[0],
                physical={
                    name: getattr(true_data_fact, name)
                    for name in ("physical_dtype", "storage", "rank", "arena")
                },
            )

        def member_phi(true_member, false_member):
            cell = book.latest_ref(
                SSA_VALUE, (self._scope(), int(true_member.id)),
            )
            fact = (
                None if cell is None
                else book.page(SSA_VALUE).cell(cell.row, cell.column)
            )
            # A cell is selected by ADDRESS: a formal cell is a pointer to
            # its storage, but a scalar-shaped Phi would copy the value it
            # holds and every store through the handle (a reserve's new
            # capacity, a new arena pointer) would land in that copy.  The
            # Phi of a cell is a one-element span, as the heap owner is.  The
            # predicate is no operand: the Phi law inherits its operands'
            # storage and a bool's is scalar.
            value = self.fresh_value(
                dtype=true_member.dtype,
                shape=tuple(true_member.shape or ()) or (1,),
                transform=PHI_CONDITIONAL,
                operands=(true_member, false_member),
                physical=(
                    {
                        name: getattr(fact, name)
                        for name in (
                            "physical_dtype", "storage", "rank", "arena",
                        )
                    }
                    if fact is not None else None
                ),
            )
            self.emit(
                Handler.Phi, [true_member, false_member], value,
                attributes={
                    "incoming_blocks": tuple(incoming_blocks),
                    "binding": "sequence_handle_member",
                    "sequence_value_id": merged_id,
                },
            )
            return value

        def name_member(value, position):
            # The handle's member is the descriptor's physical address, as
            # a formal member is: it names its sequence and position.
            value.accounting = {
                **dict(value.accounting or {}),
                "compiler_frame_storage": str(self.function_name),
                "compiler_frame_sequence_id": merged_id,
                "compiler_frame_member": int(position),
                **self._posted_physical_accounting(
                    value, ("sequence_arena", "program_abi_rank"),
                ),
            }

        for true_member, false_member in zip(true_cells[1:], false_cells[1:]):
            selected[int(true_member.id)] = member_phi(true_member, false_member)
        members = tuple(selected[int(cell.id)] for cell in true_cells)
        for position, member in enumerate(members):
            name_member(member, position)
        status = None
        true_status = self.sequence_status_values.get(arm_ids[0])
        false_status = self.sequence_status_values.get(arm_ids[1])
        if (true_status is None) != (false_status is None):
            raise ValueError(
                f"list {merged_id} is merged from branches whose lists "
                f"{arm_ids!r} disagree about owning a status cell"
            )
        if true_status is not None:
            status = member_phi(true_status, false_status)
            name_member(status, len(members))
        owner = None
        if true_arm.heap_owner_value_id is not None:
            owner = members[-1]
            self.sequence_heap_owners[merged_id] = owner
            for column in members[:len(true_arm.column_value_ids)]:
                column.accounting = {
                    **dict(column.accounting or {}),
                    "heap_owner_value_id": int(owner.id),
                }
        columns = len(true_arm.column_value_ids)
        descriptor = replace(
            true_arm,
            sequence_id=merged_id,
            column_value_ids=tuple(int(m.id) for m in members[:columns]),
            length_address_id=int(members[columns].id),
            capacity_value_id=int(members[columns + 1].id),
            status_address_id=None if status is None else int(status.id),
            heap_owner_value_id=None if owner is None else int(owner.id),
        )
        self.sequence_descriptors[merged_id] = descriptor
        self.sequence_storage_values[merged_id] = members
        if status is not None:
            self.sequence_status_values[merged_id] = status

    def _publish_loop_result_ports(
        self,
        loop: LoopBlock | WhileBlock,
        *,
        header: BasicBlock,
        exit_block: BasicBlock,
        carried: list[tuple[int, int, SSAValue, SSAValue, SSAValue]],
        break_edges: tuple[
            tuple[BasicBlock, tuple[SSAValue, ...], tuple[SSAValue, ...]], ...
        ],
        break_bound: tuple[tuple[int, int], ...] = (),
        break_bound_initials: Mapping[int, SSAValue] | None = None,
    ) -> None:
        """Define authored LoopResult ids with edge-correct exit Phis."""

        # A port continues one authored binding; the carried entry it exits
        # is the one the book attributes that binding to.  Value ids do not
        # decide: two bindings can share an updated id (``total = w``) or an
        # initial id (``second = value``).
        from .identity_concordance import current_identity_book

        book = current_identity_book()
        loop_node = getattr(loop, "source_loop_node_id", None)
        entry_bindings = [
            tuple(book.page("loop_carried_binding").latest((
                self.lexical_read_scope, int(loop_node),
                int(updated_id), int(initial_id),
            )) or ())
            if self.lexical_read_scope is not None and loop_node is not None
            else ()
            for updated_id, initial_id, *_rest in carried
        ]

        def carried_entry_of(port_id: int, initial_id: int, updated_id: int):
            if self.lexical_read_scope is None or loop_node is None:
                # No book facts exist for a program the reducer never saw.
                return next((
                    (index, entry[4]) for index, entry in enumerate(carried)
                    if int(entry[0]) == int(updated_id)
                    and int(entry[1]) == int(initial_id)
                ), None)
            binding = book.page("loop_result_port_binding").latest(
                (self.lexical_read_scope, int(port_id))
            )
            if binding is None:
                raise ValueError(
                    f"{self.function_name}: loop {loop_node} result port "
                    f"{port_id} has no loop_result_port_binding row"
                )
            owners = [
                index for index, bindings in enumerate(entry_bindings)
                if binding in bindings
            ]
            if len(owners) > 1:
                raise ValueError(
                    f"{self.function_name}: binding {binding!r} is carried by "
                    f"loop {loop_node} entries {owners!r}"
                )
            return (owners[0], carried[owners[0]][4]) if owners else None

        def port_cells(port_id: int) -> tuple:
            """The port's ``loop_result_port_binding`` and
            ``loop_carried_entry`` cells, when the book has them."""

            if self.lexical_read_scope is None or loop_node is None:
                return ()
            port_binding = book.latest_ref(
                LOOP_RESULT_PORT_BINDING, (self.lexical_read_scope, int(port_id)),
            )
            binding = book.page(LOOP_RESULT_PORT_BINDING).latest(
                (self.lexical_read_scope, int(port_id))
            )
            entry_cell = None if binding is None else book.latest_ref(
                LOOP_CARRIED_ENTRY,
                (str(self.tensor_shape_concordance_scope), int(loop_node), str(binding)),
            )
            return (port_binding, entry_cell)

        def publish_port(port_id: int, port: SSAValue, *cells: Any) -> None:
            """LOOP_RESULT_PORT binding plus the ``carried_port_value`` row:
            the exit Phi's ``ssa_value`` cell, DERIVED(the port's binding
            row, its carried entry, the Phi cell)."""

            sources = self._cells(*port_cells(port_id), port, *cells)
            row = (self._scope(), int(port_id))
            phi_cell = self._value_cell(port)
            existing = book.latest_ref(CARRIED_PORT_VALUE, row)
            if existing is None or (
                book.pages[CARRIED_PORT_VALUE.name].cells.get(
                    (row, existing.column)
                ) != phi_cell
            ):
                book.post(
                    CARRIED_PORT_VALUE, row, phi_cell,
                    stage=CONTROL_SSA_LOOP,
                    provenance=Derived(sources),
                    mode=Mode.REVISE,
                )
            self._bind(
                int(port_id), port, BindingKind.LOOP_RESULT_PORT,
                book.latest_ref(CARRIED_PORT_VALUE, row), *cells,
            )
            port_values[int(port_id)] = port
        carried_ports = getattr(self, "_carried_port_groups", None)
        if carried_ports is None:
            carried_ports = {}
            self._carried_port_groups = carried_ports
        port_values = getattr(self, "_carried_port_values", None)
        if port_values is None:
            port_values = {}
            self._carried_port_values = port_values

        self.current = exit_block
        for port_id, initial_id, updated_id in getattr(
            loop, "result_ports", ()
        ):
            carried_entry = carried_entry_of(
                int(port_id), int(initial_id), int(updated_id),
            )
            if carried_entry is None:
                continue
            carried_index, normal_value = carried_entry
            incoming_blocks = [header.name]
            incoming_values = [normal_value]
            for predecessor, edge_values, _bound_values in break_edges:
                incoming_blocks.append(predecessor.name)
                incoming_values.append(edge_values[carried_index])

            # A post-loop call may have exposed this authored identity as a
            # provisional formal while structural blocks were assembled.  Use
            # that exact SSAValue as the definition so already-built operands
            # become resident, then retire its provisional ABI role.
            port = self.produced_value(
                int(port_id),
                dtype=str(normal_value.dtype or "unknown"),
                claim_provisional_definition=True,
                cause=tuple(incoming_values),
            )
            existing_definition = next((
                (block.name, instruction_index)
                for block in self.blocks.values()
                for instruction_index, instruction in enumerate(block.instrs)
                if instruction.res is not None
                and int(instruction.res.id) == int(port.id)
            ), None)
            if existing_definition is not None:
                # A carried body's latest lexical version can share the
                # LoopResult's graph spelling. It is already a definition and
                # cannot also become the exit Phi: doing so moves its only
                # numeric-id definition into the future of body uses. Version
                # the exit and retain the authored port id in the exact map
                # below. Only a producerless provisional formal is claimed in
                # place by produced_value above.
                previous_id = int(port.id)
                previous_port = port
                port = self.fresh_value(
                    dtype=str(normal_value.dtype or port.dtype or "unknown"),
                    shape=tuple(normal_value.shape or port.shape),
                    transform=LOOP_RESULT_VERSION,
                    operands=(previous_port, normal_value),
                )
                port.accounting.update({
                    "source_value_id": int(port_id),
                    "ssa_loop_result_version": True,
                    "versioned_from_value_id": previous_id,
                    "versioned_from_definition": existing_definition,
                    "tie_policy": "incumbent_body_definition",
                })
                self._bind(
                    int(port_id), port, BindingKind.LOOP_RESULT_PORT,
                    previous_port, normal_value,
                )
            port.shape = tuple(normal_value.shape)
            port.device = normal_value.device
            self._revise_value(port, normal_value)
            self.emit(
                Handler.Phi,
                incoming_values,
                port,
                attributes={
                    "incoming_blocks": tuple(incoming_blocks),
                    "binding": "loop_result_port",
                    "initial_value_id": self._phi_initial_binding(
                        initial_id, carried[carried_index][2], port,
                        stage=CONTROL_SSA_LOOP,
                    ),
                    "initial_spelled_value_id": int(initial_id),
                    "updated_value_id": int(updated_id),
                },
            )
            group = carried_ports.setdefault(
                (int(initial_id), int(updated_id)), set()
            )
            group.add(int(port_id))
            port.accounting["carried_port_ids"] = tuple(dict.fromkeys((
                *(port.accounting.get("carried_port_ids") or ()),
                *sorted(int(item) for item in group),
            )))
            # Nested loops can expose successive LoopResult spellings for
            # the same carried binding.  Once the enclosing loop exits, every
            # spelling in that equivalence class denotes the enclosing exit
            # value.  Rebind the lookup table (without rewriting operands
            # already emitted inside the loop) so post-loop expressions that
            # retained an inner port id cannot bypass the outer zero-trip
            # path and consume a non-dominating inner Phi.
            for equivalent_port_id in group:
                publish_port(int(equivalent_port_id), port, *incoming_values)
        # A break-bound name: zero-trip / fall-through exits keep the
        # pre-loop value; each break edge carries the value its site bound.
        for bound_index, (port_id, initial_id) in enumerate(break_bound):
            normal_value = (
                (break_bound_initials or {}).get(int(initial_id))
                or self.external_value(int(initial_id))
            )
            incoming_blocks = [header.name]
            incoming_values = [normal_value]
            for predecessor, _edge_values, bound_values in break_edges:
                incoming_blocks.append(predecessor.name)
                incoming_values.append(bound_values[bound_index])
            port = self.produced_value(
                int(port_id),
                dtype=str(normal_value.dtype or "unknown"),
                claim_provisional_definition=True,
                cause=tuple(incoming_values),
            )
            self.emit(
                Handler.Phi,
                incoming_values,
                port,
                attributes={
                    "incoming_blocks": tuple(incoming_blocks),
                    "binding": "loop_result_port",
                    "result_kind": "break_bound",
                    "initial_value_id": self._phi_initial_binding(
                        initial_id, normal_value, port,
                        stage=CONTROL_SSA_LOOP,
                    ),
                    "initial_spelled_value_id": int(initial_id),
                    "updated_value_id": int(initial_id),
                },
            )
            publish_port(int(port_id), port, *incoming_values)

    def _bind_loop_result_ports_inside_body(
        self, loop: LoopBlock | WhileBlock,
    ) -> tuple[tuple[int, bool, int | None], ...]:
        """Resolve an exit spelling to its live carried version in the loop.

        ProcessGraph may retain a ``LoopResult`` identity for a lexical read
        authored late in the loop body. Its SSA definition belongs at the
        exit, but that does not make the body read a future exit Phi: inside
        the loop the same spelling denotes the current ``updated_value_id``.
        Record and temporarily install that alias while the body and latch
        condition are lowered. The exit publication restores ownership of the
        result id afterward.
        """

        saved = []
        saved_ids: set[int] = set()
        for port_id, _initial_id, updated_id in getattr(loop, "result_ports", ()):
            port_id = int(port_id)
            updated_id = int(updated_id)
            # Include every pre-existing spelling between the public result
            # and its storage root. A composed graph may feed a body region
            # with an earlier spelling from this chain instead of the final
            # LoopResult id. The seen set makes malformed cyclic provenance a
            # finite walk; first discovery is the incumbent on a repeated id.
            spellings = []
            current = port_id
            seen: set[int] = set()
            while current not in seen:
                seen.add(current)
                spellings.append(current)
                if current not in self.value_aliases:
                    break
                current = int(self.value_aliases[current])
            for spelling in spellings:
                if spelling == updated_id or spelling in saved_ids:
                    continue
                saved_ids.add(spelling)
                saved.append((
                    spelling,
                    spelling in self.value_aliases,
                    self.value_aliases.get(spelling),
                ))
                # LOOP_BODY_SPELLING: DERIVED(the port's binding row, the
                # loop construct cell).
                self._post_alias(
                    spelling, updated_id, AliasKind.LOOP_BODY_SPELLING,
                    self._declared_cell(
                        LOOP_RESULT_PORT_BINDING.name,
                        (self.lexical_read_scope, int(port_id)),
                    ) if self.lexical_read_scope is not None else None,
                    self._construct_cell(getattr(loop, "source_loop_node_id", None)),
                    stage=CONTROL_SSA_LOOP,
                )
        return tuple(saved)

    def _restore_loop_result_port_aliases(
        self, saved: tuple[tuple[int, bool, int | None], ...],
        loop: Any = None,
    ) -> None:
        loop_cell = self._construct_cell(getattr(loop, "source_loop_node_id", None))
        for port_id, existed, previous in saved:
            # RESTORED: the undo is an edge from the saved PLANNING cell and
            # the loop cell, never an erasure.
            self._post_alias(
                int(port_id), None if not existed else int(previous),
                AliasKind.RESTORED, loop_cell, stage=CONTROL_SSA_LOOP,
            )

    def _restore_ported_loop_seeds(self, loop: Any, carried: Any) -> None:
        """Exit ports own updated bindings; seed values remain their values."""

        if self.lexical_read_scope is None or not getattr(loop, "result_ports", ()):
            return
        # ``size = n; position = size; while position > 0: ...`` carries
        # position, not size. Publishing position's exit Phi on the shared
        # seed n changed the later ``size + 1`` to 1 rather than n + 1.
        # The planner already gave position its binding-specific exit port.
        # Restore captured seed residents only after all updated-id writes,
        # since one entry's update may also be another entry's seed.
        loop_cell = self._construct_cell(loop.source_loop_node_id)
        restored = set()
        for _updated_id, initial_id, initial, _updated, _current in carried:
            if initial_id not in restored:
                self._bind(initial_id, initial, BindingKind.RESTORED, loop_cell)
                restored.add(initial_id)

    def _post_alias(
        self, alias: Any, source_id: Any, kind: AliasKind, *cells: Any,
        stage: Any = None,
    ) -> Ref | None:
        """``control_value_alias`` row ``(scope, alias)``: a REVISE with
        ``AliasFact(source, kind)`` DERIVED from ``cells`` (and the previous
        revision), then the ``value_aliases`` read view."""

        alias = int(alias)
        if source_id is None:
            self.value_aliases.pop(alias, None)
        else:
            self.value_aliases[alias] = int(source_id)
        book = self._book()
        row = (self._scope(), alias)
        previous = book.latest_ref(CONTROL_VALUE_ALIAS, row)
        fact = AliasFact(None if source_id is None else int(source_id), kind)
        if previous is not None and (
            book.pages[CONTROL_VALUE_ALIAS.name].cells.get((row, previous.column))
            == fact
        ):
            return previous
        sources = self._cells(
            previous, *cells, self._canonical_cell(alias),
            None if source_id is None else self._canonical_cell(source_id),
        )
        if not sources:
            sources = (self._function_root(),)
        return book.post(
            CONTROL_VALUE_ALIAS, row, fact,
            stage=self._stage(stage),
            provenance=Derived(sources),
            mode=Mode.REVISE,
        )

    def _native_collection_address(self, receipt, base, index):
        # Never retain a payload address across a recursive native call. The
        # context column is a heap pointer CELL and may have moved meanwhile.
        column = self._native_object_bindings()[self.native_object_context.members.column_value_ids[2]]
        row = self.fresh_value(dtype='int64', transform=CONTROL_EXPRESSION, operands=(base, index))
        self.emit(Handler.Add, [base, index], row)
        address = self.fresh_value(dtype='ptr', transform=ADDRESS, operands=(column, row))
        self.emit(Handler.GetElementPtr, [column, row], address, attributes={'native_collection_row': {
            **receipt, 'action': 'address', 'base_value_id': base.id, 'index_value_id': index.id}})
        return address

    def lower_loop(self, loop: LoopBlock, *, path: str) -> None:
        recursion_region_id = loop.recursion_region_id
        deployment_id = None
        if loop.parallel_iterations and not any(receipt['loop_node_id'] == loop.source_loop_node_id
                for receipt in self.native_object_collections.values()):
            deployment_id = self.next_deployment_id
            self.next_deployment_id += 1
            record = {
                "region_id": deployment_id,
                "kind": "parallel_candidate",
                "schedule": "independent_iterations",
                "schedule_preference": loop.schedule_preference,
                "lane_count": 1,
                "iteration_space": (loop.start, loop.stop, loop.step),
                "carried_aliases": tuple(loop.carried_aliases),
                "recursion_region_id": recursion_region_id,
                "origin": "retained_loop",
                "source_loop_node_id": loop.source_loop_node_id,
                "scale": 1,
                "join": DeploymentJoin(),
                "declared_lanes": (),
            }
            self.deployment_records.append(record)
        collections = [receipt for receipt in self.native_object_collections.values()
            if receipt['loop_node_id'] == loop.source_loop_node_id]
        native_collection = None
        native_stop = None
        if collections:
            if len(collections) != 1 or str(loop.start) != '0' or str(loop.step) != '1' or loop.terminal_controls:
                raise ValueError(f'{path}: native collection requires one dense unit-step loop')
            receipt, = collections
            from .ssa_object_context import object_source_contract
            receipt = {**object_source_contract(receipt['contract_cell'], book=self._book()),
                       'contract_cell': receipt['contract_cell']}
            def dense_publications(block):
                if isinstance(block, SequenceBlock):
                    return [mutation for child in block.blocks for mutation in dense_publications(child)]
                if isinstance(block, SequenceMutationBlock):
                    return [block.mutation]
                if isinstance(block, (ConditionalBlock, LoopBlock, WhileBlock, CallBlock)):
                    raise ValueError(f'{path}: filtered/nested collection control is not admitted')
                return []
            publications = [*dense_publications(loop.body), *loop.sequence_mutations]
            publications = [mutation for mutation in publications if mutation.operator != 'object_construct']
            if (len(publications) != 1 or publications[0].operator != 'append'
                    or publications[0].sequence_value_id != receipt['collection_value_id']):
                raise ValueError(f'{path}: native collection requires exactly one unconditional publication')
            if 'target_projection_ids' in receipt:
                bindings = [binding for binding in self.program.projected_iterable_bindings if binding[2] == loop.induction]
                expected = tuple((receipt['iterable_value_id'], target, loop.induction, column)
                                 for column, target in enumerate(receipt['target_projection_ids']))
                if tuple(bindings) != expected:
                    raise ValueError(f'{path}: native pair projections differ from their exact loop bindings')
            else:
                bindings = [binding for binding in self.program.iterable_bindings if binding[2] == loop.induction]
                if (len(bindings) != 1 or bindings[0][0] != receipt['iterable_value_id']
                        or bindings[0][1] != receipt['target_value_id']):
                    raise ValueError(f'{path}: native collection iterable differs from its exact loop binding')
            cell = self._native_object_bindings()[self.native_object_context.members.length_address_id]
            zero = self.fresh_value(dtype='int64', transform=CONTROL_CONST, operands=(cell,))
            self.emit(Handler.Const, [], zero, attributes={'value': 0})
            length_address = self.fresh_value(dtype='ptr', transform=ADDRESS, operands=(cell, zero))
            self.emit(Handler.GetElementPtr, [cell, zero], length_address)
            base = self.fresh_value(dtype='int64', transform=LOAD, operands=(cell,))
            self.emit(Handler.Load, [length_address], base)
            token = self.fresh_value(dtype='int64', transform=CONTROL_CONST, operands=(receipt['collection_value_id'],))
            self.emit(Handler.Const, [], token, attributes={'value': self.native_object_context.kind_vocabulary.index(receipt['kind']) + 1})
            result = self._emit_native_object_operation('collect', receipt.get('source_iterable_value_id', receipt['iterable_value_id']), (token,), receipt['collection_value_id'])
            result.accounting.update(native_object_storage_identity=self.native_object_context.storage_identity,
                                     native_object_source_kind=receipt['kind'])
            self.current.instrs[-1].attributes['source_object_collection'] = dict(receipt)
            self._bind(receipt['materializer_node_id'], result, BindingKind.SEQUENCE_RESULT,
                       result, self._construct_cell(loop.source_loop_node_id))
            end = self.fresh_value(dtype='int64', transform=LOAD, operands=(cell,))
            self.emit(Handler.Load, [length_address], end)
            native_stop = self.fresh_value(dtype='int64', transform=CONTROL_EXPRESSION, operands=(base, end))
            self.emit(Handler.Sub, [end, base], native_stop)
            native_collection = (receipt, base)
        preheader = self.current
        start = self.expression_value(
            loop.start,
            location=f"{path}.start",
        )
        stop = native_stop if native_stop is not None else self.expression_value(
            loop.stop,
            location=f"{path}.stop",
        )
        step = self.expression_value(
            loop.step,
            location=f"{path}.step",
        )
        # A resident sequence extent is int64. The old header hard-coded
        # int (i32), while its latch's indexed use settled to i64, producing
        # an invalid Phi even for a two-member native table iteration.
        # Derive the counter from the actual range operands and widen the
        # preheader seeds explicitly; never repair the Phi at emission.
        # The shared scalar settlement widens inferred integer Add to int64,
        # including this counter's latch. A constant-bounded range(32) used
        # to mint an int32 header/seed and acquire an int64 latch afterwards.
        # State the same integer-arithmetic width at the counter's producer;
        # explicitly convert range operands, without relabelling their cells.
        induction_dtype = "int64"
        if induction_dtype == "int64":
            def range_operand(value):
                if value.dtype == induction_dtype:
                    return value
                widened = self.fresh_value(
                    dtype=induction_dtype, transform=CONTROL_CAST, operands=(value,),
                )
                self.emit(Handler.Cast, [value], widened,
                          attributes={"binding": "loop_range_width"})
                return widened
            start, stop, step = map(range_operand, (start, stop, step))
        # A carried seed whose graph node was folded to a constant must enter
        # as that literal; external_value would otherwise invent a
        # producerless argument for it.
        for seed_id, seed_literal in getattr(loop, "carried_seeds", ()):
            seed_id = int(seed_id)
            if seed_id in self.external_values:
                continue
            if isinstance(seed_literal, bool):
                seed_dtype = "bool"
            elif type(seed_literal) is int:
                from ..transmogrifier.dtype_layout import python_int_literal_dtype

                seed_dtype = python_int_literal_dtype(seed_literal)
            else:
                seed_dtype = "float64"
            seed_value = self.fresh_value(
                dtype=seed_dtype,
                transform=CONTROL_CONST,
                operands=(seed_id, loop.source_loop_node_id),
            )
            self.emit(
                Handler.Const, [], seed_value,
                attributes={"value": seed_literal},
            )
            # LOOP_SEED: the folded seed's own identity cell is the cause.
            self._bind(
                seed_id, seed_value, BindingKind.LOOP_SEED,
                self._construct_cell(loop.source_loop_node_id),
            )
        carried: list[tuple[int, int, SSAValue, SSAValue, SSAValue]] = []
        own_result_ports = {int(port_id) for port_id, *_ in loop.result_ports}
        reserved_updates: set[int] = set()
        for updated_id, initial_id in loop.carried_aliases:
            updated_id = int(updated_id)
            initial_id = int(initial_id)
            # The concordance can prove that the initial, updated, and exit
            # values occupy one storage slot.  Their temporal SSA identities
            # remain distinct: the preheader must read the value that exists
            # before the loop, not its result port after the loop.
            initial_value = self.external_value(
                initial_id,
                # An initial with no binding of its own that the alias record
                # resolves (an in-place arena after an earlier loop's stores)
                # is that storage; not following it minted a second,
                # unconnected formal for the same array.
                follow_aliases=(
                    int(initial_id) not in self.external_values
                    and int(initial_id) in self.value_aliases
                    # A physical alias to THIS loop's exit is not the
                    # preheader version. The observed 10->30 alias formerly
                    # selected unproduced result-port 30 instead of seed 10.
                    and self._concorded_resident(initial_id) not in own_result_ports
                ),
            )
            updated_value = self.external_values.get(updated_id)
            if updated_value is None:
                # The reserved backedge slot declares the initial's POSTED
                # dtype (see ``_posted_carried_type``), not its authored
                # spelling.
                updated_value = SSAValue(
                    updated_id,
                    dtype=self._posted_carried_type(initial_value)[0],
                    shape=initial_value.shape,
                )
                # LOOP_SEED: the reserved backedge slot, from the pre-loop
                # binding of the initial and the loop construct.
                self._bind(
                    updated_id, updated_value, BindingKind.LOOP_SEED,
                    initial_value, self._construct_cell(loop.source_loop_node_id),
                )
                reserved_updates.add(updated_id)
            elif updated_id not in reserved_updates:
                # An authored binding may be updated to a value which
                # already exists before the loop (``last = proposal``).
                # That value is the exact backedge resident.  Reserving a
                # second SSA object under the same ProcessGraph id erases
                # the formal and later misclassifies the binding as an
                # identity update merely because no body instruction needs
                # to reproduce the already-dominating value.
                updated_value.accounting[
                    "loop_carried_preexisting_update"
                ] = True
            self.reserve_loop_native_union_update(updated_id, updated_value)
            carried_dtype, carried_physical = self._posted_carried_type(
                initial_value, updated_value,
            )
            current_value = self.fresh_value(
                dtype=carried_dtype,
                shape=initial_value.shape,
                transform=PHI_LOOP_HEADER,
                operands=(initial_value, updated_value),
                physical=carried_physical,
            )
            current_value.accounting.update({
                "source_value_id": initial_id,
                "carried_from_value_id": updated_id,
            })
            # Region output extraction will use this exact object as the
            # backedge definition referenced by the Phi below.
            carried.append(
                (
                    updated_id,
                    initial_id,
                    initial_value,
                    updated_value,
                    current_value,
                )
            )
        header = self.new_block("loop_header")
        body = self.new_block("loop_body")
        latch = self.new_block("loop_latch")
        exit_block = self.new_block("loop_exit")
        self.current = preheader
        # The header Phi already selects the preheader seed. Its reserved
        # backedge value belongs to the body's producer, not a second Cast
        # definition in the preheader. In `m=next_m; w=next_w; total=w`, two
        # bindings share that update; seeding it twice made legalization pick
        # the preheader value instead of the body's result and froze the loop.
        # A reused reservation also is not a pre-existing authored update.
        if deployment_id is not None:
            self.emit_deployment_boundary(Handler.Deploy, record)
        self.branch(header)

        loop_cell = self._construct_cell(loop.source_loop_node_id)
        induction = self.fresh_value(
            dtype=induction_dtype, transform=PHI_LOOP_HEADER,
            operands=(start, stop, step, loop_cell),
        )
        next_induction = self.fresh_value(
            dtype=induction_dtype, transform=CONTROL_EXPRESSION,
            operands=(induction, step),
        )
        self.current = header
        self.emit(
            Handler.Phi,
            [start, next_induction],
            induction,
            attributes={
                "incoming_blocks": (preheader.name, latch.name),
                "source_name": loop.induction,
                "recursion_region_id": recursion_region_id,
                "source_loop_node_id": loop.source_loop_node_id,
            },
        )
        carried_phis: dict[int, Instr] = {}
        bound_initial_ids: set[int] = set()
        for entry, (
            updated_id,
            initial_id,
            initial_value,
            updated_value,
            current_value,
        ) in enumerate(carried):
            self.emit(
                Handler.Phi,
                [initial_value, updated_value],
                current_value,
                attributes={
                    "incoming_blocks": (preheader.name, latch.name),
                    "binding": "loop_carried",
                    "initial_value_id": self._phi_initial_binding(
                        initial_id, initial_value, current_value,
                        stage=CONTROL_SSA_LOOP,
                    ),
                    "initial_spelled_value_id": int(initial_id),
                    "updated_value_id": updated_id,
                    "recursion_region_id": recursion_region_id,
                    # The loop this generation belongs to, so a consumer
                    # can reach the scope declaration without recovering
                    # it from branch topology a transformation may have
                    # rewritten.
                    "source_loop_node_id": loop.source_loop_node_id,
                },
            )
            carried_phis[entry] = self.current.instrs[-1]
            type_source_id = next((
                value_id for value_id in (int(initial_id), int(updated_id))
                if value_id in self.native_value_type_abi
            ), int(initial_id))
            carried_tag = self.merge_native_type_tags(
                type_source_id, current_value,
                (int(initial_value.id), int(updated_value.id)),
                (preheader.name, latch.name),
                binding="loop_carried_native_type_tag",
            )
            if carried_tag is not None:
                self.native_value_type_tags[int(initial_id)] = carried_tag
                self.native_value_type_tags[int(updated_id)] = carried_tag
            if initial_id not in bound_initial_ids:
                # LOOP_HEADER: the header Phi is the body's value of the
                # initial; its cause is the Phi cell and the loop construct.
                self._bind(
                    initial_id, current_value, BindingKind.LOOP_HEADER,
                    loop_cell,
                )
                bound_initial_ids.add(initial_id)
        # Declare the loop as an evolving scope.  The rebind table is
        # exactly what ``carried`` already holds; what was missing is any
        # statement that these three names are one quantity at three
        # generations, which is why three of them could disagree in
        # silence.
        # Program: a loop whose carried value has no ssa_value cell.  Wrong
        # write: the declaration refused and `except Exception: pass` hid it,
        # leaving the loop_scope row half-written.  Rule: the refusal
        # (row = function, loop, binding; fact = value id) propagates.
        # A loop with no source_loop_node_id has no loop_scope row key (the
        # row is (function, loop node id, ...)); rebind_loop_scope_inner is
        # guarded the same way (existing precedent, ~8571).  This was the
        # swallowed TypeError of int(None).  OPEN ITEM: a loop with no node id
        # has no identity and should be refused once the hand-built fixtures
        # declare their loops.
        if loop.source_loop_node_id is not None:
            from .identity_concordance import declare_loop_scope

            # A loop the reducer never saw (no lexical read scope) stands on
            # the function root, as every other construct without a more
            # specific cell does.
            declare_loop_scope(
                self.function_name, loop.source_loop_node_id,
                header.name, latch.name, exit_block.name,
                self._loop_scope_rebinds(loop, carried),
                boundary_cells=(
                    (loop_cell,) if loop_cell is not None
                    else (self._function_root(),)
                ),
                rebind_cells=self._loop_scope_value_cells,
            )
        break_bound_initials = {
            int(initial_id): self._break_bound_initial(
                int(port_id), int(initial_id),
            )
            for port_id, initial_id, updated_id
            in getattr(loop, "result_ports", ())
            if int(updated_id) == int(initial_id)
        }
        result_port_aliases = self._bind_loop_result_ports_inside_body(loop)
        condition = self.fresh_value(
            dtype="bool", transform=CONTROL_PREDICATE,
            operands=(induction, stop),
        )
        self.emit(
            Handler.Lt if loop.comparison == "lt" else Handler.Gt,
            [induction, stop],
            condition,
            attributes={"binding": "loop_condition", "comparison": loop.comparison},
        )
        if native_collection is not None:
            induction.accounting['native_collection_predicate_value_id'] = condition.id
        self.conditional_branch(condition, body, exit_block)

        self.current = body
        self.loop_targets.append((latch, exit_block))
        exit_context = {
            "carried": tuple(
                (updated_id, initial_id, current, initial)
                for updated_id, initial_id, initial, _updated, current
                in carried
            ),
            # A port whose "updated" identity IS its initial identity has no
            # backedge version: the name is bound only on break paths.
            "break_bound": tuple(
                (int(port_id), int(initial_id))
                for port_id, initial_id, updated_id
                in getattr(loop, "result_ports", ())
                if int(updated_id) == int(initial_id)
            ),
            "break_edges": [],
            "continue_edges": [],
            "sites_seen": set(),
            "expected_sites": tuple(
                int(site) for site in getattr(loop, "control_site_ids", ())
            ),
        }
        self.loop_exit_contexts.append(exit_context)
        exit_context = self.loop_exit_contexts[-1]
        if deployment_id is not None:
            # Lane zero is the SSA template for every independent iteration;
            # the iteration space above tells a deployment pass how to fan it
            # out.  The ordinary CFG remains the serial fallback.
            self.active_deployments.append((deployment_id, 0))
        previous_induction = self.local_control_values.get(loop.induction)
        self.local_control_values[loop.induction] = induction
        if native_collection is not None:
            receipt, base = native_collection
            self.native_object_collection_rows[receipt['collection_value_id']] = (receipt, base, induction)
        restored_values: dict[int, SSAValue | None] = {}
        bound_loop_target_ids: set[int] = set()
        if native_collection is not None and 'target_projection_ids' in receipt:
            pair_receipt, base = native_collection
            key_id, value_id = pair_receipt['target_projection_ids']
            address = self._native_collection_address(pair_receipt, base, induction)
            key = self.produced_value(key_id, dtype='opaque_ref', claim_provisional_definition=True,
                cause=(address, pair_receipt['contract_cell']))
            self.emit(Handler.Load, [address], key, attributes={'native_collection_row': {
                **pair_receipt, 'action': 'iterate', 'base_value_id': base.id, 'index_value_id': induction.id}})
            value = self._emit_native_object_operation('get', pair_receipt['source_iterable_value_id'], (key,), value_id)
            self.current.instrs[-1].attributes['native_pair_projection'] = {'contract_cell': pair_receipt['contract_cell']}
            bound_loop_target_ids.update((key_id, value_id))
        # Program: ``d = {1: 10, 2: 20, 3: 30}; del d[2]; for k in d: ...``.
        # Wrong record: the loop ran over the physical rows, and a keyed
        # delete only clears the row's live flag, so the deleted key was
        # still visited (57 for 37).  Nothing here skipped a cleared row,
        # and the loop was refused.  Rule: an iteration over a table with a
        # keyed delete reads each row's live flag first and takes the
        # latch for a cleared one, as a selected child table's does; the
        # latch's carried values for that edge are the body-entry ones.
        # (A list formal a filtered loop reads also carries live flags,
        # c359; those mark kept rows, not deletions, so they are not
        # skipped.)
        table_live_block_names: set[str] = set()
        for iterable_id, _target_id, induction_name, *_projection in (
            *self.program.iterable_bindings,
            *self.program.projected_iterable_bindings,
        ):
            if induction_name != loop.induction:
                continue
            sequence_id, seen = int(iterable_id), set()
            while sequence_id in self.value_aliases and sequence_id not in seen:
                seen.add(sequence_id)
                sequence_id = int(self.value_aliases[sequence_id])
            descriptor = self.sequence_descriptors.get(sequence_id)
            if (
                descriptor is not None
                and descriptor.live_flags_value_id is not None
                and sequence_id in self.keyed_deletion_sequence_ids
            ):
                live_address = self.fresh_value(
                    dtype="ptr", transform=ADDRESS, operands=(induction,),
                )
                live = self.fresh_value(
                    dtype="bool", transform=LOAD, operands=(live_address,),
                )
                active = self.new_block("table_row_live")
                self.emit(
                    Handler.GetElementPtr,
                    [self.external_value(descriptor.live_flags_value_id), induction],
                    live_address,
                    attributes={"binding": "table_row_live"},
                )
                self.emit(
                    Handler.Load, [live_address], live,
                    attributes={"binding": "table_row_live"},
                )
                self.conditional_branch(live, active, latch)
                self.current = active
                table_live_block_names.add(active.name)
                break
        for iterable_id, target_id, induction_name in (
            self.program.iterable_bindings
        ):
            if induction_name != loop.induction:
                continue
            bound_loop_target_ids.add(int(target_id))
            restored_values[int(target_id)] = self.external_values.get(
                int(target_id)
            )
            if native_collection is not None:
                receipt, base = native_collection
                address = self._native_collection_address(receipt, base, induction)
                target = self.produced_value(int(target_id), dtype='opaque_ref',
                    claim_provisional_definition=True, cause=(address,))
                self.emit(Handler.Load, [address], target, attributes={'native_collection_row': {
                    **receipt, 'action': 'iterate', 'base_value_id': base.id, 'index_value_id': induction.id}})
                continue
            child_selection = self.child_table_selections.get(int(iterable_id))
            if child_selection is not None:
                pool, handle = child_selection
                value_columns = tuple(
                    column
                    for column in range(len(pool.column_value_ids))
                    if column not in pool.key_columns
                )
                if len(value_columns) != 1:
                    raise ValueError(
                        "selected child sequence has no unique element "
                        "column for scalar iteration: "
                        f"value={int(iterable_id)}, "
                        f"value_columns={value_columns!r}"
                    )
                self.bind_selected_child_element(
                    pool,
                    handle,
                    induction,
                    int(target_id),
                    column=int(value_columns[0]),
                    latch=latch,
                    attributes={"iteration_semantics": "values"},
                )
                continue
            if int(target_id) in self.nested_row_target_ids:
                self.bind_nested_row(
                    self.external_value(iterable_id, dtype="int"),
                    induction,
                    int(target_id),
                    child_key=("iterable", int(iterable_id), -1),
                    attributes={"induction": loop.induction},
                )
                continue
            self.indexed_load(
                self.external_value(iterable_id),
                induction,
                target_id,
                attributes={
                    "binding": "iterable",
                    "induction": loop.induction,
                },
            )
        for iterable_id, target_id, induction_name, projection in (
            self.program.projected_iterable_bindings
        ):
            if induction_name != loop.induction:
                continue
            if native_collection is not None and int(target_id) in bound_loop_target_ids:
                continue
            bound_loop_target_ids.add(int(target_id))
            restored_values[int(target_id)] = self.external_values.get(
                int(target_id)
            )
            if projection == "induction":
                # LOOP_CONTROL: the induction Phi is the target's value.
                # ``enumerate(a, start)`` counts from ``start``: its counter
                # is the induction plus that value (``induction_offsets``).
                counter = induction
                start_id = dict(
                    getattr(self.program, "induction_offsets", ()) or ()
                ).get(int(target_id))
                if start_id is not None:
                    start = self.external_value(int(start_id))
                    counter = self.fresh_value(
                        dtype="int64", transform=CONTROL_EXPRESSION,
                        operands=(induction, start),
                    )
                    self.emit(
                        Handler.Add, [induction, start], counter,
                        attributes={
                            "binding": "enumerate_start",
                            "induction": loop.induction,
                        },
                    )
                self._bind(
                    int(target_id), counter, BindingKind.LOOP_CONTROL,
                    loop_cell, int(iterable_id),
                )
                continue
            child_selection = self.child_table_selections.get(
                int(iterable_id)
            )
            if projection is None and child_selection is not None:
                pool, handle = child_selection
                value_columns = tuple(
                    column
                    for column in range(len(pool.column_value_ids))
                    if column not in pool.key_columns
                )
                if len(value_columns) != 1:
                    raise ValueError(
                        "selected child sequence has no unique element "
                        "column for scalar iteration: "
                        f"value={int(iterable_id)}, "
                        f"value_columns={value_columns!r}"
                    )
                self.bind_selected_child_element(
                    pool,
                    handle,
                    induction,
                    int(target_id),
                    column=int(value_columns[0]),
                    latch=latch,
                    attributes={
                        "iteration_semantics": "values",
                        "iterable_id": int(iterable_id),
                        "induction": loop.induction,
                        "projection": projection,
                    },
                    claim_provisional_definition=True,
                )
                continue
            projection_index = induction
            column_projection = projection
            if (
                isinstance(projection, tuple)
                and len(projection) == 3
                and projection[0] == "column_at_value"
            ):
                column_projection = int(projection[1])
                projection_index = self.external_value(
                    int(projection[2]), dtype="int"
                )
            source = self.external_value(iterable_id)
            if projection is not None:
                column_key = (int(iterable_id), int(column_projection))
                source = self.projected_row_columns.get(column_key)
                if source is None:
                    target_meta = self.region_value_meta.get(int(target_id))
                    target_dtype = (
                        None if target_meta is None else str(target_meta.dtype)
                    )
                    if target_dtype is None and int(column_projection) > 0:
                        # A destructured Python row column with no numerical
                        # descriptor is still a concrete value transport: an
                        # opaque reference arena.  This is the exact fallback
                        # representation for arbitrary objects, not a guessed
                        # scalar dtype.  Column zero keeps the iterable's own
                        # identity; later physical columns need their own ABI.
                        target_dtype = "opaque_ref"
                    target_shape = (
                        () if target_meta is None
                        else tuple(map(int, target_meta.shape or ()))
                    )
                    if (
                        int(target_id) in self.nested_row_target_ids
                        and int(target_id)
                        not in self.variant_projected_target_ids
                    ):
                        target_dtype = "int"
                    resident_sequence_id = int(iterable_id)
                    seen_aliases: set[int] = set()
                    while (
                        resident_sequence_id in self.value_aliases
                        and resident_sequence_id not in seen_aliases
                    ):
                        seen_aliases.add(resident_sequence_id)
                        resident_sequence_id = int(
                            self.value_aliases[resident_sequence_id]
                        )
                    descriptor = self.sequence_descriptors.get(
                        resident_sequence_id
                    )
                    if (
                        descriptor is not None
                        and 0 <= int(column_projection) < len(
                            descriptor.column_value_ids
                        )
                    ):
                        source = self.external_value(
                            int(descriptor.column_value_ids[int(column_projection)]),
                            dtype=str(descriptor.column_dtypes[int(column_projection)]),
                        )
                    elif int(column_projection) == 0:
                        source = self.external_value(
                            iterable_id, dtype=target_dtype
                        )
                        if target_shape:
                            source.shape = target_shape
                        source.accounting.update({
                            "projected_row_source_id": int(iterable_id),
                            "projected_row_column": int(column_projection),
                            "compiler_frame_storage": str(
                                self.function_name
                            ),
                            **(
                                {"sequence_row_shape": target_shape}
                                if target_shape else {}
                            ),
                        })
                    else:
                        source = self.fresh_value(
                            dtype=target_dtype, shape=target_shape,
                            transform=ROW_COLUMN_PROJECTION,
                            operands=(int(iterable_id), int(target_id)),
                        )
                        source.accounting.update({
                            "projected_row_source_id": int(iterable_id),
                            "projected_row_column": int(column_projection),
                            "compiler_frame_storage": str(
                                self.function_name
                            ),
                            **(
                                {"sequence_row_shape": target_shape}
                                if target_shape else {}
                            ),
                        })
                        self.arguments.append(source)
                    self.projected_row_columns[column_key] = source
                if int(target_id) in self.variant_projected_target_ids:
                    scalar_source = source
                    handle_source = self.variant_handle_columns.get(column_key)
                    if handle_source is None:
                        handle_source = self.fresh_value(
                            dtype="int", transform=ROW_COLUMN_PROJECTION,
                            operands=(int(iterable_id), scalar_source),
                        )
                        handle_source.accounting.update({
                            "projected_variant_source_id": int(iterable_id),
                            "projected_variant_column": int(column_projection),
                        })
                        self.arguments.append(handle_source)
                        self.variant_handle_columns[column_key] = handle_source
                    scalar_value = self.indexed_load(
                        scalar_source,
                        projection_index,
                        target_id,
                        attributes={
                            "binding": "projected_variant_scalar",
                            "induction": loop.induction,
                            "projection": projection,
                        },
                    )
                    type_tag = self.projected_native_type_tag(
                        int(iterable_id), int(column_projection),
                        projection_index, int(target_id),
                    )
                    if type_tag is not None:
                        scalar_value.accounting = {
                            **dict(scalar_value.accounting or {}),
                            "native_type_tag_value_id": int(type_tag.id),
                            "native_type_alternatives": tuple(
                                type_tag.accounting.get(
                                    "native_type_alternatives", ()
                                )
                            ),
                        }
                    self.bind_nested_row(
                        handle_source,
                        projection_index,
                        int(target_id),
                        child_key=(
                            "projected", int(iterable_id),
                            int(column_projection)
                        ),
                        attributes={
                            "induction": loop.induction,
                            "projection": projection,
                            "variant": True,
                        },
                    )
                    self.variant_row_values[int(target_id)] = (
                        self.external_values[int(target_id)]
                    )
                    # Scalar regions continue to consume the scalar column.
                    self._bind(
                        int(target_id), scalar_value, BindingKind.LOOP_CONTROL,
                        loop_cell,
                    )
                    continue
            if (
                projection is not None
                and int(target_id) in self.nested_row_target_ids
            ):
                self.bind_nested_row(
                    source,
                    projection_index,
                    int(target_id),
                    child_key=(
                        "projected", int(iterable_id), int(column_projection)
                    ),
                    attributes={
                        "induction": loop.induction,
                        "projection": projection,
                    },
                )
                continue
            projected_value = self.indexed_load(
                source,
                projection_index,
                target_id,
                attributes={
                    "binding": "projected_iterable",
                    "iterable_id": int(iterable_id),
                    "induction": loop.induction,
                    "projection": projection,
                },
                claim_provisional_definition=True,
            )
            resident_sequence_id = int(iterable_id)
            seen_aliases = set()
            while (
                resident_sequence_id in self.value_aliases
                and resident_sequence_id not in seen_aliases
            ):
                seen_aliases.add(resident_sequence_id)
                resident_sequence_id = int(
                    self.value_aliases[resident_sequence_id]
                )
            resident_descriptor = self.sequence_descriptors.get(
                resident_sequence_id
            )
            if (
                resident_descriptor is not None
                and resident_descriptor.child_table_pool is not None
                and column_projection is not None
                and int(column_projection)
                == int(resident_descriptor.child_table_pool.handle_column)
            ):
                # The projected handle is the selected child sequence.  Keep
                # the exact pool/handle pair so extent and nested iteration use
                # the caller-owned child arenas instead of a parallel
                # provisional descriptor for the same source value.
                self.child_table_selections[int(target_id)] = (
                    resident_descriptor.child_table_pool, projected_value,
                )
            # ``enumerate(source)`` over a single-column source authors its
            # element binding with projection ``None`` (loop_composer): the
            # element IS the source's only physical column, column zero, the
            # same reading the GLSL binder gives it.  The tag column is keyed
            # by that column, so ``None`` must not reach ``int()``.
            type_tag = self.projected_native_type_tag(
                int(iterable_id),
                0 if column_projection is None else int(column_projection),
                projection_index, int(target_id),
            )
            if type_tag is not None:
                projected_value.accounting = {
                    **dict(projected_value.accounting or {}),
                    "native_type_tag_value_id": int(type_tag.id),
                    "native_type_alternatives": tuple(
                        type_tag.accounting.get(
                            "native_type_alternatives", ()
                        )
                    ),
                }
        for base_id, column, result_id, induction_name in (
            self.nested_row_projections
        ):
            if induction_name != loop.induction:
                continue
            base = self.external_values.get(int(base_id))
            if base is None:
                continue
            column_value = self.fresh_value(
                dtype="int", transform=CONTROL_CONST, operands=(base,),
            )
            self.emit(
                Handler.Const, [], column_value,
                attributes={"value": int(column)},
            )
            projected_value = self.indexed_load(
                base,
                column_value,
                int(result_id),
                attributes={
                    "binding": "nested_row_projection",
                    "induction": loop.induction,
                    "projection": int(column),
                    "source_value_id": int(base_id),
                },
            )
            # A tuple/row member is the same heterogeneous sequence
            # projection as a directly bound loop column.  Its
            # VALUE_TYPE_ABI therefore owns a parallel tag (and arm payload)
            # column too.  Previously only the direct projected-iterable
            # path above asked for that column; a nested ``row[n]`` load then
            # reached an ``isinstance`` predicate with an invented pending
            # tag formal even though the row source was already known.
            type_tag = self.projected_native_type_tag(
                int(base_id), int(column), projection_index, int(result_id),
            )
            if type_tag is not None:
                projected_value.accounting = {
                    **dict(projected_value.accounting or {}),
                    "native_type_tag_value_id": int(type_tag.id),
                    "native_type_alternatives": tuple(
                        type_tag.accounting.get(
                            "native_type_alternatives", ()
                        )
                    ),
                }
        for iterable_id, target_id, induction_name, values in (
            self.program.static_iterable_bindings
        ):
            if induction_name != loop.induction:
                continue
            bound_loop_target_ids.add(int(target_id))
            restored_values[int(target_id)] = self.external_values.get(
                int(target_id)
            )
            aggregate = self.fresh_value(
                dtype="ssa.aggregate", transform=CONTROL_CONST,
                operands=(int(iterable_id), loop_cell),
            )
            self.emit(
                Handler.Const,
                [],
                aggregate,
                attributes={
                    "value": tuple(values),
                    "binding": "static_iterable",
                    "source_value_id": int(iterable_id),
                },
            )
            # Program: ``for v in src`` with ``src`` specialized to the
            # caller's literal ``[2, 3]`` (scratch c_h7).  Wrong record: the
            # element had no region meta, so its row posted ``unknown`` while
            # a later reader typed the instruction ``int``; the width check
            # refused.  Rule: a static iterable's element type is the join
            # of its literals, the planner's join (``_planned_scalar_dtypes``):
            # one kind is itself, ints with bools are int64, any other mix
            # proves nothing.
            def static_element_dtype_of(value):
                if isinstance(value, bool):
                    return "bool"
                if type(value) is int:
                    from ..transmogrifier.dtype_layout import (
                        python_int_literal_dtype,
                    )

                    return python_int_literal_dtype(value)
                return "float64" if isinstance(value, float) else None

            literal_kinds = tuple(static_element_dtype_of(value) for value in values)
            if not literal_kinds or None in literal_kinds:
                static_element_dtype = None
            elif all(
                kind in {
                    "bool", "int8", "int16", "int32", "int64",
                    "uint8", "uint16", "uint32", "uint64",
                    "int128", "uint128",
                }
                for kind in literal_kinds
            ):
                from ..transmogrifier.dtype_layout import common_integer_dtype

                static_element_dtype = common_integer_dtype(literal_kinds)
            elif len(set(literal_kinds)) == 1:
                static_element_dtype = literal_kinds[0]
            else:
                static_element_dtype = None
            # Use the already-published physical column when this static
            # iterable is a resident sequence.  Its descriptor is the exact
            # storage contract for the Load; Python literal payloads remain
            # only the existing fallback for an uncontracted static value.
            resident_sequence_id = int(iterable_id)
            descriptor_seen: set[int] = set()
            while (
                resident_sequence_id in self.value_aliases
                and resident_sequence_id not in descriptor_seen
            ):
                descriptor_seen.add(resident_sequence_id)
                resident_sequence_id = int(
                    self.value_aliases[resident_sequence_id]
                )
            static_descriptor = self.sequence_descriptors.get(
                resident_sequence_id
            )
            static_descriptor_cell = self._sequence_contract_cell(
                resident_sequence_id
            )
            if (
                static_descriptor is not None
                and static_descriptor_cell is not None
                and len(static_descriptor.column_dtypes) == 1
                and len(static_descriptor.column_value_ids) == 1
                and len(static_descriptor.column_shapes) == 1
                and tuple(static_descriptor.column_shapes[0] or ()) == ()
                and str(static_descriptor.column_dtypes[0])
                not in {"", "unknown", "None"}
            ):
                static_element_dtype = str(
                    static_descriptor.column_dtypes[0]
                )
            else:
                static_descriptor_cell = None
            self.indexed_load(
                aggregate,
                induction,
                target_id,
                attributes={
                    "binding": "static_iterable",
                    "induction": loop.induction,
                },
                element_dtype=static_element_dtype,
                element_dtype_cell=static_descriptor_cell,
            )
        for aggregate_id, target_id, induction_name, source_ids in (
            self.program.closure_iterable_bindings
        ):
            if induction_name != loop.induction:
                continue
            if int(target_id) in bound_loop_target_ids:
                # Closure captures are the fallback resident spelling for a
                # loop target.  If the same target already has an explicit
                # iterable/projected/static binding, emitting the fallback as
                # well defines one SSA identity twice and may replace a real
                # array load with a synthetic aggregate expression.
                continue
            bound_loop_target_ids.add(int(target_id))
            restored_values[int(target_id)] = self.external_values.get(
                int(target_id)
            )
            closure_sources = [
                self.external_value(value_id) for value_id in source_ids
            ]
            aggregate = self.fresh_value(
                dtype="ssa.aggregate", transform=CONTROL_EXPRESSION,
                operands=(*closure_sources, int(aggregate_id)),
            )
            self.emit(
                Handler.Const,
                closure_sources,
                aggregate,
                attributes={
                    "binding": "closure_iterable",
                    "source_value_id": int(aggregate_id),
                    "resident_source_ids": tuple(source_ids),
                },
            )
            self.indexed_load(
                aggregate,
                induction,
                target_id,
                attributes={
                    "binding": "closure_iterable",
                    "induction": loop.induction,
                },
            )
        # CFG keys and SSA ids survive storage eviction; Python object
        # addresses do not. These are the function's authoritative identities.
        blocks_before_body = {existing.name for existing in self.blocks.values()}
        initial_counts: dict[int, int] = {}
        for _updated_id, initial_id, *_rest in carried:
            initial_counts[int(initial_id)] = (
                initial_counts.get(int(initial_id), 0) + 1
            )
        protected_alias_sources = frozenset(
            int(updated_id)
            for updated_id, initial_id, *_rest in carried
            if initial_counts[int(initial_id)] > 1
        )
        self.protected_loop_alias_sources.append(protected_alias_sources)
        self.enclosing_loop_states.append(
            self._enter_loop_state(loop, carried)
        )
        try:
            self.lower(loop.body, path=f"{path}.body")
            for mutation in loop.sequence_mutations:
                self.lower_sequence_mutation(mutation, path=path)
            for terminal in loop.terminal_controls:
                self.lower(terminal, path=f"{path}.terminal")
        finally:
            self.enclosing_loop_states.pop()
            self.protected_loop_alias_sources.pop()
            self.loop_exit_contexts.pop()
            self.loop_targets.pop()
        body_blocks = [
            candidate
            for candidate in self.blocks.values()
            if candidate.name not in blocks_before_body or candidate.name == body.name
            or candidate.name in table_live_block_names
        ]
        # A nested retained loop may carry the same source state as this loop.
        # Its exit Phi is then the value produced by this iteration, but the
        # nested lowering necessarily replaced ``external_values[updated_id]``
        # with that inner value.  Point the enclosing Phi's latch operand at
        # the value the body actually published instead of requiring the
        # placeholder object reserved before the body was lowered.
        carried_updates: dict[int, SSAValue] = {}
        for entry, (updated_id, _initial_id, _initial, reserved, _current) in enumerate(carried):
            published = self.external_values.get(updated_id, reserved)
            carried_updates[entry] = published
            if published is not reserved:
                carried_phis[entry].args[1] = published
        if os.environ.get("TURING_DEBUG_LOOP_ALIAS_PUBLICATION"):
            print(
                "DEBUG-LOOP-CARRIED-UPDATES "
                f"fn={self.function_name} path={path} "
                f"updates={tuple((int(carried[entry][0]), int(value.id)) for entry, value in carried_updates.items())!r}",
                file=sys.stderr,
                flush=True,
            )
        # Producers are counted in the BODY's blocks only, as the shortfall
        # message has always claimed. Scanning every block would let the
        # preheader seed above stand in for a producer, silently accepting a
        # loop whose body updates nothing -- the carried value would freeze at
        # its seed, which is the exact miscompilation shape this check exists
        # to refuse.
        produced_results = {
            int(instruction.res.id)
            for basic_block in body_blocks
            for instruction in basic_block.instrs
            if instruction.res is not None
        }
        for entry, (updated_id, _initial_id, _initial, updated, _current) in enumerate(carried):
            if int(carried_updates[entry].id) not in produced_results:
                if int(carried_updates[entry].id) == int(induction.id):
                    # The loop target carried past the loop (``for i in
                    # range(10): ... break`` then ``return i``): its value
                    # this iteration IS the induction, produced by the
                    # header for every iteration.
                    continue
                if updated.accounting.get(
                    "loop_carried_preexisting_update"
                ):
                    # Selecting a value which already dominates the loop is
                    # an authored update even though the body needs no new
                    # instruction to compute it.
                    continue
                declared_outputs = tuple(
                    region_index
                    for region_index, (_feeds, outputs)
                    in self.region_signatures.items()
                    if updated_id in outputs
                )
                alias_source = self.value_aliases.get(updated_id)
                concorded_resident = self._concorded_resident

                resident_id = concorded_resident(updated_id)
                identity_occurrences = tuple(dict.fromkeys((
                    int(updated_id), int(resident_id),
                    *(
                        int(value_id)
                        for value_id in self.region_value_meta
                        if concorded_resident(value_id) == resident_id
                    ),
                )))
                updated_meta = next((
                    self.region_value_meta.get(value_id)
                    for value_id in identity_occurrences
                    if tuple(getattr(
                        self.region_value_meta.get(value_id), "shape", ()
                    ) or ())
                ), None)
                storage_shape = tuple(
                    getattr(updated_meta, "shape", ()) or ()
                )
                from .identity_concordance import current_identity_book

                shape_page = current_identity_book().page(
                    "tensor_shape_concordance"
                )
                shape_contract = (
                    shape_page.latest((
                        self.tensor_shape_concordance_scope,
                        int(updated_id),
                    ))
                    or shape_page.latest((
                        self.tensor_shape_concordance_scope,
                        int(resident_id),
                    ))
                )
                if shape_contract is None and storage_shape:
                    shape_contract = {
                        "program_abi_storage": "span",
                        "program_abi_rank": len(storage_shape),
                        "tensor_metadata_state": "static",
                        "shape": storage_shape,
                        "source": "concorded-loop-resident-meta",
                    }
                    # Program: a nested retained loop whose carried value
                    # is a resident span (tests/test_precompile_contract_rows.py,
                    # ``test_loop_resident_shape_contract_is_posted_derived``).
                    # Wrong record: this wrote the ``tensor_shape_concordance``
                    # row straight into the page (``shape_page.set``), past the
                    # closed latch.  Rule: nothing writes a page except through
                    # ``book.post``; the contract is DERIVED from the canonical
                    # cells of every spelling of the resident whose
                    # ``region_value_meta`` supplied the shape.
                    for value_id in dict.fromkeys((
                        int(resident_id), int(updated_id),
                    )):
                        self._post_tensor_shape_contract(
                            value_id, shape_contract, *identity_occurrences,
                        )
                storage_rank = int(
                    (shape_contract or {}).get("program_abi_rank", 0) or 0
                )
                storage_is_span = (
                    (shape_contract or {}).get("program_abi_storage")
                    == "span"
                )
                if (
                    not declared_outputs
                    and alias_source is not None
                    and (
                        storage_shape
                        or storage_is_span
                        or storage_rank > 0
                        or int(alias_source) in self.sequence_descriptors
                    )
                ):
                    # Indexed stores mutate their resident span.  A nested
                    # retained loop can therefore publish no new pointer
                    # value even though its body produced every authored
                    # store.  Carry the current resident pointer across the
                    # enclosing latch, exactly as the while-loop path below
                    # does for a producerless identity backedge.  Restrict
                    # this to graph-proven shaped storage or a resident
                    # sequence descriptor built from the concorded contract:
                    # an ordinary scalar recurrence must still name a real
                    # producer.
                    current = carried_phis[entry].args[0]
                    carried_phis[entry].args[1] = current
                    carried_updates[entry] = current
                    # LOOP_LATCH: the resident pointer crosses the latch.
                    self._bind(
                        updated_id, current, BindingKind.LOOP_LATCH, loop_cell,
                    )
                    current.accounting["ssa_storage_identity_backedge"] = True
                    continue
                self.shortfalls.append(
                    SSALoweringShortfall(
                        "control",
                        "loop_carried",
                        f"{path}.body",
                        f"carried update value {updated_id} has no producer "
                        "inside the loop body; "
                        f"alias_source={alias_source!r}; "
                        f"declared_region_outputs={declared_outputs}",
                    )
                )
        for source_id, collection_id, induction_name, start in (
            self.program.collection_bindings
        ):
            if induction_name != loop.induction:
                continue
            publication_index = induction
            if str(start).strip() != "0":
                offset = self.expression_value(
                    str(start), location=f"{path}.collection-offset",
                )
                publication_index = self.fresh_value(
                    dtype="int", transform=CONTROL_EXPRESSION,
                    operands=(induction, offset),
                )
                self.emit(
                    Handler.Add,
                    [induction, offset],
                    publication_index,
                    attributes={"binding": "collection_offset"},
                )
            collection = self.external_value(collection_id)
            address = self.fresh_value(
                dtype="ptr", transform=ADDRESS,
                operands=(collection, publication_index),
            )
            self.emit(
                Handler.GetElementPtr,
                [
                    collection,
                    publication_index,
                ],
                address,
                attributes={
                    "binding": "collection_publication",
                    "collection_value_id": int(collection_id),
                    "induction": loop.induction,
                },
            )
            self.emit(
                Handler.Store,
                [self.external_value(source_id), address],
                attributes={
                    "binding": "collection_publication",
                    "source_value_id": int(source_id),
                },
            )
        if deployment_id is not None:
            self.active_deployments.pop()
        if native_collection is not None:
            self.native_object_collection_rows.pop(native_collection[0]['collection_value_id'], None)
        if not self.current.successors:
            self.branch(latch)

        self.current = latch
        self._complete_loop_latch_carried(
            carried,
            carried_phis,
            carried_updates,
            exit_context["continue_edges"],
        )
        self.emit(
            Handler.Add,
            [induction, step],
            next_induction,
        )
        self.branch(header)
        if recursion_region_id is not None:
            source = self.recursion_regions[int(recursion_region_id)]
            lowered_region = self.ssa_recursion_table.setdefault(
                int(recursion_region_id),
                {**source, "function": self.function_name, "loops": []},
            )
            lowered_region["loops"].append({
                "function": self.function_name,
                "preheader": preheader.name,
                "header": header.name,
                "body": body.name,
                "latch": latch.name,
                "exit": exit_block.name,
                "phi_value_ids": (
                    int(induction.id),
                    *(int(current.id) for *_prefix, current in carried),
                ),
                "backedge": (latch.name, header.name),
            })
        # The targets leave scope at the loop's exit, and the exit is caused
        # by the latch: the induction update ``next_induction`` is what the
        # header compares to leave.  Its cell is the withdrawal's cause.
        # Without it the withdrawal cited exactly the cells the LOOP_CONTROL
        # binding cited (canonical id, induction, loop, iterable), and the
        # book refused it as a REVISE with no new source: measured on
        # ``for k in range(6)`` in the oscillator case's ``cos_series``,
        # graph id 0, ConcordanceRefusal at control_value_binding.
        exit_cause = self._value_cell(next_induction)
        for target_id, previous in restored_values.items():
            # RESTORED (or withdrawn): the loop targets leave scope.
            self._withdraw(target_id, previous, loop_cell, exit_cause)
        if previous_induction is None:
            self.local_control_values.pop(loop.induction, None)
        else:
            self.local_control_values[loop.induction] = previous_induction
        settled_initial_ids: set[int] = set()
        for updated_id, initial_id, _initial, _updated, current in carried:
            # LOOP_HEADER: after the loop every carried spelling denotes
            # the converged header Phi.
            if initial_id not in settled_initial_ids:
                self._bind(
                    initial_id, current, BindingKind.LOOP_HEADER, loop_cell,
                )
                settled_initial_ids.add(initial_id)
            self._bind(updated_id, current, BindingKind.LOOP_HEADER, loop_cell)
        for missing_site in sorted(
            set(exit_context["expected_sites"]) - exit_context["sites_seen"]
        ):
            # A source break/continue nothing placed (neither an arm nor the
            # lexical schedule) would silently turn into a loop that runs to
            # completion.
            self.shortfalls.append(SSALoweringShortfall(
                "control", "loop-control-site", path,
                f"source break/continue at graph node {missing_site} was "
                "never placed in the loop body",
            ))
        self._restore_loop_result_port_aliases(result_port_aliases, loop)
        self._restore_ported_loop_seeds(loop, carried)
        self._publish_loop_result_ports(
            loop,
            header=header,
            exit_block=exit_block,
            carried=carried,
            break_edges=tuple(exit_context["break_edges"]),
            break_bound=tuple(exit_context["break_bound"]),
            break_bound_initials=break_bound_initials,
        )
        if deployment_id is not None:
            self.emit_deployment_boundary(Handler.Join, record)

    def lower_while(self, loop: WhileBlock, *, path: str) -> None:
        recursion_region_id = loop.recursion_region_id
        loop_cell = self._construct_cell(loop.source_loop_node_id)
        constant_predicate = (
            bool(loop.predicate_expression.literal)
            if (
                loop.predicate_expression is not None
                and loop.predicate_expression.op == "const"
                and isinstance(loop.predicate_expression.literal, bool)
            )
            else None
        )
        self.lower(loop.condition, path=f"{path}.condition.initial")
        preheader = self.current
        initial_predicate = (
            self.lower_control_expression(loop.predicate_expression)
            if loop.predicate_expression is not None
            else self.external_value(loop.predicate_value_id, dtype="bool")
        )
        next_predicate = self.fresh_value(
            dtype="bool", transform=CONTROL_PREDICATE,
            operands=(initial_predicate, loop_cell),
        )

        # A carried seed whose graph node was folded to a constant must enter
        # as that literal; external_value would otherwise invent a
        # producerless argument for it.
        for seed_id, seed_literal in getattr(loop, "carried_seeds", ()):
            seed_id = int(seed_id)
            if seed_id in self.external_values:
                continue
            if isinstance(seed_literal, bool):
                seed_dtype = "bool"
            elif type(seed_literal) is int:
                from ..transmogrifier.dtype_layout import python_int_literal_dtype

                seed_dtype = python_int_literal_dtype(seed_literal)
            else:
                seed_dtype = "float64"
            seed_value = self.fresh_value(
                dtype=seed_dtype,
                transform=CONTROL_CONST,
                operands=(seed_id, loop.source_loop_node_id),
            )
            self.emit(
                Handler.Const, [], seed_value,
                attributes={"value": seed_literal},
            )
            # LOOP_SEED: the folded seed's own identity cell is the cause.
            self._bind(
                seed_id, seed_value, BindingKind.LOOP_SEED,
                self._construct_cell(loop.source_loop_node_id),
            )
        carried: list[tuple[int, int, SSAValue, SSAValue, SSAValue]] = []
        own_result_ports = {int(port_id) for port_id, *_ in loop.result_ports}
        for updated_id, initial_id in loop.carried_aliases:
            updated_id = int(updated_id)
            initial_id = int(initial_id)
            # Storage concordance does not erase the temporal distinction
            # between the preheader seed and the loop backedge value.
            initial_value = self.external_value(
                initial_id,
                # An initial with no binding of its own that the alias record
                # resolves (an in-place arena after an earlier loop's stores)
                # is that storage; not following it minted a second,
                # unconnected formal for the same array.
                follow_aliases=(
                    int(initial_id) not in self.external_values
                    and int(initial_id) in self.value_aliases
                    and self._concorded_resident(initial_id) not in own_result_ports
                ),
            )
            updated_value = self.external_values.get(updated_id)
            if updated_value is None:
                # The reserved backedge slot declares the initial's POSTED
                # dtype (see ``_posted_carried_type``), not its authored
                # spelling.
                updated_value = SSAValue(
                    updated_id,
                    dtype=self._posted_carried_type(initial_value)[0],
                    shape=initial_value.shape,
                )
                # LOOP_SEED: the reserved backedge slot, from the pre-loop
                # binding of the initial and the loop construct.
                self._bind(
                    updated_id, updated_value, BindingKind.LOOP_SEED,
                    initial_value, self._construct_cell(loop.source_loop_node_id),
                )
            else:
                # A carried binding can select an already-dominating value
                # as its authored update.  Keep that exact SSA resident;
                # manufacturing another object with the same graph id loses
                # the distinction between this binding and another binding
                # which merely shares its initial value.
                updated_value.accounting[
                    "loop_carried_preexisting_update"
                ] = True
            self.reserve_loop_native_union_update(updated_id, updated_value)
            carried_dtype, carried_physical = self._posted_carried_type(
                initial_value, updated_value,
            )
            current_value = self.fresh_value(
                dtype=carried_dtype,
                shape=initial_value.shape,
                transform=PHI_LOOP_HEADER,
                operands=(initial_value, updated_value),
                physical=carried_physical,
            )
            carried.append((
                updated_id, initial_id, initial_value,
                updated_value, current_value,
            ))

        header = self.new_block("while_header")
        body = self.new_block("while_body")
        latch = self.new_block("while_latch")
        exit_block = self.new_block("while_exit")
        self.current = preheader
        self.branch(header)

        self.current = header
        current_predicate = self.fresh_value(
            dtype="bool", transform=PHI_LOOP_HEADER,
            operands=(initial_predicate, next_predicate),
        )
        self.emit(
            Handler.Phi,
            [initial_predicate, next_predicate],
            current_predicate,
            attributes={
                "incoming_blocks": (preheader.name, latch.name),
                "binding": "while_condition",
                "source_value_id": int(loop.predicate_value_id),
                "recursion_region_id": recursion_region_id,
                "source_loop_node_id": loop.source_loop_node_id,
            },
        )
        # LOOP_CONTROL: the predicate id denotes the header Phi in the body.
        self._bind(
            int(loop.predicate_value_id), current_predicate,
            BindingKind.LOOP_CONTROL, loop_cell,
        )
        carried_phis: dict[int, Instr] = {}
        bound_initial_ids: set[int] = set()
        for entry, (updated_id, initial_id, initial, updated, current) in enumerate(carried):
            self.emit(
                Handler.Phi,
                [initial, updated],
                current,
                attributes={
                    "incoming_blocks": (preheader.name, latch.name),
                    "binding": "loop_carried",
                    "initial_value_id": self._phi_initial_binding(
                        initial_id, initial, current,
                        stage=CONTROL_SSA_LOOP,
                    ),
                    "initial_spelled_value_id": int(initial_id),
                    "updated_value_id": updated_id,
                    "recursion_region_id": recursion_region_id,
                    # The loop this generation belongs to, so a consumer
                    # can reach the scope declaration without recovering
                    # it from branch topology a transformation may have
                    # rewritten.
                    "source_loop_node_id": loop.source_loop_node_id,
                },
            )
            carried_phis[entry] = self.current.instrs[-1]
            type_source_id = next((
                value_id for value_id in (int(initial_id), int(updated_id))
                if value_id in self.native_value_type_abi
            ), int(initial_id))
            carried_tag = self.merge_native_type_tags(
                type_source_id, current,
                (int(initial.id), int(updated.id)),
                (preheader.name, latch.name),
                binding="while_carried_native_type_tag",
            )
            if carried_tag is not None:
                self.native_value_type_tags[int(initial_id)] = carried_tag
                self.native_value_type_tags[int(updated_id)] = carried_tag
            if initial_id not in bound_initial_ids:
                # LOOP_HEADER: the header Phi is the body's value.
                self._bind(
                    initial_id, current, BindingKind.LOOP_HEADER, loop_cell,
                )
                bound_initial_ids.add(initial_id)
        # Declare the loop as an evolving scope.  The rebind table is
        # exactly what ``carried`` already holds; what was missing is any
        # statement that these three names are one quantity at three
        # generations, which is why three of them could disagree in
        # silence.
        # Program: a loop whose carried value has no ssa_value cell.  Wrong
        # write: the declaration refused and `except Exception: pass` hid it,
        # leaving the loop_scope row half-written.  Rule: the refusal
        # (row = function, loop, binding; fact = value id) propagates.
        # A loop with no source_loop_node_id has no loop_scope row key (the
        # row is (function, loop node id, ...)); rebind_loop_scope_inner is
        # guarded the same way (existing precedent, ~8571).  This was the
        # swallowed TypeError of int(None).  OPEN ITEM: a loop with no node id
        # has no identity and should be refused once the hand-built fixtures
        # declare their loops.
        if loop.source_loop_node_id is not None:
            from .identity_concordance import declare_loop_scope

            # A loop the reducer never saw (no lexical read scope) stands on
            # the function root, as every other construct without a more
            # specific cell does.
            declare_loop_scope(
                self.function_name, loop.source_loop_node_id,
                header.name, latch.name, exit_block.name,
                self._loop_scope_rebinds(loop, carried),
                boundary_cells=(
                    (loop_cell,) if loop_cell is not None
                    else (self._function_root(),)
                ),
                rebind_cells=self._loop_scope_value_cells,
            )
        break_bound_initials = {
            int(initial_id): self._break_bound_initial(
                int(port_id), int(initial_id),
            )
            for port_id, initial_id, updated_id
            in getattr(loop, "result_ports", ())
            if int(updated_id) == int(initial_id)
        }
        result_port_aliases = self._bind_loop_result_ports_inside_body(loop)
        if constant_predicate is None:
            self.conditional_branch(current_predicate, body, exit_block)
        else:
            self.branch(body if constant_predicate else exit_block)
            self.current.instrs[-1].attributes.update({
                "source_control": "while_constant_predicate",
                "source_value_id": int(loop.predicate_value_id),
                "constant_predicate": constant_predicate,
            })

        self.current = body
        self.loop_targets.append((latch, exit_block))
        exit_context = {
            "carried": tuple(
                (updated_id, initial_id, current, initial)
                for updated_id, initial_id, initial, _updated, current
                in carried
            ),
            # A port whose "updated" identity IS its initial identity has no
            # backedge version: the name is bound only on break paths.
            "break_bound": tuple(
                (int(port_id), int(initial_id))
                for port_id, initial_id, updated_id
                in getattr(loop, "result_ports", ())
                if int(updated_id) == int(initial_id)
            ),
            "break_edges": [],
            "continue_edges": [],
            "sites_seen": set(),
            "expected_sites": tuple(
                int(site) for site in getattr(loop, "control_site_ids", ())
            ),
        }
        self.loop_exit_contexts.append(exit_context)
        exit_context = self.loop_exit_contexts[-1]
        preserved_before_body = set(self.preserved_region_output_ids)
        self.preserved_region_output_ids.update(
            int(initial_id) for _updated_id, initial_id, *_rest in carried
        )
        blocks_before_body = {existing.name for existing in self.blocks.values()}
        initial_counts: dict[int, int] = {}
        for _updated_id, initial_id, *_rest in carried:
            initial_counts[int(initial_id)] = (
                initial_counts.get(int(initial_id), 0) + 1
            )
        protected_alias_sources = frozenset(
            int(updated_id)
            for updated_id, initial_id, *_rest in carried
            if initial_counts[int(initial_id)] > 1
        )
        self.protected_loop_alias_sources.append(protected_alias_sources)
        loop_state = self._enter_loop_state(loop, carried)
        self.enclosing_loop_states.append(loop_state)
        try:
            self.lower(loop.body, path=f"{path}.body")
            for mutation in loop.sequence_mutations:
                self.lower_sequence_mutation(mutation, path=path)
            for terminal in loop.terminal_controls:
                self.lower(terminal, path=f"{path}.terminal")
        finally:
            self.enclosing_loop_states.pop()
            self.protected_loop_alias_sources.pop()
            self.preserved_region_output_ids = preserved_before_body
            self.loop_exit_contexts.pop()
            self.loop_targets.pop()
        body_blocks = [
            candidate
            for candidate in self.blocks.values()
            if candidate.name not in blocks_before_body or candidate.name == body.name
        ]
        carried_updates: dict[int, SSAValue] = {}
        for entry, (updated_id, _initial_id, _initial, reserved, _current) in enumerate(carried):
            published = self.external_values.get(updated_id, reserved)
            carried_updates[entry] = published
            if published is not reserved:
                carried_phis[entry].args[1] = published
        if os.environ.get("TURING_DEBUG_LOOP_ALIAS_PUBLICATION"):
            print(
                "DEBUG-WHILE-CARRIED-UPDATES "
                f"fn={self.function_name} path={path} "
                f"updates={tuple((int(carried[entry][0]), int(value.id)) for entry, value in carried_updates.items())!r}",
                file=sys.stderr,
                flush=True,
            )
        produced_results = {
            int(instruction.res.id)
            for basic_block in body_blocks
            for instruction in basic_block.instrs
            if instruction.res is not None
        }
        for entry, (updated_id, _initial_id, _initial, updated, current) in enumerate(carried):
            if int(carried_updates[entry].id) not in produced_results:
                if updated.accounting.get(
                    "loop_carried_preexisting_update"
                ):
                    # The update is an input or another value defined before
                    # the loop, so it correctly dominates the latch without
                    # a producer in the body.  It is not an untouched carried
                    # name and must not be replaced by the header Phi.
                    continue
                declared_outputs = tuple(
                    region_index
                    for region_index, (_feeds, outputs)
                    in self.region_signatures.items()
                    if updated_id in outputs
                )
                if not declared_outputs:
                    # A syntactic identity assignment (``value = value``) or
                    # an untouched arm of a partial assignment has no body
                    # instruction to publish. Its latch definition is the
                    # current iteration's header Phi, not the producerless
                    # placeholder reserved for a possible real update.
                    carried_phis[entry].args[1] = current
                    carried_updates[entry] = current
                    # LOOP_LATCH: the header Phi is the identity backedge.
                    self._bind(
                        updated_id, current, BindingKind.LOOP_LATCH, loop_cell,
                    )
                    current.accounting["ssa_identity_backedge"] = True
                    continue
                self.shortfalls.append(SSALoweringShortfall(
                    "control",
                    "loop_carried",
                    f"{path}.body",
                    f"carried update value {updated_id} has no producer "
                    "inside the while-loop body; "
                    f"alias_source={self.value_aliases.get(updated_id)!r}; "
                    f"declared_region_outputs={declared_outputs}",
                ))
        if not self.current.successors:
            self.branch(latch)

        self.current = latch
        self._complete_loop_latch_carried(
            carried,
            carried_phis,
            carried_updates,
            exit_context["continue_edges"],
        )
        # The latch evaluates the guard for the NEXT iteration, so every
        # carried name must resolve to the body's UPDATED value there --
        # not the header phi it is bound to for the rest of the loop.
        # Testing the pre-update value lags the guard one iteration behind
        # and runs the loop once too often (scorecard level 17: the
        # compiled while halved 1.0 to 0.5 where the authored loop stops).
        latch_restore = []
        latch_initial_ids: set[int] = set()
        for updated_id, initial_id, _initial, updated, _current in carried:
            if initial_id in latch_initial_ids:
                continue
            latch_initial_ids.add(initial_id)
            latch_restore.append(
                (initial_id, self.external_values.get(initial_id))
            )
            # LOOP_LATCH: at the latch the carried name is the body's update.
            self._bind(
                initial_id, self.external_values.get(updated_id, updated),
                BindingKind.LOOP_LATCH, self._binding_cell(updated_id), loop_cell,
            )
        # A retained numeric condition and its explicit scalar expression can
        # both publish the predicate. They must not define the same SSA id.
        # The expression owns the backedge value; numeric projection gets a
        # separate result when both representations are present.
        carried_test = (
            loop.predicate_expression is not None
            and loop.predicate_expression.op == "value"
            and loop.predicate_expression.value_id is not None
            and any(
                int(initial_id) == int(loop.predicate_expression.value_id)
                for _updated_id, initial_id, *_rest in carried
            )
        )
        if carried_test and loop_state is not None:
            # Decision recorded, not held: row ``(control scope, loop)`` ->
            # the carried binding the test reads (``loop_carried_entry``
            # names its entry).  The latch neither re-runs the pre-loop
            # condition regions nor re-publishes the predicate id for it.
            # DERIVED(the ``lexical_read_binding`` cells the predicate read);
            # a bare predicate id with no read position is recorded as
            # ``Unresolved(WHILE_TEST_NO_READ_EXPRESSION)``.
            predicate_cell = self._canonical_cell(
                loop.predicate_expression.value_id
            )
            if loop.predicate_expression.read is not None:
                read_cells = self._read_binding_cells(
                    (tuple(loop.predicate_expression.read),)
                )
                test_fact: Any = tuple(sorted(map(str, self._operand_bindings(
                    (tuple(loop.predicate_expression.read),)
                ))))
                test_sources = self._cells(*read_cells, predicate_cell, loop_cell)
            else:
                test_fact = Unresolved(
                    WHILE_TEST_NO_READ_EXPRESSION,
                    read=self._cells(predicate_cell),
                )
                test_sources = self._cells(predicate_cell, loop_cell)
            if not test_sources:
                test_sources = (self._function_root(),)
            self._book().post(
                WHILE_CARRIED_TEST, loop_state, test_fact,
                stage=self.active_stage,
                provenance=Derived(test_sources),
                mode=Mode.CONCORD,
            )
        if not carried_test:
            # A carried test's id is its binding's initial, which the latch
            # has just rebound to the body's update; that is the next test.
            self._bind(
                int(loop.predicate_value_id),
                self.fresh_value(
                    dtype="bool", transform=CONTROL_PREDICATE,
                    operands=(current_predicate, loop_cell),
                )
                if loop.predicate_expression is not None else next_predicate,
                BindingKind.LOOP_CONTROL, loop_cell,
            )
        preserved_before = set(self.preserved_region_output_ids)
        self.preserved_region_output_ids.update(
            int(initial_id) for _updated_id, initial_id, *_rest in carried
        )
        # The latch re-evaluates the predicate for the next iteration with
        # carried bindings at their updated values; every other binding that
        # shares a carried initial id still reads its pre-loop value, so the
        # loop's frame governs these reads exactly as it governs the body.
        self.enclosing_loop_states.append(loop_state)
        latch_leaf = None
        latch_frame = self.loop_frames.get(loop_state)
        if latch_frame is not None:
            latch_frame["latch"] = True
        latch_generation = self.__dict__.get("_latch_test_generation", False)
        self._latch_test_generation = True
        try:
            if not carried_test:
                # A carried test (``while go:``) has no latch computation:
                # the condition regions produced its pre-loop value, and
                # re-running them would test that value forever.
                self.lower(loop.condition, path=f"{path}.condition.latch")
            if loop.predicate_expression is not None:
                latch_predicate = self.lower_control_expression(
                    loop.predicate_expression,
                    result_override=next_predicate,
                )
                if latch_predicate is not next_predicate:
                    # A bare leaf (``while go:``) computes nothing: the next
                    # test IS the value the leaf resolves to at the latch.
                    header_condition = next(
                        instruction for instruction in header.instrs
                        if instruction.res is current_predicate
                    )
                    header_condition.args[1] = latch_predicate
                    latch_leaf = latch_predicate
        finally:
            self._latch_test_generation = latch_generation
            if latch_frame is not None:
                latch_frame["latch"] = False
            self.enclosing_loop_states.pop()
            self.preserved_region_output_ids = preserved_before
        # Post-loop consumers read the converged header phi, not the last
        # body update: restore the loop-wide binding before leaving.
        for initial_id, previous in latch_restore:
            # RESTORED: post-loop consumers read the header Phi again.
            self._withdraw(initial_id, previous, loop_cell)
        if latch_leaf is None and not any(
            instruction.res is next_predicate
            for instruction in self.current.instrs
        ):
            self.shortfalls.append(SSALoweringShortfall(
                "control",
                "while_condition",
                f"{path}.condition",
                f"predicate value {loop.predicate_value_id} has no producer",
            ))
        if not self.current.successors:
            self.branch(header)
        # Program: ``while d != 0 and 12 // d > 1:`` (c42_while_and_guard_div).
        # Wrong record: the latch test owns a short-circuit conditional, so
        # the latch lowering ends in that conditional's merge block, which
        # is the block that branches to the header; the header Phis still
        # named ``while_latch`` as their incoming block and the backedge
        # operands were dropped as coming from a non-predecessor (the loop
        # never re-tested and ran forever).  Rule: a header Phi's backedge
        # incoming block is the block that emits the backedge.
        backedge_block = self.current
        if (
            backedge_block is not latch
            and header.name in backedge_block.successors
        ):
            for instruction in header.instrs:
                if instruction.op != "Phi":
                    continue
                incoming = tuple(
                    instruction.attributes.get("incoming_blocks") or ()
                )
                if latch.name in incoming:
                    instruction.attributes["incoming_blocks"] = tuple(
                        backedge_block.name if name == latch.name else name
                        for name in incoming
                    )

        if recursion_region_id is not None:
            source = self.recursion_regions[int(recursion_region_id)]
            lowered = self.ssa_recursion_table.setdefault(
                int(recursion_region_id),
                {**source, "function": self.function_name, "loops": []},
            )
            lowered["loops"].append({
                "function": self.function_name,
                "header": header.name,
                "body": body.name,
                "latch": latch.name,
                "exit": exit_block.name,
                "phi_value_ids": (
                    int(current_predicate.id),
                    *(int(current.id) for *_prefix, current in carried),
                ),
                "backedge": (backedge_block.name, header.name),
                "domain": "condition",
                "source_loop_node_id": loop.source_loop_node_id,
            })
        settled_initial_ids: set[int] = set()
        for updated_id, initial_id, _initial, _updated, current in carried:
            # LOOP_HEADER: after the loop every carried spelling denotes
            # the converged header Phi.
            if initial_id not in settled_initial_ids:
                self._bind(
                    initial_id, current, BindingKind.LOOP_HEADER, loop_cell,
                )
                settled_initial_ids.add(initial_id)
            self._bind(updated_id, current, BindingKind.LOOP_HEADER, loop_cell)
        self._bind(
            int(loop.predicate_value_id), current_predicate,
            BindingKind.LOOP_CONTROL, loop_cell,
        )
        for missing_site in sorted(
            set(exit_context["expected_sites"]) - exit_context["sites_seen"]
        ):
            # A source break/continue nothing placed (neither an arm nor the
            # lexical schedule) would silently turn into a loop that runs to
            # completion.
            self.shortfalls.append(SSALoweringShortfall(
                "control", "loop-control-site", path,
                f"source break/continue at graph node {missing_site} was "
                "never placed in the loop body",
            ))
        self._restore_loop_result_port_aliases(result_port_aliases, loop)
        self._restore_ported_loop_seeds(loop, carried)
        self._publish_loop_result_ports(
            loop,
            header=header,
            exit_block=exit_block,
            carried=carried,
            break_edges=tuple(exit_context["break_edges"]),
            break_bound=tuple(exit_context["break_bound"]),
            break_bound_initials=break_bound_initials,
        )

    def lower_state_machine(
        self,
        tick: StateMachineTick,
        *,
        path: str,
    ) -> None:
        if tick.state_value_id is not None:
            # The state is the graph value the selector reads, found through
            # the book like a conditional's predicate -- never a name looked
            # up in the uniform table.
            state = self.external_value(int(tick.state_value_id))
        else:
            state = self.uniform_values.get(str(tick.state))
            if state is None:
                state = self.expression_value(
                    tick.state,
                    location=f"{path}.state",
                )
        merge = self.new_block("state_merge")
        literal_ids = tuple(tick.case_value_ids) + (None,) * (
            len(tick.cases) - len(tick.case_value_ids)
        )
        aliases = tuple(tick.carried_aliases)
        # Each arm starts from the versions the tick was entered with: take
        # the snapshot of every carried initial before any arm lowers, and
        # restore it between arms (a nested merge inside an arm would
        # otherwise leave its result as the next arm's incumbent).  One
        # ``carried_snapshot`` row per id, DERIVED from the binding cell
        # current at entry and the tick's construct cell.
        carried_snapshots = {
            int(initial_id): self.external_value(int(initial_id))
            for _arms, _default, initial_id, _merged in aliases
        }
        tick_cell = self._construct_cell(tick.source_node_id)
        snapshot_cells = (
            self._post_carried_snapshots(tick_cell, carried_snapshots)
            if aliases else {}
        )
        stage_before = self.active_stage
        if aliases:
            self.active_stage = CONTROL_SSA_CONDITIONAL

        def restore_snapshots() -> None:
            for snapshot_id, snapshot_value in carried_snapshots.items():
                if self.external_values.get(int(snapshot_id)) is not snapshot_value:
                    self._bind(
                        int(snapshot_id), snapshot_value, BindingKind.RESTORED,
                        snapshot_cells.get(int(snapshot_id)), tick_cell,
                    )

        # (exit block, {initial id: (arm value, source cell)}) per arm that
        # reaches the merge.
        reaching: list[tuple[BasicBlock, dict[int, tuple[SSAValue, Any]]]] = []

        def arm_values(arm_slot: int | None, where: str) -> dict:
            found = {}
            for arm_ids, default_id, initial_id, _merged in aliases:
                arm_id = (
                    int(default_id) if arm_slot is None
                    else int(arm_ids[arm_slot])
                )
                found[int(initial_id)] = self._carried_name_arm(
                    arm_id, initial_id, carried_snapshots[int(initial_id)],
                    snapshot_cells.get(int(initial_id)), path=where,
                )
            return found

        for index, (case_value, case_body) in enumerate(tick.cases):
            # The case literal is a graph node with an identity cell: the
            # case's blocks and the literal value derive from it.  A case
            # with no node (a hand-built tick) is a bare spelling.
            literal_cell = (
                None if literal_ids[index] is None
                else self._canonical_cell(literal_ids[index])
            )
            case = self.new_block("state_case", also=(literal_cell,))
            otherwise = self.new_block("state_next", also=(literal_cell,))
            literal_int = _case_literal_int(case_value)
            literal = (
                self.constant_value(literal_int, literal_cell)
                if literal_cell is not None and literal_int is not None
                else self.expression_value(
                    case_value,
                    location=f"{path}.case[{index}]",
                )
            )
            condition = self.fresh_value(
                dtype="bool", transform=CONTROL_PREDICATE,
                operands=(state, literal),
            )
            self.emit(Handler.Eq, [state, literal], condition)
            self.conditional_branch(condition, case, otherwise)
            self.current = case
            restore_snapshots()
            values_before_arm = dict(self.external_values)
            self.lower(case_body, path=f"{path}.case[{index}].body")
            falls_through = (
                not self.current.successors
                or merge.name in self.current.successors
            )
            exit_block = self.current
            carried_here = (
                arm_values(index, f"{path}.case[{index}].body")
                if aliases else {}
            )
            if not self.current.successors:
                self.branch(merge)
            if falls_through:
                reaching.append((exit_block, carried_here))
            else:
                # An arm that leaves through its own edge (break / continue /
                # return) never reaches the merge: nothing it binds may.
                self._restore_view(values_before_arm, tick_cell)
            self.current = otherwise
        restore_snapshots()
        if tick.default is not None:
            values_before_arm = dict(self.external_values)
            self.lower(tick.default, path=f"{path}.default")
            falls_through = (
                not self.current.successors
                or merge.name in self.current.successors
            )
            exit_block = self.current
            carried_here = (
                arm_values(None, f"{path}.default") if aliases else {}
            )
            if not self.current.successors:
                self.branch(merge)
            if falls_through:
                reaching.append((exit_block, carried_here))
            else:
                self._restore_view(values_before_arm, tick_cell)
        else:
            # No default arm: a state matching no case falls through with
            # the versions the tick was entered with.
            exit_block = self.current
            carried_here = {
                initial_id: (
                    carried_snapshots[initial_id],
                    snapshot_cells.get(initial_id),
                )
                for initial_id in carried_snapshots
            }
            if not self.current.successors:
                self.branch(merge)
                reaching.append((exit_block, carried_here))
        self.current = merge
        if reaching:
            for arm_ids, default_id, initial_id, merged_id in aliases:
                self._publish_state_merge(
                    state, reaching, carried_snapshots, snapshot_cells,
                    tick_cell, arm_ids, default_id, initial_id, merged_id,
                )
        self.active_stage = stage_before

    def _publish_state_merge(
        self,
        state: SSAValue,
        reaching: list,
        carried_snapshots: Mapping[int, SSAValue],
        snapshot_cells: Mapping[int, Any],
        tick_cell: Any,
        arm_ids: tuple[int, ...],
        default_id: int,
        initial_id: int,
        merged_id: int,
    ) -> None:
        """One Phi joining every arm that reaches a tick's merge for one
        carried scalar, the N-way counterpart of ``lower_conditional``'s
        ``conditional_carried`` Phi.  Its value is made from each arm's
        source cell (its binding, or the snapshot when it did not write),
        the snapshot cell and the state it is selected by; every id taking
        part in the join denotes the merged version afterwards
        (``CONDITIONAL_MERGE``)."""

        initial_id = int(initial_id)
        initial = carried_snapshots[initial_id]
        incoming = [values[initial_id] for _block, values in reaching]
        incoming_values = [value for value, _source in incoming]
        sources = [source for _value, source in incoming]
        phi_operands = (
            *sources, snapshot_cells.get(initial_id), *incoming_values, state,
        )
        if int(merged_id) in {int(value.id) for value in incoming_values}:
            # The graph reuses an arm's write id as the join id: they are the
            # same source version but the join is a distinct SSA definition.
            merged = self.fresh_value(
                dtype=initial.dtype, shape=initial.shape,
                transform=PHI_CONDITIONAL, operands=phi_operands,
            )
            merged.accounting.update({
                "source_value_id": int(merged_id),
                "ssa_conditional_write_version": True,
            })
        else:
            merged = SSAValue(
                int(merged_id), dtype=initial.dtype, shape=initial.shape,
            )
            self._value_cell(merged, *phi_operands)
        self.emit(
            Handler.Phi, incoming_values, merged,
            attributes={
                "incoming_blocks": tuple(block.name for block, _ in reaching),
                "binding": "state_carried",
                "initial_value_id": initial_id,
            },
        )
        merged_type_tag = self.merge_native_type_tags(
            int(merged_id), merged,
            tuple(int(value.id) for value in incoming_values),
            tuple(block.name for block, _ in reaching),
            binding="state_carried_native_type_tag",
        )
        if merged_type_tag is not None:
            for value_id in (
                int(merged_id), initial_id, int(default_id), *map(int, arm_ids),
            ):
                self.native_value_type_tags[int(value_id)] = merged_type_tag
        protected_sources = frozenset().union(
            *self.protected_loop_alias_sources
        ) if self.protected_loop_alias_sources else frozenset()
        published = {int(merged_id): merged}
        for value_id in (initial_id, int(default_id), *map(int, arm_ids)):
            if value_id not in protected_sources:
                published[value_id] = merged
        self._rebind_view(
            published, BindingKind.CONDITIONAL_MERGE, merged, tick_cell,
        )

    def _revise_semantic_output(
        self, name: str, value_id: int, *cause: Any,
    ) -> None:
        """Re-mint of a semantic output: revise the reducer's row.

        Program shape: a function whose returned name is resolved at finish
        to a value other than the one the reducer bound (the single-exit
        result, a loop-exit Phi, a freshened id).  Wrong record: the
        reducer's ``semantic_output`` row left naming the pre-control id while
        ``named_returns`` carries the merged one.  Rule: the pass that fixes
        the new value revises the row at that moment, DERIVED from the
        reducer's row cell and the new value's ``ssa_value`` cell.
        """

        scope = self.lexical_read_scope
        if scope is None:
            return
        from .concordance_declarations import SEMANTIC_OUTPUT

        book = self._book()
        page = book.page(SEMANTIC_OUTPUT)
        for row in page.scope_rows(scope):
            fact = page.latest(row)
            if fact is None or str(fact[0]) != str(name):
                continue
            if int(fact[1]) == int(value_id):
                return
            sources = self._cells(
                book.latest_ref(SEMANTIC_OUTPUT, row),
                book.latest_ref(SSA_VALUE, (self._scope(), int(value_id))),
                *cause,
            )
            book.post(
                SEMANTIC_OUTPUT, row, (str(name), int(value_id)),
                stage=self._stage(CONTROL_SSA_FINISH),
                provenance=Derived(sources), mode=Mode.REVISE,
            )
            return

    def _posted_carried_ports(self) -> dict[int, SSAValue]:
        """port id -> the Phi object the ``carried_port_value`` row's cell
        names, read from the book under this lowering's scope."""

        book = self._book()
        scope = self._scope()
        page = book.pages.get(CARRIED_PORT_VALUE.name)
        ports: dict[int, SSAValue] = {}
        for row in (() if page is None else page.scope_rows(scope)):
            fact = page.latest(row)
            if not isinstance(fact, Ref):
                continue
            port = self.ssa_value_objects.get(int(fact.row[1]))
            if port is not None:
                ports[int(row[1])] = port
        return ports

    def _posted_alias_source(self, value_id: int) -> int | None:
        """The source the latest ``control_value_alias`` row of ``value_id``
        names, or ``None`` (no row, or a withdrawn alias)."""

        page = self._book().pages.get(CONTROL_VALUE_ALIAS.name)
        if page is None:
            return None
        fact = page.latest((self._scope(), int(value_id)))
        if isinstance(fact, AliasFact) and fact.source_id is not None:
            return int(fact.source_id)
        return None

    def _finish_pages(
        self,
        named_returns: tuple,
        parameter_value_names: tuple,
        returned: tuple,
    ) -> dict[str, Any]:
        """Post ``function_parameter`` / ``function_output`` and materialize
        the metadata tuples from the pages (plan 80 B2.6).

        ``parameter_names`` and ``named_outputs`` are read back from the rows
        just posted; ``carried_port_values`` and ``value_aliases`` from the
        ``carried_port_value`` and ``control_value_alias`` pages.  Each is
        checked against the value the builder computed and the computed
        value is kept when a page cannot reproduce it (a duplicate returned
        id, a port whose object the table lost), so the metadata the 18
        readers consume stays byte-identical to today.
        """

        book = self._book()
        scope = self._scope()
        # -- function_parameter: DERIVED(declared_parameter USED, the
        #    argument's ssa_value cell, its binding cell).
        for name, value_id in parameter_value_names:
            declared = self._declare_parameter(value_id, ParameterDeclaration.USED)
            argument = self.ssa_value_objects.get(int(value_id))
            self._post_concord(
                FUNCTION_PARAMETER, (scope, str(name)), int(value_id),
                declared, self._binding_cell(value_id), argument,
                stage=CONTROL_SSA_FINISH,
            )
        page = book.pages.get(FUNCTION_PARAMETER.name)
        parameter_names = tuple(
            (str(row[1]), int(page.latest(row)))
            for row in (() if page is None else page.scope_rows(scope))
            if page.latest(row) is not None
        )
        if parameter_names != tuple(parameter_value_names):
            parameter_names = tuple(parameter_value_names)
        # -- function_output: slot -> (name or None, ssa id), DERIVED(the
        #    slot value's cell (the merge Phi or the single edge's value)).
        pending_names = list(named_returns)
        for slot, value in enumerate(returned):
            name = next(
                (
                    candidate for candidate, value_id in pending_names
                    if int(value_id) == int(value.id)
                ),
                None,
            )
            if name is not None:
                pending_names.remove((name, next(
                    value_id for candidate, value_id in pending_names
                    if candidate == name and int(value_id) == int(value.id)
                )))
            self._post_concord(
                FUNCTION_OUTPUT, (scope, int(slot)), (name, int(value.id)),
                value, self._binding_cell(value.id), stage=CONTROL_SSA_FINISH,
            )
        page = book.pages.get(FUNCTION_OUTPUT.name)
        named_outputs = tuple(
            (str(fact[0]), int(fact[1]))
            for row in (() if page is None else page.scope_rows(scope))
            for fact in (page.latest(row),)
            if fact is not None and fact[0] is not None
        )
        # Program shape: a function whose named returns the builder holds in
        # ``named_returns`` while the ``function_output`` rows say otherwise.
        # Wrong record: the dict replaced the book's answer after it had been
        # computed and compared (authority inverted).  Rule: the posted rows
        # are the output; a disagreement is a discordance and is refused with
        # both values, never overridden in either direction.
        if named_outputs != tuple(named_returns):
            raise ConcordanceRefusal(
                f"function_output page, scope {scope!r}: the posted rows name "
                f"{named_outputs!r} but the builder's named_returns is "
                f"{tuple(named_returns)!r} in {self.function_name!r}"
            )
        # -- carried_port_values: port -> the Phi object the page's cell names.
        # Program shape: a loop whose exit Phi is published as a carried port.
        # Wrong record: the live ``_carried_port_values`` dict over the
        # ``carried_port_value`` row.  Rule: the row is read; disagreement is
        # refused naming the row, the book's Phi and the dict's.
        legacy_ports = dict(getattr(self, "_carried_port_values", {}) or {})
        carried_port_values = self._posted_carried_ports()
        if carried_port_values != legacy_ports:
            discordant = sorted(
                port for port in set(carried_port_values) | set(legacy_ports)
                if carried_port_values.get(port) is not legacy_ports.get(port)
            )
            port = discordant[0]
            book_port = carried_port_values.get(port)
            dict_port = legacy_ports.get(port)
            raise ConcordanceRefusal(
                f"carried_port_value page, row {(scope, port)!r}: the posted "
                f"row names value "
                f"{None if book_port is None else int(book_port.id)!r} but "
                f"_carried_port_values holds "
                f"{None if dict_port is None else int(dict_port.id)!r} in "
                f"{self.function_name!r}"
            )
        # -- value_aliases: alias -> source, the latest alias rows.
        # Program shape: an in-place store chain / loop exit alias.  Wrong
        # record: the live ``value_aliases`` dict (which loops rewrite while
        # their bodies lower) over the ``control_value_alias`` rows.  Rule:
        # the rows are the view; disagreement is refused with both sources.
        page = book.pages.get(CONTROL_VALUE_ALIAS.name)
        value_aliases: dict[int, int] = {}
        for row in (() if page is None else page.scope_rows(scope)):
            fact = page.latest(row)
            if isinstance(fact, AliasFact) and fact.source_id is not None:
                value_aliases[int(row[1])] = int(fact.source_id)
        if value_aliases != dict(self.value_aliases):
            live = dict(self.value_aliases)
            alias = sorted(
                key for key in set(value_aliases) | set(live)
                if value_aliases.get(key) != live.get(key)
            )[0]
            raise ConcordanceRefusal(
                f"control_value_alias page, row {(scope, alias)!r}: the "
                f"posted row names source {value_aliases.get(alias)!r} but "
                f"value_aliases holds {live.get(alias)!r} in "
                f"{self.function_name!r}"
            )
        return {
            "parameter_names": parameter_names,
            "named_outputs": named_outputs,
            "carried_port_values": carried_port_values,
            "value_aliases": value_aliases,
        }

    def _return_output_arms_record(self) -> Any:
        """The function's ``return_output_arms`` fact and its output id, read
        from the book by the function's read scope (one row per function
        whose returns disagree on arity), or ``None``.  An ``Unresolved``
        row is no record."""

        from .concordance_declarations import RETURN_OUTPUT_ARMS, ReturnOutputArms

        if self.lexical_read_scope is None:
            return None
        book = self._book()
        page = book.pages.get(RETURN_OUTPUT_ARMS.name)
        if page is None:
            return None
        for row in page.scope_rows(tuple(self.lexical_read_scope)):
            cell = book.latest_ref(RETURN_OUTPUT_ARMS, row)
            fact = None if cell is None else page.cell(cell.row, cell.column)
            if isinstance(fact, ReturnOutputArms):
                return int(row[1]), fact
        return None

    def _copy_divergent_sequence_returns(
        self,
        slot: int,
        edges: list,
        incoming_values: list[SSAValue],
        incoming_blocks: list[str],
        output_name: str | None,
    ) -> list[SSAValue]:
        """Copy each return edge's list into the one result list.

        Program: ``if n > 2: return [n]`` / ``return []`` then ``t =
        pick(n); len(t)`` (lanes plan A6).  Wrong record: the two return
        sites build two lists (two arenas) and the exit joined them with a
        bare pointer Phi, while the caller reads the result arena it passed
        for the output (the last return's list), so ``[n]`` was lost.  The
        planner refused it by name.  Rule: the output's list is the one
        result storage.  An edge returning a different list replaces the
        result's rows with its own (``replace``: clear and extend) before it
        branches to the exit, and the merge is the result itself.  The
        planner admits this only for lists born in the callee, which die at
        the return, so the copy is unobservable.
        """

        history = tuple(map(int, (
            self.named_output_histories.get(str(output_name)) or ()
        ))) if output_name is not None else ()
        if not history:
            return incoming_values
        identities = {int(value.id) for value in incoming_values}
        if len(identities) < 2 or int(history[-1]) not in identities:
            return incoming_values
        destination = next(
            value for value in incoming_values
            if int(value.id) == int(history[-1])
        )
        if any(
            self.sequence_descriptors.get(int(value.id)) is None
            for value in incoming_values
        ):
            return incoming_values
        copied = list(incoming_values)
        for position, (block, values) in enumerate(edges):
            value = incoming_values[position]
            if int(value.id) == int(destination.id):
                continue
            self.current = block
            terminator = block.instrs.pop()
            self.lower_sequence_mutation(
                ControlSequenceMutation(
                    int(destination.id), "replace", (int(value.id),),
                    int(destination.id), policy="duplicates",
                    argument_kind="return_edge_sequence",
                ),
                path=f"{self.function_name}.return_slot[{slot}]",
            )
            self.current.instrs.append(terminator)
            edges[position] = (self.current, values)
            incoming_blocks[position] = self.current.name
            copied[position] = destination
        return copied

    def _return_merge_sequence_destination(
        self, merged: SSAValue, incoming_values: Iterable[SSAValue],
    ) -> SSAValue:
        """Make a return merge whose arms are ALL sequence arenas ONE sequence.

        Program: ``_detached_ordinals`` -- ``if not d: return []`` then
        ``return sorted(chain.from_iterable(...))``.  Both returns are
        resident sequences, so the reducer minted no merge value and the
        guard keeps two return edges.
        Wrong record: the ``return_merge`` Phi was a bare minted value with
        dtype 'unknown', no frame accounting and no key in the sequence
        table, so the published output was an ``unresolved-boundary-types``
        shortfall even though both arms (and ``output_identity_aliases``,
        arm -> Phi) already name it as their one output.
        Rule now holding: the merge OWNS a sequence descriptor (the same
        ``_sequence_descriptor`` helper every destination uses, with the
        arms' policy/width and the first known element dtype per column), its
        data arena is claimed by the Phi exactly as the ``conditional_result``
        merge claims its graph id, and the arms reach it through the
        existing ``output_identity_aliases`` edges.  A merge with any
        non-sequence arm, or arms that disagree on policy/width, is returned
        unchanged (mixed merges stay on the bare-Phi path).
        """

        arms = [
            self.sequence_descriptors.get(int(value.id))
            for value in incoming_values
        ]
        if not arms or any(arm is None for arm in arms):
            return merged
        policies = {"unique" if arm.key_columns else "duplicates" for arm in arms}
        widths = {len(arm.column_value_ids) for arm in arms}
        if (
            len(policies) != 1 or len(widths) != 1
            or any(arm.child_table_pool is not None for arm in arms)
        ):
            return merged
        width = next(iter(widths))
        column_dtypes = tuple(
            next((
                str(arm.column_dtypes[column]) for arm in arms
                if column < len(arm.column_dtypes)
                and str(arm.column_dtypes[column]) not in {
                    "", "None", "unknown",
                }
            ), "unknown")
            for column in range(width)
        )
        descriptor = self._sequence_descriptor(
            int(merged.id),
            policy=next(iter(policies)),
            writable=True,
            location=f"{self.function_name}.return_merge",
            column_count=width,
            retains_deleted_rows=any(
                arm.live_flags_value_id is not None for arm in arms
            ),
            column_dtypes=column_dtypes,
        )
        if descriptor is None:
            return merged
        return self.produced_value(
            int(merged.id), claim_provisional_definition=True,
            cause=tuple(incoming_values),
        )

    def finish(self) -> tuple[Function, tuple[SSALoweringShortfall, ...]]:
        self.active_stage = CONTROL_SSA_FINISH
        self.settle_selected_child_element_dtypes()
        returned = []
        named_returns = []
        returned_ids = set()
        # Every identity a RESOLVED named return has ever worn. An output
        # id that is an earlier binding of such a name is the same authored
        # output seen through a stale identity -- a while loop rebinding
        # ``total`` leaves the return node's captured id pointing at the
        # pre-loop value, and returning both publishes the scalar twice
        # (scorecard level 17: (0.5, 0.5) for 0.5).
        superseded: set[int] = set()
        # Program shape: a function returning a loop's carried result.  Wrong
        # record: the live ``_carried_port_values`` dict read for the output
        # instead of the ``carried_port_value`` rows.  Rule: read the rows.
        carried_port_values = self._posted_carried_ports()

        def existing_value(value_id: int) -> SSAValue | None:
            """Resolve an authored assignment alias without inventing an ABI input.

            An alias chain such as ``surface_velocity[..., 1] = ...`` over
            ``surface_velocity[..., 2] = ...`` over ``point * 0.0`` names ONE
            storage in successive versions.  The region that performs the
            writes publishes the version it produced (the latest), not the
            root arena, so the published value is found by checking each
            version from the returned identity toward the root and taking the
            first one that exists.  Looking up only the root dropped every
            return built by in-place stores, and for an in/out parameter
            returned the pre-write arena that the stale-identity filter then
            removed.
            """
            value_id = int(value_id)
            seen: set[int] = set()
            while True:
                found = self.external_values.get(value_id)
                if found is not None:
                    return found
                # Program shape: an in-place store chain whose returned id is a
                # later version.  Wrong record: the live ``value_aliases``
                # dict, which loops rewrite, walked for the chain.  Rule: each
                # step reads its posted ``control_value_alias`` row.
                source = self._posted_alias_source(value_id)
                if source is not None and value_id not in seen:
                    seen.add(value_id)
                    value_id = source
                    continue
                return None

        def owned_literal(value_id: int) -> SSAValue | None:
            """Resolve an output whose identity is a canonical literal.

            ``z = 0; t = x + z; return t, z``: no region publishes ``z``.
            The planner keeps every region's rematerialised copy private
            (``control_owned_literals``) and the control function owns the
            literal, so resolve it as the provisional formal that
            ``_materialize_control_constants`` turns into this function's
            own ``Const`` -- exactly how a folded ``flag = True; break`` is
            resolved on its break edge.  Silently dropping it here left the
            output to the call-frame pass, which found the callee's private
            copy and appended it to the region call's declared outputs after
            the callee's Ret was already fixed: on the vehicle body, 144
            declared against 143 produced, the literal's id last.
            """
            if int(value_id) not in self.constant_value_ids:
                return None
            return self.external_value(int(value_id))

        def owned_row_load(value_id: int) -> SSAValue | None:
            """Resolve an output that is a control-owned resident row read.

            Program: ``xs = [3, n * 2]; xs.append(5); return xs[1]``
            (scratch lp/c_n).  Wrong record: the read is a consumer row
            load, emitted only when a consumer asks ``external_value`` for
            it; no region consumes a bare returned read, ``existing_value``
            does not ask, so the output was skipped and the function
            returned nothing (an empty result; clean audit).  Rule: a
            returned row read is control-owned like a returned length, so
            materialize its declared load here.
            """
            if int(value_id) not in self.consumer_row_loads:
                return None
            return self.external_value(int(value_id))

        def owned_length(value_id: int) -> SSAValue | None:
            """Resolve an output that is a control-owned sequence length.

            Program: ``for x in xs: if x < 0: return x`` then ``return
            len(xs)`` over a list parameter (lanes plan C7).  Wrong record:
            the length is loaded only when a consumer asks for it, so the
            named output resolved to nothing; the length reached ``Ret``
            through the unnamed outputs, the return merge was never named
            the output, and recovery replaced the exit Phi by the length:
            the early return was lost (4 for -3; one finding).  Rule: a
            returned length is control-owned like a returned row read
            (and as the unnamed outputs below already treat it).
            """
            sequence_id = self.sequence_length_values.get(int(value_id))
            if sequence_id is None or (
                sequence_id not in self.sequence_descriptors
                and sequence_id not in self.native_object_source_ids
            ):
                return None
            return self.external_value(int(value_id))

        for name, history in self.named_output_histories.items():
            if self.function_return_edges:
                # With explicit return edges, source history is the temporal
                # authority for the still-open lexical fallthrough. Resolve
                # each version completely before considering an older one: a
                # newest owned literal (especially ``None``) must not lose to
                # an already-materialized value from an earlier return.
                value = next((
                    resolved
                    for value_id in reversed(history)
                    for resolved in (
                        existing_value(value_id) or owned_row_load(value_id)
                        or owned_length(value_id) or owned_literal(value_id),
                    )
                    if resolved is not None
                ), None)
            else:
                # In a single-exit conditional, histories contain competing
                # arm assignments rather than a temporal fallthrough. Prefer
                # the value materialized by control lowering; only use an
                # owned literal if no arm/join value exists.
                value = next((
                    resolved
                    for value_id in reversed(history)
                    for resolved in (
                        existing_value(value_id) or owned_row_load(value_id)
                        or owned_length(value_id),
                    )
                    if resolved is not None
                ), None)
                if value is None:
                    # Program: ``if flag > 0: fork = (row + 1, row * 2)
                    # else: fork = None; return fork`` (also the bootstrap's
                    # single-exit rewrite of ``if c: return (a, b)`` /
                    # ``return None``).  Wrong record: history (9, 10, 11)
                    # had no materialized value -- not the tuple arm (9), not
                    # the join (11) -- so the owned ``None`` literal (10)
                    # became the output and the tuple vanished from ``Ret``.
                    # Rule: an owned literal stands for the output only when
                    # it is the name's newest binding; a newer binding that
                    # nothing materialized is refused by name.
                    literal_position = next((
                        position
                        for position in reversed(range(len(history)))
                        if owned_literal(history[position]) is not None
                    ), None)
                    if (
                        literal_position is not None
                        and literal_position != len(history) - 1
                    ):
                        raise ValueError(
                            f"returned name {name!r}: its newest binding "
                            f"(value {int(history[-1])}) was not "
                            "materialized; returning the older literal "
                            f"(value {int(history[literal_position])}) "
                            "would drop it"
                        )
                    value = next((
                        resolved
                        for value_id in reversed(history)
                        for resolved in (owned_literal(value_id),)
                        if resolved is not None
                    ), None)
            if value is None:
                continue
            # A returned name whose final identity is a LoopResult port means
            # the carried phi -- the port id doubles as a written field slot
            # whose cell nothing stores.
            value = carried_port_values.get(int(value.id), value)
            named_returns.append((name, int(value.id)))
            self._revise_semantic_output(name, int(value.id))
            superseded.update(map(int, history))
            # Program: ``a = p; b = p; return a, b`` (the tire's
            # ``balloon_tire_membrane_face``: ``pressure_force_1_x_n`` and
            # ``pressure_force_0_x_n`` are one sympy value).  Wrong record:
            # the second name sharing an id got no slot, so its
            # ``function_output`` row was never posted and the page refused
            # against ``named_returns``.  Rule: every named return is its own
            # output slot; only unnamed outputs are deduplicated by id.
            returned.append(value)
            returned_ids.add(value.id)
        for value_id in self.output_value_ids:
            value = self.external_values.get(value_id)
            if value is None:
                value = owned_literal(value_id)
            # ``return len(book.objects[h].members)`` is control-owned:
            # no numerical region publishes it. Its exact source Call was
            # already bound to a resident descriptor by sequence_length_values.
            # Materialize that declared length, not a provisional ABI formal.
            if (value is None and value_id in self.sequence_length_values
                    and (self.sequence_length_values[value_id] in self.sequence_descriptors
                         or self.sequence_length_values[value_id] in self.native_object_source_ids)):
                value = self.external_value(value_id)
            if value is not None:
                value = carried_port_values.get(int(value.id), value)
            if value is None or value.id in returned_ids:
                continue
            if int(value_id) in superseded or int(value.id) in superseded:
                continue
            returned.append(value)
            returned_ids.add(value.id)
        value_names = []
        for name, history in self.value_name_histories.items():
            value = next((
                self.external_values[value_id]
                for value_id in reversed(history)
                if value_id in self.external_values
            ), None)
            if (
                value is not None
                and int(value.id) not in self.declared_parameter_only_ids
            ):
                value_names.append((name, int(value.id)))
        argument_ids = {int(value.id) for value in self.arguments}
        parameter_value_names = tuple(
            (name, value_id)
            for name, value_id in value_names
            if name in self.parameter_names and int(value_id) in argument_ids
        )
        # Structured control expressions can consume the initial authored
        # parameter and then publish a loop-carried alias as the latest value
        # in its identity history.  Keep the actual ABI argument named when it
        # is referenced by emitted SSA; do not revive parameters that were
        # preserved in the signature but genuinely unused.
        used_value_ids = {
            int(value.id)
            for block in self.blocks.values()
            for instruction in block.instrs
            for value in instruction.args
        }
        # The function's ``Ret`` is emitted after this naming pass, so a
        # parameter whose only use is being returned (``return vehicle_input,
        # ...``) is not yet visible in any block.  Returning an argument is a
        # real ABI use: the caller must supply it, so it must keep its name.
        used_value_ids.update(int(value.id) for value in returned)
        named_parameters = {name for name, _ in parameter_value_names}
        additional_parameters = []
        for name in self.parameter_names:
            if name in named_parameters:
                continue
            value_id = next((
                int(candidate)
                for candidate in self.value_name_histories.get(name, ())
                if int(candidate) in argument_ids
                and int(candidate) in used_value_ids
            ), None)
            if value_id is None:
                continue
            # One authored parameter name is one ABI slot.  Reassignments of
            # that name may also be control-function arguments when their
            # producing region is linked separately, but they are later
            # lexical versions, not additional parameters with the same name.
            additional_parameters.append((name, value_id))
            named_parameters.add(name)
        parameter_value_names += tuple(additional_parameters)
        deployment_regions = []
        for record in self.deployment_records:
            declared_lanes = {
                int(lane.index): lane
                for lane in record.get("declared_lanes", ())
            }
            lane_sites: dict[int, list[tuple[str, int]]] = {
                index: [] for index in range(int(record["lane_count"]))
            }
            lane_callees: dict[int, list[str]] = {
                index: [] for index in lane_sites
            }
            lane_regions: dict[int, list[int]] = {
                index: [] for index in lane_sites
            }
            for block_name, basic_block in self.blocks.items():
                for instruction_index, instruction in enumerate(
                    basic_block.instrs
                ):
                    memberships = tuple(
                        instruction.attributes.get(
                            "deployment_memberships", ()
                        )
                    )
                    for region_id, lane_index in memberships:
                        if int(region_id) != int(record["region_id"]):
                            continue
                        lane_index = int(lane_index)
                        lane_sites[lane_index].append(
                            (block_name, instruction_index)
                        )
                        callee = instruction.attributes.get("callee")
                        if callee is not None:
                            lane_callees[lane_index].append(str(callee))
                        source_region = instruction.attributes.get(
                            "region_index"
                        )
                        if source_region is not None:
                            lane_regions[lane_index].append(
                                int(source_region)
                            )
            deployment_regions.append(SSADeploymentRegion(
                region_id=int(record["region_id"]),
                function=self.function_name,
                kind=str(record["kind"]),
                schedule=str(record["schedule"]),
                schedule_preference=str(record["schedule_preference"]),
                lanes=tuple(
                    SSADeploymentLane(
                        index=index,
                        instruction_sites=tuple(lane_sites[index]),
                        callees=tuple(dict.fromkeys(lane_callees[index])),
                        source_region_indices=tuple(dict.fromkeys(
                            lane_regions[index]
                        )),
                        source_value_ids=tuple(
                            declared_lanes[index].value_ids
                            if index in declared_lanes else ()
                        ),
                        source_node_ids=tuple(
                            declared_lanes[index].source_node_ids
                            if index in declared_lanes else ()
                        ),
                    )
                    for index in sorted(lane_sites)
                ),
                iteration_space=record["iteration_space"],
                carried_aliases=tuple(record["carried_aliases"]),
                recursion_region_id=record["recursion_region_id"],
                origin=str(record["origin"]),
                source_loop_node_id=record["source_loop_node_id"],
                scale=int(record.get("scale", 1)),
                join=record["join"],
                deploy_site=record.get("deploy_site"),
                join_site=record.get("join_site"),
            ))
        optional_glyph_return_layouts = []
        optional_glyph_return_slots: list[tuple[int, int, int]] = []
        logical_to_physical_return_slot: dict[int, int] = {}
        if self.optional_glyph_presence_by_value:
            physical_returns = []
            optional_presence_by_slot: dict[int, SSAValue] = {}
            for slot, value in enumerate(returned):
                logical_to_physical_return_slot[int(slot)] = len(
                    physical_returns
                )
                presence = self.optional_glyph_presence_by_value.get(
                    int(value.id)
                )
                physical_returns.append(value)
                if presence is not None:
                    optional_presence_by_slot[int(slot)] = presence
                    physical_returns.append(presence)
                    optional_glyph_return_slots.append((
                        int(value.id),
                        len(physical_returns) - 2,
                        len(physical_returns) - 1,
                    ))
            returned = physical_returns
            if self.function_return_edges:
                # Expand each authored return from the exact presence value
                # published for that edge by its conditional-arm source fact.
                # The final merged presence cannot be used here: early return
                # edges do not pass through its merge block.
                expanded_edges = []
                for block, values in self.function_return_edges:
                    physical_values = []
                    for slot, value in enumerate(values):
                        physical_values.append(value)
                        if int(slot) not in optional_presence_by_slot:
                            continue
                        presence = (
                            self.optional_glyph_return_presence_by_edge_slot.get(
                                (str(block.name), int(slot))
                            )
                        )
                        if presence is None:
                            raise ValueError(
                                f"{self.function_name}: optional glyph return "
                                f"edge {block.name!r} slot {slot} has no exact "
                                "arm presence"
                            )
                        physical_values.append(presence)
                    expanded_edges.append((block, tuple(physical_values)))
                self.function_return_edges = expanded_edges
        else:
            logical_to_physical_return_slot = {
                int(slot): int(slot) for slot in range(len(returned))
            }
        native_type_return_slots = []
        native_value_union_return_layouts = []
        typed_logical_returns = []
        for logical_slot, physical_slot in sorted(
            logical_to_physical_return_slot.items()
        ):
            if physical_slot >= len(returned):
                continue
            declared_id = (
                int(named_returns[logical_slot][1])
                if logical_slot < len(named_returns) else
                int(returned[physical_slot].id)
            )
            type_fact = self.native_value_type_abi.get(declared_id)
            alternatives = tuple(
                type_fact.get("alternatives", ())
                if isinstance(type_fact, Mapping)
                else getattr(type_fact, "alternatives", ())
            )
            if len(alternatives) > 1:
                typed_logical_returns.append((
                    int(logical_slot), int(physical_slot),
                    int(declared_id), type_fact,
                ))
        if typed_logical_returns:
            typed_by_physical = {
                int(physical_slot): (
                    int(logical_slot), int(declared_id), type_fact,
                )
                for logical_slot, physical_slot, declared_id, type_fact
                in typed_logical_returns
            }

            def union_result_frame(
                source_id: int, source_value: SSAValue, type_fact: object,
            ) -> tuple[tuple[SSAValue, ...], tuple[tuple, ...]]:
                physical = tuple(
                    type_fact.get("physical_alternatives", ())
                    if isinstance(type_fact, Mapping)
                    else getattr(type_fact, "physical_alternatives", ())
                )
                payloads = self._native_value_union_row_payloads(
                    int(source_id), source_value, type_fact,
                )
                payload_iter = iter(payloads)
                values = []
                roles = []
                sequence_arms = self.native_value_union_sequence_ids.get(
                    int(source_id), {}
                )
                retained_payloads = self.native_value_union_payloads.get(
                    int(source_id), {}
                )
                material_arms = tuple(
                    arm for arm in physical
                    if str(arm.storage) != "none"
                )
                shared_payload = bool(material_arms) and len({
                    (
                        str(arm.storage), str(arm.dtype),
                        tuple(arm.shape or ()), int(arm.rank),
                        tuple(arm.storage_identity or ()),
                    )
                    for arm in material_arms
                }) == 1 and all(
                    str(arm.storage) not in {"sequence", "record"}
                    for arm in material_arms
                )
                for arm in physical:
                    identity = str(arm.identity)
                    storage = str(arm.storage)
                    if storage == "none":
                        continue
                    if shared_payload and arm is not material_arms[0]:
                        continue
                    if storage == "sequence":
                        sequence_id = sequence_arms.get(identity)
                        if sequence_id is not None:
                            arm_values = self._native_union_sequence_values(
                                int(sequence_id)
                            )
                        else:
                            arm_values = tuple(
                                retained_payloads.get(identity, ())
                            )
                            if not (
                                len(arm_values) == 1
                                and str(arm_values[0].dtype) == "int64"
                                and not tuple(arm_values[0].shape or ())
                            ):
                                raise ValueError(
                                    "native union result sequence arm has no "
                                    "exact descriptor or native handle: "
                                    f"value={int(source_id)}, arm={identity!r}"
                                )
                    elif storage in {"record", "reference"}:
                        raise ValueError(
                            "native union result aggregate/reference arm "
                            "requires its exact descriptor-backed frame: "
                            f"value={int(source_id)}, arm={identity!r}"
                        )
                    else:
                        arm_values = (next(payload_iter),)
                    for position, arm_value in enumerate(arm_values):
                        values.append(arm_value)
                        roles.append(
                            ("shared", "value", position)
                            if shared_payload else
                            ("alternative", identity, position)
                        )
                tag = self.native_type_tag_for(int(source_id), type_fact)
                if tag is None:
                    raise ValueError(
                        "native union result has no exact type tag: "
                        f"value={int(source_id)}"
                    )
                values.append(tag)
                roles.append(("tag",))
                return tuple(values), tuple(roles)

            expanded_returns = []
            expanded_mapping = {}
            layouts_by_logical = {}
            for physical_slot, value in enumerate(returned):
                typed = typed_by_physical.get(int(physical_slot))
                if typed is None:
                    expanded_returns.append(value)
                    continue
                logical_slot, declared_id, type_fact = typed
                expanded_mapping[int(logical_slot)] = len(expanded_returns)
                frame, roles = union_result_frame(
                    int(declared_id), value, type_fact,
                )
                start = len(expanded_returns)
                expanded_returns.extend(frame)
                layouts_by_logical[int(logical_slot)] = (
                    int(declared_id), tuple(
                        (role, start + offset)
                        for offset, role in enumerate(roles)
                    ),
                )
            for logical_slot, physical_slot in (
                logical_to_physical_return_slot.items()
            ):
                expanded_mapping.setdefault(
                    int(logical_slot), int(physical_slot)
                )
            returned = expanded_returns
            logical_to_physical_return_slot = expanded_mapping
            native_value_union_return_layouts = [
                layouts_by_logical[logical_slot]
                for logical_slot in sorted(layouts_by_logical)
            ]
            if self.function_return_edges:
                expanded_edges = []
                for block, values in self.function_return_edges:
                    prior = self.current
                    self.current = block
                    terminator = (
                        block.instrs.pop()
                        if block.instrs and block.instrs[-1].op
                        in {Handler.Br.value, Handler.CondBr.value}
                        else None
                    )
                    physical_values = []
                    for physical_slot, value in enumerate(values):
                        typed = typed_by_physical.get(int(physical_slot))
                        if typed is None or value is None:
                            physical_values.append(value)
                            continue
                        _logical_slot, declared_id, type_fact = typed
                        frame, _roles = union_result_frame(
                            int(value.id), value, type_fact,
                        )
                        physical_values.extend(frame)
                    if terminator is not None:
                        block.instrs.append(terminator)
                    self.current = prior
                    expanded_edges.append((block, tuple(physical_values)))
                self.function_return_edges = expanded_edges
        block_names = tuple(self.blocks)
        reachable_blocks = {block_names[0]}
        reachable_frontier = [block_names[0]]
        while reachable_frontier:
            block_name = reachable_frontier.pop()
            for successor in self.blocks[block_name].successors:
                if successor in self.blocks and successor not in reachable_blocks:
                    reachable_blocks.add(successor)
                    reachable_frontier.append(successor)
        fallthrough_open = self.current.name in reachable_blocks and (
            not self.current.successors
        ) and (
            not self.current.instrs
            or self.current.instrs[-1].op
            not in {Handler.Br.value, Handler.CondBr.value, Handler.Ret.value}
        )
        return_arm_layouts = {}
        aggregate_layout_sources = {}
        if self.function_return_edges:
            # Control-aware result merging: every source ``return`` below the
            # top level branched to `function_exit` carrying its own slot
            # values; the lexical fall-through epilogue (if still open) is
            # one more edge carrying the values computed above. One Phi per
            # output slot, one Ret -- never "the last return's values on
            # every path".
            edges = list(self.function_return_edges)
            # The record (``return_output_arms``) names each return site's
            # arity and absence; an edge joins its arm by the site cell its
            # own branch carries.  An edge no arm names (the open lexical
            # epilogue, a site the record lacks) leaves the function on the
            # unchanged path.
            from .concordance_declarations import ReturnArmsKind

            arms_record = self._return_output_arms_record()
            edge_arms: dict[int, Any] = {}
            if arms_record is not None:
                for block, _values in edges:
                    site = (
                        block.instrs[-1].attributes.get("return_site_cell")
                        if block.instrs else None
                    )
                    arm = next((
                        candidate for candidate in arms_record[1].arms
                        if site is not None and candidate.site == site
                    ), None)
                    if arm is None:
                        arms_record = None
                        break
                    edge_arms[id(block)] = arm
                if fallthrough_open and arms_record is not None:
                    # The open lexical epilogue IS the function's final
                    # ``return`` when the record declares an arm ``tail``;
                    # it joins that arm and carries its site on its edge.
                    # Without a declared tail arm the epilogue is an
                    # unrecorded path and the record does not cover it.
                    tail_arms = [
                        candidate for candidate in arms_record[1].arms
                        if candidate.tail
                    ]
                    if len(tail_arms) == 1:
                        edge_arms[id(self.current)] = tail_arms[0]
                    else:
                        arms_record = None
            record_kind = None if arms_record is None else arms_record[1].kind
            fallthrough_returned = list(returned)
            tail_arm = edge_arms.get(id(self.current)) if fallthrough_open else None
            if tail_arm is not None and not tail_arm.absent:
                from .concordance_declarations import RETURN_SITE_SLOT
                from .structural_concordance import return_slot_structure

                # The output history names the merge destination, not the
                # values arriving on this edge. Read this exact authored site.
                scope = tail_arm.container.row[0]
                slots = sorted(
                    int(row[2]) for row in self._book().page(RETURN_SITE_SLOT).scope_rows(scope)
                    if row[1] == tail_arm.site
                )
                fallthrough_returned = []
                for slot in slots:
                    structure, _cell = return_slot_structure(
                        scope, tail_arm.site, slot, book=self._book(),
                    )
                    fallthrough_returned.extend(
                        self.external_value(leaf.value_id)
                        for _path, leaf in structure.leaves()
                    )
            authored_edge_width = max((
                *(len(values) for _block, values in edges),
                *((len(fallthrough_returned),) if fallthrough_open else ()),
            ), default=0)
            if authored_edge_width > 1:
                normalized_edges = []
                for block, values in edges:
                    if len(values) == 1 and values[0] is not None:
                        absence = values[0]
                        type_fact = self.native_value_type_abi.get(
                            int(absence.id)
                        )
                        alternatives = tuple(
                            type_fact.get("alternatives", ())
                            if isinstance(type_fact, Mapping)
                            else getattr(type_fact, "alternatives", ())
                        )
                        if int(absence.id) in self.none_value_ids or (
                            alternatives == ("builtins.NoneType",)
                        ) or (
                            record_kind is ReturnArmsKind.OPTIONAL_AGGREGATE
                            and edge_arms[id(block)].absent
                        ):
                            # A scalar ``None`` return is the payload-free arm
                            # of an aggregate union.  Every physical aggregate
                            # slot is absent on this edge; reusing the one
                            # exact None SSA value preserves that authored
                            # fact without inventing a component value.
                            values = (absence,) * authored_edge_width
                    normalized_edges.append((block, values))
                edges = normalized_edges
            if os.environ.get("TURING_DEBUG_CONTROL_OVERLAY"):
                for block, values in edges:
                    print(
                        f"DEBUG-RETURN-EDGE fn={self.function_name} "
                        f"block={block.name} "
                        f"values={[None if v is None else (int(v.id), str(v.dtype), sorted((v.accounting or {}).keys())) for v in values]!r}",
                        file=sys.stderr,
                    )
            slot_count = max(
                (
                    len(fallthrough_returned),
                    *(len(values) for _block, values in edges),
                )
                if fallthrough_open
                else tuple(len(values) for _block, values in edges)
            )
            if fallthrough_open:
                fallthrough_values = tuple(
                    fallthrough_returned[index]
                    if index < len(fallthrough_returned) else None
                    for index in range(slot_count)
                )
                edges.append((self.current, fallthrough_values))
                self.branch(self.function_exit_block())
                tail_arm = edge_arms.get(id(self.current))
                if tail_arm is not None:
                    self.current.instrs[-1].attributes[
                        "return_site_cell"
                    ] = tail_arm.site
            exit_block = self.function_exit_block()
            self.current = exit_block
            merged_values: list[SSAValue] = []
            slot_names = {
                int(logical_to_physical_return_slot[logical_slot]): str(name)
                for logical_slot, (name, _value_id) in enumerate(named_returns)
                if logical_slot in logical_to_physical_return_slot
            }
            variadic_recorded = False
            for slot in range(slot_count):
                incoming_blocks = []
                incoming_values = []
                incoming_absent = []
                for block, values in edges:
                    value = values[slot] if slot < len(values) else None
                    arm = edge_arms.get(id(block))
                    # Per-edge presence of slot ``slot`` is the record's:
                    # absent iff the arm is absent or shorter than the slot.
                    incoming_absent.append(
                        arm is not None
                        and (arm.absent or slot >= arm.length)
                    )
                    if value is None and record_kind is not None and (
                        record_kind is ReturnArmsKind.VARIADIC
                        or incoming_absent[-1]
                    ):
                        # The record covers this position: the arm declares
                        # it absent (OPTIONAL_AGGREGATE) or the output is a
                        # variable-length sequence (VARIADIC), whose real
                        # lowering is the sequence lane
                        # (SSASequenceDescriptor + ControlSequenceMutation
                        # clear/extend), not a Phi per position.  Keep the
                        # arity honest with an explicit absence; a VARIADIC
                        # record is one named shortfall, not a raise here.
                        value = self.fresh_value(
                            dtype="none", transform=CONTROL_CONST,
                        )
                        self.current = block
                        terminator = block.instrs.pop()
                        self.emit(Handler.NoneValue, [], value)
                        block.instrs.append(terminator)
                        self.current = exit_block
                        if (
                            record_kind is ReturnArmsKind.VARIADIC
                            and not variadic_recorded
                        ):
                            variadic_recorded = True
                            self.shortfalls.append(SSALoweringShortfall(
                                "control", "return_arms_variadic_unlowered",
                                f"{self.function_name}.return_arms",
                                "returns of differing arity form a "
                                "variable-length output; the sequence lane "
                                "(SSASequenceDescriptor + "
                                "ControlSequenceMutation clear/extend) is "
                                "the lowering and is not built",
                            ))
                    if value is None:
                        # An unresolved slot on this return: keep the Phi
                        # arity honest with an explicit absence and record
                        # the shortfall rather than silently dropping the edge.
                        value = self.fresh_value(
                            dtype="none", transform=CONTROL_CONST,
                        )
                        self.current = block
                        # Insert before the block's terminator.
                        terminator = block.instrs.pop()
                        self.emit(Handler.NoneValue, [], value)
                        block.instrs.append(terminator)
                        self.current = exit_block
                        self.shortfalls.append(SSALoweringShortfall(
                            "control", "return",
                            f"{self.function_name}.return_slot[{slot}]",
                            "a return statement's slot value could not be "
                            f"resolved on edge {block.name!r}",
                        ))
                    incoming_blocks.append(block.name)
                    incoming_values.append(value)
                if record_kind is None:
                    incoming_values = self._copy_divergent_sequence_returns(
                        slot, edges, incoming_values, incoming_blocks,
                        slot_names.get(slot),
                    )
                    self.current = exit_block
                dtype = next(
                    (str(value.dtype) for value in incoming_values
                     if value.dtype not in {None, "unknown", "none"}),
                    str(incoming_values[0].dtype or "unknown"),
                )
                # Program: ``def pick(n, c): if c == 2: return n; return n *
                # 0.5`` read as ``pick(n, c) + 0.25`` (corpus c772, c773).
                # Wrong record: the exit merge took its FIRST return's
                # dtype, so the float arm was stored into an int64 slot (3.5
                # became 3); with a ``None`` arm too, the mismatched
                # payloads left the optional unlowered and its presence was
                # lost.  Rule:
                # scalar returns of differing numeric class merge as a
                # branch join does (``_value_shape_dtype``'s ``phi`` rule):
                # the widest float when any arm is float, int64 when the
                # arms are ints and bools.  Any other disagreement is named.
                merge_dtypes = {
                    str(value.dtype) for value in incoming_values
                    if value.dtype not in {None, "unknown", "none", "None"}
                }
                if len(merge_dtypes) > 1:
                    promoted = self._numeric_join(incoming_values)
                    if promoted is not None:
                        dtype = promoted
                        incoming_values = list(self._numeric_join_arms(
                            dtype, tuple(
                                (block, value)
                                for (block, _values), value in zip(
                                    edges, incoming_values, strict=True,
                                )
                            ),
                        ))
                        self.current = exit_block
                    else:
                        self.shortfalls.append(SSALoweringShortfall(
                            "control", "return_arms_dtype_disagree",
                            f"{self.function_name}.return_slot[{slot}]",
                            "return statements disagree on the slot's "
                            f"physical class: {tuple(sorted(merge_dtypes))!r}",
                        ))
                member_phi = (
                    record_kind is ReturnArmsKind.OPTIONAL_AGGREGATE
                    and len(edges) > 1
                    and slot < len(arms_record[1].member_cells)
                )
                # Program: ``r = []; if n < 0: return r; r.append(2 * n);
                # return r`` (c62).  Wrong record: both return edges carry
                # sequence 1, yet the exit minted Phi(1, 1) as a NEW sequence
                # (94029) with its own, never-written length/capacity cells,
                # and the caller bound that phantom.  Rule: a merge whose
                # every incoming value is one identity is that identity.
                single_identity = (
                    len({int(value.id) for value in incoming_values}) == 1
                    and not member_phi
                )
                if len(edges) == 1 or single_identity:
                    merged = incoming_values[0]
                elif member_phi:
                    # The join is the record: this slot's merge IS the
                    # member Phi the reducer minted for position ``slot``
                    # (its graph id; its ``ssa_value`` row DERIVED from the
                    # member's canonical cell), as the conditional join
                    # adopts the graph's merge id.
                    merged = SSAValue(
                        int(arms_record[1].member_cells[slot].row[1]),
                        dtype=dtype,
                    )
                    self._value_cell(merged, *incoming_values)
                else:
                    merged = self.fresh_value(
                        dtype=dtype, transform=PHI_RETURN_MERGE,
                        operands=tuple(incoming_values),
                    )
                    merged = self._return_merge_sequence_destination(
                        merged, incoming_values,
                    )
                if len(edges) != 1 and not single_identity:
                    self.emit(
                        Handler.Phi,
                        incoming_values,
                        merged,
                        attributes={
                            "incoming_blocks": tuple(incoming_blocks),
                            "binding": "return_merge",
                            "return_slot_index": slot,
                            **(
                                {"return_arm_absent": tuple(incoming_absent)}
                                if member_phi else {}
                            ),
                            **(
                                {"output_name": slot_names[slot]}
                                if slot in slot_names else {}
                            ),
                        },
                    )
                merged_values.append(merged)
            returned = merged_values
            if record_kind is ReturnArmsKind.OPTIONAL_AGGREGATE:
                from .concordance_declarations import RETURN_OUTPUT_ARMS

                output_id = int(arms_record[0])
                return_arm_layouts[output_id] = tuple(int(value.id) for value in returned)
                aggregate_layout_sources[output_id] = (
                    self._book().current_ref(
                        RETURN_OUTPUT_ARMS, (tuple(self.lexical_read_scope), output_id),
                    ),
                )
            named_returns = [
                (
                    name,
                    int(merged_values[
                        logical_to_physical_return_slot[logical_slot]
                    ].id),
                )
                for logical_slot, (name, _value_id) in enumerate(named_returns)
                if (
                    logical_slot in logical_to_physical_return_slot
                    and logical_to_physical_return_slot[logical_slot]
                    < len(merged_values)
                )
            ]
            # Program shape: returns from several edges merged at the
            # function exit; the exit Phi (a minted, structured id) IS the
            # output now.  Wrong record: ``semantic_output`` still naming the
            # pre-merge value.  Rule: revise it where the Phi is minted.
            for name, merged_id in named_returns:
                if record_kind is ReturnArmsKind.OPTIONAL_AGGREGATE:
                    # Program: ``IdentityPage._fork_of_scope`` -- ``return
                    # forks.get(scope)`` is ``(origin, stamp)`` or ``None``.
                    # Wrong record: the one semantic output (the aggregate,
                    # 32, whose leaves 33/34 are the layout just recorded)
                    # was revised to leaf 33, the physical slot-0 value, so
                    # recovery published ``Ret [33, presence]`` and dropped
                    # leaf 34.  Rule: ``function_output`` rows stay physical
                    # (one per returned slot); the ``semantic_output`` row of
                    # an optional aggregate names the aggregate, DERIVED from
                    # its ``return_output_arms`` cell.
                    self._revise_semantic_output(
                        name, int(output_id),
                        *aggregate_layout_sources.get(int(output_id), ()),
                    )
                    continue
                self._revise_semantic_output(name, int(merged_id))
            self.emit(Handler.Ret, returned)
        elif fallthrough_open:
            self.emit(Handler.Ret, returned)

        # A returned union can be widened into a physical frame before the
        # function-exit join is built.  When that join has multiple incoming
        # edges, its payload and tag are new Phi values.  They are the values
        # exported by the function, so the semantic union descriptor must name
        # those physical members, not remain absent because only one incoming
        # call arm carried the semantic identity.  ``_shadow_dt_limit`` is the concrete
        # failure: semantic value 26 fed return Phi 2305843010213708123; the
        # next caller followed this return layout and correctly found no
        # descriptor for the Phi.  The layout below is the exact authored-to-
        # physical receipt, and the declared VALUE_TYPE_ABI cell remains its
        # source of truth.
        for declared_id, role_slots in native_value_union_return_layouts:
            type_fact = self.native_value_type_abi.get(int(declared_id))
            physical = tuple(
                type_fact.get("physical_alternatives", ())
                if isinstance(type_fact, Mapping)
                else getattr(type_fact, "physical_alternatives", ())
            )
            # Aggregate arms require their descriptor tables to be remapped
            # with the return frame.  This path publishes only the fixed-width
            # value unions whose complete frame is already named here.
            if not physical or any(
                str(arm.storage) in {"sequence", "record", "reference"}
                for arm in physical
                if str(arm.storage) != "none"
            ):
                continue
            frame = {
                tuple(role): returned[int(slot)]
                for role, slot in role_slots
                if int(slot) < len(returned)
            }
            tag = frame.get(("tag",))
            if tag is None:
                raise ValueError(
                    "native union return layout has no exact merged tag: "
                    f"{self.function_name} value {int(declared_id)}"
                )
            material_arms = tuple(
                arm for arm in physical if str(arm.storage) != "none"
            )
            shared_payload = bool(material_arms) and len({
                (
                    str(arm.storage), str(arm.dtype),
                    tuple(arm.shape or ()), int(arm.rank),
                    tuple(arm.storage_identity or ()),
                )
                for arm in material_arms
            }) == 1
            payloads = {
                str(arm.identity): tuple(
                    value for role, value in sorted(
                        frame.items(),
                        key=lambda item: int(item[0][-1])
                        if item[0] and isinstance(item[0][-1], int)
                        else -1,
                    )
                    if len(role) == 3 and (
                        role[:2] == (
                            "alternative", str(arm.identity),
                        )
                        or (
                            shared_payload
                            and str(arm.storage) != "none"
                            and role[:2] == ("shared", "value")
                        )
                    )
                )
                for arm in physical
            }
            if shared_payload:
                shared_candidates = tuple(
                    payloads[str(arm.identity)]
                    for arm in material_arms
                    if payloads[str(arm.identity)]
                )
                shared_values = (
                    shared_candidates[0] if shared_candidates else ()
                )
                if any(
                    tuple(int(value.id) for value in candidate)
                    != tuple(int(value.id) for value in shared_values)
                    for candidate in shared_candidates[1:]
                ):
                    raise ValueError(
                        "shared native union return arms disagree about "
                        f"their physical payload: {self.function_name} "
                        f"value {int(declared_id)}"
                    )
                payloads.update({
                    str(arm.identity): shared_values
                    for arm in material_arms
                })
            # The descriptor key is the authored union identity.  Its member
            # ids are the physical return Phis.  Keeping those two roles
            # distinct lets the next call edge ask for the declared result
            # directly while still receiving the exact exported frame.
            union_id = int(declared_id)
            if self.value_union_table.by_id(union_id) is not None:
                continue
            self.native_value_union_payloads[union_id] = payloads
            self.native_value_type_tags[union_id] = tag
            self.post_native_type_tag(
                union_id, tag, type_fact, *frame.values(),
            )
            self.publish_native_value_union(union_id, tag, type_fact)
        optional_glyph_return_layouts = [
            (
                int(semantic_payload_id),
                (
                    int(returned[payload_slot].id),
                    int(returned[presence_slot].id),
                ),
            )
            for semantic_payload_id, payload_slot, presence_slot
            in optional_glyph_return_slots
        ]
        aggregate_return_layouts = {
            **return_arm_layouts, **dict(optional_glyph_return_layouts),
        }
        for semantic_payload_id, payload_slot, presence_slot in optional_glyph_return_slots:
            aggregate_layout_sources[int(semantic_payload_id)] = self._cells(
                returned[payload_slot], returned[presence_slot],
            )
        for semantic_payload_id, payload_slot, tag_slot in (
            native_type_return_slots
        ):
            physical = tuple(dict.fromkeys((
                *aggregate_return_layouts.get(
                    int(semantic_payload_id), ()
                ),
                int(returned[payload_slot].id),
                int(returned[tag_slot].id),
            )))
            aggregate_return_layouts[int(semantic_payload_id)] = physical
            aggregate_layout_sources[int(semantic_payload_id)] = (
                *aggregate_layout_sources.get(int(semantic_payload_id), ()),
                self._book().current_ref(
                    VALUE_TYPE_ABI, (self.lexical_read_scope, int(semantic_payload_id)),
                ),
            )
        for output_id, role_slots in native_value_union_return_layouts:
            aggregate_return_layouts[int(output_id)] = tuple(
                int(returned[int(slot)].id) for _role, slot in role_slots
            )
            aggregate_layout_sources[int(output_id)] = (
                self._book().current_ref(
                    VALUE_TYPE_ABI, (self.lexical_read_scope, int(output_id)),
                ),
            )
        page_metadata = self._finish_pages(
            tuple(named_returns), tuple(parameter_value_names), tuple(returned),
        )
        sequence_table = SSASequenceTable(owner=self.function_name)

        def register_sequence(table, descriptor):
            # A descriptor stands on the cells of the values it names.
            source_cells = self._cells(
                self._sequence_contract_cell(int(descriptor.sequence_id)),
                *(
                    self.ssa_value_objects.get(int(value_id))
                    for value_id in (
                        descriptor.sequence_id,
                        *descriptor.column_value_ids,
                        descriptor.length_address_id,
                        descriptor.capacity_value_id,
                        descriptor.status_address_id,
                        descriptor.live_flags_value_id,
                        descriptor.heap_owner_value_id,
                    )
                    if value_id is not None
                ),
            )
            return table.register(
                descriptor,
                sources=source_cells or (self._function_root(),),
                stage=self._stage(),
            )

        for descriptor in self.sequence_descriptors.values():
            register_sequence(sequence_table, descriptor)
        function = Function(
                self.function_name,
                self.arguments,
                self.blocks,
                metadata={
                    # The control scope this lowering's ``ssa_value`` rows
                    # are keyed by (``function_scope_of`` reads it): a
                    # later pass that posts about these values posts under
                    # the scope that holds them.
                    "tensor_shape_concordance_scope": self._scope(),
                    "recursion_table": dict(self.ssa_recursion_table),
                    "named_outputs": page_metadata["named_outputs"],
                    # port id -> the carried phi VALUE standing at that
                    # port after the loops.  The record-return expansion
                    # resolves layout components by id, and a component
                    # whose id doubles as a written field slot must resolve
                    # to the phi, not the unwritten slot argument.
                    "carried_port_values": page_metadata["carried_port_values"],
                    # (loop node, value id): a preheader value some non-carried
                    # binding reads inside that loop (``_resolve_read``).
                    "loop_retained_outer_reads": tuple(sorted(
                        self.__dict__.get("_retained_outer_reads", ())
                    )),
                    "value_aliases": page_metadata["value_aliases"],
                    "value_names": tuple(value_names),
                    "parameter_names": page_metadata["parameter_names"],
                    "validation_contracts": tuple(self.validation_contracts),
                    "native_object_collections": tuple(self.native_object_collections.values()),
                    "native_value_type_abi": dict(self.native_value_type_abi),
                    "native_value_type_tags": tuple(
                        (int(value_id), int(tag.id))
                        for value_id, tag in sorted(
                            self.native_value_type_tags.items()
                        )
                        if int(value_id) in self.native_value_type_abi
                    ),
                    "native_value_type_tests": tuple(
                        self.native_value_type_tests.values()
                    ),
                    "native_type_return_layouts": tuple(
                        native_type_return_slots
                    ),
                    "native_value_union_return_layouts": tuple(
                        native_value_union_return_layouts
                    ),
                    "control_identity_receipts": tuple(dict.fromkeys(
                        self.control_identity_receipts
                    )),
                    "table_lookup_ownership_receipts": tuple(dict.fromkeys(
                        self.table_lookup_ownership_receipts
                    )),
                    "control_ir": True,
                    "source_execution_receipts": tuple(
                        (int(value_id), dict(receipt))
                        for value_id, receipt in sorted(
                            self.source_execution_receipts.items()
                        )
                    ),
                    "deployment_regions": tuple(deployment_regions),
                    "sequence_table": sequence_table,
                    "value_union_table": self.value_union_table,
                    "aggregate_return_layouts": tuple(
                        aggregate_return_layouts.items()
                    ),
                    "sequence_static_capacity_bounds": tuple(sorted(
                        self.static_sequence_capacities.items()
                    )),
                    "sequence_helper_functions": tuple(
                        self.sequence_helper_functions.values()
                    ),
                    "sequence_array_argument_ids": tuple(dict.fromkeys(
                        [
                            int(value.id)
                            for value in self.projected_row_columns.values()
                        ] + [
                            int(value.id)
                            for value in self.variant_row_values.values()
                        ] + [
                            int(value.id)
                            for value in self.variant_type_tag_columns.values()
                        ] + [
                            int(value.id)
                            for value in self.variant_type_payload_columns.values()
                        ] + [
                        int(value_id)
                        for descriptor in self.sequence_descriptors.values()
                        for value_id in (
                            *descriptor.column_value_ids,
                            descriptor.length_address_id,
                            *(
                                (descriptor.status_address_id,)
                                if descriptor.status_address_id is not None else ()
                            ),
                            *(
                                (descriptor.live_flags_value_id,)
                                if descriptor.live_flags_value_id is not None else ()
                            ),
                            *(
                                (
                                    *descriptor.child_table_pool.column_value_ids,
                                    descriptor.child_table_pool.length_value_id,
                                    *((descriptor.child_table_pool.status_value_id,)
                                      if descriptor.child_table_pool.status_value_id is not None else ()),
                                    *((descriptor.child_table_pool.live_flags_value_id,)
                                      if descriptor.child_table_pool.live_flags_value_id is not None else ()),
                                )
                                if descriptor.child_table_pool is not None else ()
                            ),
                        )]
                    )),
                    "scalar_variant_argument_ids": tuple(sorted(
                        self.variant_projected_target_ids
                    )),
                    "projected_row_tables": tuple(
                        (
                            int(source_id), int(projection), int(value.id),
                            str(value.dtype or "unknown"),
                        )
                        for (source_id, projection), value
                        in self.projected_row_columns.items()
                    ),
                    "nested_child_tables": tuple(
                        (
                            str(source_kind), int(source_id), int(projection),
                            int(data.id), int(lengths.id),
                            int(sequence_stride.id), int(row_stride.id),
                        )
                        for (source_kind, source_id, projection), (
                            data, lengths, sequence_stride, row_stride
                        )
                        in self.nested_child_rows.items()
                    ),
                    "joined_sequence_views": tuple(
                        (int(outer_id), int(flat_id))
                        for outer_id, flat_id
                        in sorted(self.joined_flat_sequence_ids.items())
                    ),
                    # Exact authored identities for the resident sequence
                    # arenas.  Several names may intentionally alias one
                    # sequence id; retain every occurrence in source-table
                    # order instead of choosing a convenient spelling.
                    "sequence_value_names": tuple(
                        (
                            int(sequence_id),
                            tuple(
                                name
                                for name, history in self.value_name_histories.items()
                                if int(sequence_id) in history
                            ),
                        )
                        for sequence_id in self.sequence_descriptors
                    ),
                },
        )
        from .structural_concordance import publish_aggregate_return_layout
        from .concordance_declarations import OPTIONAL_VALUE_STRUCTURE

        for _semantic_id, payload_slot, presence_slot in optional_glyph_return_slots:
            payload, presence = returned[payload_slot], returned[presence_slot]
            optional_cell = self._book().post(
                OPTIONAL_VALUE_STRUCTURE, (self._scope(), int(payload.id)),
                (int(payload.id), int(presence.id)), stage=CONTROL_SSA_FINISH,
                provenance=Derived(self._cells(payload, presence)), mode=Mode.CONCORD,
            )
            aggregate_layout_sources[int(_semantic_id)] = (
                *aggregate_layout_sources[int(_semantic_id)], optional_cell,
            )
        for output_id, members in aggregate_return_layouts.items():
            publish_aggregate_return_layout(
                function, output_id, members,
                sources=aggregate_layout_sources[output_id],
                stage=CONTROL_SSA_FINISH, book=self._book(),
            )
        loop_result_rebindings = (
            _canonicalize_non_dominating_loop_result_uses(
                function,
                book_scope=str(self.tensor_shape_concordance_scope),
            )
        )
        if loop_result_rebindings:
            function.metadata["loop_result_use_rebindings"] = (
                loop_result_rebindings
            )
        if self.evolution is not None and self.ssa_evolution is not None:
            self.evolution.bind_artifact(function, self.ssa_evolution)
            self.evolution.close_graph(self.ssa_evolution)
        if self.native_object_context_used:
            context = self.native_object_context
            function.metadata['native_object_context'] = context.to_mapping()
            function.metadata['source_object_constructors'] = tuple(self.native_object_constructor_receipts)
            function.metadata['native_object_type_tests'] = tuple(self.native_object_type_test_receipts)
            function.metadata['native_object_requires_member_storage'] = self.native_object_requires_member_storage
            register_sequence(function.metadata['sequence_table'], context.objects)
            register_sequence(function.metadata['sequence_table'], context.members)
            from .ssa_object_context import context_values
            function.metadata['sequence_array_argument_ids'] = tuple(dict.fromkeys((
                *function.metadata['sequence_array_argument_ids'],
                *(cell.id for cell in context_values(context) if cell.shape),
            )))
        from .structural_concordance import register_sequence_row_projections
        register_sequence_row_projections(function, sequence_table, book=self._book())
        return function, tuple(self.shortfalls)


def _post_loop_result_reconciliation(
    book: Any, row: tuple, fact: tuple, sources: tuple,
) -> None:
    """Record one complete per-value analysis, with its actual input cells."""
    if not sources:
        raise ConcordanceRefusal(f"loop-result reconciliation {row!r} has no recorded inputs")
    existing = book.latest_ref(LOOP_RESULT_RECONCILIATION, row)
    if (existing is not None and book.page(LOOP_RESULT_RECONCILIATION).latest(row) == fact
            and book.edges_into(existing)):
        return  # An already justified, unchanged analysis is not a revision.
    book.post(LOOP_RESULT_RECONCILIATION, row, fact,
              stage=CONTROL_SSA_FINISH, provenance=Derived(sources), mode=Mode.REVISE)


def _post_ssa_block_geometry(book, scope, function):
    """Publish the ordered SSA geometry consumed by dominance analysis.

    A new instruction's recorded values provide the cause for shifted use and
    definition positions. Same-value reorderings without a producer receipt
    are refused, rather than given a diagnostic-only root or guessed edge.
    """
    from .concordance_declarations import (
        CALL_BINDING_INPUT, LOOP_RESULT_USE_REBINDING, SSA_BLOCK_GEOMETRY,
        SSA_CONSTANT_HOIST, SSA_CONSTANT_MATERIALIZATION,
        TENSOR_METADATA_CALL_BINDING,
    )
    result = {}
    moved = {}
    for row in book.page(SSA_CONSTANT_HOIST).scope_rows((scope, str(function.name))):
        cell = book.latest_ref(SSA_CONSTANT_HOIST, row)
        moved.setdefault(row[2], []).append(cell)
        moved.setdefault(row[4], []).append(cell)
    rebound = {}
    for row in book.page(LOOP_RESULT_USE_REBINDING).scope_rows(scope):
        if len(row) < 2:
            continue
        cell = book.latest_ref(LOOP_RESULT_USE_REBINDING, row)
        if cell is not None:
            rebound.setdefault(str(row[1]), []).append(cell)
    materialized = {}
    for row in book.page(SSA_CONSTANT_MATERIALIZATION).scope_rows(scope):
        if len(row) < 4 or str(row[1]) != str(function.name):
            continue
        cell = book.latest_ref(SSA_CONSTANT_MATERIALIZATION, row)
        if cell is not None:
            materialized.setdefault(str(row[2]), []).append(cell)
    metadata_bindings = {}
    for row in book.page(TENSOR_METADATA_CALL_BINDING).scope_rows(scope):
        if len(row) < 5 or str(row[1]) != str(function.name):
            continue
        cell = book.latest_ref(TENSOR_METADATA_CALL_BINDING, row)
        if cell is not None:
            metadata_bindings.setdefault(str(row[2]), []).append(cell)
    call_bindings = {}
    for binding_row in book.page(CALL_BINDING_INPUT).scope_rows(
        str(function.name)
    ):
        if len(binding_row) < 2:
            continue
        cell = book.latest_ref(CALL_BINDING_INPUT, binding_row)
        if cell is not None:
            call_bindings.setdefault(int(binding_row[1]), []).append(cell)
    function_outputs = tuple(
        book.latest_ref(FUNCTION_OUTPUT, row)
        for row in book.page(FUNCTION_OUTPUT).scope_rows(scope)
        if book.latest_ref(FUNCTION_OUTPUT, row) is not None
    )
    for label, block in function.blocks.items():
        block_call_bindings = tuple(
            cell
            for instruction in block.instrs
            if instruction.op in {"Call", "call"}
            for callsite in (
                instruction.attributes.get("plan_callsite_id"),
            )
            if callsite is not None
            for cell in call_bindings.get(int(callsite), ())
        ) + tuple(
            # A region call's arity is its region's signature.
            cell
            for instruction in block.instrs
            if instruction.op in {"Call", "call"}
            and instruction.attributes.get("region_index") is not None
            for cell in (book.latest_ref(
                REGION_SIGNATURE,
                (scope, int(instruction.attributes["region_index"])),
            ),)
            if cell is not None
        )
        sources = tuple(dict.fromkeys(cell for cell in (
            book.latest_ref(SSA_BLOCK, (scope, str(function.name), str(label))),
            *moved.get(label, ()),
            *rebound.get(str(label), ()),
            *materialized.get(str(label), ()),
            *metadata_bindings.get(str(label), ()),
            *block_call_bindings,
            *(function_outputs if any(
                instruction.op in {"Ret", "ret", "Return", "return"}
                for instruction in block.instrs
            ) else ()),
            *(book.latest_ref(SSA_VALUE, (scope, int(value.id)))
              for instruction in block.instrs
              for value in (*instruction.args, *((instruction.res,) if instruction.res is not None else ()))),
        ) if cell is not None))
        if not sources:
            if not block.instrs:
                continue
            raise ConcordanceRefusal(f"SSA block geometry {function.name}.{label} has no recorded owner or values")
        fact = (tuple((str(instruction.op), tuple(int(value.id) for value in instruction.args),
                       None if instruction.res is None else int(instruction.res.id),
                       tuple(instruction.attributes.get('incoming_blocks') or ()))
                      for instruction in block.instrs), tuple(block.successors))
        row = (scope, str(function.name), str(label))
        prior = book.latest_ref(SSA_BLOCK_GEOMETRY, row)
        if prior is not None and book.page(SSA_BLOCK_GEOMETRY).latest(row) == fact:
            result[label] = prior
        else:
            previous = (
                None if prior is None
                else book.page(SSA_BLOCK_GEOMETRY).latest(row)
            )
            try:
                result[label] = book.post(
                    SSA_BLOCK_GEOMETRY, row, fact,
                    stage=CONTROL_SSA_FINISH,
                    provenance=Derived(sources), mode=Mode.REVISE,
                )
            except ConcordanceRefusal as error:
                raise ConcordanceRefusal(
                    f"{error}; previous_geometry={previous!r}; "
                    f"proposed_geometry={fact!r}"
                ) from error
    return result


def _canonicalize_non_dominating_loop_result_uses(
    function: Function,
    book_scope: str | None = None,
) -> tuple[tuple[str, int, int, int, int], ...]:
    """Resolve stale nested LoopResult operands only when CFG proves it.

    Control construction can retain the inner spelling of a carried result in
    an expression that is finally placed after an enclosing loop.  The inner
    Phi does not dominate the enclosing loop's zero-trip exit; the enclosing
    result Phi does.  ``carried_port_values`` records the exact lexical result
    equivalence.  This pass changes an operand only when the old object fails
    dominance and the recorded replacement object satisfies it, so it is not
    a blanket value-id/SSA-version substitution.
    """

    from .ssa_record_return_state import accepted_ssa_component
    if accepted_ssa_component(function):
        return ()
    if function.metadata.get("llvm_repository_kernel"):
        # The tensor reference is already-complete repository SSA imported
        # from its authored LLVM module.  It has no cells in the active
        # source compilation's concordance and this source-control repair has
        # no authority to rewrite it.  Call-edge settlement belongs to the
        # enclosing unit; the reference body remains exactly its input.
        return ()
    port_values = dict(
        function.metadata.get("carried_port_values") or {}
    )
    # An empty ledger is not evidence of nothing to do.  A single-incoming
    # exit Phi states its own equivalence, and the dominance checks below
    # still decide every substitution, so the pass runs on CFG evidence
    # whether or not a recorded ledger accompanies it.
    if not function.blocks:
        return ()

    block_names = tuple(function.blocks)
    entry = block_names[0]
    predecessors = {name: set() for name in block_names}
    for name, block in function.blocks.items():
        for successor in block.successors:
            if successor in predecessors:
                predecessors[successor].add(name)

    reachable = {entry}
    pending = [entry]
    while pending:
        name = pending.pop()
        for successor in function.blocks[name].successors:
            if successor in function.blocks and successor not in reachable:
                reachable.add(successor)
                pending.append(successor)

    dominators = {
        name: ({name} if name == entry else set(reachable))
        for name in reachable
    }
    changed = True
    while changed:
        changed = False
        for name in block_names:
            if name == entry or name not in reachable:
                continue
            incoming = predecessors[name] & reachable
            parent_dominators = (
                set.intersection(*(dominators[parent] for parent in incoming))
                if incoming else set()
            )
            updated = {name} | parent_dominators
            if updated != dominators[name]:
                dominators[name] = updated
                changed = True

    argument_ids = {int(value.id) for value in function.args}
    definition_sites: dict[int, list[tuple[str, int]]] = {}
    for block_name, block in function.blocks.items():
        for instruction_index, instruction in enumerate(block.instrs):
            if instruction.res is not None:
                definition_sites.setdefault(
                    int(instruction.res.id), []
                ).append((block_name, instruction_index))

    def dominates(
        value: SSAValue,
        use_block: str,
        use_index: int,
        incoming_block: str | None,
    ) -> bool:
        value_id = int(value.id)
        if value_id in argument_ids:
            return True
        sites = definition_sites.get(value_id, ())
        # Multiple producers for one numeric identity are not valid SSA and
        # cannot be made safe by guessing which Python SSAValue object a use
        # meant.  Leave such a case untouched for structural validation.
        if len(sites) != 1:
            return False
        definition_block, definition_index = sites[0]
        target_block = incoming_block or use_block
        if target_block not in reachable:
            return False
        if definition_block != target_block:
            return definition_block in dominators[target_block]
        target_index = (
            len(function.blocks[target_block].instrs)
            if incoming_block is not None else use_index
        )
        return definition_index < target_index

    from .identity_concordance import current_identity_book
    book = current_identity_book()
    scope = str(book_scope or function.metadata.get("tensor_shape_concordance_scope") or function.name)
    geometry = _post_ssa_block_geometry(book, scope, function)
    observations = {}
    observation_sources = {}
    receipts = []
    for block_name, block in function.blocks.items():
        for instruction_index, instruction in enumerate(block.instrs):
            incoming_blocks = (
                tuple(instruction.attributes.get("incoming_blocks") or ())
                if str(instruction.op).casefold() == "phi" else ()
            )
            resolved_args = list(instruction.args)
            import os as _rc_os
            if _rc_os.environ.get("TURING_TRACE_RECONCILE") and str(
                block_name
            ) == "loop_body" and "lu_decompose" in str(function.name):
                print("RC", str(function.name)[-14:], block_name,
                      instruction_index, instruction.op,
                      [int(getattr(a, "id", -1)) for a in instruction.args][:8],
                      flush=True)
            for argument_index, argument in enumerate(instruction.args):
                def _note(
                    outcome: str, detail: Any = None,
                    candidate: Any = None,
                ) -> None:
                    """Record this argument's reconciliation decision."""

                    row = ((scope, str(function.name)), int(argument.id))
                    sources = tuple(dict.fromkeys(cell for cell in (
                        book.latest_ref(CARRIED_PORT_VALUE, (scope, int(argument.id))),
                        book.latest_ref(CONTROL_VALUE_BINDING, (scope, int(argument.id))),
                        book.latest_ref(SSA_VALUE, (scope, int(argument.id))),
                        geometry.get(block_name),
                        *(geometry.get(label) for label, _index in definition_sites.get(int(argument.id), ())),
                        *((book.latest_ref(SSA_VALUE, (scope, int(instruction.res.id))),)
                          if instruction.res is not None else ()),
                        *((book.latest_ref(SSA_VALUE, (scope, int(candidate.id))),)
                          if candidate is not None else ()),
                    ) if cell is not None))
                    observations.setdefault(row, []).append((outcome,
                        f"{block_name}#{instruction_index}", str(instruction.op), detail))
                    observation_sources.setdefault(row, {}).update(dict.fromkeys(sources))

                replacement = port_values.get(int(argument.id))
                if replacement is argument:
                    # A ledger entry mapping a port to ITSELF is not an
                    # equivalence, and taking it as one made this pass decline
                    # silently: the single case it exists to repair -- a loop
                    # body reading its own result port -- is exactly the case
                    # the ledger records that way.  Treat it as no recorded
                    # equivalence and let the CFG supply the candidate.
                    replacement = None
                if replacement is None:
                    # A result port with no recorded equivalence still states
                    # one itself: an exit Phi with a SINGLE incoming says the
                    # port IS that incoming value.  A use the exit cannot
                    # dominate -- the loop body reading its own result -- may
                    # therefore read the incoming instead.  The dominance
                    # checks below still decide; this only supplies the
                    # candidate the recorded ledger was missing.
                    sites = definition_sites.get(int(argument.id), ())
                    if len(sites) == 1:
                        site_block, site_index = sites[0]
                        defining = function.blocks[site_block].instrs[
                            site_index
                        ]
                        if (
                            str(defining.op).casefold() == "phi"
                            and len(defining.args) == 1
                        ):
                            replacement = defining.args[0]
                        elif (
                            str(defining.op).casefold() == "phi"
                            and defining.args
                            and all(
                                int(other.id) == int(defining.args[0].id)
                                for other in defining.args
                            )
                            and int(defining.args[0].id) != int(argument.id)
                        ):
                            # A Phi whose every incoming is ONE value states
                            # the same equivalence as a single incoming: the
                            # port IS that value on every path (the
                            # return-merge field Phi of a span the function
                            # forwards unwritten from every return site --
                            # N=2 orbital dt system, ``pub_limits`` of
                            # ``step_with_dt_control_used``: Phi(f, f, f),
                            # read by a call in the retry loop, where the
                            # Phi's block does not dominate).  The CFG check
                            # below still decides.
                            replacement = defining.args[0]
                if replacement is None:
                    _note("no-candidate", tuple(
                        definition_sites.get(int(argument.id), ())
                    )[:3])
                    continue
                if replacement is argument:
                    continue
                incoming_block = (
                    str(incoming_blocks[argument_index])
                    if argument_index < len(incoming_blocks) else None
                )
                if dominates(
                    argument, block_name, instruction_index, incoming_block
                ):
                    _note("argument-dominates", (
                        int(argument.id) in argument_ids,
                        tuple(definition_sites.get(int(argument.id), ()))[:2],
                    ))
                    continue
                _note("argument-not-dominating", tuple(
                    definition_sites.get(int(argument.id), ())
                )[:3])
                if not dominates(
                    replacement, block_name, instruction_index, incoming_block
                ):
                    _note("candidate-not-dominating", (
                        int(replacement.id),
                        tuple(definition_sites.get(int(replacement.id), ()))[:3],
                    ), replacement)
                    continue
                _note("replaced", int(replacement.id), replacement)
                # The substitution itself is a fact on the book, one row per
                # occurrence: DERIVED(the original's and the replacement's
                # ``ssa_value`` cells, the blocks the dominance proof names)
                # with the proof's evidence in the fact.  Not swallowed: a
                # substitution the book did not take is not a valid one.
                from .ssa_record_return_state import post_dominance_rebinding

                use_target = (
                    str(incoming_block) if incoming_block is not None
                    else str(block_name)
                )
                replacement_sites = tuple(
                    definition_sites.get(int(replacement.id), ())
                )
                post_dominance_rebinding(
                    function, LOOP_RESULT_USE_REBINDING, (
                        str(function.metadata.get(
                            "tensor_shape_concordance_scope"
                        ) or function.name),
                        str(block_name), int(instruction_index),
                        int(argument_index),
                    ), (
                        int(argument.id), int(replacement.id),
                        (
                            ("formal",) if int(replacement.id) in argument_ids
                            else replacement_sites
                        ),
                        tuple(definition_sites.get(int(argument.id), ())),
                        use_target,
                        "phi_edge" if incoming_block is not None
                        else int(instruction_index),
                    ),
                    original=argument, replacement=replacement,
                    blocks=(
                        use_target,
                        *(site[0] for site in replacement_sites[:1]),
                    ),
                    stage=CONTROL_SSA_FINISH, mode=Mode.REVISE,
                )
                resolved_args[argument_index] = replacement
                receipts.append((
                    str(block_name), int(instruction_index),
                    int(argument_index), int(argument.id),
                    int(replacement.id),
                ))
            instruction.args = resolved_args
    for row, facts in observations.items():
        _post_loop_result_reconciliation(book, row, tuple(facts), tuple(observation_sources[row]))
    return tuple(receipts)


def lower_control_program_to_ssa(
    program: ControlProgram,
    *,
    function_name: str = "planned_control",
    first_value_id: int = 0,
    region_callees: dict[int, str] | None = None,
    region_signatures: dict[
        int, tuple[tuple[int, ...], tuple[int, ...]]
    ] | None = None,
    region_writing_indices: frozenset[int] = frozenset(),
    region_feed_meta: Mapping[int, tuple[Meta, ...]] | None = None,
    region_value_meta: Mapping[int, Meta] | None = None,
    region_value_ranks: Mapping[int, int] | None = None,
    tensor_shape_concordance_scope: str | None = None,
    lexical_read_scope: Any = None,
    planning_scope: Any = None,
    source_value_descriptions: Mapping[int, Mapping[str, Any]] | None = None,
    shape_scope: Any = None,
    plan_callsite_bindings: Mapping[
        int, tuple[tuple[int, ...], tuple[int, ...]]
    ] | None = None,
    value_aliases: Mapping[int, int] | None = None,
    inout_value_ids: tuple[int, ...] = (),
    constant_value_ids: tuple[int, ...] = (),
    none_value_ids: tuple[int, ...] = (),
    output_value_ids: tuple[int, ...] = (),
    named_output_histories: Mapping[str, tuple[int, ...]] | None = None,
    value_name_histories: Mapping[str, tuple[int, ...]] | None = None,
    parameter_names: tuple[str, ...] = (),
    sequence_initializations: tuple[tuple[int, str, int], ...] = (),
    sequence_declarations: tuple[tuple[int, str, int, bool], ...] = (),
    sequence_column_dtypes: Mapping[int, tuple[str, ...]] | None = None,
    sequence_record_identities: Mapping[int, str] | None = None,
    sequence_child_table_layouts: Mapping[
        int, tuple[int, tuple[str, ...], tuple[int, ...], bool]
    ] | None = None,
    sequence_row_record_slots: Mapping[
        int, tuple[tuple[int, str, int], ...]
    ] | None = None,
    source_sequence_ids: tuple[int, ...] = (),
    dynamic_sequence_ids: tuple[int, ...] = (),
    sequence_memberships: tuple[
        tuple[int, int | tuple[int, ...], int, bool], ...
    ] = (),
    table_lookups: tuple[tuple[int, int | tuple[int, ...], int], ...] = (),
    lexical_table_lookup_result_ids: tuple[int, ...] = (),
    table_lookup_defaults: dict[int, int | float] | None = None,
    table_lookup_required_ids: frozenset[int] = frozenset(),
    table_stores: tuple[
        tuple[int, int | tuple[int, ...], int, int], ...
    ] = (),
    table_deletions: tuple[
        tuple[int, int | tuple[int, ...], int | None, str], ...
    ] = (),
    retained_sequence_ids: tuple[int, ...] = (),
    nested_sequence_ids: tuple[int, ...] = (),
    nested_tensor_sequence_ids: tuple[int, ...] = (),
    joined_sequence_ids: tuple[int, ...] = (),
    joined_singleton_values: Mapping[int, int] | None = None,
    nested_row_target_ids: tuple[int, ...] = (),
    selected_nested_sequence_ids: tuple[int, ...] = (),
    variant_projected_target_ids: tuple[int, ...] = (),
    region_array_feed_ids: Mapping[int, tuple[int, ...]] | None = None,
    nested_row_projections: tuple[tuple[int, int, int, str], ...] = (),
    sequence_length_values: Mapping[int, int] | None = None,
    table_region_operations: Mapping[int, tuple[tuple[str, tuple[Any, ...]], ...]] | None = None,
    table_region_post_operations: Mapping[int, tuple[tuple[str, tuple[Any, ...]], ...]] | None = None,
    table_epilogue_operations: tuple[tuple[str, tuple[Any, ...]], ...] = (),
    host_reads_table_status: bool = False,
    consumer_row_loads: Mapping[int, tuple[Any, ...]] | None = None,
    effect_preceding_row_reads: Mapping[int, tuple[int, ...]] | None = None,
    resolved_sequence_schemas: Mapping[int, ResolvedSequenceSchema] | None = None,
    native_object_context: Any = None,
    native_object_module: Any = None,
    native_object_value_ids: Iterable[int] = (),
    native_object_collections: Mapping[int, Mapping[str, Any]] | None = None,
    native_object_type_tests: Mapping[int, Mapping[str, Any]] | None = None,
    native_value_type_abi: Mapping[int, Any] | None = None,
    native_value_type_tests: Mapping[int, Mapping[str, Any]] | None = None,
) -> tuple[Function, tuple[SSALoweringShortfall, ...]]:
    builder = _ControlSSABuilder(
        program,
        function_name=function_name,
        first_value_id=first_value_id,
        region_callees=region_callees,
        region_signatures=region_signatures,
        region_writing_indices=region_writing_indices,
        region_feed_meta=region_feed_meta,
        region_value_meta=region_value_meta,
        region_value_ranks=region_value_ranks,
        tensor_shape_concordance_scope=tensor_shape_concordance_scope,
        lexical_read_scope=lexical_read_scope,
        planning_scope=planning_scope,
        source_value_descriptions=source_value_descriptions,
        shape_scope=shape_scope,
        plan_callsite_bindings=plan_callsite_bindings,
        value_aliases=value_aliases,
        inout_value_ids=inout_value_ids,
        constant_value_ids=constant_value_ids,
        none_value_ids=none_value_ids,
        output_value_ids=output_value_ids,
        named_output_histories=named_output_histories,
        value_name_histories=value_name_histories,
        parameter_names=parameter_names,
        sequence_initializations=sequence_initializations,
        sequence_declarations=sequence_declarations,
        sequence_column_dtypes=sequence_column_dtypes,
        sequence_record_identities=sequence_record_identities,
        sequence_child_table_layouts=sequence_child_table_layouts,
        sequence_row_record_slots=sequence_row_record_slots,
        source_sequence_ids=source_sequence_ids,
        dynamic_sequence_ids=dynamic_sequence_ids,
        sequence_memberships=sequence_memberships,
        table_lookups=table_lookups,
        lexical_table_lookup_result_ids=lexical_table_lookup_result_ids,
        table_lookup_defaults=table_lookup_defaults,
        table_lookup_required_ids=table_lookup_required_ids,
        table_stores=table_stores,
        table_deletions=table_deletions,
        retained_sequence_ids=retained_sequence_ids,
        nested_sequence_ids=nested_sequence_ids,
        nested_tensor_sequence_ids=nested_tensor_sequence_ids,
        joined_sequence_ids=joined_sequence_ids,
        joined_singleton_values=joined_singleton_values,
        nested_row_target_ids=nested_row_target_ids,
        selected_nested_sequence_ids=selected_nested_sequence_ids,
        variant_projected_target_ids=variant_projected_target_ids,
        region_array_feed_ids=region_array_feed_ids,
        nested_row_projections=nested_row_projections,
        sequence_length_values=sequence_length_values,
        table_region_operations=table_region_operations,
        table_region_post_operations=table_region_post_operations,
        table_epilogue_operations=table_epilogue_operations,
        host_reads_table_status=host_reads_table_status,
        consumer_row_loads=consumer_row_loads,
        effect_preceding_row_reads=effect_preceding_row_reads,
        resolved_sequence_schemas=resolved_sequence_schemas,
        native_object_context=native_object_context,
        native_object_module=native_object_module,
        native_object_value_ids=native_object_value_ids,
        native_object_collections=native_object_collections,
        native_object_type_tests=native_object_type_tests,
        native_value_type_abi=native_value_type_abi,
        native_value_type_tests=native_value_type_tests,
    )
    builder.lower(program.root)
    for kind, arguments in builder.table_epilogue_operations:
        if kind == "delete":
            builder._emit_table_delete(*arguments)
        elif kind == "store":
            builder._emit_table_store(*arguments)
        elif kind == "pack_bits":
            builder._emit_sequence_pack_bits(*arguments)
        else:
            raise ValueError(f"unknown table epilogue operation {kind!r}")
    function, shortfalls = builder.finish()
    from .ir_sequence_tables import schedule_joined_sequence_mutations

    schedule_joined_sequence_mutations(function)
    # Program: ``append_decimal_integer_glyphs`` (seven literal appends).
    # Wrong record: each append re-lowers and re-registers the same helper
    # name, minting a fresh row formal; the last registration is the live
    # helper, so identities stamped at each call's emission named formals
    # that no longer exist and the heap-context projection refused the
    # call.  Rule: a sequence helper call binds the LIVE helper's formals by
    # position; once the function is complete, a call into a heap-owning
    # helper records exactly those formals as its ``callee_input_ids``.
    helpers = builder.sequence_helper_functions
    for block in (
        block
        for caller in (function, *helpers.values())
        for block in caller.blocks.values()
    ):
        for instruction in block.instrs:
            if instruction.op != "Call":
                continue
            helper = helpers.get(str(instruction.attributes.get("callee")))
            if helper is None or not any(
                (formal.accounting or {}).get("heap_owner")
                for formal in helper.args
            ):
                continue
            if len(helper.args) != len(instruction.args):
                raise ValueError(
                    "heap sequence helper call does not bind every live "
                    f"formal: {helper.name!r} has {len(helper.args)} "
                    f"formal(s), the call passes {len(instruction.args)}"
                )
            instruction.attributes["callee_input_ids"] = tuple(
                int(formal.id) for formal in helper.args
            )
    return function, shortfalls


def _settle_child_pool_operation_dtypes(
    functions: Mapping[str, Function],
    sequence_tables: Mapping[str, SSASequenceTable],
) -> None:
    """Join child-pool arena dtypes with their final SSA memory operations.

    Section composition may rebuild a control function after the builder has
    withdrawn its loop-local targets.  The final ``Load``/``Store`` still
    names the exact child-pool column through its GEP, and its scalar operand
    has the settled native dtype.  Reconcile that fact into the descriptor
    and every pre-addressing spelling of the arena.  Once address lowering
    has established a ``ptr`` view of that same arena identity, preserve it:
    the pointer is the column's transport ABI while ``column_dtypes`` is its
    element ABI.  Conflicting concrete *element* dtypes remain an ABI
    disagreement and are refused.
    """

    # Program: IdentityPage._resolved (bootstrap unit 33), a child-table
    # column arena minted ``unknown``.  Wrong record: the settled element
    # dtype was written onto every occurrence with no ``ssa_value``
    # revision, so the composed product's row said None while the GEP base
    # carried int64.  Rule: the settlement is a REVISE of the arena's row and
    # of each operation value's row, DERIVED from the cells of the Load/Store
    # values that witness it; occurrences follow the rows.  An accepted
    # component is an immutable source and is not settled here.
    from .concordance_declarations import FRAME_LINK as _SETTLE_STAGE
    from .ssa_record_return_state import (
        accepted_ssa_component as _accepted_pool_owner,
        revise_ssa_value as _revise_pool_value,
        ssa_value_identity_cell as _pool_value_cell,
    )

    functions = {
        name: function for name, function in functions.items()
        if not _accepted_pool_owner(function)
    }
    addresses: dict[tuple[str, int], tuple[int, int]] = {}
    for function_name, function in functions.items():
        for block in function.blocks.values():
            for instruction in block.instrs:
                attributes = instruction.attributes or {}
                if (
                    instruction.op == Handler.GetElementPtr.value
                    and instruction.res is not None
                    and len(instruction.args) >= 1
                    and attributes.get("binding") == "child_table_element"
                    and attributes.get("child_table_column") is not None
                ):
                    addresses[(str(function_name), int(instruction.res.id))] = (
                        int(instruction.args[0].id),
                        int(attributes["child_table_column"]),
                    )
    operation_dtypes: dict[tuple[str, int, int], set[str]] = {}
    operation_values: dict[tuple[str, int, int], list[SSAValue]] = {}
    for function_name, function in functions.items():
        for block in function.blocks.values():
            for instruction in block.instrs:
                if instruction.op == Handler.Load.value and instruction.args:
                    address = addresses.get((
                        str(function_name), int(instruction.args[0].id),
                    ))
                    value = instruction.res
                elif (
                    instruction.op == Handler.Store.value
                    and len(instruction.args) >= 2
                ):
                    address = addresses.get((
                        str(function_name), int(instruction.args[1].id),
                    ))
                    value = instruction.args[0]
                else:
                    continue
                if address is None or value is None:
                    continue
                dtype = str(
                    _canonical_sequence_dtype(value.dtype) or "unknown"
                )
                if dtype not in {"", "None", "unknown"}:
                    key = (str(function_name), *address)
                    operation_dtypes.setdefault(key, set()).add(dtype)
                    operation_values.setdefault(key, []).append(value)

    for (function_name, arena_id, column), dtypes in operation_dtypes.items():
        if len(dtypes) != 1:
            raise ValueError(
                "child-table column operations disagree on physical dtype: "
                f"function={function_name!r}, arena={arena_id}, "
                f"column={column}, "
                f"dtypes={tuple(sorted(dtypes))!r}"
            )
        dtype = next(iter(dtypes))
        function = functions[function_name]
        witnesses = tuple(
            cell for cell in (
                _pool_value_cell(function, int(value.id))
                for value in operation_values.get(
                    (function_name, arena_id, column), (),
                )
            ) if cell is not None
        )
        revised_ids: set[int] = set()

        def settle_row(value_id: int, shape) -> None:
            if int(value_id) in revised_ids:
                return
            revised_ids.add(int(value_id))
            _revise_pool_value(
                function, int(value_id), dtype=dtype, shape=tuple(shape or ()),
                stage=_SETTLE_STAGE, sources=witnesses,
            )

        for value in operation_values.get(
            (function_name, arena_id, column), (),
        ):
            incumbent = str(value.dtype or "unknown")
            canonical_incumbent = str(
                _canonical_sequence_dtype(incumbent) or "unknown"
            )
            if canonical_incumbent not in {
                "", "None", "unknown", dtype,
            }:
                raise ValueError(
                    "child-table operation changes its physical dtype: "
                    f"function={function_name!r}, arena={arena_id}, "
                    f"column={column}, "
                    f"operation={incumbent!r}, settled={dtype!r}"
                )
            if str(value.dtype or "unknown") != dtype:
                settle_row(int(value.id), value.shape)
            value.dtype = dtype
        if function is not None:
            values = (
                *function.args,
                *(
                    value
                    for block in function.blocks.values()
                    for instruction in block.instrs
                    for value in (
                        *instruction.args,
                        *((instruction.res,) if instruction.res is not None else ()),
                    )
                ),
            )
            for value in values:
                if int(value.id) != arena_id:
                    continue
                incumbent = str(value.dtype or "unknown")
                canonical_incumbent = str(
                    _canonical_sequence_dtype(incumbent) or "unknown"
                )
                if canonical_incumbent == "ptr":
                    # Address lowering turns the child column arena into the
                    # base operand of its GEP.  Its element representation is
                    # still recorded by the exact Load/Store value and the
                    # child-pool descriptor; a pointer view must not be
                    # retyped as an element scalar.
                    continue
                if canonical_incumbent not in {
                    "", "None", "unknown", dtype,
                }:
                    raise ValueError(
                        "child-table arena changes its physical dtype: "
                        f"function={function_name!r}, arena={arena_id}, "
                        f"declared={incumbent!r}, "
                        f"settled={dtype!r}"
                    )
                if incumbent != dtype:
                    settle_row(int(value.id), value.shape)
                value.dtype = dtype
        table = sequence_tables.get(function_name)
        if table is not None:
            for sequence_id, descriptor in tuple(table.sequences.items()):
                pool = descriptor.child_table_pool
                if (
                    pool is None
                    or column >= len(pool.column_value_ids)
                    or int(pool.column_value_ids[column]) != arena_id
                ):
                    continue
                incumbent = str(pool.column_dtypes[column])
                canonical_incumbent = str(
                    _canonical_sequence_dtype(incumbent) or "unknown"
                )
                if canonical_incumbent not in {
                    "", "None", "unknown", dtype,
                }:
                    raise ValueError(
                        "child-table descriptor changes its physical dtype: "
                        f"sequence={int(sequence_id)}, column={column}, "
                        f"declared={incumbent!r}, settled={dtype!r}"
                    )
                column_dtypes = list(pool.column_dtypes)
                column_dtypes[column] = dtype
                table.sequences[int(sequence_id)] = replace(
                    descriptor,
                    child_table_pool=replace(
                        pool, column_dtypes=tuple(column_dtypes),
                    ),
                )


def _sequence_artifacts_from_control(
    function: Function,
) -> tuple[dict[str, Function], dict[str, SSASequenceTable]]:
    """Recover source-linked sequence helpers and their function-local tables."""

    helpers = {
        helper.name: helper
        for helper in function.metadata.get("sequence_helper_functions", ())
    }
    table = function.metadata.get("sequence_table")
    if not isinstance(table, SSASequenceTable) or not table.sequences:
        return helpers, {}
    tables = {function.name: table}
    for helper in helpers.values():
        metadata = helper.metadata
        sequence_ids = tuple(dict.fromkeys(
            int(sequence_id)
            for sequence_id in (
                metadata.get("sequence_id"),
                metadata.get("destination_sequence_id"),
                metadata.get("source_sequence_id"),
            )
            if sequence_id is not None
        ))
        helper_table = SSASequenceTable(owner=helper.name)
        for sequence_id in sequence_ids:
            if sequence_id not in table.sequences:
                continue
            descriptor_cell = table.book.latest_ref(
                SEQUENCE_DESCRIPTOR,
                (table.owner, int(sequence_id)),
            )
            helper_table.register(
                replace(
                    table.sequences[sequence_id], child_table_pool=None,
                ),
                sources=(descriptor_cell,) if descriptor_cell is not None else (),
                stage=TABLE_REGISTRATION,
            )
        if helper_table.sequences:
            tables[helper.name] = helper_table
    return helpers, tables


def lower_class_navigation_to_ssa(
    navigation: Any,
    *,
    namespace: str = "turing.class",
) -> IRModule:
    """Lower class navigation to ordinary, backend-supported SSA primitives.

    Class/member identities and permission names become deterministic integer
    LUT indices and permission bits. Lookup is a chain of ``Eq``/``LAnd``/
    ``Select`` operations; permission checks are ``And`` plus ``Eq``. Missing
    or denied references are ``-1``. No class-specific opcode is introduced.
    """

    mapping = (
        navigation.to_mapping()
        if hasattr(navigation, "to_mapping")
        else dict(navigation)
    )

    classes = tuple(mapping.get("classes", ()))
    permission_names = sorted({
        str(permission)
        for record in classes
        for permission in (
            *record.get("permissions", ()),
            *(
                permission
                for member in record.get("members", ())
                for permission in member.get("permissions", ())
            ),
        )
    })
    permission_bits = {
        name: 1 << index for index, name in enumerate(permission_names)
    }

    def mask(names) -> int:
        result = 0
        for name in names:
            result |= permission_bits[str(name)]
        return result

    lut_classes = []
    member_index = 0
    for class_index, record in enumerate(classes):
        members = []
        for local_index, member in enumerate(record.get("members", ())):
            members.append({
                **dict(member),
                "member_index": member_index,
                "local_slot": local_index,
                "required_mask": mask(member.get("permissions", ())),
                "kind_code": 1 if member.get("kind") == "method" else 0,
                "reference": (
                    int(member["function_reference"])
                    if member.get("function_reference") is not None
                    else local_index
                ),
            })
            member_index += 1
        lut_classes.append({
            **dict(record),
            "class_index": class_index,
            "required_mask": mask(record.get("permissions", ())),
            "members": members,
        })
    lut = {
        "classes": lut_classes,
        "permission_bits": permission_bits,
    }

    from .identity_concordance import current_identity_book as _navigation_book

    class Builder:
        def __init__(self, name: str, dtypes: tuple[str, ...]):
            self.name = name
            # Every value of a navigation function is minted through the
            # book under the function's own scope: formals from the function
            # root, results from their operands' cells.
            self.book = _navigation_book()
            self.scope = str(name)
            self.root = _function_root_cell(self.book, self.scope)
            self.args = [
                SSAValue(self._mint(CONTROL_EXPRESSION, (), dtype), dtype=dtype)
                for dtype in dtypes
            ]
            self.instructions: list[Instr] = []

        def _mint(self, transform: Any, args: Any, dtype: str) -> int:
            operands = tuple(
                cell for cell in (
                    self.book.latest_ref(SSA_VALUE, (self.scope, int(value.id)))
                    for value in args
                )
                if cell is not None
            ) or (self.root,)
            return _mint_ssa_id(
                self.book, self.scope, transform, operands,
                dtype=dtype, stage=CONTROL_SSA_ENTRY,
            )

        def emit(self, operation: Handler, args=(), *, dtype="int32", **attributes):
            result = SSAValue(self._mint(
                CONTROL_CONST if operation is Handler.Const else CONTROL_EXPRESSION,
                args, dtype,
            ), dtype=dtype)
            self.instructions.append(Instr(
                operation.value, list(args), result, attributes=attributes,
            ))
            return result

        def constant(self, value: int, *, dtype="int32"):
            return self.emit(Handler.Const, dtype=dtype, value=int(value))

        def finish(self, results: list[SSAValue]):
            self.instructions.append(Instr(Handler.Ret.value, results, None))
            return Function(self.name, self.args, {
                "entry": BasicBlock("entry", self.instructions),
            })

    lookup = Builder(f"{namespace}.lookup", ("int32",))
    lookup_result = lookup.constant(-1)
    for record in lut_classes:
        class_id = lookup.constant(record["class_index"])
        matches = lookup.emit(Handler.Eq, (lookup.args[0], class_id), dtype="bool")
        row = lookup.constant(record["class_index"])
        lookup_result = lookup.emit(
            Handler.Select, (matches, row, lookup_result),
        )
    lookup_function = lookup.finish([lookup_result])

    permission = Builder(
        f"{namespace}.evaluate_permission", ("int32", "int32"),
    )
    present = permission.emit(Handler.And, permission.args)
    permitted = permission.emit(
        Handler.Eq, (present, permission.args[1]), dtype="bool",
    )
    permission_function = permission.finish([permitted])

    resolve = Builder(
        f"{namespace}.resolve_member", ("int32", "int32", "int32"),
    )
    resolved_kind = resolve.constant(-1)
    resolved_reference = resolve.constant(-1)
    resolved_allowed = resolve.constant(0, dtype="bool")
    for record in lut_classes:
        class_id = resolve.constant(record["class_index"])
        class_match = resolve.emit(
            Handler.Eq, (resolve.args[0], class_id), dtype="bool",
        )
        for member in record["members"]:
            member_id = resolve.constant(member["member_index"])
            member_match = resolve.emit(
                Handler.Eq, (resolve.args[1], member_id), dtype="bool",
            )
            identity_match = resolve.emit(
                Handler.LAnd, (class_match, member_match), dtype="bool",
            )
            required = resolve.constant(
                record["required_mask"] | member["required_mask"]
            )
            present = resolve.emit(Handler.And, (resolve.args[2], required))
            permission_match = resolve.emit(
                Handler.Eq, (present, required), dtype="bool",
            )
            allowed = resolve.emit(
                Handler.LAnd, (identity_match, permission_match), dtype="bool",
            )
            kind = resolve.constant(member["kind_code"])
            reference = resolve.constant(member["reference"])
            resolved_kind = resolve.emit(
                Handler.Select, (allowed, kind, resolved_kind),
            )
            resolved_reference = resolve.emit(
                Handler.Select, (allowed, reference, resolved_reference),
            )
            resolved_allowed = resolve.emit(
                Handler.Select,
                (identity_match, permission_match, resolved_allowed),
                dtype="bool",
            )
    resolve_function = resolve.finish([
        resolved_kind, resolved_reference, resolved_allowed,
    ])

    instantiate = Builder(
        f"{namespace}.instantiate", ("int32", "int32"),
    )
    new_reference = instantiate.constant(-1)
    init_reference = instantiate.constant(-1)
    instantiate_allowed = instantiate.constant(0, dtype="bool")
    for record in lut_classes:
        class_id = instantiate.constant(record["class_index"])
        class_match = instantiate.emit(
            Handler.Eq, (instantiate.args[0], class_id), dtype="bool",
        )
        constructors = list(record.get("instantiation_functions", ()))
        constructor_members = {
            member["function_reference"]: member
            for member in record["members"]
            if member.get("function_reference") is not None
        }
        required_mask = record["required_mask"]
        for reference in constructors:
            member = constructor_members.get(reference)
            if member is not None:
                required_mask |= member["required_mask"]
        required = instantiate.constant(required_mask)
        present = instantiate.emit(Handler.And, (instantiate.args[1], required))
        permission_match = instantiate.emit(
            Handler.Eq, (present, required), dtype="bool",
        )
        allowed = instantiate.emit(
            Handler.LAnd, (class_match, permission_match), dtype="bool",
        )
        new_value = instantiate.constant(next((
            int(member["function_reference"])
            for member in record["members"]
            if member["name"] == "__new__"
            and member.get("function_reference") is not None
        ), -1))
        init_value = instantiate.constant(next((
            int(member["function_reference"])
            for member in record["members"]
            if member["name"] == "__init__"
            and member.get("function_reference") is not None
        ), -1))
        new_reference = instantiate.emit(
            Handler.Select, (allowed, new_value, new_reference),
        )
        init_reference = instantiate.emit(
            Handler.Select, (allowed, init_value, init_reference),
        )
        instantiate_allowed = instantiate.emit(
            Handler.Select,
            (class_match, permission_match, instantiate_allowed),
            dtype="bool",
        )
    instantiate_function = instantiate.finish([
        new_reference, init_reference, instantiate_allowed,
    ])

    functions = (
        lookup_function,
        instantiate_function,
        resolve_function,
        permission_function,
    )
    for function in functions:
        function.blocks["entry"].instrs[0].attributes.setdefault(
            "class_navigation_lut", lut,
        )

    # Hold the class DEFINITIONS in the module, not only the reference LUTs: each
    # class's instance-field layout and its methods (with the function-table
    # reference to each method's body). A backend reads this to emit a class's
    # methods as real, individually linkable functions -- the SSA counterpart of
    # the frontend ClassNavigationTable.
    class_definitions = []
    for record in classes:
        members = record.get("members", ())
        fields = tuple(
            SSAClassField(name=str(member["name"]), slot=int(member["slot"]))
            for member in members
            if member.get("kind") == "attribute"
            and member.get("storage") == "instance"
            and member.get("slot") is not None
        )
        methods = tuple(
            SSAClassMethod(
                name=str(member["name"]),
                function_reference=int(member["function_reference"]),
            )
            for member in members
            if member.get("function_reference") is not None
        )
        class_definitions.append(
            SSAClassDefinition(
                identity=str(record.get("identity", "")),
                fields=fields,
                methods=methods,
            )
        )
    class_table = SSAClassTable(classes=tuple(class_definitions))
    return IRModule(
        {function.name: function for function in functions},
        class_table=class_table,
    )


def find_ssa_cycles(function: Function) -> tuple[SSACycle, ...]:
    graph = nx.DiGraph()
    graph.add_nodes_from(function.blocks)
    for block in function.blocks.values():
        graph.add_edges_from(
            (block.name, successor)
            for successor in block.successors
        )
    cycles = []
    for component in nx.strongly_connected_components(graph):
        cyclic = len(component) > 1 or any(
            graph.has_edge(name, name) for name in component
        )
        if not cyclic:
            continue
        ordered = tuple(sorted(component))
        edges = tuple(sorted(
            (source, target)
            for source in component
            for target in graph.successors(source)
            if target in component
        ))
        phi_blocks = tuple(sorted(
            block_name
            for block_name in component
            if any(
                instruction.op in {
                    Handler.Phi.value,
                    Handler.Phi.value.lower(),
                }
                for instruction in function.blocks[block_name].instrs
            )
        ))
        cycles.append(
            SSACycle(function.name, ordered, edges, phi_blocks)
        )
    return tuple(sorted(cycles))


def _inject_field_slot_access(
    control_function: Function,
    *,
    self_value_id: int,
    non_self_param_ids: tuple[int, ...],
    non_self_parameters: tuple[tuple[str, int], ...] = (),
    field_ops: tuple[tuple[str, int, int], ...],
    field_count: int,
    field_const_sources: Mapping[int, Any] | None = None,
    output_value_ids: tuple[int, ...] = (),
    dtype: str | None = None,
    field_dtypes: Mapping[int, str] | None = None,
    separate_field_storage: bool = False,
    field_accounting: Mapping[int, Mapping[str, Any]] | None = None,
    field_physical: Mapping[int, tuple[Mapping[str, Any], tuple]] | None = None,
    receiver_accounting: Mapping[str, Any] | None = None,
    field_write_state_cells: tuple[Any, ...] = (),
    lexical_read_scope: Any = None,
    resident_field_locations: Mapping[int, tuple[SSAValue, int, str]] | None = None,
) -> tuple[Function, dict[int, tuple[int, int, str]]]:
    """Rewrite a method's control function to pass instance state as a slot arena.

    ``self`` becomes one or more sized field columns. Each logical field slot
    resolves through a deterministic ``(typed arena, local offset)`` location;
    homogeneous receivers therefore retain their one-array ABI, while mixed
    receivers use only as many typed columns as their actual fields require.
    Each field read is a ``Load`` from that location (producing the value the
    body already consumes, so it is no longer a free input); each field write
    is a ``Store`` of its source into it. The parameter list is rebuilt as
    ``(*receiver_columns, *non_self_params)``. A backend that indexes arrays
    renders each physical access directly and marks a written column
    ``intent(inout)``.

    Placement follows the schedule the graph already fixed, carried here by SSA
    data flow: a load goes right before the first instruction that consumes its
    value, a store right after the instruction that produces its source (or at
    the top, for a source that is a plain parameter). That is exactly the order
    the source wrote, so a read and a write of one slot -- ``self.x = v; return
    self.x`` -- emits store-then-load and reads back ``v`` with no special case.
    ``field_reads``/``field_writes`` arrive in schedule order so any two ops that
    land at the same point keep it.

    A write whose reducer WRITTEN cell (``field_write_state_cells``, one per
    ``"write"`` op) was lowered at its authored site -- control lowering
    emitted the ``scalar_record_field_assignment`` Store in the arm that owns
    the assignment and published that arm's value under the cell on
    ``ssa_field_version`` -- is OWNED by that arm: this Store is rewritten in
    place into the real slot store, and no second store is placed after the
    source's producer (which, for a literal or a value computed before the
    ``if``, is a dominating block and would run on every path).  The arm is
    the ``control_block_placement`` row of the cell's ``scalar_field_write``
    block; the slot address derives from that row.
    """

    if not control_function.blocks:
        return control_function, {}

    existing_ids = {int(value.id) for value in control_function.args}
    for block in control_function.blocks.values():
        for instruction in block.instrs:
            if instruction.res is not None:
                existing_ids.add(int(instruction.res.id))
    existing_ids.add(int(self_value_id))
    existing_ids.update(int(pid) for pid in non_self_param_ids)
    # The field ops name values that come from the graph, not the control body
    # (a read's result, a write's source), so a fresh Const/address id must
    # dodge those too or it collides with a load result.
    existing_ids.update(int(value_id) for _kind, value_id, _slot in field_ops)
    existing_ids.update(int(value_id) for value_id in output_value_ids)
    # Field-slot cells are FIELD_SLOT_ACCESS mints on the control function's
    # scope, from the receiver's ``ssa_value`` cell (its parameter seed) or
    # the function root when the receiver has no row.
    from .identity_concordance import current_identity_book as _slot_book

    _slot_scope = str(
        control_function.metadata.get("tensor_shape_concordance_scope")
        or control_function.name
    )
    _receiver_cell = _slot_book().latest_ref(
        SSA_VALUE, (_slot_scope, int(self_value_id)),
    )

    def fresh(*causes: Any, value_dtype: str) -> int:
        book = _slot_book()
        operand = (
            _receiver_cell if _receiver_cell is not None
            else _function_root_cell(book, _slot_scope)
        )
        return _mint_ssa_id(
            book, _slot_scope, FIELD_SLOT_ACCESS, (operand, *causes),
            dtype=value_dtype,
            stage=CONTROL_SSA_FINISH,
        )

    def publish_row(
        value: SSAValue, *causes: Any, physical: Any = KEEP_PHYSICAL,
    ) -> None:
        # Program: a method reading/writing ``self.<field>`` of an
        # opaque_ref field (test_ir_sequence_tables::
        # test_static_program_reference_is_typed_ssa_and_native_handle_
        # storage). Wrong record: this injector builds the receiver column
        # and the field-read Load / write-source values with the (dtype, shape) it is
        # about to emit, but posted no ``ssa_value`` row (or left the row
        # ``fresh()`` minted with the default dtype). Rule: the pass that
        # makes a value posts it at that moment -- ADOPTED_GRAPH_ID derived
        # from the receiver's cell (else the function root) and ``causes``
        # when the id has no row, a REVISE of the existing row otherwise.
        from .ssa_record_return_state import revise_ssa_value

        book = _slot_book()
        row = (_slot_scope, int(value.id))
        shape = tuple(value.shape or ())
        if book.latest_ref(SSA_VALUE, row) is None:
            operand = (
                _receiver_cell if _receiver_cell is not None
                else _function_root_cell(book, _slot_scope)
            )
            book.post(
                SSA_VALUE, row,
                rebuilt_ssa_value_fact(
                    None, value.dtype, shape,
                    SSAValueOrigin.ADOPTED_GRAPH_ID, physical,
                ),
                stage=CONTROL_SSA_FINISH,
                provenance=Derived(tuple(dict.fromkeys(
                    cell for cell in (operand, *causes)
                    if isinstance(cell, Ref)
                ))),
                mode=Mode.REVISE,
            )
            return
        revise_ssa_value(
            control_function, int(value.id), dtype=value.dtype, shape=shape,
            stage=CONTROL_SSA_FINISH, sources=causes, book=book,
            physical=physical,
        )

    # A receiver is physically a set of typed columns.  The traditional one
    # arena form is the degenerate (and fastest) one-column case.  Slots keep a
    # logical index, while this table resolves that index to (arena, offset),
    # so mixed fields never need coercion or a tagged-object runtime.
    slot_dtypes = {
        int(slot): str((field_dtypes or {}).get(int(slot), dtype))
        for _kind, _value_id, slot in field_ops
    }
    column_keys = (
        tuple((slot_dtypes[slot], int(slot)) for slot in sorted(slot_dtypes))
        if separate_field_storage else
        tuple((column_dtype, None) for column_dtype in sorted(
            set(slot_dtypes.values()) or {str(dtype)}
        ))
    )
    slots_by_column = {
        key: (
            (key[1],) if key[1] is not None else tuple(sorted(
                slot for slot, slot_dtype in slot_dtypes.items()
                if slot_dtype == key[0]
            ))
        )
        for key in column_keys
    }
    column_arrays: dict[tuple[str, int | None], SSAValue] = {}
    for index, key in enumerate(column_keys):
        column_dtype = key[0]
        if resident_field_locations is not None:
            if key[1] is None or int(key[1]) not in resident_field_locations:
                raise ValueError("resident record field loads require exact separate slot locations")
            column_arrays[key] = resident_field_locations[int(key[1])][0]
            continue
        arena_id = int(self_value_id) if index == 0 else fresh(value_dtype=column_dtype)
        column_arrays[key] = SSAValue(
            arena_id, dtype=column_dtype,
            shape=(len(slots_by_column[key]),),
            accounting=(
                dict((field_accounting or {}).get(int(key[1]), {}))
                # A shared receiver column holds several slots, so no single
                # field names it; it is still the authored ``self`` formal.
                # Declare that (``program_abi_parameter``) instead of leaving
                # the formal with no parameter, ABI or frame claim at all.
                if key[1] is not None else dict(receiver_accounting or {})
            ),
        )
        _declared = (
            (field_physical or {}).get(int(key[1]))
            if key[1] is not None else None
        )
        if _declared is None:
            publish_row(column_arrays[key])
        else:
            publish_row(
                column_arrays[key], *_declared[1], physical=_declared[0],
            )
            # Accounting is the view of the fact just posted.
            _posted = _slot_book().latest_ref(
                SSA_VALUE, (_slot_scope, int(column_arrays[key].id)),
            )
            _posted_fact = _slot_book().page(SSA_VALUE).cell(
                _posted.row, _posted.column,
            )
            column_arrays[key].accounting = {
                **dict(column_arrays[key].accounting or {}),
                "program_abi_storage": _posted_fact.storage,
                "program_abi_rank": _posted_fact.rank,
            }
    field_locations = {
        slot: (
            int(column_arrays[(slot_dtype, slot if separate_field_storage else None)].id),
            slots_by_column[(slot_dtype, slot if separate_field_storage else None)].index(slot),
            slot_dtype,
        )
        for slot, slot_dtype in slot_dtypes.items()
    }
    if resident_field_locations is not None:
        field_locations = {
            int(slot): (int(value.id), int(offset), str(dtype))
            for slot, (value, offset, dtype) in resident_field_locations.items()
        }
    # Graph identities are not SSA versions.  A SetAttr result may therefore
    # carry the same numeric id as the receiver column which must receive it
    # (for example ``self.dt_max = computed`` can name both values ``18``).
    # Give the computed definition its own SSA identity while retaining the
    # receiver column's public/call-frame id.  The Store below then provides
    # the explicit bridge which was previously lost as an apparent self-write.
    field_write_sources: dict[int, SSAValue] = {}
    receiver_column_ids = {
        int(value.id) for value in column_arrays.values()
    }
    for kind, value_id, _slot in field_ops:
        value_id = int(value_id)
        if kind != "write" or value_id not in receiver_column_ids:
            continue
        producers = [
            instruction
            for block in control_function.blocks.values()
            for instruction in block.instrs
            if instruction.res is not None
            and int(instruction.res.id) == value_id
        ]
        if len(producers) != 1:
            continue
        producer = producers[0]
        original = producer.res
        version = SSAValue(
            fresh(value_dtype=original.dtype),
            dtype=original.dtype,
            shape=tuple(original.shape),
            device=original.device,
            accounting={
                **dict(original.accounting or {}),
                "ssa_field_write_version_of": value_id,
            },
        )
        producer.res = version
        for block in control_function.blocks.values():
            for instruction in block.instrs:
                instruction.args = [
                    version if argument is original else argument
                    for argument in instruction.args
                ]
        field_write_sources[value_id] = version
    const_sources = dict(field_const_sources or {})
    reference_sources = {
        int(value_id): dict(payload)
        for value_id, payload in const_sources.items()
        if isinstance(payload, Mapping)
        and payload.get("ssa_reference_identity") is not None
    }
    reference_slots = {
        int(slot)
        for kind, value_id, slot in field_ops
        if kind == "write" and int(value_id) in reference_sources
    }

    def slot_address(
        slot: int, *causes: Any,
    ) -> tuple[list[Instr], SSAValue, str]:
        arena_id, offset, slot_dtype = field_locations[int(slot)]
        # The offset is an int64 index whatever the receiver's dtype: minting
        # it with the receiver dtype typed it ``bool`` on a bool-first
        # receiver, and Fortran refused ``logical + 1`` as an index.
        index = SSAValue(fresh(*causes, value_dtype="int64"), dtype="int64")
        address = SSAValue(fresh(*causes, value_dtype=slot_dtype))
        return (
            [
                Instr("Const", [], index, attributes={"value": int(offset)}),
                Instr("GetElementPtr", [column_arrays[(
                    slot_dtype, int(slot) if separate_field_storage else None
                )], index], address),
            ],
            address,
            slot_dtype,
        )

    # The blocks are already in schedule order, so number every instruction once
    # across them; producer and first-consumer positions in that numbering are
    # where each store and load belong.
    flat = [
        (name, instruction)
        for name, block in control_function.blocks.items()
        for instruction in block.instrs
    ]
    # Arm-owned writes.  Control lowering emitted each declared scalar field
    # assignment as a ``scalar_record_field_assignment`` Store at the block's
    # own site (inside the arm that owns it) and published its value on
    # ``ssa_field_version`` under the write's reducer cell; the write op of
    # ``field_ops`` names that same cell.  The authored site is therefore a
    # lookup by cell, not a search for the source's producer.
    arm_stores: dict[Any, int] = {}
    for position, (_name, instruction) in enumerate(flat):
        if (
            instruction.op in {"Store", "store"}
            and (instruction.attributes or {}).get("binding")
            == "scalar_record_field_assignment"
            and isinstance(
                (instruction.attributes or {}).get("field_state_cell"), Ref
            )
        ):
            arm_stores.setdefault(
                instruction.attributes["field_state_cell"], position
            )
    _write_cells = (
        iter(field_write_state_cells)
        if len(field_write_state_cells)
        == sum(1 for op in field_ops if op[0] == "write") else iter(())
    )
    _read_ids = {
        int(value_id) for kind, value_id, _slot in field_ops if kind == "read"
    }
    # op index -> flat position of the arm Store that IS that write; and the
    # positions whose destination is a field READ (the placeholder named the
    # field by its read value, which injection turns into a Load -- data, not
    # an address, so that Store does nothing and is replaced by the real one).
    arm_owned: dict[int, tuple[int, Any]] = {}
    placeholder_positions: set[int] = set()
    claimed_positions: set[int] = set()
    for op_index, (kind, value_id, _slot) in enumerate(field_ops):
        if kind != "write":
            continue
        cell = next(_write_cells, None)
        position = arm_stores.get(cell)
        if position is None or position in claimed_positions:
            continue
        claimed_positions.add(position)
        arm_owned[op_index] = (position, cell)
        if int(flat[position][1].args[1].id) in _read_ids:
            placeholder_positions.add(position)
    replaced_at: dict[int, list[Instr]] = {}

    producer_position: dict[int, int] = {}
    produced_values: dict[int, SSAValue] = {}
    first_consumer_position: dict[int, int] = {}
    for position, (_name, instruction) in enumerate(flat):
        if instruction.res is not None:
            producer_position.setdefault(int(instruction.res.id), position)
            produced_values.setdefault(int(instruction.res.id), instruction.res)
        for index, argument in enumerate(instruction.args):
            if index == 1 and position in placeholder_positions:
                continue  # the replaced placeholder's destination: not a use
            first_consumer_position.setdefault(int(argument.id), position)

    entry_name = next(iter(control_function.blocks))

    # A method that returns a field value (a getter, ``return self.x``) has no
    # producer for that value in the control body -- it is one of these loads.
    # The control lowering could not wire it as an output because it did not yet
    # exist, so treat the return as the load's consumer and add the value to the
    # return below.
    return_ops = {Handler.Ret.value, "ret", "Return", "return"}
    return_position = next(
        (
            position
            for position in range(len(flat) - 1, -1, -1)
            if flat[position][1].op in return_ops
        ),
        None,
    )
    output_ids = tuple(int(value_id) for value_id in output_value_ids)
    output_id_set = set(output_ids)

    # (insert-position, schedule-order, home-block, instructions). The second
    # key is the field op's index in the schedule, so two ops that land at the
    # same instruction keep the order the source wrote -- a store before the
    # read that must observe it.
    insertions: list[tuple[int, int, str, list[Instr]]] = []
    field_read_ids: set[int] = {
        int(value_id) for kind, value_id, _slot in field_ops if kind == "read"
    }
    def arm_placement(cell: Any) -> Any:
        """The ``control_block_placement`` cell of the ``scalar_field_write``
        block that IS ``cell`` (None when the book has no such row)."""

        if lexical_read_scope is None:
            return None
        from .concordance_declarations import (
            CONTROL_BLOCK, CONTROL_BLOCK_PLACEMENT, ControlBlockKind,
        )

        book = _slot_book()
        scope = tuple(lexical_read_scope)
        block = book.latest_ref(
            CONTROL_BLOCK, (scope, ControlBlockKind.SCALAR_FIELD_WRITE, cell),
        )
        return None if block is None else book.latest_ref(
            CONTROL_BLOCK_PLACEMENT, (scope, block),
        )

    # The reads this injection materialises as slot Loads: each is a VERSION
    # of its field, read at its own place and time, not an address of it.  It
    # is posted on ``receiver_field_slot_read`` so record-ABI materialization
    # reads the decision from the book.
    from .concordance_declarations import (
        RECEIVER_FIELD_SLOT_READ, ReceiverFieldSlotReadFact,
    )

    _write_ops = [op for op in field_ops if op[0] == "write"]
    _slot_write_cell: dict[int, Any] = {}
    if len(field_write_state_cells) == len(_write_ops):
        for (_k, _v, _slot), _cell in zip(_write_ops, field_write_state_cells):
            if isinstance(_cell, Ref):
                _slot_write_cell.setdefault(int(_slot), _cell)

    def _post_slot_read(read_id: int, slot: int, address: SSAValue) -> None:
        book = _slot_book()
        sources = tuple(dict.fromkeys(
            cell for cell in (
                book.latest_ref(SSA_VALUE, (_slot_scope, int(address.id))),
                book.latest_ref(SSA_VALUE, (_slot_scope, int(read_id))),
                _slot_write_cell.get(int(slot)),
            ) if isinstance(cell, Ref)
        ))
        if not sources:
            return
        book.post(
            RECEIVER_FIELD_SLOT_READ, (_slot_scope, int(read_id)),
            ReceiverFieldSlotReadFact(int(slot), int(read_id)),
            stage=CONTROL_SSA_FINISH, provenance=Derived(sources),
            mode=Mode.CONCORD,
        )

    materialized_references: set[int] = set()
    for schedule_index, (kind, value_id, slot) in enumerate(field_ops):
        if schedule_index in arm_owned:
            position, write_cell = arm_owned[schedule_index]
            authored = flat[position][1]
            source = authored.args[0]
            placement = arm_placement(write_cell)
            causes = () if placement is None else (placement,)
            prelude, address, slot_dtype = slot_address(slot, *causes)
            group = []
            # A static reference has no producer in the control body: it is
            # materialised once where it dominates every use (the entry --
            # a handle constant, no effect), as a reference write always was.
            # Only the STORE of it is the arm's.
            reference = reference_sources.get(int(source.id))
            if reference is not None and int(source.id) not in (
                producer_position
            ) and int(source.id) not in materialized_references:
                materialized_references.add(int(source.id))
                reference_value = SSAValue(int(source.id), dtype="opaque_ref")
                publish_row(reference_value)
                insertions.append((0, schedule_index, entry_name, [Instr(
                    Handler.StaticRef.value, [], reference_value,
                    attributes={
                        "reference_handle": int(reference["reference_handle"]),
                        "reference_identity": str(
                            reference["ssa_reference_identity"]
                        ),
                        "reference_kind": str(
                            reference.get("reference_kind", "static-python")
                        ),
                        "host_resident": bool(
                            reference.get("host_resident", True)
                        ),
                    },
                )]))
            # A literal is materialised in the slot's dtype, as a constant
            # field write always was.
            literal = producer_position.get(int(source.id))
            if literal is not None and flat[literal][1].op == "Const" and (
                not flat[literal][1].args
            ):
                source = SSAValue(fresh(*causes, value_dtype=slot_dtype), dtype=slot_dtype)
                publish_row(source)
                group.append(Instr(
                    "Const", [], source,
                    attributes=dict(flat[literal][1].attributes or {}),
                ))
            group += [*prelude, Instr(
                "Store", [source, address], None,
                attributes={
                    "opaque_reference_storage": True, "field_slot": int(slot),
                } if slot_dtype == "opaque_ref" else {},
            )]
            # A placeholder that named the field by a read is replaced; one
            # that names the field's incoming formal stays (it writes that
            # formal in this arm) and the slot store follows it.
            replaced_at[position] = (
                group if position in placeholder_positions
                else [authored, *group]
            )
            continue
        prelude, address, slot_dtype = slot_address(slot)
        if kind == "read":
            value_dtype = (
                "opaque_ref" if int(slot) in reference_slots else slot_dtype
            )
            loaded = SSAValue(int(value_id), dtype=value_dtype)
            publish_row(
                loaded,
                _slot_book().latest_ref(
                    SSA_VALUE, (_slot_scope, int(address.id)),
                ),
            )
            group = [
                *prelude,
                Instr(
                    "Load",
                    [address],
                    loaded,
                    attributes={
                        "opaque_reference_storage": True,
                        "field_slot": int(slot),
                    } if value_dtype == "opaque_ref" else {},
                ),
            ]
            position = first_consumer_position.get(int(value_id))
            if position is None and int(value_id) in output_id_set:
                position = return_position  # returned but otherwise unconsumed
            if position is None:
                continue  # a read nothing consumes has no place and no effect
            # Program: ``value = self.n; self.n += 1; return value`` (a
            # counter's ``fresh``).  Wrong record: the read's only consumer is
            # the ``return``, so its Load was placed right before it -- after
            # the Store of the increment -- and the call returned the new
            # value.  Rule: a read stays ahead of any LATER write to its own
            # slot in the schedule: when that write's Store lands at or before
            # the read's placement in the same block, the read is placed at
            # that Store (it sorts first by schedule index).
            for later_index in range(schedule_index + 1, len(field_ops)):
                later_kind, later_value, later_slot = field_ops[later_index]
                if later_kind != "write" or int(later_slot) != int(slot):
                    continue
                if later_index in arm_owned:
                    store_position = arm_owned[later_index][0]
                else:
                    later_source = field_write_sources.get(
                        int(later_value),
                        produced_values.get(int(later_value)),
                    )
                    later_producer = (
                        None if later_source is None
                        else producer_position.get(int(later_source.id))
                    )
                    store_position = (
                        later_producer + 1 if later_producer is not None else 0
                    )
                if (
                    store_position < position
                    and flat[store_position][0] == flat[position][0]
                ):
                    position = store_position
            _post_slot_read(int(value_id), int(slot), address)
        else:
            group = []
            reference = reference_sources.get(int(value_id))
            source_dtype = "opaque_ref" if reference is not None else slot_dtype
            stored_source = field_write_sources.get(
                int(value_id),
                produced_values.get(
                    int(value_id), SSAValue(int(value_id), dtype=source_dtype),
                ),
            )
            # A constant field write (self.x = None / 5 / "s") has no producer
            # in the control body, so materialise its source here -- the
            # tokenizer then turns a None/str/bytes const into a token.
            if reference is not None and int(value_id) not in producer_position:
                reference_value = SSAValue(int(value_id), dtype="opaque_ref")
                publish_row(reference_value)
                group.append(Instr(
                    Handler.StaticRef.value,
                    [],
                    reference_value,
                    attributes={
                        "reference_handle": int(reference["reference_handle"]),
                        "reference_identity": str(
                            reference["ssa_reference_identity"]
                        ),
                        "reference_kind": str(
                            reference.get("reference_kind", "static-python")
                        ),
                        "host_resident": bool(
                            reference.get("host_resident", True)
                        ),
                    },
                ))
            elif int(value_id) in const_sources and int(value_id) not in (
                producer_position
            ):
                literal_value = SSAValue(int(value_id), dtype=slot_dtype)
                publish_row(literal_value)
                group.append(
                    Instr(
                        "Const",
                        [],
                        literal_value,
                        attributes={"value": const_sources[int(value_id)]},
                    )
                )
            group += [
                *prelude,
                Instr(
                    "Store",
                    [stored_source, address],
                    None,
                    attributes={
                        "opaque_reference_storage": True,
                        "field_slot": int(slot),
                    } if source_dtype == "opaque_ref" else {},
                ),
            ]
            producer = producer_position.get(int(stored_source.id))
            # After the producer; a parameter source has none, so at the top.
            position = producer + 1 if producer is not None else 0
        home = flat[position][0] if position < len(flat) else (
            flat[-1][0] if flat else entry_name
        )
        insertions.append((position, schedule_index, home, group))

    from collections import defaultdict

    inserts_at: dict[int, list[list[Instr]]] = defaultdict(list)
    for position, _order, _home, group in sorted(
        insertions, key=lambda item: (item[0], item[1])
    ):
        inserts_at[position].append(group)

    # Field values that are returned but were not already on the return
    # instruction (the control lowering could not see them): append them so the
    # target declares them as outputs, keeping function-output order.
    existing_return_arg_ids = (
        {int(argument.id) for argument in flat[return_position][1].args}
        if return_position is not None
        else set()
    )
    returned_field_values = [
        SSAValue(int(value_id), dtype=field_locations[
            next(slot for kind, candidate, slot in field_ops
                 if kind == "read" and int(candidate) == int(value_id))
        ][2])
        for value_id in output_ids
        if value_id in field_read_ids and value_id not in existing_return_arg_ids
    ]

    rebuilt: dict[str, list[Instr]] = {
        name: [] for name in control_function.blocks
    }
    for position, (name, instruction) in enumerate(flat):
        for group in inserts_at.get(position, ()):
            rebuilt[name].extend(group)
        if position in replaced_at:
            rebuilt[name].extend(replaced_at[position])
            continue
        if position == return_position and returned_field_values:
            instruction = Instr(
                instruction.op,
                [*instruction.args, *returned_field_values],
                instruction.res,
            )
        rebuilt[name].append(instruction)
    trailing = inserts_at.get(len(flat), ())
    if trailing:
        tail_block = flat[-1][0] if flat else entry_name
        for group in trailing:
            rebuilt[tail_block].extend(group)

    new_blocks = {
        name: BasicBlock(
            name,
            rebuilt[name],
            list(control_function.blocks[name].successors),
        )
        for name in control_function.blocks
    }

    # ``self`` first, then the non-self parameters in declared order; the read
    # field values are no longer parameters because the loads produce them.
    arguments = ([column_arrays[key] for key in column_keys]
                 if resident_field_locations is None else [])
    seen_argument_ids = {int(argument.id) for argument in arguments}
    for argument in control_function.args:
        argument_id = int(argument.id)
        if (
            argument_id in seen_argument_ids
            or argument_id in field_read_ids
            or argument_id in materialized_references
        ):
            continue
        arguments.append(argument)
        seen_argument_ids.add(argument_id)
    # A source parameter unused by the current specialized body may not have
    # been materialized by control lowering, but it remains part of the public
    # method signature. Add only those absent declared parameters; all sequence
    # and child-pool ABI arguments above retain their exact shapes and dtypes.
    for param_id in non_self_param_ids:
        if int(param_id) not in seen_argument_ids and int(param_id) not in field_read_ids:
            if dtype is None:
                raise ValueError(
                    f"parameter value %{int(param_id)} is absent from the "
                    f"lowered receiver method {control_function.name} and its "
                    "dtype is not recorded"
                )
            arguments.append(SSAValue(int(param_id), dtype=dtype))
            seen_argument_ids.add(int(param_id))

    # Control lowering names parameters from uses present before receiver-slot
    # injection.  A constructor parameter used only by ``self.field = value``
    # has no such use until the Store above is installed, even though the
    # ProcessGraph identity table already names its exact version-zero input.
    # Publish that existing identity now, at the same seam that rebuilds the
    # public argument list.  This is not a positional reconstruction: callers
    # provide the exact authored name/value pairs from the identity table.
    parameter_names = list(control_function.metadata.get(
        "parameter_names", (),
    ))
    named_parameters = {
        str(name): int(value_id) for name, value_id in parameter_names
    }
    arguments_by_id = {int(argument.id): argument for argument in arguments}
    for name, value_id in non_self_parameters:
        name = str(name)
        value_id = int(value_id)
        argument = arguments_by_id.get(value_id)
        if argument is None:
            continue
        incumbent = named_parameters.get(name)
        if incumbent is not None and incumbent != value_id:
            # Control lowering ran before receiver-slot injection and could
            # therefore name a later lexical version when the version-zero
            # parameter was used only by ``self.field = parameter``.  The
            # identity table supplies that exact authored input here.  Keep
            # the later value as an ordinary frame argument, but move the one
            # public parameter name to the authored identity.
            incumbent_argument = arguments_by_id.get(int(incumbent))
            if (
                incumbent_argument is not None
                and (incumbent_argument.accounting or {}).get(
                    "program_abi_parameter"
                ) == name
            ):
                incumbent_argument.accounting = {
                    key: item
                    for key, item in dict(
                        incumbent_argument.accounting or {}
                    ).items()
                    if key != "program_abi_parameter"
                }
            parameter_names = [
                (existing_name, existing_id)
                for existing_name, existing_id in parameter_names
                if str(existing_name) != name
            ]
            named_parameters.pop(name, None)
            incumbent = None
        claimed_name = (argument.accounting or {}).get(
            "program_abi_parameter"
        )
        if claimed_name not in {None, "", name}:
            raise ValueError(
                "field-slot injection parameter identity disagrees with "
                f"formal {value_id}: {claimed_name!r} != {name!r}"
            )
        argument.accounting = {
            **dict(argument.accounting or {}),
            "program_abi_parameter": name,
        }
        if incumbent is None:
            parameter_names.append((name, value_id))
            named_parameters[name] = value_id

    return Function(
        control_function.name,
        arguments,
        new_blocks,
        metadata={
            **dict(control_function.metadata),
            "parameter_names": tuple(parameter_names),
            **({"receiver_field_locations": tuple(sorted(
                (int(slot), *location)
                for slot, location in field_locations.items()
            ))} if resident_field_locations is None else {}),
        },
    ), field_locations


def _schedule_loop_callsites(
    control: ControlProgram,
    hierarchy_plan: "PlanClosure | None",
    region_signatures: Mapping[int, tuple[tuple[int, ...], tuple[int, ...]]],
    region_dependency_signatures: Mapping[
        int, tuple[tuple[int, ...], tuple[int, ...]]
    ] | None = None,
    callsite_projection_ids: Mapping[int, tuple[int, ...]] | None = None,
    callsite_stored_argument_ids: Mapping[int, frozenset[int]] | None = None,
    sequence_length_values: Mapping[int, int] | None = None,
    pure_region_indices: frozenset[int] = frozenset(),
    table_region_operations: Mapping[int, Any] | None = None,
    table_region_post_operations: Mapping[int, Any] | None = None,
) -> tuple[ControlProgram, dict[int, tuple[tuple[int, ...], tuple[int, ...]]]]:
    """Install this closure's PlanCalls as ordinary scheduled statements.

    The hierarchy plan already interleaves calls and numerical regions. Carry
    that order into local Control IR: a call precedes the next retained region,
    or remains at its enclosing loop/closure boundary when it is trailing.
    The dependency pass below can then order calls by their exact argument and
    result identities just as it orders numerical regions. Linking supplies
    the final physical frame later; it does not rediscover execution position.
    """

    if hierarchy_plan is None:
        return control, {}

    bindings: dict[int, tuple[tuple[int, ...], tuple[int, ...]]] = {}
    planned_calls: dict[int, PlanCall] = {
        int(item.callsite_id): item
        for item in hierarchy_plan.items
        if isinstance(item, PlanCall)
    }
    for callsite_id, item in planned_calls.items():
        argument_ids = tuple(
            int(caller_id)
            for caller_id, _callee_id in item.argument_bindings
        ) or tuple(int(v) for v in item.argument_value_ids)
        result_ids = tuple(
            int(caller_id)
            for _callee_id, caller_id in item.result_bindings
        ) or tuple(int(v) for v in item.result_value_ids)
        bindings[callsite_id] = (argument_ids, result_ids)

    # Value dependencies are not the whole execution-order contract.  A
    # mutable aggregate write can publish a fresh graph identity while the
    # following call is deliberately rebound to the same resident storage.
    # At that boundary the call arguments and the write-region outputs need
    # not share an SSA value id, but their order is still explicit in the
    # hierarchy.  Preserve that order as a precedence chain among the
    # hierarchy statements which survive in this control closure.  Structural
    # producers not represented by a PlanCall/region remain free to move ahead
    # when the ordinary dependency analysis below proves that necessary.
    hierarchy_statement_rank: dict[tuple[str, int], int] = {}
    for position, item in enumerate(hierarchy_plan.items):
        if isinstance(item, PlanCall):
            hierarchy_statement_rank[("call", int(item.callsite_id))] = position
        elif (
            isinstance(item, PlanClosure)
            and item.name.startswith("region_")
        ):
            hierarchy_statement_rank[(
                "region", int(item.name.split("_", 1)[1])
            )] = position

    def scheduled_region(block: Any) -> int | None:
        if not isinstance(block, StatementBlock) or len(block.lines) != 1:
            return None
        match = _REGION_MARKER.fullmatch(str(block.lines[0]))
        return None if match is None else int(match.group(1))

    retained_regions: set[int] = set()
    present_loop_ids: set[int] = set()

    def discover_control(block: Any) -> None:
        region = scheduled_region(block)
        if region is not None:
            retained_regions.add(region)
        if isinstance(block, SequenceBlock):
            for child in block.blocks:
                discover_control(child)
        elif isinstance(block, ConditionalBlock):
            discover_control(block.body)
            if block.orelse is not None:
                discover_control(block.orelse)
        elif isinstance(block, LoopBlock):
            induction = str(block.induction)
            if induction.startswith("iteration_"):
                try:
                    present_loop_ids.add(int(induction[len("iteration_"):]))
                except ValueError:
                    pass
            discover_control(block.body)
        elif isinstance(block, WhileBlock):
            if block.source_loop_node_id is not None:
                present_loop_ids.add(int(block.source_loop_node_id))
            discover_control(block.condition)
            discover_control(block.body)
        elif isinstance(block, CallBlock):
            discover_control(block.callee)
        elif isinstance(block, StateMachineTick):
            for _value, body in block.cases:
                discover_control(body)
            if block.default is not None:
                discover_control(block.default)

    discover_control(control.root)
    # Callsites lexically owned by a conditional arm (see
    # ConditionalBlock.body_callsite_ids): scheduled inside that arm by
    # `rebuild`, never anchored on a later region or left trailing.
    arm_callsite_candidates: set[int] = set()

    def discover_arm_callsites(block: Any) -> None:
        if isinstance(block, SequenceBlock):
            for child in block.blocks:
                discover_arm_callsites(child)
        elif isinstance(block, ConditionalBlock):
            arm_callsite_candidates.update(map(int, block.body_callsite_ids))
            arm_callsite_candidates.update(map(int, block.orelse_callsite_ids))
            discover_arm_callsites(block.body)
            if block.orelse is not None:
                discover_arm_callsites(block.orelse)
        elif isinstance(block, (LoopBlock, WhileBlock)):
            discover_arm_callsites(block.body)
        elif isinstance(block, CallBlock):
            discover_arm_callsites(block.callee)
        elif isinstance(block, StateMachineTick):
            for _value, body in block.cases:
                discover_arm_callsites(body)
            if block.default is not None:
                discover_arm_callsites(block.default)

    discover_arm_callsites(control.root)
    # Callsites the shell already placed at their authored position (a
    # ``__plan_callsite_N__`` statement in the tree) are not scheduled
    # again: authored placement wins over "before the next retained region".
    placed_callsites: set[int] = set()

    def discover_placed(block: Any) -> None:
        if isinstance(block, StatementBlock):
            for line in block.lines:
                match = _CALLSITE_MARKER.fullmatch(str(line))
                if match is not None:
                    placed_callsites.add(int(match.group(1)))
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                discover_placed(child)
        elif isinstance(block, ConditionalBlock):
            discover_placed(block.body)
            if block.orelse is not None:
                discover_placed(block.orelse)
        elif isinstance(block, (LoopBlock, WhileBlock)):
            if isinstance(block, WhileBlock):
                discover_placed(block.condition)
            discover_placed(block.body)
        elif isinstance(block, CallBlock):
            discover_placed(block.callee)
        elif isinstance(block, StateMachineTick):
            # A tick's arms hold the calls its dispatch selects; a marker in
            # an arm is placed there, not "before the next region".
            for _value, body in block.cases:
                discover_placed(body)
            if block.default is not None:
                discover_placed(block.default)

    discover_placed(control.root)
    arm_owned_callsites: set[int] = set()
    calls_before: dict[int, list[int]] = {}
    replaced_projection_regions: set[int] = set()
    pending: list[int] = []
    last_call: PlanCall | None = None

    def is_call_projection_region(
        closure: "PlanClosure", call: PlanCall,
    ) -> bool:
        """Whether ``closure`` only unpacks outputs already bound by ``call``."""

        result_ids = set(bindings[int(call.callsite_id)][1])
        if not result_ids:
            return False
        projected_ids: set[int] = set()
        for line in closure.items:
            opcode = str(getattr(line, "opcode", "")).casefold()
            if opcode == "const":
                continue
            inputs = tuple(map(int, getattr(line, "inputs", ())))
            outputs = tuple(map(int, getattr(line, "outputs", ())))
            if (
                opcode != "indexed"
                or not inputs
                or inputs[0] != int(call.callsite_id)
                or not outputs
                or not set(outputs).issubset(result_ids)
            ):
                return False
            projected_ids.update(outputs)
        return projected_ids == result_ids

    for item in hierarchy_plan.items:
        if isinstance(item, PlanCall):
            last_call = item
            if int(item.callsite_id) in placed_callsites:
                continue
            if int(item.callsite_id) in arm_callsite_candidates:
                arm_owned_callsites.add(int(item.callsite_id))
                continue
            pending.append(int(item.callsite_id))
            continue
        if not (
            isinstance(item, PlanClosure)
            and item.name.startswith("region_")
        ):
            continue
        region = int(item.name.split("_", 1)[1])
        if region in retained_regions and pending:
            calls_before.setdefault(region, []).extend(pending)
            pending = []
        if (
            region in retained_regions
            and last_call is not None
            and is_call_projection_region(item, last_call)
        ):
            # A region that only unpacks a call's bound results is the
            # call's projection, whether the call was placed lexically or
            # is scheduled here; its work is the call itself.
            replaced_projection_regions.add(region)
            calls_before.setdefault(region, [])
    trailing_at_loop: dict[int, list[int]] = {}
    trailing_at_root: list[int] = []
    for callsite_id in pending:
        item = planned_calls[callsite_id]
        loop_id = next((
            int(candidate)
            for candidate in reversed(item.enclosing_loop_ids)
            if int(candidate) in present_loop_ids
        ), None)
        if loop_id is None:
            trailing_at_root.append(callsite_id)
        else:
            trailing_at_loop.setdefault(loop_id, []).append(callsite_id)

    def marker(callsite_ids: Iterable[int]) -> StatementBlock:
        return StatementBlock(tuple(
            f"__plan_callsite_{int(callsite_id)}__"
            for callsite_id in callsite_ids
        ))

    def sequence(*blocks: Any) -> SequenceBlock:
        return SequenceBlock(tuple(
            child
            for block in blocks
            for child in (
                block.blocks if isinstance(block, SequenceBlock) else (block,)
            )
        ))

    def append_before_terminal(body: Any, trailing_marker: Any) -> SequenceBlock:
        """Append a trailing call marker ahead of the body's terminal edge.

        A loop body that ends in an unconditional ``break``/``continue``/
        ``return`` has no reachable position after that edge; a marker
        appended there is dead code and the call it stands for never runs.
        """

        blocks = list(sequence(body).blocks)
        index = len(blocks)
        while (
            index > 0
            and isinstance(blocks[index - 1], LoopControlBlock)
            and blocks[index - 1].predicate_value_id is None
            and blocks[index - 1].predicate_expression is None
        ):
            index -= 1
        blocks.insert(index, trailing_marker)
        return SequenceBlock(tuple(blocks))

    def rebuild(block: Any) -> Any:
        region = scheduled_region(block)
        if region is not None:
            before = calls_before.get(region, ())
            if region in replaced_projection_regions:
                return marker(before)
            return block if not before else sequence(marker(before), block)
        if isinstance(block, SequenceBlock):
            return sequence(*(rebuild(child) for child in block.blocks))
        if isinstance(block, LoopBlock):
            rebuilt_body = rebuild(block.body)
            induction = str(block.induction)
            loop_id = (
                int(induction[len("iteration_"):])
                if induction.startswith("iteration_")
                and induction[len("iteration_"):].isdigit()
                else None
            )
            trailing = trailing_at_loop.get(loop_id, ())
            if trailing:
                rebuilt_body = append_before_terminal(
                    rebuilt_body, marker(trailing)
                )
            return replace(block, body=rebuilt_body)
        if isinstance(block, WhileBlock):
            rebuilt_condition = rebuild(block.condition)
            rebuilt_body = rebuild(block.body)
            trailing = trailing_at_loop.get(
                None if block.source_loop_node_id is None
                else int(block.source_loop_node_id),
                (),
            )
            if trailing:
                rebuilt_body = append_before_terminal(
                    rebuilt_body, marker(trailing)
                )
            return replace(
                block, condition=rebuilt_condition, body=rebuilt_body
            )
        if isinstance(block, ConditionalBlock):
            # Planned calls whose only lexical home is this arm (no region
            # of their own to anchor on) are scheduled at the head of the
            # arm, ahead of its regions and its return control.
            owned_body = tuple(
                callsite_id for callsite_id in block.body_callsite_ids
                if callsite_id in arm_owned_callsites
            )
            owned_else = tuple(
                callsite_id for callsite_id in block.orelse_callsite_ids
                if callsite_id in arm_owned_callsites
            )
            rebuilt_body = rebuild(block.body)
            if owned_body:
                rebuilt_body = sequence(marker(owned_body), rebuilt_body)
            rebuilt_else = (
                rebuild(block.orelse) if block.orelse is not None else None
            )
            if owned_else:
                rebuilt_else = sequence(
                    marker(owned_else),
                    rebuilt_else if rebuilt_else is not None
                    else SequenceBlock(()),
                )
            return replace(block, body=rebuilt_body, orelse=rebuilt_else)
        if isinstance(block, StateMachineTick):
            return replace(
                block,
                cases=tuple(
                    (value, rebuild(body)) for value, body in block.cases
                ),
                default=(
                    None if block.default is None else rebuild(block.default)
                ),
            )
        return block

    rebuilt_root = rebuild(control.root)
    if trailing_at_root:
        rebuilt_root = sequence(rebuilt_root, marker(trailing_at_root))
    rebuilt_control = replace(control, root=rebuilt_root)

    def produced_sequences(block: Any) -> set[int]:
        """Resident sequence arenas populated by one control subtree."""

        produced: set[int] = set()
        if isinstance(block, SequenceMutationBlock):
            produced.add(int(block.mutation.sequence_value_id))
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                produced.update(produced_sequences(child))
        elif isinstance(block, ConditionalBlock):
            produced.update(produced_sequences(block.body))
            if block.orelse is not None:
                produced.update(produced_sequences(block.orelse))
        elif isinstance(block, (LoopBlock, WhileBlock)):
            produced.update(
                int(mutation.sequence_value_id)
                for mutation in block.sequence_mutations
            )
            if isinstance(block, WhileBlock):
                produced.update(produced_sequences(block.condition))
            produced.update(produced_sequences(block.body))
        elif isinstance(block, CallBlock):
            produced.update(produced_sequences(block.callee))
        elif isinstance(block, StateMachineTick):
            for _value, body in block.cases:
                produced.update(produced_sequences(body))
            if block.default is not None:
                produced.update(produced_sequences(block.default))
        return produced


    def expression_value_ids(expression: Any) -> set[int]:
        """Every value id a control expression reads, transitively.

        A predicate such as ``not ok`` is a control expression over the
        call result ``ok``; the block's own predicate id is the negation
        node, which nothing publishes.  The dependency is on the operands.
        """

        found: set[int] = set()
        pending = [expression]
        while pending:
            current = pending.pop()
            if current is None:
                continue
            if getattr(current, "value_id", None) is not None:
                found.add(int(current.value_id))
            pending.extend(getattr(current, "operands", ()) or ())
        return found

    def dependency_signature(
        block: Any,
    ) -> tuple[tuple[int, ...], tuple[int, ...]] | None:
        """Return exact straight-line inputs and publications for a block."""

        if isinstance(block, LoopControlBlock):
            # A tuple return may be the sole consumer of a trailing source
            # call. Keep its value dependencies visible so that call is
            # scheduled before the function exit, not in unreachable code.
            inputs = {int(value_id) for value_id in block.return_value_ids
                      if value_id is not None}
            if block.predicate_value_id is not None:
                inputs.add(int(block.predicate_value_id))
            inputs |= expression_value_ids(block.predicate_expression)
            return tuple(sorted(inputs)), ()
        if isinstance(block, StatementBlock):
            region_index = scheduled_region(block)
            if region_index is not None:
                return (region_dependency_signatures or {}).get(
                    region_index,
                    region_signatures.get(region_index, ((), ())),
                )
            callsites = []
            for line in block.lines:
                match = _CALLSITE_MARKER.fullmatch(str(line))
                if match is None:
                    return None
                callsites.append(int(match.group(1)))
            if not callsites:
                return None
            # A call publishes its bound results and every projection the
            # caller takes of them (``metrics.mass_err``, ``result[1]``):
            # those projections are what regions, loops and effects consume.
            # Without them a loop reading the record's fields carried no
            # dependency on the call and floated ahead of it.
            return (
                tuple(dict.fromkeys(
                    value_id
                    for callsite_id in callsites
                    for value_id in bindings.get(callsite_id, ((), ()))[0]
                )),
                tuple(dict.fromkeys((
                    *(
                        value_id
                        for callsite_id in callsites
                        for value_id in bindings.get(callsite_id, ((), ()))[1]
                    ),
                    *(
                        int(value_id)
                        for callsite_id in callsites
                        for value_id in (callsite_projection_ids or {}).get(
                            int(callsite_id), ()
                        )
                    ),
                ))),
            )
        if isinstance(block, SequenceMutationBlock):
            mutation = block.mutation
            consumed_ids: set[int] = set(map(int, mutation.argument_value_ids))
            if mutation.operator == "replace":
                # Copy reads the source arena at this lexical point. Its id
                # is not an SSA result produced by a future append or clear.
                consumed_ids.difference_update(map(int, mutation.argument_value_ids))
            consumed_ids |= expression_value_ids(mutation.predicate_expression)
            for argument_expression in mutation.argument_expressions:
                consumed_ids |= expression_value_ids(argument_expression)
            return (
                tuple(sorted(consumed_ids)),
                (
                    # A display member append publishes its sequence only;
                    # its ``effect_node_id`` is the member it reads.
                    *(
                        (int(mutation.effect_node_id),)
                        if mutation.display_member is None else ()
                    ),
                    int(mutation.sequence_value_id),
                ),
            )
        if isinstance(block, ScalarFieldWriteBlock):
            return (tuple(sorted(expression_value_ids(block.value_expression))),
                    (int(block.effect_node_id),))
        if isinstance(block, SequenceQueryBlock):
            return (
                tuple(dict.fromkeys((
                    # A resident arena is storage, not a value defined by
                    # whichever mutation next mentions its id. In particular
                    # the first read must not depend on a later clear. A
                    # generator query has a separate, explicit producer.
                    *((int(block.sequence_value_id),)
                      if block.producer_loop_node_id is not None else ()),
                    *(
                        () if block.default_value_id is None
                        else (int(block.default_value_id),)
                    ),
                    *map(int, block.reduction_prefix_value_ids),
                    *map(int, block.reduction_suffix_value_ids),
                    # A keyed query reads its keys (``d.get(i % 3, 0)``,
                    # scratch c202: the lookup was scheduled before the
                    # region computing ``i % 3`` and read it undefined).
                    *map(int, block.key_value_ids),
                ))),
                tuple(dict.fromkeys((
                    int(block.result_value_id),
                    *map(int, block.result_alias_ids),
                    *map(int, block.result_member_ids),
                ))),
            )
        if isinstance(block, ConditionalBlock):
            # Keep the branch atomic, but expose its external dependencies.
            # Otherwise an overlaid region used as a call anchor can strand
            # that call after a branch which already consumes its result.
            consumed: set[int] = {int(block.predicate_value_id)}
            consumed |= expression_value_ids(block.predicate_expression)
            produced: set[int] = set()

            def collect_arm(candidate: Any) -> bool:
                if isinstance(candidate, SequenceBlock):
                    return all(collect_arm(child) for child in candidate.blocks)
                signature = dependency_signature(candidate)
                if signature is None:
                    return False
                consumed.update(map(int, signature[0]))
                produced.update(map(int, signature[1]))
                return True

            if not collect_arm(block.body) or (
                block.orelse is not None and not collect_arm(block.orelse)
            ):
                return None
            # Arm-local values do not become unconditional publications.
            # Only the control IR's explicit merges cross this boundary.
            aliases = (*block.carried_aliases, *block.carried_sequence_aliases)
            consumed.update(int(value_id)
                            for yes, no, _result in block.result_aliases
                            for value_id in (yes, no))
            external = consumed - produced
            external.add(int(block.predicate_value_id))
            external |= expression_value_ids(block.predicate_expression)
            external.update(int(initial) for _yes, _no, initial, _merged in aliases)
            return (
                tuple(sorted(external)),
                tuple(sorted({
                    *(int(merged) for _yes, _no, _initial, merged in aliases),
                    *(int(merged) for _yes, _no, merged in block.result_aliases),
                })),
            )
        if isinstance(block, (LoopBlock, WhileBlock)):
            # A loop is one scheduling unit, but it is not dependency-free.
            # Pure regions immediately outside it can define loop-invariant
            # values consumed anywhere in its body (row-neighbour indices in
            # the fluid stencil are the minimal example).  Hiding those feeds
            # lets the stable outer schedule leave their producer after the
            # loop, creating uses which no definition dominates.
            consumed: set[int] = set()
            produced: set[int] = set(produced_sequences(block))

            def loop_offset_starts(loop: Any) -> set[int]:
                # Program: ``r0 = xs0[-1]; xs0.pop(0)``, then ``for k, x in
                # enumerate(ys, n % 4 + 4)`` and ``len(xs0)`` (fuzz p91_9).
                # Wrong record: the loop body's ``enumerate_start`` reads the
                # start value, but the loop's signature did not list it, so
                # the start's region was ordered after the loop (62 for
                # 2389).  Rule: a loop reads the start of every counter its
                # induction offsets (``induction_offsets``).
                if not isinstance(loop, LoopBlock):
                    return set()
                targets = {
                    int(target_id)
                    for _iterable_id, target_id, induction, projection
                    in control.projected_iterable_bindings
                    if induction == loop.induction and projection == "induction"
                }
                return {
                    int(start_id)
                    for target_id, start_id in control.induction_offsets
                    if int(target_id) in targets
                }

            consumed.update(loop_offset_starts(block))

            def collect_surface(candidate: Any) -> None:
                if isinstance(candidate, StatementBlock):
                    region_index = scheduled_region(candidate)
                    signature = (
                        None if region_index is None
                        else (region_dependency_signatures or {}).get(
                            region_index,
                            region_signatures.get(region_index, ((), ())),
                        )
                    )
                    if signature is not None:
                        consumed.update(map(int, signature[0]))
                        produced.update(map(int, signature[1]))
                    return
                if isinstance(candidate, SequenceBlock):
                    for child in candidate.blocks:
                        collect_surface(child)
                    return
                if isinstance(candidate, ConditionalBlock):
                    if candidate.predicate_value_id is not None:
                        consumed.add(int(candidate.predicate_value_id))
                    collect_surface(candidate.body)
                    if candidate.orelse is not None:
                        collect_surface(candidate.orelse)
                    return
                if isinstance(candidate, (LoopBlock, WhileBlock)):
                    if isinstance(candidate, WhileBlock):
                        consumed.add(int(candidate.predicate_value_id))
                        collect_surface(candidate.condition)
                    consumed.update(loop_offset_starts(candidate))
                    collect_surface(candidate.body)
                    return
                signature = dependency_signature(candidate)
                if signature is not None:
                    consumed.update(map(int, signature[0]))
                    produced.update(map(int, signature[1]))

            if isinstance(block, WhileBlock):
                consumed.add(int(block.predicate_value_id))
                collect_surface(block.condition)
            collect_surface(block.body)
            consumed.update(
                int(initial_id)
                for _updated_id, initial_id in block.carried_aliases
            )
            produced.update(
                int(port_id) for port_id, _initial, _updated
                in block.result_ports
            )
            return (
                tuple(sorted(consumed - produced)),
                tuple(sorted(produced)),
            )
        return None

    def hierarchy_statement_position(block: Any) -> int | None:
        """Return this scheduled statement's position in the hierarchy."""

        if not isinstance(block, StatementBlock):
            return None
        region_index = scheduled_region(block)
        if region_index is not None:
            if region_index in pure_region_indices:
                # Pure arithmetic already has complete SSA dependencies.
                # Its old flat rank is not an effect-order constraint: keeping
                # it can force an early rejection predicate after accept work.
                return None
            return hierarchy_statement_rank.get(("region", region_index))
        callsites = []
        for line in block.lines:
            match = _CALLSITE_MARKER.fullmatch(str(line))
            if match is None:
                return None
            callsites.append(int(match.group(1)))
        # A source-placed call already has an execution position in Control
        # IR. The flat hierarchy can put an effect-only call after a read
        # because no result dependency connects them; that rank must not
        # override the authored placement during the stable sort below.
        positions = tuple(
            hierarchy_statement_rank[("call", callsite_id)]
            for callsite_id in callsites
            if ("call", callsite_id) in hierarchy_statement_rank
            and callsite_id not in placed_callsites
        )
        return min(positions) if positions else None

    def has_terminal_edge(block: Any) -> bool:
        """Does this subtree cut the current lexical fallthrough edge?"""
        if isinstance(block, LoopControlBlock):
            return True
        if isinstance(block, SequenceBlock):
            return any(has_terminal_edge(child) for child in block.blocks)
        if isinstance(block, ConditionalBlock):
            return has_terminal_edge(block.body) or (
                block.orelse is not None and has_terminal_edge(block.orelse)
            )
        # A nested loop owns its break/continue edges; they do not cut this
        # enclosing sequence's fallthrough. Callee exits likewise stay local.
        return False

    def dependency_order(block: Any) -> Any:
        """Stable-toposort exact structural dependencies in one lexical arm.

        Unrecognised control is a hard barrier.  Recognised effects may move
        only when an explicit value dependency proves the lexical order
        impossible; otherwise the stable queue retains authored order.
        """

        if isinstance(block, SequenceBlock):
            children = [dependency_order(child) for child in block.blocks]
            ordered: list[Any] = []
            run: list[Any] = []

            def flush() -> None:
                if len(run) < 2:
                    ordered.extend(run)
                    run.clear()
                    return
                signatures = [dependency_signature(child) for child in run]
                producers: dict[int, list[int]] = {}
                for position, signature in enumerate(signatures):
                    assert signature is not None
                    for output in signature[1]:
                        producers.setdefault(int(output), []).append(position)
                dependencies: list[set[int]] = []
                dependency_reasons: dict[tuple[int, int], list[Any]] = {}
                # Program: ``r = []; if n < 0: return r; r.append(2 * n)``
                # (c62).  Wrong record: the append publishes its arena id as
                # a value, the guarded ``return r`` reads that id, and the
                # later-producer rule below pulled the append (and its
                # operand region) ahead of the guard, so ``n < 0`` returned
                # ``[2n]``.  Rule: an arena is storage born at its
                # descriptor, never a value a later mutation produces; its
                # order is the RAW/WAR/WAW accesses (``sequence_accesses``,
                # where a return reads the arenas it returns).
                mutated_arenas = {
                    int(child.mutation.sequence_value_id)
                    for child in run
                    if isinstance(child, SequenceMutationBlock)
                }
                # Program: ``xs = [5, n]; xs.extend([7, 8])`` (scratch
                # c151).  Wrong record: placed by start column, the call
                # preceded the display that is its argument, and the arena
                # rule above refused the later display as a producer, so
                # ``extend`` copied an unborn arena.  Rule: a display's clear
                # and member appends are the arena's BIRTH, not a later
                # mutation of it; a reader of the arena follows its birth.
                births: dict[int, list[int]] = {}
                for position, child in enumerate(run):
                    # Program: ``xs = [4, 1] + [n, 2]`` beside a tuple
                    # unpack on the return line (fuzzer p5_2).  Wrong
                    # record: the concat's region resets and refills its
                    # result -- that arena's birth -- but only display
                    # blocks counted as births, so WAR ordered the concat
                    # after the read of ``xs[2]`` that consumes it: a cycle.
                    # Rule: a region whose recorded operations reset or fill
                    # an arena is that arena's birth.
                    recorded_region = (
                        scheduled_region(child)
                        if isinstance(child, StatementBlock) else None
                    )
                    if recorded_region is not None:
                        for kind, arguments in _region_table_operations(
                            recorded_region,
                            table_region_operations,
                            table_region_post_operations,
                        ):
                            if str(kind) in {"reset", "fill"}:
                                births.setdefault(
                                    int(arguments[0]), []
                                ).append(position)
                    if not isinstance(child, SequenceMutationBlock):
                        continue
                    mutation = child.mutation
                    if mutation.display_member is not None or (
                        str(mutation.operator) == "clear"
                        and int(mutation.effect_node_id)
                        == int(mutation.sequence_value_id)
                    ):
                        births.setdefault(
                            int(mutation.sequence_value_id), []
                        ).append(position)

                def require(
                    current: int, prerequisite: int, reason: Any,
                ) -> None:
                    dependencies[current].add(prerequisite)
                    dependency_reasons.setdefault(
                        (int(prerequisite), int(current)), []
                    ).append(reason)
                for position, signature in enumerate(signatures):
                    assert signature is not None
                    required: set[int] = set()
                    for feed in signature[0]:
                        candidates = producers.get(int(feed), ())
                        prior = [candidate for candidate in candidates if candidate < position]
                        later = [candidate for candidate in candidates if candidate > position]
                        if prior:
                            prerequisite = max(prior)
                            required.add(prerequisite)
                            dependency_reasons.setdefault(
                                (int(prerequisite), int(position)), []
                            ).append(("value", int(feed)))
                        elif later and int(feed) not in mutated_arenas:
                            prerequisite = min(later)
                            required.add(prerequisite)
                            dependency_reasons.setdefault(
                                (int(prerequisite), int(position)), []
                            ).append(("value", int(feed)))
                        for birth in births.get(int(feed), ()):
                            if birth > position:
                                required.add(birth)
                                dependency_reasons.setdefault(
                                    (int(birth), int(position)), []
                                ).append(("birth", int(feed)))
                    dependencies.append(required)
                hierarchy_positions = [
                    hierarchy_statement_position(child) for child in run
                ]
                # The hierarchy is a flat data/effect plan; a lexical terminal
                # is a control boundary absent from that flat ordering. Chaining
                # ranked statements across one can order fallthrough work before
                # the guarded return/break/continue that precedes it. Combined
                # with the terminal guard below, that manufactures a cycle even
                # though the two orders describe mutually exclusive paths.
                # Preserve hierarchy precedence independently on each side.
                terminal_segments: list[int] = []
                terminal_segment = 0
                for child in run:
                    terminal_segments.append(terminal_segment)
                    if has_terminal_edge(child):
                        terminal_segment += 1
                ranked_by_segment: dict[int, list[tuple[int, int]]] = {}
                for position, hierarchy_position in enumerate(hierarchy_positions):
                    if hierarchy_position is None:
                        continue
                    ranked_by_segment.setdefault(
                        terminal_segments[position], []
                    ).append((int(hierarchy_position), position))
                for ranked in ranked_by_segment.values():
                    ranked.sort()
                    for (_prior_rank, prior), (_rank, current) in zip(
                        ranked, ranked[1:]
                    ):
                        require(current, prior, (
                            "hierarchy", int(_prior_rank), int(_rank)
                        ))

                # The arenas some statement of this run reads or writes; a
                # call's arguments among them are its writes (below).
                run_arenas: set[int] = set()

                def sequence_accesses(candidate, include_calls=True, calls=True):
                    """One arena's reads and its writes, told apart.

                    These used to be one set, and every pair of accesses to an
                    arena was then ordered -- including READ AFTER READ, which
                    needs no ordering at all because two reads of the same
                    sequence commute.  Those spurious edges are not merely
                    conservative: chained with a real dependency they close
                    cycles that do not exist, and the scheduler then refuses a
                    whole program with "control effect order conflicts with
                    value dependencies".  One such refusal chained three pure
                    readers of one arena into a path from a placed callsite to
                    the loop's own control block, which the terminal-guard rule
                    below independently orders the other way.

                    A mutation writes its sequence; a ``replace`` also READS the
                    values it writes in; a query reads.
                    """
                    reads, writes = set(), set()
                    # Program: ``d = {1: 5, 2: n, 3: 8}; del d[2]`` placed as
                    # its own control effect, then ``len(d) * 10 + n`` (fuzz
                    # p106_43).  Wrong record: ``len(d)`` is emitted where
                    # its value is first consumed (``sequence_length_values``),
                    # so the region consuming it showed no read of ``d``, and
                    # the delete was scheduled after it (len 3 for 2).  Rule:
                    # a statement consuming a sequence's length reads that
                    # sequence.
                    if isinstance(candidate, StatementBlock) and sequence_length_values:
                        length_signature = dependency_signature(candidate)
                        if length_signature is not None:
                            reads.update(
                                int(sequence_length_values[int(value_id)])
                                for value_id in length_signature[0]
                                if int(value_id) in sequence_length_values
                            )
                    # PROGRAM SHAPE: a region ``StatementBlock`` whose effects
                    # (append/extend/store/pack_bits/lookup ...) are recorded
                    # in table_region_operations / _post_operations.  WRONG
                    # RECORD (before): it yielded no arena access, so no
                    # RAW/WAR/WAW edge ordered it against a mutation/query of
                    # the same arena.  RULE NOW HOLDING: the region's accesses
                    # are those of its recorded operations, by each
                    # operation's own sequence id.
                    if isinstance(candidate, StatementBlock):
                        recorded_region = scheduled_region(candidate)
                        if recorded_region is not None:
                            for kind, arguments in _region_table_operations(
                                recorded_region,
                                table_region_operations,
                                table_region_post_operations,
                            ):
                                operation_reads, operation_writes = (
                                    _table_operation_sequence_accesses(
                                        kind, arguments
                                    )
                                )
                                reads |= operation_reads
                                writes |= operation_writes
                    # Program: ``xs2 = [n, 6]; swap(xs2)``, then ``xs2[0]``
                    # after list and table work (fuzzer p92_28).  Wrong
                    # record: a ``__plan_callsite_N__`` statement yielded no
                    # arena access, so no edge ordered the region reading
                    # ``xs2[0]`` after the call that rewrote it, and an
                    # unrelated value edge placed that read first (-329 for
                    # -239).  Rule: a call writes every arena of this run it
                    # receives as an argument -- its callee may store into
                    # that storage, and the call boundary is where the
                    # caller sees it.  Where the callee is known
                    # (``callsite_stored_argument_ids``) a call writes exactly
                    # the arguments it stores into, as a mutation does, and
                    # the others not at all.  Where it is not known, every
                    # arena argument is a MAY write, which takes no
                    # write-after-read edge (``call_writes`` below).
                    if calls and isinstance(candidate, StatementBlock):
                        for line in candidate.lines:
                            match = _CALLSITE_MARKER.fullmatch(str(line))
                            if match is None:
                                continue
                            callsite_id = int(match.group(1))
                            stored = (callsite_stored_argument_ids or {}).get(
                                callsite_id
                            )
                            # Every arena argument is READ by the call: a
                            # whole-bound ``head(xs)`` before ``swap(xs)``
                            # must not move after it (c384 once ``xs`` stopped
                            # binding by member).
                            reads.update(
                                int(value_id)
                                for value_id in bindings.get(
                                    callsite_id, ((), ())
                                )[0]
                                if int(value_id) in run_arenas
                            )
                            if stored is None and not include_calls:
                                continue
                            writes.update(
                                int(value_id)
                                for value_id in bindings.get(
                                    callsite_id, ((), ())
                                )[0]
                                if int(value_id) in run_arenas
                                and (stored is None or int(value_id) in stored)
                            )
                    if isinstance(candidate, SequenceMutationBlock):
                        writes.add(int(candidate.mutation.sequence_value_id))
                        if candidate.mutation.operator == "replace":
                            reads.update(map(int, candidate.mutation.argument_value_ids))
                    elif isinstance(candidate, SequenceQueryBlock):
                        if candidate.producer_loop_node_id is None:
                            reads.add(int(candidate.sequence_value_id))
                    elif isinstance(candidate, LoopControlBlock):
                        # A return hands its arenas to the caller as they
                        # stand at this edge.
                        reads.update(
                            int(value_id)
                            for value_id in candidate.return_value_ids
                            if value_id is not None
                            and int(value_id) in mutated_arenas
                        )
                    for mutation in getattr(candidate, 'sequence_mutations', ()):
                        writes.add(int(mutation.sequence_value_id))
                    for child in getattr(candidate, 'blocks', ()):
                        child_reads, child_writes = sequence_accesses(
                            child, include_calls, calls
                        )
                        reads |= child_reads
                        writes |= child_writes
                    for field in ('condition', 'body', 'orelse', 'callee'):
                        child = getattr(candidate, field, None)
                        if child is not None:
                            child_reads, child_writes = sequence_accesses(
                                child, include_calls, calls
                            )
                            reads |= child_reads
                            writes |= child_writes
                    return reads, writes

                for child in run:
                    child_reads, child_writes = sequence_accesses(child)
                    run_arenas.update(child_reads | child_writes)

                # Program: ``d = {1: n, 2: 4}; del d[1]`` beside list work,
                # then ``int(1 in d)`` (fuzzer p81_13).  Wrong record: the
                # deletion rides as a pre-operation of the region after it
                # in value order, and the membership query that follows it
                # in source was placed before that region (WAR by run
                # position), so the query found the deleted key (1397 for
                # 397; clean audit).  Rule: a query of a table whose result
                # follows a deletion of that table reads after the region
                # that carries the deletion.  Where the region also needs
                # the query, the order is a cycle and lowering refuses.
                # Program: ``d = {}; for i in range(4): d[i % 2] =
                # d.get(i % 2, 0) + n`` (the plan's C4; the loop unrolls).
                # Wrong record: the same for a keyed store: all four
                # ``get``s ran before the first store (-33 for -66; clean
                # audit).  Rule: a keyed store is such a write too.
                # The run position of such a query says nothing about it, so
                # it takes no write-after-read edge to that carrier either.
                follows: set[tuple[int, int]] = set()
                deletions_by_position: dict[int, list[tuple[int, int]]] = {}
                for position, child in enumerate(run):
                    if not isinstance(child, StatementBlock):
                        continue
                    recorded_region = scheduled_region(child)
                    if recorded_region is None:
                        continue
                    for kind, arguments in _region_table_operations(
                        recorded_region,
                        table_region_operations,
                        table_region_post_operations,
                    ):
                        if kind not in {"store", "delete"}:
                            continue
                        _operation_reads, operation_writes = (
                            _table_operation_sequence_accesses(kind, arguments)
                        )
                        deletions_by_position.setdefault(position, []).extend(
                            (int(arguments[0]), int(sequence_id))
                            for sequence_id in operation_writes
                        )
                for position, child in enumerate(run):
                    if not (
                        isinstance(child, SequenceQueryBlock)
                        and child.producer_loop_node_id is None
                    ):
                        continue
                    for carrier, deletions in deletions_by_position.items():
                        if carrier != position and any(
                            sequence_id == int(child.sequence_value_id)
                            and effect_id < int(child.result_value_id)
                            for effect_id, sequence_id in deletions
                        ):
                            follows.add((position, carrier))
                            require(position, carrier, (
                                "sequence_delete_raw",
                                int(child.sequence_value_id),
                            ))

                # Three of the four dependence kinds, and not the fourth:
                #   RAW  a read after a write   -- last_write
                #   WAR  a write after a read   -- last_access
                #   WAW  a write after a write  -- last_access
                #   RAR  a read after a read    -- NONE, reads commute
                last_access: dict[int, int] = {}
                last_write: dict[int, int] = {}
                reads_since_write: dict[int, list[int]] = {}
                last_terminal = None
                terminal_guard_candidates: list[tuple[int, int]] = []
                for position, child in enumerate(run):
                    reads, writes = sequence_accesses(child)
                    # Program: ``xs = [n, 4]; ys = [0]; grow(ys, 2)``, then
                    # ``head(xs) + width(ys) * 10 + ys[-1]`` (c193).  A call
                    # write is "the callee MAY store here": a read-only
                    # ``width(ys)`` inside the return region that reads
                    # ``ys[-1]`` would take a write-after-read edge to that
                    # region while the region consumes its result -- a cycle
                    # the program does not have.  Rule: a call's arena write
                    # follows the arena's last write and precedes its later
                    # readers (RAW), but takes no WAR edge from an earlier
                    # reader.
                    call_writes = writes - sequence_accesses(
                        child, include_calls=False
                    )[1]
                    # A call fed an arena VALUE a later statement of the run
                    # produces already follows that producer by its value
                    # edge; ordering it as an accessor by run position would
                    # close a cycle with that edge (a generator call placed
                    # ahead of the loop filling its argument).
                    direct_reads, direct_writes = sequence_accesses(
                        child, calls=False
                    )
                    late_fed = {
                        arena
                        for arena in (reads | writes) - (direct_reads | direct_writes)
                        if any(
                            producer > position
                            for producer in producers.get(int(arena), ())
                        )
                    }
                    reads -= late_fed
                    writes -= late_fed
                    call_writes -= late_fed
                    # Program: ``if n > 6: t = [n, 3] else: t = [8, n]``,
                    # ``t.append(6)``, then a comprehension (fuzz p85_1).
                    # Wrong record: the join's birth (clear, then one
                    # append per member) sat after the append in the run,
                    # and the write-after-write rule ordered the birth after
                    # it, so the clear erased the append (len 2 for 3;
                    # clean audit).  Rule: an access of an arena follows its
                    # birth wherever the birth sits in the run, and a birth
                    # takes no write-after-access edge from an access it
                    # precedes.
                    for arena in reads | writes:
                        if position in births.get(int(arena), ()):
                            continue
                        for birth in births.get(int(arena), ()):
                            if birth > position:
                                require(position, birth, (
                                    "sequence_birth", int(arena)
                                ))
                    for arena in reads:
                        if arena in last_write:
                            require(position, last_write[arena], (
                                "sequence_raw", int(arena)
                            ))
                    for arena in writes:
                        if arena in last_access:
                            access_kind = (
                                "sequence_waw"
                                if arena in last_write
                                and last_write[arena] == last_access[arena]
                                else "sequence_war"
                            )
                            # Program: ``xs = [5, 7] + [n, 7]`` (fuzzer
                            # p3_54).  Wrong record: the concat region (placed
                            # at the ``+``, which starts at its left operand)
                            # read ``[n, 7]`` before that display's member
                            # append, so WAR ordered the reader before the
                            # birth while the birth rule above ordered it
                            # after: a cycle.  Rule: a birth is not a write
                            # after a read -- nothing existed to read -- so
                            # an earlier reader takes the birth edge only.
                            if (
                                access_kind == "sequence_war"
                                and position in births.get(int(arena), ())
                            ):
                                continue
                            if access_kind == "sequence_war" and arena in call_writes:
                                if arena in last_write:
                                    require(position, last_write[arena], (
                                        "sequence_waw", int(arena)
                                    ))
                                continue
                            prior = last_access[arena]
                            if (
                                position in births.get(int(arena), ())
                                and prior not in births.get(int(arena), ())
                            ):
                                continue
                            if (prior, position) in follows:
                                # The latest reader follows this write; the
                                # latest reader that does not, else the last
                                # write, precedes it.
                                prior = max((
                                    reader
                                    for reader in reads_since_write.get(arena, ())
                                    if (reader, position) not in follows
                                ), default=last_write.get(arena))
                                if prior is None:
                                    continue
                            require(position, prior, (
                                access_kind, int(arena)
                            ))
                    for arena in reads | writes:
                        last_access[arena] = position
                    for arena in reads - writes:
                        reads_since_write.setdefault(arena, []).append(position)
                    for arena in writes:
                        last_write[arena] = position
                        reads_since_write[arena] = []
                    # A source-placed call following a guarded continue/return
                    # must not execute on that terminal edge while waiting for
                    # the guard's numerical producer.
                    # The real dt step's no-save ConditionalBlock contains a
                    # return. Treating only bare LoopControlBlocks as terminals
                    # chained accept region27 -> early region14 by flat rank;
                    # its dependency cone pulled the accept PI ahead of no-save.
                    # That return cuts fallthrough just as a bare edge does.
                    if has_terminal_edge(child):
                        last_terminal = position
                    elif isinstance(child, StatementBlock) and last_terminal is not None:
                        if any(
                            (match := _CALLSITE_MARKER.fullmatch(str(line)))
                            and int(match.group(1)) in placed_callsites
                            for line in child.lines
                        ):
                            terminal_guard_candidates.append((
                                position, last_terminal,
                            ))

                def depends_on(current: int, prerequisite: int) -> bool:
                    """Whether exact value/effect edges already order these."""

                    pending = list(dependencies[current])
                    visited: set[int] = set()
                    while pending:
                        candidate = pending.pop()
                        if candidate == prerequisite:
                            return True
                        if candidate in visited:
                            continue
                        visited.add(candidate)
                        pending.extend(dependencies[candidate])
                    return False

                for position, terminal in terminal_guard_candidates:
                    # ``if self.excludes(node): return False`` retained its
                    # predicate PlanCall marker after the ConditionalBlock.
                    # The call is nevertheless in the guard's exact value
                    # dependency cone, so it is evaluation of that guard,
                    # not fallthrough work that must remain after its return.
                    # Preserve the terminal edge for every call outside that
                    # cone; never add its reverse on top of an authoritative
                    # value/effect path.
                    if not depends_on(terminal, position):
                        require(position, terminal, ("terminal_guard",))

                placed, active = set(), set()

                def schedule(position):
                    if position in placed:
                        return
                    if position in active:
                        def label(index):
                            child = run[index]
                            if isinstance(child, StatementBlock):
                                call_ids = tuple(
                                    int(match.group(1))
                                    for line in child.lines
                                    if (match := _CALLSITE_MARKER.fullmatch(str(line)))
                                )
                                if call_ids and len(call_ids) == len(child.lines):
                                    return tuple(
                                        (
                                            "PlanCall", callsite_id,
                                            planned_calls[callsite_id].callee.name
                                            if callsite_id in planned_calls else None,
                                        )
                                        for callsite_id in call_ids
                                    )
                            return (
                                child.lines if isinstance(child, StatementBlock)
                                else (type(child).__name__,
                                      getattr(child, 'source_node_id', None),
                                      getattr(child, 'source_call_node_id', None),
                                      getattr(child, 'predicate_value_id', None),
                                      getattr(child, 'action', None),
                                      getattr(child, 'site_node_id', None))
                            )
                        raise ValueError(
                            'control effect order conflicts with value dependencies: '
                            f'cycle={[(i, label(i), sorted(dependencies[i]), signatures[i]) for i in sorted(active)]}; '
                            f'edges={[(prerequisite, current, tuple(reasons)) for (prerequisite, current), reasons in sorted(dependency_reasons.items()) if prerequisite in active and current in active]}'
                        )
                    active.add(position)
                    for dependency in sorted(dependencies[position]):
                        schedule(dependency)
                    active.remove(position)
                    placed.add(position)
                    ordered.append(run[position])

                # Pull prerequisites immediately before their first consumer.
                # Choosing any ready node instead could postpone a conditional
                # append past a later truth read, or run accept calls before a
                # rejection guard whose predicate was not available yet.
                for position in range(len(run)):
                    schedule(position)
                run.clear()

            for child in children:
                if dependency_signature(child) is None:
                    flush()
                    ordered.append(child)
                else:
                    run.append(child)
            flush()
            return replace(block, blocks=tuple(ordered))
        if isinstance(block, ConditionalBlock):
            return replace(
                block,
                body=dependency_order(block.body),
                orelse=(
                    None if block.orelse is None
                    else dependency_order(block.orelse)
                ),
            )
        if isinstance(block, LoopBlock):
            return replace(block, body=dependency_order(block.body))
        if isinstance(block, WhileBlock):
            return replace(
                block,
                condition=dependency_order(block.condition),
                body=dependency_order(block.body),
            )
        if isinstance(block, CallBlock):
            return replace(block, callee=dependency_order(block.callee))
        if isinstance(block, StateMachineTick):
            return replace(
                block,
                cases=tuple(
                    (value, dependency_order(body))
                    for value, body in block.cases
                ),
                default=(
                    None if block.default is None
                    else dependency_order(block.default)
                ),
            )
        return block

    return replace(
        rebuilt_control,
        root=dependency_order(rebuilt_control.root),
    ), bindings


def debug_region_output_loads(function: Function, tag: str) -> None:
    """Env-gated probe: report region-output loads whose result id drifted.

    ``TURING_DEBUG_OUTPUT_LOADS=<function-name-substring>`` prints, at each
    call site that invokes this, every ``Load`` stamped with a
    ``source_output_id`` whose result id no longer equals that stamp.
    """

    wanted = os.environ.get("TURING_DEBUG_OUTPUT_LOADS")
    if not wanted or wanted not in str(function.name):
        return
    drifted = [
        (block_name, int(instruction.attributes.get("source_output_id")),
         int(instruction.res.id))
        for block_name, block in function.blocks.items()
        for instruction in block.instrs
        if instruction.res is not None
        and instruction.attributes
        and instruction.attributes.get("source_output_id") is not None
        and int(instruction.attributes.get("source_output_id"))
        != int(instruction.res.id)
    ]
    print(
        f"DEBUG-OUTPUT-LOADS [{tag}] {function.name}: drifted={drifted}",
        file=sys.stderr, flush=True,
    )
    if tag != os.environ.get("TURING_DEBUG_OUTPUT_LOADS_TRACE_AT", "shell-after-sections"):
        return
    import traceback as _traceback

    def _where() -> str:
        frames = _traceback.extract_stack(limit=9)[:-2]
        return " <- ".join(f"{f.name}:{f.lineno}" for f in reversed(frames))

    class _TracedValue(SSAValue):
        @property
        def id(self):  # type: ignore[override]
            return self.__dict__["id"]

        @id.setter
        def id(self, new_id):
            old_id = self.__dict__.get("id")
            if old_id is not None and int(old_id) != int(new_id):
                print(f"DEBUG-OUTPUT-LOADS-TRACE {function.name}: value id "
                      f"{old_id} -> {new_id} at {_where()}", file=sys.stderr, flush=True)
            self.__dict__["id"] = new_id

    class _TracedInstr(Instr):
        @property
        def res(self):  # type: ignore[override]
            return self.__dict__["res"]

        @res.setter
        def res(self, value):
            old = self.__dict__.get("res")
            if old is not None and value is not None and int(old.id) != int(value.id):
                print(f"DEBUG-OUTPUT-LOADS-TRACE {function.name}: res object "
                      f"{int(old.id)} -> {int(value.id)} (source_output_id="
                      f"{(self.attributes or {}).get('source_output_id')}) at {_where()}",
                      file=sys.stderr, flush=True)
            self.__dict__["res"] = value

    for block in function.blocks.values():
        for instruction in block.instrs:
            if (
                instruction.res is not None
                and str(instruction.op) == "Load"
                and instruction.attributes
                and instruction.attributes.get("source_output_id") is not None
            ):
                instruction.res.__class__ = _TracedValue
                instruction.__class__ = _TracedInstr


def _materialize_control_constants(
    function: Function,
    constant_values: Mapping[int, Any],
    *,
    value_dtypes: Mapping[int, str],
    constant_source_cells: Mapping[int, tuple[Any, ...]] | None = None,
) -> Function:
    """Materialize authored graph literals instead of exposing ABI inputs.

    Numerical regions legitimately receive literals as call arguments.  The
    enclosing control function owns those literals and must produce them
    before making the region call.  Keeping them in its signature would make
    every source constant an invented caller-supplied parameter.
    """

    if not function.blocks or not constant_values:
        return function
    # Call-frame legalization runs after control lowering and can expose a
    # literal identity again after its first materialization was dead-code
    # eliminated.  Preserve the exact specialized source ledger so that late
    # recovery never has to guess through a transformed ProcessGraph.
    function.metadata["authored_constant_values"] = tuple(
        (int(value_id), copy.deepcopy(literal))
        for value_id, literal in sorted(constant_values.items())
    )
    sequence_table = function.metadata.get("sequence_table")
    resident_sequence_ids = {
        int(sequence_id)
        for sequence_id in getattr(sequence_table, "sequences", {})
    }
    argument_ids = {int(argument.id) for argument in function.args}
    existing: dict[int, Instr] = {}
    for block in function.blocks.values():
        retained = []
        for instruction in block.instrs:
            value_id = (
                None if instruction.res is None
                else int(instruction.res.id)
            )
            if (
                value_id in constant_values
                and str(instruction.op).casefold() in {
                    "const", "constant", "nonevalue",
                }
            ):
                # A list/tuple literal which already owns a resident sequence
                # descriptor is storage, not a second scalar constant.  Its
                # exact elements are installed by the sequence initializer;
                # retaining ``Const(value=[])`` under the arena's identity
                # gives one value two incompatible physical producers.
                if value_id in resident_sequence_ids:
                    continue
                literal = constant_values[value_id]
                matches = (
                    str(instruction.op).casefold() == "nonevalue"
                    and literal is None
                    and not instruction.attributes
                ) or (
                    str(instruction.op).casefold() in {"const", "constant"}
                    and instruction.attributes.get("value") == literal
                )
                if not matches:
                    raise ValueError(
                        "canonical constant identity has conflicting literals: "
                        f"value={value_id}"
                    )
                if literal is None and str(instruction.op).casefold() != "nonevalue":
                    instruction.op = "NoneValue"
                    instruction.attributes = {}
                    if instruction.res is not None:
                        instruction.res.dtype = "none"
                elif instruction.res is not None:
                    # Program: an imported module integer such as U64_MAX
                    # reaches a control Const after scalar_fact_dtype has
                    # selected uint64, while the resident graph Const still
                    # carries the provisional int64.  Wrong record: the
                    # materialization and SSA_VALUE then preserve that stale
                    # dtype, so the exact integer cannot reach the native
                    # operator.  Rule: this materialization consumes the
                    # already-published value_dtypes decision for its exact
                    # identity before either concordance row is written.
                    selected_dtype = value_dtypes.get(value_id)
                    if selected_dtype not in (None, "", "unknown"):
                        instruction.res.dtype = str(selected_dtype)
                existing.setdefault(value_id, instruction)
                continue
            retained.append(instruction)
        block.instrs[:] = retained
    materialized_ids = tuple(sorted({
        int(value_id)
        for value_id in constant_values
        if (
            int(value_id) not in resident_sequence_ids
            and (
                int(value_id) in argument_ids
                or int(value_id) in existing
            )
        )
    }))
    if not materialized_ids:
        return function
    entry_label, entry = next(iter(function.blocks.items()))
    materializations = []
    for value_id in materialized_ids:
        resident = existing.get(value_id)
        if resident is not None:
            materializations.append(resident)
            continue
        literal = constant_values[value_id]
        is_none = literal is None
        if isinstance(literal, bool):
            authored_dtype = "bool"
        elif type(literal) is int:
            from ..transmogrifier.dtype_layout import python_int_literal_dtype

            authored_dtype = python_int_literal_dtype(literal)
        elif isinstance(literal, float):
            authored_dtype = "float64"
        else:
            authored_dtype = None
        materializations.append(Instr(
            "NoneValue" if is_none else "Const", [],
            SSAValue(
                value_id,
                # A proven dtype wins; otherwise the authored literal's own
                # Python type is exact.  ``return True`` had no proven dtype
                # and was declared float64 here, which only a later pass's
                # re-inference from the literal used to hide.
                dtype=(
                    "none" if is_none
                    else str(
                        value_dtypes.get(value_id)
                        or authored_dtype
                    )
                ),
                accounting={"authored_constant": True},
            ),
            attributes={} if is_none else {
                "value": copy.deepcopy(literal)
            },
        ))
    entry.instrs[0:0] = materializations
    from .identity_concordance import current_identity_book

    book = current_identity_book()
    scope = str(
        function.metadata.get("tensor_shape_concordance_scope")
        or function.name
    )
    prior_geometry = book.latest_ref(
        SSA_BLOCK_GEOMETRY,
        (scope, str(function.name), str(entry_label)),
    )
    for instruction in materializations:
        value_id = int(instruction.res.id)
        sources = tuple(cell for cell in (
            book.latest_ref(SSA_VALUE, (scope, value_id)),
            prior_geometry,
            *tuple((constant_source_cells or {}).get(value_id, ())),
        ) if cell is not None)
        if not sources:
            # Standalone IR utilities have no source/concordance owner to
            # publish against.  The materialization remains an ordinary IR
            # rewrite there; a source compile reaches this point with either
            # the value cell or the geometry it is revising.
            continue
        materialization_cell = book.post(
            SSA_CONSTANT_MATERIALIZATION,
            (scope, str(function.name), str(entry_label), value_id),
            (
                str(instruction.op),
                str(instruction.res.dtype),
                repr((instruction.attributes or {}).get("value")),
            ),
            stage=CONTROL_SSA_FINISH,
            provenance=Derived(sources),
            mode=Mode.CONCORD,
        )
        # Program: repro_opt_tuple.py (``return None``) -- value 6, a
        # NoneValue.  Wrong record: the ``ssa_value`` row was adopted with
        # dtype None from the graph object, while this pass materialized the
        # resident as "none" (here and in the retained-instruction rewrite
        # above) and posted only the materialization row, so row and resident
        # disagreed and settlement refused.  Rule: the pass that makes a
        # transformation posts it at that moment, derived from the cells it
        # read; a resident's dtype is a view of its ``ssa_value`` row -- a
        # REVISE of the existing row, a post when the id has none.
        _row = (scope, value_id)
        _shape = tuple(instruction.res.shape or ())
        physical = (
            {
                "physical_dtype": str(instruction.res.dtype),
                "storage": "scalar",
                "rank": 0,
                "arena": False,
            }
            if type((instruction.attributes or {}).get("value")) is int
            else KEEP_PHYSICAL
        )
        publication_sources = tuple(dict.fromkeys((
            *sources, materialization_cell,
        )))
        if book.latest_ref(SSA_VALUE, _row) is None:
            book.post(
                SSA_VALUE, _row,
                SSAValueFact(
                    instruction.res.dtype, _shape,
                    SSAValueOrigin.ADOPTED_GRAPH_ID,
                    **({
                        "physical_dtype": str(instruction.res.dtype),
                        "storage": "scalar", "rank": 0,
                    } if physical is not KEEP_PHYSICAL else {}),
                ),
                stage=CONTROL_SSA_FINISH,
                provenance=Derived(publication_sources),
                mode=Mode.REVISE,
            )
        else:
            from .ssa_record_return_state import revise_ssa_value

            revise_ssa_value(
                function, value_id, dtype=instruction.res.dtype,
                shape=_shape, stage=CONTROL_SSA_FINISH,
                sources=publication_sources,
                physical=physical,
                book=book,
            )
    materialized = set(materialized_ids)
    function.args = [
        argument for argument in function.args
        if int(argument.id) not in materialized
    ]
    return function


def _install_loop_owned_table_queries(
    control: ControlProgram,
    table_lookups: Iterable[tuple[int, int | tuple[int, ...], int]],
    loop_owners: Mapping[int, int],
    *,
    excluded_result_ids: Iterable[int] = (),
    globally_mutated_sequence_ids: Iterable[int] = (),
) -> tuple[ControlProgram, tuple[int, ...], tuple[tuple[int, str], ...]]:
    """Place keyed reads only under their exact retained source loop.

    The graph identifies both the lookup's key value and the comprehension
    node which defines that key.  A retained LoopBlock carries that same
    source node id.  This is sufficient to place a pure read after the loop's
    projected target load, provided the queried sequence is not mutated in the
    loop.  Missing/ambiguous owners are left untouched and reported; numeric
    proximity is never used as a scheduling surrogate.
    """

    excluded = set(map(int, excluded_result_ids))
    globally_mutated = set(map(int, globally_mutated_sequence_ids))
    by_loop: dict[int, list[tuple[int, tuple[int, ...], int]]] = {}
    for result_id, query_ids, sequence_id in table_lookups:
        result_id = int(result_id)
        if result_id in excluded:
            continue
        keys = tuple(map(
            int, query_ids if isinstance(query_ids, tuple) else (query_ids,),
        ))
        owners = {
            int(loop_owners[key]) for key in keys if key in loop_owners
        }
        if len(owners) != 1 or any(key not in loop_owners for key in keys):
            continue
        owner, = owners
        by_loop.setdefault(owner, []).append((
            result_id, keys, int(sequence_id),
        ))

    installed: list[int] = []
    refusals: list[tuple[int, str]] = []

    def mutated_sequences(block: ControlBlock) -> set[int]:
        found: set[int] = set()
        if isinstance(block, SequenceMutationBlock):
            found.add(int(block.mutation.sequence_value_id))
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                found.update(mutated_sequences(child))
        elif isinstance(block, ConditionalBlock):
            found.update(mutated_sequences(block.body))
            if block.orelse is not None:
                found.update(mutated_sequences(block.orelse))
        elif isinstance(block, LoopBlock):
            found.update(
                int(item.sequence_value_id) for item in block.sequence_mutations
            )
            found.update(mutated_sequences(block.body))
        elif isinstance(block, WhileBlock):
            found.update(
                int(item.sequence_value_id) for item in block.sequence_mutations
            )
            found.update(mutated_sequences(block.condition))
            found.update(mutated_sequences(block.body))
        elif isinstance(block, CallBlock):
            found.update(mutated_sequences(block.callee))
        elif isinstance(block, ParallelDeployment):
            for lane in block.lanes:
                found.update(mutated_sequences(lane))
        elif isinstance(block, StateMachineTick):
            for _case, body in block.cases:
                found.update(mutated_sequences(body))
            if block.default is not None:
                found.update(mutated_sequences(block.default))
        return found

    def rewrite(block: ControlBlock) -> ControlBlock:
        if isinstance(block, SequenceBlock):
            return replace(block, blocks=tuple(map(rewrite, block.blocks)))
        if isinstance(block, ConditionalBlock):
            return replace(
                block,
                body=rewrite(block.body),
                orelse=(
                    None if block.orelse is None else rewrite(block.orelse)
                ),
            )
        if isinstance(block, LoopBlock):
            body = rewrite(block.body)
            owned = tuple(by_loop.get(int(
                block.source_loop_node_id
                if block.source_loop_node_id is not None else -1
            ), ()))
            if not owned:
                return replace(block, body=body)
            mutated = mutated_sequences(body) | {
                int(item.sequence_value_id) for item in block.sequence_mutations
            } | globally_mutated
            queries = []
            for result_id, keys, sequence_id in owned:
                if sequence_id in mutated:
                    refusals.append((
                        result_id,
                        f"sequence {sequence_id} is mutable in its owner loop",
                    ))
                    continue
                queries.append(SequenceQueryBlock(
                    result_value_id=result_id,
                    sequence_value_id=sequence_id,
                    operation="lookup",
                    source_call_node_id=result_id,
                    producer_loop_node_id=block.source_loop_node_id,
                    key_value_ids=keys,
                ))
                installed.append(result_id)
            if not queries:
                return replace(block, body=body)
            body_blocks = (
                body.blocks if isinstance(body, SequenceBlock) else (body,)
            )
            return replace(
                block,
                body=SequenceBlock((*queries, *body_blocks)),
            )
        if isinstance(block, WhileBlock):
            return replace(
                block,
                condition=rewrite(block.condition),
                body=rewrite(block.body),
            )
        if isinstance(block, CallBlock):
            return replace(block, callee=rewrite(block.callee))
        if isinstance(block, ParallelDeployment):
            return replace(block, lanes=tuple(map(rewrite, block.lanes)))
        if isinstance(block, StateMachineTick):
            return replace(
                block,
                cases=tuple(
                    (case, rewrite(body)) for case, body in block.cases
                ),
                default=(
                    None if block.default is None else rewrite(block.default)
                ),
            )
        return block

    return (
        replace(control, root=rewrite(control.root)),
        tuple(dict.fromkeys(installed)),
        tuple(refusals),
    )


def _concord_region_feed_consumers(
    lexical_read_scope: Any,
    control_scope: Any,
    region_index: int,
    instructions: Any,
    feeds: Any,
) -> None:
    """Commit, per region feed, the graph consumers inside the region.

    Page ``region_feed_consumer`` row ``(control scope, region index, feed
    id)`` holds the region instructions' result ids (their graph consumer
    nodes) that read the feed.  Structure only: which binding each of those
    operands read is the base fact ``lexical_read_binding``.
    """

    if lexical_read_scope is None:
        return
    from .identity_concordance import current_identity_book

    book = current_identity_book()
    feed_ids = set(map(int, feeds))
    consumers: dict[int, list[int]] = {}
    for instruction in instructions:
        if instruction.res is None:
            continue
        for argument in instruction.args:
            if int(argument.id) in feed_ids:
                consumers.setdefault(int(argument.id), []).append(
                    int(instruction.res.id)
                )
    scope = tuple(lexical_read_scope)
    for feed, nodes in consumers.items():
        # DERIVED(the ``consumer_operand`` cells when the planner declared
        # them, else the consumers' and the feed's canonical cells).
        sources = []
        for node in dict.fromkeys(nodes):
            for cell in (
                (
                    book.latest_ref(
                        book.registry.pages["consumer_operand"],
                        (scope, int(node), int(feed)),
                    )
                    if "consumer_operand" in book.registry.pages else None
                ),
                book.latest_ref(CANONICAL_VALUE, (scope, int(node))),
            ):
                if cell is not None and cell not in sources:
                    sources.append(cell)
        feed_cell = book.latest_ref(CANONICAL_VALUE, (scope, int(feed)))
        if feed_cell is not None and feed_cell not in sources:
            sources.append(feed_cell)
        _post_derived_or_raw(
            book, REGION_FEED_CONSUMER,
            (str(control_scope), int(region_index), feed),
            tuple(dict.fromkeys(nodes)), tuple(sources),
            stage=CONTROL_SSA_REGION, mode=Mode.CONCORD,
        )


def _split_region_captures_by_binding(
    lexical_read_scope: Any,
    control_scope: Any,
    region_index: int,
    instructions: Any,
    captures: tuple[int, ...],
) -> tuple[int, ...]:
    """Give each binding a region reads through one captured value its formal.

    ``second = value`` then ``second = second + value`` inside a loop is one
    captured value read as two bindings; only ``second`` is loop-carried, so
    the two operands see different values at the call.  A region formal per
    value id cannot carry both.  When the book attributes a capture's
    operand slots (``lexical_read_binding`` at ``(read scope, instruction
    result, role, ordinal)``) to more than one binding and a loop carries
    that value under one of them (``loop_carried_binding``), every binding
    after the first gets a fresh formal and its slots are rewired to it.

    Page ``region_capture_binding`` row ``(control scope, region, formal)``
    -> ``(source value id, binding)`` records each split formal, the first
    binding's included; the region feed reads it by that binding.  Returns
    the captures with the new formals appended after their source.
    """

    if lexical_read_scope is None:
        return captures
    from ..common.tensors.topological_reducer import _operand_positions
    from .identity_concordance import current_identity_book

    book = current_identity_book()
    read_page = book.page("lexical_read_binding")
    carried_page = book.page("loop_carried_binding")
    carried_initials: dict[int, set[str]] = {}
    for row in carried_page.scope_rows(tuple(lexical_read_scope)):
        if len(row) == 4:
            carried_initials.setdefault(int(row[3]), set()).update(
                map(str, carried_page.latest(row) or ())
            )
    wanted = {int(value_id) for value_id in captures} & set(carried_initials)
    if not wanted:
        return captures
    slots: dict[int, list[tuple[Any, int, Any]]] = {}
    for instruction in instructions:
        if instruction.res is None:
            continue
        roles = list(getattr(instruction, "arg_roles", ()) or ())
        if len(roles) != len(instruction.args):
            continue
        for index, (role, ordinal, argument) in enumerate(_operand_positions(
            zip(instruction.args, roles)
        )):
            if int(argument.id) not in wanted:
                continue
            binding = read_page.latest((
                tuple(lexical_read_scope), int(instruction.res.id),
                role, ordinal,
            ))
            slots.setdefault(int(argument.id), []).append(
                (instruction, index, binding)
            )
    expanded: list[int] = []
    scope = tuple(lexical_read_scope)
    for value_id in map(int, captures):
        expanded.append(value_id)
        reads = slots.get(value_id)
        if not reads:
            continue
        bindings = list(dict.fromkeys(binding for *_slot, binding in reads))
        if (
            len(bindings) < 2
            or None in bindings
            or not set(bindings) & carried_initials[value_id]
        ):
            continue
        source_cell = book.latest_ref(CANONICAL_VALUE, (scope, value_id))

        def read_cells(binding: Any) -> tuple:
            """The ``lexical_read_binding`` cells of the slots that read
            ``binding``."""

            found = []
            for instruction, index, read in reads:
                if read != binding:
                    continue
                roles = list(getattr(instruction, "arg_roles", ()) or ())
                positions = list(_operand_positions(
                    zip(instruction.args, roles)
                ))
                role, ordinal, _argument = positions[index]
                cell = book.latest_ref(
                    LEXICAL_READ_BINDING,
                    (scope, int(instruction.res.id), role, ordinal),
                )
                if cell is not None and cell not in found:
                    found.append(cell)
            return tuple(found)

        # DERIVED(the ``lexical_read_binding`` cells of the first binding's
        # slots, the source's canonical cell).
        _post_derived_or_raw(
            book, REGION_CAPTURE_BINDING,
            (str(control_scope), int(region_index), value_id),
            (value_id, str(bindings[0])),
            (*read_cells(bindings[0]), source_cell),
            stage=CONTROL_SSA_REGION, mode=Mode.CONCORD,
        )
        for binding in bindings[1:]:
            binding_cells = read_cells(binding)
            # The split formal is a NOVEL mint: REGION_FORMAL_SPLIT from the
            # binding's read cells and the source's canonical cell.
            source_value = next(
                instruction.args[index]
                for instruction, index, read in reads if read == binding
            )
            formal_id = _mint_ssa_id(
                book, str(control_scope), REGION_FORMAL_SPLIT,
                (*binding_cells, source_cell),
                dtype=source_value.dtype, shape=tuple(source_value.shape or ()),
                stage=CONTROL_SSA_REGION,
            )
            for instruction, index, read in reads:
                if read != binding:
                    continue
                source = instruction.args[index]
                instruction.args[index] = SSAValue(
                    formal_id,
                    dtype=source.dtype,
                    shape=source.shape,
                    device=getattr(source, "device", None),
                )
            _post_derived_or_raw(
                book, REGION_CAPTURE_BINDING,
                (str(control_scope), int(region_index), formal_id),
                (value_id, str(binding)),
                (
                    *binding_cells, source_cell,
                    book.latest_ref(SSA_VALUE, (str(control_scope), formal_id)),
                ),
                stage=CONTROL_SSA_REGION, mode=Mode.CONCORD,
            )
            expanded.append(formal_id)
    return tuple(expanded)


def lower_control_sections_to_ssa(
    control: ControlProgram,
    *,
    hierarchy_plan: PlanClosure | None = None,
    value_concordance: IdentityPage | None = None,
    control_name: str = "planned_control",
    identity_table: Mapping[str, tuple[int, ...]] | None = None,
    function_outputs: tuple[str, ...] = (),
    function_parameters: tuple[str, ...] = (),
    lexical_read_scope: Any = None,
    planning_scope: Any = None,
    source_value_descriptions: Mapping[int, Mapping[str, Any]] | None = None,
    shape_scope: Any = None,
    value_dtypes: Mapping[int, str] | None = None,
    value_shapes: Mapping[int, tuple[int, ...]] | None = None,
    constant_values: Mapping[int, Any] | None = None,
    constant_source_cells: Mapping[int, tuple[Any, ...]] | None = None,
    required_output_value_ids: tuple[int, ...] = (),
    region_output_value_ids: Mapping[int, tuple[int, ...]] | None = None,
    record_field_write_value_ids: tuple[int, ...] = (),
    self_value_id: int | None = None,
    field_ops: tuple[tuple[str, int, int], ...] = (),
    field_write_state_cells: tuple[Any, ...] = (),
    field_const_sources: Mapping[int, Any] | None = None,
    field_count: int = 0,
    field_names: tuple[str, ...] = (),
    record_identity: str | None = None,
    record_field_dtypes: Mapping[str, str] | None = None,
    record_field_contracts: Mapping[str, Mapping[str, Any]] | None = None,
    record_field_mutability: Mapping[str, bool] | None = None,
    sequence_initializations: tuple[tuple[int, str, int], ...] = (),
    field_aliases: tuple[tuple[int, int], ...] = (),
    sequence_declarations: tuple[tuple[int, str, int, bool], ...] = (),
    sequence_capacity_sources: tuple[tuple[int, int], ...] = (),
    sequence_column_dtypes: Mapping[int, tuple[str, ...]] | None = None,
    sequence_record_identities: Mapping[int, str] | None = None,
    sequence_child_table_layouts: Mapping[
        int, tuple[int, tuple[str, ...], tuple[int, ...], bool]
    ] | None = None,
    sequence_row_record_slots: Mapping[
        int, tuple[tuple[int, str, int], ...]
    ] | None = None,
    callsite_projection_ids: Mapping[int, tuple[int, ...]] | None = None,
    callsite_stored_argument_ids: Mapping[int, frozenset[int]] | None = None,
    source_sequence_ids: tuple[int, ...] = (),
    dynamic_sequence_ids: tuple[int, ...] = (),
    sequence_memberships: tuple[
        tuple[int, int | tuple[int, ...], int, bool], ...
    ] = (),
    table_lookups: tuple[tuple[int, int | tuple[int, ...], int], ...] = (),
    table_lookup_loop_owners: Mapping[int, int] | None = None,
    table_lookup_defaults: dict[int, int | float] | None = None,
    table_lookup_required_ids: frozenset[int] = frozenset(),
    table_stores: tuple[
        tuple[int, int | tuple[int, ...], int, int], ...
    ] = (),
    table_deletions: tuple[
        tuple[int, int | tuple[int, ...], int | None, str], ...
    ] = (),
    retained_sequence_ids: tuple[int, ...] = (),
    nested_sequence_ids: tuple[int, ...] = (),
    nested_tensor_sequence_ids: tuple[int, ...] = (),
    joined_sequence_ids: tuple[int, ...] = (),
    joined_singleton_values: Mapping[int, int] | None = None,
    nested_record_fields: tuple[tuple[int, str, int], ...] = (),
    sequence_augassigns: tuple[tuple[int, int, int], ...] = (),
    sequence_concats: tuple[
        tuple[int, int, int, str, int | None, int | None], ...
    ] = (),
    sequence_append_fills: tuple[
        tuple[int, int, int | float | bool | None, int, int], ...
    ] = (),
    sequence_append_slices: tuple[
        tuple[int, int, int, int, int, int], ...
    ] = (),
    sequence_bit_packs: tuple[
        tuple[int, int, int, tuple[int, ...]], ...
    ] = (),
    sequence_prepends: tuple[tuple[int, int, int, int, int], ...] = (),
    sequence_prepend_packed_calls: tuple[
        tuple[int, int, int, int, int, int, int], ...
    ] = (),
    sequence_inplace_bit_pack_calls: tuple[
        tuple[int, int, int, int, int], ...
    ] = (),
    sequence_row_operations: tuple[tuple[Any, ...], ...] = (),
    sequence_read_before_effects: tuple[tuple[int, int], ...] = (),
    nested_row_projections: tuple[tuple[int, int, int, str], ...] = (),
    sequence_length_values: Mapping[int, int] | None = None,
    string_table: Any = None,
    tensor_ssa_reference: Any = None,
    resolved_sequence_schemas: Mapping[int, ResolvedSequenceSchema] | None = None,
    progress: Callable[[str], None] | None = None,
    parameter_value_abi: Mapping[str, Any] | None = None,
    parameter_record_abi: Mapping[str, Any] | None = None,
    native_object_context: Any = None,
    native_object_module: Any = None,
    native_object_value_ids: Iterable[int] = (),
    native_object_collections: Mapping[int, Mapping[str, Any]] | None = None,
    native_object_type_tests: Mapping[int, Mapping[str, Any]] | None = None,
    native_value_type_abi: Mapping[int, Any] | None = None,
    native_value_type_tests: Mapping[int, Mapping[str, Any]] | None = None,
) -> tuple[
    IRModule,
    tuple[SSALoweringShortfall, ...],
    dict[str, tuple[SSAValue, ...]],
]:
    """Lower one method's control + planner regions to SSA -- no numeric projection.

    This is the whole-object emission path.  A class method is control (field
    get/set, calls, returns) plus zero or more flat operator regions the planner
    already carved out.  Neither needs a fused numerical program: the regions
    come straight from the hierarchy plan via ``plan_region_to_ssa_instrs`` and
    the control program lowers directly.  Nothing here builds or validates a
    ``FusedProgram``, so a method with no numeric region (a void ``__init__``)
    and a method with one (``scale``'s ``mul``) both lower the same way.

    Returns the module, any shortfalls, and ``section_outputs`` -- the output
    SSA values of each region function, which the target must declare as that
    function's ``intent(out)`` dummies (a region has no explicit return).
    """
    region_writing_indices: set[int] = set()

    def report(message: str) -> None:
        if progress is not None:
            progress(f"ssa-section {control_name}: {message}")

    from .shell_telemetry import compile_substage
    compile_substage(f"SSA section {control_name}: survey values and sequence operations")
    report(
        f"start; regions={len(tuple(control.region_indices))} "
        f"hierarchy_items={len(tuple(getattr(hierarchy_plan, 'items', ()) or ()))}"
    )

    functions: dict[str, Function] = {}
    region_callees: dict[int, str] = {}
    region_signatures: dict[int, tuple[tuple[int, ...], tuple[int, ...]]] = {}
    region_feed_meta: dict[int, tuple[Meta, ...]] = {}
    region_value_meta: dict[int, Meta] = {}
    nested_row_target_ids: set[int] = set()
    selected_nested_sequence_ids: set[int] = set()
    variant_projected_target_ids: set[int] = set()
    region_array_feed_ids: dict[int, set[int]] = {}
    section_outputs: dict[str, tuple[SSAValue, ...]] = {}
    # One expansion per planned region, shared by every stage below, so all
    # stages agree on the ids a region defines (including the temporaries
    # its lowering coins, which are allocated plan-wide and never collide
    # with an authored id or with another region's temporaries).
    # Every value id this function already has in play, whether or not the
    # hierarchy plan mentions it (control-only graph values never do).
    known_value_ids: set[int] = {0}
    for history in (identity_table or {}).values():
        known_value_ids.update(int(value_id) for value_id in history)
    known_value_ids.update(map(int, control_dependency_value_ids(control)))
    known_value_ids.update(int(value_id) for _kind, value_id, _slot in field_ops)
    if self_value_id is not None:
        known_value_ids.add(int(self_value_id))
    known_value_ids.update(map(int, required_output_value_ids))
    known_value_ids.update(map(int, record_field_write_value_ids))
    for region_outputs in (region_output_value_ids or {}).values():
        known_value_ids.update(map(int, region_outputs))
    planning_aliases = (
        value_concordance.alias_bindings(control_name)
        if value_concordance is not None else {}
    )
    for mapping in (value_dtypes, value_shapes, constant_values,
                    planning_aliases, sequence_length_values,
                    joined_singleton_values, field_const_sources):
        known_value_ids.update(int(value_id) for value_id in (mapping or {}))
    known_value_ids.update(
        int(value_id) for value_id in planning_aliases.values()
    )
    known_value_ids.update(
        int(sequence_id)
        for sequence_id, _policy, _columns, _writable in sequence_declarations
    )
    known_value_ids.update(
        int(sequence_id) for sequence_id, _policy, _columns in sequence_initializations
    )
    for group in (table_lookups, table_stores, table_deletions, field_aliases,
                  sequence_memberships, nested_record_fields, sequence_augassigns):
        for entry in group:
            for leaf in entry:
                if isinstance(leaf, bool) or not isinstance(leaf, int):
                    continue
                known_value_ids.add(int(leaf))
    known_value_ids.update(map(int, (*retained_sequence_ids, *nested_sequence_ids,
                                     *joined_sequence_ids, *source_sequence_ids)))
    if os.environ.get("TURING_DEBUG_REGION_OUTPUTS"):
        print(f"DEBUG-REGION-WATERMARK {control_name}: known_max={max(known_value_ids)}",
              file=sys.stderr, flush=True)
    from .work_contract import active_contract
    expanded_plan_regions = (
        expand_plan_regions(
            hierarchy_plan,
            first_free_value_id=max(known_value_ids) + 1,
            function_scope=control_name,
            lexical_read_scope=lexical_read_scope,
            shape_scope=shape_scope,
            resident_limit=active_contract().ssa_resident_regions,
        )
        if hierarchy_plan is not None else {}
    )

    def region_instructions(closure: "PlanClosure") -> list[Instr]:
        key = (str(closure.name), int(closure.closure_id))
        if key not in expanded_plan_regions:
            raise RuntimeError(
                f"planned region {closure.name} (closure {closure.closure_id}) "
                "is not a top-level region of the hierarchy plan; its "
                "instructions have no plan-wide expansion to share"
            )
        return copy_region_instructions(expanded_plan_regions[key])

    def lexical_mapping_writes(block):
        mutations = list(getattr(block, "sequence_mutations", ()))
        if isinstance(block, SequenceMutationBlock):
            mutations.append(block.mutation)
        for mutation in mutations:
            if mutation.operator == "update" and mutation.argument_kind == "mapping_items":
                yield int(mutation.effect_node_id)
        for child in getattr(block, "blocks", ()):
            yield from lexical_mapping_writes(child)
        for name in ("condition", "body", "orelse", "callee"):
            child = getattr(block, name, None)
            if child is not None:
                yield from lexical_mapping_writes(child)

    lexical_mapping_write_ids = set(lexical_mapping_writes(control.root))
    shortfalls: list[SSALoweringShortfall] = []
    table_sequence_ids = {
        int(sequence_id)
        for sequence_id, policy, column_count, _writable
        in sequence_declarations
        if str(policy) == "unique" and int(column_count) > 1
    }
    declared_sequence_ids = {
        int(sequence_id)
        for sequence_id, _policy, _column_count, _writable
        in sequence_declarations
    }
    table_lookup_result_ids = {
        int(result_id) for result_id, _query_id, _sequence_id in table_lookups
    }
    table_store_effect_ids = {
        int(effect_id)
        for effect_id, _key_id, _value_id, _sequence_id in table_stores
    }
    sequence_fills = {
        int(sequence_id): (
            int(sequence_id),
            ast.literal_eval(str(policy).split(";", 1)[0].split("=", 1)[1]),
            int(str(policy).split("count=", 1)[1]),
        )
        for sequence_id, policy, _column_count in sequence_initializations
        if str(policy).startswith("fill=") and ";count=" in str(policy)
    }
    sequence_augment_by_result = {
        int(result_id): (int(destination_id), int(source_id))
        for result_id, destination_id, source_id in sequence_augassigns
    }
    sequence_concat_by_result = {
        int(result_id): (
            int(lhs_id), int(rhs_id), str(kind),
            None if lhs_scalar is None else int(lhs_scalar),
            None if rhs_scalar is None else int(rhs_scalar),
        )
        for (
            result_id, lhs_id, rhs_id, kind, lhs_scalar, rhs_scalar,
        ) in sequence_concats
    }
    sequence_append_fill_by_result = {
        int(result_id): (
            int(destination_id), literal, int(count_id)
        )
        for result_id, destination_id, literal, count_id, _source_result_id
        in sequence_append_fills
    }
    append_fill_source_result_ids = {
        int(source_result_id)
        for _result_id, _destination_id, _literal, _count_id, source_result_id
        in sequence_append_fills
    }
    sequence_append_slice_by_result = {
        int(result_id): (
            int(destination_id),
            int(source_id),
            None if lower_id is None else int(lower_id),
            None if upper_id is None else int(upper_id),
        )
        for (
            result_id, destination_id, source_id, lower_id, upper_id,
            _source_result_id,
        ) in sequence_append_slices
    }
    append_slice_source_result_ids = {
        int(source_result_id)
        for (
            _result_id, _destination_id, _source_id, _lower_id, _upper_id,
            source_result_id,
        ) in sequence_append_slices
        if source_result_id is not None
    }
    for (
        _result_id, destination_id, source_id, _lower_id, _upper_id, _slice_id,
    ) in sequence_append_slices:
        for value_id in (int(destination_id), int(source_id)):
            region_value_meta[value_id] = Meta((), "int")
            for history in (identity_table or {}).values():
                if value_id in tuple(map(int, history)):
                    for alias_id in history:
                        region_value_meta[int(alias_id)] = Meta((), "int")
    for (
        _result_id, _destination_id, _source_id, lower_id, upper_id, _slice_id,
    ) in sequence_append_slices:
        # Slice bounds are address arithmetic.  State that contract before the
        # numerical region producing e.g. ``i + width`` is typed, so its result
        # and operands remain integer across the region/helper boundary.
        # Whole-sequence extends carry no authored bounds (None).
        if lower_id is not None:
            region_value_meta[int(lower_id)] = Meta((), "int")
        if upper_id is not None:
            region_value_meta[int(upper_id)] = Meta((), "int")
    bit_pack_consumed_ids = {
        int(value_id)
        for _destination_id, _source_id, _width_id, consumed_ids
        in sequence_bit_packs
        for value_id in consumed_ids
    }
    for destination_id, source_id, width_id, _consumed_ids in sequence_bit_packs:
        region_value_meta[int(destination_id)] = Meta((), "int")
        region_value_meta[int(source_id)] = Meta((), "int")
        region_value_meta[int(width_id)] = Meta((), "int")
    prepend_by_result = {
        int(concat_result_id): (int(sequence_id), int(value_id))
        for (
            _store_result_id, sequence_id, value_id, concat_result_id,
            _tail_result_id,
        ) in sequence_prepends
    }
    prepend_store_result_ids = {
        int(store_result_id)
        for store_result_id, _sequence_id, _value_id, _concat_id, _tail_id
        in sequence_prepends
    }
    packed_concat_ids = {
        int(concat_result_id)
        for (
            _store_result_id, _destination_id, _prefix_id, _source_id,
            concat_result_id, _tail_result_id, _callsite_id,
        ) in sequence_prepend_packed_calls
    }
    packed_store_ids = {
        int(store_result_id)
        for (
            store_result_id, _destination_id, _prefix_id, _source_id,
            _concat_result_id, _tail_result_id, _callsite_id,
        ) in sequence_prepend_packed_calls
    }
    packed_by_concat = {
        int(concat_result_id): (
            int(destination_id), int(source_id), int(prefix_id),
            int(callsite_id),
        )
        for (
            _store_result_id, destination_id, prefix_id, source_id,
            concat_result_id, _tail_result_id, callsite_id,
        ) in sequence_prepend_packed_calls
    }
    packed_by_store = {
        int(store_result_id): (
            int(destination_id), int(source_id), int(prefix_id),
            int(callsite_id),
        )
        for (
            store_result_id, destination_id, prefix_id, source_id,
            _concat_result_id, _tail_result_id, callsite_id,
        ) in sequence_prepend_packed_calls
    }
    # A packed-call replacement supersedes the scalar-only prepend view of the
    # same authored concatenation/store pair.
    for concat_id in packed_concat_ids:
        prepend_by_result.pop(concat_id, None)
    prepend_store_result_ids.difference_update(packed_store_ids)
    inplace_pack_by_result = {
        int(result_id): (
            int(sequence_id), int(width), int(callee_reference),
            int(callsite_id),
        )
        for result_id, sequence_id, width, callee_reference, callsite_id
        in sequence_inplace_bit_pack_calls
    }
    for _result_id, sequence_id, _width, _reference, _callsite_id in (
        sequence_inplace_bit_pack_calls
    ):
        region_value_meta[int(sequence_id)] = Meta((), "int")
    for _result_id, destination_id, literal, _count_id, _source_id in (
        sequence_append_fills
    ):
        element_dtype = "int" if isinstance(literal, int) else "float64"
        destination_id = int(destination_id)
        region_value_meta[destination_id] = Meta((), element_dtype)
        for history in (identity_table or {}).values():
            if destination_id not in tuple(map(int, history)):
                continue
            for value_id in history:
                region_value_meta[int(value_id)] = Meta((), element_dtype)
    # Sequence replication is a structural memory contract.  Its destination
    # element and requested extent must agree in every numerical region and in
    # the control/helper function that surrounds those regions.
    for sequence_id, literal, count_id in sequence_fills.values():
        region_value_meta[int(count_id)] = Meta((), "int")
        if isinstance(literal, tuple):
            # A runtime member: the rows hold its class.
            member = region_value_meta.get(int(literal[1]))
            if member is not None:
                region_value_meta[int(sequence_id)] = Meta((), member.dtype)
            continue
        element_dtype = (
            "bool" if isinstance(literal, bool)
            else "int" if isinstance(literal, int)
            else "float64" if isinstance(literal, float)
            else "int64" if literal is None
            else "unknown"
        )
        region_value_meta[int(sequence_id)] = Meta((), element_dtype)
    for _iterable_id, target_id, _induction_name, projection in (
        control.projected_iterable_bindings
    ):
        if projection == "induction":
            region_value_meta[int(target_id)] = Meta((), "int")

    def queried_row_sequences(block: ControlBlock) -> set[int]:
        """Loop-local rows whose authored query requires sequence storage."""

        if isinstance(block, SequenceQueryBlock):
            return (
                {int(block.sequence_value_id)}
                if block.operation in {"length", "truth"} else set()
            )
        if isinstance(block, SequenceBlock):
            return set().union(*(
                queried_row_sequences(child) for child in block.blocks
            )) if block.blocks else set()
        if isinstance(block, ConditionalBlock):
            result = queried_row_sequences(block.body)
            if block.orelse is not None:
                result.update(queried_row_sequences(block.orelse))
            return result
        if isinstance(block, LoopBlock):
            return queried_row_sequences(block.body)
        if isinstance(block, WhileBlock):
            return (
                queried_row_sequences(block.condition)
                | queried_row_sequences(block.body)
            )
        if isinstance(block, CallBlock):
            return queried_row_sequences(block.callee)
        return set()

    queried_sequence_ids = queried_row_sequences(control.root)
    # Settle strict scalar roles across the complete method before constructing
    # any one region signature.  The same SSA identity can cross several
    # regions; whichever region proves it is an address index or predicate must
    # inform every caller/callee occurrence, independent of traversal order.
    if hierarchy_plan is not None:
        semantic_instructions: list[Instr] = []
        for planned in hierarchy_plan.items:
            if not (
                isinstance(planned, PlanClosure)
                and planned.name.startswith("region_")
            ):
                continue
            planned_instructions = region_instructions(planned)
            semantic_instructions.extend(planned_instructions)
            for instruction in planned_instructions:
                for value in (
                    *instruction.args,
                    *((instruction.res,) if instruction.res is not None else ()),
                ):
                    if str(value.dtype) in {"bool", "int", "int32", "int64"}:
                        region_value_meta[int(value.id)] = Meta(
                            tuple(value.shape), str(value.dtype)
                        )
        integer_ids = {
            int(argument.id)
            for instruction in semantic_instructions
            if instruction.op == "GetElementPtr"
            for argument in instruction.args[1:]
        }
        iterable_target_ids = {
            int(target_id)
            for _iterable_id, target_id, _induction
            in control.iterable_bindings
        }
        iterable_target_ids.update({
            int(target_id)
            for _iterable_id, target_id, _induction, projection
            in control.projected_iterable_bindings
            if projection != "induction"
        })
        # ``len(row)`` and ``bool(row)`` are direct structural evidence that
        # a loop target is a selected child row even when its body never
        # indexes the row.  The nested-table ABI already owns the child length
        # arena; admitting the target here lets control lowering bind that
        # exact row handle before emitting the query.
        nested_row_target_ids.update(
            iterable_target_ids.intersection(queried_sequence_ids)
        )
        nested_row_target_ids.update(
            int(instruction.args[0].id)
            for instruction in semantic_instructions
            if instruction.op in {"Indexed", "IndexedStore", "GetElementPtr"}
            and instruction.args
            and int(instruction.args[0].id) in iterable_target_ids
        )
        scalar_use_ids = {
            int(argument.id)
            for instruction in semantic_instructions
            for argument in (
                instruction.args[1:]
                if instruction.op in {
                    "Indexed", "IndexedStore", "GetElementPtr"
                }
                else instruction.args
            )
        }
        indexed_base_ids = {
            int(instruction.args[0].id)
            for instruction in semantic_instructions
            if instruction.op in {"Indexed", "IndexedStore", "GetElementPtr"}
            and instruction.args
        }
        statically_shaped_ids = {
            int(value_id)
            for value_id, meta in region_value_meta.items()
            if tuple(meta.shape or ())
        }
        statically_shaped_ids.update(
            int(value_id)
            for value_id, shape in dict(value_shapes or {}).items()
            if tuple(shape or ())
        )
        variant_projected_target_ids.update(
            target_id
            for target_id in nested_row_target_ids
            if target_id in scalar_use_ids
            and target_id not in statically_shaped_ids
        )
        # The same heterogeneous contract is required when source pursuit has
        # specialized away the owning loop and left its payload as a direct
        # method input.  Its uses name the candidates; the declared fact is
        # STORAGE IDENTITY: a candidate is a payload only when its
        # ``storage_root`` row reaches a formal's storage cell along DERIVED
        # edges (a view, index or alias of input storage).  ``m = x * 1.0``
        # is new storage (a PRODUCED root) and mints no row column; this
        # used to be decided by "no known shape yet", which classified it a
        # payload and left an unbound row formal (Woodshop ``_resolve_floor``:
        # ``velocity = momentum / mass; if velocity[2] < 0.0: momentum[2]``).
        from .identity_concordance import current_identity_book

        storage_book = current_identity_book()
        storage_scope = storage_book.mint_scope(
            f"storage_root:{control_name}", STORAGE_ROOT_STAGE,
        )
        storage_formals: dict[int, Any] = {}
        formal_names: dict[int, str] = {}
        for parameter_name in function_parameters:
            history = (identity_table or {}).get(str(parameter_name), ())
            if not history:
                continue
            formal_names[int(history[0])] = str(parameter_name)
            storage_formals[int(history[0])] = (
                None if lexical_read_scope is None
                else storage_book.latest_ref(
                    NAME_BINDING,
                    (lexical_read_scope, str(parameter_name), 0),
                )
            )
        if self_value_id is not None:
            storage_formals.setdefault(int(self_value_id), None)
            formal_names.setdefault(int(self_value_id), "self")
        # A formal-rooted candidate needs a row column only when its formal
        # is declared as a record / row handle carrying the payload (or
        # nothing declares it).  A declared span is its own binding: it is
        # already a named formal.  The ``parameter_abi_kind`` row is the
        # authority (``y = x * a; y[0] = x[1] + b`` with ``x`` a span).
        abi_kinds = post_parameter_abi_kinds(
            storage_book, lexical_read_scope, formal_names.values(),
            value_abi=dict(parameter_value_abi or {}),
            record_abi=dict(parameter_record_abi or {}),
        )
        abi_kind_page = storage_book.page(PARAMETER_ABI_KIND)

        def carries_payload(root_cell: Ref | None) -> bool:
            if root_cell is None:
                return False
            name = formal_names.get(int(root_cell.row[1]))
            cell = None if name is None else abi_kinds.get(name)
            kind = None if cell is None else abi_kind_page.latest(cell.row)
            return not isinstance(kind, ParameterAbiKind) or (
                kind is ParameterAbiKind.RECORD
            )

        payload_candidates = (
            (indexed_base_ids & scalar_use_ids) - declared_sequence_ids
        )
        storage_roots = _post_storage_roots(
            storage_book, storage_scope, lexical_read_scope,
            formals=storage_formals, instructions=semantic_instructions,
            aliases=planning_aliases, wanted=sorted(payload_candidates),
        )
        variant_projected_target_ids.update(
            value_id for value_id in payload_candidates
            if carries_payload(
                _storage_formal_root(storage_book, storage_roots[value_id])
            )
        )
        for planned in hierarchy_plan.items:
            if not (
                isinstance(planned, PlanClosure)
                and planned.name.startswith("region_")
            ):
                continue
            region_index = int(planned.name.rsplit("_", 1)[1])
            instructions = region_instructions(planned)
            region_array_feed_ids[region_index] = {
                int(instruction.args[0].id)
                for instruction in instructions
                if instruction.op in {"Indexed", "IndexedStore", "GetElementPtr"}
                and instruction.args
                and int(instruction.args[0].id) in variant_projected_target_ids
            }
        nested_iterable_source_ids = {
            int(iterable_id)
            for iterable_id, target_id, _induction
            in control.iterable_bindings
            if int(target_id) in nested_row_target_ids
        }
        selected_nested_sequence_ids.update(
            int(instruction.res.id)
            for instruction in semantic_instructions
            if instruction.op in {"Indexed", "Load"}
            and instruction.res is not None
            and int(instruction.res.id) in nested_iterable_source_ids
        )
        for selected_id in selected_nested_sequence_ids:
            region_value_meta[selected_id] = Meta((), "int")
        # Mod and FloorDiv are integer only when integer evidence reaches
        # them (an index result, or all-integer operands), like Add/Mul:
        # Python ``%`` and ``//`` on floats are float.  As unconditional
        # integer seeds they retyped the whole float cone of a float Mod to
        # int64: orbital_game_phasing ``t36 = t32 % (2*pi)`` made the
        # sign() Select feeding t32 an int64 region result, its 1.0 arm was
        # cast to i64 and read back by where_double as 4.9e-324, and
        # t_wait came out 0 instead of 4995.3 s (2026-10-03,
        # docs/concordance_census/CONTINUATION_phasing_regression.md).
        integer_ops = {
            "And", "Or", "Xor", "Shl", "Shr",
            "bitand", "bitor", "bitxor", "shl", "shr",
        }
        arithmetic_ops = {
            "Add", "Sub", "Mul", "add", "sub", "mul",
            "FloorDiv", "Mod", "floordiv", "mod",
        }
        changed = True
        while changed:
            changed = False
            for instruction in semantic_instructions:
                result_id = (
                    None if instruction.res is None else int(instruction.res.id)
                )
                argument_ids = tuple(int(value.id) for value in instruction.args)
                if instruction.op in integer_ops:
                    candidates = (*argument_ids, *((result_id,) if result_id is not None else ()))
                elif instruction.op in arithmetic_ops and (
                    (result_id is not None and result_id in integer_ids)
                    or (argument_ids and all(value_id in integer_ids for value_id in argument_ids))
                ):
                    candidates = (*argument_ids, *((result_id,) if result_id is not None else ()))
                else:
                    continue
                for value_id in candidates:
                    if value_id not in integer_ids:
                        integer_ids.add(value_id)
                        changed = True
        for value_id in integer_ids:
            current = region_value_meta.get(value_id)
            region_value_meta[value_id] = Meta(
                () if current is None else tuple(current.shape), "int64"
            )
    compile_substage(f"SSA section {control_name}: place table and sequence effects")
    report("placing table and sequence effects")
    table_region_operations: dict[
        int, list[tuple[str, tuple[Any, ...]]]
    ] = {}
    table_region_post_operations: dict[
        int, list[tuple[str, tuple[Any, ...]]]
    ] = {}
    row_load_by_result = {
        int(operation[1]): tuple(operation[1:])
        for operation in sequence_row_operations
        if str(operation[0]) == "load"
    }
    effect_preceding_row_reads: dict[int, tuple[int, ...]] = {}
    for reader, effect in sequence_read_before_effects:
        if (int(reader) in row_load_by_result
                or int(reader) in (sequence_length_values or {})):
            effect_preceding_row_reads[int(effect)] = (
                *effect_preceding_row_reads.get(int(effect), ()), int(reader),
            )
    row_store_by_result = {
        int(operation[1]): tuple(operation[1:])
        for operation in sequence_row_operations
        if str(operation[0]) == "store"
    }
    # A fixed-width authored row annotation is authoritative at both sides of
    # a positional update.  Apply its column contract to extracted values and
    # stored leaves before region signatures rebind planner values; otherwise
    # an unknown numeric leaf can retain the planner's conservative float type
    # while its resident column and append helper are correctly integral.
    for operation in sequence_row_operations:
        if str(operation[0]) == "load":
            (
                _kind, result_id, sequence_id, _index_id,
                _index_literal, column, _outer_id,
            ) = operation
            contract = tuple(
                (sequence_column_dtypes or {}).get(int(sequence_id), ())
            )
            if int(column) < len(contract):
                region_value_meta[int(result_id)] = Meta(
                    (), str(contract[int(column)])
                )
        elif str(operation[0]) == "store":
            (
                _kind, _result_id, sequence_id, _index_id,
                _index_literal, leaves, _row_id,
            ) = operation
            contract = tuple(
                (sequence_column_dtypes or {}).get(int(sequence_id), ())
            )
            for column, leaf_id in enumerate(leaves):
                if leaf_id is not None and column < len(contract):
                    region_value_meta[int(leaf_id)] = Meta(
                        (), str(contract[column])
                    )

    sequence_query_result_ids: set[int] = set()
    sequence_query_arena_ids: set[int] = set()
    sequence_queries: list[SequenceQueryBlock] = []

    def collect_sequence_query_results(block: ControlBlock) -> None:
        if isinstance(block, SequenceQueryBlock):
            sequence_queries.append(block)
            sequence_query_result_ids.add(int(block.result_value_id))
            sequence_query_result_ids.update(map(int, block.result_alias_ids))
            sequence_query_arena_ids.add(int(block.sequence_value_id))
        elif isinstance(block, SequenceBlock):
            for child in block.blocks:
                collect_sequence_query_results(child)
        elif isinstance(block, ConditionalBlock):
            collect_sequence_query_results(block.body)
            if block.orelse is not None:
                collect_sequence_query_results(block.orelse)
        elif isinstance(block, LoopBlock):
            collect_sequence_query_results(block.body)
        elif isinstance(block, WhileBlock):
            collect_sequence_query_results(block.condition)
            collect_sequence_query_results(block.body)
        elif isinstance(block, CallBlock):
            collect_sequence_query_results(block.callee)

    collect_sequence_query_results(control.root)
    # Seeded with the caller's graph-derived storage aliases (loop-carried
    # versions of in-place mutated arenas chasing to their base storage),
    # so a later loop's reads of "a after loop 1" resolve to a's own
    # buffer instead of materializing a fresh, unconnected formal -- the
    # defect that silently dropped the first of two sequential loops
    # storing to one array (pinned in test_compiled_linalg.py).
    if value_concordance is None:
        value_concordance = IdentityPage("planning_value_concordance")

    # ``ControlProgram.value_aliases`` is an equivalence ledger assembled by
    # lexical control composition.  Once a component contains exactly one
    # declared resident sequence, its other spellings are proven logical
    # versions of that sequence.  This is NOT necessarily physical in-place
    # storage: a conditional ``where`` can compute the next whole mapping.
    # Publish it on its own concordance page so region output construction does
    # not mistake a computed replacement for an IndexedStore, then give it to
    # control SSA only after region signatures are settled.
    declared_sequence_arenas = {
        *(int(sequence_id) for sequence_id, *_rest in sequence_declarations),
        *(int(sequence_id) for sequence_id, *_rest in sequence_initializations),
        *map(int, source_sequence_ids),
        *map(int, retained_sequence_ids),
        *map(int, nested_sequence_ids),
        *map(int, joined_sequence_ids),
    }
    from .identity_concordance import current_identity_book

    control_value_concordance = current_identity_book().page(
        "control_value_concordance"
    )
    # A source method can be lowered more than once while specializations are
    # assembled.  Its authored value ids repeat, while the physical metadata
    # ids minted by each lowering do not.  Scope tensor rows to this exact
    # control instance so one lowering cannot read another's shape address.
    # The scope is numbered by the book (``scope_registry``), so each
    # lowering of one method owns distinct rows and the rows carry no
    # process object id (census 75, section 8).
    _control_label, _control_serial = current_identity_book().mint_scope(
        f"control:{control_name}"
    )
    tensor_shape_concordance_scope = (
        f"{control_name}@control:{_control_serial}"
    )
    # Row ``(control scope, value id)`` -> the dtype the control program
    # declares for a uniform it reads (loop-bound leaves are ints).  One
    # fact, read by region formal typing and by the control's own argument.
    from .identity_concordance import current_identity_book as _book

    uniform_dtype_page = _book().page("control_uniform_dtype")
    # Row ``(control scope, value id)`` -> the scalar dtype the producing
    # region computes for that value.
    region_dtype_page = _book().page("region_value_dtype")

    def _graph_cell(value_id: Any) -> Any:
        """The ``canonical_value`` cell of a graph id in this function."""

        if lexical_read_scope is None or value_id is None:
            return None
        row = (tuple(lexical_read_scope), int(value_id))
        # A node a specialized copy added after the canonical relabel has its
        # ``ingestion_value`` row in the copy's scope and no canonical row.
        return _book().latest_ref(CANONICAL_VALUE, row) or _book().latest_ref(
            INGESTION_VALUE, row,
        )

    for uniform in getattr(control, "uniforms", ()) or ():
        # DERIVED(the uniform's declaration cell: its ``scalar_parameter``
        # row when declared, else its canonical cell).
        _post_derived_or_raw(
            _book(), CONTROL_UNIFORM_DTYPE,
            (str(tensor_shape_concordance_scope), int(uniform.value_id)),
            str(uniform.dtype),
            (
                _book().latest_ref(
                    SCALAR_PARAMETER,
                    (str(control_name), int(uniform.value_id)),
                ),
                _graph_cell(uniform.value_id),
            ),
            stage=CONTROL_SSA_ENTRY, mode=Mode.CONCORD,
        )
    # ``np.asarray`` reaches the plan as canonical ``tensor``.  When its
    # requested dtype already equals the operand dtype it is a view of the
    # same storage identity, not a new arena.  Publish that fact before
    # region captures are built so a later region reads the resident
    # sequence root directly instead of receiving a row-shaped stand-in.
    # This is the same value concordance used for indexed-store versions and
    # loop-carried storage; no shape or name matching participates.
    for expanded in expanded_plan_regions.values():
        for instruction in expanded:
            if (
                instruction.res is None
                or len(instruction.args) != 1
                or str(instruction.op).casefold() != "cast"
                or str((instruction.attributes or {}).get(
                    "source_operator", ""
                )).casefold() != "tensor"
            ):
                continue
            source = instruction.args[0]
            result = instruction.res
            source_dtype = str(source.dtype or "unknown").casefold()
            result_dtype = str(result.dtype or "unknown").casefold()
            if (
                source_dtype in {"", "none", "unknown"}
                or result_dtype != source_dtype
            ):
                continue
            alias_id, resident_id = int(result.id), int(source.id)
            incumbent = value_concordance.resolve_alias(
                control_name, alias_id
            )
            resident_root = value_concordance.resolve_alias(
                control_name, resident_id
            )
            if incumbent == resident_root:
                continue
            if incumbent != alias_id:
                raise ValueError(
                    "tensor normalization identity disagrees with planning "
                    f"concordance for {control_name!r}: result={alias_id} "
                    f"already resolves to {incumbent}, operand resolves to "
                    f"{resident_root}"
                )
            _bind_planning_alias(
                value_concordance, control_name, alias_id, resident_root,
                (_graph_cell(alias_id), _graph_cell(resident_root)),
                root_scope=tensor_shape_concordance_scope,
            )
    alias_neighbors: dict[int, set[int]] = {}
    for left, right in control.value_aliases:
        left, right = int(left), int(right)
        alias_neighbors.setdefault(left, set()).add(right)
        alias_neighbors.setdefault(right, set()).add(left)
    visited_aliases: set[int] = set()
    for seed in tuple(alias_neighbors):
        if seed in visited_aliases:
            continue
        component, frontier = set(), [seed]
        while frontier:
            value_id = frontier.pop()
            if value_id in component:
                continue
            component.add(value_id)
            frontier.extend(alias_neighbors.get(value_id, ()))
        visited_aliases.update(component)
        residents = component & declared_sequence_arenas
        if len(residents) != 1:
            continue
        resident_id = next(iter(residents))
        for alias_id in sorted(component - {resident_id}):
            incumbent = control_value_concordance.latest(
                (control_name, int(alias_id))
            )
            if incumbent is None:
                # DERIVED(alias node's and resident's canonical cells); the
                # planning alias row that joined them is the planner's page.
                _post_derived_or_raw(
                    _book(), CONTROL_VALUE_CONCORDANCE,
                    (control_name, int(alias_id)), int(resident_id),
                    (_graph_cell(alias_id), _graph_cell(resident_id)),
                    stage=CONTROL_SSA_ENTRY, mode=Mode.REVISE,
                )
            elif control_value_concordance.resolve_alias(
                control_name, int(alias_id)
            ) != control_value_concordance.resolve_alias(
                control_name, int(resident_id)
            ):
                raise ValueError(
                    "control sequence identity disagrees with planning "
                    f"concordance for {control_name!r}: "
                    f"alias={alias_id}, control_resident={resident_id}, "
                    f"concordance_resident={incumbent}"
                )
    from .identity_concordance import resolved_concordant_alias_bindings

    region_value_aliases = resolved_concordant_alias_bindings(
        control_name,
        control_value_concordance.alias_bindings(control_name),
        page=value_concordance,
    )
    # Publish the resolved roots back to the live authority. Later passes and
    # the durable function snapshot must see the same complete identity, not
    # whichever half of the chain their stage happened to author.
    for alias_id, resident_id in region_value_aliases.items():
        if value_concordance.latest(
            (control_name, int(alias_id))
        ) != int(resident_id):
            _bind_planning_alias(
                value_concordance, control_name, int(alias_id),
                int(resident_id),
                (_graph_cell(alias_id), _graph_cell(resident_id)),
                root_scope=tensor_shape_concordance_scope,
            )

    def bind_resident(alias_id: int, resident_id: int) -> None:
        """Publish a planning alias, then mirror the concorded fact for SSA."""
        alias_id, resident_id = int(alias_id), int(resident_id)
        alias_root = value_concordance.resolve_alias(control_name, alias_id)
        resident_root = value_concordance.resolve_alias(
            control_name, resident_id
        )
        if alias_root == resident_root:
            # A later stage may encounter the same resident relationship in
            # the opposite syntactic direction (loop-result versus final
            # IndexedStore).  It is already one concordance row; recording the
            # reverse edge would manufacture a cycle from an agreement.
            # A value is not an alias of itself: a concat result binds its
            # own resident (``bind_resident(6, 6)``) and the mirror recorded
            # ``6 -> 6``, an alias no concordance row states (``xs = [5, 7]
            # + [n, 7]``: the audit's value_aliases disagreement).
            if alias_id != resident_root:
                region_value_aliases[alias_id] = resident_root
            return
        if alias_root != alias_id:
            raise ValueError(
                "planning identity concordance disagreement for "
                f"{control_name!r}: alias {alias_id} already resolves to "
                f"{alias_root}, cannot bind it to {resident_root}"
            )
        _bind_planning_alias(
            value_concordance, control_name, alias_id, resident_root,
            (_graph_cell(alias_id), _graph_cell(resident_root)),
            root_scope=tensor_shape_concordance_scope,
        )
        region_value_aliases[alias_id] = resident_root

    def resident_root(value_id: int) -> int:
        """Canonical planning identity for one value occurrence."""

        return value_concordance.resolve_alias(control_name, value_id)
    # An in-place pursued call can publish a result identity that is never an
    # operand of a later numerical region: the resident arena itself carries
    # the effect.  Such calls still execute at their authored position.  Use
    # the next retained region as the control anchor, exactly as hierarchical
    # call composition does, instead of waiting for a nonexistent data use.
    trailing_inplace_pack_operations: list[tuple[str, tuple[Any, ...]]] = []
    if hierarchy_plan is not None and inplace_pack_by_result:
        planned_items = tuple(hierarchy_plan.items)
        consumed_result_ids = {
            int(argument.id)
            for item in planned_items
            if isinstance(item, PlanClosure)
            and item.name.startswith("region_")
            for instruction in region_instructions(item)
            for argument in instruction.args
        }
        call_item_positions = {
            int(item.callsite_id): position
            for position, item in enumerate(planned_items)
            if isinstance(item, PlanCall)
        }
        for result_id, (
            sequence_id, width, callee_reference, callsite_id,
        ) in inplace_pack_by_result.items():
            if int(result_id) in consumed_result_ids:
                continue
            position = call_item_positions.get(int(callsite_id))
            if position is None:
                continue
            next_region = next((
                item for item in planned_items[position + 1:]
                if isinstance(item, PlanClosure)
                and item.name.startswith("region_")
            ), None)
            if next_region is None:
                # PROGRAM SHAPE: an in-place pursued pack call
                # (``pack(bits)`` whose result is never read) with no numerical
                # region after its callsite, e.g. ``bits[0] = 1; pack(bits);
                # return 3``.  WRONG RECORD: this branch used to ``continue``,
                # so the ``pack_bits`` effect was recorded in no table
                # operation list and only the ``__plan_callsite_N__`` marker
                # survived, with nothing to decompose it.  RULE NOW HOLDING:
                # the authored call effect is always recorded.  Its position is
                # trailing, which the existing ``table_epilogue_operations``
                # keying already expresses (same ``pack_bits`` entry shape as
                # ``sequence_bit_packs``); it carries callee_reference and
                # callsite_id so the frame linker matches the decomposition.
                bind_resident(result_id, sequence_id)
                trailing_inplace_pack_operations.append((
                    "pack_bits",
                    (
                        sequence_id, sequence_id, width, True,
                        callee_reference, callsite_id,
                    ),
                ))
                continue
            region_index = int(next_region.name.rsplit("_", 1)[1])
            bind_resident(result_id, sequence_id)
            table_region_operations.setdefault(region_index, []).append((
                "pack_bits",
                (
                    sequence_id, sequence_id, width, True,
                    callee_reference, callsite_id,
                ),
            ))
    lookup_by_result = {
        int(result_id): (int(result_id), query_id, int(sequence_id))
        for result_id, query_id, sequence_id in table_lookups
    }
    store_by_effect = {
        int(effect_id): (
            int(effect_id), key_id, int(value_id), int(sequence_id)
        )
        for effect_id, key_id, value_id, sequence_id in table_stores
    }
    region_source_values: list[tuple[int, int]] = []
    handled_table_region_indices: set[int] = set()
    field_read_value_ids = {
        int(value_id)
        for kind, value_id, _slot in field_ops
        if kind == "read"
    }
    authored_output_value_ids = {
        int(history[-1])
        for name in function_outputs
        for history in (
            tuple((identity_table or {}).get(str(name), ())),
        )
        if history
    }
    instruction_pool = getattr(expanded_plan_regions, "pool", None)
    planned_region_instructions = ({} if instruction_pool is None else
                                   instruction_pool.view("planned"))
    resolved_plan_live_value_ids: set[int] = set()
    plan_line_produced: set[int] = set()
    plan_line_consumed: set[int] = set()

    def region_free_value_ids(
        instructions: Any,
    ) -> tuple[int, ...]:
        """Return exact body operands with no local SSA definition.

        Planner captures are scheduling evidence, but the emitted region body
        is the final authority for its callable ABI.  Structural rewrites can
        expose an operand the hierarchy capture set omitted; failing to add it
        creates a function whose instructions reference a value absent from
        its formals.
        """

        produced = {
            int(instruction.res.id)
            for instruction in instructions
            if instruction.res is not None
        }
        return tuple(dict.fromkeys(
            int(argument.id)
            for instruction in instructions
            for argument in instruction.args
            if int(argument.id) not in produced
        ))

    def collect_resolved_plan_dependencies(closure: PlanClosure) -> None:
        """Collect the dependency boundary already resolved by the planner."""

        resolved_plan_live_value_ids.update(int(value_id) for value_id in closure.captures)
        for item in closure.items:
            if isinstance(item, PlanLine):
                plan_line_produced.update(int(v) for v in item.outputs)
                plan_line_consumed.update(int(v) for v in item.inputs)
            if isinstance(item, PlanClosure):
                collect_resolved_plan_dependencies(item)
            elif isinstance(item, PlanCall):
                resolved_plan_live_value_ids.update(
                    int(value_id) for value_id in item.argument_value_ids
                )
                # ``argument_value_ids`` live in the assigned hierarchy
                # namespace. Region SSA is built in the caller's local value
                # namespace, whose exact correlation is the caller side of
                # each PlanCall binding. Preserve both views; do not infer the
                # local feed again from instruction order or terminal values.
                resolved_plan_live_value_ids.update(
                    int(caller_id)
                    for caller_id, _callee_id in item.argument_bindings
                )

    if hierarchy_plan is not None:
        collect_resolved_plan_dependencies(hierarchy_plan)
        # A value some plan line produces that nothing in the hierarchy
        # consumes is either the plan's TERMINAL result or dead planner
        # residue, and the difference is who else is speaking. When ANY
        # output authority is declared -- identity-table function outputs,
        # required ids, per-region output declarations -- declarations are
        # exhaustive, and unconsumed undeclared values are residue to drop
        # (test_cross_region_live_out holds a produced-and-unconsumed value
        # OUT of the boundary for exactly this reason). Only when the plan
        # declares nothing at all do terminals become the result by default:
        # a program whose answer is exported by no one has computed nothing.
        declared_authority = bool(
            (identity_table or {})
            or required_output_value_ids
            or (region_output_value_ids or {})
        )
        if not declared_authority:
            resolved_plan_live_value_ids.update(
                plan_line_produced
                - plan_line_consumed
                - resolved_plan_live_value_ids
            )
        for planned in hierarchy_plan.items:
            if not (
                isinstance(planned, PlanClosure)
                and planned.name.startswith("region_")
            ):
                continue
            planned_index = int(planned.name.rsplit("_", 1)[1])
            planned_instructions = region_instructions(planned)
            planned_region_instructions[planned_index] = planned_instructions

    captured_row_loads: set[int] = set()
    compile_substage(f"SSA section {control_name}: lower planned regions")
    planned_result_ids = {
        int(instruction.res.id)
        for instructions in planned_region_instructions.values()
        for instruction in instructions if instruction.res is not None
    }
    # A read that precedes an effect the control function performs (no
    # region plans it) is loaded before that effect
    # (``effect_preceding_row_reads``), never at a later consuming region.
    effect_preceding_reads = {
        int(reader) for reader, effect in sequence_read_before_effects
        if int(effect) not in planned_result_ids
    }
    if hierarchy_plan is not None:
        for region in hierarchy_plan.items:
            if not (
                isinstance(region, PlanClosure)
                and region.name.startswith("region_")
            ):
                continue
            region_index = int(region.name.split("_", 1)[1])
            if region_index not in set(map(int, control.region_indices)):
                # Projection removed this region's only lexical marker. This
                # is how an external-reference occurrence replaces the old
                # capture-time numerical imitation of the same call; keeping
                # the detached region would execute both meanings.
                continue
            if region_index in region_callees:
                continue
            # Namespace regions by their owning method so two methods that each
            # carve a ``region_0`` do not collide in one shared library, and so
            # the control call the lowering emits already targets this symbol.
            region_name = f"{control_name}__planned_region_{region_index}"
            instructions = region_instructions(region)
            report(
                f"region {region_index}: lowering {len(instructions)} "
                "planned instruction(s)"
            )
            # A resident generator query (currently ``sum(1 for ...)`` or
            # ``next(..., default)``) is emitted in lexical control beside its
            # producer loop. Remove only that replaced operator from the
            # numerical region; downstream arithmetic/compare instructions
            # remain and consume the query's exact result identity.
            instructions = [
                instruction for instruction in instructions
                if instruction.res is None
                or (int(instruction.res.id) not in sequence_query_result_ids
                    and not (
                        instruction.op == "Const"
                        and int(instruction.res.id) in sequence_query_arena_ids
                        and isinstance(instruction.attributes.get("value", instruction.attributes.get("constant")), list)
                        and not instruction.attributes.get("value", instruction.attributes.get("constant"))
                    ))
            ]
            replaced_maximum_calls = {
                int(query.source_call_node_id)
                for query in sequence_queries
                if query.operation == "maximum"
                and query.source_call_node_id is not None
                and int(query.source_call_node_id) in set(map(
                    int,
                    (region_output_value_ids or {}).get(region_index, ()),
                ))
            }
            if replaced_maximum_calls:
                # Variadic Python max is flattened into a chain of Max
                # instructions in one numerical region.  The resident query
                # replaces that whole chain, while its scalar prefix operands
                # (often Div results) remain real region outputs consumed by
                # the query after the generator completes.
                instructions = [
                    instruction for instruction in instructions
                    if not (
                        instruction.op == "Max"
                        and instruction.attributes.get("extraction_identity")
                        == "builtins.max"
                    )
                ]
            row_loads = tuple(dict.fromkeys((*(
                row_load_by_result[int(instruction.res.id)]
                for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in row_load_by_result
            ), *(
                # values[2] after append survives as an exact graph read but
                # the numeric plan keeps only its scalar feed, not Indexed.
                # Recover the existing row operation at its first consuming
                # region ONLY when no region owns its defining instruction.
                row_load_by_result[value_id]
                for value_id in region_free_value_ids(instructions)
                if value_id in row_load_by_result
                and value_id not in planned_result_ids
                and value_id not in captured_row_loads
                and value_id not in effect_preceding_reads
            ))))
            # A row read no region owns that precedes an effect this region
            # performs (an indexed store; ``sequence_read_before_effects``)
            # is loaded before the region, not at its later consumer
            # (scratch lp/c_t: ``a = xs[1]; xs[1] = 9; return a + 0``).
            region_effect_ids = {
                int(instruction.res.id) for instruction in instructions
                if instruction.res is not None
            }
            row_loads = tuple(dict.fromkeys((*row_loads, *(
                row_load_by_result[int(reader)]
                for reader, effect in sequence_read_before_effects
                if int(effect) in region_effect_ids
                and int(reader) in row_load_by_result
                and int(reader) not in region_effect_ids
                and int(reader) not in planned_result_ids
                and int(reader) not in captured_row_loads
            ))))
            # Program: ``g = [[1, 2], [3, n]]; g[i][1]`` (corpus c732).  A
            # row load from the row ``g[i]`` selects reads the slice that
            # ``g[i]``'s own load binds, so it follows that load whatever
            # order the region's instructions listed them.
            loaded = {int(operation[0]) for operation in row_loads}
            ordered_loads: list[tuple] = []
            waiting = list(row_loads)
            while waiting:
                ready = [
                    operation for operation in waiting
                    if int(operation[1]) not in loaded
                    or int(operation[1]) in {
                        int(done[0]) for done in ordered_loads
                    }
                ]
                if not ready:
                    ready = waiting
                ordered_loads.append(ready[0])
                waiting.remove(ready[0])
            row_loads = tuple(ordered_loads)
            captured_row_loads.update(int(operation[0]) for operation in row_loads)
            row_stores = tuple(
                row_store_by_result[int(instruction.res.id)]
                for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in row_store_by_result
            )
            if row_loads or row_stores:
                removed_results = {
                    int(operation[0]) for operation in (*row_loads, *row_stores)
                }
                instructions = [
                    instruction for instruction in instructions
                    if instruction.res is None
                    or int(instruction.res.id) not in removed_results
                ]
                while True:
                    consumed = {
                        int(argument.id)
                        for instruction in instructions
                        for argument in instruction.args
                    }
                    dead_constants = {
                        int(instruction.res.id)
                        for instruction in instructions
                        if instruction.op == "Const"
                        and instruction.res is not None
                        and int(instruction.res.id) not in consumed
                    }
                    if not dead_constants:
                        break
                    instructions = [
                        instruction for instruction in instructions
                        if instruction.res is None
                        or int(instruction.res.id) not in dead_constants
                    ]
                for operation in row_loads:
                    result_id = int(operation[0])
                    table_region_operations.setdefault(
                        region_index, []
                    ).append((
                        "row_load_capture" if instructions else "row_load",
                        operation,
                    ))
                for operation in row_stores:
                    result_id, sequence_id = map(int, operation[:2])
                    # Whole-row assignment returns the sequence; a sparse
                    # column assignment retains its already-concorded row
                    # view. Rebinding Store12 from Indexed11 to Sequence10
                    # would publish a second identity for the same effect.
                    if all(value is not None for value in operation[4]):
                        bind_resident(result_id, sequence_id)
                    table_region_operations.setdefault(
                        region_index, []
                    ).append(("row_store", operation))
            # Instance-field reads already have an exact record slot contract.
            # Keeping their source-level GetAttr instruction inside a flat
            # region throws that information away and asks every backend to
            # rediscover Python object semantics. Remove that instruction here:
            # a mixed region receives the loaded field value as a capture, and
            # a field-only region disappears. `_inject_field_slot_access`
            # inserts the corresponding GEP/Load at the first region call (or
            # at Ret for a getter), so the object has become ordinary storage
            # before target emission.
            resolved_field_reads = {
                int(instruction.res.id)
                for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in field_read_value_ids
                and str(instruction.op).casefold() == "getattr"
            }
            if resolved_field_reads:
                instructions = [
                    instruction
                    for instruction in instructions
                    if not (
                        instruction.res is not None
                        and int(instruction.res.id) in resolved_field_reads
                        and str(instruction.op).casefold() == "getattr"
                    )
                ]
            # Attribute lookup itself is pure. Planner regions historically
            # retained method/property lookup nodes as terminal outputs even
            # when a typed PlanCall, structural helper, or tensor operation
            # already carried the actual effect. Prune only terminal lookups
            # that neither cross a region boundary nor implement an authored
            # return. Iterate so a dead ``obj.__dict__.get`` chain collapses
            # from the outside inward.
            while True:
                locally_consumed = {
                    int(argument.id)
                    for instruction in instructions
                    for argument in instruction.args
                }
                removable = {
                    int(instruction.res.id)
                    for instruction in instructions
                    if instruction.res is not None
                    and str(instruction.op).casefold() == "getattr"
                    and int(instruction.res.id) not in locally_consumed
                    and int(instruction.res.id) not in resolved_plan_live_value_ids
                    and int(instruction.res.id) not in authored_output_value_ids
                }
                if not removable:
                    break
                instructions = [
                    instruction
                    for instruction in instructions
                    if instruction.res is None
                    or int(instruction.res.id) not in removable
                ]
            effective_captures = tuple(dict.fromkeys((
                *map(int, region.captures),
                *region_free_value_ids(instructions),
                *(
                    int(operation[0])
                    for operation in row_loads
                    if instructions
                ),
                *(
                    int(argument.id)
                    for instruction in instructions
                    for argument in instruction.args
                    if int(argument.id) in sequence_query_result_ids
                ),
                *(
                    int(argument.id)
                    for instruction in instructions
                    for argument in instruction.args
                    if int(argument.id) in resolved_field_reads
                ),
            )))
            produced_after_field_resolution = {
                int(instruction.res.id)
                for instruction in instructions
                if instruction.res is not None
            }
            consumed_after_field_resolution = {
                int(argument.id)
                for instruction in instructions
                for argument in instruction.args
            }
            region_inout_ids = tuple(
                value_id
                for value_id in map(int, record_field_write_value_ids)
                if value_id in produced_after_field_resolution
            )
            effective_captures = tuple(dict.fromkeys((
                *effective_captures,
                *region_inout_ids,
            )))
            effective_captures = tuple(
                value_id
                for value_id in effective_captures
                if (
                    value_id in region_inout_ids
                    or value_id in region_free_value_ids(instructions)
                )
            )
            if not instructions:
                table_region_operations.setdefault(region_index, []).append((
                    "structural_consumed", (),
                ))
                continue
            if any(
                instruction.res is not None
                and int(instruction.res.id) in (
                    append_fill_source_result_ids
                    | append_slice_source_result_ids
                )
                for instruction in instructions
            ):
                table_region_operations.setdefault(region_index, []).append((
                    "structural_consumed", (),
                ))
                continue
            if any(
                instruction.res is not None
                and int(instruction.res.id) in bit_pack_consumed_ids
                for instruction in instructions
            ):
                table_region_operations.setdefault(region_index, []).append((
                    "structural_consumed", (),
                ))
                continue
            fill_instructions = tuple(
                instruction for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in sequence_fills
                and instruction.op in {"Mul", "Mult", "mul"}
            )
            if fill_instructions:
                removed_ids = {
                    int(instruction.res.id)
                    for instruction in fill_instructions
                }
                # The list literal feeding replication is structural input to
                # the fill helper; remove its now-dead Const from the region.
                fill_operand_ids = {
                    int(argument.id)
                    for instruction in fill_instructions
                    for argument in instruction.args
                }
                instructions = [
                    instruction for instruction in instructions
                    if instruction not in fill_instructions
                    and not (
                        instruction.op == "Const"
                        and instruction.res is not None
                        and int(instruction.res.id) in fill_operand_ids
                        and isinstance(instruction.attributes.get("value"), (list, tuple))
                    )
                ]
                for result_id in removed_ids:
                    table_region_post_operations.setdefault(
                        region_index, []
                    ).append(("fill", sequence_fills[result_id]))
            augment_instructions = tuple(
                instruction
                for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in sequence_augment_by_result
                and instruction.op in {"Add", "add"}
            )
            if augment_instructions:
                for instruction in augment_instructions:
                    result_id = int(instruction.res.id)
                    destination_id, source_id = sequence_augment_by_result[
                        result_id
                    ]
                    bind_resident(result_id, destination_id)
                    table_region_post_operations.setdefault(
                        region_index, []
                    ).append((
                        "extend",
                        (result_id, destination_id, source_id),
                    ))
                instructions = [
                    instruction for instruction in instructions
                    if instruction not in augment_instructions
                    and not (
                        instruction.op == "Const"
                        and instruction.res is not None
                        and not any(
                            int(instruction.res.id) == int(argument.id)
                            for remaining in instructions
                            if remaining not in augment_instructions
                            for argument in remaining.args
                        )
                    )
                ]
            concat_instructions = tuple(
                instruction
                for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in sequence_concat_by_result
                and instruction.op in {"Add", "add"}
            )
            if concat_instructions:
                for instruction in concat_instructions:
                    result_id = int(instruction.res.id)
                    (
                        lhs_id, rhs_id, _kind, lhs_scalar, rhs_scalar,
                    ) = sequence_concat_by_result[
                        result_id
                    ]
                    bind_resident(result_id, result_id)
                    scheduled = table_region_operations.setdefault(
                        region_index, []
                    )
                    scheduled.append(("reset", (result_id,)))
                    scheduled.append((
                        "append_scalar" if lhs_scalar is not None
                        else "append_slice",
                        (
                            (result_id, lhs_scalar)
                            if lhs_scalar is not None
                            else (result_id, lhs_id, None, None)
                        ),
                    ))
                    scheduled.append((
                        "append_scalar" if rhs_scalar is not None
                        else "append_slice",
                        (
                            (result_id, rhs_scalar)
                            if rhs_scalar is not None
                            else (result_id, rhs_id, None, None)
                        ),
                    ))
                instructions = [
                    instruction for instruction in instructions
                    if instruction not in concat_instructions
                ]
                if not instructions:
                    table_region_operations.setdefault(
                        region_index, []
                    ).append(("structural_consumed", ()))
                    continue
            append_fill_instructions = tuple(
                instruction
                for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id)
                in sequence_append_fill_by_result
                and instruction.op in {"Add", "add"}
            )
            if append_fill_instructions:
                for instruction in append_fill_instructions:
                    result_id = int(instruction.res.id)
                    destination_id, literal, count_id = (
                        sequence_append_fill_by_result[result_id]
                    )
                    bind_resident(result_id, destination_id)
                    table_region_post_operations.setdefault(
                        region_index, []
                    ).append((
                        "append_fill",
                        (destination_id, literal, count_id),
                    ))
                instructions = [
                    instruction for instruction in instructions
                    if instruction not in append_fill_instructions
                ]
            append_slice_instructions = tuple(
                instruction
                for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in sequence_append_slice_by_result
                and instruction.op in {"Add", "add"}
            )
            if append_slice_instructions:
                for instruction in append_slice_instructions:
                    result_id = int(instruction.res.id)
                    destination_id, source_id, lower_id, upper_id = (
                        sequence_append_slice_by_result[result_id]
                    )
                    bind_resident(result_id, destination_id)
                    table_region_post_operations.setdefault(
                        region_index, []
                    ).append((
                        "append_slice",
                        (destination_id, source_id, lower_id, upper_id),
                    ))
                instructions = [
                    instruction for instruction in instructions
                    if instruction not in append_slice_instructions
                ]
            prepend_instructions = tuple(
                instruction for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in prepend_by_result
                and instruction.op in {"Add", "add"}
            )
            if prepend_instructions:
                for instruction in prepend_instructions:
                    result_id = int(instruction.res.id)
                    sequence_id, value_id = prepend_by_result[result_id]
                    bind_resident(result_id, sequence_id)
                    table_region_post_operations.setdefault(
                        region_index, []
                    ).append(("prepend", (sequence_id, value_id)))
                instructions = [
                    instruction for instruction in instructions
                    if instruction not in prepend_instructions
                ]
            packed_instructions = tuple(
                instruction for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in packed_by_concat
                and instruction.op in {"Add", "add"}
            )
            if packed_instructions:
                for instruction in packed_instructions:
                    result_id = int(instruction.res.id)
                    (
                        destination_id, source_id, prefix_id,
                        packed_callsite_id,
                    ) = packed_by_concat[
                        result_id
                    ]
                    bind_resident(result_id, destination_id)
                instructions = [
                    instruction for instruction in instructions
                    if instruction not in packed_instructions
                ]
            packed_store_instructions = tuple(
                instruction for instruction in instructions
                if instruction.res is not None
                and int(instruction.res.id) in packed_by_store
            )
            if packed_store_instructions:
                for instruction in packed_store_instructions:
                    store_result_id = int(instruction.res.id)
                    (
                        destination_id, source_id, prefix_id,
                        packed_callsite_id,
                    ) = packed_by_store[
                        store_result_id
                    ]
                    # Preserve authored call order at the splice boundary:
                    # bitmap-pack destination, then prepend the prefix and
                    # packed mapping words, then consume the slice store.
                    prior_pack = next((
                        inplace_pack_by_result[result_id]
                        for result_id in sorted(inplace_pack_by_result)
                        if result_id in {int(value.id) for value in instruction.args}
                    ), None)
                    if prior_pack is not None:
                        (
                            sequence_id, width, callee_reference,
                            pack_callsite_id,
                        ) = prior_pack
                        bind_resident(next(
                            result_id for result_id, contract
                            in inplace_pack_by_result.items()
                            if contract == prior_pack
                            and result_id in {
                                int(value.id) for value in instruction.args
                            }
                        ), sequence_id)
                        table_region_operations.setdefault(
                            region_index, []
                        ).append((
                            "pack_bits",
                            (
                                sequence_id, sequence_id, width, True,
                                callee_reference, pack_callsite_id,
                            ),
                        ))
                    table_region_operations.setdefault(
                        region_index, []
                    ).append((
                        "prepend_packed_bytes",
                        (
                            destination_id, source_id, prefix_id, 4,
                            packed_callsite_id,
                        ),
                    ))
                table_region_operations.setdefault(region_index, []).append((
                    "structural_consumed", (),
                ))
                continue
            if any(
                instruction.res is not None
                and int(instruction.res.id) in prepend_store_result_ids
                for instruction in instructions
            ):
                # The following zero-width slice store is the authored splice;
                # prepend has already performed it in resident memory.
                table_region_operations.setdefault(region_index, []).append((
                    "structural_consumed", (),
                ))
                continue
            # A pursued structural bit-pack call publishes the same resident
            # arena under its call result ID.  Schedule the helper at the first
            # region that consumes that result, before that region executes.
            consumed_pack_results = tuple(sorted({
                int(argument.id)
                for instruction in instructions
                for argument in instruction.args
                if int(argument.id) in inplace_pack_by_result
            }))
            for result_id in consumed_pack_results:
                (
                    sequence_id, width, callee_reference,
                    pack_callsite_id,
                ) = inplace_pack_by_result[
                    result_id
                ]
                bind_resident(result_id, sequence_id)
                table_region_operations.setdefault(region_index, []).append((
                    "pack_bits",
                    (
                        sequence_id, sequence_id, width, True,
                        callee_reference, pack_callsite_id,
                    ),
                ))
            for instruction in instructions:
                if (
                    instruction.op == "IndexedStore"
                    and instruction.res is not None
                    and instruction.args
                ):
                    # IndexedStore versions resident memory; it does not return
                    # a new scalar payload.  Preserve the authored result ID as
                    # an alias of the base arena across subsequent regions.
                    bind_resident(
                        int(instruction.res.id), int(instruction.args[0].id),
                    )
            instructions = [instruction for instruction in instructions
                            if not (instruction.op == "IndexedStore"
                                    and instruction.res is not None
                                    and int(instruction.res.id) in lexical_mapping_write_ids)]
            # The table helper publishes every member of its source tuple.
            # A planned Indexed of that exact member is the same projection,
            # not a second numerical operation on a scalar aggregate handle.
            # Keep all other indexing, including mixed-region computations.
            if lexical_read_scope is not None:
                from .structural_concordance import source_structure

                retained_instructions = []
                for instruction in instructions:
                    supplied_by_lookup = False
                    if (str(instruction.op).casefold() == "indexed"
                            and instruction.res is not None and instruction.args
                            and int(instruction.args[0].id) in table_lookup_result_ids
                            and instruction.attributes.get("aggregate_index") is not None):
                        structure, _cell = source_structure(
                            tuple(lexical_read_scope), int(instruction.args[0].id), book=_book(),
                        )
                        member = dict(structure.leaves()).get((int(instruction.attributes["aggregate_index"]),))
                        supplied_by_lookup = bool(
                            structure.kind == "product" and structure.storage == "tuple"
                            and member is not None and member.value_id == int(instruction.res.id)
                        )
                    if not supplied_by_lookup:
                        retained_instructions.append(instruction)
                if len(retained_instructions) != len(instructions):
                    instructions = retained_instructions
                    planned_region_instructions[region_index] = tuple(instructions)
                    if not instructions:
                        table_region_operations.setdefault(region_index, []).append((
                            "structural_consumed", (),
                        ))
            if lexical_mapping_write_ids:
                planned_region_instructions[region_index] = tuple(instructions)
            if not instructions:
                handled_table_region_indices.add(region_index)
                continue
            region_source_values.extend(
                (int(instruction.res.id), region_index)
                for instruction in instructions
                if instruction.res is not None
            )
            table_index_instructions = tuple(
                instruction
                for instruction in instructions
                if instruction.op in {"Indexed", "IndexedStore"}
                and instruction.res is not None
                and (
                    int(instruction.res.id) in table_lookup_result_ids
                    or int(instruction.res.id) in table_store_effect_ids
                )
            )
            if table_index_instructions:
                if (
                    len(table_index_instructions) == len(instructions) == 1
                    and table_index_instructions[0].op == "Indexed"
                    and table_index_instructions[0].res is not None
                    and int(table_index_instructions[0].res.id)
                    in table_lookup_result_ids
                ):
                    handled_table_region_indices.add(region_index)
                    table_region_operations.setdefault(region_index, []).append((
                        "lookup",
                        lookup_by_result[int(table_index_instructions[0].res.id)],
                    ))
                    continue
                if (
                    len(table_index_instructions) == len(instructions) == 1
                    and table_index_instructions[0].op == "IndexedStore"
                    and table_index_instructions[0].res is not None
                    and int(table_index_instructions[0].res.id)
                    in table_store_effect_ids
                ):
                    handled_table_region_indices.add(region_index)
                    table_region_operations.setdefault(region_index, []).append((
                        "store",
                        store_by_effect[int(table_index_instructions[0].res.id)],
                    ))
                    continue
                table_ids = {
                    int(instruction.res.id)
                    for instruction in table_index_instructions
                    if instruction.res is not None
                }
                remaining = [
                    instruction for instruction in instructions
                    if instruction not in table_index_instructions
                ]
                consumed_table_ids = {
                    int(argument.id)
                    for instruction in remaining
                    for argument in instruction.args
                    if int(argument.id) in table_ids
                }
                if consumed_table_ids:
                    unsupported_consumed = tuple(
                        instruction
                        for instruction in table_index_instructions
                        if (
                            int(instruction.res.id) in consumed_table_ids
                            and (
                                instruction.op != "Indexed"
                                or int(instruction.res.id) not in lookup_by_result
                            )
                        )
                    )
                    if unsupported_consumed:
                        for instruction in unsupported_consumed:
                            shortfalls.append(SSALoweringShortfall(
                                "ssa-table",
                                instruction.op,
                                f"{control_name}.region_{region_index}",
                                "keyed table effect is consumed as a scalar but is not a lookup",
                            ))
                        continue
                    for result_id in sorted(consumed_table_ids):
                        table_region_operations.setdefault(
                            region_index, []
                        ).append((
                            "lookup_capture", lookup_by_result[result_id]
                        ))
                    effective_captures = tuple(dict.fromkeys((
                        *effective_captures,
                        *sorted(consumed_table_ids),
                    )))
                instructions = remaining
                for instruction in table_index_instructions:
                    effect_id = int(instruction.res.id)
                    if effect_id in consumed_table_ids:
                        continue
                    if instruction.op == "Indexed":
                        table_region_post_operations.setdefault(
                            region_index, []
                        ).append(("lookup", lookup_by_result[effect_id]))
                    else:
                        table_region_post_operations.setdefault(
                            region_index, []
                        ).append(("store", store_by_effect[effect_id]))
            instruction_values = {
                int(value.id): value
                for instruction in instructions
                for value in (
                    *instruction.args,
                    *((instruction.res,) if instruction.res is not None else ()),
                )
            }
            # A variant payload has parallel scalar and child-row columns.
            # Its authored ID remains scalar in regions that use it as a value
            # or index; only regions that dereference it receive the row-base
            # address selected by the control caller.
            for value_id in variant_projected_target_ids:
                if value_id in region_array_feed_ids.get(region_index, set()):
                    region_value_meta[value_id] = Meta((), "float64")
                elif value_id in instruction_values:
                    region_value_meta[value_id] = Meta((), "float64")
            # Physical parameter/field ABI applies inside numerical callees
            # too. Applying this only when constructing the coordinator let
            # its byte-valued bool field be read as a double by a region.
            # A control uniform's dtype is a contract of the control program
            # (a ``range`` bound leaf is an int); the book row committed at
            # entry is read here so the region formal and the control caller
            # agree.  A declared physical ABI dtype below still wins.
            for value_id in instruction_values:
                uniform_dtype = uniform_dtype_page.latest(
                    (str(tensor_shape_concordance_scope), int(value_id))
                )
                if uniform_dtype is not None:
                    previous = region_value_meta.get(int(value_id))
                    region_value_meta[int(value_id)] = Meta(
                        () if previous is None else tuple(previous.shape),
                        str(uniform_dtype),
                    )
            # A value an earlier region produced has the dtype that region
            # typed it with (``region_value_dtype``); the planner's generic
            # capture guess must not retype it at this formal.
            for value_id in instruction_values:
                produced_dtype = region_dtype_page.latest(
                    (str(tensor_shape_concordance_scope), int(value_id))
                )
                if produced_dtype is not None:
                    previous = region_value_meta.get(int(value_id))
                    region_value_meta[int(value_id)] = Meta(
                        () if previous is None else tuple(previous.shape),
                        str(produced_dtype),
                    )
            for value_id, dtype in (value_dtypes or {}).items():
                if int(value_id) in instruction_values:
                    previous = region_value_meta.get(int(value_id))
                    region_value_meta[int(value_id)] = Meta(
                        tuple((value_shapes or {}).get(int(value_id),
                              () if previous is None else previous.shape)), str(dtype),
                    )
            region_values = {}
            for value_id, shape, dtype in region.value_shapes:
                authoritative = region_value_meta.get(int(value_id))
                semantic = instruction_values.get(int(value_id))
                region_values[int(value_id)] = SSAValue(
                    int(value_id),
                    dtype=(
                        str(authoritative.dtype)
                        if authoritative is not None else str(dtype)
                        if semantic is None or semantic.dtype is None
                        else str(semantic.dtype)
                    ),
                    shape=(
                        # One storage identity may enter different planned
                        # regions through different reshape/view contracts.
                        # The instruction occurrence is the exact local view;
                        # the id-keyed region-wide metadata is only a fallback
                        # for otherwise shapeless occurrences.
                        tuple(semantic.shape)
                        if semantic is not None and semantic.shape
                        else tuple(map(int, authoritative.shape))
                        if authoritative is not None
                        else tuple(map(int, shape))
                    ),
                )
            for value_id, shape, dtype in region.value_shapes:
                semantic = instruction_values.get(int(value_id))
                region_value_meta.setdefault(
                    int(value_id),
                    Meta(
                        shape=(
                            tuple(semantic.shape)
                            if semantic is not None and semantic.shape
                            else tuple(map(int, shape))
                        ),
                        dtype=(
                            str(semantic.dtype)
                            if semantic is not None and semantic.dtype is not None
                            else str(dtype)
                        ),
                    ),
                )

            def typed_region_value(value_id: int) -> SSAValue:
                return region_values.get(
                    int(value_id),
                    instruction_values.get(
                        int(value_id), SSAValue(int(value_id))
                    ),
                )

            # One SSA identity has one storage/dtype contract, but may have
            # several shaped views. Retype each occurrence independently so
            # reshape metadata is not collapsed by the id-keyed canonical
            # table. Target inference must see the authored view at each op.
            for instruction in instructions:
                instruction.args = [
                    _typed_region_occurrence(
                        value,
                        typed_region_value(value.id),
                        region_value_meta.get(int(value.id)),
                    )
                    for value in instruction.args
                ]
                if instruction.res is not None:
                    instruction.res = _typed_region_occurrence(
                        instruction.res,
                        typed_region_value(instruction.res.id),
                        region_value_meta.get(int(instruction.res.id)),
                    )

            # An aggregate formal IS the tuple of its member formals: its
            # ``Tuple`` constructor has no physical value.  Every projection
            # of it is aliased to a member, and a starred call argument
            # (``step(inputs, *tire_constants)``) is expanded by the linker
            # into those members, so a plan-level reference to the tuple id
            # is never a physical use.  A backend has no spelling for the
            # constructor and must not be asked for one: keep it only while
            # an instruction in this region consumes it, or it is itself an
            # authored function output.
            consumed_in_region = {
                int(argument.id)
                for instr in instructions
                for argument in instr.args
            }
            instructions = [
                instr for instr in instructions
                if not (
                    str(instr.op) in {"Tuple", "tuple"}
                    and instr.res is not None
                    and int(instr.res.id) not in consumed_in_region
                    and int(instr.res.id) not in authored_output_value_ids
                )
            ]
            produced = {
                int(instr.res.id)
                for instr in instructions
                if instr.res is not None
            }
            consumed = {
                int(argument.id)
                for instr in instructions
                for argument in instr.args
            }
            effective_captures = tuple(
                value_id
                for value_id in dict.fromkeys((
                    *effective_captures,
                    *region_free_value_ids(instructions),
                ))
                if (
                    value_id in region_inout_ids
                    or value_id in region_free_value_ids(instructions)
                )
            )
            # The resolved hierarchy plan owns the dependency calculation.
            # A region exports exactly the values crossing that boundary (plus
            # authored function results), never locally terminal temporaries.
            required_outputs = (
                resolved_plan_live_value_ids
                | set(control_dependency_value_ids(control))
                | authored_output_value_ids
                | set(map(int, required_output_value_ids))
                | set(map(
                    int,
                    (region_output_value_ids or {}).get(region_index, ()),
                ))
                | set(map(int, record_field_write_value_ids))
                # Program: ``xs = [2] * (n % 4 + 1)`` (fuzzer p3_54).  Wrong
                # record: the replication left the region as a recorded fill
                # that reads the count ``n % 4 + 1`` after the region, but
                # the count's only consumer had been the region's own Mul,
                # so nothing published it and the fill read an unproduced
                # formal (0 rows).  Rule: a value this region's recorded
                # table operations read crosses the region boundary.
                | {
                    value_id
                    for kind, arguments in _region_table_operations(
                        region_index,
                        table_region_operations,
                        table_region_post_operations,
                    )
                    for value_id in _table_operation_value_reads(
                        str(kind), tuple(arguments),
                    )
                }
            )
            # Captures cross from the authored control frame into a planned
            # region. Resolve them through the planning concordance before
            # either side's ABI is constructed. Otherwise an exact-return
            # helper can leave the region formal under its result spelling
            # while the caller has already resolved the same occurrence to
            # the returned argument spelling.
            capture_rebindings = {
                int(value_id): resident_root(int(value_id))
                for value_id in effective_captures
                if resident_root(int(value_id)) != int(value_id)
            }
            if capture_rebindings:
                for instruction in instructions:
                    instruction.args = [
                        SSAValue(
                            capture_rebindings[int(argument.id)],
                            dtype=argument.dtype,
                            shape=tuple(argument.shape or ()),
                            device=argument.device,
                            accounting=dict(argument.accounting or {}),
                        )
                        if int(argument.id) in capture_rebindings
                        else argument
                        for argument in instruction.args
                    ]
                effective_captures = tuple(dict.fromkeys(
                    resident_root(int(value_id))
                    for value_id in effective_captures
                ))

            # An IndexedStore versions resident memory: every version id in
            # ``region_value_aliases`` names the SAME storage as its root
            # arena.  A requirement on a version is therefore a requirement
            # on that storage, so the produced root is published; and the
            # required version is published AS ITSELF, because the version id
            # is the identity every later stage keys on (the identity ledger,
            # the structural-output recovery, ``emit_outputs`` and the call
            # linker all name a returned store chain by its final version).
            # This is exactly what the repository-call lowering of the same
            # store already does (``index_assign`` results are published next
            # to their arena).  Intermediate versions nothing requires stay
            # private.  A version whose root is a CAPTURE (a parameter or an
            # earlier region's arena written in place here) is not published:
            # the write is already visible through that storage, and a copied
            # output slot would turn an in/out write into a second value.
            # Dropping every aliased id silently removed each authored output
            # built by in-place slice stores (``surface_velocity = point *
            # 0.0; surface_velocity[..., 0] = ...``) from the region and then
            # from the function's Ret.
            required_roots = {
                resident_root(value_id) for value_id in required_outputs
            }
            # A canonical literal (one graph node, a known value) is owned
            # by the control function, which materializes it itself
            # (``_materialize_control_constants``).  The planner
            # rematerializes such a literal privately inside every region
            # that uses it; those copies are never that region's outputs.
            # Publishing them made four regions each define the one id
            # (``step_with_dt_control_used`` 342 x4).
            control_owned_literals = {
                int(instr.res.id)
                for instr in instructions
                if instr.res is not None
                and str(instr.op).casefold() in {"const", "constant"}
                and int(instr.res.id) in (constant_values or {})
            }
            outputs = tuple(sorted(
                value_id for value_id in produced
                if value_id not in control_owned_literals
                and (
                    (
                        value_id in required_outputs
                        and (
                            value_id not in region_value_aliases
                            or resident_root(value_id) in produced
                        )
                    )
                    or (
                        value_id in required_roots
                        and value_id not in region_value_aliases
                    )
                )
            ))
            # The region's formal parameters are its captures only. Its outputs
            # are declared as ``intent(out)`` dummies by the target from the
            # ``outputs`` map (returned below as ``section_outputs``), exactly as
            # the fused numerical region path does -- never by placing them in
            # ``args``, which would misread an output as an in/out alias.
            def region_argument(value_id: int) -> SSAValue:
                canonical = typed_region_value(value_id)
                occurrences = tuple(
                    argument
                    for instruction in instructions
                    for argument in instruction.args
                    if int(argument.id) == int(value_id)
                    and (
                        tuple(argument.shape or ())
                        or (argument.accounting or {}).get(
                            "program_abi_storage"
                        ) == "span"
                        or (argument.accounting or {}).get(
                            "tensor_metadata_state"
                        ) == "dynamic"
                    )
                )
                contracts = {
                    (
                        tuple(value.shape),
                        str(value.dtype or ""),
                        (value.accounting or {}).get("program_abi_storage"),
                        (value.accounting or {}).get("program_abi_rank"),
                        (value.accounting or {}).get("tensor_metadata_state"),
                        (value.accounting or {}).get("tensor_shape_value_id"),
                        (value.accounting or {}).get("tensor_rank_value_id"),
                        (value.accounting or {}).get(
                            "tensor_element_count_value_id"
                        ),
                    )
                    for value in occurrences
                }
                # A sole concrete use is the exact ordered region view. When
                # several reshapes share the storage id, keep the canonical
                # formal neutral; the individual op occurrences above retain
                # their own views.
                selected = occurrences[0] if len(contracts) == 1 else canonical
                if value_id in region_array_feed_ids.get(region_index, set()):
                    # ``region_array_feed_ids`` is derived from an exact
                    # indexed use of a projected iterable target.  The
                    # control caller supplies ``variant_row_values[target]``,
                    # a nested-row base address, so publish that same rank on
                    # the independently compiled region formal instead of
                    # leaving a scalar ABI beside GetElementPtr.
                    return SSAValue(
                        int(selected.id), dtype=selected.dtype,
                        shape=tuple(selected.shape or ()),
                        device=selected.device,
                        accounting={
                            **dict(selected.accounting or {}),
                            "ssa_call_rank": 1,
                            "nested_row_region_feed": int(region_index),
                        },
                    )
                return selected

            # Python integer arithmetic stays integer: a scalar result whose
            # operands are all integers and whose dtype is only the planner's
            # generic guess is an integer, decided here, once, before the
            # control caller and later regions read it (``n + k`` indexing
            # an array; its caller once loaded the int result as a double).
            integer_dtypes = {"int", "int64", "int32", "int16", "int8"}
            integer_ops = {
                "add", "sub", "mul", "floordiv", "mod", "neg",
                "min", "max", "abs",
            }
            declared_ids = {int(value_id) for value_id in (value_dtypes or {})}
            integer_results: dict[int, str] = {}
            for instruction in instructions:
                result = instruction.res
                if (
                    result is None
                    or str(instruction.op).casefold() not in integer_ops
                    or not instruction.args
                    or tuple(result.shape or ())
                    or int(result.id) in declared_ids
                    or str(result.dtype or "") in integer_dtypes
                ):
                    continue
                operand_dtypes = [
                    integer_results.get(int(argument.id), str(argument.dtype or ""))
                    for argument in instruction.args
                ]
                if all(
                    dtype in integer_dtypes and not tuple(argument.shape or ())
                    for dtype, argument in zip(operand_dtypes, instruction.args)
                ):
                    integer_results[int(result.id)] = "int64"
            if integer_results:
                for instruction in instructions:
                    values = [*instruction.args]
                    if instruction.res is not None:
                        values.append(instruction.res)
                    for value in values:
                        dtype = integer_results.get(int(value.id))
                        if dtype is not None:
                            value.dtype = dtype
                for value_id, dtype in integer_results.items():
                    if value_id in region_values:
                        region_values[value_id].dtype = dtype
                    previous = region_value_meta.get(value_id)
                    region_value_meta[value_id] = Meta(
                        () if previous is None else tuple(previous.shape),
                        dtype,
                    )
            # Each scalar result's dtype as this region computes it is the
            # fact later regions read for the same value.
            for instruction in instructions:
                result = instruction.res
                if (
                    result is None
                    or result.dtype is None
                    or tuple(result.shape or ())
                    or str(result.dtype) in {"ptr", "unknown"}
                ):
                    continue
                row = (str(tensor_shape_concordance_scope), int(result.id))
                if region_dtype_page.latest(row) != str(result.dtype):
                    # REVISE DERIVED(the value's canonical cell, the
                    # incumbent dtype cell): a later region's different
                    # dtype is a retype the audit sees.  A value with
                    # neither (a planned region's own result) stands on the
                    # control function's root, as its region signature does.
                    _post_derived_or_raw(
                        _book(), REGION_VALUE_DTYPE, row, str(result.dtype),
                        tuple(cell for cell in (
                            _book().latest_ref(REGION_VALUE_DTYPE, row),
                            _graph_cell(result.id),
                        ) if cell is not None) or (_function_root_cell(
                            _book(), str(tensor_shape_concordance_scope),
                        ),),
                        stage=CONTROL_SSA_REGION, mode=Mode.REVISE,
                    )
            effective_captures = _split_region_captures_by_binding(
                lexical_read_scope, tensor_shape_concordance_scope,
                region_index, instructions, effective_captures,
            )
            arguments = [region_argument(vid) for vid in effective_captures]
            region_function = Function(
                region_name,
                arguments,
                {"entry": BasicBlock("entry", instructions)},
            )
            # Construction adopts the authoritative mutable tile handles.
            # The publication Ret below and later feed refinements must write
            # this block, not the raw construction list it replaced.
            instructions = region_function.blocks["entry"].instrs
            arguments = region_function.args
            # A planned region is a compile-complementary source integral,
            # not an anonymous backend kernel.  Retain its deterministic
            # structural address so a bounded project compile can publish a
            # complete region even when the enclosing authored method still
            # needs Python object semantics.  The chain is deliberately
            # reversible text, not a digest or a process-local numeric ID.
            region_function.metadata["source_region_integral"] = {
                "schema": "turing.source-region-integral.v1",
                "owner": str(control_name),
                "plan_name": str(region.name),
                "region_index": int(region_index),
                "closure_id": int(region.closure_id),
                "identity_token_chain": (
                    "source-region",
                    str(control_name),
                    f"closure:{int(region.closure_id)}",
                    str(region.name),
                ),
                "capture_value_ids": tuple(map(int, effective_captures)),
                "output_value_ids": tuple(map(int, outputs)),
                # An in-place store publishes its result through the captured
                # arena, not through a copied return slot.  Keep the store's
                # own SSA identity in the integral receipt so the product
                # audit can distinguish an effect-only region from a dead
                # output-less arithmetic region without guessing from names
                # or from the caller's eventual backend spelling.
                **({"effect_value_ids": tuple(
                    int(instruction.res.id)
                    for instruction in instructions
                    if (
                        instruction.res is not None
                        and str(instruction.op).casefold()
                        == "indexedstore"
                    )
                )} if any(
                    instruction.res is not None
                    and str(instruction.op).casefold() == "indexedstore"
                    for instruction in instructions
                ) else {}),
            }
            region_function.metadata[
                "tensor_shape_concordance_scope"
            ] = tensor_shape_concordance_scope
            region_function.metadata["scalar_variant_argument_ids"] = tuple(
                sorted(
                    value_id
                    for value_id in variant_projected_target_ids
                    if value_id in effective_captures
                    and value_id not in region_array_feed_ids.get(
                        region_index, set()
                    )
                )
            )
            if os.environ.get("TURING_DEBUG_REGION_OUTPUTS"):
                print(
                    f"DEBUG-REGION-OUTPUTS {control_name} {region_name}: "
                    f"produced={sorted(produced)} outputs={outputs} "
                    f"required={sorted(required_outputs & produced)} "
                    f"req-sets={ {name: sorted(set(map(int, group)) & produced) for name, group in (('plan_live', resolved_plan_live_value_ids), ('control_dep', control_dependency_value_ids(control)), ('authored_out', authored_output_value_ids), ('required_out', required_output_value_ids), ('region_out', (region_output_value_ids or {}).get(region_index, ())), ('record_write', record_field_write_value_ids))} } "
                    f"aliases={ {k: v for k, v in region_value_aliases.items() if k in produced or v in produced} } "
                    f"instrs={[(str(i.op), [int(a.id) for a in i.args], None if i.res is None else int(i.res.id)) for i in instructions]}",
                    file=sys.stderr, flush=True,
                )
            functions[region_name] = region_function
            region_callees[region_index] = region_name
            region_signatures[region_index] = (
                tuple(int(vid) for vid in effective_captures),
                outputs,
            )
            if any(
                str(instruction.op).casefold() in {"store", "indexedstore"}
                for instruction in instructions
            ):
                region_writing_indices.add(int(region_index))
            signature_cell = _post_region_signature(
                _book(), str(tensor_shape_concordance_scope), lexical_read_scope,
                region_index, region_signatures[region_index],
            )
            _post_planned_region_identities(
                _book(), str(tensor_shape_concordance_scope), region_function,
                signature_cell, _graph_cell, shape_scope=shape_scope,
            )
            _concord_region_feed_consumers(
                lexical_read_scope, tensor_shape_concordance_scope,
                region_index, instructions, effective_captures,
            )
            region_feed_meta[region_index] = tuple(
                Meta(
                    tuple(argument.shape),
                    str(argument.dtype or "unknown"),
                    argument.device,
                )
                for argument in arguments
            )
            section_outputs[region_name] = tuple(
                typed_region_value(vid) for vid in outputs
            )
            if not any(instruction.op in {"Ret", "Br", "CondBr", "Switch", "IndirectBr"}
                       for instruction in instructions):
                # Region output maps serve legacy emitters, but repository
                # SSA consumers need an explicit publication terminator too.
                # Without it, C computes the result and returns without ever
                # writing the caller's output storage.
                definitions = {int(value.id): value for value in arguments}
                definitions.update({int(instruction.res.id): instruction.res
                                    for instruction in instructions if instruction.res is not None})
                instructions.append(Instr("Ret", [definitions[int(vid)] for vid in outputs], None))
            # Do NOT gate region ops on the repository ``Handler`` enum here: that
            # is the LLVM/repository vocabulary, but this path emits through the
            # selected target (Fortran), whose op set is broader -- e.g. it
            # renders ``equal`` as ``(a == b)`` though ``Handler`` only knows
            # ``Eq``. The target's own emit reports any op it genuinely cannot
            # express, with a message accurate to that target.
            report(
                f"region {region_index}: complete; "
                f"captures={len(effective_captures)} outputs={len(outputs)} "
                f"instructions={len(instructions)}"
            )
    compile_substage(f"SSA section {control_name}: settle control dependencies")
    report("settling control dependencies and lexical lookups")
    table_epilogue_operations: list[tuple[str, tuple[Any, ...]]] = []
    iterable_source_ids = {
        int(binding[0]) for binding in control.iterable_bindings
    }
    # Program: ``e = {}; for i in range(4): e[i] = i + n`` then ``del e[0];
    # len(e)`` (fuzzer p11_63; lanes plan C3).  Wrong record: the delete
    # keeps its authored id while the unrolled stores are minted after it,
    # so the value-order rule below put it before the region that carries
    # the first store, and it deleted from an empty table (4 for 3).  Rule:
    # a delete whose table version is a scheduled store follows that store.
    store_placements: dict[int, tuple[list, int]] = {}
    for operations_by_region in (
        table_region_operations, table_region_post_operations,
    ):
        for operations in operations_by_region.values():
            for position, (kind, arguments) in enumerate(operations):
                if kind == "store":
                    store_placements[int(arguments[0])] = (operations, position)
    control_placed_delete_ids = _control_placed_table_delete_ids(control.root)
    for deletion in table_deletions:
        effect_id = int(deletion[0])
        if effect_id in control_placed_delete_ids:
            continue
        # Every keyed delete is an authored control effect the shell
        # installs where its statement stands (``_install_lexical_sequence_
        # mutations``); one that no control block carries has no record to
        # place it by, and value order is not one.
        shortfalls.append(SSALoweringShortfall(
            "ssa-table", "unplaced-delete", control_name,
            f"delete {effect_id} is carried by no control block",
        ))
    table_epilogue_operations.extend(trailing_inplace_pack_operations)
    for destination_id, source_id, width_id, _consumed_ids in sequence_bit_packs:
        table_epilogue_operations.append((
            "pack_bits", (
                int(destination_id), int(source_id), int(width_id)
            ),
        ))
    # The control lowering mints synthetic values (aggregate handles, index
    # constants) for the region-call convention. They must not reuse a graph
    # value id, or a synthetic const collides with a field value the injection
    # below references by that same id. Start them above every graph id in play.
    graph_value_ids = [0, *known_value_ids]
    for history in (identity_table or {}).values():
        graph_value_ids.extend(int(value_id) for value_id in history)
    for expanded in expanded_plan_regions.values():
        for instruction in expanded:
            graph_value_ids.extend(int(value.id) for value in instruction.args)
            if instruction.res is not None:
                graph_value_ids.append(int(instruction.res.id))
    if os.environ.get("TURING_DEBUG_REGION_OUTPUTS"):
        print(f"DEBUG-REGION-WATERMARK {control_name}: graph_max={max(graph_value_ids)} "
              f"control_dep_max={max(map(int, control_dependency_value_ids(control)), default=-1)}",
              file=sys.stderr, flush=True)
    for feeds, outputs in region_signatures.values():
        graph_value_ids.extend(int(value_id) for value_id in feeds)
        graph_value_ids.extend(int(value_id) for value_id in outputs)
    graph_value_ids.extend(int(value_id) for _kind, value_id, _slot in field_ops)
    if self_value_id is not None:
        graph_value_ids.append(int(self_value_id))
    for value_id in set(value_dtypes or {}) | set(value_shapes or {}):
        value_id = int(value_id)
        existing = region_value_meta.get(value_id)
        region_value_meta[value_id] = Meta(
            tuple((value_shapes or {}).get(
                value_id,
                tuple(existing.shape or ()) if existing is not None else (),
            )),
            str(_region_value_dtype(value_id, value_dtypes, existing, control_name)),
            existing.device if existing is not None else None,
        )
    # Keep the hierarchy's pre-rewrite dataflow as scheduling authority.  A
    # structural region may disappear entirely into resident-sequence
    # operations and therefore never receive a numerical ``region_signature``;
    # its original instructions still say exactly which identities it consumes
    # and publishes.  Reading arbitrary integer leaves out of operation tuples
    # would conflate IDs with widths, slots, literals, and callsite numbers.
    region_dependency_signatures = {}
    item_operand_page = None
    if lexical_read_scope is not None:
        from .identity_concordance import current_identity_book

        item_operand_page = current_identity_book().page("item_operand")
    for region_index, instructions in planned_region_instructions.items():
        # Program: ``xs1 = [4, n]; xs1[0] += n; return xs1[0]`` (fuzzer
        # p25_25; corpus c273).  Wrong record: the store's region spelled
        # its index ``0`` as a local ``Const`` of graph id 3, and that local
        # was counted as produced, so the row load of ``xs1[0]`` (index 3)
        # depended on the store that consumes its sum: an order cycle
        # (loud).  Rule: a region's ``Const`` is its own spelling of a
        # literal, not a value it produces for anyone else.
        produced = tuple(dict.fromkeys(
            int(instruction.res.id)
            for instruction in instructions
            if instruction.res is not None
            and str(instruction.op) != "Const"
        ))
        produced_set = set(produced)
        consumed = tuple(dict.fromkeys(
            int(argument.id)
            for instruction in instructions
            for argument in instruction.args
            if int(argument.id) not in produced_set
        ))
        # A captured ``item()`` IS its operand's read (``item_operand``):
        # the region consumes the operand's producer too.  Matched by id
        # alone, ``float(x.item())`` had no dependency on the region
        # producing ``x`` and was scheduled before it
        # (``_propose_dt_pen``: ``float(maximum(ratios.max(), 1.0).item())``).
        if item_operand_page is not None:
            consumed = tuple(dict.fromkeys((
                *consumed,
                *(
                    int(item[0])
                    for value_id in consumed
                    for item in (item_operand_page.latest(
                        (tuple(lexical_read_scope), int(value_id))
                    ),)
                    if item is not None
                ),
            )))
        # A captured sequence-row load IS a read of its index and of its
        # sequence: the load is emitted lazily, at the first region that
        # asks for its result, so it is no block of its own.  Program:
        # ``xs = []; for ..: xs.append(..)`` then ``return xs[0] * 100 +
        # xs[len(xs) - 1]`` (scratch c136).  Wrong record: the region
        # consuming ``xs[17]`` had no dependency on the region producing
        # index 17 (``len(xs) - 1``), sorted ahead of it by its earlier
        # source column, and the load read the index before its definition
        # (the concordance's dominance finding; n=3 returned 0, not 4).
        consumed = tuple(dict.fromkeys((
            *consumed,
            *(
                int(read_id)
                for value_id in consumed
                for operation in (row_load_by_result.get(int(value_id)),)
                if operation is not None
                for read_id in (operation[1], operation[2])
                if read_id is not None
            ),
        )))
        region_dependency_signatures[int(region_index)] = (consumed, produced)

    def retained_lookup_ids(block):
        if isinstance(block, SequenceQueryBlock) and block.operation == "lookup":
            yield int(block.result_value_id)
        for child in getattr(block, "blocks", ()):
            yield from retained_lookup_ids(child)
        for name in ("condition", "body", "orelse", "callee"):
            child = getattr(block, name, None)
            if child is not None:
                yield from retained_lookup_ids(child)

    retained_table_lookup_ids = set(retained_lookup_ids(control.root))
    region_scheduled_lookup_ids = {
        int(operation[0])
        for operations in (
            *table_region_operations.values(),
            *table_region_post_operations.values(),
        )
        for kind, operation in operations
        if str(kind) in {"lookup", "lookup_capture"}
    }
    control, lexical_table_lookup_ids, lookup_refusals = (
        _install_loop_owned_table_queries(
            control,
            table_lookups,
            table_lookup_loop_owners or {},
            excluded_result_ids=region_scheduled_lookup_ids | retained_table_lookup_ids,
            globally_mutated_sequence_ids=(
                int(sequence_id)
                for _effect, _key, _value, sequence_id in table_stores
            ),
        )
    )
    lexical_table_lookup_ids = tuple(sorted(
        set(lexical_table_lookup_ids) | retained_table_lookup_ids
    ))
    shortfalls.extend(
        SSALoweringShortfall(
            "ssa-table", "lexical-lookup", control_name,
            f"lookup {result_id} cannot be placed: {reason}",
        )
        for result_id, reason in lookup_refusals
    )
    from .ir_identities import _PURE_REGION_OPS

    control, plan_callsite_bindings = _schedule_loop_callsites(
        control,
        hierarchy_plan,
        region_signatures,
        region_dependency_signatures,
        callsite_projection_ids=callsite_projection_ids,
        callsite_stored_argument_ids=callsite_stored_argument_ids,
        sequence_length_values=sequence_length_values,
        pure_region_indices=frozenset(
            index for index, instructions in planned_region_instructions.items()
            if all(instruction.op in _PURE_REGION_OPS for instruction in instructions)
            # The builder's _pure_region_index predicate: recorded table
            # operations are effects the planned instructions no longer show.
            and not _region_table_operations(
                index, table_region_operations, table_region_post_operations,
            )
        ),
        table_region_operations=table_region_operations,
        table_region_post_operations=table_region_post_operations,
    )
    # Uniform types describe a control use (for example an integer loop
    # bound), not authority to reinterpret an explicitly typed ABI buffer.
    # The same value can also feed tensor arithmetic. Preserve the declared
    # storage type at the coordinator just as region lowering does above.
    control = replace(control, uniforms=tuple(
        replace(uniform, dtype=str((value_dtypes or {}).get(
            int(uniform.value_id), uniform.dtype
        )))
        for uniform in control.uniforms
    ))
    report(
        f"control lowering start; region_functions={len(region_callees)}"
    )
    from .control_source import place_loop_carried_region_producers

    final_value_aliases = resolved_concordant_alias_bindings(
        control_name,
        region_value_aliases,
        control_value_concordance.alias_bindings(control_name),
        page=value_concordance,
    )
    tensor_shape_concordance = current_identity_book().page(
        "tensor_shape_concordance"
    )

    def final_resident(value_id: int) -> int:
        return int(final_value_aliases.get(int(value_id), int(value_id)))

    # IndexedStore is the numerical stage's exact proof that a result versions
    # resident tensor storage. Publish that storage contract for every
    # concorded spelling before lexical loop lowering temporarily rewrites
    # result-port aliases. A loop backedge can then recognize the resident as
    # a span even when no stage-local Meta uses the final loop-result id.
    for instructions in planned_region_instructions.values():
        for instruction in instructions:
            if (
                str(instruction.op).casefold() != "indexedstore"
                or not instruction.args
                or instruction.res is None
            ):
                continue
            base, result = instruction.args[0], instruction.res
            resident_id = final_resident(base.id)
            rank = max(
                len(tuple(base.shape or ())),
                len(tuple(result.shape or ())),
                int((base.accounting or {}).get("program_abi_rank", 0) or 0),
                int((result.accounting or {}).get(
                    "program_abi_rank", 0
                ) or 0),
            )
            contract = {
                "program_abi_storage": "span",
                "program_abi_rank": int(rank),
                "tensor_metadata_state": (
                    "static" if rank > 0 else "unknown"
                ),
                "shape": tuple(base.shape or result.shape or ()),
                "source": "planned-region-indexed-store",
            }
            spellings = (
                int(base.id), int(result.id), int(resident_id),
                *(
                    int(alias_id)
                    for alias_id, target_id in final_value_aliases.items()
                    if int(target_id) == resident_id
                ),
            )
            for value_id in dict.fromkeys(spellings):
                incumbent = tensor_shape_concordance.latest((
                    tensor_shape_concordance_scope, value_id,
                ))
                committed = dict(contract)
                if incumbent is not None:
                    committed = {
                        **contract,
                        **dict(incumbent),
                        "program_abi_storage": "span",
                        "program_abi_rank": max(
                            int(rank),
                            int(dict(incumbent).get(
                                "program_abi_rank", 0
                            ) or 0),
                        ),
                    }
                # REVISE DERIVED(the incumbent contract cell when merged
                # over one, the value's canonical cell); a value with
                # neither (a planned program's own value) stands on the
                # control function's root, as its region signature does.
                _post_derived_or_raw(
                    _book(), TENSOR_SHAPE_CONCORDANCE,
                    (tensor_shape_concordance_scope, value_id), committed,
                    tuple(cell for cell in (
                        _book().latest_ref(
                            TENSOR_SHAPE_CONCORDANCE,
                            (tensor_shape_concordance_scope, value_id),
                        ),
                        _graph_cell(value_id),
                    ) if cell is not None) or (_function_root_cell(
                        _book(), str(tensor_shape_concordance_scope),
                    ),),
                    stage=CONTROL_SSA_REGION, mode=Mode.REVISE,
                )
    control = place_loop_carried_region_producers(
        control,
        {
            region_index: tuple(
                int(instruction.res.id)
                for instruction in instructions
                if instruction.res is not None
            )
            for region_index, instructions in planned_region_instructions.items()
        },
        # Region results and loop-result nodes are transient spellings of the
        # same resident tensor after an in-place store.  This map has already
        # been merged with and resolved through planning_value_concordance;
        # schedule by that identity instead of comparing stage-local ids.
        value_aliases=final_value_aliases,
        lexical_read_scope=lexical_read_scope,
    )
    # A keyed Tensor lookup is materialized by the control function while its
    # numerical uses live in planned regions.  Commit the region's logical
    # rank claim under the lookup's exact value identity, then give that fact
    # to the control builder when it binds the selected child span.  The flat
    # child arena is not rank one merely because its storage is flat.
    region_value_ranks: dict[int, int] = {}
    for region_index, instructions in planned_region_instructions.items():
        for instruction in instructions:
            for value in (
                *instruction.args,
                *((instruction.res,) if instruction.res is not None else ()),
            ):
                value_id = int(value.id)
                if value_id not in table_lookup_result_ids:
                    continue
                rank = max(
                    len(tuple(value.shape or ())),
                    int((value.accounting or {}).get(
                        "program_abi_rank", 0
                    ) or 0),
                )
                # A selected child span's flat arena does not limit its
                # logical axes. `selected[:, index]` supplies two exact
                # index ports on Indexed's base, so its consumer requires
                # at least rank2 even when the Mapping[str, Tensor] schema
                # has only the default rank1. Carry that demand on the same
                # lookup identity into the existing shape concordance.
                if (instruction.op == "Indexed" and instruction.args
                        and int(instruction.args[0].id) == value_id):
                    rank = max(rank, len(instruction.args) - 1)
                if rank <= 0:
                    continue
                _post_derived_or_raw(
                    _book(), TENSOR_SHAPE_CONCORDANCE,
                    (tensor_shape_concordance_scope, value_id),
                    {
                        "program_abi_storage": "span",
                        "program_abi_rank": int(rank),
                        "tensor_metadata_state": "dynamic",
                        "tensor_shape_value_id": None,
                        "tensor_rank_value_id": None,
                        "tensor_element_count_value_id": None,
                        "source": "planned-region-rank",
                    },
                    (
                        _book().latest_ref(
                            TENSOR_SHAPE_CONCORDANCE,
                            (tensor_shape_concordance_scope, value_id),
                        ),
                        _graph_cell(value_id),
                    ),
                    stage=CONTROL_SSA_REGION, mode=Mode.REVISE,
                )
                region_value_ranks[value_id] = max(
                    int(rank), region_value_ranks.get(value_id, 0)
                )
    compile_substage(f"SSA section {control_name}: lower control program")
    control_function, control_shortfalls = lower_control_program_to_ssa(
        control,
        function_name=control_name,
        first_value_id=max(graph_value_ids) + 1,
        region_callees=region_callees,
        region_signatures=region_signatures,
        region_writing_indices=frozenset(region_writing_indices),
        region_feed_meta=region_feed_meta,
        region_value_meta=region_value_meta,
        region_value_ranks=region_value_ranks,
        tensor_shape_concordance_scope=tensor_shape_concordance_scope,
        lexical_read_scope=lexical_read_scope,
        planning_scope=planning_scope,
        source_value_descriptions=source_value_descriptions,
        shape_scope=shape_scope,
        plan_callsite_bindings=plan_callsite_bindings,
        value_aliases=final_value_aliases,
        inout_value_ids=tuple(map(int, record_field_write_value_ids)),
        constant_value_ids=tuple(map(int, constant_values or {})),
        none_value_ids=tuple(
            int(value_id)
            for value_id, literal in (constant_values or {}).items()
            if literal is None
        ),
        output_value_ids=tuple(map(int, required_output_value_ids)),
        named_output_histories={
            str(name): tuple(map(int, (identity_table or {}).get(name, ())))
            for name in function_outputs
        },
        value_name_histories=identity_table,
        parameter_names=function_parameters,
        sequence_initializations=sequence_initializations,
        sequence_declarations=sequence_declarations,
        sequence_column_dtypes=sequence_column_dtypes,
        sequence_record_identities=sequence_record_identities,
        sequence_child_table_layouts=sequence_child_table_layouts,
        sequence_row_record_slots=sequence_row_record_slots,
        source_sequence_ids=source_sequence_ids,
        dynamic_sequence_ids=dynamic_sequence_ids,
        sequence_memberships=sequence_memberships,
        table_lookups=table_lookups,
        lexical_table_lookup_result_ids=lexical_table_lookup_ids,
        table_lookup_defaults=table_lookup_defaults,
        table_lookup_required_ids=table_lookup_required_ids,
        table_stores=table_stores,
        table_deletions=table_deletions,
        retained_sequence_ids=retained_sequence_ids,
        nested_sequence_ids=nested_sequence_ids,
        nested_tensor_sequence_ids=nested_tensor_sequence_ids,
        joined_sequence_ids=joined_sequence_ids,
        joined_singleton_values=joined_singleton_values,
        nested_row_target_ids=tuple(sorted(
            nested_row_target_ids
        )),
        selected_nested_sequence_ids=tuple(sorted(
            selected_nested_sequence_ids
        )),
        variant_projected_target_ids=tuple(sorted(
            variant_projected_target_ids
        )),
        region_array_feed_ids={
            region: tuple(sorted(value_ids))
            for region, value_ids in region_array_feed_ids.items()
            if value_ids
        },
        nested_row_projections=nested_row_projections,
        sequence_length_values=sequence_length_values,
        resolved_sequence_schemas=resolved_sequence_schemas,
        table_region_operations={
            region: tuple(operations)
            for region, operations in table_region_operations.items()
        },
        table_region_post_operations={
            region: tuple(operations)
            for region, operations in table_region_post_operations.items()
        },
        table_epilogue_operations=tuple(table_epilogue_operations),
        consumer_row_loads=row_load_by_result,
        effect_preceding_row_reads=effect_preceding_row_reads,
        native_object_context=native_object_context,
        native_object_module=native_object_module,
        native_object_value_ids=native_object_value_ids,
        native_object_collections=native_object_collections,
        native_object_type_tests=native_object_type_tests,
        native_value_type_abi=native_value_type_abi,
        native_value_type_tests=native_value_type_tests,
    )
    report(
        f"control lowering complete; blocks={len(control_function.blocks)} "
        f"shortfalls={len(control_shortfalls)}"
    )
    control_function.metadata[
        "tensor_shape_concordance_scope"
    ] = tensor_shape_concordance_scope
    # The ProcessGraph owns this exact collection->iterable edge.  Publish it
    # before repository tensor lowering below; attaching it only after this
    # function returns makes dynamic collection extents invisible at the one
    # phase that must turn ``rows[:, j]`` into bounded index arithmetic.
    generated_capacity_sources = tuple(
        (
            int(instruction.attributes["scratch_sequence_id"]),
            int(instruction.attributes["sequence_id"]),
        )
        for block in control_function.blocks.values()
        for instruction in block.instrs
        if instruction.attributes.get("ssa_sequence_operation") == "sort"
        and instruction.attributes.get("scratch_sequence_id") is not None
        and instruction.attributes.get("sequence_id") is not None
    )
    control_function.metadata["sequence_capacity_sources"] = tuple(
        dict.fromkeys((
            *(
                (int(sequence_id), int(source_id))
                for sequence_id, source_id in sequence_capacity_sources
            ),
            *generated_capacity_sources,
        ))
    )
    debug_region_output_loads(control_function, "after-control-lowering")
    compile_substage(f"SSA section {control_name}: materialize constants and sequence helpers")
    report("materializing constants and sequence helpers")
    control_function = _materialize_control_constants(
        control_function,
        constant_values or {},
        value_dtypes=value_dtypes or {},
        constant_source_cells=constant_source_cells or {},
    )
    debug_region_output_loads(control_function, "after-constants")
    sequence_helpers, sequence_tables = _sequence_artifacts_from_control(
        control_function
    )
    control_sequence_table = sequence_tables.get(control_function.name)
    control_sequences = (
        dict(control_sequence_table.sequences)
        if control_sequence_table is not None else {}
    )
    sequence_field_slots: dict[int, int] = {}
    for _kind, value_id, slot in field_ops:
        if int(value_id) in control_sequences:
            sequence_field_slots[int(slot)] = int(value_id)
    for alias_slot, target_slot in field_aliases:
        if int(target_slot) in sequence_field_slots:
            sequence_field_slots[int(alias_slot)] = sequence_field_slots[
                int(target_slot)
            ]
    # Only fields this method actually touches belong to its scalar receiver
    # view. Sequence slots travel through their descriptors, while unrelated
    # class fields are neither dependencies nor native ABI parameters.
    declared_contracts = {
        str(name): dict(contract)
        for name, contract in dict(record_field_contracts or {}).items()
    }
    # Reference is a physical ABI storage class, not an untyped scalar.  A
    # static-reference write also proves that class for source-derived records;
    # an explicit ProgramABI declaration proves it even when this particular
    # method only reads the field or writes a value produced elsewhere.
    reference_slots = {
        int(slot) for slot, name in enumerate(field_names)
        if str((declared_contracts.get(name) or {}).get("storage") or "")
        == "reference"
    } | {
        int(slot)
        for kind, value_id, slot in field_ops
        if kind == "write"
        and isinstance((field_const_sources or {}).get(int(value_id)), Mapping)
        and (field_const_sources or {})[int(value_id)].get(
            "ssa_reference_identity"
        ) is not None
    }
    span_slots = {
        int(slot) for slot, name in enumerate(field_names)
        if str((declared_contracts.get(name) or {}).get("storage") or "")
        == "span"
    }
    # A nested record field is a descriptor correlation, never a slot: its
    # leaves are the physical storage (see ``nested_record_by_slot`` below).
    from .concordance_declarations import (
        CLASS_FIELD_DECLARATION, FIELD_SLOT_STORAGE,
    )
    from .frame_identity_book import (
        _frame_post, _frame_value_cell, _record_field_declaration_cell,
    )
    from .identity_concordance import current_identity_book

    nested_record_slots = set()
    for slot, identity, nested_value_id in nested_record_fields:
        slot_name = (
            str(field_names[int(slot)])
            if 0 <= int(slot) < len(field_names) else int(slot)
        )
        # The slot holds a nested record because the field is declared on its
        # owning class and the value stored there is that record instance:
        # read from the class field declaration and the value's own cell.
        declared_receiver = dict(
            dict(parameter_record_abi or {}).get("self") or {}
        )
        field_declaration_cell = _record_field_declaration_cell(
            declared_receiver, slot_name, identity=record_identity,
        )
        _frame_post(
            FIELD_SLOT_STORAGE, (str(control_function.name), slot_name),
            ("nested_record", str(identity)), stage=CONTROL_SSA_FINISH,
            cells=(
                _frame_value_cell(control_function, nested_value_id),
                field_declaration_cell,
            ),
        )
        nested_record_slots.add(int(slot))
    scalar_slots = tuple(sorted({
        int(slot)
        for _kind, _value_id, slot in field_ops
        if int(slot) not in sequence_field_slots
        and int(slot) not in span_slots
        and int(slot) not in nested_record_slots
    }))
    compact_slot = {slot: index for index, slot in enumerate(scalar_slots)}
    scalar_field_ops = tuple(
        (kind, value_id, compact_slot[slot])
        for kind, value_id, slot in field_ops
        if slot in compact_slot
    )
    # The reducer WRITTEN cell of each scalar ``"write"`` op, aligned with the
    # write ops of ``scalar_field_ops`` (empty when the shell supplied none).
    _write_ops = [op for op in field_ops if op[0] == "write"]
    scalar_write_state_cells = (
        tuple(
            cell for op, cell in zip(_write_ops, field_write_state_cells)
            if op[2] in compact_slot
        )
        if len(field_write_state_cells) == len(_write_ops) else ()
    )
    declared_field_dtypes = {
        str(name): str(dtype)
        for name, dtype in dict(record_field_dtypes or {}).items()
        if dtype is not None
    }
    scalar_dtypes = {
        declared_field_dtypes[name]
        for slot, name in enumerate(field_names)
        if slot in compact_slot and name in declared_field_dtypes
    }
    undeclared_scalar_fields = tuple(
        name for slot, name in enumerate(field_names)
        if slot in compact_slot
        and slot not in reference_slots
        and name not in declared_field_dtypes
    )
    if scalar_slots and declared_field_dtypes and undeclared_scalar_fields:
        raise ValueError(
            f"record scalar slot ABI lacks dtype in {control_function.name} "
            f"for record {record_identity!r}: "
            + ", ".join(undeclared_scalar_fields)
            + f"; declared={tuple(sorted(declared_field_dtypes))!r}"
        )
    # A receiver with no authored record declaration (``record_identity`` is
    # None) settles each scalar slot's dtype from the values its field
    # operations move: the read result / written value carry the settled
    # dtype in the function.  Disagreement or absence is a named refusal.
    _function_value_dtypes: dict[int, set[str]] = {}
    for _block in control_function.blocks.values():
        for _instruction in _block.instrs:
            for _value in (*_instruction.args, _instruction.res):
                if _value is not None and _value.dtype is not None:
                    _function_value_dtypes.setdefault(
                        int(_value.id), set()
                    ).add(str(_value.dtype))
    for _name in undeclared_scalar_fields:
        _slot = field_names.index(_name)
        _seen = set()
        for _kind, _value_id, _op_slot in field_ops:
            if int(_op_slot) == _slot:
                _seen |= _function_value_dtypes.get(int(_value_id), set())
        if len(_seen) != 1:
            raise ValueError(
                f"record scalar slot ABI lacks dtype in {control_function.name} "
                f"for record {record_identity!r}: field {_name!r}; its field "
                f"operations carry dtypes {tuple(sorted(_seen))!r}"
            )
        declared_field_dtypes[_name] = next(iter(_seen))
    scalar_dtypes = set(scalar_dtypes) | {
        declared_field_dtypes[name] for name in undeclared_scalar_fields
    }
    receiver_scalar_dtype = (
        sorted(scalar_dtypes)[0] if len(scalar_dtypes) == 1 else None
    )
    scalar_slot_dtypes = {
        compact_slot[old_slot]: (
            "opaque_ref" if old_slot in reference_slots
            else declared_field_dtypes[name]
        )
        for old_slot, name in enumerate(field_names)
        if old_slot in compact_slot
    }
    scalar_field_locations: dict[int, tuple[int, int, str]] = {}
    scalar_field_accounting = {
        compact_slot[old_slot]: {
            "program_abi_record": str(record_identity),
            "program_abi_parameter": "self",
            "program_abi_field": str(field_names[old_slot]),
            "program_abi_mutable": bool(
                (record_field_mutability or {}).get(field_names[old_slot], False)
            ),
            "program_abi_field_written": any(
                kind == "write" and int(slot) == int(old_slot)
                for kind, _value_id, slot in field_ops
            ),
        }
        for old_slot in scalar_slots
    }
    # Program: a method whose receiver holds scalar/reference field slots
    # (test_precompile_contract_rows.py, ``test_field_slot_columns_post_
    # their_physical_view``).  Wrong record: each slot's column carried
    # storage and rank 0 only in accounting.  Rule: a field slot's column
    # IS scalar (or, for a reference-handle slot, reference) at rank 0 by
    # construction -- the DECLARATION of the construct.  The injector posts
    # it with the class field declaration cell as a source and sets the
    # accounting FROM the posted fact.
    from .frame_identity_book import _record_field_declaration_cell as _decl
    _field_receiver = dict(
        dict(parameter_record_abi or {}).get("self") or {}
    )
    scalar_field_physical = {
        compact_slot[old_slot]: (
            {
                "storage": (
                    "reference" if old_slot in reference_slots else "scalar"
                ),
                "rank": 0,
            },
            (_decl(
                _field_receiver, str(field_names[old_slot]),
                identity=record_identity,
            ),),
        )
        for old_slot in scalar_slots
    }
    # ``self`` is a compile-time record correlation, not an opaque runtime
    # object.  When every field is already represented by explicit sequence
    # arenas, the receiver has no remaining scalar storage and must not become
    # an otherwise-unused ABI argument.  Method-call linking correlates the
    # authored receiver identity to the record descriptor and passes the field
    # arenas themselves.
    if (
        self_value_id is not None
        and record_identity is not None
        and not scalar_slots
        and not any(
            int(argument.id) == int(self_value_id)
            for block in control_function.blocks.values()
            for instruction in block.instrs
            for argument in instruction.args
        )
    ):
        control_function.args = [
            argument for argument in control_function.args
            if int(argument.id) != int(self_value_id)
        ]
    if self_value_id is not None and scalar_slots:
        non_self_parameters = tuple(
            (str(name), int((identity_table or {})[name][0]))
            for name in function_parameters
            if name != "self" and (identity_table or {}).get(name)
        )
        non_self_param_ids = tuple(
            value_id for _name, value_id in non_self_parameters
        )
        output_value_ids = tuple(
            int((identity_table or {}).get(name, (None,))[-1])
            for name in function_outputs
            if (identity_table or {}).get(name)
        )
        control_function, scalar_field_locations = _inject_field_slot_access(
            control_function,
            self_value_id=int(self_value_id),
            non_self_param_ids=non_self_param_ids,
            non_self_parameters=non_self_parameters,
            field_ops=scalar_field_ops,
            field_write_state_cells=scalar_write_state_cells,
            lexical_read_scope=lexical_read_scope,
            field_const_sources=field_const_sources or {},
            field_count=len(scalar_slots),
            output_value_ids=output_value_ids,
            dtype=receiver_scalar_dtype,
            field_dtypes=scalar_slot_dtypes,
            separate_field_storage=bool(declared_contracts),
            field_accounting=scalar_field_accounting,
            field_physical=scalar_field_physical,
            receiver_accounting=(
                {
                    "program_abi_record": str(record_identity),
                    "program_abi_parameter": "self",
                }
                if record_identity is not None else None
            ),
        )
        # Field injection rebuilds the function but preserves its sequence
        # metadata, so refresh the table/function correlation after rewriting.
        sequence_helpers, sequence_tables = _sequence_artifacts_from_control(
            control_function
        )
    functions[control_function.name] = control_function
    functions.update(sequence_helpers)
    _settle_child_pool_operation_dtypes(functions, sequence_tables)
    from .ir_sequence_tables import lower_sequence_aggregate_constants

    lower_sequence_aggregate_constants(functions, sequence_tables)
    # Tensor SSA gets first refusal on shaped subscripts below.  Any scalar
    # Indexed/IndexedStore operations left afterward become universal address
    # primitives; doing that here erased the tensor selection before its
    # repository kernel could see it.
    # Tokenize every string constant to its universal fnv1a token before
    # emission, so a word is a 64-bit value the target expresses like any other
    # constant instead of an inexpressible literal.
    from .ir_string_interning import tokenize_ssa_string_constants

    tokenize_ssa_string_constants(functions, string_table)
    # Section composition and field/index materialization can reconstruct
    # SSAValue wrappers after the control builder's own finish boundary.  Run
    # the same CFG-proven LoopResult reconciliation at the completed section
    # boundary, where every final scalar expression and zero-trip edge exists.
    for function in functions.values():
        rebindings = _canonicalize_non_dominating_loop_result_uses(function)
        if rebindings:
            function.metadata["loop_result_use_rebindings"] = tuple((
                *function.metadata.get("loop_result_use_rebindings", ()),
                *rebindings,
            ))
    compile_substage(f"SSA section {control_name}: materialize record and reference tables")
    report("materializing record and reference tables")
    record_tables = {}
    if record_identity is not None and field_names:
        from ..transmogrifier.ssa import (
            SSARecordDescriptor,
            SSARecordFieldDescriptor,
            SSARecordFieldStorage,
            SSARecordTable,
        )

        record_fields = []
        nested_record_by_slot = {
            int(slot): (str(identity), int(value_id))
            for slot, identity, value_id in nested_record_fields
        }
        alias_targets = {int(alias): int(target) for alias, target in field_aliases}
        declared_mutability = {
            str(name): bool(mutable)
            for name, mutable in dict(record_field_mutability or {}).items()
        }
        span_field_values = {
            int(slot): int(value_id)
            for kind, value_id, slot in field_ops
            if kind == "read" and int(slot) in span_slots
        }
        for old_slot, name in enumerate(field_names):
            canonical_slot = alias_targets.get(old_slot, old_slot)
            canonical_name = (
                field_names[canonical_slot]
                if 0 <= canonical_slot < len(field_names)
                else name
            )
            storage_identity = f"{record_identity}.{canonical_name}"
            sequence_id = sequence_field_slots.get(old_slot)
            nested_record = nested_record_by_slot.get(old_slot)
            if nested_record is not None:
                nested_identity, nested_value_id = nested_record
                record_fields.append(SSARecordFieldDescriptor(
                    name,
                    SSARecordFieldStorage.RECORD,
                    storage_identity=storage_identity,
                    # The nested record id is a descriptor correlation, not a
                    # physical SSA value.  Its leaf fields name the actual
                    # caller-owned arenas.
                    value_ids=(),
                    record_id=nested_value_id,
                    dtype=nested_identity,
                ))
            elif sequence_id is not None:
                descriptor = control_sequences[sequence_id]
                value_ids = (
                    *descriptor.column_value_ids,
                    descriptor.length_address_id,
                    descriptor.capacity_value_id,
                    *((descriptor.status_address_id,) if descriptor.status_address_id is not None else ()),
                    *((descriptor.live_flags_value_id,) if descriptor.live_flags_value_id is not None else ()),
                    *(
                        (
                            *descriptor.child_table_pool.column_value_ids,
                            descriptor.child_table_pool.length_value_id,
                            descriptor.child_table_pool.capacity_value_id,
                            descriptor.child_table_pool.row_stride_value_id,
                            *((descriptor.child_table_pool.shape_value_id,)
                              if descriptor.child_table_pool.shape_value_id is not None else ()),
                            *((descriptor.child_table_pool.rank_value_id,)
                              if descriptor.child_table_pool.rank_value_id is not None else ()),
                            *((descriptor.child_table_pool.shape_stride_value_id,)
                              if descriptor.child_table_pool.shape_stride_value_id is not None else ()),
                            *((descriptor.child_table_pool.status_value_id,)
                              if descriptor.child_table_pool.status_value_id is not None else ()),
                            *((descriptor.child_table_pool.live_flags_value_id,)
                              if descriptor.child_table_pool.live_flags_value_id is not None else ()),
                        )
                        if descriptor.child_table_pool is not None else ()
                    ),
                )
                record_fields.append(SSARecordFieldDescriptor(
                    name,
                    SSARecordFieldStorage.SEQUENCE,
                    storage_identity=storage_identity,
                    value_ids=tuple(dict.fromkeys(map(int, value_ids))),
                    sequence_id=sequence_id,
                    writable=descriptor.writable,
                ))
            elif old_slot in span_field_values:
                contract = declared_contracts.get(name) or {}
                record_fields.append(SSARecordFieldDescriptor(
                    name,
                    SSARecordFieldStorage.SPAN,
                    storage_identity=storage_identity,
                    value_ids=(span_field_values[old_slot],),
                    dtype=contract.get("dtype"),
                    writable=bool(declared_mutability.get(name, False)),
                ))
            elif old_slot in compact_slot and self_value_id is not None:
                field_dtype = declared_field_dtypes.get(name)
                record_fields.append(SSARecordFieldDescriptor(
                    name,
                    (
                        SSARecordFieldStorage.REFERENCE
                        if old_slot in reference_slots
                        else SSARecordFieldStorage.SCALAR
                    ),
                    storage_identity=storage_identity,
                    value_ids=(scalar_field_locations[compact_slot[old_slot]][0],),
                    offset=(
                        None if declared_contracts else
                        scalar_field_locations[compact_slot[old_slot]][1]
                    ),
                    dtype=(
                        "opaque_ref"
                        if old_slot in reference_slots else field_dtype
                    ),
                    writable=bool(declared_mutability.get(name, False)),
                ))
        if record_fields:
            from .concordance_declarations import CLASS_FIELD_DECLARATION
            from .identity_concordance import current_identity_book

            record_id = int(
                self_value_id
                if self_value_id is not None
                else max(graph_value_ids) + 1
            )
            descriptor = SSARecordDescriptor(
                record_id, record_identity, tuple(record_fields),
            )
            book = current_identity_book()
            declared_record = next((
                dict(receipt)
                for receipt in dict(parameter_record_abi or {}).values()
                if str(receipt.get("identity") or "")
                == str(record_identity or "")
            ), {})
            from .frame_identity_book import _record_field_declaration_cell

            declaration_cells = tuple(
                _record_field_declaration_cell(
                    declared_record, field.name, identity=record_identity,
                )
                for field in record_fields
            )
            value_scope = control_function.metadata.get(
                "tensor_shape_concordance_scope"
            )

            def member_cell(value_id: int) -> Ref | None:
                cell = book.latest_ref(
                    SSA_VALUE, (str(value_scope), int(value_id)),
                )
                if (
                    cell is None
                    and self_value_id is not None
                    and int(value_id) == int(self_value_id)
                ):
                    # The receiver column (``_inject_field_slot_access``'s
                    # arena 0) IS the receiver's id.  Its ``ssa_value`` row
                    # is the parameter seed when the receiver was named a
                    # parameter; when it was not, the slot mints stood on
                    # the function root instead, and so does the record
                    # read through them.
                    cell = _function_root_cell(book, str(value_scope))
                return cell

            member_cells = tuple(
                member_cell(value_id)
                for field in record_fields
                for value_id in field.value_ids
                if value_scope is not None
            )
            sources = tuple(dict.fromkeys(
                cell for cell in (*declaration_cells, *member_cells)
                if cell is not None
            ))
            table = SSARecordTable(owner=control_function.name)
            table.register(
                descriptor,
                sources=sources,
                stage=CONTROL_SSA_FINISH,
            )
            record_tables[control_function.name] = table
    from ..transmogrifier.ssa import (
        SSAReferenceDescriptor,
        SSAReferenceKind,
        SSAReferenceTable,
    )

    reference_table = SSAReferenceTable()
    for function in functions.values():
        for block in function.blocks.values():
            for instruction in block.instrs:
                if instruction.op != Handler.StaticRef.value:
                    continue
                attributes = instruction.attributes
                reference_table.register(SSAReferenceDescriptor(
                    int(attributes["reference_handle"]),
                    str(attributes["reference_identity"]),
                    SSAReferenceKind(attributes.get(
                        "reference_kind", "static-python"
                    )),
                    bool(attributes.get("host_resident", False)),
                ))
    # A planned region that captures a resident sequence arena may perform
    # rank-aware indexing whose leading extent is the sequence's live length.
    # Make that cell an ordinary ABI operand before tensor lowering.  The
    # sequence descriptor is the authority for the correlation; calls and
    # formals are extended together, so no stage-local ID comparison is used.
    compile_substage(f"SSA section {control_name}: propagate sequence ABI members")
    report("propagating sequence ABI members")
    control_sequences = sequence_tables.get(control_function.name)
    if control_sequences is not None:
        from .concordance_declarations import (
            SEQUENCE_CONTRACT_CONCORDANCE as _SEQUENCE_CONTRACT_PAGE,
        )
        from .identity_concordance import current_identity_book
        from .ssa_record_return_state import revise_ssa_value

        _control_book = current_identity_book()
        for region_function in functions.values():
            receipt = (
                region_function.metadata or {}
            ).get("source_region_integral") or {}
            if str(receipt.get("owner") or "") != control_function.name:
                continue
            additions: list[tuple[int, int]] = []
            existing_ids = {int(value.id) for value in region_function.args}
            for argument in tuple(region_function.args):
                accounting = dict(argument.accounting or {})
                storage_view = accounting.get("ssa_storage_view") or {}
                candidate_ids = {
                    int(argument.id),
                    final_resident(int(argument.id)),
                    *(
                        (int(accounting["ssa_storage_alias"]),)
                        if accounting.get("ssa_storage_alias") is not None
                        else ()
                    ),
                    *(
                        (int(storage_view["storage_value_id"]),)
                        if storage_view.get("storage_value_id") is not None
                        else ()
                    ),
                }
                descriptors = {
                    descriptor.sequence_id: descriptor
                    for candidate_id in candidate_ids
                    for descriptor in (
                        control_sequences.by_id(candidate_id),
                    )
                    if descriptor is not None
                }
                for candidate_id in candidate_ids:
                    claims = tuple(control_sequences.member_claims(candidate_id))
                    sequence_ids = {
                        int(sequence_id)
                        for sequence_id, role in claims
                        if tuple(role) == ("column", 0)
                    }
                    descriptors.update({
                        sequence_id: control_sequences.by_id(sequence_id)
                        for sequence_id in sequence_ids
                        if control_sequences.by_id(sequence_id) is not None
                    })
                if len(descriptors) != 1:
                    continue
                descriptor = next(iter(descriptors.values()))
                if len(descriptor.column_value_ids) == 1:
                    # The length cell and the row layout are two parts of one
                    # sequence descriptor.  Planned regions previously
                    # received the former while their arena formal lost the
                    # latter, leaving an exact N-by-W sequence looking like a
                    # rankless scalar to tensor lowering.  Publish the
                    # descriptor receipt on that same formal; no new storage
                    # or reconstructed identity is introduced.
                    row_shape = tuple(
                        (descriptor.column_shapes or ((),))[0]
                    )
                    # Program: a planned region capturing a resident N-by-W
                    # sequence arena (test_precompile_contract_rows.py,
                    # ``test_region_sequence_arena_formal_posts_span_rank``).
                    # Wrong record: the formal's ``ssa_value`` row carried no
                    # storage/rank while accounting said span, 1 + len(row).
                    # Rule: the rank is read from the sequence descriptor, so
                    # the formal's row is REVISED DERIVED from the
                    # descriptor's ``sequence_contract_concordance`` cell and
                    # the accounting is set FROM the posted fact.
                    _descriptor_cells = tuple(
                        cell for cell in (
                            _control_book.latest_ref(
                                _SEQUENCE_CONTRACT_PAGE,
                                (_scope, int(descriptor.sequence_id)),
                            )
                            for _scope in (
                                control_function.name,
                                str(control_function.metadata.get(
                                    "tensor_shape_concordance_scope"
                                ) or control_function.name),
                            )
                        ) if cell is not None
                    )
                    # Program: ``xs = [5, n, 2]; xs[0] = 7`` (scratch
                    # c140).  Wrong record: this revise wrote the formal's
                    # planner capture guess (float64) into the arena's row,
                    # which region formals share with the control function,
                    # overwriting the int64 its appends concorded.  Rule:
                    # the arena formal's element type is read from the same
                    # descriptor as its rank.
                    _column_dtype = str(
                        (descriptor.column_dtypes or ("unknown",))[0]
                    )
                    if (
                        descriptor.heap_owner_value_id is None
                        and _column_dtype not in {"", "None", "unknown"}
                    ):
                        argument.dtype = _column_dtype
                    elif (
                        descriptor.heap_owner_value_id is not None
                        and _column_dtype not in {"", "None", "unknown", "ptr"}
                    ):
                        # A heap-owned arena enters the region as its pointer
                        # CELL (``sum(collect(n))``, scratch c116: the region
                        # read the cell as rows).  The formal carries the
                        # descriptor's heap element layout.
                        from ..transmogrifier.dtype_layout import layout_for

                        # The region only reads the rows: it carries the
                        # element layout, not the owner (which is no value
                        # of the region; growth stays with the caller).
                        argument.dtype = "ptr"
                        accounting = {
                            key: entry for key, entry in accounting.items()
                            if key != "heap_owner_value_id"
                        }
                        accounting["heap_element_dtype"] = layout_for(
                            _column_dtype
                        ).name
                        argument.accounting = dict(accounting)
                    # Program: ``add_all(a, b)`` over caller lists (c196) and
                    # the string-core ``repeated_manager`` audit.  Wrong
                    # record: region formals share the control function's
                    # row, which already posted this resident arena as
                    # ``sequence`` (SEQUENCE_CONTRACT owns a resident
                    # collection's physical kind); the hard-coded ``span``
                    # overwrote it and the ABI arm disagreed.  Rule: a row
                    # that already declares ``sequence`` keeps it; ``span``
                    # is posted only where nothing declared a kind.
                    from .ssa_record_return_state import (
                        function_scope_of as _formal_row_scope,
                    )
                    _posted_arena = _control_book.latest_ref(
                        SSA_VALUE, (_formal_row_scope(region_function), int(argument.id)),
                    )
                    _posted_fact = (
                        None if _posted_arena is None
                        else _control_book.page(SSA_VALUE).cell(
                            _posted_arena.row, _posted_arena.column,
                        )
                    )
                    # The kind is read, in order, from the row's own posted
                    # storage, then from the descriptor's SEQUENCE_CONTRACT
                    # cell (a region reads a column arena as the contiguous
                    # ``span`` its rank is taken from).  With neither record
                    # there is nothing to derive it from, so it is refused.
                    _arena_formal_storage = getattr(
                        _posted_fact, "storage", None,
                    )
                    if _arena_formal_storage not in {"sequence", "span"}:
                        _arena_formal_storage = None
                    if _arena_formal_storage is None:
                        if not _descriptor_cells:
                            raise ValueError(
                                "region sequence arena formal "
                                f"{int(argument.id)} of {region_function.name} "
                                "has neither a posted storage kind nor a "
                                "sequence contract cell to derive it from"
                            )
                        _arena_formal_storage = "span"
                    _formal_cell = revise_ssa_value(
                        region_function, int(argument.id),
                        dtype=argument.dtype,
                        shape=tuple(argument.shape or ()),
                        stage=CONTROL_SSA_REGION,
                        sources=_descriptor_cells, book=_control_book,
                        physical={
                            "storage": _arena_formal_storage,
                            "rank": 1 + len(row_shape),
                        },
                    )
                    _formal_fact = (
                        None if _formal_cell is None
                        else _control_book.page(SSA_VALUE).cell(
                            _formal_cell.row, _formal_cell.column,
                        )
                    )
                    argument.accounting = {
                        **accounting,
                        "sequence_id": int(descriptor.sequence_id),
                        "sequence_row_shape": row_shape,
                        **(
                            {
                                "program_abi_storage": _formal_fact.storage,
                                "program_abi_rank": _formal_fact.rank,
                            }
                            if isinstance(_formal_fact, SSAValueFact)
                            and _formal_fact.storage is not None else {}
                        ),
                        "tensor_metadata_state": "dynamic",
                    }
                length_id = int(descriptor.length_address_id)
                if length_id in existing_ids:
                    continue
                existing_ids.add(length_id)
                region_function.args.append(SSAValue(
                    length_id,
                    dtype="int64",
                    shape=(1,),
                    accounting={
                        "sequence_length_for": int(descriptor.sequence_id),
                        "compiler_frame_storage": control_function.name,
                    },
                ))
                additions.append((int(descriptor.sequence_id), length_id))
            if not additions:
                continue
            for caller in functions.values():
                for caller_block in caller.blocks.values():
                    for call_instruction in caller_block.instrs:
                        if (
                            call_instruction.op not in {"Call", "call"}
                            or str(call_instruction.attributes.get("callee"))
                            != region_function.name
                        ):
                            continue
                        present = {
                            int(value.id) for value in call_instruction.args
                        }
                        appended = [
                            SSAValue(
                                length_id,
                                dtype="int64",
                                shape=(1,),
                                accounting={
                                    "sequence_length_for": sequence_id,
                                    "compiler_frame_storage": (
                                        control_function.name
                                    ),
                                },
                            )
                            for sequence_id, length_id in additions
                            if length_id not in present
                        ]
                        call_instruction.args.extend(appended)
                        if appended:
                            attributes = dict(call_instruction.attributes)
                            # Program: ``out = []`` filled by a callee, then
                            # ``len(xs) * 100 + sum(xs)`` (scratch c116).
                            # Wrong record: appending the length cell changed
                            # the calling block's geometry with no new cause,
                            # and the geometry post was refused.  Rule: the
                            # region's signature gains the feed, REVISED from
                            # the sequence contract cells that require it;
                            # block geometry names that signature.
                            region_index = attributes.get("region_index")
                            if region_index is not None:
                                previous_signature = region_signatures.get(
                                    int(region_index)
                                )
                                if previous_signature is not None:
                                    revised_feeds = (
                                        *tuple(previous_signature[0]),
                                        *(
                                            int(value.id) for value in appended
                                            if int(value.id)
                                            not in previous_signature[0]
                                        ),
                                    )
                                    region_signatures[int(region_index)] = (
                                        revised_feeds, previous_signature[1],
                                    )
                                    signature_sources = tuple(
                                        cell for cell in (
                                            _control_book.latest_ref(
                                                _SEQUENCE_CONTRACT_PAGE,
                                                (_scope, int(sequence_id)),
                                            )
                                            for sequence_id, _length in additions
                                            for _scope in (
                                                control_function.name,
                                                str(tensor_shape_concordance_scope),
                                            )
                                        ) if cell is not None
                                    ) or (_function_root_cell(
                                        _control_book,
                                        str(tensor_shape_concordance_scope),
                                    ),)
                                    _control_book.post(
                                        REGION_SIGNATURE,
                                        (
                                            str(tensor_shape_concordance_scope),
                                            int(region_index),
                                        ),
                                        RegionSignature(
                                            tuple(map(int, revised_feeds)),
                                            tuple(map(int, previous_signature[1])),
                                        ),
                                        stage=CONTROL_SSA_REGION,
                                        provenance=Derived(signature_sources),
                                        mode=Mode.REVISE,
                                    )
                            if "feed_ids" in attributes:
                                attributes["feed_ids"] = (
                                    *tuple(attributes["feed_ids"]),
                                    *(int(value.id) for value in appended),
                                )
                            if "feed_shapes" in attributes:
                                attributes["feed_shapes"] = (
                                    *tuple(attributes["feed_shapes"]),
                                    *((1,) for _value in appended),
                                )
                            if "feed_dtypes" in attributes:
                                attributes["feed_dtypes"] = (
                                    *tuple(attributes["feed_dtypes"]),
                                    *("int64" for _value in appended),
                                )
                            call_instruction.attributes = attributes
    # Every function this lowering produced -- the control function and its
    # planned regions -- states shapes for the graph COPY it was lowered
    # from (``identity_concordance.shape_scope_of``).
    if shape_scope is not None:
        for _stamped in functions.values():
            if _stamped.metadata.get("ssa_sequence_operation"):
                # A returned statuses list is unresolved when its replace
                # helper is born. The helper's descriptor formals are its
                # own SSA rows, not graph projection38: inheriting the
                # owner's shape scope completed them from that projection's
                # provisional float64 before the int64 return was linked.
                # Sequence helpers have no graph copy; their descriptor and
                # exact call bindings own their physical element layout.
                continue
            _stamped.metadata.setdefault("shape_scope", tuple(shape_scope))
    compile_substage(f"SSA section {control_name}: assemble repository module")
    module = IRModule(
        link_required_ssa_features(functions),
        recursion_table={
            name: dict(function.metadata.get("recursion_table", {}))
            for name, function in functions.items()
            if function.metadata.get("recursion_table")
        },
        sequence_tables=sequence_tables,
        record_tables=record_tables,
        value_union_tables={
            name: table
            for name, function in functions.items()
            for table in (function.metadata.get("value_union_table"),)
            if table is not None and dict(table.unions)
        },
        reference_tables=(
            {control_function.name: reference_table}
            if reference_table.references else {}
        ),
    )
    tensor_reference_shortfalls = ()
    if tensor_ssa_reference is not None:
        from .tensor_ssa_lowering import (
            legalize_aggregate_adapters,
            lower_tensor_calls_to_repository_ssa,
            propagate_repository_ssa_call_metadata,
        )

        report(
            f"tensor repository linking start; functions={len(module.functions)}"
        )
        tensor_reference_shortfalls = tuple(
            SSALoweringShortfall(
                "tensor-ssa-reference",
                item.operation,
                f"{item.function}:{item.block}",
                item.reason,
            )
            for item in lower_tensor_calls_to_repository_ssa(
                module, tensor_ssa_reference
            )
        )
        report(
            "tensor repository linking complete; "
            f"shortfalls={len(tensor_reference_shortfalls)}"
        )
    from .ir_indexing import lower_indexing_to_ssa_addressing

    compile_substage(f"SSA section {control_name}: lower addressing and aggregate adapters")
    report("lowering addressing and aggregate adapters")
    lower_indexing_to_ssa_addressing(module.functions)
    if tensor_ssa_reference is not None and legalize_aggregate_adapters(module):
        propagate_repository_ssa_call_metadata(module)
    # Tensor/reference linking and aggregate legalization are allowed to
    # settle an element operation's physical dtype.  Reconcile child-pool
    # arenas only after those final section rewrites, so the descriptor and
    # its ABI formal receive the exact dtype owned by the completed Load/Store
    # rather than the provisional dtype visible during control construction.
    _settle_child_pool_operation_dtypes(
        module.functions, module.sequence_tables,
    )
    report(
        f"complete; functions={len(module.functions)} "
        f"shortfalls={len(shortfalls) + len(control_shortfalls) + len(tensor_reference_shortfalls)}"
    )
    if instruction_pool is not None:
        control_function.metadata["region_instruction_residency"] = {
            "schema": "turing.region-instruction-residency.v1",
            "limit": instruction_pool.limit, **instruction_pool.stats,
        }
        instruction_pool.close()
    return module, tuple((
        *shortfalls,
        *control_shortfalls,
        *tensor_reference_shortfalls,
    )), section_outputs


def link_verified_source_region_integrals(
    module: IRModule,
    outputs: dict[str, tuple[SSAValue, ...]],
    linked_regions: Mapping[
        tuple[str, ...], tuple[IRModule, Mapping[str, tuple[SSAValue, ...]], Mapping[str, Any]]
    ],
) -> tuple[dict[str, Any], ...]:
    """Install receipt-matched region SSA, retaining current lowering fallback.

    Region token chains are the structural identity.  Integer value IDs are
    checked only as the already-deterministic physical ABI within that named
    compartment; they are never remapped. A stale or unverified candidate is
    ignored and the freshly lowered source region remains authoritative.
    """

    receipts = []

    def value_contract(values: Iterable[SSAValue]) -> tuple[tuple[Any, ...], ...]:
        return tuple(
            (
                int(value.id), tuple(value.shape or ()),
                str(value.dtype or "unknown"), dict(value.accounting or {}),
            )
            for value in values
        )

    scoped_tables = (
        "recursion_table", "deployment_table", "tensor_tables",
        "sequence_tables", "record_tables", "value_union_tables",
        "reference_tables", "call_table",
    )
    for function_name, current in tuple(module.functions.items()):
        provenance = dict(current.metadata.get("source_region_integral") or {})
        token_chain = tuple(map(
            str, provenance.get("identity_token_chain") or ()
        ))
        if not token_chain or token_chain not in linked_regions:
            continue
        linked_module, linked_outputs, verification = linked_regions[token_chain]
        record = {
            "ssa_function": str(function_name),
            "identity_token_chain": list(token_chain),
            "status": "fallback",
        }
        if verification.get("status") != "verified":
            record["reason"] = "candidate-is-not-verified"
            receipts.append(record)
            continue
        if tuple(map(
            str, verification.get("identity_token_chain") or ()
        )) != token_chain:
            record["reason"] = "verification-identity-mismatch"
            receipts.append(record)
            continue
        candidate = linked_module.functions.get(str(function_name))
        candidate_outputs = tuple(linked_outputs.get(str(function_name), ()))
        current_outputs = tuple(outputs.get(str(function_name), ()))
        if candidate is None:
            record["reason"] = "candidate-function-is-absent"
            receipts.append(record)
            continue
        if value_contract(candidate.args) != value_contract(current.args):
            record["reason"] = "input-abi-mismatch"
            receipts.append(record)
            continue
        if value_contract(candidate_outputs) != value_contract(current_outputs):
            record["reason"] = "output-abi-mismatch"
            receipts.append(record)
            continue
        candidate_provenance = dict(
            candidate.metadata.get("source_region_integral") or {}
        )
        if tuple(map(
            str, candidate_provenance.get("identity_token_chain") or ()
        )) != token_chain:
            record["reason"] = "candidate-provenance-mismatch"
            receipts.append(record)
            continue
        module.functions[str(function_name)] = candidate
        outputs[str(function_name)] = candidate_outputs
        for table_name in scoped_tables:
            destination = getattr(module, table_name)
            source = getattr(linked_module, table_name)
            if str(function_name) in source:
                destination[str(function_name)] = source[str(function_name)]
            else:
                destination.pop(str(function_name), None)
        record["status"] = "linked"
        record["probe_count"] = int(verification.get("probe_count") or 0)
        receipts.append(record)
    if receipts:
        module.metadata["linked_source_region_integrals"] = tuple(receipts)
    return tuple(receipts)


def lower_precompile_and_control_to_ssa(
    artifact: Any,
    control: ControlProgram,
    *,
    numerical_name: str = "numerical_precompile",
    control_name: str = "planned_control",
    region_programs: dict[int, Any] | None = None,
    hierarchy_plan: PlanClosure | None = None,
    identity_table: Mapping[str, tuple[int, ...]] | None = None,
    function_outputs: tuple[str, ...] = (),
    function_parameters: tuple[str, ...] = (),
    tensor_ssa_reference: Any = None,
) -> PrecompileSSALoweringResult:
    validation = validate_precompile_ssa_compatibility(artifact)
    program = getattr(artifact, "program", artifact)
    numerical, numerical_shortfalls = lower_fused_program_to_ssa(
        program,
        function_name=numerical_name,
    )
    used_ids = {
        value.id
        for value in numerical.args
        for _ in (0,)
    } | {
        instruction.res.id
        for block in numerical.blocks.values()
        for instruction in block.instrs
        if instruction.res is not None
    }
    # One authority for the authored kernel algorithms: when a tensor code
    # reference is supplied, its (cached) module IS the import -- a second
    # independent import would mint different Function identities and collide
    # at the tensor lowering's linker.
    if tensor_ssa_reference is not None:
        algorithm_functions = dict(tensor_ssa_reference.module.functions)
        algorithm_shortfalls: tuple[Any, ...] = ()
    else:
        algorithm_import = import_llvm_to_repository_ssa(LLVM_SSA_MODULE)
        algorithm_functions = dict(algorithm_import.module.functions)
        algorithm_shortfalls = tuple(algorithm_import.shortfalls)
    functions = dict(algorithm_functions)
    functions[numerical.name] = numerical
    region_callees: dict[int, str] = {}
    region_signatures: dict[
        int, tuple[tuple[int, ...], tuple[int, ...]]
    ] = {}
    region_feed_meta: dict[int, tuple[Meta, ...]] = {}
    region_value_meta: dict[int, Meta] = {}
    region_shortfalls: list[SSALoweringShortfall] = []
    # The control scope of this lowering, numbered by the book, so the
    # region signatures below and the builder's own rows share one scope.
    from .identity_concordance import current_identity_book as _fused_book

    _fused_label, _fused_serial = _fused_book().mint_scope(
        f"control:{control_name}"
    )
    fused_control_scope = f"{control_name}@control:{_fused_serial}"
    for region_index, region_artifact in sorted(
        (region_programs or {}).items()
    ):
        region_name = f"numerical_region_{int(region_index)}"
        region_program = getattr(
            region_artifact,
            "program",
            region_artifact,
        )
        region_function, shortfalls = lower_fused_program_to_ssa(
            region_program,
            function_name=region_name,
        )
        functions[region_name] = region_function
        region_callees[int(region_index)] = region_name
        region_signatures[int(region_index)] = (
            tuple(sorted(int(value_id) for value_id in region_program.feeds)),
            tuple(
                int(value_id)
                for value_id in region_program.outputs.values()
            ),
        )
        _post_region_signature(
            _fused_book(), fused_control_scope, None,
            int(region_index), region_signatures[int(region_index)],
        )
        region_feed_meta[int(region_index)] = tuple(
            region_program.meta[int(value_id)]
            for value_id in region_signatures[int(region_index)][0]
        )
        # A region states the dtype and shape of the values it consumes and
        # produces. The control program refers to those same value ids but
        # carries no metadata of its own, so without this the control
        # function's SSA values are shapeless -- which a target that must
        # declare every variable (Fortran) cannot express at all, and which
        # silently degrades an array to a scalar.
        for value_id, meta in (region_program.meta or {}).items():
            region_value_meta.setdefault(int(value_id), meta)
        region_shortfalls.extend(shortfalls)
    if hierarchy_plan is not None:
        expanded_plan_regions = expand_plan_regions(
            hierarchy_plan,
            first_free_value_id=max(used_ids, default=-1) + 1,
            function_scope=control_name,
        )
        for expanded in expanded_plan_regions.values():
            for instruction in expanded:
                used_ids.update(int(value.id) for value in instruction.args)
                if instruction.res is not None:
                    used_ids.add(int(instruction.res.id))
        for region in hierarchy_plan.items:
            if not (
                isinstance(region, PlanClosure)
                and region.name.startswith("region_")
            ):
                continue
            region_index = int(region.name.split("_", 1)[1])
            if region_index in region_callees:
                continue
            region_name = f"planned_region_{region_index}"
            instructions = copy_region_instructions(expanded_plan_regions[
                (str(region.name), int(region.closure_id))
            ])
            produced = {
                int(instruction.res.id)
                for instruction in instructions
                if instruction.res is not None
            }
            consumed = {
                int(argument.id)
                for instruction in instructions
                for argument in instruction.args
            }
            outputs = tuple(sorted(produced - consumed)) or tuple(sorted(produced))
            arguments = [SSAValue(int(value_id)) for value_id in region.captures]
            functions[region_name] = Function(
                region_name,
                arguments,
                {"entry": BasicBlock("entry", instructions)},
            )
            _post_built_function_rows(functions[region_name])
            region_callees[region_index] = region_name
            region_signatures[region_index] = (
                tuple(int(value_id) for value_id in region.captures),
                outputs,
            )
            _post_region_signature(
                _fused_book(), fused_control_scope, None,
                int(region_index), region_signatures[region_index],
            )
            shape_by_id = {
                int(value_id): Meta(tuple(map(int, shape)), str(dtype))
                for value_id, shape, dtype in region.value_shapes
            }
            region_feed_meta[region_index] = tuple(
                shape_by_id.get(int(value_id), Meta((), "unknown"))
                for value_id in region.captures
            )
            known_operations = {handler.value for handler in Handler}
            region_shortfalls.extend(
                SSALoweringShortfall(
                    "planned-region",
                    str(instruction.op),
                    f"{region_name}:entry",
                    "operator has no repository SSA handler",
                )
                for instruction in instructions
                if str(instruction.op) not in known_operations
            )
    if not region_callees:
        region_callees = {
            int(region_index): numerical.name
            for region_index in control.region_indices
        }
    control_function, control_shortfalls = lower_control_program_to_ssa(
        control,
        function_name=control_name,
        first_value_id=max(used_ids, default=-1) + 1,
        region_callees=region_callees,
        region_signatures=region_signatures,
        region_feed_meta=region_feed_meta,
        region_value_meta=region_value_meta,
        output_value_ids=(
            tuple(map(int, program.outputs.values()))
            if region_signatures and not function_outputs else ()
        ),
        named_output_histories={
            str(name): tuple(map(int, (identity_table or {}).get(name, ())))
            for name in function_outputs
        },
        value_name_histories=identity_table,
        parameter_names=function_parameters,
    )
    sequence_helpers, sequence_tables = _sequence_artifacts_from_control(
        control_function
    )
    functions[control_function.name] = control_function
    functions.update(sequence_helpers)
    from .ir_sequence_tables import lower_sequence_aggregate_constants

    lower_sequence_aggregate_constants(functions, sequence_tables)
    # Preserve shaped subscripts until tensor SSA has selected its repository
    # kernels. Scalar structural subscripts are addressed after that pass.
    module = IRModule(
        link_required_ssa_features(functions),
        recursion_table={
            name: dict(function.metadata.get("recursion_table", {}))
            for name, function in functions.items()
            if function.metadata.get("recursion_table")
        },
        sequence_tables=sequence_tables,
    )
    tensor_reference_shortfalls = ()
    if tensor_ssa_reference is not None:
        from .tensor_ssa_lowering import (
            legalize_aggregate_adapters,
            lower_tensor_calls_to_repository_ssa,
            propagate_repository_ssa_call_metadata,
        )

        tensor_reference_shortfalls = tuple(
            SSALoweringShortfall(
                "tensor-ssa-reference",
                item.operation,
                f"{item.function}:{item.block}",
                item.reason,
            )
            for item in lower_tensor_calls_to_repository_ssa(
                module, tensor_ssa_reference
            )
        )
    from .ir_indexing import lower_indexing_to_ssa_addressing

    lower_indexing_to_ssa_addressing(module.functions)
    if tensor_ssa_reference is not None and legalize_aggregate_adapters(module):
        propagate_repository_ssa_call_metadata(module)
    cycles = (
        *find_ssa_cycles(numerical),
        *find_ssa_cycles(control_function),
    )
    return PrecompileSSALoweringResult(
        module,
        validation,
        tuple((
            *numerical_shortfalls,
            *region_shortfalls,
            *control_shortfalls,
            *tensor_reference_shortfalls,
            *(
                SSALoweringShortfall(
                    "llvm",
                    item.opcode,
                    f"{item.function}:{item.block}",
                    item.reason,
                )
                for item in algorithm_shortfalls
            ),
        )),
        tuple(cycles),
    )


def ssa_module_dictionary(module: IRModule) -> dict[str, Any]:
    """Return the repository SSA module as a deterministic plain dictionary."""

    def value(entry: SSAValue | None):
        if entry is None:
            return None
        return {
            "id": int(entry.id),
            "dtype": entry.dtype,
            "shape": tuple(entry.shape),
            "device": entry.device,
            "accounting": dict(entry.accounting),
        }

    return {
        "recursion_table": {
            name: dict(regions)
            for name, regions in module.recursion_table.items()
        },
        "reference_tables": {
            name: [
                table.references[handle].to_mapping()
                for handle in sorted(table.references)
            ]
            for name, table in sorted(module.reference_tables.items())
        },
        "functions": {
            name: {
                "args": [value(argument) for argument in function.args],
                "blocks": {
                    block_name: {
                        "instructions": [
                            {
                                "op": instruction.op,
                                "args": [
                                    value(argument)
                                    for argument in instruction.args
                                ],
                                "result": value(instruction.res),
                                "arg_roles": tuple(
                                    instruction.arg_roles
                                ),
                                "attributes": dict(
                                    instruction.attributes
                                ),
                                "source_span": instruction.source_span,
                            }
                            for instruction in block.instrs
                        ],
                        "successors": tuple(block.successors),
                    }
                    for block_name, block in function.blocks.items()
                },
                "metadata": dict(function.metadata),
            }
            for name, function in module.functions.items()
        }
    }


def merge_repository_ssa_modules(
    primary: IRModule,
    *attachments: IRModule,
) -> IRModule:
    """Compose independently lowered repository SSA surfaces without loss.

    Numerical/control lowering and whole-object lowering are complementary:
    the former owns scheduled regions and imported algorithms, while the
    latter owns class definitions, physical record layouts, method bodies and
    call-frame status.  This merge keeps both in one module and rejects name
    collisions instead of choosing one representation implicitly.
    """

    from ..transmogrifier.ssa import (
        SSAClassTable,
        SSAMachineControlTable,
        SSAMachineIndirectTable,
    )

    modules = (primary, *attachments)

    def merge_named(attribute: str) -> dict[str, Any]:
        merged: dict[str, Any] = {}
        for module in modules:
            for name, value in dict(getattr(module, attribute, {}) or {}).items():
                existing = merged.get(str(name))
                if existing is not None and existing != value:
                    raise ValueError(
                        f"conflicting repository SSA {attribute} entry {name!r}"
                    )
                merged[str(name)] = value
        return merged

    classes: dict[str, SSAClassDefinition] = {}
    for module in modules:
        for definition in getattr(module.class_table, "classes", ()):
            existing = classes.get(definition.identity)
            if existing is not None and existing != definition:
                raise ValueError(
                    "conflicting repository SSA class definition "
                    f"{definition.identity!r}"
                )
            classes[definition.identity] = definition

    function_tables = tuple(
        module.function_table for module in modules if len(module.function_table)
    )
    if len({id(table) for table in function_tables}) > 1:
        raise ValueError("cannot merge independently owned SSA function tables")
    function_table = (
        function_tables[0] if function_tables else primary.function_table
    )
    from .ir_identities import PRECISION_PIPELINE_METADATA
    metadata = {"identity_book": primary.metadata.get("identity_book"),
                "ssa_composition_components": modules,
                "ssa_composition_function_books": {
                    name: (function.metadata.get("accepted_ssa_component") or {}).get(
                        "identity_book", (module.metadata or {}).get("identity_book"))
                    for module in modules for name, function in module.functions.items()
                    if (module.metadata or {}).get("identity_book") is not None}}
    # Backend-semantic module records cannot be dropped or arbitrarily chosen
    # from one enclosure. Equal declarations share a view; differing precision
    # or shell contracts require explicit reconciliation by their own producer.
    for key in (PRECISION_PIPELINE_METADATA, "shell_io"):
        declarations = [module.metadata[key] for module in modules if key in module.metadata]
        if declarations:
            if any(value != declarations[0] for value in declarations[1:]):
                raise ValueError(f"conflicting composed SSA module contract: {key}")
            metadata[key] = declarations[0]
    metadata["call_result_type_conflicts"] = tuple(
        conflict for module in modules for conflict in module.metadata.get("call_result_type_conflicts", ()))
    outlines = {}
    for module in modules:
        for name, outline in module.metadata.get("deployment_outlines", {}).items():
            if name in outlines and outlines[name] != outline:
                raise ValueError(f"conflicting composed deployment outline: {name}")
            outlines[name] = outline
    if outlines:
        metadata["deployment_outlines"] = outlines

    return IRModule(
        merge_named("functions"),
        # Independently lowered enclosures retain their original books. Their
        # policies/history cannot be attributed to the new module's empty
        # transaction. The audit follows these component owners explicitly.
        metadata=metadata,
        function_table=function_table,
        class_table=SSAClassTable(tuple(classes.values())),
        recursion_table=merge_named("recursion_table"),
        deployment_table=merge_named("deployment_table"),
        tensor_tables=merge_named("tensor_tables"),
        sequence_tables=merge_named("sequence_tables"),
        record_tables=merge_named("record_tables"),
        value_union_tables=merge_named("value_union_tables"),
        reference_tables=merge_named("reference_tables"),
        call_table=merge_named("call_table"),
        machine_control_table=SSAMachineControlTable(tuple(
            link
            for module in modules
            for link in module.machine_control_table.links
        )),
        machine_indirect_table=SSAMachineIndirectTable(tuple(
            link
            for module in modules
            for link in module.machine_indirect_table.links
        )),
    )


